INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Hoşgeldin Aşk', 'hey-hosgeldin-ask-sule-aydemir-1wuaa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hey kuşlar 

kıskanın  kanatsız daha yükseklerdeyim hepinizden

hey ağaçlar 

sevda yeşiliyim, yeşilim daha da fazla sizlerden 

hey akarsular 

daha hızlı akıyorum yetişemezsiniz çağlayanlar oldum ben

hey bulutlar 

övünmeyin hafifliğinizle daha yumuşak sizden yüreğim

hey örümcekler

dokuduğunuzdan daha güzel sevdadan gönül ağım 

bu delice bir denge ezgilerin arasında

hey aşk dervişleri 

kozaya sığmıyor bu yürek

yaşamadan ölmeyecek 

minnettar yaşama şükretmekte tadında ilmek ilmek 

başka bir bedende 

coşkusunda atıyor bu yürek', 'hey kuşlar  kıskanın  kanatsız daha yükseklerdeyim hepinizden hey ağaçlar  sevda yeşiliyim, yeşilim daha da fazla sizlerden  hey akarsular  ...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hey-hosgeldin-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Uyuyordun', 'sen-uyuyordun-ali-haydar-timisi-k7jnf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çığlıklar saplandı geceye

Derin uykulardan uyandılar

Uzun yollarda tay gibi

Soluk soluğaydılar

Günebakan türküler söylüyorlardı

Altlarında kilimler

El emeği göz nuru

Alın teriyle dokunmuş ilmekler

Haram lokma geçmemişti boğazlarından

Sofraları yerde 

     gönülleri darda

Derin uykulardan uyandılar 

                        kıl çadırlarda

Toprak gebeydi

Koynunda sızlayan sancısıyla yakıyordu ayakları

Sonra yılan, 

           çıyan, 

              börtü, 

                   böcek

Hiç konuşmuyorlardı o sabah

Güneş kan rengi doğuyordu

Kızıl aleviyle boyuyordu kenti

Ve ağaçlar

Binlerce yaprağıyla titriyorlardı

Rüzgar 

Kehribar peteklere bal taşır gibi

İhaneti, 

    yalanı 

        ve bütün rezilliğini ölümün 

Toprakta çürüyen ten gibi 

Ağır ağır dağıtıyordu semaya

Ve kuşlar

Korkunç bir depremden kaçarcasına 

Sarı, kurşuni kanatlarını çırparak 

En derin yeşili gibi kör bir kuyunun

Gökyüzünü kendi renklerine boyayarak

Göçüyorlardı kuzeye...

Sen uyuyordun...

 

Rüyanda en güzelinde cennet bahçelerinin

Ebedi bir huzura dalmışçasına 

Yanağında gülüşün

Zümrüt yapraklarıyla süslenmiş saçların

Ve baş ucunda meleklerin beklediği bir yatakta

Çırılçıplak, saf

        ve el değmemiş çiçekler gibi tertemizdin...

Bense gece vardiyalarında

Boş bir tren istasyonunda 

Emekli bir şimendiferin hüznü gözlerimde

Bedenimde dolaştığım şehirlerin yorgunluğu 

Ağır, aşınmış ve pas tutmuş yüreğimle

Üzerinde yol aldığım raylara hasret

Yanağıma vuran dallardan ayrı

Bir başıma ve alabildiğine yorgun

Gelen sabahı karşılıyordum 



Ayak sesleriyle aralanıyordu sabah

Yanakları ıslak, 

Makyajı akmış bir kadın

Ağlamış

Belli kırık kalplerle dolu valizi

Yürüyordu istasyonun soğuk yolunda

Dudaklarında yalan sevişmelerin izi

Gözlerinde hüzün bulutları 

Ve ardından koşup gelecek birini beklercesine 

Ya da “gitme” diyecek bir ses duymak için

Sessizce atıyordu adımlarını... 

Geceden yıldız yağıyordu sabaha

Sen uyuyordun...

Ilık bir Çukurova gecesinde 

İki yataklı bir otel odasında

Bambaşka bir kentin rüyalarına dalıyordun

Bense çok uzak bir ülkede hayal ediyordum aşkı

Prag’da

Bir son bahar yaprağı gibi düşüyordum sevdaya

Taş binaların koridorlarında uyuyordum

Vitava’nın iki yakası gibiydik

Sen Nove Mesto’da bir katedral

Ben Stare Mesto’da üçüncü sınıf bir otel odası

Ellerimi umudunla ısıtıyordum...

Hiç bir köprünün kaldıramayacağı hasretler

Nehirler boyunca ayırıyordu ikimizi

Kendi yüreğine küsmüş şehirler gibiydim

Karanlık yağmurlar altında

        gri duvarlara çiziyordum aşkı

Adım başı bir tanıdığa rastlıyordum

Ama hepsiyle küstüm

Sessiz merhabaları içime gömüyordum

Yüreğim yarım kalmış sevdalarla dolu 

Yüreğim şehir dışında kimsesizler mezarlığı

Ve sen bu derde düştün düşeli

Bütün dermanları bilsen bile 

Bulutlarda mavi bir bakışa sarılmış

Ateşler içinde günün güneşin

Çaren aynalarda ince bir gülüş

Öylece uyuyordun...

Ve ne kadar sızlıyorsa gülüşün

Bir o kadar yanıyordun...', 'Çığlıklar saplandı geceye Derin uykulardan uyandılar Uzun yollarda tay gibi Soluk soluğaydılar Günebakan türküler söylüyorlardı Altlarında k...', ARRAY['Türk Edebiyatı','Şiir','Ali Haydar Timisi']::text[], 8.5, '{"poet":"Ali Haydar Timisi","poet_slug":"ali-haydar-timisi","theme":"Türk Şiiri","is_hero":false,"total_lines":96,"source_url":"https://www.antoloji.com/sen-uyuyordun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terkediş', 'terkedis-ali-haydar-timisi-scvji', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öyle bir terk edeceğim ki İstanbul seni

Limanlarında vapurların ağlayacak

Martıların ıslak yataklarında sessiz

Köprülerin ardımdan el sallayacak

Ağlamaktan kör kuşlara döneceksin

Hüznünden sokakların tek tek yanacak

Öyle bir terk edeceğim ki İstanbul seni

Bütün saatlerin bir anda duracak

Gölgesiz bir adam gibi öyle tek başına

Yağmur seni boğmak istercesine yağacak

Boğazına düğümlenecek geçen gemiler

Yüreğin azmış nehirler gibi çağlayacak

Öyle bir terk edeceğim ki İstanbul seni

Çocukların sana her gün beni soracak

Kum gibi dağılacak yanan uykuların

Bacaklarında dermanın kalmayacak

Ve öyle bir  terk edeceğim ki İstanbul seni

Benim bile yüreğim yanacak...', 'Öyle bir terk edeceğim ki İstanbul seni Limanlarında vapurların ağlayacak Martıların ıslak yataklarında sessiz Köprülerin ardımdan el sallay...', ARRAY['Türk Edebiyatı','Şiir','Ali Haydar Timisi']::text[], 8.5, '{"poet":"Ali Haydar Timisi","poet_slug":"ali-haydar-timisi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/terkedis-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gün De Akşam Oldu...', 'bu-gun-de-aksam-oldu-ali-haydar-timisi-aobmd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gün de akşam oldu

Yorgun kanatlarında kuşların

Bu gözlerini görmediğim kaçıncı gün

Bilmem yüreğimde solan 

Kaçıncı mevsim...

Kimsenin haberi yok içimdeki talandan

Sustukça beynimde büyüyor hasretin

Sustukça içimde gemiler yanıyor

Ve dönüş ihtimallerinin boynu bükük

Karanlığa suretimi kazıyor gözlerin

Gece her çöküşünde omuzlarıma

İçimde bir şeyler soluyor

Çiçeklerin boynu bükük

Yıldızların hepsi yaralı

Ve hala aynı saatte ötüyor bahçedeki kuş

Ama 

Yoksun yanımda...

Bu yalnızlık bana fena koyuyor...

Bilmem şimdi ne yapıyorsun

Hangi yalanın peşinde düşlerin

Hala her ayrılık şarkısında ağlıyor musun? 

Yoksa sen de yüreğindeki ateşle

Yanıyor musun? 

Bu gün de akşam oldu

Yorgun uykularında İstanbul’un

Satıcılar çoktan topladılar tezgahlarını

Evin yolunu tuttu tüm sevdalar

Sen hala çarşaf gibi serilisin denizin üstüne

Hala bütün sokakları sen aydınlatıyorsun

Bu şehirde ne varsa senden kalan

Hepsi ağlıyor ardından

Yürüdüğüm yol

Isındığım güneş

Her şey seni anlatıyor...

Bütün meyhaneler seninle dolu

Dokunduğum her kadehte dudaklarımı yakıyorsun

Bütün kadınlar senin gözlerinle bakıyor

Bütün dilenciler seni dileniyor 

Oysa cebimde bozukluk da olsa

Bir kuruşluk mutluluğun yok

Bendeki sen bana yetmiyor

Ve bu yoksulluk bana ağır geliyor...

Kiliselerinde sana yalvarıyor insanlar

Yolların hepsi sana çıkıyor 

Kiminle konuşsam aklımda sen

Kiminle karşılaşsam seni soruyor

“İyi” diyorum 

“Selamı var...”

Evin içi sana getirdiğim selamlarla dolu

Yüreğimse hasretinle...

Bu hasretler bana ağır geliyor...

Bu gün de akşam oldu

Sevda bilmez oyunlarında çocukların

Bu sesini duymadığım kaçıncı gün

Bilmem kaçıncı ayrılık 

Tam söküp atmışken yüreğimden seni

Bir şarapnel gibi gelip gelip saplanışın niye

Defol git istemiyorum artık seni! 

Kokmuş bir yürekse derdin 

Söküp atacağım önüne bir gün

Yaralı sevdana saracaksın sonra cesedimi

Alıp yangınına götüreceksin

Bu ayrılık bana ağır geliyor...

Elini tuttuğum kimse sen değil

Koynuna girdiğim sevdalar yalan

Yalan söylüyorum bu şehrin tüm kadınlarına 

Hepsinin dudaklarında seni öpüyorum

Hepsinin saçlarında seni kokluyorum

Hepsine seni sevdiğimi söylüyorum

Ve bil ki benim gül yüzlüm

Bu yangınlar beni fena yakıyor

Kimse anlamıyor halimden

Sustukça beynimde büyüyor hasretin

Bunu bir tek sen anlarsın...

Bu sensizlik bana kahır geliyor

Bu gün de akşam oldu

Yorgun ağlarında balıkçıların

Her geçen gemi seni götürüyor

Uçan her kırlangıç sana göçüyor 

Sen beni yoruyorsun 

Ben şarkıları

Başımdan gitmiyor hasretin

Bu şarkılar beni fena tüketiyor

Bilmiyorsun...

Oysa ölüm olsa sen değil miydin “gelirim” diyen

Daha dün omzumda ağladığın yaşlar kurumadı

“Seni ölene kadar seveceğim” diyen kimdi? 

Bu yalanlar bana ağır geliyor

Görmüyorsun...

Oysa çaresizliklerin içinde değilim

Elimde altın anahtarı bütün hayallerin

Ve ben bile bile çekip gideceğini

Açıp girmiyorum o rezil kapılardan

Zehir zemberek geceler batsa da tenime

Seni sormuyorum anılardan

Çünkü sende biliyorsun gül yüzlüm biliyorsun

Bu iki yüzlülük bana ölüm geliyor

Bu gün de akşam oldu

Yanan bakışlarında ayrılığın

Bu kaçıncı düşen yaprak

Bahar bilmez dalımdan

Bu yitişler bana sağır geliyor

Beni en çok sen saklarsın 

Bir de yanan uykular biliyor

Söyle daha ne istiyorsun benden

Dört yanlışın bir doğruyu götürdüğü sınavlarda

Bir yanlışa kestik bu aşkın hükmünü

Artık ne yana gitsem çare ölüm

Kimi sevsem sen değilsin

Taşları kum eden rüzgar gibi

Al savur yüreğimi sevdanın çöllerine

Bu talanlar beni benden ediyor

Yüreğimin her yanı mayın

Kim yaklaşsa can veriyor

Ve her mezar bir ölümü aklarken

Benim yüreğimdeki cesetlerden

İğrenç kokular geliyor...

Gel artık üzerime ey sevgili! 

Gel artık topunla tüfeğinle

Terinle, 

      emeğinle, 

                 etinle! 

Gel de görelim hesabını bu aşkın

Ve bu meydanda kalsın yenileni

Bu üç kuruşluk sevdanın...

Bu savaşlar bana oyun geliyor!', 'Bu gün de akşam oldu Yorgun kanatlarında kuşların Bu gözlerini görmediğim kaçıncı gün Bilmem yüreğimde solan  Kaçıncı mevsim... Kimsenin hab...', ARRAY['Türk Edebiyatı','Şiir','Ali Haydar Timisi']::text[], 8.5, '{"poet":"Ali Haydar Timisi","poet_slug":"ali-haydar-timisi","theme":"Türk Şiiri","is_hero":false,"total_lines":126,"source_url":"https://www.antoloji.com/bu-gun-de-aksam-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Tanrının Sözü Var', 'bana-tanrinin-sozu-var-besim-bekler-hrdl6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana Tanrının Sözü Var

Doğduğunda çok mutlu olacağını söyledi, 

Acıların olmadığı yere gidiyorsun dedi.

Güzel günler bekliyor, sen mutlu olacaksın, 

Ben acı çekmeye gelmedim, bana Tanrı''nın sözü var.

Çocukluğumu çocuk gibi gençliğimi adam gibi, 

Yaşayacaksın mutluluğu sen de herkes gibi.

Doğduğuna sevinecek, şükredeceksin, 

Ben acı çekmeye gelmedim, bana Tanrı''nın sözü var.

Mutluluğu aramayacaksın o kendi gelecek, 

Biraz sabır biraz sukünet edersen dedi.

Sevecek biri çıkacak taparcasına karşıma, 

Ben onu bekliyorum, bana Tanrı''nın sözü var.', 'Bana Tanrının Sözü Var Doğduğunda çok mutlu olacağını söyledi,  Acıların olmadığı yere gidiyorsun dedi. Güzel günler bekliyor, sen mutlu ola...', ARRAY['Türk Edebiyatı','Şiir','Besim Bekler']::text[], 8.5, '{"poet":"Besim Bekler","poet_slug":"besim-bekler","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bana-tanrinin-sozu-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızım Benim', 'kizim-benim-besim-bekler-x5c03', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Balla sütle beslemek isterdim kızım seni 

Ama kazandığım para sadece ekmek almaya yetiyor.

Seni al yazmalı kadifelerle gezdirmek isterdim.

Kazandığım para yediklerime anca yetiyor.

Bu şiirimi sen uyurken sana bakarak yazdım.

Saçların dağınık üstünde abinin eşofmanı

Koynunda yıllar önce aldığım bebek 

Cüzdanımdan aldığın yirmibin lirayla uyuyordun kızım.

Karşımda taksidini geciktirdiğim renkli televizyonun

Bardağımda son duble rakım

Paketimde kalan son sigarayı yaktım.

Sen rüyanda güzel düşler kurarken kızım.

Kızma bana ne olur üzme beni

Zaten kahroluyorum sen bari anla beni

İstediğin veremeyeceğim sana, 

Eğer nefret edeceksen sen et haklısın kızım', 'Balla sütle beslemek isterdim kızım seni  Ama kazandığım para sadece ekmek almaya yetiyor. Seni al yazmalı kadifelerle gezdirmek isterdim. K...', ARRAY['Türk Edebiyatı','Şiir','Besim Bekler']::text[], 8.5, '{"poet":"Besim Bekler","poet_slug":"besim-bekler","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kizim-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Affetsin Ana', 'soyle-affetsin-ana-besim-bekler-i6ff7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne çabuk unuttum yaptıklarını, 

Beni ne zorluklarla büyüttüğünü ana.

Ben hayırsız ben günahkar sana karşı, 

Sen Tanrı nın yanındasın söylede affetsin ana.

Bilmeden kırdım kalbini biliyorum, 

Ne acılar çektirdim sana ana.

Biliyorsun tanıyorsun beni, ben kötü değilim, 

Sen Tanrı nın yanındasın söylede affetsin ana.

Dokuz ay karnındaydımbu yaşa kadarda yanında, 

Gözünden bile kıskanırdın nasıl unuttum ana, 

Göz yaşım aksa seninki sel oluyordu, 

Sen Tanrı nın yanındasın söylede affetsin ana.

Sen büyüttün sen evlendirdin beni

Bu mutluluğumun sebebi sensin ana.

Mezarına gelmedim bir inat uğruna, 

Sen Tanrı nın yanındasın söylede affetsin ana.

		Besim Bekler 01.06.2001', 'Ne çabuk unuttum yaptıklarını,  Beni ne zorluklarla büyüttüğünü ana. Ben hayırsız ben günahkar sana karşı,  Sen Tanrı nın yanındasın söylede...', ARRAY['Türk Edebiyatı','Şiir','Besim Bekler']::text[], 8.5, '{"poet":"Besim Bekler","poet_slug":"besim-bekler","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/soyle-affetsin-ana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nemrut Karıma', 'nemrut-karima-besim-bekler-9n806', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kelepçeler prangalar acıttı beni, 

Ama senin nefretin kadar değil

Bir sürü sopalar kırıldı üstümde, 

Ah etmedim, senin benden ah ettiğin gibi.

Çok nefret ettik birbirimizden, 

Taa ki buralara sebep oldu gelmemiz.

Sen hastanede, ben ceza evlerinde

Evimizde yatsaydık daha iyi olmaz mıydı sevgilim.

Ben alkole, sen diline sahip olamadın.

Ne olur biraz hoşgörseydik birbirimizi.

Ama sende bu katır, inadı bende bu içki, 

Olduğu sürece hep aynı yerde olacağız değil mi.

Çıkarsak artık son olsun emi, 

Sen dilini aza, bende rakıyı otuzbeşliğe indireyim, 

Ufacık nedenlerden belki kavga etmeyiz, 

Zaten hayatımız iptal olmuş, nasıl isterse öyle gitsin.

		  Besim Bekler 29.04.2001', 'Kelepçeler prangalar acıttı beni,  Ama senin nefretin kadar değil Bir sürü sopalar kırıldı üstümde,  Ah etmedim, senin benden ah ettiğin gib...', ARRAY['Türk Edebiyatı','Şiir','Besim Bekler']::text[], 8.5, '{"poet":"Besim Bekler","poet_slug":"besim-bekler","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/nemrut-karima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennete doğru...', 'cennete-dogru-omay-tezcan-uoafe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'köprünün ortasında durup, seyredaldım

demirleri...

köprünün demirlerini, suya bakmadan, 

alttan akan suya...

demir paslanmıştı benim gibi, su ise akıyordu

dışarısı gibi...

ondan haşırneşir oldum demirle, 

bana benzediği için....

köprüyü yürümeye başladım

en kenarına adımlarımı sıkıştırdım, 

korksaydım düşmemek için düşerdim, 

ama ben değildim sanki yürüyen...

sıratta olsaydım girmiştim cennete...

adımlarımı hızlandırdım ve koşmaya başladım, 

cennet vardı ucunda nasıl koşmayım...

cehennemin dibinde olması gereken ben, 

cenneti geçiriyordum aklımdan...

gülmeye başladım sonra

hem koştum hem güldüm...

hem güldüm hem koştum...', 'köprünün ortasında durup, seyredaldım demirleri... köprünün demirlerini, suya bakmadan,  alttan akan suya... demir paslanmıştı benim gibi, s...', ARRAY['Türk Edebiyatı','Şiir','Omay Tezcan']::text[], 8.5, '{"poet":"Omay Tezcan","poet_slug":"omay-tezcan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cennete-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Bir Sese Doğru', 'kayip-bir-sese-dogru-cem-ozkok-0ul51', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kararsızlıkla başlıyorum. Her ikisini de ilan ederek... Yani bir karar verme zorunluluğunu ve bir başlangıcı. Birdenbire boşluk beliriyor. İlk duraksayan cümlede beliren, görünür kılınan boşluk. Zorunluluk ise, diyorum şimdi iyice yüreklenerek, bu boşluk karşısında duyurulur. Varolana ilişkin okuduğum, duyduğum, söylediğim her söz gibi bende düş kırıklığı yaratmıştı.

        Başlangıçta söz vardı. Ve beden söz oldu. Hatırlarsınız. Bir yerlerde okumuşsunuzdur. Sanırım, İsa’nın havarileri arasında en sevdiği olduğu söylenen Yuhanna söylemişti bunu. Ya da yazmıştı.

        Öğle sonrası saatleri... Gün, çoktan yoluna koyulmuş, uzaklaşmış bile. Kendi berrak sesinin izinde. Bense burada, saydamlaşan seslerin ve saatlerin ortasında duruyorum. Bu cümleleri yazmak için. Gün diye yazıyorum, giderek yüreklenerek bir dünya barındırıyor içinde. Uzak ve görünür bir dünya, tek parça granitten oyulmuş gibi. Ancak yanlış bir soruyla bir adım atabilir, bunca ışığa ve sese yetişebilirim belki. Bu düşkırıklığı, dünyaya yaşıt gibi duran bu düşkırıklığı ne zaman başladı? 

        Neden şimdi hatırlamaya çalışıyorum? Unutmuş muydum ki? Kaybettiğimiz bir yer, bir söz, bir ses. Gaipten gelen sesler... Belki biz kaybettik onu, belki kendiliğinden kayboldu.

        Kayıp bir ses... Saatlerin ve seslerin, saydam kılıçlarla çarpıştığı bir savaş alanı mı bedenim? Boşluğa karşı duran kemik, tenle başlayan acı. Belki de bazı seslerin çıkarılabilmesi için dilin çarpmak zorunda kaldığı bir diş gibi. Her şey varolabilmek için hedefi tam ortasından vurmak zorunda, diye yazmış biri, kendi cümlelerinden derin bir düşkırıklığı duyarak, on ikiyi ıskalayan hiçbir şey varolamıyor. Benim için söz konusu olan varoluş, eğer bir isabetse, dilin kemiğe çarptığı ana benziyordu sanırım. Bu acıya...

        Boş, beyaz kağıtlar ve bu kağıtlara girmek için varolduğu söylenen dünya. Hiç kimsenin okumaması için kumlara yazılan sözcükler. Olması söylenen ve olan ışık. Beyazın kabullenişi kendisine dokunanı, ama boşluğun, üzerindeki her türlü insani size karşın boşluk olarak kalacağına dair sarsılmaz inancı.

         Neden? Kayıp olanla kurulan bir ilişki mi bu? Kendimizi orada bulacağımızı zannettiğimiz için mi? Ben miyim kaybolan? Kayıp olanda mı rastlayacağım kendime? Yeniden mi? Hatırlayacak mıyım? Unuttum mu? 

         Bütün bu kopuk kopuk cümlelerin beni öne çıkaran ya da yarıya doğru iten seslerin, başlangıçların, yol ayrımlarının, sert granitin içindeki adımların ortasında duruyorum. Hayatın ortasında yaşarkalmış darmadağınık. Benim bedenim bir iz yalnızca, her yara gibi çoğu zaman sessiz, ama konuştuğunda ürkütücü bir sesle konuşan ve yalan söylemeyi beceremeyen. Yanınıza gelmek için bırakıp kaçtığım ölüm gibi.

         Başlangıçta söz vardı? Kimin sözü? Söz beni kaybettiğim kendine iade edebilir mi? Ve söz beden oldu. Yoksa yazı mı? Yazı sözün beden kazanması mı? Gaipten gelen seslere verilen bir biçim. Bir beden. Bir ürperme.

         Kim söyler? Kim yazar? Kim duyar? 

         Yazıyorum, o kadar. Sesimin beni getirdiği yerde duruyor, sizler için karanlığı terk etmiş sözcüklerimin ardından bakıyorum. Belki ben de izini sürdüğüm bu ses kadar boşum. Belki ancak şimdi sessizliğin sorularına katlanabilirim. Belki benim yalnızlığım sizin yalnızlığınızı tanıyor. Yazdıklarımla yalnızım.

      

        

           07.12.2003/ÇİĞLİ', 'Kararsızlıkla başlıyorum. Her ikisini de ilan ederek... Yani bir karar verme zorunluluğunu ve bir başlangıcı. Birdenbire boşluk beliriyor. İ...', ARRAY['Türk Edebiyatı','Şiir','Cem Özkök']::text[], 8.5, '{"poet":"Cem Özkök","poet_slug":"cem-ozkok","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kayip-bir-sese-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sultanım Ol', 'sultanim-ol-alaettin-isik-y9onq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gülen gözlerinin içinden gelen; 

Dostluğun en büyük armağan bana.

Sevgiyle, saygıyla gerçek aşkı, 

Bilerek yaşatan aşkımsın bana.

Bin türlü çiçekten toplanmış sözün, 

Bal olmuş derde dermandır özün.

Bir köprü   sanki her iki gözün, 

Cennete giden yol olur bana.

Sevmek ne güzel, yaşatır bu doğayı, 

Sevginin kudreti ki indirir gökten ayı, 

İstersen gör yaşarken bu rüyayı, 

Hayra yor, olsun gülüşün derman bana.

Sevildiğini bil, sevenini tanı, 

Olma sakın başkasının hayranı, 

Aşkın sarhoş eder inan ki cihanı, 

Ele kul değil,  gel ol sultan bana..', 'Gülen gözlerinin içinden gelen;  Dostluğun en büyük armağan bana. Sevgiyle, saygıyla gerçek aşkı,  Bilerek yaşatan aşkımsın bana. Bin türlü ...', ARRAY['Türk Edebiyatı','Şiir','Alaettin Işık']::text[], 8.5, '{"poet":"Alaettin Işık","poet_slug":"alaettin-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sultanim-ol-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dip', 'dip-cem-ozkok-qvthq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'üst sularda yüzen 

renkli bir balıkken

diplerde

ama 

çok diplerde

renksiz bir balık (dip hayat)

olmayı seçtim.

ama unutma, 

unutma ki:

renksiz balıklar yaşayamaz üstlerde

ve yine unutma ki:

renksiz balıklar vardır (yaşar)

diplerde

çok diplerde

senden uzak

ama

senin dibinde

içinde...

   

       Denizin dibinde, ama çok dibinde, ışığın sızmadığı yerde renksiz balıklar yaşar. Işık yoktur ama hayat yine de sürer. Denizin büyük ve karmaşık hayatı o dipten başlar. O küçük balıkları tutup yukarı çıkarana kadar ölürler belki. Ama orada, hayatı başlatan bir ‘dip hayat’ vardır. İki kişinin arasında akan “ilişki” adlı nehirde de böyle bir dip vardır. Orada, suyun dışından bakan üçüncü kişilerin göremeyeceği, iki kişinin de tutup yukarı çıkarıp birbirine veya başkalarına gösteremeyeceği balıklar birikir. Derinliklerde, ışığın sızamayacağı kadar dipte, kolay adlandırılamayacak balıklar, anlamlar, iletiler ve sözcüksüz sırlar yüzer. Toplulukların birbiriyle ilişkileri de iki insanın ilişkilerine benziyorsa eğer... insan ilişkisi değil mi nihayetinde? Kırgınlıklar, intikamlar, yaralar, buluşmalar, hatırlamalar, kesişmeler, coşkular, yeminler, düğümlenen, düğümlendikçe ağırlaşan suskunluklar... 

                    21 Haziran 2002/İzmir', 'üst sularda yüzen  renkli bir balıkken diplerde ama  çok diplerde renksiz bir balık (dip hayat) olmayı seçtim. ama unutma,  unutma ki: renks...', ARRAY['Türk Edebiyatı','Şiir','Cem Özkök']::text[], 8.5, '{"poet":"Cem Özkök","poet_slug":"cem-ozkok","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dip-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç', 'hic-cem-ozkok-4ytov', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç’in perküşa ruhuna komşu düşmedim henüz... Lakin ‘mutlu yarin’ kisveli siyaset anlayişi sürdükçe, bunun uzak bir ihtimal olmadigini bilirim pekala... Zira kalmadi bir anlami, ‘siradan günlük yaşamin’... ‘Anlamli başarisizlik’larin... ‘Kutsal çilginliklar’in... ‘Onurlu yalnizlik’larin... Içimde peykan! ‘Saglikli normaller’e ragmen şeyleştirmemeye çalışıyorum taşlaşmış öfkemi... Gündelik şeylere yetmeyen aklim ve ‘tarihin tüylerini tersine firçalamaya’ alişmiş bellegimle... Kabul etmem gerek ki, siyasal bir ürün’üm; eninde sonunda, ürüyor ve seçiyorum-yanliş bir hayatin dogru yaşanamayacagini bile bile... Kendini aramak ve araştirmak: Ah ne yaman açilim! Nerede o yorumcu, beni tanimlayacak... Anlatılabilir ve anlaşilabilir kilacak... 

         Biliyorum; Hiç’i tanımadan kendisi için varlık olamamakta insan. Ne zaman ki ‘kendi Hiç’imi kendi içimde taşımayı’ öğrenirim, işte o zaman özgün ve özgür yaşam için göreceli bir adim atmiş olurum. (Sahi olur muyum?)

          Bir süredir böyle... İmgesel birmekandayım sanki... Ya cümbüş var ya da maskeli balo. Bir kaç Pierrot... Gerisi sabun köpüğü... Yüzsüz bile olamayan bir güruh. Güruh-ı eşkiya... Orkestra durmaksızın çalıyor... Handel’i... Saul Orataryosu’nu... Kimseyi tanımıyorum. Uçuşuyor havada, yırtıcı kuşlar gibi, ‘olağanüstü insanların mutsuzlukları’... Çığlık çığlığa tanrılar... Tanrıların oğulları... Torunları... Kimseyi tanımıyorum. Öyle ya ‘tanımak için bilge olmak gerek’ (Xenophanes) ... Susuyorum... Hüzünlü değil, gerekli bir susuş bu... (En çok sustuğu yerden kanayan ben için zor bşr durum)   Cennette kopmuş bir fırtına... Öylesine güçlü... Sırtımı döndüğüm geleceğe doğru sürüklüyor beni, önümdeki yıkıntı ise göğe doğru yükselmekte... İşte ilerleme... İşte fırtına...

          Yokuşun tepesindeyim bu firtina sonrasi... “Yeşil pancurlu büyüük, beyaaz bir ev. Renksiz ve boyasiz ahşap barakalarin üstünde, köylüsüyle beraber yaşayan ortaçag asilzadelerinin şatolarini andiracak derecede ihtişamli bir şey! (...)   Bir tarafta ben, diger tarafta yanliz camileri camileri ve büyük binalari gözüken Istanbul: Sulardan ufuklara fişkiran bir maketler ve abideler şehri, dalgali beyaz! Bir tarafta ben, diger tarafta çamlar arasindan renk renk çikan köşk çiçekleriyle, kirmizi toprakli oda yamaçlari: Hayalleri sularda titreşen beyaz benekli, nefti kivrimlar yapan koylar! Önünde bulutlarin beyaz izlerini gayet hafifçe çalkalandiran uçuk mavi deniz. Ötesinde ben ve sari topraklar. Kiyilara öbek öbek dagitilmiş yazlik köşkler ile uzak ve tenha ova mesafeleri. (şu an içinde yaşadigim)   Ve sonra sirada, sira sira siradaglar ve ben... Nihayetinde Levent; bulutlarin aksiyle parça parça koyulaşmiş toprak şişkinligi! ...

           Dar ve uzun bir odadayım. Burada ne varsa son derece lüzumlu olduğu için konmuş: Mesela misafir, yere bağdaş kurmayacağı için, duvar kenarına üç dört sandalye dizivermişler. Kitaplar, tahtalara serili duramaz diye abonoz renkli gayet basit ve uzun raflar koyuvermişler.

           Derken Fazıl Ahmet (Aykaç)   beliriveriyor. Arkasında gümüşi pardesüsü, başında fesi. Rafların önündeki sandalyeye, ellerini  ovuştura ovuştura büzülüyor. Nezleden pürtükleşmiş sesiyle Ruşen Eşref’in hatırını soruyor. “Yüzü zayıf, uzun... kulakları iri, ayrık kaşları ince...” Bir kasılıyorum bir gevşiyorum. Alnımda maşallah irisi ter(ler) ... Damlıyor, bozuk musluk gibi; şıp şıp...

            Ruşen Eşref soruyor: “Eski edebiyat hakkindaki fikriniz? ”

            Handel sözü viyolaya veriyor. Dünyasal, bedensel, tensel hazlar telkin halinde. Uykuyla uyanıklık arasındayım.

            “Eskiler, sarayda padişahla bayramlaşma merasimine gider gibi, yazi yazarlardi, ” diyor Fazil Ahmet, “Üsluplarinin kiligi kiyafeti bir takim terimlerle dolu cümlelerden kaftanlar, agir ve anlaşilmaz kelimelerden meydana gelme süslerle bezensin! Tanzimattan sonraki dil inkilabimizda frakin istanbulin şekline, binişin de sako haline -pardesü degil ama, dikkat ediyor musunuz, sako haline konmasi tarzinda bir fark var.”

            Ortalık şenleniyor. Namık Kemal ve Abdülhak Hamit, Şevket (Dağ)   Bey’den pastel bir ‘eskiz’in asılı olduğu duvara sırtlarını dayamış, Ruşen Eşref’i dinlemekteler. Biraz huysuzlar sanki...

            “Namık Kemal’le Abdülhak Hamit Bey, edebiyatımıza bu yeni elbiseleri biçen ikimakastardır.”

            Neler oluyor? Bu bulut, bu taşkin da neyin nesi? 

            “Gerçi, eskisi gibi, kahveye çıkmak için kürk ve samur giyilmiyordu. Fakat bu sefer de üslupların günlük elbisesi smokin oldu. Uydurma ve yapmacık, şurdan burdan çalınmış, kıymetsiz fikirlerin bu yeni tuvaletler Edebiyat-ı Cedide devrinin birçok yazısına tuhaf bir eda veriyor. Arzedebiliyor muyum? ”

             Kuşku mu var? 

             “Benden bahsederken rahmetli Tevfik Fikret’le Halit Ziya beyefendiyi de hatırımdan bir türlü çıkaramıyorum. Bu iki üstattan birincisinin rübabı bugün bize,  paslanmaya başlamış tel sesi veriyor. İkinci de çok düzgünlü birihtiyar çehresi var.”

              Paltosundan ‘en ala’ sigara çıkarıyor. Dumanların arasından konuşuyor: “Şimdiye kadar ve hala biz ‘servile’ bir şekilde, bir esir, bir ücretle çalışan kimse halinde kalmışız. Acem Edebiyatı’na karşı da öyle, Fransız Edebiyatı’na karşı da öyle...”

              Bir ses... “Nerdesin? ” diyen... Teneffüs zili misali öten... Uğultu... Ya da inilti...

              Fazıl Ahmet, sağ avucunun içine sol yumruğunu vuruyor, işitilir işitilmez bir yavaşlıkla, “Halide Hanım’ın kitapları, lezzetli fakat kılçığı bol sardalye gibi.” Diyor. “Çok ve bol yazan nesirci Süleyman Nafiz Bey’in üslubunu ise Mısırçarşısı’na benzetirim: Bin bir korku, bin bir renk, efendim.”

              Handel nihayet susuyor. ‘Olağanüstü isanların mutsuzlukları’ geri çekiliyor, yırtıcı kuşlar gibi... Fırtına diniyor... (Zaten hiç olmamıştı ki! ...)   Gülüyorum...  Bir süredir böyle... ‘Sonluluk içinde sonsuzluk, tamamlanmışlık içinde tamamlanmamışlık’... Eşref havası mı? Soysuz yabancılaşma mı? Uyuyorum uyanıklığımda... Biri “Ders kitaplarını bedeva yapacağım! ” diyor. Esniyorum. Tarihin küçük dili titriyor. İşte diyorum, ‘her ilmin macunundan bir parça ç(alınmış)   sohbet yazısı’ bu olmasa gerek...” Evet! Evet! Evet! 

(Derkenar: Hasan Fehmi’den sonra öldürülen ikinci gazeteci Ahmet Samim’dir. Hilal Gazetesi’nin yazarı olan Samim,9 Haziran 1910’da Bahçekapı’da saldırıya uğrar. Kendisi ölürken, yanında ki arkadaşı kurtulur..Kurtulan arkadaşı Fazıl Ahmet’tir. O fazıl ki Kulüp Rakısı’nda (kendisi şarapçıdır aslında)   fotoğrafı vardır ve genellikle benle karıştırılır.

10 Ekim 2002/Akhisar 

(doğum günüm)', 'Hiç’in perküşa ruhuna komşu düşmedim henüz... Lakin ‘mutlu yarin’ kisveli siyaset anlayişi sürdükçe, bunun uzak bir ihtimal olmadigini bilir...', ARRAY['Türk Edebiyatı','Şiir','Cem Özkök']::text[], 8.5, '{"poet":"Cem Özkök","poet_slug":"cem-ozkok","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hic-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağıt', 'agit-aziz-bulut-337lv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'karda yansıyan 

düşler için, 

düşen her yağmur damlasına

ağıt yaksamda; 

içimde 

ne kadar sen

ne kadar başkası

ve ne kadar

b

e

n 

kalır..', 'karda yansıyan  düşler için,  düşen her yağmur damlasına ağıt yaksamda;  içimde  ne kadar sen ne kadar başkası ve ne kadar b e n  kalır.....', ARRAY['Türk Edebiyatı','Şiir','Azız Bulut']::text[], 8.5, '{"poet":"Azız Bulut","poet_slug":"aziz-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/agit-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Gül Saati', 'gecenin-gul-saati-aziz-ahmet-bulut-27sjh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'benimdi, 

gecenin gül saatinde

büyüyen eller

uzayan kollar.

beynimdi, 

beni rededen

ayrı bedenimden

karşımda

bana gülen.

-o sarıda ölen çocuktu-

ben ise

gecenin gül saatinde

hala sendim...', 'benimdi,  gecenin gül saatinde büyüyen eller uzayan kollar. beynimdi,  beni rededen ayrı bedenimden karşımda bana gülen. -o sarıda ölen çocu...', ARRAY['Türk Edebiyatı','Şiir','Aziz Ahmet Bulut']::text[], 8.5, '{"poet":"Aziz Ahmet Bulut","poet_slug":"aziz-ahmet-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gecenin-gul-saati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip', 'garip-hasan-ali-gurleyen-p7bhd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sokakta bir insan

Üstü başı perişan

Feleğin darbesini yemiş

Yıkık bir insan

Kimbilir nasıldı

Nasıl bu hale geldi

Hayatını yaşarken 

Nasılbir darbe yedi

Diye sakın düşünme

Bilki o insan benim

Aşkından bu haldeyim

Benim canım sevdiğim...', 'Sokakta bir insan Üstü başı perişan Feleğin darbesini yemiş Yıkık bir insan Kimbilir nasıldı Nasıl bu hale geldi Hayatını yaşarken  Nasılbir...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ali Gürleyen']::text[], 8.5, '{"poet":"Hasan Ali Gürleyen","poet_slug":"hasan-ali-gurleyen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/garip-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hem Deli Hem Sevdalı', 'hem-deli-hem-sevdali-aziz-ahmet-bulut-nyfo9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'asılsın.

yağmura sevdalı

bir deli o.

yüreği gerilsin

bir ucu ay ışığına, 

diğeri

peygamberler ateşine.

sonrada

ışığa gömülsün.

hem deli

hem sevdalı.', 'asılsın. yağmura sevdalı bir deli o. yüreği gerilsin bir ucu ay ışığına,  diğeri peygamberler ateşine. sonrada ışığa gömülsün. hem deli hem ...', ARRAY['Türk Edebiyatı','Şiir','Aziz Ahmet Bulut']::text[], 8.5, '{"poet":"Aziz Ahmet Bulut","poet_slug":"aziz-ahmet-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hem-deli-hem-sevdali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni yalnız yâr diye mi..', 'seni-yalniz-y-r-diye-mi-mahir-ozel-i1e2y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben seni yalnız yâr diye mi sevdim

Öyle miydi

Gördüğün hissettiğin bende

Bütünleyenim

Tamamlayanımsın

Bir de saranımsın yaralarımı

Sarmalayanım

Ben seni

Doruklarındayken dağdağamın

Ve titriyorken her yanım sevdim

Bıkmışken yaşamdan

Esirgenmişken duyumsamalardan

Ben seni yâr diye sevdim

Yarısı değil miydin yüreğimin

Ve diğer yarısı beynimin/tamamı düşüncelerimin

Ve değil miydin soluduğum bahar

Ve değil miydin düşlerimdeki yâr

Sen değil miydin

Ve ben seni yalnız yâr diye mi sevdim

İçten içe bir duyuş

Hissediş

Ve masum bir yakarıştı bu

Sen gel de

Baharla

Gel de yazla gel

Gel de dolu dolu binbir hazla gel

Dilersen yormadan

Yüzbin nazla gel

Yeter ki gel

Yaşama ait ne varsa getir

Getir de öylesi beni de bitir

Yeter ki gel

Haydi

Gel durma

Durma ey yâr gel

Seni

Ben yalnız yâr diye mi sevdim

Seni sevdim

Hayatı sevdim

Ve birde yaşamayı sevdim seninle

Kopmadım dünden

Bu günlerden

Kopmadım yarınlardan

Ben seni yalnız yâr diye mi sevdim

Yarınımı da sevdim

Ötesini de

Sen dallarının çiçeğe vurduğu baharda girdin de gönlüme/Yaz ettin güzümü

Ve

Haldeşim

Yoldaşım

Arkadaşım

Gönüldaşım değil miydin

Seni

Ben yalnız yâr diye mi sevdim

Kavak yellerini ayaklandırdın da yeniden gönülde

Ben süphanım dağ dağ/sen dumanım tütsü tütsü

Dermanı başımın/yorganı kışımın

üşümelerimin örtüsü

Sen tenimin sıcaklığı ılık ılık

yaşamadım ki seninle ayrılık

Buğusu sabahımın

Aydınlığı karanlığımın

Şebnemi güllerimin

Özlemi gözlerimin

Kuvveti kollarımın/mesnedi sözlerimin

Sabahı mavi düşlerimin

Dudaklar da gonca / gülüşlerimin

Anlayamadın mı bir tanem

Ben seni yalnız yar diye mi sevdim

Yâr diye mi

Yâr..

 mahirane - Ankara 21-06-2003, 21:22', 'Ben seni yalnız yâr diye mi sevdim Öyle miydi Gördüğün hissettiğin bende Bütünleyenim Tamamlayanımsın Bir de saranımsın yaralarımı Sarmalaya...', ARRAY['Türk Edebiyatı','Şiir','Mahir Özel']::text[], 8.5, '{"poet":"Mahir Özel","poet_slug":"mahir-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/seni-yalniz-yar-diye-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Yazdım', 'adini-yazdim-turgay-kadiroglu-cxevl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '...Aydınlat sönmüş lambanın ışığı, 

Kalbimi ıslatan hüzün rengi ırmağı...

Karanlık ve ıslak, aşkı tattığım şehir, 

Menekşe kadar sen kokuyor

Adını yazdığım bu şiir.

Giderken ellerime tutuşturduğun aşk, 

Yüreğimde üşüyor.

Tutuşan ellerime sen yüklü şiirler düşüyor

Ve içinde kaybolduğum karanlık üşüyor.

Güneşsiz bir odam vardı; sen yoktun, 

Dört duvara yaslanan bir adam vardı; sen yoktun, 

Secde vakti dualarım vardı ve içinde sen vardın, 

Üzeri titreyen bir toprak vardı ve içinde ben vardım.', '...Aydınlat sönmüş lambanın ışığı,  Kalbimi ıslatan hüzün rengi ırmağı... Karanlık ve ıslak, aşkı tattığım şehir,  Menekşe kadar sen kokuyor...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/adini-yazdim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum Dostlar', 'gidiyorum-dostlar-fatma-ful-ozok-7wekp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gidiyorum dostlar

Yolum çok uzun...

Bense yolun başında

Hayat yorgunuyum...', 'Gidiyorum dostlar Yolum çok uzun... Bense yolun başında Hayat yorgunuyum......', ARRAY['Türk Edebiyatı','Şiir','Fatma Ful Özok']::text[], 8.5, '{"poet":"Fatma Ful Özok","poet_slug":"fatma-ful-ozok","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gidiyorum-dostlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynalardan Baktım Yıllara', 'aynalardan-baktim-yillara-derin-oger-yitmz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerin hatıra diye

Bakışlarınla

Çok sürüklendim ben

Tedirginliğin denizlerinde

Soğuk akıntılarla

Zaman acıydı liman yoktu

Kayalar altında kaldım

Yengeç sürüleriyle

Dindi tufanın

Çekildi dalgaların

Günler azar azar götürdü dertleri

Sisler içinde

İçimde bir şeyler göçse de

Sızısı kalmış yüreğimin dibinde

Aynalara baktım 

Acılar yakışmış gözlerime

Ve yıllar yakışmış yüzüme.......', 'Gözlerin hatıra diye Bakışlarınla Çok sürüklendim ben Tedirginliğin denizlerinde Soğuk akıntılarla Zaman acıydı liman yoktu Kayalar altında ...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aynalardan-baktim-yillara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sevda ki', 'bir-sevda-ki-hikmet-karakus-3wk1q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eriyorum için için, 

Söyleniyorum acı acı, 

Dil yine de ürkek, 

Adımlıyorum yalnızlığımı

Öfkeyi boğmak için.

Bir sevda ki 

             zulme nışanlı, 

Bunca acı yetmez sanki

                  hasreti dert

                      kendi nazlı.

(İst.1980)', 'Eriyorum için için,  Söyleniyorum acı acı,  Dil yine de ürkek,  Adımlıyorum yalnızlığımı Öfkeyi boğmak için. Bir sevda ki               zulm...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-sevda-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-hikmet-karakus-tbbf1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgi Yunus gibi

Sevgi  Kerem gibi, 

Sevgi ekmek su gibi, 

Sevgi memleket gibi, 

Sevgi gül gibi, 

Sevgi sen ben gibi, 

Sevgi murat, 

Sevgi can gibidir.

(İst.1980)', 'Sevgi Yunus gibi Sevgi  Kerem gibi,  Sevgi ekmek su gibi,  Sevgi memleket gibi,  Sevgi gül gibi,  Sevgi sen ben gibi,  Sevgi murat,  Sevgi c...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevgi-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Sen Gidiyorsun', 'sen-gidiyorsun-derin-oger-8mx8a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Başkalarına göz oluyorsun

Başkalarına dudak

Elimden alıyorsun o en tatlı hayali

Dehşetler yüklüyorsun omuzlarıma

Yakamozlar kayboluyor denizden 

Gel gitlerin koynunda

Gözlerimin ürkekliğine bırakıyorsun 

Tanrının verdiği o en güzel armağanı

Sen gidiyorsun

Başkalarına göz oluyorsun 

Başkalarına dudak.....', 'Başkalarına göz oluyorsun Başkalarına dudak Elimden alıyorsun o en tatlı hayali Dehşetler yüklüyorsun omuzlarıma Yakamozlar kayboluyor deniz...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-gidiyorsun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki ölüm', 'i-ki-olum-hikmet-karakus-7jfvc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biri uzandı

      sessizce düştü ölüme, 

Biri destan

      erkekçe düştü yüreğime.

(İst.1975)', 'Biri uzandı       sessizce düştü ölüme,  Biri destan       erkekçe düştü yüreğime. (İst.1975)...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/iki-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Seyirlik Uyanış', 'bir-seyirlik-uyanis-hikmet-karakus-94oki', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biri ağlıyor

  gecenin sessizliğinde

                           bir şarkı, 

Ve Afrika''da uyanışın

     vahşi güzelliğinde

               dinleniyor Nil

                        sabaha karşı.

(İst.1981)', 'Biri ağlıyor   gecenin sessizliğinde                            bir şarkı,  Ve Afrika''da uyanışın      vahşi güzelliğinde                din...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-seyirlik-uyanis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdeyim Ben', 'nerdeyim-ben-atila-gunal-8r4av', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sahi aklıma geldi de birden

Ben senin nerendeyim? 

24-06-2003', 'Sahi aklıma geldi de birden Ben senin nerendeyim?  24-06-2003...', ARRAY['Türk Edebiyatı','Şiir','Atila Günal']::text[], 8.5, '{"poet":"Atila Günal","poet_slug":"atila-gunal","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/nerdeyim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alfabesiz Ayin', 'alfabesiz-ayin-yasar-aslan-xtdxl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çayın demini yeni kırdım

kokusunu içime sindirmemle başlar

alfabesiz bir dilin, tarifsiz  ayini 

yavaş adımlarla çıkardığım sigara

kibrit çakışımla başlar kendimi yakma', 'Çayın demini yeni kırdım kokusunu içime sindirmemle başlar alfabesiz bir dilin, tarifsiz  ayini  yavaş adımlarla çıkardığım sigara kibrit ça...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Aslan']::text[], 8.5, '{"poet":"Yaşar Aslan","poet_slug":"yasar-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/alfabesiz-ayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hançer', 'hancer-tekin-gonenc-znyb1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yine mi sen

kimliğime küskün gecelerimde

döne dolana pusular kuran

rüya kılıklı uçarı kız

elinde o hoyrat hançer

denizlerimin kıyısında işin ne

dilim dilim maviler yontup

yine hangi uzaklara

(Varlık Dergisi, Mart,2003)', 'yine mi sen kimliğime küskün gecelerimde döne dolana pusular kuran rüya kılıklı uçarı kız elinde o hoyrat hançer denizlerimin kıyısında işin...', ARRAY['Türk Edebiyatı','Şiir','Tekin Gönenç']::text[], 8.5, '{"poet":"Tekin Gönenç","poet_slug":"tekin-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hancer-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denize Olan Uzaklığımsın', 'denize-olan-uzakligimsin-fatih-pasali-mkdht', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-kılıçla kın gibi bir ilişki

 kedinin tırnaklarıyla arasındaki yakınlık yani-

yine kaçış

yine korku

yine kopuk parmaklar avuçlarımda

bir infaz bekliyorum belki de

böylece kayıplığımdan kurtulmak

yokluğunun yerine kurşun taşıyorum

acıtsın uyuşan taraflarımı

ama

kanım akmaz 

kurağım 

denize olan uzaklığımsın

		

Bir kadın teni geziniyor düşümde

düşler avuntu gülüşlerden kalan

gülüşler dudaklarımın kavuşmayan ucu

iki yakasını tutuyorum ömrümün

bir araya gelmiyor

(birleşmeyen yanımsın)', '-kılıçla kın gibi bir ilişki  kedinin tırnaklarıyla arasındaki yakınlık yani- yine kaçış yine korku yine kopuk parmaklar avuçlarımda bir inf...', ARRAY['Türk Edebiyatı','Şiir','Fatih Paşalı']::text[], 8.5, '{"poet":"Fatih Paşalı","poet_slug":"fatih-pasali","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/denize-olan-uzakligimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Kör Bir Bıçakla Değiştir Duygularını', 'simdi-kor-bir-bicakla-degistir-duygularini-fatih-pasali-5vi5n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yeni tenleri yalnızlığa ekle

kuşat kendini

ayraçları belirteçlemede etkin olsa da 

sevgilinin sonbahar yaprağını andıran hüznü

aşklar ayrılıklar olduğu sürece vardır

Çatlayan tenini güneşe sermiştin hani

şiire sığınan bi''yanın vardı

yağmur öncesi kumun dağınıklığı yani

kurağını yeşerttiğimiz gecenin

iflah olmaz yağmursuzluğuydun

Çeliğe verilen su yumuşatmaz özlemi

dudaklarımda esrik bir öpüşmenin

jilet izleri varsa da

ayraçlardan damıttığımdır 

sonraya kalan / sonrası; 

içimde uluyan

sırlar duldasında

Şimdi kör bir bıçakla değiştir duygularını.', 'Yeni tenleri yalnızlığa ekle kuşat kendini ayraçları belirteçlemede etkin olsa da  sevgilinin sonbahar yaprağını andıran hüznü aşklar ayrılı...', ARRAY['Türk Edebiyatı','Şiir','Fatih Paşalı']::text[], 8.5, '{"poet":"Fatih Paşalı","poet_slug":"fatih-pasali","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/simdi-kor-bir-bicakla-degistir-duygularini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devamlı Peşimizde Olan Bir Tecavüzcüdür Zaman', 'devamli-pesimizde-olan-bir-tecavuzcudur-zaman-fatih-pasali-bxhir', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kavga gelir

kan eskir

soyunup kendi kayıplığımdan

arayamam seni

hayat hala gaspetmekte ruhumu

ve şimdi

ırzıma geçiyor zaman

alfabesiz bir sohbete

ve

imlasız sevişmelere özlemim

ama hayat

yüreğimin kırık raflarına sıraladığım

yasaklanmış

en eski kavga romanının içinden

Türk Dil Kurumu edası ile çıkıyor karşıma

kavgam kendimle

hayata yasal bağlanamayığışımdan

içimde darağaçları taşımam

toprağın altınla üstünü ayraçlayan

bir zaman tünelidir yaşamak yalnızca geçilir

ve

güne tutulur hesabı

boş içki şişeleri gibidir artık hayat

yalnızca

birbirine çarpınca ses çıkartır

yaşama direnişimiz 

temyiz edilemez

geometri kadar kolay çözülemez

bir hayatın

yüzümüzde bıraktığı

derin çizgiler..! 

biraz da kaderdir yaşamak

ve...

zaman daha hızlı ırzımıza geçiyor şimdi.', 'kavga gelir kan eskir soyunup kendi kayıplığımdan arayamam seni hayat hala gaspetmekte ruhumu ve şimdi ırzıma geçiyor zaman alfabesiz bir so...', ARRAY['Türk Edebiyatı','Şiir','Fatih Paşalı']::text[], 8.5, '{"poet":"Fatih Paşalı","poet_slug":"fatih-pasali","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/devamli-pesimizde-olan-bir-tecavuzcudur-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kor Metalleri Bileyen Keskin Bakışlar', 'kor-metalleri-bileyen-keskin-bakislar-fatih-pasali-aaeo2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1.				       Asmin''e

gün yine geç kaldı

küflendi gece

her dakikası isyandı

ve

en acı kaybımdı 

yüzünüz

irinli bir yarayı deştim saatlerce

kaktüsüne sığmayan dikenlerin sayısını

bedenimdeki çiziklerden tuttum

şafak çizgisine astım umutlarımı

ve bir nefret ürettim kendime

kanayan yerlerime sardım bu nefreti

sızıları unutulmasın

2.

ilkel adamın ilk haykırışı

kelimesiz ilk çığlığıydı

yalnızlık

karalar denizleri emer oldu

ıslaklıklar çamur

bir şelalenin suyunu sindirmek istiyorum

içimde saklı kalsın asiliği

işte göz yaşlarımda açıyor tomurcuk

ve

rüzgar soluyorum günlerdir

3.

gülüşleri toplayıp giti küflü bir karanlık

''damarlarımızda hissettik aşkı ve inkarı''

bir düşünüşün yayılabileceği kadar

yayıldık sevdaya

sevdamızdan saptık yollara

ve akıştık koyaklara

yazıyı buluşumuzdandır bu sevincimiz

şiir ki

yaramıza basılan bir tütündür artık

kanayışlarımızı durduran

4.

gökyüzüne düşüyoruz 

ateşi ve suyu ayraçlamadan

işte bununla mutluyuz

oklar göğsümüzde paslanıyor

ve 

bekledikçe küfleniyor gece

şarjörler boşalıyor yüreğimize

ölmemekte inatçı ve isyancıyız

kurşun bir hiçtir kimi zaman

yürekteki kor eritir metali

damıtır sevdamıza azar azar

ki kimi zaman

demirde kuvvettir

dirayet katar aşklara ve ayraçlara

5.

bir umut kadar uzaksın artık

bir gidiş kadar zamansız

tenin kokuşlu çiçekler soluyor ve kurutuyorum / 

küflü geceye

yüreğime batan dikenlerin eylemi

çöl sessizliğinde gizli kalsın

6.

firarlarımı sığdıramadım kervanlar

sezilerimi gömüyor şimdi

kumlar utanır ve ıslanır oldu

yüzümün deltasında kayıp giden

erozyon bakışlarından

çöle dahi sığmaz artık

bu aşkın otopsisi

kronik suçlarımdan firar edemem

varsın

kaçışımın idam mangalarına hedef olsun

yatamadığım tüm hapisler/

tenimi çizen bakışların 

hükümdür artık bana

7.

tenha bir aşk

asvalt kadar yoğun düşünceler

çöl olmak geçiyor içimden

ve kuru bir yağmur kadar

anlaşılmaz hüznüm

kurşunluyor kendini

8.

işte çöl de küflendi

ve ben

bir gecenin sesinde susmak istiyorum şimdi.', '1.				       Asmin''e gün yine geç kaldı küflendi gece her dakikası isyandı ve en acı kaybımdı  yüzünüz irinli bir yarayı deştim saatlerce ka...', ARRAY['Türk Edebiyatı','Şiir','Fatih Paşalı']::text[], 8.5, '{"poet":"Fatih Paşalı","poet_slug":"fatih-pasali","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/kor-metalleri-bileyen-keskin-bakislar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tersi tersine', 'tersi-tersine-mehmet-ali-kepez-astum', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mahkum oldu savcıları

Suçlu kalem  kırar oldu

Bizim köyùn avcıları

Dağda balık avlar oldu

Sarayda  gezer katırlar

Tıp ı solladı  yatırlar

Yatağa  dùştù doktorlar

Hasta yara  sarar  oldu

Kızıl bayrak oldu sarı

Atlar kopardı yuları

Bitlı sokak bocuları

Aslanlara  havlar oldu

Er oldu paşa erine

El yanar maşa yerine

isciler alın terine

Simdi  çelme  atar oldu

Sarhoş gezer mumin hoca

Ateist gidiyor  haca

Bu asırda karı koca

Birbirini  satar oldu

sazlar küstü  ozanında

okur kaçtı yazarında

yeni  Dünya dùzeninde

ters yaşamak  kural oldu

Cana  düştù  korucular

Sinek besler arıcılar

Yalı  tùkenen bocular

Kanlı  çete  kurar oldu

kimse  durmuyor sözünde

At izi itin izinde

Hezan polissin gözünde

Elde çör çöp arar oldu

Dedeler çılgın torunda

Mubaşir hakim yerinde

Mahpushane dıyarında

Gardiyanlar  yatar oldu

Yolcular yolunda sapmış

Kasaplar  cerrahlık yapmış

Dùnyanin çivisi kopmuş

Kàr dediğin zarar oldu

Gùzel suratlar buruşuk

Emek sermaye karışık

Velhasıl karma karışık

Kurt kuzuya yarar oldu

Dùnya mi ters ben mi tersim

Ben mi yanlış  aldım  dersim

Kendimde  çikaram hırsım

Gùn  doğu da  batar oldu

Kepez  den  selam herkese

Kimseler  bir  şey  demese

Tavuklar  girmez kùmese

Tilkilere  çatar oldu', 'Mahkum oldu savcıları Suçlu kalem  kırar oldu Bizim köyùn avcıları Dağda balık avlar oldu Sarayda  gezer katırlar Tıp ı solladı  yatırlar Ya...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/tersi-tersine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harman Zamanı Düşkırıklıkları ve Su Yangınları', 'harman-zamani-duskirikliklari-ve-su-yanginlari-namik-kuyumcu-1qxr0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gözlerimde taşıdığımçıplak resimlerin utancı

kirpiklerimin kavuşmasına nasıl da gebeydi

hiç unutmam

çok erken öğrendim leyleğin hikayesini

hemen kovuldum

babaannemle gittiğim kadınlar hamamından

muskalı eşiklerden geçtim

eşiklerin sağ ayakla aşıldığı evlerden

nazara karşı dökülürken öğrendim kurşunu

cinayetler işledim oyuncak satan dükkanlarda

sapantaşım cebimdeydi

esas oğlanların esas kadınlara varmasıyla

biten romanları yazdım ve oynadım yeniden

boşuna aradım yaşanmış gerçek aşkları

sonu hep mutlulukla biten romanlarda

kendimi tutamadığım yerlerde

kendi kulaklarımı çekerek

kitap sayfalarına hınzırca girip

en gizli sevdalara çöpçatanlık yaptım

kiminde çivi ile çekiç oldum

kiminde yağmur ile toprak

darbelerle anıldı adım

çığlıklarla düştüm ormana

ceylanlar/eşkıya hüznüyle bağışlandı

büyüdüm ve rüzgara yürüyorum

uzaklarda asmin çağrısı

tedirginlik/incelmiş kayalar üstünde

ölüm celladıyla şakalaşıyor

ve sanki herşey kendisini eskiten bir şaka

sen ve senfonisi bütün gidişlerin

şakaklarda biriken yanlışların ağrısı

raylarına yabancılaşmış trenler/ve düdük sesleri

ki en çok uykuları bölendir

en çok yolculukları anımsatır

yanlış haritaların cinnet geçiren dağları

düşen çığlıklarla derinliğinden utanan uçurumlar

bir halk ve ölüm

göç yollarını değiştiren kuş sürüleri

yalnızlık ki/en çok şairlerle anılır

sanki her şey kendisini eskiten bir şaka

her şey kendisini eskiten bir şaka mı

su''ya düşen buz mu eskir su mu çoğalır

yaşadığımız kaç doğruyu kaç yanlışımız götürür

kendimi nasıl ihbar edebilirim

sağır kentlerin sahte seslerine/söyleyin

sevmekten suçlu olduğum belli değil mi

(yine şaka olsun diye/hiç girilmemeiş mağaraları

düşünüyorum/hiç çıkılmamış dağları/aklıma bakire

kadınlar geliyor/bakir delikanlılar/

bütün dağları aşk için yıkıyorum/taşıyor mağaralar) 

buğulu camlara

ters soruişaretleri çiziyorum/anlayın beni

sesim rüzgarlara da sığmıyor

izimi bulun ve bitirin bu oyunu

oyuncaklarımı da kırın

sevmekten suçlu olduğum belli değil mi

delillerimi

fena halde susamış günlerin gülüşlerinde biriktirdim

su testisiyim inkar etmiyorum

bir kez daha kırabilirsiniz beni

su için

su için

su için

gözyaşları için/su için', 'gözlerimde taşıdığımçıplak resimlerin utancı kirpiklerimin kavuşmasına nasıl da gebeydi hiç unutmam çok erken öğrendim leyleğin hikayesini h...', ARRAY['Türk Edebiyatı','Şiir','Namık Kuyumcu']::text[], 8.5, '{"poet":"Namık Kuyumcu","poet_slug":"namik-kuyumcu","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/harman-zamani-duskirikliklari-ve-su-yanginlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Yalnızlık ve Devrim Bir Buluşmadır', 'ask-yalnizlik-ve-devrim-bir-bulusmadir-namik-kuyumcu-9073w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğini kör kirpi yollarına yatırmış insan

kırılır gök yüzünün kafesi inadınla

mavi yeni bir buluşmadır / sevişgendir saklanan

çağrı çiçeği açar kendisini kaçıran kızın ayıp yerlerinde

arınsın diye beden adaklar adanmış 

ve yaşamak bağışlanmıştır

tütsü kurşun ve tuz buhurlanır

yalnız ve bundan suçludur insan

okunmuş sular saçılır saçlardan tırnaklara

kem göz ve kötü söze karşı / devrim

bir buluşmadır 

aşka yazılıdır / yıldızları kucaklayıp geceyle vedalaşanlar

toprak ağaçlarla seviştiği için nemfomandır

sunulan aldanış

ahlakta saklanan yalan

kara trenleriyle gurbete çağresiz bakışlarını bağlayan insan

atını eğerle yollara düş

han yerinde hançerind uyu 

geceye borçlan

tuz ve su sığmaz olur bir gün denize

taş devrindeki maden ve çiğ şiir çığlığın belki anlaşılmaz

o zaman

kül kehlibar ve başak bir başka bekliyordur

şikayetsiz ve mühürsüz geçersin

çığlığını kör çeşmelere asarak

bunu bil sevişmeyi kokla

kendinle yüzleş

yanlışından arın

zamanın kiriyle yıkanmış kavmin varsın eksilsin

insan yaşadıkça eskir

ve kendi yanlışını emzirir

batık gemilerin günahı alınır

tuzlu su ve balık kılçıklarından

ayrılığın aş kaldığı yerde kemiklerim sızı

sancıyan ruhumla bir yalnızlığım iliklerimde

yağmur değmesede hiç yüzüme

sulara küsmem yürürüm

günahı geceye ayarlı sokaklarda

suç tinerle kucaklaşır

maznumdur çocuklar

unutulduğumuz her bakış

kırgınca gök yüzüne çekilirken / biraz intihar

dokunduğumuz her bekleyiş

yaramızın tuzlu dudaklarında / 

ürkek ve vahşi bir buluşmadır

avuçlarımda jiletlenmiş soru işaretleri

aşk için zar tuttum itiraf ediyorum

gözlerimde son sevişmeden kalan ağrı

sadece dağ ismi olsaydı ezberimde

yürürdüm katran küllerin karasına posta koyarak

geçerdim gülüşünüzden

teninizden

sonra kendimden

şehirlerim mühürlenmiş

şiirler kırmızı mürekkep ve leke

pazarcılar kül satıyor

kan izleri ve göz yaşları için

çürüten tekrarlara kör kapılar

dokunmayışlara küskün yosunlu pencreler gördüm

yüreği buz kesmiş şehvetli ateş gövdeleri

süsledim bakire yaşlıkların sandıklarında saklanan

ipek hançer ve amber kokan incilerle

geceden düşen yıldızlı tuzaklar ve aşk

hangi ay gözlere bağışlandı bilmek isterdim

gölgesini bile kendisine düşman gören insan

gülleri koklamadan solduran zaman taciri yerine 

kısa çöpü bilerek çekenlerden kaçınca

kırdım yüreğimi hiç beklemediği yerden

kimseye borçum kalmasın istedim

öğrenilmiş yerleşik korkularda sulanıyordu

aşkın aykırı yollarında kendine küs çiçekleri

herkes bir düş edinip belki delice

önce kendi uçurumuna düşmeli

hepimizin aşkı beynimiz ve yüreğimiz kadardır

bıçaktan hep alacaklı durur ayrılığın arısı.', 'Yüreğini kör kirpi yollarına yatırmış insan kırılır gök yüzünün kafesi inadınla mavi yeni bir buluşmadır / sevişgendir saklanan çağrı çiçeği...', ARRAY['Türk Edebiyatı','Şiir','Namık Kuyumcu']::text[], 8.5, '{"poet":"Namık Kuyumcu","poet_slug":"namik-kuyumcu","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/ask-yalnizlik-ve-devrim-bir-bulusmadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilim Varmıyor', 'dilim-varmiyor-ertugrul-adem-karisan-rthvf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hasretin vuruyor gözlerime

Gözlerim gözlerini özlüyor              

Düşlerim ümitlerim seninle

Elveda demeye dilim varmıyor

Hazan olur bu şarkılar sensiz

Güller yetim bülbüller kimsesiz

Giderken arkandan sessiz sessiz

Elveda demeye dilim varmıyor

Hasretine hasreti eklerken

Geleceksin diye hep beklerken

Seninle bir ömrü düşlerken

Elveda demeye dilim varmıyor

Aşkınla alev alev yanmadan

Yağmur olup gönlüne yağmadan		

Seninle bir günü paylaşmadan

Elveda demeye dilim varmıyor', 'Hasretin vuruyor gözlerime Gözlerim gözlerini özlüyor               Düşlerim ümitlerim seninle Elveda demeye dilim varmıyor Hazan olur bu şa...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Adem Karışan']::text[], 8.5, '{"poet":"Ertuğrul Adem Karışan","poet_slug":"ertugrul-adem-karisan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dilim-varmiyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua', 'beddua-ozcan-ozkan-gvua3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şerefsiz ellerinle 

Şerefe kaldırdığın

Kadehlerin içinde

Zehir zıkkım olayım

                                         

                 (1971)', 'Şerefsiz ellerinle  Şerefe kaldırdığın Kadehlerin içinde Zehir zıkkım olayım                                                            (197...', ARRAY['Türk Edebiyatı','Şiir','Özcan Özkan']::text[], 8.5, '{"poet":"Özcan Özkan","poet_slug":"ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/beddua-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Antepli Şahin', 'antepli-sahin-yavuz-bulent-bakiler-72gfn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben Antepliyim, Şahin''im ağam. 

Mavzer omzuma yük. 

Ben yumruklarımla dövüşeceğim. 

Yumruklarım memleket kadar büyük. 

Hey, hey! 

Yine de hey hey! 

Kaytan bıyıklarım, delişmen çağım 

Düşman kurşunlarına inat köprü başında 

Memleket türküleri çağıracağım. 

Bu dağlarda biz yaşarız, bu dağlar bizim dağımız. 

Namusumuz temiz, bayrağımız hür 

Analarımız, karımız, kızımız, kısrağımız 

Burda erkekçe döğüşür 

Bir bayrak dalgalanır Antep kalesi üstünde 

Alı kanımdaki al, akı alnımdaki ak 

Bayraklar içinde en güzel bayrak 

Düşüncem senden yanadır 

Hep senden yanadır çektiğim kahır 

Bu senin ülkende, senin gölgende 

Düşmesin kara kalpaklar, kirlenmesin duvaklar 

Korkum yok ölümden kâfirden yana 

Alacaksa alsın beni şafaklar. 

Hey, hey! 

Yine de ey hey! 

Al bayraklar altında kara bir kartal gibi 

Yaşamak ne güzel şey. 

Bir sır var bu mavzerde, attığım gitmez boşa 

Çıkmış bir eski savaştan 

Türk''ün bir karış toprak parçası için 

Destanlar yazacağız yeni baştan. 

Yıktım toprağın üstüne bir sarı kurşunla birini 

Çıktı karşıma biri, 

Çıktıkça çektim tetiği bismillâhlarla beraber 

Vurdum alnından kâfiri. 

Bu kaçıncı kurşundur, bu kaçıncı bismillâh 

Bu kaçıncı ölüdür? 

Bir türkü söylenir siperlerde her sabah 

Vurun Antepliler namus günüdür! 

Ben Antepliyim Şahin''im ağam 

Mavzer omzuma yük 

Ben yumruklarımla dövüşeceğim 

Yumruklarım memleket kadar büyük', 'Ben Antepliyim, Şahin''im ağam.  Mavzer omzuma yük.  Ben yumruklarımla dövüşeceğim.  Yumruklarım memleket kadar büyük.  Hey, hey!  Yine de he...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bülent Bakiler']::text[], 8.5, '{"poet":"Yavuz Bülent Bakiler","poet_slug":"yavuz-bulent-bakiler","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/antepli-sahin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amasra', 'amasra-arzu-dincer-99hg9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tanrı yeryüzüne dokunmuş, 

Yalçın dağlardan aşağıya, 

Turkuaz suya doğru...

Beyaz danteller süslemiş denizi, 

Dalgaların, kayaları öptüğü yerde..

Kemere köprüsü, 

Seyirlik bir şenlik alanı, 

Martılar dalıyor maviye..

Martılar kanatlarında gün ışığı...

Karadeniz, hırçın kız! 

Bu ne işve, bu ne öfke söyle! 

Güzelliğini sunmaktan kaçınmayan, 

Ama kimseye yar olmayan....

Gözün gördüğü...

Cennetin yansıması...', 'Tanrı yeryüzüne dokunmuş,  Yalçın dağlardan aşağıya,  Turkuaz suya doğru... Beyaz danteller süslemiş denizi,  Dalgaların, kayaları öptüğü ye...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/amasra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pusuya yatmış cesaret', 'pusuya-yatmis-cesaret-arzu-dincer-ptfmb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şinanay ateşi cevahirinde yanan, 

Korku söndürmüş alazını...

Ha cesaret! 

Körük, senin kendinde..

Bak nasıl canlandıracaksın, 

Düşüncelerin ateşini......', 'Şinanay ateşi cevahirinde yanan,  Korku söndürmüş alazını... Ha cesaret!  Körük, senin kendinde.. Bak nasıl canlandıracaksın,  Düşüncelerin ...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/pusuya-yatmis-cesaret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şahinden Düşünceler', 'sahinden-dusunceler-sule-aydemir-h1xhw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yaşananlara defter tutarız bazen

nedense yapışır kalırız anılara

ve bir mutluluk gelir 

koca çalı süpürgesi süpürür geçer gider

sonrası hüsransa yaşanmışlığın eğer 

bir hazan rüzgarıdır hepsini geri alır gelir

yenilere eklenir çoğalır boğar

cam parçalarından kırık sevgilerim vardı benim

ve hileli gülümsemeler kaçak dövüşte sevdalar

kim dürüst kim sahtekar bilinmeden 

yığıntılar üst üste gelmiş yıllar

birleşmeden akıp geçtiler gözlerimden onca zaman

beklenmeyecekleri bekledim kaçırmamak diye diye

en büyük sandıklara saklı küf tutmuş çeyizlerdi hayallerim

bir genç kız işledi umutlarımı resimli goblenlere

hoyratça güveler yedi gecenin en karanlık köşelerinde

siyah bir çöp torbasına çoktan sıkıştırılmış bir gençliğim 

yaşanmamış heyecanlarım ve keşifte renklerim vardı

örtüm üstlerini hepsinin güvercinin siyah zeytinden çığlıklarıyla

ellerim uzandı mutluluğa inanmadım anlık sevinçlerdi isimleri

bir ahududu idi huzur hiç bahçemde yetişmedi

sesimi de verdim gitti rüzgarlara sustum güneşçe ayca

isyan zamanıdır şimdi açıldı yeni günlük seyir defteri

uyanış hınzırca çalınmış yaşanmamış zamanlara

asla asla demeden pişmanlığa yolun ucu bile gözükmeden

keşkelere boğup da duyguları mutsuz içgüveyi vermeden

bencil bir şahinin uyanışı şimdi hırçınlığında boğulmadan çığlıkları

görüp millerce öteyi  hayatın ciğerini sökmeli pençeleri

kan revan olmadan damak tadında yıllanmış tecrübe 

kırmızı değil inadına beyaz şarapla 

aheste aheste yaşam savaş ki

ekşi bir zaferdir dedikleri 

sindirmeli

yenmeli

yemeli', 'yaşananlara defter tutarız bazen nedense yapışır kalırız anılara ve bir mutluluk gelir  koca çalı süpürgesi süpürür geçer gider sonrası hüsr...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sahinden-dusunceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Pişmanlık', 'son-pismanlik-i-brahim-bayraktar-n0608', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her sabah erkenden kalkıp ayağa, 

Servis yolu beklemek, huy oldu artık, 

Giyinip, kuşanıp çıkmak sokağa, 

Vazgeçilmez bir yol oldu artık. 

Kravat boynumdan hiç eksik olmaz, 

Aldığım paralar cüzdanda durmaz, 

Bağırsam, sitem etsem sesim duyulmaz, 

Asil devlet memuru kul oldu artık.

Arkadaştan borç alıp hayatını sürdürmek, 

Alış verişlerini taksitlere böldürmek, 

Sağa, sola koşuşturup vakit öldürmek, 

Devlet memurluğunda bol oldu artık.

Kimi; selam vermez mağrurlanır, 

Kimi; mazisine bakar gururlanır, 

Kimi, yakın arkadaşından huylanır, 

Devlet Memurluğu pul oldu artık.

Çocuklar defter ister, hanım elbise, 

Dağları devirsen de yetmez nefise, 

Memurluk giyilmesi zor bir elbise, 

Şimdi meçhule giden yol oldu artık. 

Bu kervan yürüsün, devran durmasın, 

Sen, Devlet hazinesine akan kurnasın, 

Arkadaş söylenme sende aynı yoldasın, 

Devlet memurluğu zül oldu artık.', 'Her sabah erkenden kalkıp ayağa,  Servis yolu beklemek, huy oldu artık,  Giyinip, kuşanıp çıkmak sokağa,  Vazgeçilmez bir yol oldu artık.  K...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/son-pismanlik-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin uyuduğu şehir', 'gecenin-uyudugu-sehir-ensar-cevval-zi2be', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Garbın bir köşesi hep aydınlıkmış

haziranın bir gününde

öyle anlatmıştı; votkanın sertliğini

yüzüne kan damarları ile çizen yaşlı satıcı

cebindeki şişeden kopabildiği dünde.

Bir gün öncesinden başlarmış tüm hikaye

Gündüz, kör gecenin bastonunu alınca elinden

gece, gündüzün tarifiyle geçermiş özünden.

gece, zamanı sordukça gündüze

yıldızları saydırtırmış gündüz, âma dilenciye

O gün dünya dönmüş yine kendi çapında

güneş, dünyaya özenmiş dönmüş etrafında

Çiçek, perdelerini açmış gönül evinin

tohum, camını açmış penceresinin

ve iniltisi yayılmış yarasanın, kör mağarada.. 

St.Petersburgmuş anlattıkları  şehir

içindeki yaşamın aynası, sert yüzlü nehir

kızıl suratlı yaşam, votka şişesinde esir

Leningrad diye bilinen o toprak parçası

değişmezdi adı, toprak olmasaydı babası.', 'Garbın bir köşesi hep aydınlıkmış haziranın bir gününde öyle anlatmıştı; votkanın sertliğini yüzüne kan damarları ile çizen yaşlı satıcı ceb...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gecenin-uyudugu-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Şiirim...', 'siirim-naime-erlacin-ogrrf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'biter mi şiir

bu serüven 

bu hüzün

mekân: küçük bir oda

masa başında göçülür başka bir dünyaya 

kimsesizliğe bürünür yalnızlık

gölgem olur

başlar sonsuz yürüyüş 

sonraki bir rüyaya

ey şiirim! 

beynim 

bedenim 

düşüncemde tutuşan

eriten beni ateşli sularda

bitmesin serüven

bitmesin bu hüzün

çünkü biliyorum artık 

her şiir 

bir Leylâ’dır Mecnun’un koynunda

(24 Haziran 2003)', 'biter mi şiir bu serüven  bu hüzün mekân: küçük bir oda masa başında göçülür başka bir dünyaya  kimsesizliğe bürünür yalnızlık gölgem olur b...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/siirim-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hükümetçiler', 'hukumetciler-murat-demir-jz6k8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vatandaş kemik alıyor

Kasaptan hükümetçiler

Et yerine, yok keyfinden

Hesaptan hükümetçiler

Tüccar bildiğini yapar

Bu gidişle dertler artar

Ya vur öldür yada kurtar

Azaptan hükümetçiler

Vara yoğa sarılmayın

Ona buna darılmayın

Millet derki ayrılmayın

İnsaftan hükümetçiler

Yaşanılıyor etsizce

Hiç olurmu milletsizce

Kaçınalım gereksizce

Masraftan hükümetçiler

Bilinki ben vatandaşım

Kalmadı hiç arkadaşım

Kaynamıyor artık aşım

Kazanda hükümetçiler', 'Vatandaş kemik alıyor Kasaptan hükümetçiler Et yerine, yok keyfinden Hesaptan hükümetçiler Tüccar bildiğini yapar Bu gidişle dertler artar Y...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hukumetciler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Para', 'para-murat-demir-4b7bp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sağda solda dolaşmanı

İster her an savaşmanı

İnsanlığın baş düşmanı

Paradır para, yürekte yara

En yakın dost gibi düşman

Anlar isen olma pişman

Kötülükle el sıkışan

Paradır para, yürekte yara

Canlar alır sanık olmaz

Her yerde var tanık olmaz

Garibana konuk olmaz

Paradır para, yürekte yara

Hem ağlatan hem güldüren

Yokluğuyla kul öldüren

Ocak değil can söndüren

Paradır para, yürekte yara', 'Sağda solda dolaşmanı İster her an savaşmanı İnsanlığın baş düşmanı Paradır para, yürekte yara En yakın dost gibi düşman Anlar isen olma piş...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/para-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben''den İçeru', 'ben-den-i-ceru-naime-erlacin-wba93', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'öz ben’im 

öz benliğim

dışımda bile içimdesin

belli ki iç dünyam 

öz benliğimdir benim

beni 

ben yapan tohum

ekmeğim 

hamurum

sürüncemeli düşlerim

duygum 

düşüncelerim

buluşmalıyım özümle

yoksa biterim

uçuyordum ya durmaksızın

sanmayın gittim bir yerlere

özlemim örtüşmekti içimle

dedim:

“saçımın her teli dünya benim”

yanıldım! 

gençtim

oysa içimdeydi dünya

fark edemedim

dedi:

“bir ben var, bende ben’den içeru”

dedim:

“ne ben’ler var

bende ben’den de içeru...”

iç yolculuklarım

ah ne zorluydunuz siz! 

uykum açıldı 

kucakladım dünyayı

dünya oldum

öz benliğimden doğdum yeniden

(24 Haziran 2003)', 'öz ben’im  öz benliğim dışımda bile içimdesin belli ki iç dünyam  öz benliğimdir benim beni  ben yapan tohum ekmeğim  hamurum sürüncemeli dü...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ben-den-iceru-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Politika', 'politika-william-butler-yeats-yhtrt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O kız orada dururken

Ben nasıl bütün dikkatimle

Roma’nın, yok Rusya’nın

Ya da İspanya’nın

Politikaları üzerinde durayım? 

Oysa gezmiş görmüş bir adam bu

Ne söylediğini bilen.

Öbürü de mürekkep yalamış

Bir politikacı, 

Belki de söyledikleri doğru

Savaş ve savaşın belalarıyla ilgili, 

Ama ah, genç olsaydım da yeniden

Kollarıma alabilseydim o kızı!', 'O kız orada dururken Ben nasıl bütün dikkatimle Roma’nın, yok Rusya’nın Ya da İspanya’nın Politikaları üzerinde durayım?  Oysa gezmiş görmüş...', ARRAY['Türk Edebiyatı','Şiir','William Butler Yeats']::text[], 8.5, '{"poet":"William Butler Yeats","poet_slug":"william-butler-yeats","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/politika-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Olacak', 'nasil-olacak-murat-demir-7bcmr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biri haydi şimdi gel diyor

Biri yatağıma gir diyor

Biri gelmiş bundan hesap sor diyor

İnsanlığın sonu nasıl olacak

Maykıl gelmiş şeylerini tutuyor

Madonnaysa paran varsa gel diyor

Bizim kuşlar onlarla devleşiyor

İnsanlığın sonu nasıl olacak

Doktorunu arayanlar bir yana

Yalnızlığa demir atan kullara

Soruyorum sırasıyla bunlara

İnsanlığın sonu nasıl olacak

Eşekten arkadaş yetmemiş gibi

Ayıyla macera bitmemiş gibi

Fatihler fethinden geçmemiş gibi

İnsanlığın sonu nasıl olacak

Kimi kasetinde sarıl bana der

Kimi çalışmadan dünyaları yer

Kurtlarla kuzular olmuş can ciğer

İnsanlığın sonu nasıl olacak

Eller gelmiş bize hava atıyor

Fıransa da türksatımız batıyor

Bizi gören ne varsa kabartıyor

İnsanlığın sonu nasıl olacak

Gençlik bir yol tutmuş vurdum duymazca

Umurundamı dünya hep yok olsada

Aman boş ver diyor bu bir anlamda

Memleketin sonu nasıl olacak', 'Biri haydi şimdi gel diyor Biri yatağıma gir diyor Biri gelmiş bundan hesap sor diyor İnsanlığın sonu nasıl olacak Maykıl gelmiş şeylerini t...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/nasil-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
