INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mini Minnacık Bir Kadın', 'mini-minnacik-bir-kadin-mine-ozdemirtas-xf9pi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mini minnacık bir kadın olsam! ! ! ! Sığdırmayı başarabilirdin beni yüreğine.

Bir yer bulurdun bana değil mi? Kenarda ya da köşede.! ! ! ! 

Yazık ki! ! ! Ben;  Mini minnacık  olmayı başarsam bile, 

Öylesine büyük bir sevdayı yeşerttim ki yüreğimde

Ürkütmeden Kurbağaları, ......  Beni ve sevdamı; 

Sığdıramazsın değil mi?  ne yaşamında, ne yüreğinde; hiçbir yere.

Ama üzülme.  / Ben; tası tarağı toplayıp gittiğimde.

Beyaz bir örtü sereceğim. Adımla başlayan karanlık düşlerine.

Üzerine; beyaz zambaklar bırakacağım. Kucaklar dolusu.

Ve; hiç açılmamış / hiç açılmayacak / Okumadığın kadar okunmuş                           

Yazmadığın kadar yazılmış./ Bir de mektubun olacak

Yaşamadığın kadar yaşanamamış  ve mini minnacık olamamış

Bir aşktan geriye / elinde sadece....bunlar kalacak.

10/06/2003 çamlıca', 'Mini minnacık bir kadın olsam! ! ! ! Sığdırmayı başarabilirdin beni yüreğine. Bir yer bulurdun bana değil mi? Kenarda ya da köşede.! ! ! !  ...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/mini-minnacik-bir-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Bir Adam O,', 'mutlu-bir-adam-o-mine-ozdemirtas-jvnbm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mutlu bir adam O /Seviyor uzaktan

Sevildiğini de biliyor ya! ! !  / Gerisi; ne Gam? 

Belki bir gün; Kim bilebilir? 

Şöyle... boş kaldığı bir zaman

Hani; bir değişiklik ister ya insan! 

İşte öylesine bilinmeyen bir an

“Bir tatlı huzur almaya gelecek” Kalamış’tan.

Susacak. /Hiç konuşmayacak                                                                

Dem vurmayacak / Ne yazdan,  ne de kıştan

Özlediği /  Ve Adı sadece ; “Bir masum kaçamak” olan

“Bir tatlı Huzur’ u almaya gelecek Kalamış’tan.

Mutlu bir adam O / Seviyor uzaktan.

Kalamış yerinde duruyor ya! ! !  /  Gerisi ne gam? 

11/06/2003 kalamış', 'Mutlu bir adam O /Seviyor uzaktan Sevildiğini de biliyor ya! ! !  / Gerisi; ne Gam?  Belki bir gün; Kim bilebilir?  Şöyle... boş kaldığı bir...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/mutlu-bir-adam-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynasız Nakarat', 'aynasiz-nakarat-aziz-ahmet-bulut-z0guz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'talan edilmiş, 

ülkemin lirik aşkları

yade.

masum çocuk

evvel yaşam  denizinde

aynasız nakartat.

aşk zehirzemberek

zamansız

imzasız....', 'talan edilmiş,  ülkemin lirik aşkları yade. masum çocuk evvel yaşam  denizinde aynasız nakartat. aşk zehirzemberek zamansız imzasız.......', ARRAY['Türk Edebiyatı','Şiir','Aziz Ahmet Bulut']::text[], 8.5, '{"poet":"Aziz Ahmet Bulut","poet_slug":"aziz-ahmet-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/aynasiz-nakarat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok', 'yok-mahir-dereli-ve6zy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eskisi gibi bereket yok, 

Trafik kazasız günler yok, 

Önceleri kadar balık yok, 

Güvenilir insan fazla yok.

Çoğu gençlerin dişleri yok, 

Kanser olanlara çare  yok, 

Eski evleri beğenen yok, 

Paranın dini imanı yok.

Önceleri kadar fakir yok, 

İlaçsız olan sebzeler yok, 

Hastalıksız insan fazla yok, 

Ögretmnde yaya giden yok.

Televizyon olmayan ev yok, 

Önceleri gibi orman yok, 

Eskisi kadar yaşayan yok, 

Eski seneler kadar kış yok.

Ütüsüz elbise giyen yok, 

Elektiriği olmayan köy yok, 

Ağrı dağında karsız gün yok, 

Şair Mahir'' in saçları yok.', 'Eskisi gibi bereket yok,  Trafik kazasız günler yok,  Önceleri kadar balık yok,  Güvenilir insan fazla yok. Çoğu gençlerin dişleri yok,  Kan...', ARRAY['Türk Edebiyatı','Şiir','Mahir Dereli']::text[], 8.5, '{"poet":"Mahir Dereli","poet_slug":"mahir-dereli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yok-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gamze', 'gamze-oktar-almac-nd2w4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Günlerdir hasretinle yanıyor gönlüm

Ayrılığının hüznüyle soldu gönlüm

Mahsundur şimdi geçen her günüm

Zamansız bırakıp gittin gülüm, 

En güzel yıllarım heba oldu gülüm

Sensiz gecelere isyan ettim her gün

Ezildi yüreğim yokluğunda 

Nafile yakarıştır biliyorum bu son veda

İçimde bir ümit bitmeyecek sevda

Sevda ki bedenimi cayır, cayır yakıyor da 

Elimden bir şey gelmiyor gülüm.

Vakit geldi artık gitmeliyim

İstediğim mutlu olman sevdiğim

Yitirilmişliği umutlarımın şiirlerisin

Oktar bitti artık bilmelisin

Rüya gibiydi yaşanmış her şey

Umudum bitti, bitti artık her şey

Masum bir sevgi yüreğimde kalan tek şey.', 'Günlerdir hasretinle yanıyor gönlüm Ayrılığının hüznüyle soldu gönlüm Mahsundur şimdi geçen her günüm Zamansız bırakıp gittin gülüm,  En güz...', ARRAY['Türk Edebiyatı','Şiir','Oktar Almac']::text[], 8.5, '{"poet":"Oktar Almac","poet_slug":"oktar-almac","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gamze-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Arıyor Gözlerim', 'seni-ariyor-gozlerim-oktar-almac-6qq42', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni, arıyor her yerde gözlerim, 

Kime baksam, nereye baksam sen, 

Öyle özlemiş ki seni yüreğim, 

Gözlerimi kapatsamda yine sen.

Ayrılık vakti geldiğinde içimi hüzün kaplar, 

Gözlerim sen farketmeden sessiz''ce ağlar, 

Yüreğimin içi ateşlerle dolar yanar, 

Ve ellerim titrer, içime hüzün dolar.

Akşam olunca hayalin gelir karşıma

Oturur sohbet ederiz onunla, 

Seni nekadar sevdiğimi anlatırım, 

Sessizce dinler beni, dalgın bakışlarla.

Ve yine sen gidersin sabahın ilk ışıklarında, 

Yine yalnızlığımla  ben kalırım baş başa.

Bir kere seviyorum demeni bekledim günlerce, 

Ne olurdu söyleyebilseydin bir kere, 



Biliyoruz ki biz yasak aşkı yaşıyoruz, 

Bir sır gibi ikimizde, içimizde saklıyoruz.

Ne kaybederizki içimizde yaşamakla

Bir sır gibi, birbirimize bağlanmakla

Yaşasak bu aşkı o sırrın içinde, 

Biterdi belki bu isyan, bu ızdırap ve çile, 

Gel ayrılmayalım birbirimizle, 

Ve yaşayalım bu aşkı gönlümüzce.', 'Seni, arıyor her yerde gözlerim,  Kime baksam, nereye baksam sen,  Öyle özlemiş ki seni yüreğim,  Gözlerimi kapatsamda yine sen. Ayrılık vak...', ARRAY['Türk Edebiyatı','Şiir','Oktar Almac']::text[], 8.5, '{"poet":"Oktar Almac","poet_slug":"oktar-almac","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seni-ariyor-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutsuzluk Reçetesi', 'mutsuzluk-recetesi-ahmet-unal-cam-6tqwk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hep yeni yerlere gitmek isterim, 

Hep bıraktığım diyarları özlerim.

Bin dost kazansam, birini 

              kaybetmeye ağlarım.

Yaptığım iyilikleri, 

              yapılan kötülükleri unuturum, 

Bana iyiliği dokunanlar hep aklımda, 

       hep borçluyum birilerini vefa.

Atılan taşlara alışırım da

       mezarımda bir çakıl üzer beni

Attığım her adım, götürür beni geri

Yokuşları çıkarım, deniz bulurum

Gönlümün derinlerinde gizli dağlar

Pasta yiyenler, elimdeki kuruya ağlar…

Her akşam hüzünlere doğarım, 

Her sabah yalnızlık bulur beni

Kalabalıklar atar çukurlara, 

                       nefsim karşılar beni', 'Hep yeni yerlere gitmek isterim,  Hep bıraktığım diyarları özlerim. Bin dost kazansam, birini                kaybetmeye ağlarım. Yaptığım iy...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mutsuzluk-recetesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canevimden Vur Beni', 'canevimden-vur-beni-i-brahim-bayraktar-5q8gw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Deli gönlün geçit vermez dağ bana, 

Karagözün salkım salkım bağ bana, 

Yıldız olup, damla damla yağ bana.

Naz sende, zarafet senden ibaret.

Gam olma bana, gamhanem ol, 

Sende hayat bulayım bahanem ol, 

Sevdama sevda ekle bir tanem ol, 

Bütün ümitlerim sende nihayet.

Kanat olup bedenine dolansam, 

Bulut olup her teline dokunsam, 

Eğer sana senden daha yakınsam, 

Hasretine katlanırım etmem şikayet.

24.06.2003', 'Deli gönlün geçit vermez dağ bana,  Karagözün salkım salkım bağ bana,  Yıldız olup, damla damla yağ bana. Naz sende, zarafet senden ibaret. ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/canevimden-vur-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'anlayamazlar', 'anlayamazlar-i-kbal-senturk-596se', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yıllardır gizlice büyüttüğüm 

sana ait hasreti

ne sen, nede yanındakiler 

anlayamazlar

ağlamamak için, ısırılan dudakların

acısını

gözlerini kaçırıp gizlenmenin

ezikliğini

dimdik durup

içinde kopan fırtınalarla savaşmayı

boş vermenin, 

aldırmaz görünmenin

ağızdaki ekşi tadını

kadere isyan edememenin

burukluğunu

ne SEN, nede yanındakiler

anlayamazlar', 'yıllardır gizlice büyüttüğüm  sana ait hasreti ne sen, nede yanındakiler  anlayamazlar ağlamamak için, ısırılan dudakların acısını gözlerini...', ARRAY['Türk Edebiyatı','Şiir','İkbal Şentürk']::text[], 8.5, '{"poet":"İkbal Şentürk","poet_slug":"i-kbal-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/anlayamazlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nihavent', 'nihavent-murat-tali-is6wp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen uzakların türküsü

nihavent makamı notalarım

kimi zaman hicaz özlemi yangınlarımsın

kimi zaman

yüklü yüklü kürdilihicazkar nağmelerim

kanunun üzerinde gezen mızrap

udumdaki en ince ve en kalın telsin

ezgisin defterlerimdeki notalarda

şiirsin satırlardaki kelimelerde

sana şiir yüklü 

hüseyni makamından

geldim

gözlerini 

Rast makamından yoğurdum

Özlemlerini 

Mağrur bestelerle 

Çevirdim acemşiran makamına

Hiç susmadan

günlerce çalman için

uşşak makamından hasretleri', 'sen uzakların türküsü nihavent makamı notalarım kimi zaman hicaz özlemi yangınlarımsın kimi zaman yüklü yüklü kürdilihicazkar nağmelerim kan...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nihavent-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kulların', 'kullarin-sema-senel-cjn9z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne çileler gördüm hiç tükenmedi

Mutlu oldum diyen kiymet bilmedi

Ellerini açip  Mevlam demedi

Şükrana  lüzum duymaz kulların

Zamanı tüketirler boş vakitlerle

Moda deyip uydular ne hünerlerle

Dünya malı batmaz göze derlerde

Bir doğruyu bulamaz senin kulların

Nefisler uslanmaz sanki kör kuyu

Hasat kabul etmez çamurlu suyu

Belki tövbe edecek değişse huyu

Pişmanlık nedir bilmez kulların

Sallanır yerler orta yerinden

1 saniye 1 sene  geçti demeden

Ateşten topu ibret görmeden

Yine eski hallerini alir kulların

Helal bilmez kokar kirli nefesler

Ellerinde dolaşır sahte formüller

Dillerinde yankı,  acı  tebliğler

Gazabından korkmaz zalim kulların

Dünya yı döndürürler tek başlarına

Doğradıkları çıkıyor kaşıklarına

Bin türlü belayı sarsan başina

Uslanmak bilmez nankör kulların

Dünden yorgun kalacak koşan atları

Gün gelirde yıkılır sultanatları

Kurtarır mı sanırlar o gün putları

Şeytana boyun egen aciz kulların

Hepsi kendince birer ehiller

Tek düşünce sıçrar kümelenirler

Yolunu şaşırıp ta mehtiyiz derler

Inanacak az kalsın şaşkın kulların

Sifatlarına bakar da hayran kalırlar

Inanmazlar yine de fesat katarlar

Anahtarı islamdan öte  ararlar

Formülü çözemeyen cahil kulların

Bıkmadan okurlar her tür kitabı

Kur´an´ı iter  tek parmakları

Öldükten sonra hangi hakları

Savunacak bıkkın cahil kulların

Islamı anlatırlar yürek ise boş

Münafıklar doldu, koş kardeşim koş

Inkar eden kafirlere dünya hepten hoş

Rahmetinden yoksundur böyle kulların

Giydirdiğin elbise çıkacak bir gün

Pişmanlık fayda etmez bilmezler o gün

Ölümü düşünseydi beşerler  hergün

Yanarmıy dı o gün güzel kulların

Gelmez ki aklına üç günlük dünya

Yaşananlar kalacak, hepsi bir rüya

Kalbinde taşırlarmış HÜDA´YI güya

Derlerde emrine uymaz kulların

12:15

23/06/03', 'Ne çileler gördüm hiç tükenmedi Mutlu oldum diyen kiymet bilmedi Ellerini açip  Mevlam demedi Şükrana  lüzum duymaz kulların Zamanı tüketirl...', ARRAY['Türk Edebiyatı','Şiir','Sema Senel']::text[], 8.5, '{"poet":"Sema Senel","poet_slug":"sema-senel","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/kullarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakışmış Sana', 'yakismis-sana-cemal-safi-uieik', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne kadar kolaymış esirin olmak 

Tesadüf eseri bakışmış sana 

Sen derya olmuşsun ben coşkun ırmak 

Sonrası çaresiz akışmış sana... 

Kaçıncı kalbimi kırıp gidişin 

Aldığın vebali günahı düşün 

Adımı Mecnun''dan beter edişin 

Leyla''dan daha çok yakışmış sana... 

Bir gece aklına delin düşmedi 

Yaktığın ateşe külün düşmedi 

Yıllardır insafa yolun düşmedi 

Merhamet ne kadar yokuşmuş sana...', 'Ne kadar kolaymış esirin olmak  Tesadüf eseri bakışmış sana  Sen derya olmuşsun ben coşkun ırmak  Sonrası çaresiz akışmış sana...  Kaçıncı k...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yakismis-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayışığı', 'ayisigi-ali-saglam-3-pfayd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana tutkun, aşıktı.

Seni tanıyan kim varsa.

Erişilmezdin...

Aşkın, sevdanın

İkiz kardeşiydin.

Anlatmaya acizdi kelimeler.

Yüzünde açan, 

Tomurcuk gülleri.

Zaman unutturamaz ömrüme.

Dokunduğum o elleri.

Bir hırçın denizdin.

Vuruyordun vakitli, vakitsiz.

İçimdeki sahillere.

Aşkı sen öğrettin.

Sana tutkun bu kalbe.

Anlatmaya acizdi kelimeler.

Sana duyulan

Bu eşsiz aşkı.

Sen içimde bir renksin.

Gözlerimde ayışığı...', 'Sana tutkun, aşıktı. Seni tanıyan kim varsa. Erişilmezdin... Aşkın, sevdanın İkiz kardeşiydin. Anlatmaya acizdi kelimeler. Yüzünde açan,  To...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ayisigi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmesini Bilene', 'sevmesini-bilene-ensar-aktas-nz0nn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyorsan sevmeyi

Bu bilmezlik tavrı ne

Düşlerinde sevdayı

Yaşamanın sırrı ne

Bir kere gülmek yetmez

Yaşamayı bilene

Bin kere ölmek yetmez

Sevmesini bilene

Uyan da bak dünyaya

Güneş doğuyor hâlâ

Küsmek niye hayata

Sevmesini bilene

Her yıldızı seven var

Onlar bunu bilmese de

En güzel yıldız sensin 

Sevmesini bilene

Dağların karı benim

Güneşin ısısı sen

Doğ üzerime eriyeyim

Sevmesini bilirim ben

Gouda,14.10.2002', 'Biliyorsan sevmeyi Bu bilmezlik tavrı ne Düşlerinde sevdayı Yaşamanın sırrı ne Bir kere gülmek yetmez Yaşamayı bilene Bin kere ölmek yetmez ...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevmesini-bilene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kuş Gibi', 'bir-kus-gibi-ensar-aktas-i70ue', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir kuş gibi besle sevgimi yufka yüreğinde

Kafesini geniş tut ki sıkışmasın serpildikçe

Sevginle besle sevgimi, mayası aşk olsun

Olur da bir gün salıverirsen eğer

İçinde ukde kalmasın, gözlerinde kin

Özgürce çırpsın kanatlarını, aşka çırpsın

Bir beyaz güvercin gibi barışa uçsun

Sevgiye, sevgiyle, sevgiliye…

Rotterdam,15-06-2003', 'Bir kuş gibi besle sevgimi yufka yüreğinde Kafesini geniş tut ki sıkışmasın serpildikçe Sevginle besle sevgimi, mayası aşk olsun Olur da bir...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-kus-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şiir Başka Şiir', 'bu-siir-baska-siir-oguzkan-bolukbasi-r7ox0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen benim yanlış yerde başlayan sevdamsın

Herşey yanlış

Zaman

Mekan

Vaziyet 

Bu eziyet çekilirken

Tek doğru olan seni sevmem

Bu doğruya yetemem

Diyen  gözlerin de yalan söylüyordu

Kaçıp giderken ellerimin arasından 

Yerlere dökülen dudaklarından

Ne damlasıydı 

Bahar yağmurlarından 

Ve toprak kokularından daha anlamlı

Duyamadım

Dokunamadım

Ne zaman yanlış yapsam o nedenle

Yani bir çılgınlık

Yani bir  insani  dellenme

Ve fakat  umutsuzca

Senin hatırın için

Bir adım ileri gidemem', 'Sen benim yanlış yerde başlayan sevdamsın Herşey yanlış Zaman Mekan Vaziyet  Bu eziyet çekilirken Tek doğru olan seni sevmem Bu doğruya yete...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bu-siir-baska-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Prenses', 'prenses-ali-saglam-3-3j2of', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duyurmuyor sesini, 

Selamını getirmez yollar.

Sensiz tükenecek, 

Koca ömür.

Sensiz tükenecek, 

En güzel yıllar.

Bir çizgi daha atıldı.

Duvarın bir köşesine.

Ölüm bugünde tahsil etti.

Ömrümden alacağını.

Bir yaprak daha koptu.

Sevda çiçeğinden.

Baharlar gitti.

Dönmüyorlar seferinden.

Sen dönmüyorsun.

Aşk dönmüyor.

Yıllar dönemiyor.

Gittiği yerden.

Gözlerimde bir hayaldin.

İçimde kalan bir heves.

Unutmam diyordun hani? 

Unutuluyormuş değil mi? 

Prenses...', 'Duyurmuyor sesini,  Selamını getirmez yollar. Sensiz tükenecek,  Koca ömür. Sensiz tükenecek,  En güzel yıllar. Bir çizgi daha atıldı. Duvar...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/prenses-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gebe Mevsimler', 'gebe-mevsimler-askin-gungor-so8wa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anlamayacaksın, 

     neden dudağıma aynı sitem bulanmış; 

          neden yıkıyorum ağzımı

               seni öptüğümü hatırladıkça

                   ve neden kaldırımlarda arıyorum yitirdiğimi

                        yağmur kenti yıkadıkça...

Çünkü zaman bu kentte

     mevsimi gebe bırakmış

          ve keder denen harami, 

               bir yokmuş, bir varmış

                    bir yokmuş, bin bir varmış...

Sen her gece

     zaman mevsimle ilişkiye girince

          başka tenlerle sarmalanırken, 

               nasıl anlayacaksın

                    neler söyler

                         penceresinden geceye yıldız tüküren

                              bir sevgiliye                             

                                   zaman baba ile kırk haramiler.

Kim bilir

     belki de sana yazıp da unuttuğum bir şiirle yanacaksın.

Yine de sevdanın tenimde nasıl dolaştığını

     hiç anlamayacaksın. 

(24.06.2003)', 'Anlamayacaksın,       neden dudağıma aynı sitem bulanmış;            neden yıkıyorum ağzımı                seni öptüğümü hatırladıkça       ...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Güngör']::text[], 8.5, '{"poet":"Aşkın Güngör","poet_slug":"askin-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gebe-mevsimler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanatları Yırtık Melek', 'kanatlari-yirtik-melek-askin-gungor-lpmlz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hah ha, bak sen şu işe, çok seviyormuş, öyle mi? 

Yokluğumda ölecekmiş demek.

Gerekirse kapıma dek gelip de sürünerek

     kocaman gözyaşlarıyla 

          ve hatta bağıra çağıra

               ağlayacakmış demek.

Kirlettiklerini yıkayacak, 

     kırılanları yapıştıracak

          yüreğimdeki öfkeyi dindirecek, 

               hayallerde kalan evimizi

                    köşe bucak süpürecek

                         ve her şeyi aynı aklığıyla

                              yerli yerine dizecekmiş demek.

Yok yahu, daha neler, çok seviyormuş, öyle mi? 

Bensiz nefesleri eksikmiş, 

     Bütün hayalleri hiç kişilikmiş

          Tuttuğu eller el değil, 

                Seviştiği tenler ten değilmiş.

Beş dakikaya kadar gelmezsem ölecekmiş, öyle mi? 

Söyle ona, 

     aklının aynasında her gece

          kendi ölümünü görmenin

               ve alınan bir nefesle iki kere ölmenin

                     ne demek olduğunu bilir mi? 

Sor ona, 

     yüreğimdeki meleğin tül kanatları yırtık artık; 

           dikebilir mi? 

(24.06.2003)', 'Hah ha, bak sen şu işe, çok seviyormuş, öyle mi?  Yokluğumda ölecekmiş demek. Gerekirse kapıma dek gelip de sürünerek      kocaman gözyaşlar...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Güngör']::text[], 8.5, '{"poet":"Aşkın Güngör","poet_slug":"askin-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kanatlari-yirtik-melek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Ateş', 'i-lk-ates-ali-saglam-3-w3l7w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eller ayrıldı birbirinden.

Gözler yabancılaştı.

Tuzlu bir yalnızlık.

Yalayıp geçti sahili.

Ümitler tükendi birden.

Bir yumruk indi kalbe.

Hüzün yağdı gözlerden.

Karanlık bir köşeden.

Islık çalarak gitti sevda.

Mutluluklar çıktı yörüngeden.

Kan sızdı dudaklarımdan.

İnceden inceye bir sızıyla.

Gözler ağlamaklı, duruşum serkeş.

Gençliğimi yakıp geçti.

Kalbe düşen o ilk ateş.', 'Eller ayrıldı birbirinden. Gözler yabancılaştı. Tuzlu bir yalnızlık. Yalayıp geçti sahili. Ümitler tükendi birden. Bir yumruk indi kalbe. Hü...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ilk-ates-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Mavinin Altında Değilmiş', 'sevgi-mavinin-altinda-degilmis-birol-ozkan-i8t7v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seni severken, 

sevginin rengiydi mavi...

o seni severken acının, 

sana söylerken sevdiğimi, 

umudun rengiydi mavi..

ve umut bitti

şimdi...

mavi sevgi, 

mavi acı, 

mavi umut, 

mavi ayrılık.......

sevgim mavi değilmiş anladım, 

kapkaraymış..

sevgi mavinin altında değilmiş, 

mavi sevgimin üzerinde kalmış anladım...', 'seni severken,  sevginin rengiydi mavi... o seni severken acının,  sana söylerken sevdiğimi,  umudun rengiydi mavi.. ve umut bitti şimdi... ...', ARRAY['Türk Edebiyatı','Şiir','Birol Özkan']::text[], 8.5, '{"poet":"Birol Özkan","poet_slug":"birol-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevgi-mavinin-altinda-degilmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karbeyaz', 'karbeyaz-ali-saglam-3-fnuxf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zaman durmadı.

Dağlar yıkılmadı.

Kıyamette kopmadı.

Gidişinle...

Gözlerde yaş.

Çokça hüzün.

Ayrılığa sitemdi.

En kırıcı sözüm...

Yokluğun öldürmedi.

Yaktı koca bir yaz.

Ama umudum sönmedi.

Umutlar hala karbeyaz...', 'Zaman durmadı. Dağlar yıkılmadı. Kıyamette kopmadı. Gidişinle... Gözlerde yaş. Çokça hüzün. Ayrılığa sitemdi. En kırıcı sözüm... Yokluğun öl...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/karbeyaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık', 'asik-ali-saglam-3-6hiqw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneşte gölgesin.

Gecemde ışık.

Kalbim sensizliğe değil.

Sana tutkun.

Sana alışık.

Varlığın kaderim.

Aşkın sebebim.

Hep sana ağlar.

Hep seni sever.

Tek seni yazar kalemim.

Seni düşünmekle.

Geçer günler.

Sensiz içim.

Karma karışık.

İliklenmiş.

Kalbine kalbim.

Öyle deli, öyle çılgın.

Öyle aşığım sana aşık.', 'Güneşte gölgesin. Gecemde ışık. Kalbim sensizliğe değil. Sana tutkun. Sana alışık. Varlığın kaderim. Aşkın sebebim. Hep sana ağlar. Hep seni...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/asik-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Defteri', 'gonul-defteri-ali-saglam-3-yjh9r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk denilen o arsız ve tatlı kelimeyi.

Yazacak yer kalmadı, gönül defterimde.

Bundan böyle dost''u, arkadaş''ı sevgili''yi.

Yazacak yer kalmadı gönül defterinde.

Kahretmekten kahroldum, kahrederek hayatı.

Bıraktım aksın yaşlar sevdanın gözlerinde.

Ne eksik, ne fazla, ne mutlu, ne acı.

Yazacak yer kalmadı gönül defterimde.

Hayatıma saplanan iki ucu keskin bıçak.

Saplandığı gibi duruyor sapladığın yerde.

İyi kötü, mutlu mutsuz, yalnız yada şaşkın.

Yazacak yer kalmadı gönül defterimde.', 'Aşk denilen o arsız ve tatlı kelimeyi. Yazacak yer kalmadı, gönül defterimde. Bundan böyle dost''u, arkadaş''ı sevgili''yi. Yazacak yer kalmadı...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-defteri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum Anlayacaksın!', 'biliyorum-anlayacaksin-turgay-kaygi-frsw2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'affına sığınarak

bir düş kurdum abla! 

bir şöminenin başına

toplanmışız 3-5 kişi; 

çekmişiz iskemleleri

sen, ben 

bir de

dünyanın bilmediğimiz yerlerinden gelmiş

bir kaç tanımadığımız canciğer dostumuz...

anlatıyoruz boyuna

geçmişten, gelecekten

gülüyoruz

kelimeler birbirine karışıyor bazen

bazı da sessizlik çöküyor hepimize

dışarısı soğuk besbelli

-buz gibi derler ya! 

hah! işte aynen öyle-

karanlığı sızmış gecenin pencerelerden odaya

haendel çalıyor gramafonda, 

üst kattan usul usul geliyor aramıza sesi

duvarların hiçbirimizin yüzüne bakacak cesareti yok; 

karanlığın ardına saklanmış hepsi...

herşey güzel! 

herşey ancak olabileceği kadar iyi! 

fakat 

hepimiz bilmekteyiz ki

bu soğuk gecede

ellerimizi, yüzlerimizi aydınlatan

o şöminedeki ateş var ya abla! 

o ateşi biz yakmış değiliz ki! 

bizler yalnızca o ateşin esiriyiz! 

(inegöl,  24.06.2003)', 'affına sığınarak bir düş kurdum abla!  bir şöminenin başına toplanmışız 3-5 kişi;  çekmişiz iskemleleri sen, ben  bir de dünyanın bilmediğim...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/biliyorum-anlayacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatlı Kamer', 'tatli-kamer-giray-ozer-ril4a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İçime meyil eder deryanın en derin suları bu gece

Ufkunda Tekirdağ''ın simle işlenmiş bir vapur gibi kahpe kader

Seyre daldım gözlerini, kirpiklerini acımasızca severek, delice

Seni unuttuğumu zannettiğin her anda, 

Seni bin kat daha fazla sevdim Ah! .. Tatlı Kamer', 'İçime meyil eder deryanın en derin suları bu gece Ufkunda Tekirdağ''ın simle işlenmiş bir vapur gibi kahpe kader Seyre daldım gözlerini, kirp...', ARRAY['Türk Edebiyatı','Şiir','Giray Özer']::text[], 8.5, '{"poet":"Giray Özer","poet_slug":"giray-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/tatli-kamer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Perisi', 'gece-perisi-ali-saglam-3-o6lml', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(Oya ''ya...)

Seni yazmak, 

Beni Yazmak, 

Bizi Yazmak, 

İmkansız biliyorum.

Bu her kalemin taşıyabileceği, 

Her defterin kaldırabileceği kadar, 

Hafif bir sorumluluk değil...

Seni iki basit kelimenin arasına, 

Sıkıştırmak istemiyorum.

Seni ne kendi karanlığıma, 

Ne de kendi karanlığına, 

Gizlemek istemiyorum...

Sen masmavi denizlerin, 

Sen bembeyaz bulutların, 

Ruhunu taşıyan, 

Özgür bir martısın, 

Benim için...

Ve sen uçmalısın, 

Yaşamalısın, 

Solmamalısın...

Seni bana yazdıran ne idi.

Çok düşündüm bulamadım.

Belki senin içinde gizliydi.

Sorularımın cevabı, 

Ulaşamadım...

Ya da ulaşmak istemedim.

Ya da ulaşmamı istemedim.

Ya da birileri engelledi.

Ya da hepsi...

Seninle aynı havayı solumak isterdim.

Seninle hasreti, acıyı

Hayatı solumak isterdim...

Aramızda şehirden duvarlar var.

Aşılması bir o kadar kolay, 

Bir o kadar zor, 

Duvarlar...

Hep dedim ya dostum; 

''Çünki her şey böyleyken güzel''

Aslında yalandı, 

Hiçbirşeyin böyleyken, 

Güzel olduğu yoktu.

Sen yoktun yokluğun vardı.

Yokluğun paylaşılabilecek, 

Tek şey ise yokluğundu...

Oysa ben en çok mutluluğu, 

Sevgiyi paylaşmayı severim.

Ben gülmeyi, 

Ağlamayı, 

Acı çekmeyi, 

Hayatı severim.

Ben insanları sevmem.

Ben özünde 

İnsanlık olanları severim...

Seni yazmak, 

Beni yazmak, 

Bizi yazmak, 

İmkansız biliyorum.

Bu her yüreğin taşıyabileceği, 

Her aklın kaldırabileceği kadar, 

Hafif bir sorumluluk değil...

Karanlık çöktüğünde, 

Geceden bir elbise giyiyorsun üzerine.

Gece gözlerine yazılmış şiir senin.

Sen aslında; 

Bir gece perisisin, 

Periler prenses''isin...

Gece perisi; 

Dokun hadi, 

Yıldız yıldız büyülü gözlerinle omuzlarıma, 

Ve şu kahrolası laneti kaldır artık...

                                                                 01.10.2002', '(Oya ''ya...) Seni yazmak,  Beni Yazmak,  Bizi Yazmak,  İmkansız biliyorum. Bu her kalemin taşıyabileceği,  Her defterin kaldırabileceği kada...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/gece-perisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak Kolay mı Sanki?', 'unutmak-kolay-mi-sanki-ali-saglam-3-8n3qm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Unut diyorlar seni.

Unutmak kolay mı sanki? 

Çok sevdim unutamam.

Unutmak kolay mı sanki? 

Uğrunda gözyaşı döküp.

Anıları maziye gömüp.

Aşkını kalbimden söküp.

Unutmak kolay mı sanki? 

Ne akıllıyım ne deli.

Bulamaz oldum ben beni. 

Bir çırpıda o gözleri.

Unutmak kolay mı sanki? 

Aşkın bende yanarken.

Gözlerim gidişine ağlarken.

Bir tel saçına ölürken.

Unutmak kolay mı sanki?', 'Unut diyorlar seni. Unutmak kolay mı sanki?  Çok sevdim unutamam. Unutmak kolay mı sanki?  Uğrunda gözyaşı döküp. Anıları maziye gömüp. Aşkı...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/unutmak-kolay-mi-sanki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Kendimi Takdimimdir', 'bu-kendimi-takdimimdir-oguzkan-bolukbasi-9wg9z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu sen olmayan bir şiir

İçimin su yeşilinde akıp gitmesi

Mevsimsiz kuşların dallarıma konması

Ve mevsimsiz çiçeklerin açması bahar öncesi

Yaprakların yeşermesi bir bir

Gizli bir sevda filizlenir

Çıt kırılacak kökleri toprak üzerinde

Yürek önce sevinir

Sonra hüzün

Her aşkın sonunu bilir

Kalbim tecrübelidir

Yıl eski zamanlar bir duygu yüklemişim dizelere

Henüz çocuğum

Beşinci şiirim belki

“Çakıl taşlarından bir ev yapacağım sana

Gündüz güneş gece gözlerin ışıtacak”

Umut vardı dizlerimde evlerimi taşırdım hayallerimde

Sonra acılar ve umutsuzluklar

Hala çocuğum 

Onuncu şiirim

“Ölüm kadar güzelsin yaşamak kadar acı

Hayat kadehinde kalan en son damlasın

Ben kadehin içinde kadeh bana yabancı

İçin siz o damlayı bana bir şey kalmasın”

Ölümü sevdiğim şiirim

Belki yirmi belki yirmibirim

Sonra her aşka bir şiir

Her şiire bir aşk

İçim akar gider güzelliğin peşinden

Burada

Sadece bir cümle yazdım kendimden

Bir emin olursam beğendiğinizden

Hayatım akacak ellrinizden', 'Bu sen olmayan bir şiir İçimin su yeşilinde akıp gitmesi Mevsimsiz kuşların dallarıma konması Ve mevsimsiz çiçeklerin açması bahar öncesi Ya...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bu-kendimi-takdimimdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalin', 'hayalin-nihat-tasdemir-l11ns', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni, hayalinle aldattım dün gece.

Gerçi senin gibi bakmıyordu gözlerime, 

Ama kapanıp da dizlerine yalvardım...

Ne olur sende bırakıp gitme diye.

Hiç kimse yerini tutamaz ya

Ama hayalinde olsa sendin karşımda.

Hiç kimse senin gibi saramaz ya, 

Ama hayalinde olsa ellerindi avucumda.

Yalandı be güzelim, yalandı. 

Sadece dün gece değil, 

Gittin gideli her gece, 

Evet evet her gece

Hayalinle aldatıyorum seni.

Yorgun Yalnızlıklar isimli kitabımdan', 'Seni, hayalinle aldattım dün gece. Gerçi senin gibi bakmıyordu gözlerime,  Ama kapanıp da dizlerine yalvardım... Ne olur sende bırakıp gitme...', ARRAY['Türk Edebiyatı','Şiir','Nihat Taşdemir']::text[], 8.5, '{"poet":"Nihat Taşdemir","poet_slug":"nihat-tasdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hayalin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başbaşa', 'basbasa-hakan-rodop-4uw18', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne zaman bıraksalar

beni kendimle

bir kuş kanatlanır

yüreğimde

yükselir göğe

kanat çırpmayı

bilmeyen kuşlarla

buluşurum gökyüzünde

umutla tırmanırım

metreleri bir bir

meraklanırım 

daha ne var 

ne var ileride

beni kendimle

ne zaman bıraksalar

yanımda 

bir kuşla uyanırım...', 'Ne zaman bıraksalar beni kendimle bir kuş kanatlanır yüreğimde yükselir göğe kanat çırpmayı bilmeyen kuşlarla buluşurum gökyüzünde umutla tı...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/basbasa-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ömür Boyunca Seveceğim Ol', 'bir-omur-boyunca-sevecegim-ol-veli-altioglu-vs6mr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Denize dökülen bir ırmak gibi 

Öyle ak içime öylesine dol 

Yarına açılan bir yaprak gibi 

Unuttur mazimi geleceğim ol

Hasretin yerini müjdeler alsın 

Bırak da mutluluk kapımı çalsın 

Bütün acılarım dünlerde kalsın 

Unuttur mazimi geleceğim ol 

Yorgunum yıllardır hep beklemekten 

Yorgunum gönlüme sabır eklemekten 

Kurtar artık beni hasret çekmekten 

Unuttur mazimi geleceğim ol 

Bir ömür boyunca seveceğim ol', 'Denize dökülen bir ırmak gibi  Öyle ak içime öylesine dol  Yarına açılan bir yaprak gibi  Unuttur mazimi geleceğim ol Hasretin yerini müjdel...', ARRAY['Türk Edebiyatı','Şiir','Veli Altıoğlu']::text[], 8.5, '{"poet":"Veli Altıoğlu","poet_slug":"veli-altioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-omur-boyunca-sevecegim-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayabilir misin?', 'anlayabilir-misin-ali-tosmer-ikvfy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'anlayabilir misin beni..

a desem; 

aşık olduğumu..

s desem; 

seni sevdiğimi..

bilebilir misin..? 

bakabilir misin gözüme

gözbebeklerime..

bebeğimi

görebilir misin...? 

duyabilir misin sesimi

fısıltılarımı

anlayabilir misin..? 

yaklaştırabilir misin nefesime

dudaklarını..

okşayabilir misin saçlarımı

dokunabilir misin ellerime

ağaran nefsime..

ve rûhuma..

................dokunabilir misin..? 

söyle eey alçakgönüllü yüksek nefis..

nefis nefis..

dokunabilir misin..

ve rûhumca..

...............okunabilir misin...? 

                           (25haziran’03)', 'anlayabilir misin beni.. a desem;  aşık olduğumu.. s desem;  seni sevdiğimi.. bilebilir misin..?  bakabilir misin gözüme gözbebeklerime.. be...', ARRAY['Türk Edebiyatı','Şiir','Ali Tosmer']::text[], 8.5, '{"poet":"Ali Tosmer","poet_slug":"ali-tosmer","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/anlayabilir-misin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki Bir Gün', 'belki-bir-gun-hasan-kagan-yayla-adnm0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kara yazılmış şu yazım, 

Kimselere yoktur sözüm.

İçten içe, sızım sızım, 

Azar azar yanar gönül...

Yirmibeş yıl geçti yarsız, 

Hep hoyratça hep umarsız...

Şimdi neden arsız arsız 

Damla damla kanar gönül? 

Kağan için yoktur sefa, 

Her gün bin dert bin bir cefa.

Hiç olmazsa tek bir defa

Coşsaydı şu pınar gönül!', 'Kara yazılmış şu yazım,  Kimselere yoktur sözüm. İçten içe, sızım sızım,  Azar azar yanar gönül... Yirmibeş yıl geçti yarsız,  Hep hoyratça ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kağan Yayla']::text[], 8.5, '{"poet":"Hasan Kağan Yayla","poet_slug":"hasan-kagan-yayla","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/belki-bir-gun-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoruldu Bu Sevda İçimde', 'yoruldu-bu-sevda-i-cimde-derin-oger-s2ofq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bağrıma bastım

Pervasız  hayalini

Alnımın yazısıdır diye

Salındı durdu gözlerimde

Gezindi yaralar üstünde

Bir türlü gelmedi gönüle

Gölgelerden seyrettim güneşini

Uzaklardan kokladım menekşelerini

Tenhalar da yazdım şiirlerimi

Yoruldu bu sevda içimde

Sürüldü ayaklarım

Bir adım bile atamadan

Gönül bahçene........', 'Bağrıma bastım Pervasız  hayalini Alnımın yazısıdır diye Salındı durdu gözlerimde Gezindi yaralar üstünde Bir türlü gelmedi gönüle Gölgelerd...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yoruldu-bu-sevda-icimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bul Beni...', 'bul-beni-necat-i-ltas-m12l9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Toprağın kalp atışını duy! 

Ritmine ayak uydur, 

Avuçlarında coşkusunu yakala, 

Öfkesini gözlerinde biriktir, 

Sevgisini yüreğine işle.

Mesela Kızıltepe''de bir halay, 

Bu halayda terli bir mendil ol.

Gözleri güneş, 

Dudakları ateş, 

Ney''in sihirli hüznünü üfle can evime.

Yıldızlara asılı bedenimde martı çığlığı.

Kelebeğin özgürlüğünde bir ilahi, 

Başağın kadın yüzünde bul beni.

Kendini yıkarak var ol; 

Çünkü bu gerçeğin kırılma noktasıdır...

Kırılarak gerçek bulunur yalan pazarında.

Kırıl, yan, piş ve bul beni... Bul...

Çevir gözlerini dağlara, 

Dağdan vadiye süzülen rüzgarı, 

Güneşin tenini, 

Suyun gücünü, 

Ateşin öfkesini hisset.

Uçuruver özlemlerini, 

Beyaz güvercinin kanatlarına bağla sevdanı, 

Yüreğinin gözyaşlarıyla sulansın, 

Çatlasın gonca, 

Çiçeklensin umutlar..

Her ova kendi ihanetini, 

Her orman kendi uğultusunu, 

Her dağ kendi destanını saklar, 

Omuzundaki dumanda...

Başını yukarı kaldır, dik tut.

Yıldızlara gülümse, 

Yıldızlar senin için parlayacak, 

Terleyen otların kokusunda, 

Göğün yerle birleştiği yerde bulacaksın beni.

İşte mutluluk bu, 

Sözlerle ifade edilemez, 

Zaman sana ait olur beni bulduğunda...

Şahdamarı gibi öldürücü, 

Şahdamarı gibi varedici, 

Kendini yıkarak var ol; 

Kanımda şahlanan deniz dalgasında, 

Gerçeğin kırılma noktasında, bul beni...

Necat İLTAŞ (2000)', 'Toprağın kalp atışını duy!  Ritmine ayak uydur,  Avuçlarında coşkusunu yakala,  Öfkesini gözlerinde biriktir,  Sevgisini yüreğine işle. Mese...', ARRAY['Türk Edebiyatı','Şiir','Necat İltaş']::text[], 8.5, '{"poet":"Necat İltaş","poet_slug":"necat-i-ltas","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/bul-beni-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem’e', 'annem-e-ozcan-ozkan-g7q9a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerinde yaş, dilinde türkü, 

Geceyi yırtardı dikiş tıkırtıların.

“Karadır kaşların ferman yazdırır”

“Asmalardan kol uzatmış dallere”

Ben yorganın içinde hiç uyumazdım anne.

Bana yüklediğin yükleri düşün.

Ne kadar ağırdı, ne çok ezildim. 

Oysa ben kocaman bir kızken bile; 

Hâlâ senin memeni emerdim.

Şiirler ezberletirdin kendi yazdığın.

Ben törenlerde okurdum senin yerine.

Artık hindibağı bile toplamaz oldun.

Hangi banka en çok veriyor anne. 

Ne zaman bir çınaraltı serinliği arasam, 

Yüzümü senden yana çevirsem, 

Hep başın, hep belin, hep heryerin ağrıyor.

Sen artık hiç süt kokmuyorsun anne.

Koynunda kefen çıkının, mezar taşı gibisin.

Gözüne bakınca.......of! 

Sesimi duyunca.......ah! 

Yarınım diye diye ağlıyorsun.

Yavrum demeni özledim anne.

Bu dünyaya yeniden doğmak mı istiyorsun? 

Ömrümü ömrüne katmak mı istiyorsun? 

Sen benim sırtımda yatmak mı istiyorsun? 

Bu kadar çok sevme hayatı anne.

Benim de saçımda aklar var artık.

Ruhum bedenimden çok daha yaşlı.

Baksana tükendim daha ne kaldı? 

Bir kerecik “nasılsın? “diyemiyorsun.

Sen beni ne diye doğurdun anne? 

Anılarım olmasa, sen olmasan anılarda, 

Bana anlattığın masalları unutabilsem, 

Başımda sabahladığın çocuk hastalıklarım, 

Ve o duygu yüklü mektupların olmasa, 

Nasıl istersen öyle öl anne...

(2003)', 'Gözlerinde yaş, dilinde türkü,  Geceyi yırtardı dikiş tıkırtıların. “Karadır kaşların ferman yazdırır” “Asmalardan kol uzatmış dallere” Ben ...', ARRAY['Türk Edebiyatı','Şiir','Özcan Özkan']::text[], 8.5, '{"poet":"Özcan Özkan","poet_slug":"ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/annem-e-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşin Doğum Günü', 'gunesin-dogum-gunu-yalcin-ergir-fpl48', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her sabah Saatli Maarif Takvimi’nin

En üstteki yaprağını koparmak yerine

Her sabah Saatli Maarif Takvimi’nin

En üstüne yeni bir yaprak eklemek...

Bütün duvarların dolsun

Bugünkü doğum günün kutlu olsun', 'Her sabah Saatli Maarif Takvimi’nin En üstteki yaprağını koparmak yerine Her sabah Saatli Maarif Takvimi’nin En üstüne yeni bir yaprak eklem...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergir']::text[], 8.5, '{"poet":"Yalçın Ergir","poet_slug":"yalcin-ergir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gunesin-dogum-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-murat-tali-gbs42', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hamza Abi''me...

Ölümün zamanı yokmuş 

Tıpkı adresinin olmadığı gibi

Zamansız ölümlerle kim sorgularki günü

Uzak ülkelere terk edilmişse ölüm

Ağlamak bize mi düşer, 

Yürek yarası kanarda kim görür kanadığını

Gün karanlıktı ama

Kaynak elektrodundan çıkan ışıkla aydınlanırdı

Heryer 

Oysa günü aydınlatmaktan öteydi herşey

Uzaklarda türkü söylermiydin Abi

Sesin hiç gelmedi buralara

Rüyalarda seslendinde kimse duymadı sesini

Kim düşünürdü seni kendi yalnızlığında

Sen yalnızlığınla İskenderun’lar da 

Çağrı bırakırken telefonlarımıza 

Nasıl düşünürdük kü senin bizi özlediğini

Nasıl düşünemedik bizi düşündüğünü

Hani dostların nerede Abi

Sevgili kardeşlerin, annen

Ve çocukların

Bak şimdi hepsi ağlıyorlar

Ağlamak ne fayda 

Ölüm kapıyı çaldıktan sonra

Ölüm

Ölüm sen nereden gelirsin

Böyle sessiz ve derinden

Kim görür seni gelirken

Neden sinsi sinsidir gelişlerin

Bak yüreğim dağlanıyor 

Kaynak makinesinin ateşiyle

Ateş günü aydınlatıyor

Gün seni alıp götürüyor Abi

Düşünemezdim ölümünü

Düşünemedim ölümünün acısını 

Eyyy hala oğlu Hamza 

Bırakıp gitmek varmıydı 

Ekmek için İskenderun’lara

Oysa bütün İskenderun

İstanbul’daydı 

Sen meyan kökü şerbeti içmişmiydin

Yalnızlığına ortak oldumu, tatlımıydı

Acıların hafifledi mi 

Miden de ki yaraların kurudu mu? 

Abi

Mezarında bile yalnızdın 

Seni öylece bırakıp gittiler susuz topraklara kaldın

Su istedin Annen’den oysa annen bile yoktu yanında

Duyuramadım sesini onlara 

Ya o sis bulutları arkasından gelen 

Kızıla bürünmüş ışıklar

Senmiydin o yangınları çıkaran gökyüzünde

Yüzlerce kilometre uzaklara 

nasıl taşıdın ateş yüklü ölüm arabasını

Nasıl kanattın geceyi

Ve gece yüklü günleri

Özlemlerin yokmuydu Abi

Düşlerin, sevgilerin, yarınlara ait umutların

Korkuların yok muydu 

Anlat bana ben dinlerim seni

Sesini duyabiliyorum 

Hıçkırıklarını da

Neden derinlere gömdün 

Neden direnmedin yaşama

Böyle salıp gitmek varmıydı 

Hani direnmek gerekiyordu

Hani hakkını söke söke alırdın

Neden teslim oldun ölüme

Neden boşverdin kendini

Bilmezmiydin vücüdunu saran örümcek ağını

Acı kimin adresiydi

Ölüm kimin adresiydi

Gelip buldu seni

Ölümün adresi yok Abi

Tıpkı zamanı olmadığı gibi

Acının da adresi yok 

Acınında....

...

..

.

Ölüm üşüyor kollarımda 

morga kapatılmışım 

bıçaklar altında 

kimse görmedi ağladığımı

oysa gözlerimi kapadığımda 

acıyı da gömmüştüm yüreğime

bu yüzden gözlerimden yaş gelmedi

bu yüzden soğuktu bedenim

bu yüzden kanamadım

göğsümü açtıklarında bu yüzden 

kalbim ses vermedi 

oysa ben onu da gömmüştüm

yalnızlığıma........', 'Hamza Abi''me... Ölümün zamanı yokmuş  Tıpkı adresinin olmadığı gibi Zamansız ölümlerle kim sorgularki günü Uzak ülkelere terk edilmişse ölüm...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":94,"source_url":"https://www.antoloji.com/olum-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tual', 'tual-mehmet-tombuloglu-jstvv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tenha ışık; yine seçemedim rengini uzağın

yine bir tutku usul usul belirdi, incelmiş sözle

giyinip bir rüzgarın şeffaf kanatlarını

önümde uzanan denizi uzaklara fısıldayarak

bakıp susmakta ustayım sanırdım

hiç usanmadan ırak yüzüne o puslu akşamın

köşe başında bir sokak lambasıydım bunun için belki biraz da

ucuza kapatmış gibi gecenin bir yarısını

kendimden belli belirsiz gölgelerle uzaklaşarak

ne suskun mavisi vardı o gölgeli denizin

anlık kabarışlarla dalgalar, duman duman

sisler arasında kalmış ada gibi, varla yok arası

koyları, pek vakitsiz iklimlere bölünmüş liman...

tualdeki en son rengi bıraktım orda ben! 

bu ünlemle şiirden çıkmak olmaz ama

vakitli vakitsiz gömülüp aksine eski zamanların

bir anlam çıkardım o sımsıcak gülüşünden

imkansız bir sevdaya eğildim yine elimde olmadan...', 'Tenha ışık; yine seçemedim rengini uzağın yine bir tutku usul usul belirdi, incelmiş sözle giyinip bir rüzgarın şeffaf kanatlarını önümde uz...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tombuloğlu']::text[], 8.5, '{"poet":"Mehmet Tombuloğlu","poet_slug":"mehmet-tombuloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/tual-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzin''deyiz Atam', 'i-zin-deyiz-atam-i-brahim-bayraktar-oy1ry', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Memur olsa müstafi sayarlardı, 

Asker olsa kapı önüne koyarlardı, 

Vatandaş olsa çoktan kovarlardı, 

“İzin”dekiler dönmüyor Atam.

Vatan hala bıraktığın yerde sayıyor, 

En güvendiklerin bile altını oyuyor, 

Bu vatanda hala ne açlar doyuyor, 

“İzin”dekiler boş durmuyor Atam.', 'Memur olsa müstafi sayarlardı,  Asker olsa kapı önüne koyarlardı,  Vatandaş olsa çoktan kovarlardı,  “İzin”dekiler dönmüyor Atam. Vatan hala...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/izin-deyiz-atam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tablodaki Masumiyet', 'tablodaki-masumiyet-baris-yavuz-iengd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir tabloya bakiyorum, 

yillar gecmis aradan..

kucuk bir kiz

saclari kizil mi kizil

gozleri magrur mu magrur

saclari ipek mi ipek.

O, Mahsun efendinin torunu, 

ne de masum bir durustur bu boyle

o kucuk eller

o kucuk dudaklar

o mini mini gozler, 

kaybettirir insana yolunu.

O, Ihsan efendinin kizi, 

hani mahsumuyetin, 

hani safligin, 

hani mutlulugun, 

resmi istense

gosterirsin iste bu miz mizi. 

Bir tabloya bakiyorum, 

yillar gecmis aradan..

mini mini kiz 

simdi olmus bir yildiz. 

bogaz koprusunun iki yani gibi ciplak 

saclari al mi al, teni ak mi ak

dolanip ince beline olurdun ya kusak

hani olsaydi ornegi tarihimizde

bir devlete oldugumuz usak		

			

simdi ararim o tablonun ressamini, 

niye olacak, hesap sormak icin, 

resimlerdeki masumiyetle

ne hakki var bizi kandirmaya 

ne de agatmaya.

bak bu arada yok mu benim resmim anne, 

merakta etmedi degilim hani

ben nasil gorunurmusum masumken.

diyorum ki vakitte cok gec sayilamz hani, 

bulunca su meshur ressami

cizitti verelim kendimizi.

(18/06/2003)', 'Bir tabloya bakiyorum,  yillar gecmis aradan.. kucuk bir kiz saclari kizil mi kizil gozleri magrur mu magrur saclari ipek mi ipek. O, Mahsun...', ARRAY['Türk Edebiyatı','Şiir','Barış Yavuz']::text[], 8.5, '{"poet":"Barış Yavuz","poet_slug":"baris-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/tablodaki-masumiyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasat', 'hasat-mehmet-tombuloglu-axkiz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüklü bir taş gibi kuyusuna düştü 

içimdeki ormanı tutuşturan bir avuç anı

karanlık suyunu döktüğü yerde gecenin

tasası yokmuş dünün, bilemedim

şahittir dudağımda çatlağını hissettiğim güz

yalan yanlış ömrümde zehrine alıştığım tütünü

son kez kılavuz ettiğim kendime

zaten ilk hasadı da bu oldu, keşkelerle bilenmiş ömrümün

isteseydin, bakışımı suya eğdirmezdim

bir çiçeğin ürkek dalgınlığıyla titrerken alnım

lüksüne aldandığım bunca yağma içinde

kimbilir hangi yanılgının diyeti

yıllarca gözüm kapalı dinlediğim; içten içe

o hep mührünü göğsümde taşıdığım avuntum

yaklaştıkça uzun akan ırmağın hevesine

anladım; gidendim, bir uzak denize eklenmek üzere

büküp solmuş bir gülün dirençsiz dalını

duyamadığım bir sesin uzak hayalinde

artık yok sayılmış arzulardan kalma yabancılıkla

bilmem hangi ölgün zaman çarpar artık yüreğimde...', 'Yüklü bir taş gibi kuyusuna düştü  içimdeki ormanı tutuşturan bir avuç anı karanlık suyunu döktüğü yerde gecenin tasası yokmuş dünün, bileme...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tombuloğlu']::text[], 8.5, '{"poet":"Mehmet Tombuloğlu","poet_slug":"mehmet-tombuloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hasat-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akliman Zamanları 3', 'akliman-zamanlari-3-zeki-ergin-dwx15', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'güneş tüm sevecenliğiyle

okşarken tenimizi

eserken güzel ege rüzgarı

nedir içimizi ürperten

gün düşerken bababurnunda suya

renkler okşar bu kez 

el ele çıkarken sevdalılar 

Çağkent yokuşunu

işte kayıklar dönüyor kısmetleriyle

kararırken hava 

sofralardadır rakıya eş

ikinci baharlar yaşanıyordur 

belki de bir yerlerde 

kumsalda harlanan ateş yüreğimizdedir

sevda şarkılarına eş

_babakale may03

_sevgiliye isyan yt:haz04', 'güneş tüm sevecenliğiyle okşarken tenimizi eserken güzel ege rüzgarı nedir içimizi ürperten gün düşerken bababurnunda suya renkler okşar bu ...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/akliman-zamanlari-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzünç, Sevgilim ya da Nane Otları', 'uzunc-sevgilim-ya-da-nane-otlari-lale-muldur-aoj25', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gençken renkli bir cepken sevgilim

çift bıçaklı bir sevinç

unuttum diye bir şarkı

gençken renkli bir cepken sevgilim

önüne çıkan her ata binme

doğudan gelen kimsesiz tekne

ona hüzün demeyi artık öğrendin

ya da kuzeyden gelen çift bıçaklı sevinç

karıştırma daha fazla bu otları

bak öğle güneşi

şapkanı indir

karıştırma sevgi
..........
..........', 'gençken renkli bir cepken sevgilim çift bıçaklı bir sevinç unuttum diye bir şarkı gençken renkli bir cepken sevgilim önüne çıkan her ata bin...', ARRAY['Türk Edebiyatı','Şiir','Lale Müldür']::text[], 8.5, '{"poet":"Lale Müldür","poet_slug":"lale-muldur","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/uzunc-sevgilim-ya-da-nane-otlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuğunun Ölümü', 'kugunun-olumu-naime-erlacin-ju6yo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'parmak uçlarında haykırır 

kuğunun ölümsüz dansı

ezeli tercihi Prens’in

kadınla kuğu arasında

farkı yok

birinin ötekinden

sonu yok tükenmenin

derinden seslenen

aşkın isyanıdır yalnızca

örselenmese aşk

tasmalar takılmasa keşke

sığ sulardan kurtulduğunda

tutsaklıkta boğulur aşk 

ve korkuda

Odile 

ya da Odette 

ne fark eder kuğu ölürse

inkara uğrayan kişi değil

kişiler arasındaki bağ

üzülme ey aşk! 

ayrık otu gibisin

her zaman 

yaşanacak bir toprak bulunur sana...

(25 Haziran 2003)', 'parmak uçlarında haykırır  kuğunun ölümsüz dansı ezeli tercihi Prens’in kadınla kuğu arasında farkı yok birinin ötekinden sonu yok tükenmeni...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kugunun-olumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Çiçektozu Sen ve Korno', 'sari-cicektozu-sen-ve-korno-lale-muldur-x3v5f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'papatya esansısın sen ve nefti

yaprakları yalnızca

ve sepalleri ve saçların

ki içinde ritmik bir hamparsun

limonciyan notası duyulurdu

floransalı bir ressam ve

ışık hızıyla gelirdin ki

ben derhal

turunçgi
..........
..........', 'papatya esansısın sen ve nefti yaprakları yalnızca ve sepalleri ve saçların ki içinde ritmik bir hamparsun limonciyan notası duyulurdu flora...', ARRAY['Türk Edebiyatı','Şiir','Lale Müldür']::text[], 8.5, '{"poet":"Lale Müldür","poet_slug":"lale-muldur","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sari-cicektozu-sen-ve-korno-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarartı', 'sararti-lale-muldur-vqspk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sasal siyah inci

sar ma şık

yana eğik ağaçlar

neredeyse birbirimize

yabancıyız artık

burası hep

sarı yaz

dışarda

hep

kasım

patlar

hep bir sarı

gagalı yelkovan

böyle kafamın içinde

limonsu safran

sarı ekran amino asit

bir ağaca gerisin

geriye sonbahar

siluetiyle

giren bir

kız

RNA

mesajcısı

yunusların

kurtardığı

ha
..........
..........', 'sasal siyah inci sar ma şık yana eğik ağaçlar neredeyse birbirimize yabancıyız artık burası hep sarı yaz dışarda hep kasım patlar hep bir sa...', ARRAY['Türk Edebiyatı','Şiir','Lale Müldür']::text[], 8.5, '{"poet":"Lale Müldür","poet_slug":"lale-muldur","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sararti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim, sevdim, sevdim be şenay....', 'sevdim-sevdim-sevdim-be-senay-haci-ozturk-i8bc2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Toprak  dün  akşam  dedimya  sana

Bir  kadeh sana  doldurdum bir kadeh  bana

Bir  senden  içtim, birde kendimden, 

İçtim,  içtim, içtim içtim,  be  şenay........

Solmasın   yüzünden o  gülücükler, 

Gelecek  günler  senden  neleri bekler, 

Sevdiklerin  seninle  olsun  beraber, 

Ömrün  uzun olsun  yaşa, yaşa yaşa, be  şenay......

Bildiğim  kadar  mutluluk  seninde hakkın, 

Yaradan  nazardan seni  aman  saklasın, 

Mutluluk  uzak değil  yakın mı  yakın, 

O  senin  hakkın, hakkın hakkın be  şenay.......

Gurbette  sen  oldun  derdimin  ilacı, 

Seveni  her  zaman  yaptım  baştacı, 

Şu  satırları  yazan  garibim izmirli hacı, 

Gerçekte olmasa sevdim, sevdim  sevdim  be  şenay.

Hacı  Öztürk                            22/06/2003

                                                  LİBYA

KAYDEDEN                          Hacı  Öztürk', 'Toprak  dün  akşam  dedimya  sana Bir  kadeh sana  doldurdum bir kadeh  bana Bir  senden  içtim, birde kendimden,  İçtim,  içtim, içtim içti...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevdim-sevdim-sevdim-be-senay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derim anlatamam sevdamı...', 'derim-anlatamam-sevdami-haci-ozturk-njc5x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hasretim  dağlara  taşlara  degil, 

Hasretim  sanadır  bilesin  sevdalım.

Bu benim ilk  günkü  ölmem  değil, 

Yinede yoluna  ölürüm  sevdalım.

Ayrılık diye  bir  yasa  varmıdır, , , ? 

Seven  bu  yüreğe  dünya  darmıdır, , 

Sevgi   hakikatte  kalpte     harmıdır, , ? 

Yanarda, yanar  dururum sevdaılım.

Uzakta  arama  sevgi  senin  yanında, 

Gözünü  aç  bir  bak  senin  elinde, 

Çare  arama   çare   sevda  yelinde, 

Eserde,  eser  dururum  sevdalım.

“Hacım,  niye  çattın acep  kaşını, 

Sevmeyen  bilmez  gönül  kışını, 

Boş  sevgiye  akıtma değmez  gözyaşını, 

Derimde,  derim  anlatamam    sevdalım.

Hacı  Öztürk                         24/06/2003

                                              LİBYA

KAYDEDEN                         Hacı  Öztürk', 'Hasretim  dağlara  taşlara  degil,  Hasretim  sanadır  bilesin  sevdalım. Bu benim ilk  günkü  ölmem  değil,  Yinede yoluna  ölürüm  sevdalı...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/derim-anlatamam-sevdami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O yeter bana....', 'o-yeter-bana-haci-ozturk-hk7ws', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel  beni  bırakma  çöllerde, 

Burada  sıcaklık  altmış  derece, 

Yanar, yanar  dururum  sessizce, 

Bir  gel  desen  o  yeter  bana.....

Çöldeyim  susuz  yanarım, 

Gün geçmezki  adını  anarım, 

Elbet  hasreti  birgün  satarım, 

Bir  gel  desen  o  yeter  bana....

Çöldeyim  sevdam   seni  ararım, 

Nereden  bir ses gelse sana yorarım, 

İnan  vallahi AKDENİZ’İ  yararım, 

Bir  gel  desen  o  yeter  bana....

Çöldeyim  her gece  serap görürüm, 

Beni  sevdiğini  yemin olsun bilirim, 

Ölürüm  sevdam bu sevdaya  ölürüm, 

Bir  gel  desen  ''hacı''ya  o  yeter.

Hacı  Öztürk                     24/06/2003

                                           LİBYA

KAYDEDEN                    Hacı   Öztürk', 'Gel  beni  bırakma  çöllerde,  Burada  sıcaklık  altmış  derece,  Yanar, yanar  dururum  sessizce,  Bir  gel  desen  o  yeter  bana..... Çöl...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/o-yeter-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrağı Özgürlüğün', 'bayragi-ozgurlugun-bir-mim-kemal-ertugrul-8baf9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '____________________-Spartaküs 

_____________________ve isimsiz 

_____________________yiğitlerine...- 

_____________________(Bayrak açmıştılar, bayrağı oldular

_____________________ikibin yıldır özgürlüğün................)

Marcius Licinus Crassus; 

Baş komutan edasında, 

Yürüyordu vakur ve emin adımlarla 

____________ordusunun başında.

Göğe doğru kaldırarak demirden kalpağını

Ve halka doğru uzatarak ağır ağır 

____________kalkanıyla mızrağını 

‘’SELAM SANA! 

________SELAM.........’’ diye bağırdı 

‘’SELAM, ÜÇ KIT’ANIN EFENDİSİ ROMA’ ya! ’’

Her sefer dönüşü, 

Gül suyuyla yıkanırdı Romanın sokakları.

Taş üstünde taş, 

Baş üstünde baş kalmaz, 

Zafer çığlıkları yükselir 

Ve nal seslerine karışırdı günlerce 

_____insanların çılgınca haykırışları..

Esirler bitkin ve şaşkın, 

Halk çılgın, Vezüv kızgın olurdu

____________böyle günlerde.

Öfkeyle çarpar kocaman kalbi, 

Dumanlar savrulur

Ve lavlar fışkırırdı doruklarından

O; 

Trak ‘ lı bir çoban 

Say ki bulgar, belki makedon.

Bir sefer dönüşü, 

Bir fidan gibi sökülüp köküyle toprağından 

Esir alınıp köle yapılmıştı Romalılar ‘ca

________daha İsa’nın anası bile doğrulmadan.

Yüzbinlerden biriyken O, 

Taş ocaklarından orduya kaydırılmıştı terfisi

Ve asker kaçaklığına yükselmişti sonunda rütbesi.

Bir kaplan gibi ökseye kıstırılıp 

Ve bir vahşi hayvan gibi zincire vurulup ayaklarından, 

Eski bir eşya gibi satılmıştı Lentulus Batiatus’a

____________________Roma sokaklarından......

Bir dövüşçü gibi yetiştirilecek Gladyo Okulu’ndan 

Ve bir hayvan gibi ölümüne dövüştürülecekti.......

Ve yenildiğinde; 

Parmak uçlarında imparatorun, 

Bir hayvan gibi, 

Korkunç bir ölümü bekleyecekti.......

Bir gün yenilgiyi de görecekti yenenler 

Ve yenmeyi öğreneceklerdi elbet

Öfke ve zulmün zımparasında bilenenler....

YENİLDİ arenada

...................TRAK’LI ÇOBAN! 

İmparatorun havaya kalkan parmağı değil, 

Galibin insan yüreğiydi bağışlayan...........

Karşı çıktığından geleneklere, 

Mağlup sayıldı bu yolda galip

Ve paramparça edildi kana susamış soyluların

____________________hayvanca haykırışlarıyla.

Bu kadar ucuzdu hayat

Ve bukadar pahalı..... heyhat! 

..................................................

Galibin kanı bile kurumadan 

Kaçtılar 70 kadar arkadaşıyla

Lentulus Batiatus’un okulundan..........

‘’ YOKTU ZİNCİRLERİNDEN BAŞKA

_________KAYBEDECEK ŞEYLERİ’’

AMA; 

ORTAYA KOYMAKTI KELLEYİ

________ÖZGÜRLÜĞÜN BEDELİ.

DEĞİL YALNIZCA KELLEYİ, 

YÜREKLERİNİ KOYDULAR AVUÇLARINDA 

__KURTULUŞTAN SAYARAK BU UĞURDA ÖLMEYİ.....

Onlar; 

Esir, köylü ve köleydiler

Birken 70,70 ken 70 kere bindiler

Ve hatta 100 bindiler.

Süt içerek koyunların memelerinden 

_________efendisiz yaşamayı öğrendiler.

Karınlarını doyurdular sürülerin etlerinden 

Ve elbise ve ayakkabı diktiler derilerinden

Vakit tamam 

Ötesi yalandı

Boru sesi, nal sesi 

________ve at kişnemeleriyle 

Geliyordu Marcius Licinus Crassus

Kralca öfkesi ve 

______üç kıtanın yedi sülalesiyle

Onlarsa ard arda, 

Yan yana can cana dizilmişler, 

Bırakınız düşmana, 

________rüzgara bile geçit vermemişlerdi.

Bir kalkan gibi siper edip göğüslerini 

Ve bir balyoz gibi sallayarak avuçlarında

__________________düşmana yüreklerini

Yendiler iki kere

Üç kıt’anın yenilmez denilen efendilerini.

Bir elin nesi vardı

Ve iki elin de sesi 

Kesilmeseydi zaferden önce Crixus’un nefesi, 

Söküp atacaklardı yeryüzünden 

_____kölelik denilen prangalı illeti.

Hele; 

Görmeselerdi Venedikli gemici tacirlerden

______________________diz boyu ihaneti.............

19.06.1995 / 22:00 EV

Asker ol(un)  madan, 

Komutan ol(un)  maz...

WWW.MiMSANAT.COM''dan alınmıştır.....', '____________________-Spartaküs  _____________________ve isimsiz  _____________________yiğitlerine...-  _____________________(Bayrak açmıştıl...', ARRAY['Türk Edebiyatı','Şiir','Bir Mim Kemal Ertuğrul']::text[], 8.5, '{"poet":"Bir Mim Kemal Ertuğrul","poet_slug":"bir-mim-kemal-ertugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":109,"source_url":"https://www.antoloji.com/bayragi-ozgurlugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle bir yerdeyimki..!', 'oyle-bir-yerdeyimki-haci-ozturk-jkb6o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle bir yerdedeyim ki   dardayım, 

Öyle  bir  yerdeyim ki   zordayım, 

Öyle  bir  yerdeyim  ki   hardayım, 

Söyletmen  beni, söyletmen  beni.

Öyle  bir  yerdeyim  ki  çaresiz, 

Öyle  bir  yerdeyim  ki  kadersiz, 

Öyle  bir  yerdeyim  ki  sessizmi, sessiz, 

Söyletmen  beni, kahretmen  beni.

Öyle  bir  yerdeyim  ki  düşteyim, 

Öyle  bir  yerdeyim  ki  sesteyim, 

Öyle  bir  yerdeyim  ki   hastayım, 

Söyletmen  beni, delirtmen  beni.

Öyle  bir  yerdeyim ki  isyan  yok, 

Öyle  bir  yerdeyim  ki  ziyan  çok, 

Öyle  bir  yerdeyim  ki her anı  şok, 

Söyletmen  beni, darıltman  beni.

Öyle  bir  yerdeyim ki  kan  kusturan, 

Öyle  bir  yerdeyim  ki hatip olsan  susturan, 

Öyle  bir  yerdeyim  ki dostu, dosta küstüren, 

Söyletmen  beni, delirtmen   beni.

Öyle  bir  yerdeyim  ki herkesin işi menfaat çıkar, 

Öyle  bir  yerdeyim ki dışı  seni, içi beni  yakar, 

Öyle  bir  yerdeyim ki deyyuslar canımı  sıkar, 

Söyletmen   beni, delirtmen   beni.

Her  nereye  baksam  belirsizlik  var, 

Her  neye  sarılsam  ümitsizlik  var, 

Bel  bağladıklarımda  şerefsizlik  var, 

''Hacım, daha ne desin söyletmen  beni.

Hacı  Öztürk                      21/06/2003

                                            LİBYA

KAYDEDEN                     Hacı   Öztürk', 'Öyle bir yerdedeyim ki   dardayım,  Öyle  bir  yerdeyim ki   zordayım,  Öyle  bir  yerdeyim  ki   hardayım,  Söyletmen  beni, söyletmen  ben...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/oyle-bir-yerdeyimki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Bana', 'soyle-bana-hasan-ali-gurleyen-yjn94', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Söyle bana ey güzel

Seni benim kadar 

Seven oldu mu hiç? 

Deryalar kada mı sevdiler seni

Dünyalar kadar mı sevdiler seni

Söyle bana ey güzel

Seni benim kadar

Seven oldu mu hiç

Hava su kadar 

Seven oldu mu seni

Her an içinde hisseden oldu mu

Kimse sevemez seni

Benim sevdiğim kadar

Seven olsaydı eğer

O da burada olurdu

Bu uçurumun kenarında

Tek başına dururdu.

Gidiyorum artık ben 

Bir adımda sonsuzluğa

Ne zaman seversen beni

İşte o zaman dönerim geri

Sen hiç hayal kurdun mu

Söyle bana ey güzel

Yeşilin mavinin grinin olduğu bir yer

Yem yeşil ormanın ortasında

Mas mavi bir dere

Kuşlar cıvıl cıvıl ötüyor

Çiçekler mis kokular yayıyor

Deniz dalgarıyla kayaları okşuyor

Gür ağaçlı orman bu güzelliği izliyor

Birden bir çiçek takılıyor gözüme

Her renk var üzerinde tam ortası simsiyah

Kin var kalbinde nefret var öfke var

Büyüyor siyahlığı her yeri kaplıyor

Cıvıl cıvıl kuşlar susuyor

Çiçeklerin mis kokusu 

Ölüm kokusuna bürünüyor

Boşluktayım düşüyorum

Bir yerlere tutunmak istiyorum

Rastgele sağa sola sallıyorum elimi

Bir şey geliyor elime bakıyorum

Bir çiçek olmalı

Her renk var üzerinde 

Bir tek siyah yok kin yok nefret yok

Dünyam kendine geliyor

Karanlık kalkıyor yavaş yavaş

Yem yeşil ormanın ortasında

Mas mavi bir dere

Kuşlar cıvıl cıvıl ötüyor

Çiçekler mis kokular yayıyor

Deniz dalgarıyla kayaları okşuyor

Gür ağaçlı orman bu güzelliği izliyor

Hayat çiçeği soluyor

Canını bir cana verdi

Kendini bir cana feda etti

Kim demiş önce can sonra canan diye

Canan candan önce gelmedikçe

Bir can kalır dünyada

Bir tek insan yalnız kalır dünyada', 'Söyle bana ey güzel Seni benim kadar  Seven oldu mu hiç?  Deryalar kada mı sevdiler seni Dünyalar kadar mı sevdiler seni Söyle bana ey güzel...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ali Gürleyen']::text[], 8.5, '{"poet":"Hasan Ali Gürleyen","poet_slug":"hasan-ali-gurleyen","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/soyle-bana-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygu Adamları', 'duygu-adamlari-bekir-mutlu-gokcesu-7vgz0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güzellikler insanları çeker.

Farkında olmadan

bir tebessümü hisseder

uzaklarda biri.

Sevgi dolu bir kalbe

koşmak ister

duygu adamları.', 'Güzellikler insanları çeker. Farkında olmadan bir tebessümü hisseder uzaklarda biri. Sevgi dolu bir kalbe koşmak ister duygu adamları....', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/duygu-adamlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arıyorum', 'ariyorum-oguzkan-bolukbasi-dfejj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yokolmuş kentleri arıyorum, sokaklarında bir çocukluk yitirdiğim, 

saklanmış sanki anıların hüzünlü sayfalarına, gülen bakışlarımı 

görünmeden sana fırlattığım, bayram gecelerinde yeni giysilerim ve 

sevincimle yanyana yattığım 

Yokolmuş kentleri arıyorum 

Dualarımla iyilikler yaratan Tanrı''ya taptığım 

Kirlenmemiş ruhum hangi hengamede kayboldu, hangi pisliğe bulandı 

unuttum bile, hangi sabah yüreğim uyanmadı sevgiyle 

Yokolmuş kentleri arıyorum 

Sokaklarında gençliğimi sattığım 

Geçmiş zaman pencerelerinde perdeler sıkısıkıya kapalı, ışıkların 

sızacak delikleri kalmamış, ümit gözlerimiz alabildiğine açık, 

zihnimizde yarıkaçık bir adam seslenir durur, gönlümüzde sabırlı bir 

hicran oturur 

Kurumuş nehirlerde balık tutar deliliklerimiz, birer birer yok olurken 

sevgili sevdiklerimiz 

Yokolmuş kentleri arıyorum 

Ayrılırken gönlümü kanattığım', 'Yokolmuş kentleri arıyorum, sokaklarında bir çocukluk yitirdiğim,  saklanmış sanki anıların hüzünlü sayfalarına, gülen bakışlarımı  görünmed...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ariyorum-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyanın', 'uyanin-murat-demir-pqf9c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çivimizi çıkarmışlar çakan yok

Ağlasakta halimize bakan yok

Meşaleyi adam gibi tutan yok

Son pişmanlık fayda etmaz uyanın

Sabır taşı çatlamaya yaklaştı

Yurdumuzda şerefsizler kartlaştı

Kör düğümle suçlu, suçsuz bantlaştı

Son pişmanlık fayda etmez uyanın

Felaketin habercisi bellidir

Bu densizler ithal değil yerlidir

Çoğu hırsız olmuş, uzun ellidir

Son pişmanlık fayda etmez uyanın

Pislikler ağ gibi sarmış her yeri

Sırtları tüğlenmiş, kürklü inleri

İslah edemezsek bu herifleri

Son pişmanlık fayda etmez uyanın

Etkililer, yetkililer birleşsin

Yeter artık, yurda düzen yerleşsin

Lider yoksa gariban halk neylesin

Son pişmanlık fayda etmez uyanın

Kabadayı, baba, olmuş çakallar

Pisliklerden emir almış bakanlar

Hür vicdanla meydanlara çıkanlar

Son pişmanlık fayda etmez uyanın', 'Çivimizi çıkarmışlar çakan yok Ağlasakta halimize bakan yok Meşaleyi adam gibi tutan yok Son pişmanlık fayda etmaz uyanın Sabır taşı çatlama...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/uyanin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünürken', 'seni-dusunurken-hakki-hakan-kaya-dbpf5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aklım başka, bedenim başka yerde, 

Mekansızım seni düşünürken.

El sallarım ardından tasaya, derde, 

Gamsızım seni düşünürken.

Açılır gönlümün kapısı sonsuz bir hana, 

Vız gelir kurşunlar kılınçlar bana, 

Aklımı sevdaya yüreğimi sana, 

Salmışım seni düşünürken.

Gözlerim dalmış ufka, bulutlara, 

Sesin ilham vermiş şarkılara, tınılara, 

Ansızın siyah beyaz anılara, 

Dalmışım seni düşünürken.

Şimdi umutsuzca hatırlasamda maziyi, 

Zihnimde hala busesi gülücüğü, 

Son paramla aldığım o yüzüğü, 

Takmışım seni düşünürken.

Kara kışlar dönmez bahara, 

Buhranlı geceler çıkmaz sabaha, 

Sensiz son bir sigara daha, 

Yakmışım seni düşünürken.', 'Aklım başka, bedenim başka yerde,  Mekansızım seni düşünürken. El sallarım ardından tasaya, derde,  Gamsızım seni düşünürken. Açılır gönlümü...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-dusunurken-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Megaloben', 'megaloben-oguzkan-bolukbasi-r5irp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sende izimi bırakmak istiyorum

zaman zaman işmar edip işaret veriyorum

bilmezden geliyorsun

gülüyorum

içinde ne taşıdığını biliyorum

bir dolu ben', 'sende izimi bırakmak istiyorum zaman zaman işmar edip işaret veriyorum bilmezden geliyorsun gülüyorum içinde ne taşıdığını biliyorum bir dol...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/megaloben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Misafir', 'misafir-murat-demir-kekt5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yanıp kavrulsakta, susuz kalsakta

Varla, variyetle, dolup taşsakta

Butün kainata, kral olsakta

Misafiriz bu dünyada misafir

Her yanımız dolsa, elmasla safir

Misafiriz bu dünyada misafir

Doğru yada yanlış, müslüman, kafir

Misafiriz bu dünyada misafir

Konak sahibidir, sonunda toprak

Can değil, ağaçta olsakta yaprak

Derya, deniz gibi, sel olup taşsak

Misafiriz bu dünyada misafir

Murat der bozulur, bir gün düzenin

Yanına kalırmı, seni ezenin

Fen’i yetecekmi, ayda gezenin

Misafiriz bu dünyada misafir', 'Yanıp kavrulsakta, susuz kalsakta Varla, variyetle, dolup taşsakta Butün kainata, kral olsakta Misafiriz bu dünyada misafir Her yanımız dols...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/misafir-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buzul', 'buzul-filiz-kurun-vey59', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'soğuktu kuru ayaz

gözyaşım buza dönüşüyordu 

içim buzula...', 'soğuktu kuru ayaz gözyaşım buza dönüşüyordu  içim buzula......', ARRAY['Türk Edebiyatı','Şiir','Filiz Kurun']::text[], 8.5, '{"poet":"Filiz Kurun","poet_slug":"filiz-kurun","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/buzul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Yüzün Yeter Bana', 'ay-yuzun-yeter-bana-sair-peykani-ye7ig', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalbinden derinlerden bir nur seli ver bana

O pembe dudaklardan bir teselli ver bana

İstemem muhabbetler el ele dolaşmalar

Sadece samimi bir tebessümün der bana

O siyahî gözlerin gece kadar derinden

Karanlıkta yıldızlar, yakamoz göster bana

Ellerin bir menekşe dokununca solarmış

Dokunamam ama sen menekşeler ser bana

Yar dalından bakarken tüm bülbüller şakırmış

Eğer biz konuşursak küssün güller bana

Gül yaprağın göstermez içine kapanırmış

Bülbül kaldı soluksuz rengini göster bana

Nice bülbül sevdası dağlara uzanırmış

Yâr bize dağ kalmadı ay yüzün yeter bana

Sanki gözler süzgünken daha derin bakarmış

Bakışlar bir yüreği bu kadar mı yakarmış

Sevgi yardan ayrıyken daha derin akarmış

Bari eline değmiş bir sinan gönder bana', 'Kalbinden derinlerden bir nur seli ver bana O pembe dudaklardan bir teselli ver bana İstemem muhabbetler el ele dolaşmalar Sadece samimi bir...', ARRAY['Türk Edebiyatı','Şiir','Şair Peykani']::text[], 8.5, '{"poet":"Şair Peykani","poet_slug":"sair-peykani","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ay-yuzun-yeter-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cankuşum', 'cankusum-sair-peykani-wz78x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kara saçlarında bir an canmışım

Gözlerime dolamışım sarmışım

Bir karanlık yar zülfüne yanmışım

Gözlerimden süzülmüyor cankuşum

Duman duman tüter yarin gözleri

Kirpiklerle gizleniyor hisleri

Bir sızı var bende belki közleri

Bir bağ varki çözülmüyor cankuşum

Beyaz bir güvercin yanaklarında

Kaçar gider kaçamak bakışında

Hele ki bakışlar bir buluşunca

Deli kalbim durulmuyor cankuşum

Pembe dudakların nağmelerinde

Yazılır güller, laleler içinde

Kesilir can damarım yar sesinde

Yar sesinden geçilmiyor cankuşum

Yar gezinir edasıyla, nazıyla

Bülbül bakar “belki” diye sızıyla

Çalar aşkın şarkısını sazıyla

Göz yaşları seçilmiyor cankuşum', 'Kara saçlarında bir an canmışım Gözlerime dolamışım sarmışım Bir karanlık yar zülfüne yanmışım Gözlerimden süzülmüyor cankuşum Duman duman t...', ARRAY['Türk Edebiyatı','Şiir','Şair Peykani']::text[], 8.5, '{"poet":"Şair Peykani","poet_slug":"sair-peykani","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cankusum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arada', 'arada-behcet-necatigil-vznez', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her şey araya giriyor, aradan çıkıyor

Arada çocuklar doğuyor, büyüyor, yürüyor

Arada evler, evlenmeler, ölümler duruyor

Arada yaz kış bahar, dünya dönüyor', 'Her şey araya giriyor, aradan çıkıyor Arada çocuklar doğuyor, büyüyor, yürüyor Arada evler, evlenmeler, ölümler duruyor Arada yaz kış bahar,...', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 8.5, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/arada-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-muhammet-pekyilmaz-2bqnt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne doğduğum, 

Ne doyduğum yer, 

Benimle neredeysen, 

Memleketim orası.

Yoksun şimdi yanımda, 

Bana gurbet burası....

(16.08.2001)', 'Ne doğduğum,  Ne doyduğum yer,  Benimle neredeysen,  Memleketim orası. Yoksun şimdi yanımda,  Bana gurbet burası.... (16.08.2001)...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Pekyılmaz']::text[], 8.5, '{"poet":"Muhammet Pekyılmaz","poet_slug":"muhammet-pekyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gurbet-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı', 'kirmizi-cemal-ekren-7nvq0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her yer kırmızı; 

Sagım, solum, önüm, arkam

Kan çiçekleri.

Dudak kırmızı öpemem, 

Kızıl bir akşamda, Ay ışıgının altında masamız, 

Şarap kırmızı içemem.

Yıldızlar kırmızlarını giymiş göz kırpıyorlar

Utanırım bakamam.

Dudak kırmızı öpemem

Gülüm, 

ÖPEMEM', 'Her yer kırmızı;  Sagım, solum, önüm, arkam Kan çiçekleri. Dudak kırmızı öpemem,  Kızıl bir akşamda, Ay ışıgının altında masamız,  Şarap kır...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kirmizi-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Pınarı', 'gonul-pinari-i-brahim-bayraktar-olm98', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Arkadaş, bu muydu bizim kavlimiz? 

Ölene kadar destek idik biz bize, 

Hani hiç bitmeyecekti bizim sevgimiz, 

Bir gün olsun olmasak da biz bize.

Buğulu, güzel sesin çınlar özümde, 

Mest-i naz bakışın her an gözümde, 

Seni unutamam ne özümde ne sözümde, 

Bir gün olsun bakmasak da yüz yüze.

Selam söyle Paşa ile Valiye, 

Bir ilanla duyursunlar ahaliye, 

Ben seni seviyorum deliler gibi, 

Bir kez olsun bakmasak da göz göze.

Ey! Güzel, sen açmamış bir goncasın, 

Yanımda olmasan da, her an bendesin, 

İnan; hep benimlesin, hep gönlümdesin, 

Bir gün olsun olmasak da diz dize.

12.7.1999', 'Arkadaş, bu muydu bizim kavlimiz?  Ölene kadar destek idik biz bize,  Hani hiç bitmeyecekti bizim sevgimiz,  Bir gün olsun olmasak da biz bi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gonul-pinari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lodosta İstanbul''u dinle', 'lodosta-i-stanbul-u-dinle-i-rem-yitmen-ebfx1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Lodosta İstanbul''u dinle

Yanlızlığın gelir aklına

Perde perde örtmüşüz sevgileri

Tüter üstünde gri külleri

Sonra bir melodi dolanır diline

Bakarsınki gökyüzüne

Artık yıldızlar bile suskun

Ve yüreğinde bir kuş kanat açar

Bilinmeyen engin semalara

Lodosta İstanbul''u dinle

Gökyüzü gri bulut ve isli

Bir an nefes alamayacağını düşünürsün

Oysa çoktan öldürmüşsündür

İçindeki yaşam enerjisini

Hergün geçtiğin aynı yollar

Belki daima gördüğün aynı yüzler

Yaptığın her şey tek tip

Monotonluk canına tak etmiştir

Tek farklı olan hergün değişen tarifeler

Lodosta İstanbul''u dinle

Belki bir uçakta gece vakti

Üzerinden geçiyorsundur boğazın

Ayaklarının altında binlerce ışıltı

Bir elmas gibi yanıyordur bu şehir

Soruverirsin kendine 

Onca ihtişamına rağmen

Nedir sırrı yanlızlığının

Eğer bulabilirsen o saf mutluluğu

Çözülüverirsin derinlerden

Boncuk boncuk sevgileri

Dolayıverirsin tel tel saçlarına

Ve anlarsınki bir zaferdir yaşam

(1999)', 'Lodosta İstanbul''u dinle Yanlızlığın gelir aklına Perde perde örtmüşüz sevgileri Tüter üstünde gri külleri Sonra bir melodi dolanır diline B...', ARRAY['Türk Edebiyatı','Şiir','İrem Yitmen']::text[], 8.5, '{"poet":"İrem Yitmen","poet_slug":"i-rem-yitmen","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/lodosta-istanbul-u-dinle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleket Sevdası', 'memleket-sevdasi-hikmet-karakus-msmzf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreğim hep sevdaya düşer

                        gözlerim yola, 

Tüketiyorum sözcükleri birer birer

                     acıyla yoğura yoğura, 

Ve sana geldim

                 çok uzaklardan, 

İşte yüreğindeyim şimdi

                     memleketim

                     hasretim

                     sevdiceğim benim.

(Ank.1984)', 'Yüreğim hep sevdaya düşer                         gözlerim yola,  Tüketiyorum sözcükleri birer birer                      acıyla yoğura yoğu...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/memleket-sevdasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamaya Hasret', 'yasamaya-hasret-hikmet-karakus-3wcqj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Toprak damlarda büyüdük, 

Tahta sedirlerin üstünde

           soğuktan morarırdı dudaklarımız, 

Pencerelerin önünde seyrederdik

                               kardan adamı

                              taptaze yeşerirdi 

                              beyazlar arasında umutlarımız, 

Hep çamurlu yollarda yürüdük

                           yoğurduk yarınlarımızı

                           oyuncaklarımızda, 

Ellerimiz yüzümüz sert

                           dağlar gibi, 

İnsanca yaşamaya hasret

                          sefiller gibi, 

Şehirler hep sevdamızdı

                  pembe düşler içinde

                        yol görünürdü bize.

(İst.1979)', 'Toprak damlarda büyüdük,  Tahta sedirlerin üstünde            soğuktan morarırdı dudaklarımız,  Pencerelerin önünde seyrederdik             ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yasamaya-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terk Ediyorum Kendimi', 'terk-ediyorum-kendimi-melih-coskun-sd8zo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Terk ediyorum kendimi 

Aynalarda bırakıyorum üzgün yüzümü

Yollarda bırakıyorum yorgun ayaklarımı 

Dostun sıcak ellerinde bırakıyorum ellerimi 

Sizi değil 

En çok kendimi terk ediyorum

Bütün Temmuzlarını bu şehrin

Yağmurlardan sonra 

Uzun zamandır görmediğin 

Eski bir dost gibi 

Pencereme gülümseyen güneşini terk ediyorum 

Hasretin bitip başladığı yerde yanan cılız ışıklarını terk ediyorum

Ben en çok kendimi 

Terk ediyorum 

Senden de çok...

3 Mayıs 2003

01:05', 'Terk ediyorum kendimi  Aynalarda bırakıyorum üzgün yüzümü Yollarda bırakıyorum yorgun ayaklarımı  Dostun sıcak ellerinde bırakıyorum ellerim...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/terk-ediyorum-kendimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Uzaklardan Geldiler', 'cok-uzaklardan-geldiler-melih-coskun-sc1x2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok uzaklardan geldiler 

Ve siperler kazdılar 

Çiçeklerle donatmak istediğim ülkemin yollarına 

Varolmak düşüncesi 

Kemirirken günden güne beynimi

Var olduğunu sanan yoklardan saydılar bizi

Milyonlarca gözdük biz hiçbir şey görmeyen 

Ve milyonlarca beyindik 

Çaresizliğinden başka 

Hiçbir şeyi düşünemeyen 

Aşkı yok saydılar 

Yok saydılar ellerimizi

Yok saydılar yüzlerimizi

Yok saydılar senin için ağlayan gözlerimizi 

Bizi yok saydılar 

Oysa biz yazmıştık 

Resimleri bile sararmış 

Delikanlı bir serüvenin destanını 

Haritası acılarla ve gözyaşlarıyla çizilmiş 

Bir coğrafyanın feryadını 

Enkazlar altında kalmış 

Sürgünlere gitmiş 

Sevdalanmış

Aç ve açık kalmış

Savaşlarda ölmüş 

Öldürmüş 

Acılarla kurulmuş bir ülkenin hikayesidir bu... 

Öyle bir ülkenin hikayesini anlattık ki size 

Dağların zirvesi şahittir yalnız 

Ovaların düzlüğü şahittir

Gövdesi bir insanın bedeniyle kardeş olmuş 

Ormanlardan başka kimseler bilmez bu kederi 

Bir kurşun atımı mesafede 

Açlık ve tokluk arasındaki derin uçurumları

Sadece yediği ekmek kadar hür olabilen bir halkı 

Yamalı pantolonu 

Şekersiz çayı... 

Bilir sefaleti 

Açlığı bilir onlar 

Ama anlatamazlar 

Çünkü çoktan unutmuşlardır konuşmayı 

Uzun yıllar geçmiştir 

Kullanmayalı bir soru işaretini 

Kendilerini bildiklerinden beri kullanmamışlardır bir ünlemi 

Halbuki 

O soru işaretinde saklıdır kurtuluş 

Ve kullanmadıkları ünlemlerde saklı kalmıştır isyanları

   

Bu ebedi sürgüne mahkum oluşumuz 

Anlattığımız içindir 

Zulmün ardında saklandığı perdeleri 

Düşürmek istediğimizden 

Altında saklandığı bütün maskeleri 

Bitirmek için adına özgürlük 

Adına medeniyet dedikleri bütün esaretleri 

Eritmek için bütün kurşunları, 

Mayınlar yerine 

Çiçekler açsın diye 

Özgür topraklarımda...

2 Mayıs 2003

00:51', 'Çok uzaklardan geldiler  Ve siperler kazdılar  Çiçeklerle donatmak istediğim ülkemin yollarına  Varolmak düşüncesi  Kemirirken günden güne b...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/cok-uzaklardan-geldiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Olduğunu Sanan Yabancılar', 'dost-oldugunu-sanan-yabancilar-melih-coskun-ex6q3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dost olduğunuzu sanan 

Yabancılarsınız hepiniz 

Yalan arkadaşlık 

Dediğiniz ne varsa 

Uzak dağlar kadar 

Gölgeyle güneş kadar 

Yabancısınız birbirinize 

Çünkü siz kaldırmadınız 

Hiçbir zaman

Bir dostun cesedini sokak ortasından 

Ve sarmadınız kanayan bir yarayı 

Bembeyaz gömleklerinizle... 

Bir bardak suyu paylaşmadınız 

Susuzluğunuzda 

Ve yıllanmış bir şarabın dibinde sandığınız kurtuluş 

Unutulan arkadaşlıklar kadar uzaktı oysa

Yan yana olsanız da uzaksınız birbirinize

Arasına okyanuslar girmiş ülkeler kadar 

Dost olduğunu sanan 

Yabancılarsınız siz aslında 

Çünkü siz paylaşmadınız

Bir hücrenin rutubetli duvarlarını

Düşmediniz yola 

Birbirinizin ardı sıra 

Bozkırda yakılan cılız ateşin başında 

Sabahlamadınız 

Korunmaya çalışarak 

Etrafı saran kurt sürülerinden 

Yabancısınız hepiniz 

Kapatmadınız ellerinizle 

Dostun açık kalan gözkapaklarını

Asılmadınız beraber 

Bir şafak vakti 

Sorgusuzca...

6 Mayıs 2003

00:28', 'Dost olduğunuzu sanan  Yabancılarsınız hepiniz  Yalan arkadaşlık  Dediğiniz ne varsa  Uzak dağlar kadar  Gölgeyle güneş kadar  Yabancısınız ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/dost-oldugunu-sanan-yabancilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-mehmet-secer-no0sf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bırak artık ellerimi; 

Unutmaya başlayacağım

Dakikalar sonra seni.

Söndür sigaranı...

Boş kalan kadehimi, 

Gözlerimde solan resmini

Bir de kırık yüreğimi

Bıraktım avuçlarına 

              Gidiyorum.

Çıkardım lacivert gecemden

Semaya çaktığım gözlerini...

Şimdi yıldızlar özgür; 

Toprağa sardım saçlarını

Ve güneşimi yudum yudum içen

Akşam sarısı dudaklarını.

Artık mavilikler benim

Sana bıraktım karanlıklarımı

Aldanmışlığımı,  tutsaklığımı

Ve üç ayaklı kırık masamı...

Yarım kalan bu aşk masalını

Sayfa sayfa yırttım; 

                     Gidiyorum.', 'Bırak artık ellerimi;  Unutmaya başlayacağım Dakikalar sonra seni. Söndür sigaranı... Boş kalan kadehimi,  Gözlerimde solan resmini Bir de k...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Seçer']::text[], 8.5, '{"poet":"Mehmet Seçer","poet_slug":"mehmet-secer","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gidiyorum-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-mehmet-secer-ygo8y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu kaçıncı tren ki senden habersiz

Kayıp gitti ufuklara sessiz sessiz

Kaç kez vurdu raylara son kampana

Ve kaç kez yenildi vuslat bilmemki zamana

Ben şehirler kadar kalabalık, yıldızlar kadar suskun

Yüzüme yıllar doluyor... Yoksun...', 'Bu kaçıncı tren ki senden habersiz Kayıp gitti ufuklara sessiz sessiz Kaç kez vurdu raylara son kampana Ve kaç kez yenildi vuslat bilmemki z...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Seçer']::text[], 8.5, '{"poet":"Mehmet Seçer","poet_slug":"mehmet-secer","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bekleyis-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-burhan-gokoguz-67wf6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tarifsiz sokaklarda yürüyorum

Sağ taraf kanlar içinde

Sol tarafta intiharlar kol geziyor.

Rüzgarın musikisinde gözlerin

Gözlerimde kanla dolu yaşlar

Akar gider sensiz yürüdüğüm sahillerde

Ayaklarım ıslanır yakamozlanan denizde.

Ortalama bir hızla yürüyorum

Ortalama bir ölüme doğru.

Gecenin karanlığında

Bir ışık hüzmesi aydınlatır yolumu

Gözlerini görüyorum, 

Gözlerin umut, 

Gözlerin çığlık, gözlerin bulut, 

Gözlerinde ben, kendimi

Düşünce tabutumun içinde görüyorum

Direniyorum; 

Gülün zamana direndiği gibi

Ürküyorum hayattan

Ürkek hayallerin tedirğinliği içinde.

Bir porsiyonluk hayatlar kol geziyor

Görüş gününde sevgilimle aramda

Bakarken tel örgülerin arkasından

İki damla göz yaşıyla

ZAMAN; 

Eriyip gidiyor, 

Eriyip yok olan

Düşünce çarkımın arasında....', 'Tarifsiz sokaklarda yürüyorum Sağ taraf kanlar içinde Sol tarafta intiharlar kol geziyor. Rüzgarın musikisinde gözlerin Gözlerimde kanla dol...', ARRAY['Türk Edebiyatı','Şiir','Burhan Gökoğuz']::text[], 8.5, '{"poet":"Burhan Gökoğuz","poet_slug":"burhan-gokoguz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/zaman-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimin Bamteli', 'yuregimin-bamteli-i-rem-yitmen-irq4l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '‘’Aşk nedir? ’’

Bunun tanımlaması yapılabilmiş mi? Aşk üzerine yazılmış, çizilmiş, bestelenmiş ve söylenmiş birçok şey var.Bugün arkadaşlarıma sordum.’’Sizce aşk nedir? ’’

Tanımlamalar şöyleydi:Aşk gelip geçici bir tutku, aşk ayaklarının yerden kesilmesi, aşk acı çekmek vs.

Geçenlerde televizyonda Kayahan’la yapılan bir röportajı izledim.Aşkın tanımının yanlış yapıldığından yakınıyordu.Günümüzde küçük kaçamakların ve tek gecelik ilişkilerin adının bile aşk olarak nitelendirildiğinden yakınıyordu.Aşkın ve sevginin uğraş, emek ve fedakarlık istediğinden sözediyordu, ona içtenlikle katılıyorum.

Aşkın tanımlamarını çoğaltmak mümkün...

‘’Aşık olmak seyretmektir, başka bir insanın ruhunun şaşırtıcı harikalarına gözlerini fal taşı gibi açıp bakmak.Sevilen birisinin varlığında bizleri dönüşüme uğratan enerjiden daha güzel ve daha güçlü bir sihir yoktur.Bu sihirmidir yoksa ilahi bir güç mü? Ben ilahi olması gerektiğini düşünüyorum.Türümüzün hayatta kalması başka nasıl bu kadar mükemmel bir biçimde sağlanabilirdi ki? ’’ (Janice R.Levine)  

John Gray’a göre aşk fiziksel, duygusal, zihinsel ve ruhsal bir kimyanın bir bütünü.

Aşk üzerine bence söylenebilecek herşey aşağıdaki dizelerde en güzel ifadesini bulmuş.

TEK HECE AŞK 

Var mı beni içinizde tanımayan, 

Yaşanmadan çözülmeyen sır benim

Kalmasada şöhretimi duymayan

Kimliğimi tarif etmek zor benim

Kimsesizim; hısmım da yok hasmım da 

Görünmezim; cismim de yok resmim de

Dil üzmezim; tek hece var ismim de 

Barınağım gönül denen yer benim

Bülbül benim lisanımla ötüştü, 

Bir gül için can evinden tutuştu, 

Yüreğine toroslardan çığ düştü

Yangınımı söndürmedi kar benim

Niceler kraldı sultandı şahtı, 

Benimle değişti talihli bahtı

Yerle bir eyledim tac ile tahtı

Akıl almaz hünerlerim var benim

Kamil iken cahil ettim alimi, 

Vahşi iken yahşi ettim zalimi, 

Yavuz iken zebun ettim Selimi, 

Her oyunu bozan gizli zor benim

İlahimle Mevlana’yı döndürdüm, 

Yunusumla öfkeleri dindirdim

Günahımla çok ocaklar söndürdüm, 

Mevladanım hayır benim şer benim 

Sebep bazı Leyle bazı Şirin’di, 

Hatrım için yüce dağlar delindi, 

Bilek gücüm Ferhat ile bilindi, 

Kuvvet benim kudret benim fer benim 

Yeryüzünde ben ürettim veremi, 

Lokman Hekim bulamadı çaremi, 

Aslı için kül eyledim Kerem’i, 

İbrahim’in atıldığı kor benim.

Benim adım aşk...

Cemal Safi

Günümüzde insanlar aşkın gerçek anlamını bilemediklerinden ve gerçek aşkı yaşayamadıklarından; aşka inanmıyorum, aşk denilen şey yalandır, aşk gelip geçici bir duygudur, aşık olmak acı çekmektir vs. gibi tanımlamaları kullanıyorlar. 

Bizler aşkın gerçek anlamını kavrayamadığımızdan ve gerçek aşkı yaşamayı beceremediğimizden dolayı böyle konuşmayı seçiyoruz. 

‘’Aşkın herşeyiyle orada olduğu aşka dair bildiğimiz tek şeydir’’ Emily Dickinson

‘’Size içinde ilaç yada bir cadının büyüsü olmadan bir aşk iksiri göstereceğim:eğer sevilmek istiyorsanız, sevin’’ Hecato 

Aşkı bana sorsalardı şunları söylerdim:

Aşk içimizdeki güzellikleri ortaya çıkaran bir sihir, bizim iyi yanlarımızın ve karşımızdaki insanın iyi yanlarının ortaya çıkmasına ve bunları keşfedip geliştirmemize neden olan bir sihir

‘’Aşkın içimizdeki en iyiyi açığa çıkardığı sanırım bir gerçek ve bu nedenle aşkı arıyoruz.İçimizdeki en iyiyi ifade etme yolumuz bu, başka birisini severek ve onlar için orada olmayı isteyerek ‘’ Annette Bening 

Aşk farklılıklarımızı olduğu gibi kabul edebilmektir.Gerçek aşk farklılıklarımızı derinden kabullenmektir, karşımızdaki insanı olduğu gibi kabullenmektir ve onun verdikleri ve verebilecekleri ile mutlu olmayı seçmektir.

Bunu yaptığımızda mutluluğun gerçek sırrını keşfedebiliriz.Arkadaşımın bir sözü vardır:’’Karşındaki insana tüm çıplaklığıyla bak.O insanın tüm icraatlerini, geçmişini ve kariyerini bir köşeye koyduğunda hala o insanla 

beraber olmak istiyorsan o insan potansiyel aşık olabileceğin ve gerçekten sevebileceğin bir insandır. ‘’

‘’Romantik aşk kusur kapatıcı bir ayna gibidir...Pembe kızarıklığı yansıtır.Gerçekliğe dayanan aşk ise daha çok kırışıklıklarımızı büyüten makyaj gibidir.’’ Shirley B.Glass 

‘’Aşkın gözü kusurlara karşı her zaman kördür

Hep eğlenceye meyilidir

Kuralsız, kanatlı ve sınırsızdır

Ve her akıldaki tüm zincirkeri kırar’’ William Blake 

Aşkın gözü kör olabilir, özellikle başlangıçta....Ancak keşfettiklerimiz vasıtasıyla gözlerimizi ve kulaklarımızı açarak kalıcı ve köklü aşkı yaşamayı başarabiliriz.Keşfettiklerimiz farklılıklarımızı derinden kabullenmek, farklılıklarımızdan öğrenebileceğimiz birçok şey olabileceğini kavrayabilmek ve bunu eğlenceli bulabilmektir.Kusursuzluğu arayarak değil de kendimizinde kusursuz olmadığının bilincinde olarak ve bir ilişkiye 

verebileceklerimizin ve alabileceklerimizin tadına vararak mutlu olabiliriz.

Aşk var olababilme ve var edebilme amacımızdır.Bizleri bütünleşmeye, çoğalmaya ve türümüzü devam ettirmeye iten ana duygu...

‘’Aşkın çok sayıdaki boyutunu düşünün.Biyolojik düzeyde, türümüzün hayatta kalması aşka bağlıdır.Bu tek, güçlü enerji, beslenme ve korunmadan üremeye kadar olan her temel ihtiyacın kalbindedir.Biyologlar, aşkın sadece bizi insan olarak tanımlayan şey değil, aynı zamanda hem bireysel gelişimimizin  hemde toplu evrimimizin aracısı olduğunu öne sürerler.Düşünün:başka bir insan çevresini kendimizinkine katmak için kendimizi açtığımızda hücresel yapılarımız ve sinir yollarımız kelimenin tam anlamıyla aşkın aracılığıyla değişir.Büyüleyici! ‘’ Janice R.Levine 

Aşk üzerine söylenebilecek o kadar çok şey varki, ama inkar edilemez bir gerçek varki:

‘’ Gerçek aşk durdurulamaz, gerçek aşk kapıdan da olsa bacadan da olsa girer, kalplerimizdeki esas yerini bulur.Gerçek aşk bizim kendimizi tanımamızı, olumlu özelliklerimizi keşfedip bunları daha çok geliştirmeimize 

neden olur.Olumsuzlukların bilincine vararak bunları daha aza indirgememizi sağlar, yeter ki yüreklerimizin kapıları daima açık olsun.’’ İrem Yitmen

ten tenle 

buluştuğunda 

hiçbir şey durduramaz 

birleşmelerini 

kalp kaple 

buluştuğunda

hiçbir şey durduramaz 

tutkuyu

ruh ruhla 

öpüştüğünde 

kim durdurabilirki 

aşkı? 

Afua Cooper

Bir şiirimle noktalamak istiyorum sözlerimi, 

SEVGİLİ 

Ben seni sevdim sevgili, 

Gözündeki pırıltıları, 

Dudaklarındaki gülümseyişi, 

Ellerinin sıcaklığını, 

Yüreğindeki saflığı, 

Gönlündeki candanlığı

Ben sadece seni sevdim sevgili, 

Ne ayaklarının altındaki kırmızı halıları, 

Ne de başının üstündeki o altın tacı, 

Ne de elindeki o zümrüt asayı, 

Ben seni, sen olduğun için sevdim sevgili, 

Ben sadece seni sevdim sevgili, 

Ne senden gökyüzündeki yıldızları, 

Ne de denizin dibindeki incileri, 

Ne de zümrüt dağındaki anka kuşunu 

istedim sevgili

Sadece senden seni istedim sevgili, 

Sadece tek bir şeyi istedim, 

Beni ben olduğun için sevebilmeni sevgili, 

Beni daima olduğum gibi hatırla sevgili, 

İ.Y (Temmuz 1998)', '‘’Aşk nedir? ’’ Bunun tanımlaması yapılabilmiş mi? Aşk üzerine yazılmış, çizilmiş, bestelenmiş ve söylenmiş birçok şey var.Bugün arkadaşları...', ARRAY['Türk Edebiyatı','Şiir','İrem Yitmen']::text[], 8.5, '{"poet":"İrem Yitmen","poet_slug":"i-rem-yitmen","theme":"Türk Şiiri","is_hero":false,"total_lines":101,"source_url":"https://www.antoloji.com/yuregimin-bamteli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılanlar Günü', 'ayrilanlar-gunu-oguzhan-akay-hze3a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biz sevgiyi değil, birbirimizi tükettik

Bir ayağım ayrılığa uzanmış bir ayağım sana

Saçlarına dokunamam artık yasak

Sevişmeler çok uzak

Ölmeden ölmüş gibi olmak

Doğmadan doğmuş gibi olmak nasılsa 

Uğurlamadan, uğurlanmadan hayata

Bir teknenin üstünde, limana kayıtlı

Saklı duygular denizinde yol almak

Hangisi kolay, hangisi hülya

Senle de sensiz yaşamak', 'Biz sevgiyi değil, birbirimizi tükettik Bir ayağım ayrılığa uzanmış bir ayağım sana Saçlarına dokunamam artık yasak Sevişmeler çok uzak Ölme...', ARRAY['Türk Edebiyatı','Şiir','Oğuzhan Akay']::text[], 8.5, '{"poet":"Oğuzhan Akay","poet_slug":"oguzhan-akay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ayrilanlar-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyü', 'buyu-ertug-akbay-cpe0p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayrılığı haketmeyecek kadar gençti bu sevda

Büyü bozulmuştu, 

Bozan bendim, 

Çünkü daha büyümemiştim.

Şimdi bildiğim bütün duaları okuyorum

Seni geri döndürmek için.

Yalnız bir odada 

Reenkarnasyona inanmayan bir sevdayı

Ayakta tutmak için', 'Ayrılığı haketmeyecek kadar gençti bu sevda Büyü bozulmuştu,  Bozan bendim,  Çünkü daha büyümemiştim. Şimdi bildiğim bütün duaları okuyorum ...', ARRAY['Türk Edebiyatı','Şiir','Ertuğ Akbay']::text[], 8.5, '{"poet":"Ertuğ Akbay","poet_slug":"ertug-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/buyu-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçek Yollama Şiiri', 'cicek-yollama-siiri-oguzhan-akay-bgyqb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstanbullu bir gül istedim, sevgi mahallesinden

Dikenleri az, kırmızısı bol olsun

Özlemi çok, öyküsü uzun olsun

Bir gülün olsun, yanağına dokunsun

Yanağına öpücüğüm konsun

Oh be! Söyledim işte', 'İstanbullu bir gül istedim, sevgi mahallesinden Dikenleri az, kırmızısı bol olsun Özlemi çok, öyküsü uzun olsun Bir gülün olsun, yanağına do...', ARRAY['Türk Edebiyatı','Şiir','Oğuzhan Akay']::text[], 8.5, '{"poet":"Oğuzhan Akay","poet_slug":"oguzhan-akay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/cicek-yollama-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Yağmurum Ol', 'sevgi-yagmurum-ol-nuri-can-w32fd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Günüm güneşim ol, ısınacağım

Ümit duvarım ol, yaslanacağım

Sevgi yağmurum ol, ıslanacağım

Gül kokun bir ömür tenimde kalsın

Gel sevgilim ol benim, düş kaçağım

Göğsüne başımı yaslayacağım

Kalbimin içinde saklayacağım

Özlemin bir ömür gönlümde kalsın

Bir dünya sun bana tutunacağım

Gönlümü sevginle avutacağım

Bütün ihanetleri unutacağım

Ellerin bir ömür elimde kalsın

Sen uyku ol, ben gördügün düş olam

Sen yuva ol, ben bir yavru kuş olam

Ağlar isen yanağında yaş olam

Gözlerin bir ömür gözümde kalsın

Sevgi mırıldayan nehirler gibi

Derin uykularda şehirler gibi

İsminki bir dua şiirler gibi

Ölünceye kadar dilimde kalsın', 'Günüm güneşim ol, ısınacağım Ümit duvarım ol, yaslanacağım Sevgi yağmurum ol, ıslanacağım Gül kokun bir ömür tenimde kalsın Gel sevgilim ol ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevgi-yagmurum-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Dair Çiçekler', 'aska-dair-cicekler-abdullah-oztemiz-hacitahiroglu-si4st', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşk adına durmuş saatler

Yine aşk adına kurulur

İçerde bir gökyüzü başlar

Güneşler birbirini bulur.

Çalar saatler aşkı vurur

Aşkı yanıp söner yıldızlar

Dallar verdiği sözde durur

Aşka dair çiçekler açar.', 'Aşk adına durmuş saatler Yine aşk adına kurulur İçerde bir gökyüzü başlar Güneşler birbirini bulur. Çalar saatler aşkı vurur Aşkı yanıp söne...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Öztemiz Hacıtahiroğlu']::text[], 8.5, '{"poet":"Abdullah Öztemiz Hacıtahiroğlu","poet_slug":"abdullah-oztemiz-hacitahiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aska-dair-cicekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Durdu', 'zaman-durdu-fatih-pasali-7oala', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hiç bir günahı yakıştıramadığım sevgili

bak yelkovan kuşları da göç etti / 

zamansızlık mevsimine

akrep kendini sokuyor ve sorguluyor artık

zamanı kurşunlayarak eskiten kum akışından utanık

rüzgarlarla yarışan çocuğun anlık duraklarında

tüm takvimler kendisine ihtilal

işte zaman da intihar etti

tarih utandı / devinim yorgun

yıpranıp ipildeyen bir kumaş gibi

yırtıldı orta yerinden zaman

zaman durdu! 

ve şimdi; 

saatler kolumuzda (bir)  göçebedir artık...

zaman öldü! 

(işte tüm kiplerini de yanına alarak)', 'hiç bir günahı yakıştıramadığım sevgili bak yelkovan kuşları da göç etti /  zamansızlık mevsimine akrep kendini sokuyor ve sorguluyor artık ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Paşalı']::text[], 8.5, '{"poet":"Fatih Paşalı","poet_slug":"fatih-pasali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zaman-durdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşluk', 'bosluk-sule-aydemir-jjxqg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-Şeker'' den

seni seviyorum 

doluca doluyor 

koca bir boşluk 

yaşamım var şimdi tam anlamında

üstünde yürüyorum sevgiden suyun 

hem sinsi bir güzel 

hem huzur sessizce

gülümse

yüreğin dokunsun suya

ayak izlerim var şimdi

gördün mü akanı

öp zamanı sar 

sarmala  yaşamı

herşeyi unut 

coşkunu bozan ne varsa

seni sevdiğimi asla', '-Şeker'' den seni seviyorum  doluca doluyor  koca bir boşluk  yaşamım var şimdi tam anlamında üstünde yürüyorum sevgiden suyun  hem sinsi bir...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bosluk-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serfiraz Naif', 'serfiraz-naif-sule-aydemir-13zl7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'serfiraz bir naif 

kırıldım mı kanatlarda

uçan kuş mudur bülbül 

şakıyor mu ya da

gonca açılıyor tatlı yorgunluğunda

serfiraz çiğden yalnızlığı gülün

naifliği anason kokusu sarhoşluğunda', 'serfiraz bir naif  kırıldım mı kanatlarda uçan kuş mudur bülbül  şakıyor mu ya da gonca açılıyor tatlı yorgunluğunda serfiraz çiğden yalnızl...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/serfiraz-naif-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin(m) i kapalı tut(acağım)', 'gozlerin-m-i-kapali-tut-acagim-gok-tengri-7cu32', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni nasıl göresim geldi bir bilsen

Lakin ben ayrı memlekette sen ayrı memlekette..

Sen düşünüyorum..

-Yetmiyor ama

Elimden fazlası da gelmiyor-

Uyuyorsun sen

Istanbul''da yatağında bir tatlı kızsın

Bense seni düşünerek

Şiir yazmaktayım Adana''da

Ama kapadım mı gözlerimi yanıbaşındayım

Tatlı yanağından öpüyorum

Okşuyorum saçlarını

Kulağına fısıldıyorum:

''Canım

Sen beni bırakıp ardında gidince

Ben sensiz n''aparım? ''

Yine gözlerimi kaparım

Aşarım denizleri

Gelirim yanına

Yine fısıldarım:

''Canım

Ben sensiz

Hiç bir şey yapamam! ''

Sen Istanbul''da yatağında uyumakta olan tatlı bir kızsın

Ben senin başucunda, kulağına bir şeyler fısıldayan adam

Gözlerini açtığında yanağında bir öpücük ıslaklığıyla

Ben yine Adana''da yatağımda oluc''am', 'Seni nasıl göresim geldi bir bilsen Lakin ben ayrı memlekette sen ayrı memlekette.. Sen düşünüyorum.. -Yetmiyor ama Elimden fazlası da gelmi...', ARRAY['Türk Edebiyatı','Şiir','Gök Tengri']::text[], 8.5, '{"poet":"Gök Tengri","poet_slug":"gok-tengri","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gozlerin-m-i-kapali-tut-acagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Anladık', 'ne-anladik-bekir-mutlu-gokcesu-p1qfe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aklımın irili ufaklı çakıl taşları

yundu, yıkandı deli yağmurlarda.

Denizi de içtik, susuz da kaldık

kimi beydik, kimi hırpalandık.

Diyorsun ki, iyi de baba ne anladık? 

Hem hiç bir şey, hem çok şey...

Galiba sadece insan olmalıydık

işte bunu anladık.', 'Aklımın irili ufaklı çakıl taşları yundu, yıkandı deli yağmurlarda. Denizi de içtik, susuz da kaldık kimi beydik, kimi hırpalandık. Diyorsun...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ne-anladik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SeferiNaz', 'seferinaz-sule-aydemir-y71nq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir aşk 

takıldı umudun kuşlarına 

uçacak gönül 

ettiği seferinaz

bir hoş seda 

en vakitsiz zamanda 

gün seferinaz  eyledi asudeliğinde

nail oldu dizeler 

manzum bir siluete

ey bedii

geçmiyor zaman aşksız meşksiz

uzan hey umut uzan 

sök kır dağıt parçala

seferi de al 

nazı sahiplenme

kulda kulluk ki

seferinaz sevda isterse', 'bir aşk  takıldı umudun kuşlarına  uçacak gönül  ettiği seferinaz bir hoş seda  en vakitsiz zamanda  gün seferinaz  eyledi asudeliğinde nail...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seferinaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili''ye (2)', 'sevgili-ye-2-ensar-cevval-le9p8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen gittin ya sevgili, 

duramam artık bu ıssız sokaklarda

ne bahçemden pencereme düşen gül 

ne lale, menekşe, karanfil, ne de sümbül

ne de aşkından biçare dolanan bülbül

sensiz hatıramda, belli ki olmayacaklar

Sen döndün ya sevgili, 

Yedi harf düştü gönlüme yedi katlı semadan

yedi karanfil tadında

yedi yıldız indi gecenin bir zamanında

yedikulenin yüzüne, yakamoz parıltısında

yedişer kez yıkandı

yedi kat derin mavinin göbeğinde

yedi tepeli şehrin yedide birinde otururken 

yedi yıldız kaydı yedi köşesinde

yedi yürek yandı

yedi gonca açtı yediveren

yedi eşkiya öldü

sen döndün ya...', 'Sen gittin ya sevgili,  duramam artık bu ıssız sokaklarda ne bahçemden pencereme düşen gül  ne lale, menekşe, karanfil, ne de sümbül ne de a...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevgili-ye-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazıksın', 'yaziksin-murat-demir-f876q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gelin oldun habersizce ellere

Düşünmeden teslim oldun kimlere

Yüreğimi parçaladın hiç yere

Benden beter ol diyemem yazıksın

Seni yakan sen değilde atandır

Acımadan eşya gibi satandır

Senden gayri bana sevda haramdır

Benden beter ol diyemem yazıksın

Ben ağlarım sen ağlama boşuna

Bensiz hayat gitmesede hoşuna

Sensizliği yokluk ördü başıma

Benden beter ol diyemem yazıksın

Yatıyorum kalkıyorum sen yoksun

Dünya batsın sensiz açan gül solsun

İster dönsün, isterse dünya dursun

Benden beter, ol diyemem yazıksın', 'Gelin oldun habersizce ellere Düşünmeden teslim oldun kimlere Yüreğimi parçaladın hiç yere Benden beter ol diyemem yazıksın Seni yakan sen d...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yaziksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koruk', 'koruk-naime-erlacin-9rfzn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''aşka anlam katmak'' dedi birisi

düşündüm:

ne biliyor

ne anlatıyorlardı aşk hakkında

aşk dilencisiydi çoğu

feryatlar koparıyor 

haykırıyor ''bana dön'' diye

ellerinde tasma bekliyorlardı 

tensel arzular fışkırıyordu kiminden

doyumsuzluk doruklarında aşkı su sanıp 

hazza ulaşmaktı amaç

kendine aşık olanlar ah! 

kutsanmak isteyenler her şafakta

duydukça aşk sözlerini buluta tırmanan

narkissos''un aynasına bakarken gölde

bir nergis çiçeği kadar olamayan! 

kızgındı bazıları, öfkeli

ateş kusuyorlardı

çekildi ben''ler bencillik gönderine

görüş mesafesi ''sıfır''

ötesi ne! 

ah kuru asma ne zaman yeşereceksin

koruğun üzüme dönüşecek de

şarap yapmayı öğrenecek 

aşk ehli eller bir gün

ne zaman? 

(26 Haziran 2003)', '''aşka anlam katmak'' dedi birisi düşündüm: ne biliyor ne anlatıyorlardı aşk hakkında aşk dilencisiydi çoğu feryatlar koparıyor  haykırıyor ''b...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/koruk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Bakışlar', 'siyah-bakislar-derin-oger-zm5nj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Farkındasın aslında sana olan hasretimin

Kimseler bilmesede farkındasın seni özlediğimin 

Tüm çıplaklığıyla farkındasın seni sevdiğimin

Oysa kayıp gecelerde arıyorum hayalini

Yanağımda gözyaşlarımın yuvarlanışları gibi

Sözcüklerim de donuk ve buruk damlıyor

Burdasın aslında yanımda derin siyah bakışlarla

Sanki her arkamı döndüğümde ardımda

Gzlerini ve ellerinin sıcaklığını özlüyorum 

Hasreti zarf zarf katlayıp katar katar raylara döşüyorum

Ha gayret diyip yüreğe pul pul purbetine dökülüyorum

Benimlesin aslında bende olduğunu biliyorum.......', 'Farkındasın aslında sana olan hasretimin Kimseler bilmesede farkındasın seni özlediğimin  Tüm çıplaklığıyla farkındasın seni sevdiğimin Oysa...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/siyah-bakislar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı şahane', 'aski-sahane-murat-tali-70g04', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'olmaya devri cihanda kamer gözlü yar 

senin gibi bir dilber

şems ile alazlanır gönül 

bir akşam vakti

goncaya düşen bir çiğ damlası ile 

söner

yangın yeri bakışlarım

gel bozma asude gönlümün hicranını

Nağmelerinle mesut eyle

mekanımı', 'olmaya devri cihanda kamer gözlü yar  senin gibi bir dilber şems ile alazlanır gönül  bir akşam vakti goncaya düşen bir çiğ damlası ile  sön...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aski-sahane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Dediğin', 'can-dedigin-murat-demir-2eoq3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Can dediğin kaçar gider

Bir nefeste uçar gider

Sona yelken açar gider

Kıymetini bilmeliyiz

Ne göz görür ne el tutar

Ne yan gelir nede yatar

Terki beden tenden sapar

Kıymetini bilmeliyiz

Ha varım ben o oldukça

Kafesinde kalp vurdukça

Anladımki yaşadıkça

Kıymetini bilmeliyiz

O an gelir herşey biter

Ne olduysa gelip geçer

Ecel gelir tıpan biçer

Kıymetini bilmeliyiz', 'Can dediğin kaçar gider Bir nefeste uçar gider Sona yelken açar gider Kıymetini bilmeliyiz Ne göz görür ne el tutar Ne yan gelir nede yatar ...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/can-dedigin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük', 'ozgurluk-cemal-ekren-ozdnd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ÖZGÜRLÜK

Hiç mavi renkli gömleğim, 

mavi renkli yatak çarşafım; 

mavi gözlü sevgilim olmadı.

Gökyüzünden bir parça alıp gömlek diktim, 

Deniz mavisini yatağıma  çarşaf  yaptım.

Gözleri mavili sevgiliyi bulunca; 

Firari sayıldım vuruldum.

Şimdi beyazlar içindeyim...', 'ÖZGÜRLÜK Hiç mavi renkli gömleğim,  mavi renkli yatak çarşafım;  mavi gözlü sevgilim olmadı. Gökyüzünden bir parça alıp gömlek diktim,  Deni...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ozgurluk-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adım çocuk', 'adim-cocuk-cemal-ekren-rft6z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tecritli bir oda

Yasaklı sözcüklerin ortasında, 

Ritmi dudaklarda gizli, 

Küfürler.

Babamın kır saçalarına saklanmış acılar, 

Voltam sınırlı, 

öksürüğüm nemli duvarlara gebe.

Bogmacam şehgüzelin tükürüğüne kalmış

Kara trenin buharını ararım  çocuksu gözlerimde

Anam bismillahla yoğurur hamuru

Kuşluk vakti

Ve

Kuşluk vakti

Firari ölümler sırrını arka sokaklarda gizler

Anaların ağıtları

 tecritli odamda yankılanır.

Dışarda ki gözlerim firaridir vurulur

Dipsiz kuyunun karanlığındayım

Sokak aralarına düşerken

Adım çocuktur; 

Soyadım suç

Öfkem beni büyütür

Salçalı ekmegime konan sinek, 

Suç delilimdir

Ben büyürken

Tecritli odalar küçülür

Öfkemin yeni adresi küfürleri ezerken

Dışardaki gözlerim

Dipsiz kuyudan çıkar

Yeni canlarla....', 'Tecritli bir oda Yasaklı sözcüklerin ortasında,  Ritmi dudaklarda gizli,  Küfürler. Babamın kır saçalarına saklanmış acılar,  Voltam sınırlı...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/adim-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gezmesin Bir Başka El Saçlarında', 'gezmesin-bir-baska-el-saclarinda-nuri-can-kkr9k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dönderme yüzünü  kurban olaym 

Sen ol bu dünyada güneşim ayım 

Yalnız ben seveyim, ben okşayayım

Gezmesin bir başka el saçlarında

Kalbimin içidir   en  güzel  yerin

Tutmasın bir başka eli  ellerin

Gözlerin gözümde bak derin derin

Kaybolup gideyim bakışlarında

Yüce dağ başına yağan karlarca

Seyrine dalayım senin  yıllarca

Gönül ırmağında  coşan sularca

Bin huzur bulayım   akışlarında

Süsenim  sümbülüm  reyhancasına

Kekliğim   maralım   ceylancasına

Tamburum  cümbüşüm kemancasına

Şarkılar  derleyim   ağaçlarında

Tanrıya dilenen  dilekler  gibi 

Cennette dolanan melekler gibi

Sevda dağındaki  çiçekler gibi

Bir  ömür kalayım  yamaçlarında', 'Dönderme yüzünü  kurban olaym  Sen ol bu dünyada güneşim ayım  Yalnız ben seveyim, ben okşayayım Gezmesin bir başka el saçlarında Kalbimin i...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gezmesin-bir-baska-el-saclarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunki Yansın Yüreğin', 'dokunki-yansin-yuregin-nuri-can-27d73', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey  sevdiğim  bir  çiçeğe

Dokunki  yansın  yüreğin 

Aşka  yanmış bir  yüreğe

Sokulki  yansın   yüreğin

Usul  usul   ince  ince

Yapraklara kar duşünce

Aç kolların  bütün  gece

Sarılki  yansın  yüreğin

Mor  dağları  aşa  aşa

Ay doğunca baştan  başa

Yanakta  bir damla  yaşa

Dokunki  yansın  yüreğin

İster  sümbül boyun eğsin

İster  dallar  yere  değsin

Seviyorsan  nerden bilsin

Sokulki  yansın  yüreğin

Sabah  seher  yellerince

Coşan  bahar  sellerince

Sazın    sarı   tellerince

Dokunki  yansın  yüreğin

Can düşerken  al toprağa

Hayat  gelir  bin  yaprağa

Aşka  susuz  bir  dudağa

Dokunki  yansın  yüreğin

Aşk denilen bir ummana

Düşer  isen  yana  yana

Nuri Can  gibi  bir  cana

Sokulki  yansın  yüreğin', 'Ey  sevdiğim  bir  çiçeğe Dokunki  yansın  yüreğin  Aşka  yanmış bir  yüreğe Sokulki  yansın   yüreğin Usul  usul   ince  ince Yapraklara ka...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dokunki-yansin-yuregin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Yemini', 'ask-yemini-serkan-ertunc-1kn1w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni bir ömür boyu seveceğime, 

Gözümün gözüne değdiği her an sana yeniden aşık olacağıma, 

Sevgimin asla değişmeyeceğine, azalmayacağına

Seni asla ihmal etmeyeceğime, 

Bir ömür elini bırakmayacağıma, 

Bir ömür canım aşkım olarak kalacağına, 

Yıldızlara kement atacağıma, 

Her anın unutulmazlık zincirine bir yenisini ekleyeceğime, 

Seni sen olduğun için seveceğime, 

Seni bir ömürden öte seveceğime; 

Söz verir, Yemin ederim Aşkım..!', 'Seni bir ömür boyu seveceğime,  Gözümün gözüne değdiği her an sana yeniden aşık olacağıma,  Sevgimin asla değişmeyeceğine, azalmayacağına Se...', ARRAY['Türk Edebiyatı','Şiir','Serkan Ertunç']::text[], 8.5, '{"poet":"Serkan Ertunç","poet_slug":"serkan-ertunc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ask-yemini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sor hele niye..?', 'sor-hele-niye-haci-ozturk-bxtfc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu  mutlu  günler geride  kalır, 

Biter  bu sevda  demiştim, sor hele niye...? 

Sevda  karşılıksız  olursa  can sıkar, 

Çekene  sor demiştim, sor hele niye...? 

Ağıra  satma kendini sevene naz olmaz, 

Bilirsin taşıma suyla değirmen dönmez, 

Sevda  sevene  kor ateştir  bilesin sönmez, 

Bunu  sana  demiştim,  sor hele  niye....? 

Sallama  sevdayı   sende  sallanırsın, 

Seversen  eğer  filizlenir, dallanırsın, 

Arı  gibi  petek  yapar  ballanırsın, 

Tadına  doyum olmaz demiştim, sor hele niye...? 

“Hacım, der  sözlerim olsun nasihat, 

Sevene  yaratan verir sabrı  kat, kat, 

Sönmez  dediğin yıldızlar, söner  elbet, 

Dönüşün  olmaz  demiştim, sor  hele  niye...?

Hacı  Öztürk                       24/06/2003

                                            LİBYA

KAYDEDEN                       Hacı  Öztürk', 'Bu  mutlu  günler geride  kalır,  Biter  bu sevda  demiştim, sor hele niye...?  Sevda  karşılıksız  olursa  can sıkar,  Çekene  sor demiştim...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sor-hele-niye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedduâ', 'beddu-serkan-ertunc-i8e81', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bak yine bizim şarkımız çalıyor, 

Bak ben her zamanki gibi ağlıyorum, 

Göz yaşlarım bir  bir süzülüyor, 

Onlarda senin sevgin kadar alçalıyor.

Ama bu son göz yaşlarım

Yok bundan sonra ağlamak, 

Senin için tanrıya yalvarmak, 

Umudumu fallara adamak.

Eğer bir gün olurda, 

Senin için yine ağlarsam, 

Başımı hep dik tutacağım ki, 

Göz yaşlarımda senin kadar alçalmasın…

Sana En Büyük Bedduâm Sevgi Yağmurları Altında Şemsiyesiz Kalman..!', 'Bak yine bizim şarkımız çalıyor,  Bak ben her zamanki gibi ağlıyorum,  Göz yaşlarım bir  bir süzülüyor,  Onlarda senin sevgin kadar alçalıyo...', ARRAY['Türk Edebiyatı','Şiir','Serkan Ertunç']::text[], 8.5, '{"poet":"Serkan Ertunç","poet_slug":"serkan-ertunc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/beddua-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlar ve Ben', 'yildizlar-ve-ben-serkan-ertunc-gqt6v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Söyleyin yıldızlar..! 

Sevdiğimi geri getire bilir misiniz? 

Söyleyin yıldızlar..! 

Tekrar beni sevdire bilir misiniz? 

Söyleyin yıldızlar..! 

Tekrar el ele dolaşa bilir miyiz? 

Söyleyin yıldızlar..! 

Yağmurlar altında öpüşe bilir miyiz? 

Söyleyin yıldızlar..! 

Yıllar geçse de aradan

İsimler silinse de banklardan

Yinede mutlu olur muyuz BİRGÜN…', 'Söyleyin yıldızlar..!  Sevdiğimi geri getire bilir misiniz?  Söyleyin yıldızlar..!  Tekrar beni sevdire bilir misiniz?  Söyleyin yıldızlar.....', ARRAY['Türk Edebiyatı','Şiir','Serkan Ertunç']::text[], 8.5, '{"poet":"Serkan Ertunç","poet_slug":"serkan-ertunc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yildizlar-ve-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamana İnat', 'zamana-i-nat-serkan-ertunc-njucs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hasretinle geçiyorken şu gençlik çağım, 

Ey sevdiğim, ben ümitsiz değilim gene.

Ak düşünce  saçların kumral rengine, 

Kollarında son aşığın ben olacağım.

Ey başında şimdi sevda rüzgarları esen, 

Böyle hergün yollarından geçsemde süzgün, 

Sen benimsin büsbütün tek olduğun gün.

O mukadder günü bilmem düşündün mü sen? 

Ben bir beyaz saçlı aşık, 

Sen bir ihtiyar…

O gün bana yanaşırken ey ilahi yar…

Esirgeme gözlerimden bir son buseni

Kirpiğinden yavaş yavaş bir damla aksın, 

Çünkü ruhum sende o gün anlayacaksın.

Ki hiç kimse benim kadar sevmemiş SENİ..!', 'Hasretinle geçiyorken şu gençlik çağım,  Ey sevdiğim, ben ümitsiz değilim gene. Ak düşünce  saçların kumral rengine,  Kollarında son aşığın ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Ertunç']::text[], 8.5, '{"poet":"Serkan Ertunç","poet_slug":"serkan-ertunc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/zamana-inat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksan Ben de Yokum', 'sen-yoksan-ben-de-yokum-serkan-ertunc-slokq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana unutulmazlığının eseri olarak, 

Ne kadar çok sevildiğini bilmen için, 

Kuşların kanadında yüreğimi gönderiyorum.

Çünkü ben artık bu yüreği taşıyamıyorum

Sana sevgimi ne şekilde olursa olsun anlatamıyorum.

Bende kalmasının yanımda sen olmadan hiç anlamı yok.

Sen yoksan bu yüreğin bu bedende yeri yok.', 'Sana unutulmazlığının eseri olarak,  Ne kadar çok sevildiğini bilmen için,  Kuşların kanadında yüreğimi gönderiyorum. Çünkü ben artık bu yür...', ARRAY['Türk Edebiyatı','Şiir','Serkan Ertunç']::text[], 8.5, '{"poet":"Serkan Ertunç","poet_slug":"serkan-ertunc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sen-yoksan-ben-de-yokum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Geliyorum...', 'sana-geliyorum-serkan-ertunc-6pqxf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana yangınlarla geliyorum

Kor dudaklarla

Tuzlu tenimle 

Yaşlı gözlerle

Ne masum bir aşkım var sana verecek

Ne görülmemiş rüyalarım

Nede pembe hayallerim var

Çırılçıplak geliyorum sana 

Kırmızı güllerin kanlı dikenleriyle

Sensiz gecelerin kabuslarıyla

Mükemmel bir hayat vaad etmiyorum sana

Her ağaç günü gelir yaprak döker

Ben sana sağlam kökler veriyorum', 'Sana yangınlarla geliyorum Kor dudaklarla Tuzlu tenimle  Yaşlı gözlerle Ne masum bir aşkım var sana verecek Ne görülmemiş rüyalarım Nede pem...', ARRAY['Türk Edebiyatı','Şiir','Serkan Ertunç']::text[], 8.5, '{"poet":"Serkan Ertunç","poet_slug":"serkan-ertunc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sana-geliyorum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğimsin', 'sevdigimsin-serkan-ertunc-dplqt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gülün dikeni batarya ele, 

Batmışsın sende benim kalbime.

Çağlayan misali dökül kalbime

Sevsin kalbim seni ölesiye.

Ne olur inan sözlerime

Karşılık ver benim kalbime

Sana yemin ederim bu gençliğim üstüne

Seni  Seviyorum hem de delicesine.

Görmeden, bilmeden, birden, aniden

Sormadan etmeden kalbime giren

Bir kor olup derinden yanan içimden

AŞK ‘denen meçhul alevimsin SEN..!', 'Bir gülün dikeni batarya ele,  Batmışsın sende benim kalbime. Çağlayan misali dökül kalbime Sevsin kalbim seni ölesiye. Ne olur inan sözleri...', ARRAY['Türk Edebiyatı','Şiir','Serkan Ertunç']::text[], 8.5, '{"poet":"Serkan Ertunç","poet_slug":"serkan-ertunc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevdigimsin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Klorofilsizler!', 'klorofilsizler-yalcin-ergir-2gg8k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'çakıp kibritlerini

yaksalar da çıramızı

dökseler de tepemize

asit yağmurlarını

dikseler de yerimize

beton yapılarını

bu savaşı sonunda

mutlaka biz, 

klorofilliler kazanacağız...', 'çakıp kibritlerini yaksalar da çıramızı dökseler de tepemize asit yağmurlarını dikseler de yerimize beton yapılarını bu savaşı sonunda mutla...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergir']::text[], 8.5, '{"poet":"Yalçın Ergir","poet_slug":"yalcin-ergir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/klorofilsizler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dışarıda Kalanlar', 'disarida-kalanlar-erdal-noyan-dtjia', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Pervazında pencerenin

Yılların alışkanlığı kırıntılar

İstek başka bu defa

Cama vuruyor serçeler

Kar yağmıyor

Takvimden biliniyor kış

Kuşları ve evsizleri donduran

Ayazdan bir de

Yüreğini kaptırmıyor sıcağa

Pencereyi açıyor

Unuttuğundan kapıyı

Yalnızca serçeler kurtuluyor.', 'Pervazında pencerenin Yılların alışkanlığı kırıntılar İstek başka bu defa Cama vuruyor serçeler Kar yağmıyor Takvimden biliniyor kış Kuşları...', ARRAY['Türk Edebiyatı','Şiir','Erdal Noyan']::text[], 8.5, '{"poet":"Erdal Noyan","poet_slug":"erdal-noyan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/disarida-kalanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkı', 'sarki-erdal-noyan-wpivc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aynı değil her şarkı

Ama düşüyor hepsi

Sessizliğin kuyusuna

Alkışlı da uğurlansa 

Yarım kalmaz hiçbir şarkı

Söylendiği kadardır

Oynar avunuruz şarkımızın

Bestesiyle güftesiyle

Ve zavallı süresiyle

Değişir mi

Bir şarkı ne zaman en özgündür

Sustuğunda mı?', 'Aynı değil her şarkı Ama düşüyor hepsi Sessizliğin kuyusuna Alkışlı da uğurlansa  Yarım kalmaz hiçbir şarkı Söylendiği kadardır Oynar avunur...', ARRAY['Türk Edebiyatı','Şiir','Erdal Noyan']::text[], 8.5, '{"poet":"Erdal Noyan","poet_slug":"erdal-noyan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sarki-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adres: Düşler Ülkesi', 'adres-dusler-ulkesi-naime-erlacin-etwdl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bakmayın siz benim

iç karartıcı şiirler yazdığıma

öyle gülerim ki bazen 

kasılır kalırım gülmekten

inanamazsınız

hem deli 

hem  dolu 

deli-dolu olurum da 

tutamazsınız

hüzün kan kardeşim

onca yüzümden oysa

sadece biridir hüznüm

aldanmayınız! 

bin yüzü olmalı insanın

-yazacağım bunu

anlatacağım bir gün-

bırakınız çocuklaşmayı

yaprakla bile oynaşırım ben

yolunuz düşerse bana bir gün

sakın şaşırmayınız

ölüdeniz ruhumda açan 

nilüferlere bakın siz

sıkmayınız beni yeter

son şiir yazılmasa da olur

sadece bir “hayal”im ben

görmeye uğraşmayınız! 

adresim: düşler ülkesi

yazınız dostlar

yazınız…

(26 Haziran 2003)', 'bakmayın siz benim iç karartıcı şiirler yazdığıma öyle gülerim ki bazen  kasılır kalırım gülmekten inanamazsınız hem deli  hem  dolu  deli-d...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/adres-dusler-ulkesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar', 'ruzgar-murat-tali-9xvrh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'En hızlı düşünen rüzgarmış

oysa

rüzgar düşünmez 

alır götürür önüne geleni

düşünceleri ona yetişemez 

yetişseydi rüzgarla yıkılmazdı ağaçlar 

kırılmazdı çiçekler boylu boyunca

hayatla büyük oynarmış rüzgar

Katar götürürmüş önüne tekneleri

Takaları, 

sandalları, 

kürekleri

Ve insanları 

ve dalgaları 

ve tozu toprağı

Yinede severim rüzgarı

Poyrazı, lodosu, keşişlemeyi, kıbleyi, yıldızı, karayeli, 

Yıldız karayeli

Birde

sam yellerini 

Sam yelleri gibi

sıcak ve 

hafif essin rüzgar

Sevgiyi ekerek toprağa

Rüzgar 

Yaşam demek bilir misiniz? 

Aldığı tohumları taşır uzak diyarlara

Eş eyler 

Çiçeklerle böcekleri

Sevgili eyler

Yapraklarla dalları

Toprağın en sırdaş dostudur rüzgar

Her gün üzerinden eser geçer 

Derdini, tasasını

ayak basmaların yorgunluğunu alır

Üzerinden

Ve kederlerini dağıtır 

Rüzgara verdim kendimi

Yıldız karayel ile 

Karadenizin dağlarına 

Sürüldüm 

damla damla 

Bazen bir çay yaprağına düştüm

Bazende bir tütün 

Karanlıktı Karadeniz 

Ama suskun değildi

Bir rüzgar vardı

Birde ben

Yıldız Karayel düşlerden

Sam yellerine düşen', 'En hızlı düşünen rüzgarmış oysa rüzgar düşünmez  alır götürür önüne geleni düşünceleri ona yetişemez  yetişseydi rüzgarla yıkılmazdı ağaçlar...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/ruzgar-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşli bir gün', 'gunesli-bir-gun-ozcelik-peker-8ljnv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüzgarda kırılmak üzere olan bir dalım

İsteğim bu uğultunun geçmesi

Yapraklarım benden gitti gideli

Çıplak bir ağacın yalnızlığındayım

Çok güneşli bir gündü

İnanmazsın gözlerim kamaşmıştı

O kadar şaşırdım ki

Yapraklanmakta kararsız kaldım

Sen geçmiştin ben de ağaç gibi kalmıştım

Bir gün rüzgar dinecek

Bir de yağmur yağmaya başlarsa

İçim içime sığmaz  o zaman

21.02.2002', 'Rüzgarda kırılmak üzere olan bir dalım İsteğim bu uğultunun geçmesi Yapraklarım benden gitti gideli Çıplak bir ağacın yalnızlığındayım Çok g...', ARRAY['Türk Edebiyatı','Şiir','Özçelik Peker']::text[], 8.5, '{"poet":"Özçelik Peker","poet_slug":"ozcelik-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gunesli-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feriha', 'feriha-aziz-ahmet-bulut-5ucwr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dalgaların ağıtları eşliğinde

ateş ve  Zerdüşt ün 

şahitliğinde

Artos un karşısında diz çökerek

and olsun diyorum.

birgün bir çift 

beyaz güvercin

yüreğimle

ellerinde

kana kana su içecek FERİHA..

bekle beni bekle.

düş ateşinde

kar sıcaklığında..FERİHAAA..', 'dalgaların ağıtları eşliğinde ateş ve  Zerdüşt ün  şahitliğinde Artos un karşısında diz çökerek and olsun diyorum. birgün bir çift  beyaz gü...', ARRAY['Türk Edebiyatı','Şiir','Aziz Ahmet Bulut']::text[], 8.5, '{"poet":"Aziz Ahmet Bulut","poet_slug":"aziz-ahmet-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/feriha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim!', 'kalbim-engin-kahraman-fktdn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Azra''ya

geleceğinden habersizdim kalbim! 

yollara düştüğünden habersiz

bağışla bir an tutukluğumu

açıp kapıyı girdiğinde göreceksin

seni neyin bekliyor olduğunu

sevgiyle var olunur bileceksin

kalbim! ne iyi ettin de geldin

bademlerin çiçek açışı gibi aniden

çoğaldım taşkın nehirler gibi... 

durdurdu bir an için zamanı

parmaklarıma dolalı saçının kıvrımı

sen serin, büyülü ve masaldan öte 

öyle bir bahçe içindesin şimdi 

kaybolmayan bulutlar altında

uyu kalbim uyu, uğurla gölgeni

öpeceğim seni her uyanışında

sıcak camlara sessizce düşen 

esirgeyici damlalar gibi', 'Azra''ya geleceğinden habersizdim kalbim!  yollara düştüğünden habersiz bağışla bir an tutukluğumu açıp kapıyı girdiğinde göreceksin seni ney...', ARRAY['Türk Edebiyatı','Şiir','Engin Kahraman']::text[], 8.5, '{"poet":"Engin Kahraman","poet_slug":"engin-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kalbim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Dersin...', 'ne-dersin-guzin-sirin-gedik-n6ozh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Belki imkansız belki bir o kadar karanlık

Bir duygu karmaşası  bu; Sevgi değil, aşk değil

Tarifin içinde bir tutam Alışkanlık 

Benzer tatlar hissedilen ama  adı  yok.

Yaşanan ise; 

Kaygısızca, bağlanmadan, 

Özgürlüğünde ötesinde

Bir kuş misali

Belki bir şahin asilliğinde...

Kelimeler yasaklı

Yasaklar gelir ya  bir o kadar tatlı! 

An gelir haykırmak istersin 

Sessizce, sevgini gönlünce...

Ama tutuklu kalır  soluğun, 

Yaralı kalır heceler, dudakların gerisinde...

Hangisi doğru? 

Olması gerekenler, olmasını arzu ettiklerin? 

yanlış olan  ne? 

Hissetmek, insanlığınca onu  özümsemek mi? 

Yoksa; 

Bahar’a  inat doğruluğun peşinden sıra adımlarla kış’ı  izlemek midir? 

......sen ne dersin? ......', 'Belki imkansız belki bir o kadar karanlık Bir duygu karmaşası  bu; Sevgi değil, aşk değil Tarifin içinde bir tutam Alışkanlık  Benzer tatlar...', ARRAY['Türk Edebiyatı','Şiir','Güzin Şirin Gedik']::text[], 8.5, '{"poet":"Güzin Şirin Gedik","poet_slug":"guzin-sirin-gedik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ne-dersin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesap', 'hesap-ozcelik-peker-hjzwr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey hayat sana sorarım! 

Bu rüzgar kime sevdalı böyle? 

Deli deli esmediği gün yok

Sanki kendi ateşini soğutur

Dağlardan iner şehre kaçar

Şehrin öpmediği yerini bırakmaz

Ey hayat sana sorarım! 

Ne yaptın ha bu bulutlara? 

Söylediklerin çok üzmüş

Ağlamadıkları yer görülmemiş

İnsanların göz yaşları olsaydı biterdi

Ey hayat sana sorarım! 

Seni sevenler mi çok iyimser? 

Yoksa ben mi karamsarım? 

İyiliklerini unutuyorum demek

Yaptıkların hep hatırımda

Kurtulmak basit senden

Ne zaman mı? 

Ölür ölmez

15.04.2002 pzr', 'Ey hayat sana sorarım!  Bu rüzgar kime sevdalı böyle?  Deli deli esmediği gün yok Sanki kendi ateşini soğutur Dağlardan iner şehre kaçar Şeh...', ARRAY['Türk Edebiyatı','Şiir','Özçelik Peker']::text[], 8.5, '{"poet":"Özçelik Peker","poet_slug":"ozcelik-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hesap-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmza', 'i-mza-ozcelik-peker-flceo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdam senden bir isteğim var

Her sabah kimse sormasın seni sevdiğimi

İlkin hava başlıyor yağıyor, yağıyor

Sonra rüzgar bana, bana esiyor

Hepsi senden görevli

Hele, hele deniz kıyısında isem

Her dalga “Seviyor musun? ” diyor

Bir gün bir bağırdım “Seviyorum” diye

İşte o gündür hiç kimseye “Seviyorum” demedim

Rüzgara “Uçur beni sevdiğime” dedim

Karşılık olarak ömrümü al istersen

“Sadece sevdanı taşırım” dedi

Tüm aşkımı verdim rüzgara

Aç pencereni içine dolsun

Hayatında göğsünün solunda

Benim bir imzam olsun

15.04.2002 pzr.', 'Sevdam senden bir isteğim var Her sabah kimse sormasın seni sevdiğimi İlkin hava başlıyor yağıyor, yağıyor Sonra rüzgar bana, bana esiyor He...', ARRAY['Türk Edebiyatı','Şiir','Özçelik Peker']::text[], 8.5, '{"poet":"Özçelik Peker","poet_slug":"ozcelik-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/imza-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurma', 'kurma-ozcelik-peker-nbwyg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayallerin de vurulduğunda 

Gerçekte ölmeyeceksen 

Zaten hiç kurmada 

Zamanına yazık olmasın

04.05.2002', 'Hayallerin de vurulduğunda  Gerçekte ölmeyeceksen  Zaten hiç kurmada  Zamanına yazık olmasın 04.05.2002...', ARRAY['Türk Edebiyatı','Şiir','Özçelik Peker']::text[], 8.5, '{"poet":"Özçelik Peker","poet_slug":"ozcelik-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kurma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saksı', 'saksi-ozcelik-peker-8b193', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İstasyona geldin

Merdivenlerden çıktın

Büyük salon önünde

Sağda peronlar

Solda gişeler

Peronlara giden yolda

Bekleme salonu

Köşedeki saksıyım ben

Sabah akşam sulayın kurumasın

Sevgini damlayla ölçtüğümü sanma

Yağmur yanında halt etmiş

İnsanlar hep sevdiklerin bekler çevremde

Bende öyle

01.01.2002', 'İstasyona geldin Merdivenlerden çıktın Büyük salon önünde Sağda peronlar Solda gişeler Peronlara giden yolda Bekleme salonu Köşedeki saksıyı...', ARRAY['Türk Edebiyatı','Şiir','Özçelik Peker']::text[], 8.5, '{"poet":"Özçelik Peker","poet_slug":"ozcelik-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/saksi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kesit 1', 'kesit-1-aziz-ahmet-bulut-7sqfw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'onurluydu yaprak 

karıncalanmış dalını

gördüğü o ana kadar.

şahidim ben

rüzgarla sevişerek

döne döne, usulca

toprakla kucaklaştı

vefasızca.

suçsuzum seyirciydim ben

rüzgardı onu cezbeden

dalından koparan

ve sonra toprakla üzerini örten.', 'onurluydu yaprak  karıncalanmış dalını gördüğü o ana kadar. şahidim ben rüzgarla sevişerek döne döne, usulca toprakla kucaklaştı vefasızca. ...', ARRAY['Türk Edebiyatı','Şiir','Aziz Ahmet Bulut']::text[], 8.5, '{"poet":"Aziz Ahmet Bulut","poet_slug":"aziz-ahmet-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kesit-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmen için', 'sevmen-icin-ozcelik-peker-so66i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yere düşer yürek tuz buz olur

Dağılmış bardak gibi kimsesiz

İsteğim üzerime basman

Ayakların kanasa bile

05.05.2002', 'Yere düşer yürek tuz buz olur Dağılmış bardak gibi kimsesiz İsteğim üzerime basman Ayakların kanasa bile 05.05.2002...', ARRAY['Türk Edebiyatı','Şiir','Özçelik Peker']::text[], 8.5, '{"poet":"Özçelik Peker","poet_slug":"ozcelik-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevmen-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyahla beyaz', 'siyahla-beyaz-ozcelik-peker-tulol', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çok değerli bir şey keşfettim

Hayatın anlamını

Belki anlatamam 

Yada anlamazsın 

Kendi kendineyken anlayamazsın

Bunu sana başkası verecek

Herkesinki bir başkasında 

Onu arıyoruz oda bizi 

Söyle oluyor bir zamanlar

Aşıkken, elim ayağım tutmadığı günlerde

Kimler, kimler jestler yapmış ona benden önce

Hepsi başarısız kalmış benden yakışıklılar

Sessizim tek başınayım ona yazıyorum 

Dedim ki ben olmasaydım bu kadar özel miydi? 

Yada başkası olsaydı, başkası geçseydi benden 

onun değeri bu kadar artar mıydı? 

İşte ben ona hayatımın anlamını verdim 

Anlatmadığım için bilmiyor yok sanıyor

Bazen buluruz da niyeliğimizi söylemezler

Ne olur herkes anlatsın herkes bilsin

13.06.2002', 'Çok değerli bir şey keşfettim Hayatın anlamını Belki anlatamam  Yada anlamazsın  Kendi kendineyken anlayamazsın Bunu sana başkası verecek He...', ARRAY['Türk Edebiyatı','Şiir','Özçelik Peker']::text[], 8.5, '{"poet":"Özçelik Peker","poet_slug":"ozcelik-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/siyahla-beyaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kesit 2', 'kesit-2-aziz-ahmet-bulut-r4b09', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'küflenmiş suda

hançer kokusu

ahh  yüreğim

etten tabut içinde

ölüyorum

ö

l

ü

y

o

r

s

u

n

tedbil aşk uğruna..', 'küflenmiş suda hançer kokusu ahh  yüreğim etten tabut içinde ölüyorum ö l ü y o r s u n tedbil aşk uğruna.....', ARRAY['Türk Edebiyatı','Şiir','Aziz Ahmet Bulut']::text[], 8.5, '{"poet":"Aziz Ahmet Bulut","poet_slug":"aziz-ahmet-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kesit-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Sonra', 'senden-sonra-aziz-ahmet-bulut-xhwtp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'senden sonra bir başka sevdim.

Mecnun nun düşünde öldüm

Leyla nın saçlarında 

intihar ettim.

senden sonra bir başka sevdim.

sevdiğime sevindim, birde sevilmediğime.

senden sonra bir başka sevdim

herşeyi ve hiç bir şeyi..', 'senden sonra bir başka sevdim. Mecnun nun düşünde öldüm Leyla nın saçlarında  intihar ettim. senden sonra bir başka sevdim. sevdiğime sevind...', ARRAY['Türk Edebiyatı','Şiir','Aziz Ahmet Bulut']::text[], 8.5, '{"poet":"Aziz Ahmet Bulut","poet_slug":"aziz-ahmet-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/senden-sonra-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Mavi', 'hep-mavi-aziz-ahmet-bulut-cvx2m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''canına aşk düşmüş gibi''

uçurtması yıldızlara 

takılan çocuk

aynı yerde

aynı saate

hep ölürdü

sonrası hep mavi  olurdu..', '''canına aşk düşmüş gibi'' uçurtması yıldızlara  takılan çocuk aynı yerde aynı saate hep ölürdü sonrası hep mavi  olurdu.....', ARRAY['Türk Edebiyatı','Şiir','Aziz Ahmet Bulut']::text[], 8.5, '{"poet":"Aziz Ahmet Bulut","poet_slug":"aziz-ahmet-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hep-mavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimle evlenir misin?', 'benimle-evlenir-misin-mehmet-salih-guven-k8bhu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sensiz doğan güneşi, sadece senin ay yüzünle

örtüşmeyen ''ay''ı istemiyorum artık. Ama

gülümsemendeki o parıltı, o efsanevi sıcaklığın

dolduruyor yüreğimi. Seni seninle birlikteyken bile

özlediğimi anımsıyorum sonra. Sensiz zamanlarda, 

milyonların içindeki yalnızlığımla başbaşa kalıyorum.

kalbim sana, sadece sana dönük. Beynimin ürettiği

dalgalar sana ait. Gel pamuğumgel kartanem, 

kırçiçeğim, esir ruhların özgürlüğe hasret kaldığı

gibi hasretim sana. Beni evrenin en mutlu erkeği yapar mısın? Sonsuz mutluluğun, sınırsız sevginin oldduğu bir

hayat kuralım. Benimle evlenir misin? 

NURAY seni çok ama çok seviyorum. Sevgi ölümsüzdür, 

sevgi paylaşımdır; ölümsüz sevgiyi paylaşalım.

                                                       ölümsüz sevgi anısına

                                                          26.06.2003', 'Sensiz doğan güneşi, sadece senin ay yüzünle örtüşmeyen ''ay''ı istemiyorum artık. Ama gülümsemendeki o parıltı, o efsanevi sıcaklığın dolduru...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Salih Güven']::text[], 8.5, '{"poet":"Mehmet Salih Güven","poet_slug":"mehmet-salih-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/benimle-evlenir-misin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir kırık ayna', 'bir-kirik-ayna-zeynep-nihal-akpinar-nrwgz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir kırık ayna 

Önunde bir kız cocugu duruyor üşümüş

Yaslamış gozlerini ayna kırıklarına

taralı sacları inmis gozlerinin üstüne

Bir gülüşle bir damla gozyasından ote

Kırık kollu bebeğini de kucağından düşürmüş

Sormamışlar orerken saçlarını 

Hüznü reva gormusler küçük ellerine

Oysa o şekeri hic bitmesin istermiş, birde ellerine kına

Birde gittigi lunaparktan hic gelmemeyi

Donerken babasının kucağında uyuyakalmayı dilermis.

Ve sen küçük kız

Kırmızı şapkanı hic çıkarma yüreğinden

Bırak yolver dönüp gitsin giden

Gozlerinin karasına hic değdirme gözyaşını

Kırıksada ayna yitip gitmissede özlenen

Bekle hiç bitirme sakın dilindeki masum şarkını..', 'Bir kırık ayna  Önunde bir kız cocugu duruyor üşümüş Yaslamış gozlerini ayna kırıklarına taralı sacları inmis gozlerinin üstüne Bir gülüşle ...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Nihal Akpınar']::text[], 8.5, '{"poet":"Zeynep Nihal Akpınar","poet_slug":"zeynep-nihal-akpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-kirik-ayna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmalıyım', 'unutmaliyim-sair-turuncu-rmqx8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'küçük kız çocukları var içimde görmüyorsun

sen de benim gibi parça parçasın oysa

sen de boğazına kadar pisliğe batmışsın

en güzel renklerimi veririm sana, 

tüm yaşamımı

karaysa için kuşlar getiririm, göçmen kuşlar

seviyorum seni

kim ne derse desin

zamanın  sonuna kadar seveceğim

ne olursa olsun..

hani kim almış düşlerimi benden? 

hani kim sever seni benim gibi..

yinede sevmiyorsun beni

benim rengimde değilsin

başka tenlere vurgunsun 

bilirim, yorgunsun

suskunsun bana

ama doluyum sana ağzıma kadar

gönlümden, en dibe kadar

mısrayım sana..', 'küçük kız çocukları var içimde görmüyorsun sen de benim gibi parça parçasın oysa sen de boğazına kadar pisliğe batmışsın en güzel renklerimi...', ARRAY['Türk Edebiyatı','Şiir','Şair Turuncu']::text[], 8.5, '{"poet":"Şair Turuncu","poet_slug":"sair-turuncu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/unutmaliyim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-abdullah-karabag-bqx3n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Malabadi’nin kemerine

Konan güvercin

Bana bir kart yolla

Acıyı

      kini

          öfkeyi

Tüm gadre uğramışlığı

Bir yana bırak

Yaz

Kınalı tırnak ucuyla

Kürdü

      karanfil

Asuri

        nergiz

Türkmeni

       yabangülü

Ermeni

       gelincik

Rumu

       nilüfer

Gürcü

      çiğdem

Lazı

     kardelen

Çeçeni

      narçiçeği

Acemi

       zambak

Arabı

       menekşe

İbrani

       yasemin...

Dar mı geldi kâğıt

Ser gönlünü dök üstüne

Kara afrikayı

           sarı asyayı

                beyaz avrupa

                   kızıl amerikayı

Birileri mi kaldı

Denizin atlasında

                      onu da al

Koy

Resmini imza yerine

Öyle gönder.

Güldestan Gibi, toplu şiirler, 2.baskı', 'Malabadi’nin kemerine Konan güvercin Bana bir kart yolla Acıyı       kini           öfkeyi Tüm gadre uğramışlığı Bir yana bırak Yaz Kınalı t...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karabağ']::text[], 8.5, '{"poet":"Abdullah Karabağ","poet_slug":"abdullah-karabag","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/ozlem-107-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eller', 'eller-abdullah-karabag-xy665', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'I

Bu eller

Şahin pençesidir

Sağlam baş ister

Zühre Yıldızı doğmadan

Çeliği halat eyler bendine

Sular Mezopotamya’yı

Bu eller

Aslan bileklidir

Everestler gibi bel ister

Alnı ak

Kara çalmaz alın terine

Yedi kıtanın

Tekmil denizin yükünü taşırken

II

Bu eller ancak

Düşüne vefasız

Gün devrilmeden devrilir

Eli boş

Fabrika çıkışı

Liman dönüşü

III

Bu eller

Zerdüşt afsunlu

Hürmüz hüneri

Gılgamış özlemidir

Sin-Leke’nin

Bir adım sonrası

Helen şafağıdır

Sokrates mahkemesi

Bilimin ebesi

Düşüncenin duruşması

IV

Bu eller

Kırk gözlü sevda pınarı

Kuşlar söyleşir 

Feqiye Teyran sofrasında

Ah’ında bulur Aslı‘yı Kerem

Yeniden dirilir Aziz Valentin

Prenses Dulsina’dır İberya’ da

Don Kişot’unu yaratır

V

Burası

Nil boyu değil 

Kalmaz ayakta Ramsesler

Terazisi yok elinde Oziris’in

Burası

Munzur Vadisi 

Gülü kan ağlar

Bir kadın 

Amazon tanrıçası

Yürür üstüne zulmün

Volkana döner güzelim

Güzelliği sığmaz kaleme.

Güldestan Gibi, toplu şiirler, 2.baskı', 'I Bu eller Şahin pençesidir Sağlam baş ister Zühre Yıldızı doğmadan Çeliği halat eyler bendine Sular Mezopotamya’yı Bu eller Aslan bileklidi...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karabağ']::text[], 8.5, '{"poet":"Abdullah Karabağ","poet_slug":"abdullah-karabag","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/eller-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-abdullah-karabag-5hudh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni

Soluksuz gecede

Yıldızların

Dansında görmüşüm

Yılanlı düşte 

Engereğin ağzından almışım 

Acıların ezgisinde

Yaratanın yüreğiyle sevmişim

Dudaklarıma dokunmadan 

Ellerime 

Kına yak  benim

Koynuma girmeden

Yatağıma

Gül dök benim.

Güldestan Gibi, toplu şiirler, 2.baskı', 'Seni Soluksuz gecede Yıldızların Dansında görmüşüm Yılanlı düşte  Engereğin ağzından almışım  Acıların ezgisinde Yaratanın yüreğiyle sevmişi...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karabağ']::text[], 8.5, '{"poet":"Abdullah Karabağ","poet_slug":"abdullah-karabag","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sen-268-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrım', 'tanrim-giray-ozer-6k41x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tanrım, 

Biz bir akvaryumda kaybolmuş iki fakir ruh.

Kollarımız olmasaa sevgiyle sarıldık geleceğe.

Bir iç çekişi uzaklıkta, ayrı kalıp

Bir nefes veriş kadar yakın olduk birbirimize

Ağladık geçmişimize, güldük geleceğimize

Yorulduk, ezildik, kırıldık kaderimize.

Şimdilerde, dünyaları beraber yaşamak isterken

Tek dileğimiz, ölsek de ayırma bizi bizde.', 'Tanrım,  Biz bir akvaryumda kaybolmuş iki fakir ruh. Kollarımız olmasaa sevgiyle sarıldık geleceğe. Bir iç çekişi uzaklıkta, ayrı kalıp Bir ...', ARRAY['Türk Edebiyatı','Şiir','Giray Özer']::text[], 8.5, '{"poet":"Giray Özer","poet_slug":"giray-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tanrim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mehemedê Benlî', 'mehemed-benl-abdullah-karabag-tuczz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-Bu Memed nasıl kurtulur-

1

Tanıktır

Bilge Fırat tanık

İsyan besler koynunda

Yerin yedi katına tutsak

Tarihi ayaklandırarak

Sanıktır

Koca Fırat sanık

Dalında şahin yuvasıdır

Şikefta bûk û zavan

Dersanesi

Can yoldaşların

On İki Eyül öncesi

2

Yıl

Bindokuzyüz seksenyedi

Mevsimlerden yaz

Yine geldik sana 

Şen ola

Kemerli Mezrası

3

Kimdi

Neciydi

Ne gerek var

Sual etmeye

Güne

Gün gözüyle bakmayınca

Namı diyarı

Diyarından aşırı

Bir adı

Mehemedê Benlî

Bir adı

Benli Memed

4

Avcundaydı yüreği

Daha da avuçladı

Vardı köy odasına

Mustafa Bey’in makamı

İkramı bol

Hürmeti sinsi

Bey’in silik turası

Kahya Mehmet Ali’nin

Çullandı üzerine

Rayber ruhlu

Birkaç köylü

Bağlandı eli kolu

Haber salındı karakola

5

Potin dipçik

Darbeleriyle  indirildi

Taş yığma toprak dama

6

Osmanlı kırma’sı

Bezirgân başı

Vehbi Efendi’nin

Tutmasıydı biçare anası

Sivilinde

Sığır güderdi

Ankaralı Çopur Memed

Gözde askeriydi komutanın

Zulüm kusarken

Köy baskınlarında

Tutmalığın

Fukarılığın

Baş sebebiydi bu köyler

                        Kürt köyleri

Böyle bellemişti

Ankaralı Memed Çavuş

7

Derken rivayeten

Rivayeten denilir ki

Balkanlar’dan Yemen’e

Yemen’den Magrib’e

Kara kalpak-yalın kılıç 

Aymazlığın kör neferleri

Memedlerin mehmetçiği

Biri durur

Beşi vurur

Zalimin cümlesine

Duaya sayılır işkenceleri

Kırılan

Koldu ayaktı

Süngülerde dokunan

Umuttu yürekti

Benli Memed’in

Yoluna toy

Uzun yolun yolcusu

Yunusça dingin

Nesimice direngen

Mem û Zîn gibi sevdazar

Kızıldağ’ın Benli Memed’i

8

Memed’im

Yaşarım her şeyi yeniden

Bir yanım Mehemedê Benlî

Bir yanım Benli Memed

Birlikte türküler söyledik

Emek üstüne

Berdar edilen

‘Üç fidan’ üstüne

Şartel indirdik

Halay çektik

Deste gül olduk zindanlara

Kefen gömlek

Eyledik biz yaşamı

Çabuk tut ellerini

Benim kavga’m

Seninle değil

Deli Memed

Divane Memed

9

Takat kalmayınca

Mehmetçik memedlerin

Ateşe verdiler

Taş yığma toprak damı

Ve kurşun yağmuru

Vay li min

Ferman eski ferman

Aman’ı yok yaman’ı yok

Ankaralı Memed Çavuş’un

10

Memed’im

Yaşarım her şeyi yeniden

Bir elim Mehemedê Benlî

Bir elim Benli Memed

Yalnız değilim

Bütün sevdam başucumda

Damla damladır belleğim

Ak benekli nar çiçekleri

Dalında kuş cıvıltıları

Gölgesinde çocukluğum

Elim varmaz yaş’a

Türkü söyler dilim

Tepemdeki yavru kuşa

Ey güzel ülke’m

Sırmalı güneş ülke’m

Yaz yağmuru

Toprak kokmuyor

Kan-karanfil kokan ülke’m

11

Duman

Dumana dolanır

Dam

Dumana boğulur

Üç çöp kibrit ışıldar

Tenli duman ortasından

 Dirilişidir mazlumlar’ın

Çarpar kanat

Kollarındayım dörtler’in

Dörtler bir şiir

Onsekiz mayıs ezgisiyle

12

Memed’im

Yaşarım her şeyi yeniden

Bir gönlüm Mehemedê Benlî

Bir gönlüm Benli Memed

Yalnız değilim

Bütün sevdam ayakta

Bayırında

Oğlak-kuzu güdüşümüz

Düzünde

Çelik-çomak tutuşumuz

Doruklarında

Silah çatışımız

Bir düş mü dersin

Yaralı düşler kaçağı

Bir şeyler düğümlenir

                         şuramda

Zagros eli’nden

Kemerli Mezrası’na

Hawarlaşan halepçe türküsü

Bu

Kaçıncı Enfal’dır

Başımıza yağan

Ve

Binlerin

Ve

Yüzbinlerin kaçışı

13

Yeşil alevlerle

Sarsılırken taş yığma dam

Yanık sesinden Mehemedê Benlî’nin

Meze olacaksa

Dostlar sofrasına sözüm

Kavlinden evvel paslanacaksa silahım

Kırmayacaksa ölü kabuğunu

Toprağa düşen cemre kanım

Garip anam

             nazlı anam

Mezarıma

Çiçek konulmasın

Adıma

Türkü yakılmasın

14

Derken rivayeten

Rivayeten denilir ki

Çıkageldi savcı hakim

Divan kuruldu

Divana alındı

Kömür bedeni Mehemedê Benlî’nin

“Maktule ait bomabanın

infilakından vaka

hasıl olmuştur” dedi

Hipokrat yeminli Memed

15

Son defa yokladı

Ankaralı Memed Çavuş

Bir muska

Göğsünde Mehemedê Benlî’nin

Muska içinde bir muska

Yeşil çuha içinde

Şalın altın rengine

Gülen gelincik alıyla işlenmişti

Sarı çiğdem perçemli dotmam

Sen ve Ben

Nişanlıyız  bu topraklara

Serxwebûn’dur düğünümüz

Hayli zaman oldu görmeyeli

Öp benim için

Ellerinden anamın

An neman an Kurdistan! 

Güldestan Gibi, toplu şiirler, 2.baskı', '-Bu Memed nasıl kurtulur- 1 Tanıktır Bilge Fırat tanık İsyan besler koynunda Yerin yedi katına tutsak Tarihi ayaklandırarak Sanıktır Koca Fı...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karabağ']::text[], 8.5, '{"poet":"Abdullah Karabağ","poet_slug":"abdullah-karabag","theme":"Türk Şiiri","is_hero":false,"total_lines":223,"source_url":"https://www.antoloji.com/mihemede-benli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ladeslim', 'ladeslim-abdullah-karabag-ludn5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hongkong sahili değildi

Pekin ördeği de yoktu masada

Ateşin

Köşkünde tutuştuk

Acına

Elveda diyeyim ladeslim

Ayrılığın

Perçemine manolya taktım

Resminden esinlenir

Sahne düşer payıma

Tek kişilik sensizlik

Işıklar ak sakallı

Bin bir gözün

Dişlediği eğlemcem

Nazdan

Besteye dolan

Yıldızı

Gölgesinden çalan

Kahrına

Bilenen sevdam.

Güldestan Gibi, toplu şiirler, 2.baskı', 'Hongkong sahili değildi Pekin ördeği de yoktu masada Ateşin Köşkünde tutuştuk Acına Elveda diyeyim ladeslim Ayrılığın Perçemine manolya takt...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karabağ']::text[], 8.5, '{"poet":"Abdullah Karabağ","poet_slug":"abdullah-karabag","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ladeslim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Milis Çocuk', 'milis-cocuk-abdullah-karabag-l22h2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir ocak newroz’dum

Kavli belâdan beri

Ha

Bozkır döşünde

Ha

Dağ başında

Nice

Kış gördüm

Tufan

Nice

Bahar gördüm

Şavkı dilber

Yaşam

Budur dedim

Çiçeğe durdum 

Aldanmışım

Palete 

      potine

              bere

Kırıma

        sürgüne

                denek

her bir yanım

Bir gözüm 

        kurşun yuvası

Bir gözüm

        telli duvaklı gelin

Yüreğim

         hıncahınç yürek

Toprağıma sarıldım

İnadım 

         inattır

              diyerek

Bu

Nasıl tarihtir

                 yazmaz

Kaleminden darağacı

Kurmuş haneme

Düşmüşüm

Düşürülmüşüm

Kararmadı cevherim

Bızıra durur umudum

Umutların en güzeli

      KAVGA GÜNÜ’nde

                              deşilmek

Bekledim

Yüreğim ateşte

Erişilmez dağların

Karını bekler gibi

Bekledim

Koynunda kitap

Elinde 

      kaval

Çoban çocukla

Dudak

     dudağa

           gelene

                  dek

Türküsü

Al kana boyanan çocuk

Taranmıştı

             sarat

                 sarat

Toyluğundan değil

Tetiğe uzanan

Ellerin kahpeliğinden

Aşa-yima damlıyordu

Dudaklarından

Dudaklarıma

Emdim

      canlandı

Emdim

   açıldı gözleri

Emdim

       güldü

Can derdinde değildi

                         bu çocuk

Delice kavramıştı kavalı

Paramparça göğsüne

Gömüyordu

Newroz’a dönüşsün diye

Ben

Newrozluğumdan utandım

Bir karış toprağı

Newrozlaştıramadım 

                             diye! 

Güldestan Gibi, toplu şiirler, 2.baskı', 'Bir ocak newroz’dum Kavli belâdan beri Ha Bozkır döşünde Ha Dağ başında Nice Kış gördüm Tufan Nice Bahar gördüm Şavkı dilber Yaşam Budur ded...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karabağ']::text[], 8.5, '{"poet":"Abdullah Karabağ","poet_slug":"abdullah-karabag","theme":"Türk Şiiri","is_hero":false,"total_lines":87,"source_url":"https://www.antoloji.com/milis-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açlık', 'aclik-abdullah-karabag-qppop', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aç mı kaldın

Önemli değil

Bir şeyler

Bulur yersin

Aç mı kaldın

Üç gün beş gün

Ya da aylar

İşte tenin

Ye yiyebildiğin kadar

Sakın

Düşlerini yeme

Yersen düşersin

Seni

Aç koyanların sofrasına! 

Güldestan Gibi, toplu şiirler, 2.baskı', 'Aç mı kaldın Önemli değil Bir şeyler Bulur yersin Aç mı kaldın Üç gün beş gün Ya da aylar İşte tenin Ye yiyebildiğin kadar Sakın Düşlerini y...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karabağ']::text[], 8.5, '{"poet":"Abdullah Karabağ","poet_slug":"abdullah-karabag","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aclik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özüne Vugunum', 'ozune-vugunum-abdullah-karabag-50f2q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-Karayılan’ın anısına-

Seni yaşadım yine

Uzunca değil

       şöyle bir anlık

Gülün

     goncasında değil

İsmi konulmamış 

                   bir savaşta

İsimsiz bir dağ başında

   batan güneşin gölgesinde

      gülüşünde keleşlerin

Öyle sevdalıyım ki

Bülbüle avaza güle

Ve karayılan gibi sinen

Mevziden mevziye uçan

Gezi

       gözü

Haktan geçiren özüne

                      vurgunum.

Güldestan Gibi, toplu şiirler, 2.baskı', '-Karayılan’ın anısına- Seni yaşadım yine Uzunca değil        şöyle bir anlık Gülün      goncasında değil İsmi konulmamış                    ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karabağ']::text[], 8.5, '{"poet":"Abdullah Karabağ","poet_slug":"abdullah-karabag","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ozune-vugunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'The Heart', 'the-heart-turgay-kadiroglu-hrbga', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Follow the blood, cooming from my heart, 

And you will find the heart waited for you and died. 

Smell the smell of your own in that poor heart, 

The poor heart is nothing without your smelling. 

Watch the alone soul leaving that dead heart, 

While still feeling about loving you till the end. 

And finally take everything of yours from that heart, 

Just to be sure that, that heart is a dead...', 'Follow the blood, cooming from my heart,  And you will find the heart waited for you and died.  Smell the smell of your own in that poor hea...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/the-heart-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Gar Hüzünleri...', 'gar-huzunleri-naime-erlacin-9s3rp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'çanlar çalıyor durmaksızın

vahşi yankılanıyor ses

ölümden canlanıyor hücreler

gelenler var hayli kalabalık

giden tek bir yolcu

son şimendiferde

titreşiyor kampana

gar hüznüdür fışkıran 

uhrevi

derin bir düşten

vedadır acıyı çoğaltan

insan

acıda insan ancak 

acıda büyür her zaman

adı yok bunun 

ne ilk 

ne sonuncu

giden tek yolcu 

son şimendiferde

gar kendine kalabalık

yolcu kendine yalnız

tütsüleniyor buhurdan

hava ağır

zaman

susmak ve dinlemek zamanı

(26 Haziran 2003)', 'çanlar çalıyor durmaksızın vahşi yankılanıyor ses ölümden canlanıyor hücreler gelenler var hayli kalabalık giden tek bir yolcu son şimendife...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gar-huzunleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Aşkına Kal', 'yagmur-askina-kal-nuri-can-84j50', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni nasıl unuturum usul boylum, nazlı huylum 

yeşil gözlüm aybakışlım, bal sözlüm, gülnakışlım 

nasıl unuturum seni 

deniz yeşili gözlerini, ipek sarısı saçlarını 

kalbim kalbine düğümken 

ben seni sevdiğim zaman 

yağmur yağıyordu alanlara yeşil gözlüm 

sokaklar ağlıyordu 

kar yağıyor şimdi dağlara 

gitme kal 

yağmur aşkına kal 

gidersen 

gecenin siyahı çöker yüreğime 

kelebekleri göç eder ömrümün 

boynunu büker gelincikler 

dağlar ceylansız 

nehirler türküsüz kalır 

Gidersen 

tarlalar susuz 

çocuklar uykusuz kalır bahar gözlüm 

ben senin yürekkırgını gülüşünü sevdim en çok 

umutsuzluğa umudu sürüşünü 

acılara sevda yazışını sevdim 

kendinle barışını yeşil gözlüm 

seni seviyorum deyişini sevdim en çok 

tüm sevgiler sürgünken 

yaşamak bir türkü seninle bahar bakışlım 

yediveren tomurcuk 

gidersen boynu bükük kalır bu şehir 

ölür kahrından bu içli çocuk 

yokluğuna nasıl alışırım 

dudağın dudağıma mühürken 

ben senin en çok ince kırgın gülüşünü sevdim 

seni seviyorum deyişini 

bir ekmeği bölüşünü düşkünlerle 

öksüzleri sevişini sevdim 

ve yüzündeki hüznü yeşil gözlüm 

bakınca insan gibi bakışını 

ağlayınca çağlayanlar gibi akışını sevdim 

insanı sevişini sevdim en çok yeşil gözlüm 

omuzuna dayanmayı efkarlıyken 

ve affedişini sevdim düşmanını bile 

düşkünlere el uzatışını 

hayatın bu kirli sahnesinde temiz kalışını sevdim en çok 

bir umut gibi, bir türkü gibi, bir şiir gibi duruşunu 

bin bahar tazeliğinde, 

saçlarına günün vuruşunu sevdim 

ben senin bir gülü koparmasınlar diye 

günlerce gül düşmanlarına yalvarışını sevdim 

bir annenin acısına ağlayışını 

tüm kavramları ve kuralları çiğneyip 

küflenmiş törelere ve haksızlıklara karşı çıkışını sevdim 

ben seni beyaz beyaz sevdim yeşil gözlüm 

mavi mavi, yeşil yeşil, al al 

seninle sokaklar dolusu çığlık, acılar dolusu yalnızlık 

çiçekler dolusu sevgi ektik dağların doruklarına 

maviler boyunca beyaz güvercinler uçurduk meydanlara 

sınırlar çiçek açmaz dikenli teller içinde bahar gözlüm 

gitme kal 

yağmur aşkına kal 

ben seni sevdiğim zaman 

yağmur yağıyordu bu şehre 

kimsesiz çocuklar ağlıyordu sokaklarda 

biz bu şehrin gözyaşlarını sildik mendilimizle 

oturup yüreğimizin avlusuna çaresizliklere ağladık 

kar yağıyor şimdi dağlara 

gitme 

yağmur ve gözyaşı aşkına kal 

gidersen 

mutluluğumdan sızılar kalır yüreğimde 

yarım elvedalar kalır, soğuk odalar, karanlık geceler 

sensiz koma yüreğimi yağmur aşkına 

seninle başlayan hikayem 

seninle son bulsun yağmur gözlüm 

elveda demek zor şeydir bilirsin 

gitme 

yağmur aşkına kal 

Nuri CAN 1984 

www.nurican.com 

Muhteşem bir yorum dinlemenizi öneririm 

Ben seni sevdiğim zaman yağmur yağıyordu

http:www.youtube.com/watch? v=hwRQ2yz3NOw 

.', 'Seni nasıl unuturum usul boylum, nazlı huylum  yeşil gözlüm aybakışlım, bal sözlüm, gülnakışlım  nasıl unuturum seni  deniz yeşili gözlerini...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/yagmur-askina-kal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana geldim', 'sana-geldim-selvi-celik-loajy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kac yil gecti aradan.

Ben unuttum, sanki bir asirdi.

Hatirladinmi beni, can dost.

Sana inanmak icin geldim.

Sen hala ayni hala gencsin.

Yillar seni görmemis, sanki unutmus.

Boyrat bir yönden esmis, sana ugramadan.

Sana geldim yeniden yasamak icin.

Ne saclarina ak düsmüs.

Ne gözleriyin nesesi sönmüs.

Sanki yillar benden almis hirsini.

Yeniden genc olmak icin, sana geldim.

Yüreginin güzelligi yüzüne vurmus.

Gayesiz ve dertsiz olduguna, 

Cöküntülerin sende olmadigina.

Inanmak icin, sana geldim, 

Ne insanlarin degistigine, 

Nede dünyanin güzelliginin bittigine, 

Sevdalarin asklarin, sahte olmadigina.

Inanmak icin, sana geldim.

Dostlugun, kardesligin hala var olusuna.

Hatiralarin birgün cana gelecegine.

Unutulmayan birseylerin olduguna.

Inanarak, sana geldim.

Öyle bakma bana.

Hatirladinmi benim, ben.

Huysuz bitmeyen nesesiyle, hircin, 

Yillarin yuttugu, eski dost''un

Seni unutmadan sana geldim.

Yeniden dogmak icin.

kalbimde kaybolan asklarla sana geldim.

Gönül bahcemin güllerinin acmasi icin.

Herseye yeniden inanmak icin.

Seninle dogmak icin.

Sana geldim, dost.', 'Kac yil gecti aradan. Ben unuttum, sanki bir asirdi. Hatirladinmi beni, can dost. Sana inanmak icin geldim. Sen hala ayni hala gencsin. Yill...', ARRAY['Türk Edebiyatı','Şiir','Selvi Çelik']::text[], 8.5, '{"poet":"Selvi Çelik","poet_slug":"selvi-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sana-geldim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam Enver Gökçe', 'selam-enver-gokce-hikmet-karakus-ia76c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şen olasın Türkiyem dedin, 

Sevdamızı dize dize

              yana yana tükettin, 

Sessizce düştün yüreğimize

Ve yiğitçe bastın gittin

    alacakızıl bir bulut altından

                ardına baka baka

                dostlara, 

Selam Enver Gökçe

                selam sana..

(Ank.1981)', 'Şen olasın Türkiyem dedin,  Sevdamızı dize dize               yana yana tükettin,  Sessizce düştün yüreğimize Ve yiğitçe bastın gittin     a...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/selam-enver-gokce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba Manken Olacağım (Zamane)', 'baba-manken-olacagim-zamane-oznur-saka-ymrdm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu zamanda gözde meslek tek budur, 

Baba manken olacağım, 

İstersen kız, delir, istersen kudur, 

Baba manken olacağım.

Katlanamam yarısı boş fileye, 

Haftada bir çıkarım defileye, 

Sende katıl artık bu kafileye, 

Baba manken olacağım.

Senin hatrın için gitmem aşırı, 

Ya mayo olur ya iç çamaşırı, 

Çay içerim Paris’te gün aşırı, 

Baba manken olacağım.

Ne var bunda böyle şaşarım, hayret, 

Alışırsın sende, birazcık gayret, 

“Boynuzlu” derlerse  e  idare et, 

Baba manken olacağım. 

Mayoma bakarlar, etime asla, 

Zengin bir damada sırtını yasla, 

Sen hâlâ durmadan yobazlık tasla, 

Baba manken olacağım.

Her gece bir başka televolede, 

Gezerim baba sen ne söylesen de, 

Ne olursa olsun canım illede, 

Baba manken olacağım.', 'Bu zamanda gözde meslek tek budur,  Baba manken olacağım,  İstersen kız, delir, istersen kudur,  Baba manken olacağım. Katlanamam yarısı boş...', ARRAY['Türk Edebiyatı','Şiir','Öznur Saka']::text[], 8.5, '{"poet":"Öznur Saka","poet_slug":"oznur-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/baba-manken-olacagim-zamane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Elinden', 'gonul-elinden-oznur-saka-cs5b8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nedir bu başıma gelen ey gönlüm, 

Her gün bin dert çıkarırsın ortaya, 

Böyle mi geçecek bu koca ömrüm, 

Kapılırsın hemen yeni sevdaya.

Bırakmadın  rahat bir  gün göreyim, 

Engel olma bir murada ereyim, 

Uslan artık bir gönüle gireyim, 

Kahreder oldum bak  yalan dünyaya.

Ulaşılmaz bağlandığın sevdalar, 

Ona bakıp bakıp gözlerim dalar, 

Yalnızlığıma dost şu boş odalar, 

Doldururum, meyler kalkar havaya.', 'Nedir bu başıma gelen ey gönlüm,  Her gün bin dert çıkarırsın ortaya,  Böyle mi geçecek bu koca ömrüm,  Kapılırsın hemen yeni sevdaya. Bırak...', ARRAY['Türk Edebiyatı','Şiir','Öznur Saka']::text[], 8.5, '{"poet":"Öznur Saka","poet_slug":"oznur-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-elinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Defa', 'son-defa-oznur-saka-hlqjb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne kadar da severdim biliyorsun, 

O karanfilleri getir son defa, 

Neden beni sessizce dinliyorsun? 

Bu tatlı dilleri bitir son defa.

Bilmem bu günlere nasıl ulaştık? 

Neler engel oldu, neleri aştık, 

İstemem yorganı istemem yastık, 

Başımı dizinde yatır son defa, 

Bir yolunu bulup fikrime erip, 

Gönül bahçesinden özenle derip, 

“Seversin” diyerek gülleri verip, 

Elime dikeni  batır son defa.

Sözde ustasındır, üstatsın şair, 

Acı tatlı, iyi kötü vesair, 

Bildiğin ne varsa  sevdaya dair, 

Yazıversen birkaç satır son defa.

Bu defa yıkamam  gayrı bendimi, 

Unuttum inan ki kendi kendimi, 

Zaten yeşermeyen son ümidimi, 

Ne çıkar elinle yitir son defa.', 'Ne kadar da severdim biliyorsun,  O karanfilleri getir son defa,  Neden beni sessizce dinliyorsun?  Bu tatlı dilleri bitir son defa. Bilmem ...', ARRAY['Türk Edebiyatı','Şiir','Öznur Saka']::text[], 8.5, '{"poet":"Öznur Saka","poet_slug":"oznur-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/son-defa-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninim Hâlâ', 'seninim-h-l-oznur-saka-em8zh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin için yaratılmış bu yürek

Bu yüreğe olmadı senden âlâ

Sevda dedikleri bu olsa gerek

Bil ki  ömür boyu seninim hâlâ

Ellere baktığım kanma, yalandır

Benim gözüm sende hayli zamandır

Sende sevdiğime seni inandır

Ruhum bedenimle seninim hâlâ

Sana  öylesine bağlanmışım  ben

Adını koymuşum bir tatlı bela

Yar olmam ellere seni severken

Kıyamete kadar seninim hâlâ

Terk edilmek canım zor gelse bana

Başka yar aramam bağlıyım sana

Uğrunda bir ömür gelse en sona

Bil ki ilk gün gibi seninim hâlâ', 'Senin için yaratılmış bu yürek Bu yüreğe olmadı senden âlâ Sevda dedikleri bu olsa gerek Bil ki  ömür boyu seninim hâlâ Ellere baktığım kanm...', ARRAY['Türk Edebiyatı','Şiir','Öznur Saka']::text[], 8.5, '{"poet":"Öznur Saka","poet_slug":"oznur-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seninim-hala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkman mı Gerek+', 'yikman-mi-gerek-bayram-tunca-mxdbe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıkman mı gerek yıkman mı gerek

İllâ değerlerimizi yıkman mı gerek

Sıkman mı gerek sıkman mı gerek

İlle de şu canımı sıkman mı gerek

Çıkman mı gerek çıkman mı gerek

İlle de zıvanadan çıkman mı gerek

Yıkman mı gerek, yıkman mı gerek

Mutlaka, sarayımı yıkman mı gerek

Ah yar kırman mı gerek kırman gerek

İlle de kristal avizemi kırman mı gerek

Ağlatman mı gerek ağlatman mı gerek

İlle de zalim gibi, yalvartman mı gerek

İyilik yapmak varken kötülüğe ne gerek

Bu yaptıklarını bir bir kaydediyor melek

Sana lazım, yüzünü örtmen için bir elek

Mutlak bir gün hesabını soracaktır felek

Hem bak tamir zor, tahripse çok kolaydır

Yaptıklarınsa, vicdana sığmaz bir olaydır

Hem Nebimiz, örnek olmadı mı hepimize

Hem O, iyilik için yaratmadı mı hepimizi

Asiliği bırakıp çekidüzen verem kendimize

Dosta düşmana güldürmeyelim kendimizi

Hem Rabb’im, eşit yaratmadı mı hepimizi

Üstünlük bir tek takvadır der Nebimiz bize

16.06.2003-16:06

Aşk Ateşten Gömlek', 'Yıkman mı gerek yıkman mı gerek İllâ değerlerimizi yıkman mı gerek Sıkman mı gerek sıkman mı gerek İlle de şu canımı sıkman mı gerek Çıkman ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yikman-mi-gerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elif''im', 'elif-im-oznur-saka-knqm7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bana aşkı sorup durma, öğreneceksin, 

Aşk gecelerden daha zifirdir Elif’im, 

Ayrılık parçası aşkın, öğreneceksin, 

Ayrılıkta ölümle birdir Elif’im.

Bir araştır nedir beni sana bağlayan, 

Kalbim sever ancak gözlerimdir ağlayan, 

Bir ben miyim böyle iki gözü çağlayan, 

Nice sevipte ayrılan vardır Elif’im.

Bilmiyorum bu mudur ki aşkın kuralı, 

Bir kumar mıdır sevgi yazılı, turalı, 

Tâ ki Hakk sırtımıza bu yükü vuralı, 

Yüz mü, bin mi bu kaçıncı turdur Elif’im.

Dilekçeyi yazdırıp ta arzuhalcıya, 

Şikayet mi edeceksin beni savcıya? 

Öğren kısmetini gidip sor da falcıya, 

Belki bir başkası belki Öznur’dur Elif’im', 'Bana aşkı sorup durma, öğreneceksin,  Aşk gecelerden daha zifirdir Elif’im,  Ayrılık parçası aşkın, öğreneceksin,  Ayrılıkta ölümle birdir E...', ARRAY['Türk Edebiyatı','Şiir','Öznur Saka']::text[], 8.5, '{"poet":"Öznur Saka","poet_slug":"oznur-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/elif-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah özlemin bu kaçamak tutkusu', 'ah-ozlemin-bu-kacamak-tutkusu-mehmet-tombuloglu-nu6v5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Koyu bir sis dalgasının gölgelendirdiği yüzümde

sonsuz ürpertisini üstümde taşıdığım rüzgar

hep aynı düşünceden uzayan mesafeleri

hiç yorulmadan kat eden irade

pul pul düşlerinden serpilerek dökülüyor gibi

sabahların hercai alnına:

tutkuyla sonsuzluğun buluştuğu yere

lekesiz bir berraklıkla ta derinlerden kopup gelen

imgesel yolculuklara yön veren bu rüzgar

çekip çıkarıyor kendi yer çekimiyle

hiç elenmemiş sözleri: o, dudaklarımdaki

dünü bugün gibi yaşatan her neyse

bir sırrın kutbuna demir atmış

senden ve benden uzak ne varsa

bu ateş; ah özlemin bu kaçamak tutkusu

yıllarca menzilini perdelediğim sonsuzluğun içinde

hemen her gece şiire uzanır acemi ellerim

duyulur sesi, kısık bir veda cümlesinden

''bak hala yanıyor arzuları emrine verdiğimiz ateş

harlıyarak vaktin sönmeye yüz tutan közünü''

bir mührü kırar gibi heyecanlı

dökülür incelmiş bir duygunun çıkrığından böyle

akşamın ufuk çizgisinden dağılan gölgelerle

şiirin en tepesinden görürsün, sözcüklerin reveransını', 'Koyu bir sis dalgasının gölgelendirdiği yüzümde sonsuz ürpertisini üstümde taşıdığım rüzgar hep aynı düşünceden uzayan mesafeleri hiç yorulm...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tombuloğlu']::text[], 8.5, '{"poet":"Mehmet Tombuloğlu","poet_slug":"mehmet-tombuloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ah-ozlemin-bu-kacamak-tutkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık mektubu', 'ayrilik-mektubu-elif-sebnem-akal-uw05t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gelinmez gittiğin yollardan 

Bilirim....

Yüreğimde kül var artık, 

Sen

Y o k s u n....

Şenlik ateşleri yak da... danset keyfince

Başka

Yüreklerde

Başkalaşmış sevdaların... ne yazık, 

Öksüz oğlusun....

Dolaştığın kaygan zeminlere selam durarak, 

Unutursun...umarım, unutursun beni

Kan tükürerek...Acı haykırıp da

Köz ağlayarak....', 'Gelinmez gittiğin yollardan  Bilirim.... Yüreğimde kül var artık,  Sen Y o k s u n.... Şenlik ateşleri yak da... danset keyfince Başka Yürek...', ARRAY['Türk Edebiyatı','Şiir','Elif Şebnem Akal']::text[], 8.5, '{"poet":"Elif Şebnem Akal","poet_slug":"elif-sebnem-akal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ayrilik-mektubu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hissel Sıfır Düşünceler', 'hissel-sifir-dusunceler-sule-aydemir-3iik7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sıfır çarpı sıfır eşittir sıfır

sıfır çarpı bir ya da on yüz

eşittir sıfır

hep istediklerimiz ve bizde olan sıfırlar

ölen yakınlarım elde var sıfır

sevdalarım ayrılık elde var sıfır

sıfırı öğreniriz olmak istemediğimiz

anlamı var anlamsız olmak ki

aranır 

olmayan bildiğimiz

boşluk değer almadığında

hissel bir sıfıra

yükleriz bir özlem ki

korkumuz her yalnızlığa

sıfır biz olmadan daha', 'sıfır çarpı sıfır eşittir sıfır sıfır çarpı bir ya da on yüz eşittir sıfır hep istediklerimiz ve bizde olan sıfırlar ölen yakınlarım elde va...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hissel-sifir-dusunceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gönül', 'deli-gonul-murat-demir-32p2z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hata ettim hayatımda bir defa 

Huzur nerde çektiklerim hep cefa 

Ne durursun uy onlara sür sefa 

Deli gönül ömür bitti bitecek 

Vere vere ver kalmadı özümde 

Hiç bir şeyin önemi yok gözümde 

Onur dedim, hep ben durdum sözümde 

Deli gönül ömür bitti bitecek 

Gençlik geçti yaş yarıya dayandı 

Garip gönlüm hayatında hep yandı 

Eller gibi sendeki de bir candı 

Deli gönül ömür bitti bitecek 

Eller ayda mekan kurdu sen hala 

Kuş olupta konamadın bir dala 

Esir etme beni böyle ikbala 

Deli gönül ömür bitti bitecek 

Hedef belli hemen hemen dünyada 

Neden hala yaşıyorsun hülyada 

Ya tam yaşa adam gibi, öl yada 

Deli gönül ömür bitti bitecek', 'Hata ettim hayatımda bir defa  Huzur nerde çektiklerim hep cefa  Ne durursun uy onlara sür sefa  Deli gönül ömür bitti bitecek  Vere vere ve...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/deli-gonul-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düğün', 'dugun-bekir-gedikoglu-704u3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düğün

8 Ağustos 1984 te

Kader ile yapılmıştı,  büyük bir mukavele

Bugün eşim olan kadınla vermiştik el ele

Bir yıl önce kavil eyledik, girecektik gerdeğe

Babam hastaydı, birlikte gittik hastaneye

Sokacaklardı 8 Ağustosta onu ameliyathaneye

Doktora dedi ki “ bu tarihte gideceğim İstanbul’a oğlumu evlendirmeye”

“Ancak 9 Ağustos’ta gelip teslim olacağım ellerinize”

Ankara’da yapılan hesaplar, hep tutardı tarihte

Sokmamıştık feleği, biz bu işin içine

Ölümle evlilik yan yana geldi ye

Bak şu tesadüfe! ! 

Tarihte rastlanmaz  böyle bir gidişe

Öğrenin gerçeği yazıyorum işte

Ağır hasta Babam,7 Ağustos’ta biraz canlandı yine

Bu durum üzerine

Hemen gittim İstanbul’a, belirlenmiş tarihte evlenmeye

Şayet Babama bir şey olursa, düğünü erteleyip dönecektim geriye

8 Ağustos, gün yeni doğmuş duruyor eşikte

İstanbuldan salladım telefonu, Eniştemin Ankarada ki evine

Annem tembihlemiş ağlamak, bağırmak ve ağıt yakmak yoktu bu evde

Sebep? Ben duymayayım Babamın ölümünü, oğlum düğününü ertelemesin diye

Sordum telefonda “Ana babam nerede? ”

O da cevap verdi bana “sağlığı yerinde”, düğünü yapıp dön evine

Ana-Oğul arasında –yoktu yalan- bu alemde

Amma biri evlilikse, amma biri ölümse

...ve ikisi de Yüce  Allah’ın emriyse

Hiç kimse karşı gelemez bu emirlere

İşte tarihte, 

İlk kez girdi yalan, evimize

Bu gün saat 14 te evlendim

Saat 18 de dünya evine girdim

Saat 20 de Babamı, o gün saat 03’te kaybettiğimi öğrendim.

Saat 20 den ertesi gün saat 06 ya kadar ağladım

Arkadaşlarımın, kuaförde boyatıyor musun dediği

kapkara saçlarıma 10 saat içerisinde aklar bağladım

Bekir GEDİKOĞLU

Ankara,25.06.2003', 'Düğün 8 Ağustos 1984 te Kader ile yapılmıştı,  büyük bir mukavele Bugün eşim olan kadınla vermiştik el ele Bir yıl önce kavil eyledik, girec...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/dugun-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oy Baba', 'oy-baba-murat-demir-bv78t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gezerim yalın ayak

Oy baba fakir baba

Yoksulluk biz ne yapak

Vay baba garip baba

Çorap, lastik parası yok

Oy baba işsiz baba

Metelikle arası yok

Ağzında dişsiz baba

Köyünün en fukarası

Oy baba yoksul baba

Ne bağı var ne tarlası

Vay baba yurtsuz baba

Bağırsan kimse duymaz

Oy baba sessiz baba

Dert derde derman olmaz

Mekânsız yersiz baba

Kara kara düşünmekle

Yılların geçti baba

Ecel dediğin sonunda

Seni de seçti baba', 'Gezerim yalın ayak Oy baba fakir baba Yoksulluk biz ne yapak Vay baba garip baba Çorap, lastik parası yok Oy baba işsiz baba Metelikle arası...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/oy-baba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin Yıl', 'bin-yil-bekir-gedikoglu-2xzg7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bin Yıl

Bin yıl gözlerine baksam

Ben hiç bıkmam

Bin yıl kollarım belinde kalsa

Ben hiç yorulmam

Bin yıl saçlarını tarasam

Ellerimi ağrıtmam

Bin yıl seninle sohbet etsem

Ooff bile demem

Bin yıl ellerin avuçlarımın arasında kalsa

Parmaklarımı oynatmam

Senin terzin olsam

Bin yıl sana elbise dikerim

Şarkı söylememi istesen sana bin yıl şarkı söylerim

Türkü söylememi istesen sana bin yıl türkü söylerim

Bu dünyayı gezelim desen

Seni bin yıl kucağımda taşırım

....İşte ben buyum

Seni...S.... desen! ! ! ! ! 

Bu dünyadan çeker giderim.

Ankara,24.06.2003', 'Bin Yıl Bin yıl gözlerine baksam Ben hiç bıkmam Bin yıl kollarım belinde kalsa Ben hiç yorulmam Bin yıl saçlarını tarasam Ellerimi ağrıtmam ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bin-yil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönderdiğim Güle Eklediğim Not:', 'gonderdigim-gule-ekledigim-not-turgay-kaygi-58u1a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sana seni sevdiğimi söylemek

çok pahalıya patladı bana

uğruna canımı bile verebileceğim gülümsemenden

mahrum bıraktın beni...

herşey karşılıklı değil mi? 

bak! 

ben sana bu gülü veriyorum; 

sen de 

allahaşkına

son bir gülüver yüzüme...

(edirne,27.06.2003)', 'sana seni sevdiğimi söylemek çok pahalıya patladı bana uğruna canımı bile verebileceğim gülümsemenden mahrum bıraktın beni... herşey karşılı...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gonderdigim-gule-ekledigim-not-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğumun Arka Bahçesi', 'cocuklugumun-arka-bahcesi-bekir-mutlu-gokcesu-qohl2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güzellikler örselendi, 

sevgi ile varolduk, unutuldu,

mutluluklar resimlerde dondu.

Düşlere dokunamadılar tek,

çocukluğumun arka bahçesi 

her şeye rağmen bende kaldı.

Bir selamı bile çok gördük 

tebessüm özürlü hale geldik.

Doyumsuz sohbetlerimiz vardı

gün ağarana dek bitmeyen,

az mı kurtarmıştık memleketi,

ne çapkındık hele,  ne hızlıydık.

Her şey çok uzaklarda kaldı

ama çocukluğumun arka bahçesi

dedim ya hep bende kaldı.

İçinden çıkamadığım an olur

gelir arka bahçem,

gelir dayanır aklıma,

açar kapılarını düşlerimin

alır götürür beni uzaklara,

açılır arka bahçem

açılır gönlümün diyarına...

Ey beni çeken diyar, 

ey gönlümdeki diyar,

tüm güzelliklerin düğümlendiği,

buram, buram sevda kokan diyar,

çağlayan suların, rüzgarın fısıltısında 

sessiz, sessiz akıp gittiği,

sevdalı bülbüllerin sabahlara dek

aşkın kitabını yazdığı güzel diyar.

Art niyet yok, kalleşlik yok  orada

toprak, anam gibi cevval, yürekli,

tüm güzellikleri üstünde taşıyor,

taşıyor da bana mısın demiyor.

Kıskanmıyor cevizden selviyi,

böğrüne, böğrüne vursam kazmayı

kesmiyor suyumu, ekmeğimi 

Bir gün, tüm sevdiklerimi takıp peşime

alıp götüreceğim

doğru çocukluğumun arka bahçesine

sonra yine bir kapıdan geçip 

ulaşacağız gönlümün diyarına.', 'Güzellikler örselendi,  sevgi ile varolduk, unutuldu, mutluluklar resimlerde dondu. Düşlere dokunamadılar tek, çocukluğumun arka bahçesi  he...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/cocuklugumun-arka-bahcesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nöbet Tutuyor Acılar', 'nobet-tutuyor-acilar-hakki-hakan-kaya-qlz1q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Verdim tezkeresini almadı, 

Nöbet tutuyor acılar.

Silahı elinde, palaskası belinde, 

Nöbet tutuyor acılar.

Kışladan çıktı bu yıldız, 

Büyüttüm acıyı çocuk gürbüz, 

''''3-5'''' değil gece gündüz, 

Nöbet tutuyor acılar.

Bugün güzel hergün olmaz ki, 

Toprağa gömdüklerim yeniden doğmaz ki, 

Hayaller torbaya konmaz ki, 

Nöbet tutuyor acılar.

Bezirgan boynunu bükmüş, 

Duygular şaha kalkmış, 

Mutluluk tezkeresini almış, 

Nöbet tutuyor acılar.

Keskin gözleri üstümde, 

Soğuk süngüsü böğrümde, 

Kulede değil göğsümde, 

Nöbet tutuyor acılar.', 'Verdim tezkeresini almadı,  Nöbet tutuyor acılar. Silahı elinde, palaskası belinde,  Nöbet tutuyor acılar. Kışladan çıktı bu yıldız,  Büyütt...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nobet-tutuyor-acilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YEDİ''ler Masalı', 'yedi-ler-masali-naime-erlacin-96y2e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yedi zaman uzaklıkta

yedi dağın büyücüsü

yedi gün yedi gece

deniz kabuğuna inci ektiler

yedi deniz kızı doğdu dünyaya

birbirinden güzel yedi kozada gizli

aşk 

erdem 

masumiyet 

güzellik 

iyilik 

basiret 

ve düşünceden beslenmiştiler

karada yürünmez 

havada uçulmaz

ne yazık çabuk örselendiler! 

karanlık 

tenhâ sulara sığınıp sessizce gittiler

yedi zaman uzaklıkta

yedi dağın büyücüsü

kötülük ekti bu kez

büyüdü ki hem ne büyüme! 

hafta yedi gün 

sırtlarında yedi günah*

yedi kat yükselip arşa

yedi’ler divanına geçtiler 

ne tuhaf! 

ışığın yedi rengi

müziğin yedi notası gibiydiler...

(*)   Yedi Günah: Kibir, öfke, tembellik, kıskançlık, cimrilik-açgözlülük, şehvet, oburluk.

(27 Haziran 2003)', 'yedi zaman uzaklıkta yedi dağın büyücüsü yedi gün yedi gece deniz kabuğuna inci ektiler yedi deniz kızı doğdu dünyaya birbirinden güzel yedi...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yedi-ler-masali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Tarardı Saçlarını', 'ay-tarardi-saclarini-onder-karadag-szijz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen bir deniz aşığıydın

Benim hasretliğim dağlardı

Ay tarardı saçlarını

Yakamozunda teninin

Bulutlar hüznündü

Yağmurlar  ağlayışın

Gülüşün bin  bereket 

Sesinden esen akyellerde

Mavileşirdi  yeşil gözlerim 

Karayellerde sen esmerleşirdin 

Bir dağ yangınıydı bende

Sende deniz vurgunu 

olan  yürek

Sürgündük birbirimize

Bir korsan hükmüydü 

Sende bu sevda

Eşkıya çaresizliği bende

Beni dağlarda vurdu dev

Sen kayboldun denizlerde

Ve sevgili, eğer

Senin denizin Ege’yse 

Benim dağım Marmara’dır

Ve elbette bilirsin

Bir denizin güzelliği

Bir dağın bakışlarındadır. 

(20-21 Ekim 2001)', 'Sen bir deniz aşığıydın Benim hasretliğim dağlardı Ay tarardı saçlarını Yakamozunda teninin Bulutlar hüznündü Yağmurlar  ağlayışın Gülüşün b...', ARRAY['Türk Edebiyatı','Şiir','Önder Karadağ']::text[], 8.5, '{"poet":"Önder Karadağ","poet_slug":"onder-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ay-tarardi-saclarini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-cemal-ekren-wbosv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu şehrin suyuna kan karışmış, 

Sokaklarına kilit vurulmuş, 

Hamravat  suyunda boğdum küstah sevişmeleri; 

Tılsımlı  burçların gölgesinde; 

Dünyaya geldin...; 

Anan sancılarını, 

Amed’in  suskunluğu gibi saklardı, 

Sen geldin bebeğim, çocuğum, 

Bu şehrin acılarının akıntısına katılmak için....

Sen büyürken öldürdüler seni; 

Önce adını yasakladılar, sonra dilini...; 

Analar  karınlarında can değil; 

Yasaklar  büyüttüler......

Bir  öfke, 

Bir nefret, 

Bir sancı, 

Yasakta olsa, 

Baran  büyüttüler........; 

Damlarda  loğumuz, tahtımız vardı, 

Ayvanda; 

Çiçeklerimiz...; 

Renk renk, 

Yüreklerimizde amansız bir sevda, 

Önce, 

Loğlarımızı devirdiler; 

Tahtlarımızı yıktılar; 

Kan kokulu çizmeleriyle çiçeklerimizi ezdiler.

Suyu akmayan çeşmelerimizden zehir verdiler.

Abdessiz günümüzde, 

Vücudumuzu kanla yıkadık.....

Yüreklerdeki sevdamızın orucunu tutardık

Yoksul soframızda; 

Sen büyüdün mü çocuğum...? 

Yaşın kaç

İsmin bile yok, 

Dökerken gözyaşlarını sokaklara, 

Sokaklar dar gelirdi acılarına 

Bir değil bin nefretle  döverdin, 

Tekmelerdin 

O isimsiz sokakları.

Büyüde....; 

Büyüde  gör

Yasaklar şehrinde  yaşadığını.............

Acılarını ekmeğine katık edip yersin, 

Susarsın; 

Dilin damağın kurur, 

Adına yoksulluk dersin..; 

Gökyüzüne uçuracağın  uçurtman olmayacak; 

Büyük uçurtmalar; 

Uçurtmalarını parçalar...

Sessizce sokağına dönersin

Sabırla ananın dilinden dökülenleri dinlersin; 

Dinlediğin, 

Ve gördüklerinle büyüyeceksin; 

Sonra; 

Kara önlüğünü giydiğinde; 

Dilin değişecek....

İlk, 

A, B, C’ yi  öğreneceksin

Yerli malı haftasında; 

Susan ve ağlayan olacaksın; 

Sana gülecekler...; 

Hiç bir şey götürmediğin  için...

Oysa oğul sen dolu dolu

Masanın üstüne; 

İnsanlığını, 

Onurunu, 

Ve de minicik yüreğinde  büyüttüğün, 

Sevdanı bırakacaksın, 

Paylaşılsın diye....

Okul  sıralarında künyen işaretlenecek.., 

Kendi şehrinde gurbetlerde yaşayacaksın...

Oğul, 

İsmi  yasaklı oğul, 

Baranım  büyüdükçe..

Acıları  koynuna alıp  uyuyacaksın

Amed’ in yıllardır uyutulduğu gibi...

Bu şehre kan karışmış oğul...

Ben sana  beynimi, 

Amed  sana  sancılı yüreğini vermiş, 

Büyüde gör oğul

Büyüyeceksen..............se..........!', 'Bu şehrin suyuna kan karışmış,  Sokaklarına kilit vurulmuş,  Hamravat  suyunda boğdum küstah sevişmeleri;  Tılsımlı  burçların gölgesinde;  ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/cocuk-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçak', 'kacak-cemal-ekren-4nd51', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'KAÇAK

Sen kaçak

Ben kaçak, 

İçtiğimiz çay kaçak, 

Tütün kaçak, dil kaçak

Öyle bir tohum ektik ki toprağa inan çocuklar, 

Savaşacak', 'KAÇAK Sen kaçak Ben kaçak,  İçtiğimiz çay kaçak,  Tütün kaçak, dil kaçak Öyle bir tohum ektik ki toprağa inan çocuklar,  Savaşacak...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kacak-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gidişdi sadece', 'bir-gidisdi-sadece-ensar-cevval-08yb8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönlümün yazdan kalma günleri, 

kitaplar açıldığında dökülen güller

ayaklarına sarılıp da gittiler ya

o gün kızıla yattı bülbüller

o gün ağıt oldu ninniler

çiçekler boyun büktü dalında

yarıya indirilmiş bayrak misali

ve kuşlar anlaşılmaz öttüler 

Rüzgar sustu sokak tenhalarını dinlerken

bulutlar indi yere damlalarını dökerken

saçlarında taç misali duran yıldızlar

ve hilal

geceleri denizde seni aradılar

Mavinin sonsuzluğu gibi kalabalıklar

ve dipte ağlaşan  balıklar

herkes yakamoz sandı ya çırpınışları

bilmediler ki mavi sonsuzlukta

bir ıramadır, kayboluştur gidişin

bilemediler ki

maviye tutkun yüreğinin

her yıl bu mevsimde  göç ettiğini

Biliyorum döneceksin

su, esneyip ağaca tırmandığı gün

koyun ve çiçeğin tohuma yattığı 

beyazın maviye aktığı gün

biliyorum, 

biliyoruz  da...

kokun hafifleyecek ya tenimde..

onun için tüm endişem...

onun içindir afaki çırpınışlar..', 'Gönlümün yazdan kalma günleri,  kitaplar açıldığında dökülen güller ayaklarına sarılıp da gittiler ya o gün kızıla yattı bülbüller o gün ağı...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bir-gidisdi-sadece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İp', 'i-p-mahir-kurt-ent2r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Görevini tamamlamadan kopmuş bir ip, hareketsiz

Bağlayanı yok; yalnız, ümitsiz

Suçlu aramıyor, suçlu kim? Siz.

İp bu olacak ya, mutsuz ve çaresiz.

İpin uzunluğu altımilyar insan metre

Kopmuş altımilyar yerinden

Altımilyar umut lazım

Güneşin doğup battığı yerden.

Herkes kendi kopuğunun derdinde

Bağlayan kurtuluyor.

Diğerleri aç, sefil

Neye yarar, yine dünya dönüyor.

Diğer kopukların arasındayım

Herzaman onları düşünmüşüm

Ama herkes içimden geçiyor

Sonradan anladımki, ölmüşüm.', 'Görevini tamamlamadan kopmuş bir ip, hareketsiz Bağlayanı yok; yalnız, ümitsiz Suçlu aramıyor, suçlu kim? Siz. İp bu olacak ya, mutsuz ve ça...', ARRAY['Türk Edebiyatı','Şiir','Mahir Kurt']::text[], 8.5, '{"poet":"Mahir Kurt","poet_slug":"mahir-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ip-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Labirent', 'labirent-mahir-kurt-xkeeg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Söylenmek istenipte söylenemeyen cümle

Bilirkişi raporlarının beyaz kağıdı

Müfettişlik sınav sorularının cevabı

Magna Carta''nın gelişmiş hali

Yanan kaloriferin sıcaklığı

Dağınık odanın hissedilen havası

Elektriği kesilen evin mumu

Açık pencereden içeriye giren gün ışığı

Kafaları kurcalıyan paradoks

İktisatta tatmin edilen talep

Matematikte heran çözülmeyi bekleyen denklem

Türkçede kurallı cümlenin öznesi

Dünya kupası final maçının biletli seyircisi

Hesabında para olan bankamatik kartı

Vücudun vazgeçilmez vitamini

Dünya klasiklerinin kadın kahramanı

Dünyanın en güzel şarkısı

Ağaçtaki elmanın yarısı

Avcının omuzundaki tüfek

Seni bekliyor işte böyle bir kompleks', 'Söylenmek istenipte söylenemeyen cümle Bilirkişi raporlarının beyaz kağıdı Müfettişlik sınav sorularının cevabı Magna Carta''nın gelişmiş hal...', ARRAY['Türk Edebiyatı','Şiir','Mahir Kurt']::text[], 8.5, '{"poet":"Mahir Kurt","poet_slug":"mahir-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/labirent-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuğum', 'cocugum-emine-senlikoglu-p6wvp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hakkı görmek içindi

O küçük gözlerin

O''na yalvarmak için

Mini mini ellerin

Küfür seline attık

Kanına girdik senin

Seni anlayamadık

Affet bizi çocuğum

Ağlamakta haklıydın

Perişan hallerine

Sür diye zehir koyduk

Açılan dillerine

Sana yâr gibi değil

Düşman gibiydi sine

Seni anlayamadık

Affet bizi çocuğum

Suçsuzdun, günahsızdın

Öyle tertemiz doğdun

Alemlerin Rabbine

Kul olmak istiyordun

Küffara çok benzedin

Şimdi onların oldun

Seni anlayamadık

Affet bizi yavrum', 'Hakkı görmek içindi O küçük gözlerin O''na yalvarmak için Mini mini ellerin Küfür seline attık Kanına girdik senin Seni anlayamadık Affet biz...', ARRAY['Türk Edebiyatı','Şiir','Emine Şenlikoğlu']::text[], 8.5, '{"poet":"Emine Şenlikoğlu","poet_slug":"emine-senlikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cocugum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-emine-senlikoglu-o2djl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çocuk bir gül derlerse inanma

Güller ağlamayı bilmez.

Çocuklar çiçektir derlerse de kanma.

Çiçeklere basılınca, onlar inlemez.

Çocuk bir dünyadır derlerse durun orda

Çücuksuz bir dünya

Orada ya da burada

İnanın çekilmez', 'Çocuk bir gül derlerse inanma Güller ağlamayı bilmez. Çocuklar çiçektir derlerse de kanma. Çiçeklere basılınca, onlar inlemez. Çocuk bir dün...', ARRAY['Türk Edebiyatı','Şiir','Emine Şenlikoğlu']::text[], 8.5, '{"poet":"Emine Şenlikoğlu","poet_slug":"emine-senlikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cocuk-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluk Hikâyemden', 'cocukluk-hik-yemden-emine-senlikoglu-hagec', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kışım ortasında lapa lapa kar yağarken

Kalktım yatağımdan bir gün çok erken

Pencereden baktım ki yerler sanki bir deniz

Ne kadar duygulandım, bir bilebilseniz

Baktım, bizim yaşlı eğri ağaçta

Bir kuş acıyla ötüyor, galiba muhtaçda

Beni kimse görmeden, atladım pencereden

Bir de fırtına vardı, kulaklarımı delen

Ağaca yaklaşmıştım, kuşa doğru bakarak

O ise inliyordu kanadını çırparak

Küçük kuş söyle, ne oldu sana böyle

Kimler incitti seni, ne olur bana söyle

Bakıyor... Sanki birşeyler söylüyordu

Dilinden anlıyordum, ama o bilmiyordu

El uzattım alayım diye, hafifçe kımıldandı

Dost eli olduğunu çok çabuk anladı

Elime aldım onu, kanatları donmuştu

Zannederim yuvadan, yârinden kovulmuştu

Ağlamaya başladım, çok acı çekiyordu

Yuvasız koyanlara beddua ediyordu

Birden elimde gördüm koyu bir kan lekesi

Aniden yavrucuk kesivermişti sesi

Anlayamadım onu kim yaraladı

Can yakmakla bilmem ki, o eller ne anladı?', 'Kışım ortasında lapa lapa kar yağarken Kalktım yatağımdan bir gün çok erken Pencereden baktım ki yerler sanki bir deniz Ne kadar duygulandım...', ARRAY['Türk Edebiyatı','Şiir','Emine Şenlikoğlu']::text[], 8.5, '{"poet":"Emine Şenlikoğlu","poet_slug":"emine-senlikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cocukluk-hikayemden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eminim', 'eminim-emine-senlikoglu-cdw62', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cumartesim, Pazarım çocuklar

Hergünüm yavrucuklar

Kalbimi yol yaptım onlara

Üstünde koşacaklar

Onlar için güneş olsam

Karanlıkları kovsam

Yıldız toplasam onlara

Dünyalarında kalsam

Fısıldasam hepsine

Davet etsem bu dine

Desem aldanma onlara

Herşeyleri tersine

Samanyolunu alsam

Orada onlarla kalsam

Sarılsam tek tek onlara

Ve asla kaybolmasam

Benim umudum, canım çocuklar

Bir kurtulsa yavrucuklar

Derdimi ışınlasam onlara

Eminim anlayacaklar

5.9.1993 İstanbul', 'Cumartesim, Pazarım çocuklar Hergünüm yavrucuklar Kalbimi yol yaptım onlara Üstünde koşacaklar Onlar için güneş olsam Karanlıkları kovsam Yı...', ARRAY['Türk Edebiyatı','Şiir','Emine Şenlikoğlu']::text[], 8.5, '{"poet":"Emine Şenlikoğlu","poet_slug":"emine-senlikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/eminim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Küçükken', 'ben-kucukken-emine-senlikoglu-oj46l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben küçükken kuşları çok severdim

Onlara sapan atan Ali''yi dövdüm

Elekten kapan kuran Fadime''nin yoldum saçını

Bir lokma et yemek için mi? 

Olur mu sevimli cikciği yiyelim diye

''Zıkkım yesin'' diyesim gelirdi Ali''ye

Beni dövmek ister yürürdü üzerime

Hadi bir denesene

Ama bana vuramıyordu

Cesaret edemiyordu

Çünkü ben haklıydım haklılık vakarıyla

Ben gönül dünyasıyla bakıyorum, o mide ile

Mide ile bakanların gözleri midede olur

Onun için Ali beni dövemiyor

Geri dönüyordu

Fadime kızıyor

Dudaklarını sinirden yiyordu

Ama bana vuramıyorlardı

Ben haklı olduğum için

Vakar bendeydi

Vakar hep haklıdır

Çocuk bile olsa kişi, vakara hakkı vardır.', 'Ben küçükken kuşları çok severdim Onlara sapan atan Ali''yi dövdüm Elekten kapan kuran Fadime''nin yoldum saçını Bir lokma et yemek için mi?  ...', ARRAY['Türk Edebiyatı','Şiir','Emine Şenlikoğlu']::text[], 8.5, '{"poet":"Emine Şenlikoğlu","poet_slug":"emine-senlikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ben-kucukken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mazideki İplik', 'mazideki-i-plik-emine-senlikoglu-l3tl4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün bebektim ben, 

Sonra oldum yaramaz bir çocuk

Ne büyük bir hata ettim ki ben, 

Büyüyüverdim çarçabuk

Hâlâ hatırlarım tek tek

Büyüklerin öperdim ellerini.

Onlardan beklediğim bir tek

Pişman etmesinler hayallerimi

Her suçumuzu görürler eğitmeden

Tokatları yüzümüze iniverir

İslâm''da çocuk gelmez, cahil gitmeden

Rüzgâr gibi yüzümüze vuruverir.

Çocukça balon patlatırdık

Hemen kızarlar döverlerdi bizi

Şimdi bombalarla kundaklandık

Sesiniz yok, kim ürküttü sizi.

''Yaramaz çocuk'' derler

Büyükler ne işe yarar sanki

Küçüklerin suçlarını bilirler

Suçsuz büyük var mı ki? 

Ah keşke büyümeseydim de

Ağlasaydım emzik için

''Neden'' diyor bir ses içimde

Büyüklük çirkin mi çirkin.', 'Bir gün bebektim ben,  Sonra oldum yaramaz bir çocuk Ne büyük bir hata ettim ki ben,  Büyüyüverdim çarçabuk Hâlâ hatırlarım tek tek Büyükler...', ARRAY['Türk Edebiyatı','Şiir','Emine Şenlikoğlu']::text[], 8.5, '{"poet":"Emine Şenlikoğlu","poet_slug":"emine-senlikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mazideki-iplik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merdivenler', 'merdivenler-emine-senlikoglu-lw37w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimi çıkar kimi iner bu merdivenlerden

Çıkanlardan haber olur, ses çıkmaz inenlerden

Bakılır akşamüstü bir garip inivermiş

Bir ömür kilimi dünyaya serilmiş.

Sen ve ben... Bir merdivendeyiz

Basamak basamak inenlerdeniz

Sen hangi basamakta ben hangisindeyim

Ne yazık ki bir türlü bilemeyenlerdeniz.

Çocuklar tehlikeyi tam bilemezler

Bilseler oynayıp gülemezler

Yılanlardan çok korkar çocuklar

İki ayaklıları görmezler.', 'Kimi çıkar kimi iner bu merdivenlerden Çıkanlardan haber olur, ses çıkmaz inenlerden Bakılır akşamüstü bir garip inivermiş Bir ömür kilimi d...', ARRAY['Türk Edebiyatı','Şiir','Emine Şenlikoğlu']::text[], 8.5, '{"poet":"Emine Şenlikoğlu","poet_slug":"emine-senlikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/merdivenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanmaki', 'sanmaki-emine-senlikoglu-xw0h4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''Kamış ses verince ney oldum sanır, 

İplik gerilince yay oldum sanır.

Sarayda oturmakla padişah olmaz kişi, 

Abdal ata binince bey oldum sanır.''', '''Kamış ses verince ney oldum sanır,  İplik gerilince yay oldum sanır. Sarayda oturmakla padişah olmaz kişi,  Abdal ata binince bey oldum san...', ARRAY['Türk Edebiyatı','Şiir','Emine Şenlikoğlu']::text[], 8.5, '{"poet":"Emine Şenlikoğlu","poet_slug":"emine-senlikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sanmaki-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelepçeli Kaleminden''', 'kelepceli-kaleminden-emine-senlikoglu-uhwye', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'DAVA ERİ

Bütün zaferlerin ardında, 

Dert yatar, çile yatar

Dava eri denilen kişi

Tozda yatar, çölde yatar

Kim ne derse desin

O sadece Hakka bakar.

FEDAKAR OLMAK

Senin sermayen O’nu yalnızca bilmek değildir.

O’ndan gelen her şeyi, O’na verebilmektir.

HAYAL

Asırlar önceydi o, yıldızlar elimizde, 

Şimdi o yıldızların hayali zihnimizde.

KENDİNE

İnsanın kendine verdiğini bir dünya veremez.

Kendine yaptığını da, hiç kimse yapamaz.

NEFSİME

Ey nefsim, bak şu mezara, ibret al

Ölüm hayatla kardeş, ona göre zevke dal.

ÖLÜM

Annem veya ben ondan önce, 

Öleceğim muhakkak vadem gelince, 

Düşünüyorum ölümü ta derinden, 

Gerçek ince, fikirdeki zardan ince

TABİATCI’YA

Desem, şu duvar kendi kendine dizilmiş

Bana ağız eğerek der; imkansız bir iş

Mikro aleminden makro alemine dek

İnci inci kaideler, mükemmel gidiş

Görür bunları da yine inanmaz

Hiç aklım almadı, bu nasıl iş! ..

YAKIŞIR MI? 

Bırak davayı ne demek? 

İnsan Allah’ı bırakır mı? 

Hiç çile çekmeyen nas’a, 

Söyle; cennet yakışır mı?', 'DAVA ERİ Bütün zaferlerin ardında,  Dert yatar, çile yatar Dava eri denilen kişi Tozda yatar, çölde yatar Kim ne derse desin O sadece Hakka ...', ARRAY['Türk Edebiyatı','Şiir','Emine Şenlikoğlu']::text[], 8.5, '{"poet":"Emine Şenlikoğlu","poet_slug":"emine-senlikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kelepceli-kaleminden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Bu Vatanın Neyi Oluyoruz?', 'biz-bu-vatanin-neyi-oluyoruz-emine-senlikoglu-8trwi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İmkanın olsa asacaksın

Elinde olsa keseceksin

Kendine göre biçeceksin

Biz bu vatanın neyi oluyoruz? ! 

İstiyorsan hep susalım

Senin korkundan pusalım

O kadar değil dur bakalım

Biz bu vatanın neyi oluyoruz? ! 

Anayasayı babayasayı

Sen istiyorsan bütün payı

Bu yaptığını yapmaz ayı

Biz bu vatanın neyi oluyoruz? ! 

Bizler Allah''ın mülkündeyiz

Ve O''nun verdiğini yeriz

Sırası gelince deriz

Biz bu vatanın neyi oluyoruz? ! 

Sen istiyorsun biz ölelim

Tahrik olup sana teslim olalım

Ülkeyi sana teslim edelim

Biz bu vatanın neyi oluyoruz? ! 

Hürriyet midir yaptığınız? 

Nedir sizin yaptığınız? 

Tümden suçtur varlığınız

Biz bu vatanın neyi oluyoruz? ! 

Güya bizi çarparsınız

Lehimizde kırparsınız

Siz bu vatanda yaşarsınız

Biz bu vatanın neyi oluyoruz? ! 

Büyükler emrinizdedir? 

Hakaretiniz dizdedir.

Kem gözleriniz bizdedir, 

Biz bu vatanın neyi oluyoruz? ! 

Bize hakaretler aldı gidiyor

Eller atına bindi gidiyor

Gençlik İslam''a daldı gidiyor

Biz bu vatanın neyi oluyoruz? ! 

Biz Allah''ı sevenlerdeniz

Ve O''na gönül verenlerdeniz

Gerekirse ölenlerdeniz

Biz bu vatanın neyi oluyoruz? ! 

Biz savaştık biz çalıştık

Eller doyarken acıktık, 

Kadın, erkek yola çıktık, 

Biz bu vatanın neyi oluyoruz? ! 

Söz bizim temel hakkımız

Biz Hakk''a en yakınız

Siz kalleş ile farkımız, 

Biz bu vatanın neyi oluyoruz? ! 

Meşhur ''Yaşar yaşamaz'' gibi

Öyle istiyorsun sen bizi

Alırız hakkımızı bal gibi, 

Biz bu vatanın neyi oluyoruz? ! 

Be kefere, be kitapsız

Senin Hak dediğin haksız.

Yaşamak hakkımız, tutsaksız

Biz bu vatanın neyi oluyoruz?', 'İmkanın olsa asacaksın Elinde olsa keseceksin Kendine göre biçeceksin Biz bu vatanın neyi oluyoruz? !  İstiyorsan hep susalım Senin korkunda...', ARRAY['Türk Edebiyatı','Şiir','Emine Şenlikoğlu']::text[], 8.5, '{"poet":"Emine Şenlikoğlu","poet_slug":"emine-senlikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/biz-bu-vatanin-neyi-oluyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavrum', 'yavrum-emine-senlikoglu-4lgc7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağlamaktan kurumuş gamlı gözün, 

Yardım ister gibi bakmışsın yavrum.

Gördüğümden beri ilk kez yüzünü, 

Uykularım kaçtı inanki yavrum.

Galiba insanlık duygumuz ölmüş

Ne desem sana, bilmem yavrum.

Ruhumuz habersizce bizden süzülmüş, 

Biz ölmüşlere gücen gücenme yavrum.

''...Bir müminin ayağına diken batsa...''

Okuruz hadisleri sen bakma yavrum.

Bundan sonra senin için ayağa kalksa da, 

Sakın müslümanları af etme yavrum.

                                                   21.9.93', 'Ağlamaktan kurumuş gamlı gözün,  Yardım ister gibi bakmışsın yavrum. Gördüğümden beri ilk kez yüzünü,  Uykularım kaçtı inanki yavrum. Galiba...', ARRAY['Türk Edebiyatı','Şiir','Emine Şenlikoğlu']::text[], 8.5, '{"poet":"Emine Şenlikoğlu","poet_slug":"emine-senlikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yavrum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökkuşağı', 'gokkusagi-berna-yilmaz-5v4o2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben sende kalıcıydım yabancı

Bir sevda bekledim yamacinda

Kuşkunun girdabinda bir yaprak

Savruldum hırçınlığında

Haziran 2002', 'Ben sende kalıcıydım yabancı Bir sevda bekledim yamacinda Kuşkunun girdabinda bir yaprak Savruldum hırçınlığında Haziran 2002...', ARRAY['Türk Edebiyatı','Şiir','Berna Yılmaz']::text[], 8.5, '{"poet":"Berna Yılmaz","poet_slug":"berna-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gokkusagi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Med Cezir', 'med-cezir-berna-yilmaz-qnr6n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Suları çekildi sevda denizimizin

Ay sakındı saçını ürkek dalgalarından

Bambaşka özlemlerle tutuşuverdi güneş

Ayrılık saçıldı bu bahar korlarından

Sevgilinin yüzüne resimler çizdi zaman

Bir gülüş mühürledi tuzdan dudaklarına

Sarı bir bulut çöktü gözlerinin üstüne

Erirken seslerimiz sessizliğin tavında

Sevgili fısıldadı sırrımızı geceye

Teker teker karardı yıldızlar kederinden

Demir aldı hayaller bu hayalet limandan

Tüyden hafif elleri ellerimden kayarken

19 Şubat 1999, Bebek', 'Suları çekildi sevda denizimizin Ay sakındı saçını ürkek dalgalarından Bambaşka özlemlerle tutuşuverdi güneş Ayrılık saçıldı bu bahar korlar...', ARRAY['Türk Edebiyatı','Şiir','Berna Yılmaz']::text[], 8.5, '{"poet":"Berna Yılmaz","poet_slug":"berna-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/med-cezir-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parmak İzi', 'parmak-i-zi-ensar-aktas-ldhoe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Madem ki herşey yalandı

Yaşananlar bir rüyaydı

Madem ki gidiyorsun

Herşeyi bir kalemde siliyorsun

Madem ki sende bir iz bırakamadım

Sevgine layık olamadım

Hadi kes beni

Vur hançeri bağrıma

Sonra kanımdan bir parmak çal alnına

Kurban kanı gibi

Bir parmak izi olsun orada

Benden sana hatıra

Rotterdam,07.09.2002', 'Madem ki herşey yalandı Yaşananlar bir rüyaydı Madem ki gidiyorsun Herşeyi bir kalemde siliyorsun Madem ki sende bir iz bırakamadım Sevgine ...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/parmak-izi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairliğin De Suyu Çıktı', 'sairligin-de-suyu-cikti-ensar-aktas-knuqg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şairliğin de suyu çıktı kardeşim, yeter artık

Şiirde enflasyon aldı başını gidiyor

Bir günde oniki şiir yazılır mı, yeter bıktık 

Kafamın içinde migrenler cirit atıyor

Rotterdam,25.08.2002', 'Şairliğin de suyu çıktı kardeşim, yeter artık Şiirde enflasyon aldı başını gidiyor Bir günde oniki şiir yazılır mı, yeter bıktık  Kafamın iç...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sairligin-de-suyu-cikti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sabah', 'bu-sabah-ensar-aktas-b69on', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu sabah uyandığımda

Sen hâlâ uyuyordun yanımda

Kulağıma fısıldadığın o hüzünlü sözler

Dün akşamdan kalmış bir şiir gibi dudaklarımda

Bir koşu gittim banyoya

Elimi yüzümü yıkamaya

Bakışlarımda bıraktığın o büyülü gözler

Sel olmuş akıyordu bir nehir gibi yanaklarımda

Bu sabah bir başkalık var da

Ciğerlerime çektiğim havanın kokusunda

Anlayamadım yüreğim şimdiden seni özler

Yıllarca görmediğim bir şehir gibi çok uzaklarda

Madem bu sabah uyandığım da 

Sen hâlâ uyuyordun yanımda

Öyleyse ne işim var benim burada

Elimde kırmızı güllerle bu mezarın başında

Rotterdam,09-06-2003', 'Bu sabah uyandığımda Sen hâlâ uyuyordun yanımda Kulağıma fısıldadığın o hüzünlü sözler Dün akşamdan kalmış bir şiir gibi dudaklarımda Bir ko...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-sabah-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşlarına Yağmur Yağdı mı', 'gozyaslarina-yagmur-yagdi-mi-oguzkan-bolukbasi-dyxah', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözyaşlarına yağmur yağdı mı hiç

Bir acıyı sele verdin mi hıçkırıkla

Beklemek değildi  kaybedileni

Özlemek değildi çekip gideni

O sıcak yaz akşamlarında yandığımız

Yokluğunda hissettiğimiz kahrolası yalnızlığımız

Varlığında  sevdandı anlamadığımız', 'Gözyaşlarına yağmur yağdı mı hiç Bir acıyı sele verdin mi hıçkırıkla Beklemek değildi  kaybedileni Özlemek değildi çekip gideni O sıcak yaz ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gozyaslarina-yagmur-yagdi-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı koyulmadı yalnızlığımın', 'adi-koyulmadi-yalnizligimin-berna-yilmaz-v6k19', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çözemedim sessizliğin dilini

Yüzümdeki alay boşuna değil

Bilsem de sabırdır sabrın meyvesi

İsyanımı dindirmek elimde değil

Yoklugun çiğ olup yağdı üstüme

Yüzümde ayrılığın gölgesi

Sabah yeli gibi inceden serin

Sızılar doldurdu şimdi yerini

Tutamadim fırtınanın elini

Çaresiz azad etti seni yüreğim

Sensiz, doğmamış bir çocuk gibiyim

Adı koyulmadı yalnızlığımın', 'Çözemedim sessizliğin dilini Yüzümdeki alay boşuna değil Bilsem de sabırdır sabrın meyvesi İsyanımı dindirmek elimde değil Yoklugun çiğ olup...', ARRAY['Türk Edebiyatı','Şiir','Berna Yılmaz']::text[], 8.5, '{"poet":"Berna Yılmaz","poet_slug":"berna-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/adi-koyulmadi-yalnizligimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-berna-yilmaz-udkhd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Selamınla basladı günüm

Sesinde yumuşacik meltemler 

Gözlerine tutunmus nemi gordüm

Bak denizleri de unuttum düşlerine dalalı

Huzura sarındı uykum

Terketti başımı sarhosluğu

Köhne, yaralı sevdanın

Yüregim kücük, sabırsız bir kuş

Günahsızım

Yaşlarıma son verdi gülüşün

Bırak..

Yüzüm nefesinle ıslansın.', 'Selamınla basladı günüm Sesinde yumuşacik meltemler  Gözlerine tutunmus nemi gordüm Bak denizleri de unuttum düşlerine dalalı Huzura sarındı...', ARRAY['Türk Edebiyatı','Şiir','Berna Yılmaz']::text[], 8.5, '{"poet":"Berna Yılmaz","poet_slug":"berna-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dus-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acılar Tohumlarıdır Şiirlerimizin', 'acilar-tohumlaridir-siirlerimizin-melih-coskun-d0ccn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Acılar tohumlarıdır şiirlerimizin 

Mürekkebidir en güzel dizelerimizin

Kırarak daralan bir göğsün kafesini

Yazılır her akşam kentin yoksul duvarlarına 

Bir koyu kızılı ararken gün batımında

Ve sahip olamadıkların 

Gömülürken güneşle beraber o uzak sulara 

Bambaşka bir duyguyla sarsılır fikrin 

O sancıyan dünyanın 

İyi kalpli çocukları da aşık olurlar 

Çünkü mayasına sevda katılmıştır onların bir kez

Ve seçme şansları yoktur acı çekmekten başka 

Sarmak isterken yaralarını 

Koskoca bir halkın 

Kendilerine bile yetmez olur 

Bu kocaman yürekleri

Acılar tohumlarıdır şiirlerimizin 

Mürekkebidir en güzel dizelerimizin 

O iyi yürekli çocuklarının hikayelerini anlatırlar

Akşamüstünün kızıl göğü çevirirken yüzünü ağır ağır siyaha 

Yola koyulurlar aşk çağının o sürgün yürekleri 

Çıkmaz sokaklarda dövüştüklerini bile bile...

23 Mayıs 2003

02:25', 'Acılar tohumlarıdır şiirlerimizin  Mürekkebidir en güzel dizelerimizin Kırarak daralan bir göğsün kafesini Yazılır her akşam kentin yoksul d...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/acilar-tohumlaridir-siirlerimizin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevişmelerimiz', 'sevismelerimiz-cemal-ekren-q252y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sevişmelerimiz

kehriban sarısı saçlarına yenik düştü; 

yosun yeşili gözlerim, 

tiryakisi oldugum sevişmerimiz; 

zemheri ayazında hep buzluga kaldı, 

tenimizin sıcaklığından fışkıran tanecikler, 

yaşamın avucuna düşerken, 

yeni canlar ayaklanır  suskun sokaklarda; 

berivan olur, 

berfin olur

azem olur

insan olur, 

sonra faili meçhul bir kurşuna, 

kurban olur....', 'sevişmelerimiz kehriban sarısı saçlarına yenik düştü;  yosun yeşili gözlerim,  tiryakisi oldugum sevişmerimiz;  zemheri ayazında hep buzluga...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevismelerimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paylaşım', 'paylasim-cemal-ekren-263c4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Paylaşım

Gülüşüm dudaklarında yitti 

Ve masaldı yaşanılan

Daha bir bile veremeden bittim

Çelik migferler

Metal silindir demirden yapılı

Onlarca  kat boyunca uzanan inşaat iskeleleri, 

Sen kokulu sokaklar saklayan, 

Sipot ışıkları, 

Ve her gece anamın binbir itinayla serdigi yer döşegi, 

Buydu tüm  anlatacagım.

Senin dilinden anlıyacagın bir maceram olmamıştı oysa..; 

Başıda sonuda belliydi anlatacaklarımın, 

Tüm varlıgım bir solukta  anlatabilecek kadardı...

Çok şeyim olmamıştı 

Hatta  , Çok şey istememiştim 

Topu topu  içinde bulundugum bir metre kareyi 

Suna, 

bilmiştim sana

gayem seninle komünel yaşamın zorlugunun  tadına  varabilmekti...

ve, 

uyanınca her sabah anamın  zoruyla

başımı diktiğimde tavana, nemli duvarları görmemek içindi.

Çabam seninle koyun koyuna, 

Çabam aynı kulakta zikri içindi anamın sesinin...; 

Çabam, 

Zor bir ihtimalda olsa; 

Aynı tabakta  buluşabilmek içindi bir gün....

Ve gerekmese de aynı ekmeği bölüşebilmek içindi...

Çabam; 

Senle aynı metrekareyi paylaşabilmek içindi........', 'Paylaşım Gülüşüm dudaklarında yitti  Ve masaldı yaşanılan Daha bir bile veremeden bittim Çelik migferler Metal silindir demirden yapılı Onla...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/paylasim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-cemal-ekren-06brz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen

bende  gizli olan sensin.

Çözülmiyen, 

Bir denklemin, 

X, 

İşareti gibisin...

Açlığımın öteki adı kadar bana yakınsın

Sigaramdaki duman kadar içimde, 

Yıldızlar kadar uzağımdasın, 

Sen

Bende ikinci bir bensin...; 

Biliyorum, 

Bana  gülüyorsun....., 

Bende  itiraf ediyorum; 

Bir çocuk  gülüşüyle 

evet; 

seni seviyorum....', 'sen bende  gizli olan sensin. Çözülmiyen,  Bir denklemin,  X,  İşareti gibisin... Açlığımın öteki adı kadar bana yakınsın Sigaramdaki duman ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-269-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-cemal-ekren-n6885', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu şehirden gidiyorum 

Dudağımın kıyısında yanık bir sigara, 

Yüreğimin yanığı gibi.

Çocuksu gülüşlerimi sokaklara bırakıp, 

acılarımı, 

yalnızlığımı, 

sırtlayıp gidiyorum.

Oysa, 

Sen tenimde bir yaraydın, 

Kabuk tutmuştun, 

Kutsaldın..

Sana geleceğim yolara göz yaşlarımı dökerken, 

Sen, 

Tüm yollara  kilit vurdun.', 'Bu şehirden gidiyorum  Dudağımın kıyısında yanık bir sigara,  Yüreğimin yanığı gibi. Çocuksu gülüşlerimi sokaklara bırakıp,  acılarımı,  yal...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gidiyorum-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden', 'yeniden-cemal-ekren-i81jl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yeniden 

sana yasaklar şehirinden, 

kan kokulu çiçekler getirdim.

yüreginde yeniden yeşersin diye.

Sokaklarına kilit vurulmuş, 

Oyuncakları ellerinden alınmış, 

çocukların gülüşlerini getirdim, 

yeniden gülesin diye.

Sen bakma bana; 

Öyle alık alık, 

Yirmi sekizinde olup otuz beşinde gösteriyorsam....! 

Anlımın en kalın çizgisinde, 

Acılar  voltaya çıkmış.

Sana acılarımı değil, 

Yüreğimi veriyorum sevesin diye.

Benim şehirimde güneş doğmaz, 

Üşüyorum...; 

Gönder sıcaklığın ısıt beni.

Bir anlamı olmalı anlımdaki çizğilerin..

Vede neden üşüdüğümün.

Neden bu şehirde kan çiçekleri....? 

gökyüzünden yağmur yağmaz

Acılar düşer  avuçlarımıza.

Ve, 

Topraklarımızda, 

Onurlu, 

Bereketli, 

Yoksulluk boy verir.

sana yasaklar şehirinden, 

sabahı agıtlarla karşılıyan, 

anaların gözyaşlarını getirdim, 

minicik ellerinle silesin diye.....

sana, sürgünlüğümde, 

çatlamış dudagımı verdim, 

öpesin diye.....

sana yüregimi verdim, 

suçuma ortak olasın diye...

hemen korkma, 

suçumdan..., 

yüregimizdeki topraklara, 

anaların sevinçlerini, 

çocukların gülüşlerini, 

onurlu yaşamı, 

vede, 

senin  sevdanı ektik.

Dedim ya; 

Güneş firaridir, 

Üşüyorum......

Gönder sıcaklığını ısıt beni.', 'yeniden  sana yasaklar şehirinden,  kan kokulu çiçekler getirdim. yüreginde yeniden yeşersin diye. Sokaklarına kilit vurulmuş,  Oyuncakları ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/yeniden-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışveriş', 'alisveris-cemal-ekren-xy8h5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yorgun caddenin  köşesinde, 

bir çocuk, 

bir adam, 

adam çocuksu bir gözle çocuğa bakıyor..., 

çocuk  uykulu bir gözle bakıyor......

çocuk; 

boyayalım mı abi? 

Neyi? 

Ayakabılarını, 

O an; 

Çıplak ayaklar konuşuyor...

Çocuk; 

Sen; 

Tenimi, 

Yoksulluğumu, 

Acılarımı, 

Yalnızlığımı, 

Boyaya bilirmisin...? 

Çocuk  boya kutusuna yaslanmış uyuyordu...

Bu kez  boya kutusu konuştu..

Sen bana balon resmi çizermisin, 

Gökyüzünü, 

Kuşları, 

Bunları çizmem için kalem alırmısın...? 

Bu kez ikiside sustu, 

Konuşanlar konuşmaya başladı....', 'yorgun caddenin  köşesinde,  bir çocuk,  bir adam,  adam çocuksu bir gözle çocuğa bakıyor...,  çocuk  uykulu bir gözle bakıyor...... çocuk; ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/alisveris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pazarlık', 'pazarlik-cemal-ekren-v8g2z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Pazarlık

demli bir çay gibi; 

yüregimi demledim sana, tenimin sıcaklığında.

Adresi yazılmamış ilk mektubuda sana yazdım...

Nakaratında hep sen olan, 

ilk şiiri de sana yazdım.

İlk göz yaşlarımı  annemin avuclarına  dökerken, 

Birde senin yokluğuna ağladım, 

Nisan yağmurlarını çiğnerken.

Parsellenmemiş vucudumdan, 

 Yüregimi verdim sana, 

bir gülücüğün, 

bir öpücügün için...

anlıyormusun....', 'Pazarlık demli bir çay gibi;  yüregimi demledim sana, tenimin sıcaklığında. Adresi yazılmamış ilk mektubuda sana yazdım... Nakaratında hep s...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/pazarlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni seviyormuyum....? ?', 'seni-seviyormuyum-cemal-ekren-6v1jj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni seviyormuyum....? ? 

senki vasıfsız  mavi, 

öyle deniz, öyle gökyüzü

senki kaba; 

öyle gece, öyle yasak

ve, 

öyle isyan kokulu.

Gövdesi arap, 

Gövdesi zenci, gövdesi  kürt, 

Gövdesi nakış nakış  insan kokulu.

Öfke, tasa, 

Ve kinle bilenmiş bir bıçak.

Çulsuz bir şair gibi.., 

Ritmik bir ten, 

Bir gitar dinletisi, 

Yahut kumsalsız bir deniz seeeeeeeennnn...., 

Dünü  bu günü ve yarını olmayan, 

Ve daı  hiçbir nufus kütüğünde geçmeyen, 

Ve  kötüde  olsa  anlatacağı bir hayat  hikayesinden  mahrum., 

Yoksul bir  sokak yosması, 

Yüregi sevgisiz, 

Yüreği yazımsız, çizimsiz, 

Yüreği kan  kan seeeeeeeeeeeeennnnn, 

Kokusu tırnağıma  sinmiş

Kınam gibi saygı duyduğum, 

Uğruna  dillere düşüp  şair olduğum, 

Sen ki  öyle dem

 Ben ki öyle ifadem, 

Heeeeeyyyyy, 

Yarının  buğünü  olsada, 

Öbür gün  olsa da; 

Seni seviyoruuuuuuuuuummmmmmm...........', 'Seni seviyormuyum....? ?  senki vasıfsız  mavi,  öyle deniz, öyle gökyüzü senki kaba;  öyle gece, öyle yasak ve,  öyle isyan kokulu. Gövdesi...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/seni-seviyormuyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ucuzluk', 'ucuzluk-cemal-ekren-xaqam', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ucuzluk

benim şehrimde  yaşamanın faturası  ağırdır; 

sevişmelerin yasak, 

ağız dolusu gülüşlerin yitik, 

gök gürültüsü , 

göz  yaşlarımıza eşdeğerdir.

Kirpiklerimiz  paslanmaz..., 

Yüreklerimiz  demli çay kıvamındadır.

Çocuklarımız, 

Çelimsiz, 

Aç, 

Gözleri değişkendir.

Benim şehrimde; 

Her şey, 

Pahalıdır.

Ve, 

Ondandır  babalar, 

Mağrur, 

Sıkılğan, 

İsyan kokuludur.

Analar, 

Yorgun, 

Analar, 

Can pazarındadır.

Ucuzluğun, 

Her eve  girdiği...! 

Kapısını  çaldığı, 

Ölümdür..........................', 'Ucuzluk benim şehrimde  yaşamanın faturası  ağırdır;  sevişmelerin yasak,  ağız dolusu gülüşlerin yitik,  gök gürültüsü ,  göz  yaşlarımıza ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ucuzluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine', 'oylesine-cemal-ekren-n5ymx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öylesine

ki gözlerin kumsalsız, 

bin kez ölmüş denizdir bakar.

Öylesine mavi işte...

Ki  saçlarını taradıkça, 

Birer birer  bugdaydın döken...

Öylesine sarı  işte...

Ki  tenin parça parça  cehenemdir  yakan; 

Öylesine  sıcak  işte...

Ki  yoksun yine, 

 Ki umurunda bile  değilim, 

Biliyorum; 

Ama, 

Öylesine  seviyorum işte.....', 'Öylesine ki gözlerin kumsalsız,  bin kez ölmüş denizdir bakar. Öylesine mavi işte... Ki  saçlarını taradıkça,  Birer birer  bugdaydın döken....', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/oylesine-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyuma', 'uyuma-cemal-ekren-jtm6o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uyuma

uyusunda  büyüsünde ninni; 

derdi anam..., 

o şefkat dolu yüreğiyle.

Ve öyle de büyüyoruz......., 

Sen meraklanma ana, 

Bizi uyutacakları yeni ninniler çok...

Uyuyanlar uyuyor.

Uyumuyanlar, 

Ölüyor.....

Ninni...............', 'Uyuma uyusunda  büyüsünde ninni;  derdi anam...,  o şefkat dolu yüreğiyle. Ve öyle de büyüyoruz.......,  Sen meraklanma ana,  Bizi uyutacakl...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/uyuma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dişi Ozan', 'disi-ozan-cemal-ekren-tsuyf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hedefim değilsin  dişi ozan; 

dizelerin keskin  bir bıçak gibi olsa da, 

aşkların en yücesini yaşatsan da, 

geceyi gündüze devir etsen de, 

sevinçlerin gölğesin de, 

aşıklar soluklansa da, 

sen benim acılarımı yaza bilirmisin....? 

ben, 

acılarımın gölgesinde sevinçlerimi ararım..; 

sen, 

yaşarken etinin dilim dilim kesildiğini, 

mülteci bakışlarla güneşe kucak açıp; 

yalnızlığı koynuna alıp uyurmusun..? 

uyandığında   nemli duvarlara, 

güneş resmi çizermisin..? 

ben yaşarken, 

ölümü koynuma alıp yatarım..

sen, 

sevğilinle  uyurken..., 

ondandır hedefim degilsin dişi ozan....', 'hedefim değilsin  dişi ozan;  dizelerin keskin  bir bıçak gibi olsa da,  aşkların en yücesini yaşatsan da,  geceyi gündüze devir etsen de,  ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/disi-ozan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berivan', 'berivan-cemal-ekren-vpbxn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bu gün doyasıya içmek sarhoş olmak istedim; , 

ayaklarım beni köhne bir bara götür dü..

zaten, 

seni sevmekten başka bir lüksüm olmadı, 

kuytu bir köşeye oturdum.

Agzı tütün kokan; 

Garson, 

“ne içersiniz”

bir şişe berivan dedim..., 

garson güldü

seni yudum yudum içmek isterdim, 

ama garson, 

“pardon ne istediniz? ”

bir şişe berivan..

“rakı var”, 

rakı geldi, 

ben kadehime berivan doldururken, 

ilk yudumda rakının tadını his ettim, 

burayı  sevmedim..., 

sen yokttun.., 

aç ve iştahı kabarmış adamlarla doluydu...

bana bakıp gülüyorlardı....

kadehimde boşalmış benim gibi; 

yalnız kalmıştı.

Tekrar kadehime berivanı doldurdum; 

Fondik  ettim...

Tam kalkarken; 

Usulca yanıma yaşlı bir tarih oturdu.

“aşıkmısın”

güldüm, 

“aşıkmısın”

güldüm ve

kalbim dilime hain konuşamadım.

“hey ogul”

işte o an; 

yetimliğim masama geldi.

Yaşlı tarih gitti.

Garson geldi; 

“meze ne alırsınız? ”

ben berivanı sade içerim.

Garson gitti.

Bir nefes, 

Bir nefes daha sigaramı içime çektim, 

İçim berivanla dolu, 

Masama, 

Elleri titreyen, 

Ama  kemanıyla bir şeyler çalan, 

çinğen geldi; 

“hangi  türküyü çalalım? ”

berivan..., 

burayı sevdim....

sen masama geldin....

hey garson bir şişe daha berivan getiiiir....! 

sen garsonun elinde masama geldin..

türküyle  seni birden içtim....

duvarda asılı duran aglayan çocuk fotoğrafı, 

şimdi bana bakıp gülüyordu.

Çingene; 

“Tamamı abi türkü bitti”

berivan hiç bitmez 

tekrar o, 

türkü, 

tekrar  tekrar sen kadehim de.

korkularım, 

yalnızlığım, 

yok olmuştu.

başımda diklen; 

garsona; 

hesap....! 

hesap gelince; 

seni, 

sevmenin faturası çok ağırdı

masaya; 

yalnızlığımı, 

bırakıp kalktım.

Dışar da  deli bir yağmur, 

Ellerim çebim de, 

Islanarak

Dudağımda, 

O, 

Türkü..., 

Berivan sokağına girerken, 

Yagmur  durmuştu.....

Şimdi gözlerimin yağmuru senin yokluğuna yağıyordu....', 'bu gün doyasıya içmek sarhoş olmak istedim; ,  ayaklarım beni köhne bir bara götür dü.. zaten,  seni sevmekten başka bir lüksüm olmadı,  kuy...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/berivan-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Destan', 'destan-cemal-ekren-ktirq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Destan 

Hani Bu Akşam Firar Edecektin; 

Ay Işıgının Altında; 

Acılarımızı, 

Hasretligimizi, 

Yalnızlıgımızı Meze Edip Yiyecektik...... 

Devrilen Yüregimize Eşdeger; Şarap Şişelerini Devirecektik..... 

Oysa Sen, 

Yoksun; 

Yine Kendinde Tutklusun 

Herzaman Ki Gibi Yine Gelmedin..! 

Tek Başıma; 

Yalnızlıgın Potasına; 

Sensizligi, 

Ve Gözyaşlarımı Atıp Duruyorum...... 

Korkunun Yalnızlıgın Bir Adresi Olmalı. 

Not Defterimde Sende Kaldı; 

Sana Yük Olacak, 

Suç Olacak, 

Korkularımla, 

Acılarımla, 

Kavgalarımla Doluydu..... 

Ben Soframı Kurdum; 

Yavaş Yavaş Demleniyorum, 

Sen Olmasanda Herzamanki Gibi Bardagın Dolu, 

Sigaranıda Yaktım..; 

Hafiften; 

Agrılı Kızın Türküsünü Dinliyorum! 

Oysa Sen Bende Her Zaman Vardın; 

Bir Yıldız Çilingir Soframıza Düştü; 

Ben Konuştum; 

Sen Sustun; 

Susan Ve Anlatacagın Nice Hikayelerin, 

Acıların Vardı.......; 

Bilirim... 

Yıldız......; 

Yıldız...; 

İsmini Zikir Ettigimde Yıldızda Beni Terk Etti.. 

Sen Gökyüzünün Degişmez Aksesuarı Olan Yıldızlardan, 

Daha Güzeldin, 

Neyse.....; 

Bu Kadeh Senin Şerefine... 

Meze Ne Alırdın...? 

Ben Bir Dilim Yalnızlıgını Ve Yetimligimden Bir Lokma Aldım....... 

Baktınmı Not Defterime? 

Sayfaları Genç Bir Rüzgar Gibidir, 

Rüzgar Kapısını Açmış Sevinç Dagıttıyor..., 

Oysa Ben; 

Kan Dolu Dipsiz Bir Kuyunun İçinde Seni Arıyorum... 

Sırtımı; 

Yaşlı Bir Çınar Agacına Dayadım, 

Dolu Dolu Bir Nefes, 

Bir Nefes, 

Bir Nefes Daha Çekip; 

Sigarayıda Kendime Küstürüp 

Gelmiyecegin Yollara Gözlerimi; 

Nöbette Diktim.., 

Biliyorum Gelmiyeceksin, 

Olsun, 

Maksat Muhabet Olsun........! 

Neyse 

Not Defterimden Kendine Bir Mutluluk Al, 

Yoklugun İçin; 

Şerefine............... 

Yüreği 

Yüregimde Depremler, İsyanlar; 

Yolunu Kayıp Etmiş Yetimler, Secdeye Duran Yaşlı Bir Ana. 

Susamış Maviş Bir Çocuk, 

Gözyaşlarımı Kana Kana İçiyor.. 

Elinde Şarap Şişesi İle Orta Yaşlı Bir Adam; 

Yalnızlıgından; 

Kahrından; 

Nara Atıyor Yüregimde....; 

Bir Bebek Aglıyor Dolu Dolu; 

Ana Sütüne Hasret...; 

Silahlar Patlıyor Arka Sokakta....! 

“Faile” Giden Cansız Bedenler; 

Yüregime Gömülüyor; 

Secdeye Duran Ananın Feryadı; 

Yürekleri Daglıyor. 

Hep Susan; 

Susması Gereken Olduk, 

Bir Şiir Dinletisine Hasret, 

Yada Kürdün Gelinin Dinlemek, 

Hasretligin Halkası Oldu Yüregimde.. 

Hep Acıların Duragı Oldu; 

Bu Mahsun, 

Suskun, 

Vede Öfkesinin Karnı Büyüyen Yüreğim.... 

Sonra Kuşlar Uçtu; 

Yagmur Yagarken Yüreğime! 

Ve Sen Düştün; 

Zavalı Yetim Yüreğime, 

Kar Tanesi Gibi Ak......', 'Destan  Hani Bu Akşam Firar Edecektin;  Ay Işıgının Altında;  Acılarımızı,  Hasretligimizi,  Yalnızlıgımızı Meze Edip Yiyecektik......  Devr...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":94,"source_url":"https://www.antoloji.com/destan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim', 'yuregim-cemal-ekren-uya7w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğim 

Yüregimde Depremler, İsyanlar; 

Yolunu Kayıp Etmiş Yetimler, Secdeye Duran Yaşlı Bir Ana. 

Susamış Maviş Bir Çocuk, 

Gözyaşlarımı Kana Kana İçiyor.. 

Elinde Şarap Şişesi İle Orta Yaşlı Bir Adam; 

Yalnızlıgından; 

Kahrından; 

Nara Atıyor Yüregimde....; 

Bir Bebek Aglıyor Dolu Dolu; 

Ana Sütüne Hasret...; 

Silahlar Patlıyor Arka Sokakta....! 

“Faile” Giden Cansız Bedenler; 

Yüregime Gömülüyor; 

Secdeye Duran Ananın Feryadı; 

Yürekleri Daglıyor. 

Hep Susan; 

Susması Gereken Olduk, 

Bir Şiir Dinletisine Hasret, 

Yada Kürdün Gelinini Dinlemek, 

Hasretligin Halkası Oldu Yüregimde.. 

Hep Acıların Duragı Oldu; 

Bu Mahsun, 

Suskun, 

Vede Öfkesinin Karnı Büyüyen Yüreğim.... 

Sonra Kuşlar Uçtu; 

Yagmur Yagarken Yüreğime! 

Ve Sen Düştün; 

Zavalı Yetim Yüreğime, 

Kar Tanesi Gibi Ak..... 

Zamansız Bir Yerde Eriyip Gitme.., 

Saattin Akrep İle Yelkovanını Rehin Aldım... 

Çalışmıyor....! 

Hep Bende Kalasın Diye. 

Saat Tık Tık Tık Atmıyor, 

Atan Yüreğimdir Bilesin, 

Bu Yüregim Nice Sancıların Şahitligini Yaptı, 

Yorgun Düşmedi. 

Şimdi Yüregim Yaşlı Bir Çınar Agacıdır...; 

Sırtını Dayamış Nice Aşıklar Gölgemde Soluklanır, 

Sen Yosun Yeşili Gözlerinle, 

Mülteci Bakışlarınla Yüregimi Yaraladın......, 

Bir Gün Uçup Gidecegini Bildigim Halde. 

O Gün 

Geldi; 

Sen Gittin. 

Demek Gidiyorsun, 

Yüregimde Depremler Yaratarak. 

Yüregim Kiralık Degildi... 

Sana Ucuza Vermiştim, 

Tek İstegim; 

Bir Gülüşün, 

Bir Öpücügündü Anlıyormusun.......? 

Sen Gittin, 

Kepenklerini Kapatı Yüregim Rahat Uyu; 

Ben Sensizligin Ebedi Uykusuna Daldım................ 

Hoşça Kal.', 'Yüreğim  Yüregimde Depremler, İsyanlar;  Yolunu Kayıp Etmiş Yetimler, Secdeye Duran Yaşlı Bir Ana.  Susamış Maviş Bir Çocuk,  Gözyaşlarımı K...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/yuregim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hece', 'hece-cemal-ekren-e1hcw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hece 

Bazen Saklı Aglamak Güzeldir. 

Ya Denizlere Gömülmeli, 

Yada Denizleri Gömmeli Gözbebeklerine, 

Öyleki Bilmeliler Agladıgını, 

Onikisiydi Yamandık, 

Onbeşinde Hırçın, 

Onsekizinde Bıçkındık.... 

Yirmiydi 

Daha Çok Yol Vardı Gidilecek; 

Geceydi, 

Ve İki Heceydi; 

Ölüm, 

Ölüm.........', 'Hece  Bazen Saklı Aglamak Güzeldir.  Ya Denizlere Gömülmeli,  Yada Denizleri Gömmeli Gözbebeklerine,  Öyleki Bilmeliler Agladıgını,  Onikisi...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Akşam', 'dun-aksam-cemal-ekren-b3av2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dolu Dolu Yagmur Yagdı Şehrime, 

Yüregime.., 

Sen Aglıyordun Gözlerin Boşalırcasına.., 

Sonra Şehirim Agladı. 

Kaldırımın Parke Taşları Ezilmekten İnliyordu, 

Sokak Kedisi Duvar Dibine Sinmiş Üşüyordu, 

Koşuşan İnsanlar, 

Caddeleri Sahipsiz Bırakıyorlardı, 

Beni Bırakıp Gittigin Gibi..., 

Şimdi Aglıyorsun, 

Gökyüzü Aglıyor, 

Ben Aglıyorum, 

Kedi Üşüyor.... 

Şehir; 

Adım İzleriyle Yalnız Kalıyor, 

Yagmur O İzleride Silip Süpürüyor... 

Şimdi; 

Sade Ve Magrur, 

Yalnız Kalıyor Şehirim, 

Bir Gelsen, 

Ellerin Avuçlarımın İçinde Olsa, 

Gözlerinde Parıldasa Yıldızlar..., 

Kapım Çalınıyor; 

Açıyorum........; 

Sennnnnnn, 

Kedi Üşümüyor Artık.....', 'Dolu Dolu Yagmur Yagdı Şehrime,  Yüregime..,  Sen Aglıyordun Gözlerin Boşalırcasına..,  Sonra Şehirim Agladı.  Kaldırımın Parke Taşları Ezil...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dun-aksam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-cemal-ekren-7yei2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasret

ne yalan, 

ne üç kağıt, 

nede ihanet, 

bin parça et, 

bir kadeh şarap

ve bin tuz tanesiydi aramızdaki

veyahut boş bir iskambil destesi

 bizi böyle ulaşılmaz kılan

ulaşılmaz kılan.......', 'Hasret ne yalan,  ne üç kağıt,  nede ihanet,  bin parça et,  bir kadeh şarap ve bin tuz tanesiydi aramızdaki veyahut boş bir iskambil destes...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hasret-112-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Göze Bir Can', 'i-ki-goze-bir-can-cemal-ekren-le6cr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'iki  göze  bir can

gecenin karanlığını  bölen  iki çift göz, 

korkuyla, 

kinle, nefretle, 

vede  küstahça...

bir can nöbetinde...., 

yorgun adımlarda gizli; 

bir sevdalı yürek.

sokağın  köşesinde pusuya yatmış, 

titrek, namustan uzak, 

hiç vermeyen, hep alan iki el..., 

zemheri ayazında; 

azrailliğe soyunmuşlar..., 

yorgun adımda bir heycan...

titrek bir mum ışıgı gibi parlayan ateş

sokağı doldurmuş; 

iki çift göz, 

bir sevdalı yürek.., 

o, 

sesizlikte yürüyen, bir  can.., 

sorgusuz sualsiz patlayan

bir ölüm....

nöbetini devirederken  katrankarası gece, 

sabaha, 

kinin ve nefretin  gözleri gömülüyordu toprağa

ve sevdalı yürek; 

yürüyordu, 

onuruyla mutluluga.....', 'iki  göze  bir can gecenin karanlığını  bölen  iki çift göz,  korkuyla,  kinle, nefretle,  vede  küstahça... bir can nöbetinde....,  yorgun ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/iki-goze-bir-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıraktığım Yerde Yoksun', 'biraktigim-yerde-yoksun-hasan-basri-isim-2ysc1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bıraktığım yerde yoksun; 

Suç benim biliyorum, 

Seni bensiz bıraktım.

Bir uçsuz bucaksız denizler, 

Bir ben anlarım seni, 

Bir de sokak lambaları ya; 

Onlarda yanmazki bu zamanlarda.

Kayalıklar mı çekti seni, 

Yoksa sesi mi dalgaların? 

Bana küstün biliyorum.

Bıraktığım yerde yoksun...

Biliyorum yine arasındasın kayalıkların, 

Yine dalgalar dövüyor seni, 

Yine maverasındasın aşkın, 

Yine ağlıyorsun, ağlıyorsun...

Battı bak güneş! 

Gel! 

Sokak lambaları BİZİ bekliyor.', 'Bıraktığım yerde yoksun;  Suç benim biliyorum,  Seni bensiz bıraktım. Bir uçsuz bucaksız denizler,  Bir ben anlarım seni,  Bir de sokak lamb...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Işım']::text[], 8.5, '{"poet":"Hasan Basri Işım","poet_slug":"hasan-basri-isim","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/biraktigim-yerde-yoksun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Seninleyim', 'bugun-seninleyim-hasan-basri-isim-iayjm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün seninleyim, 

Maverasında aşkın

Ya da berisinde...

Gördüğümün, 

Görüp de istediğimin, 

Avuçlarıma dolması gibi, 

Karanlığımda, 

Güneşin üzerime doğması, 

Kurumaya yüz tutmuşken, 

Çiğlerin böynumu yıkaması, 

Bomboşken kucağım; 

Kollarımın seni sarması

gibi.

Bugün seninleyim.

A''raftan indim yanına, 

Ezel-ebed arasına, 

Kollarına, 

Boynuna, 

Dudaklarına, 

Tâ ki ya-rı-na.', 'Bugün seninleyim,  Maverasında aşkın Ya da berisinde... Gördüğümün,  Görüp de istediğimin,  Avuçlarıma dolması gibi,  Karanlığımda,  Güneşin...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Işım']::text[], 8.5, '{"poet":"Hasan Basri Işım","poet_slug":"hasan-basri-isim","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bugun-seninleyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşaran Gözlerine', 'yasaran-gozlerine-mehmet-fatin-baki-qr5up', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben inandım, güzelim, gözlerinin sözlerine

Su salar kalpte yanan hasretimin közlerine.

Uzak ellerde bulunsam bile, on yıl daha çok

Yaşarım, bir kere baksam yaşaran gözlerine. 

Bu sızan gözyaşı toplansa gönül mahzenine

Dökeriz  güller için susamış gül bahçesine. 

Kara makberde de olsam yeni hislerle yine

Taşarım, bir kere baksam yaşaran gözlerine. 

Feilâtun  feilâtun  feilâtun  feilun 

.  .  /   / .  .  /   / .  .  /   / .  .  /', 'Ben inandım, güzelim, gözlerinin sözlerine Su salar kalpte yanan hasretimin közlerine. Uzak ellerde bulunsam bile, on yıl daha çok Yaşarım, ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yasaran-gozlerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sordum', 'sordum-mehmet-fatin-baki-czzwk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Rü’yamdaki âşüfte kadın nerde diyordum

Haşrolmak için yâra da ağyâra da sordum.

Cânım güzelim ben seni göklerde ararken

Hergün gece yıldızlara, rüzgâra da sordum

Dallarda konan kuşlara, ormandaki kurda

Otlar arasında sürünen mâra da sordum.

Çayhânede, keşhânede, meyhânede her dem

Sâkî’ye de sordum, seni ebkâra da sordum.

Geçmişte saraylarda dolaştın diye bir gün

Mecliste cesâret ile hünkâra da sordum. 

Kalbimdeki bir yaz günü gülgûn bağ içinde

Hem goncaya hem bülbüle, gülzâra da sordum. 

Ey sevgili cânan, yolumun son durağında

Yoktur dediler. Ben yine esrâra da sordum.

Âşüfte  = cilveli              Haşr = buluşmak

Mâr = yılan                     Ebkâr = bakireler

Gülgûn = gül renkli        Esrâr = sırlar

Mefûlü    mefâîlü    mefâîilü  feûlun

/   /  .  .   /   / .  .   /   / . .   /   /', 'Rü’yamdaki âşüfte kadın nerde diyordum Haşrolmak için yâra da ağyâra da sordum. Cânım güzelim ben seni göklerde ararken Hergün gece yıldızla...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sordum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tegafül', 'tegaful-mehmet-fatin-baki-tik9m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '‘Senden bilirim yok bana bir fâide. Ey gül’ (1) 

Mecnun gibi gel etmeyelim biz de tegâfül

Bülbül bile etmez daha çok hâra tahammül

Mecnun gibi gel etmeyelim biz de tegâfül

Çoktan beri kırgın sana bülbül ile sümbül

Meyhânede sümbülle beraber içiyor mül

Bülbül gelecektir diyerek etme tehayyül

Mecnun gibi gel etmeyelim biz de tegâfül

Senden yana bir neş’eli gün görmedi bülbül 

Artık yetişir bahçede gezmekle tedâvül

Bir kez daha ettim sizi Allâha tevekkül

Mecnun gibi gel etmeyelim biz de tegâfül

(1)  Osman Nevres’in şarkısından

Tegâfül = bilmezlikten gelme 

Hâr = diken

Mül = şarap

Mefûlü    mefâîlü    mefâîlü   feûlün

/    /  .   .   /   /  .  .   /   /  .  .   /   / 

Şarkı

Senden bilirim yok bana bir fâide. Ey gül

Gül yağını eller sürünür çatlasa bülbül

Etsem de abesdir sitem-i hâre tahammül

Gül yağını eller sürünür çatlasa bülbül

Ellerde o zevk etdi, ben ateşlere yandım

Çektim o kadar cevr ü cefâsın ki usandım

Derlerdi kabûl etmez idim şimdi inandım

Gül yağını eller sürünür çatlasa bülbül

Senden güzelim çare bana kat’-ı emeldir

Etsen dahî ülfet diyemem ellere haleldir

Ağyâr ile gezsen de gücenmem ki meseldir

Gül yağını eller sürünür çatlasa bülbül

Gördüm açılırken bu seher goncayı hâra

Sordum nola cev ü cefâ bülbül-i zâra

Bir âh çekip hasret ile dedi ne çare 

Gül yağını eller sürünür çatlasa bülbül

Bigâne edâdır bilir ol âfeti herkes

Ümmid-i visâl eyleme andan emelin kes

Beyhûde yere âh ü figân eyleme Nevres

Gül yağını eller sürünür çatlasa bülbül

 Osman Nevres   (1876)', '‘Senden bilirim yok bana bir fâide. Ey gül’ (1)  Mecnun gibi gel etmeyelim biz de tegâfül Bülbül bile etmez daha çok hâra tahammül Mecnun gi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/tegaful-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El Kızı', 'el-kizi-mehmet-fatin-baki-1joni', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Firkat-zede ben fakr-ü garip, sen de bir eldin

Deryâlar aşıp vuslat için sen bana geldin

Aklımda yer etmiş, hiç unutmam sen o akşam

Yıldız gibi göklerde melekten de güzeldin.

İkbâli hemen biz kaderin seyrine saldık

Aşk âlemi derken gece hülyâlara daldık

Biz böylece geç vakte kadar bir süre kaldık

Meltemli o seherde melekten de güzeldin

Rüzgarlı  semâlarda bulutlarla görüştük

Ay nûrunun altında harâretle öpüştük

Hûrî dolu âlemde yeşil cennete düştük

Cenneteki her yerde melekten de güzeldin.

Firkat-zede = ayrılık derdine uğrayan

Fakr-ü garip = fakir ve garip

İkbâl = bahtiyarlık

Mefûlü   mefâîlü   mefâîlü   feûlün

/   /  .    .   /   /  .  .   /   /  . .   /   /', 'Firkat-zede ben fakr-ü garip, sen de bir eldin Deryâlar aşıp vuslat için sen bana geldin Aklımda yer etmiş, hiç unutmam sen o akşam Yıldız g...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/el-kizi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harcatmayın ne olur bizi...!', 'harcatmayin-ne-olur-bizi-haci-ozturk-ktq4r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir”ANADOLU’dur kalan yurdumuz, yerimiz, 

Bu  vicdansızlara  harcatmayın ne  olur  bizi....! 

Vatan  için  her zaman   feda  canımız, 

Bu  vicdansızlara  harcatmayın  ne olur  bizi...! 

Örümcek sarmış  kafaları gitmek bilmiyor, 

Yapışmışlar  koltuğa  kalkmak  bilmiyor, 

Utanmadan  birde   orduyu dil   uzatıyor, 

Bitirin  bunları, harcatmayın  ne olur  bizi....! 

Kepenğ indirtip kilit vurdurdular  esnafa, 

Onlar için  her zaman  bol güneşli  hava, 

Onur  yoktur  vicçdansızlar  gelmez  insafa, 

Dağıtın  şunları  harcatmayın  ne  olur  bizi....! 

Banka  hortumlamak, rüşvet almak onur sayıldı, 

Bu illet hastalık tüm bürokrata yayıldı, 

Faturası  ise garip halkıma kesildi, 

Durdurun  şunları harcatmayın  ne olur bizi....! 

Az  gibi dörtyüz elliden, beşyüzelliye çıktılar, 

Enflasyon denen  kazığı göğsümüze  çaktılar, 

Tüyü  yetmemeiş bebenin  sütünü  çaldılar, 

İçirmeyin  bunlara, harcatmayın  ne olur bizi....! 

Türk  lirasımı..?  oda  ne..! waşıntona  tapıyor, 

Sam  babası  ne derse   çekinmeden  yapıyor, 

Memleket  parsellenmiş  parça, parça satıyor, 

Sattırmayın  bunlara  harcatmayın  ne  olur  bizi...! 

Yaptıklarınız  yanınıza sanmayın  kalacak, 

Elbet bıçak bir gün  kemiğe  dayanacak, 

Sanmayın  yaptıklarınız  af  olacak, 

Yıkın  bu  duvarı sakın  harcatmayın ne  olur  bizi....! 

“Hacım, , der  senin  gibi  niceleri  gurbette, 

Yeter  artık  komutanım  yeter   bekleme, 

Garantimiz, güvencemiz  sizlersiniz  elbette, 

Ezin  başlarını bunların  harcatmayın  ne  olur  bizi....! 

Hacı  Öztürk                       08/08/2001

                                            LİBYA

KAYDEDEN                      Hacı  Öztürk', 'Bir”ANADOLU’dur kalan yurdumuz, yerimiz,  Bu  vicdansızlara  harcatmayın ne  olur  bizi....!  Vatan  için  her zaman   feda  canımız,  Bu  v...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/harcatmayin-ne-olur-bizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Yoruldum', 'artik-yoruldum-sevilay-saban-mp9ra', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdim, sevildim sandım

Yıllarca peşinden sürüklendim

Ben yalancı gözlere inandım

Artık yoruldum

Yere düşen solmuş gülün hüznü

Var yüreğimin derinliğinde

Ölçüsüz yaşamak istemiyorum

Artık yoruldum

Geceler yüzümü örttü

Sessizlik en iyi dostum oldu

Umutsuzluk eşim oldu

Artık yoruldum

Senden büyük ümitler beklemedim

Olasılıkları sen ile yaşamadım

Ben hayal dünyam ile acıları buldum

Artık yoruldum

Kırık parçalanmış kalbim

Çizgi, çizgi olmuş yüzüm

En gerçek yanım

Artık yoruldum

İçimdeki güzel çocuğun

Ana dili suskunluk

Geleceği yalnızlık

Artık yoruldum', 'Sevdim, sevildim sandım Yıllarca peşinden sürüklendim Ben yalancı gözlere inandım Artık yoruldum Yere düşen solmuş gülün hüznü Var yüreğimin...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Saban']::text[], 8.5, '{"poet":"Sevilay Saban","poet_slug":"sevilay-saban","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/artik-yoruldum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladım bugün gelmeyeceksin..!', 'anladim-bugun-gelmeyeceksin-haci-ozturk-ugl4a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Son bir umudumdun  ekrana  gömdüm, 

Anladım  bugün gelmeyeceksin  toprak.

Çok bekledim, çok  sabırla direndim, 

Anladım bugün gelmeyeceksin  toprak.

Doğrusu bu mecbur değilsin  bana, 

Bilirsinki  çok değer veririm  sana, 

Her şey bir tarafa, bir tarafa  ankara, 

Anladım bugün gelmeyeceksin  toprak.

Evde  olsaydın  eminim ki arardın...! , 

Olmasamda   hatırımı sorardın..! 

Rahat olsun diye bir şey yazardın..! 

Anladım bugün  gelmeyeceksin  toprak, 

Sanma  boş  sözlerle seni yoruyorum, 

Dostluk de, arkadaşlık de seni seviyorum, 

Seni  unutmaz bu garip” hacı, diyorum, 

Anladım bugün  gelmeyeceksin toprak.

Hacı  Öztürk                       26/06/2003

                                            LİBYA

KAYDEDEN                      Hacı   Öztürk', 'Son bir umudumdun  ekrana  gömdüm,  Anladım  bugün gelmeyeceksin  toprak. Çok bekledim, çok  sabırla direndim,  Anladım bugün gelmeyeceksin ...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/anladim-bugun-gelmeyeceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gece', 'dun-gece-ceyhun-yilmaz-hnn24', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ve dün gece; 

Aynada bile, 

Ben bile, 

Beni ben sanıp, 

Sen diye kırdım aynamı.', 'Ve dün gece;  Aynada bile,  Ben bile,  Beni ben sanıp,  Sen diye kırdım aynamı....', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dun-gece-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım', 'yalnizim-sevilay-saban-zytac', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Umutsuz dolaşıyorum yollarda

Sokaklar unutuyor karanlıkta

Hayaletmiyim neyim sokaklarda

Anlamadan öleceğim bu sokaklarda

Yalnızım kurtarın sokaklar

Boşluktan kurtarın sokaklar

Yalnızlık insanı öldürür derler

Ölüyorum kurtarın sokaklar

Gözlerim dünyaya kapanınca

Bedenim toprakta ruh bulunca

Ancak o zaman huzur bulunca

Yalnız olmadığımı anlayacağım

Neden kendimi aldatılmış hissediyorum

Neden ölümü yakın görüyorum

Neden yalnız olduğumu sanıyorum

Neden neden işte yine neden

Dünyayı iyi tanısaydım

İnsanları tanımayı bilseydim

Kendimi şimdi bu kadar yalnız

Bu kadar boşlukta hissetmezdim', 'Umutsuz dolaşıyorum yollarda Sokaklar unutuyor karanlıkta Hayaletmiyim neyim sokaklarda Anlamadan öleceğim bu sokaklarda Yalnızım kurtarın s...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Saban']::text[], 8.5, '{"poet":"Sevilay Saban","poet_slug":"sevilay-saban","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalnizim-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat 01.17', 'saat-01-17-huseyin-kapan-y9s9c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Huzun kokulu bır subat gecesınde, adını yazıyorum goz yaslarıma, tıtrek bır mumun ruzgarında! Ozledıgım cocuk seslerı gıbı hasretım yoklugunda gozlerıne. Hıc bu kadar hoyrat bır hasret kaplamamıstı sefıl yuregımı ve hıc bır gece sabaha bu kadar gec kavusmamıstı! Senle baslayan her ısyankar sarkı yoklugunda daha da vuruyor hucrelerımı ve umut tasıyan multecı bulutlar goz yaslarıma bıle vokal yapamıyor artık! Sen baskasın bılıyorum, hıc olmadık zamanlarda hep dustun aklıma, hep gırdın şu yaralı hayatıma! Ama sımdı nerdesın, nerelerdesın, hangı dıyarlarda, hangıs sıırın ımgesındesın! Sen benım ıcın herseysın, hersey! Ruyalarımın hıc degısmeyen basrol oyuncusu, ya da hayallerımın ası gelıncıgı! Hep bendesın, hep aklımdasın anlıyacağın...', 'Huzun kokulu bır subat gecesınde, adını yazıyorum goz yaslarıma, tıtrek bır mumun ruzgarında! Ozledıgım cocuk seslerı gıbı hasretım yoklugun...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kapan']::text[], 8.5, '{"poet":"Hüseyin Kapan","poet_slug":"huseyin-kapan","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/saat-01-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim', 'ogretmenim-sevilay-saban-xy4nx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevinç ve üzüntüyü paylaşan

Öğrencileri ile gurur duyan

Bir harfi öğretmek için çaba gösteren 

Sensin sensin öğretmenim

Gösterdiğin çabaya karşılık veren

Sana inanan, sana güvenen

Seni bir ömür boyunca biz

Mutlu görmek isteriz öğretmenim

Mutsuz, üzüntülü olsanda

Bize belli etmezsin öğretmenim

Gözyaşları içinde boğulsanda

Bunu anlayamayız öğretmenim

Ders çalışmama gerek yok diye

Seni üzeriz öğretmenim

Fakat sen bizden çok

Ders çalışırsın öğretmenim

Gözlerindeki kararlığı

Sert bakışlarının altındaki

Güzel gülümsemeyi hatırladıkça

Hala gülerim öğretmenim', 'Sevinç ve üzüntüyü paylaşan Öğrencileri ile gurur duyan Bir harfi öğretmek için çaba gösteren  Sensin sensin öğretmenim Gösterdiğin çabaya k...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Saban']::text[], 8.5, '{"poet":"Sevilay Saban","poet_slug":"sevilay-saban","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ogretmenim-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Gözlü Sevgili', 'mavi-gozlu-sevgili-sevilay-saban-5spau', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen gidince buralardan, unuttum ben gülmeyi

Götürdün bendeki neşemi, sevincimi

Gönlüm ara bul diyor sevdiğini

Ey mavi gözlü sevgili gel artık

Seni heryerde aradım, sordum

Mehtaplı gecelere, parlayan yıldızlara

Dağlara, yollara seni sordum

Nerde mavi gözlü sevgilim diye

Özlemini kalbimin en derin köşesinde sakladım

Duymak, dinlemek istermisin özlemlerimi

Hayallerinle avuttum yıllarca kendimi

Bekletme senin için atan bu kalbi

Gündüzüm geceme karıştı hasretinle

Rüyamda sen., dünyamda sen

Bir saniye görmek için bile seni

Ömrümü, hayatımı herşeyimi veririm

Sevda yarası bu gönlümdeki

Sönmeyen alev bu yüreğimdeki

Ey sevgili hançerini saplayıp gittin

Gel artık gel gamsız sevgili', 'Sen gidince buralardan, unuttum ben gülmeyi Götürdün bendeki neşemi, sevincimi Gönlüm ara bul diyor sevdiğini Ey mavi gözlü sevgili gel artı...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Saban']::text[], 8.5, '{"poet":"Sevilay Saban","poet_slug":"sevilay-saban","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mavi-gozlu-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-sevilay-saban-ae5dm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkın yolu aşılmaz

Sevdanın kolu kapanmaz

Gözlerdeki yaş dinmez

Hasret hiç tükenmez

Ateştir yakar kavurur

Çiledir dert yapar öldürür

Bilirsin görünmez kazadır

Geride kalan herşeyi alır götürür

Gördüğüm bir rüyamıdır

Yoksa çöldeki serapmıdır

Her ikisindede uyanmak lazımdır

Bu bir sevgi oyunudur

Arkana bakmadan kaçarsın

Gözlerini yumar açmazsın

Dilinden bir söz bile etmezsin

Genede bir meçhule yakalanırsın

Gecenin ışığına bakma

Gündüze aldanıp çıkma

Falcının lafına kanma

Gördüm sanıpta aldanma', 'Aşkın yolu aşılmaz Sevdanın kolu kapanmaz Gözlerdeki yaş dinmez Hasret hiç tükenmez Ateştir yakar kavurur Çiledir dert yapar öldürür Bilirsi...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Saban']::text[], 8.5, '{"poet":"Sevilay Saban","poet_slug":"sevilay-saban","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ask-157-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buse', 'buse-sevilay-saban-yglyr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlk gördüğümde seni bir heyecan

Anlamsız bir sızı duydum ta yüreğimde

O zaman anlamalıydım, kaçmalıydım

Ama geç kaldım, 

Mavi gözlerine tutuldum

İşin yokmuş, evin yokmuş

Kim takar maddiyatı

Sen bir bak yeter

Ne diyeceğini, ne isteyeceğini

Konuşma, gözlerin anlatır bana

Her sabah kalktığımda

Senin için giyinir, süslenirim

Her sözüm senin için dökülür

Seni kırmaktan çok korkarım

Biri sana birşey söylediğinde

Senden çok ben alınırım

Sana aldığım hiçbirşeyi beğenmiyorsun

Her hareketime bir mazeret bulursun

Olsun ben genede seni düşünürüm

Hep yanımda yamacımda ol

Bana benden yakın ol

Ama sen hep kaçarsın

Başka limanlar ararsın

Beni hep yedekte tutarsın

Nasıl olsa benim sevgim

Sana olan tutkum

Hiç bitmek bilmez

Sen başka kollar ararken

Çeşitli kapılar açarken

Bense bana verdiğin 

O küçücük busen ile avunurum', 'İlk gördüğümde seni bir heyecan Anlamsız bir sızı duydum ta yüreğimde O zaman anlamalıydım, kaçmalıydım Ama geç kaldım,  Mavi gözlerine tutu...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Saban']::text[], 8.5, '{"poet":"Sevilay Saban","poet_slug":"sevilay-saban","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/buse-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'F....s. O....d''e', 'f-s-o-d-e-edgar-allan-poe-d2iy5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevilmek mi? -öyleyse bırakma yüreğini

Şimdiki yolundan ayrılmaya.

Olduğun herşeyken şimdi, 

Olmadığın şey olma.

Böylece kibarlığın, lütfun, 

Aşkın güzelliğin, sonsuz bir

Övgü konusu olacak yeryüzünde, 

ve aşk-basit bir görev.', 'Sevilmek mi? -öyleyse bırakma yüreğini Şimdiki yolundan ayrılmaya. Olduğun herşeyken şimdi,  Olmadığın şey olma. Böylece kibarlığın, lütfun,...', ARRAY['Türk Edebiyatı','Şiir','Edgar Allan Poe']::text[], 8.5, '{"poet":"Edgar Allan Poe","poet_slug":"edgar-allan-poe","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/f-s-o-d-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelin Baladı', 'gelin-baladi-edgar-allan-poe-mnylb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüzük parmağımda, 

     Ve alnımda gelin çelengi; 

Muhteşem mücevherler ve satenşer

Hepsi emrinde, 

     Ve ben mutluyum şimdi.

Ve Lordum ki beni çok sever; 

     Ama andını ilk kez içtiğinde, 

Hissetim göğsümün kabardığını-

Çünkü bir ölüm çanı gibi öttü sözler

Ve ses onunkiymiş gibi geldi.

     Savaşta düşmüştü o kuytu ağaçlıkta

     Ve mutludur şimdi.

Ama konuşup bana güvence verdi, 

     Ve solgun alnımı öptü, 

Derken bir hayal hali geldi üzerime, 

Ve kilise avlusuna taşıdı beni, 

Ve ona dedim ki iç çekerek

(merhum D''Elormie sanıp onu) 

    ''Oh, mutluyum şimdi''.

Ve böylece söylendi bu sözler, 

    Ve bu evlilik andı; 

Ve, inancım yıkılsa da, 

Ve, kırılsa da kalbim, 

Delil olarak burada yüzük

    Ki mutluyum şimdi, 

Bak, mutluluğumu kanıtlayan

    Şu altından simgeye.

Tanrım, uyanabilseydim keşke.

    Çünkü bilmeden düş görüyorum nasıl olduğunu, 

Ve fena sarsılıyor ruhum

Atılmasın diye yanlış bir adım, -

O unutulan ölü

    Mutlu olmayabilir belki diye', 'Yüzük parmağımda,       Ve alnımda gelin çelengi;  Muhteşem mücevherler ve satenşer Hepsi emrinde,       Ve ben mutluyum şimdi. Ve Lordum ki...', ARRAY['Türk Edebiyatı','Şiir','Edgar Allan Poe']::text[], 8.5, '{"poet":"Edgar Allan Poe","poet_slug":"edgar-allan-poe","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/gelin-baladi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göl:...''ye', 'gol-ye-edgar-allan-poe-o93h3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu yaban dünyada bir köşe vardı.

Gençliğimizin baharında gittiğim, 

Kara kayalarla sarılmış ve

Yüksek çamların kuleleriyle çevrilmiş-

Öylesine güzeldi ki yalnızlığı

Vahşi bir gölün, onu daha az sevemzdim.

Ama kara kefenini serdiğin gece üzerine

Herşeye serdiğin gibi, 

Ve gizemli rüzgar

Ahenkle mırıldanarak gittiğinde, 

O zaman- aho zaman- uyanırdım.

Issız göl dehşetine.

Ama korku değildi

İnsanı titreten bir zevkti bu dehşet-

Öyle bir duygu ki ne madenler, mücevherler

Ne de- hatta senin aşkın

Kandırabilirdi anlatmaya beni

O zehirli dalgadaydı ölüm

Bir mezarlık çukurumda-

Yalnız imgelemi böyle teselli bulan, 

Kimsesiz ruhu bu karnlık gölden

Bir Adeb yaratan, O''nun için', 'Bu yaban dünyada bir köşe vardı. Gençliğimizin baharında gittiğim,  Kara kayalarla sarılmış ve Yüksek çamların kuleleriyle çevrilmiş- Öylesi...', ARRAY['Türk Edebiyatı','Şiir','Edgar Allan Poe']::text[], 8.5, '{"poet":"Edgar Allan Poe","poet_slug":"edgar-allan-poe","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gol-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Helen''e', 'helen-e-edgar-allan-poe-t8nlu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Helen, senin adın

Eskinin Nicean yelkenlileri gibidir, benim için

Usulca, kokulu denizin üzerinden

O yol yorgunu gezgini taşır

Kıyısına kendi memleketinin

Gezmeyi özler yapayalnız denizlerin üstünde

Yunanlı yüzün, sümbül saçların

Senin havaların getirmişti beni eve

Yunanistanın görkemine ve

Roma yüceliğine.

İşte, oradaki pırıltılı pencere nişinde

Nasıl da bir heykel gibi, görürüm dineldiği

Ah, Pysche, kutlu topraklar olan bölgelerden

Akik lamba elinde.', 'Helen, senin adın Eskinin Nicean yelkenlileri gibidir, benim için Usulca, kokulu denizin üzerinden O yol yorgunu gezgini taşır Kıyısına kend...', ARRAY['Türk Edebiyatı','Şiir','Edgar Allan Poe']::text[], 8.5, '{"poet":"Edgar Allan Poe","poet_slug":"edgar-allan-poe","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/helen-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlahi', 'i-lahi-edgar-allan-poe-axkp4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sabahleyin-öğlenleyin-akşam karanlığında-

Benim ilahimi duyarsın, Maria.

Kederde ve sevinçte, iyide ve kötüde, 

Tanrının anası benimle ol.

Saatler pırıltıyla uçtuğunda, 

Ve tek bir bulur karartmadığında göğü, 

Aylak olmasın diye ruhum, 

Lütfun götürürdü onu sana ve seninkine; 

Şimdi, fırtınaları kaderin

Geçmişimi ve günümü karartınca, 

Bırak ışısın geleceğim

Senin ve senin olanın tatlı ümidiyle', 'Sabahleyin-öğlenleyin-akşam karanlığında- Benim ilahimi duyarsın, Maria. Kederde ve sevinçte, iyide ve kötüde,  Tanrının anası benimle ol. S...', ARRAY['Türk Edebiyatı','Şiir','Edgar Allan Poe']::text[], 8.5, '{"poet":"Edgar Allan Poe","poet_slug":"edgar-allan-poe","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ilahi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkı', 'sarki-edgar-allan-poe-1rst6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gelin olduğun gün gördüm seni-

    Alevli bir pembelik yüzüne indiğinde

Mutlulukla sarılmıştın, öyleyken

    Tümden aşka kesilmişti dünya önünde.

Ve senin gözlerinde tutuşan ışık

    (artık her ne idiyse) 

Güzellik diye gördüğüydü

    Sızlayan gözlerimin yeryüzünde.

O pembelik, kızlık utancı belki-

    Geçip gider öyleyse-

Ama hala harlı bir ateş, öyleyken

    Tutuşturdu, yazık, o adamın göğsünde.

O, gelin olduğun gün seni gören

    Hani şu derin pembelik yüzüne çöktüğünde

Mutlulukla sarılmıştın, öyleyken

    Tümden aşka kesilmişti dünya önünde.', 'Gelin olduğun gün gördüm seni-     Alevli bir pembelik yüzüne indiğinde Mutlulukla sarılmıştın, öyleyken     Tümden aşka kesilmişti dünya ön...', ARRAY['Türk Edebiyatı','Şiir','Edgar Allan Poe']::text[], 8.5, '{"poet":"Edgar Allan Poe","poet_slug":"edgar-allan-poe","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sarki-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'M.L.S....''ye', 'm-l-s-ye-edgar-allan-poe-zycrc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Varlığını sabah diye selamlıyanlardan-

Yokluğunu gece sayanlardan-

Yüksek göklerde kutsal ateşi gölgeleyen-

Ağlayarak ümit için her saat seni kutsayanlardan-

Yaşam için-ah. Hepsinin üstünde, 

Derinlere gömülü inancın Gerçeklik

Erdem ve İnsanlıkta canlanması için-

Ümitsizliğin menfur yatağında ölmeye yatanlardan, 

Birden yükselir, senin mırıldandığın sözler üzre, 

''Işık olsun''

Mırıldandığın sözlerin, gözlerinin-

Seraphlara özgü bakışıyla gerçekleşen-

Sana en çok borçlu olanlardan-şükranı

Tapınmaya benzeyen-ah, anımsa

En doğrusunu-adanmış olanı en çok tutkuyla, 

Ve düşün ki bu güçsüz dizeleri o yazdı-

O yazdı, yazarken ürperip düşünerek

Bir olduğunu ruhunun bir meleğinkiyle', 'Varlığını sabah diye selamlıyanlardan- Yokluğunu gece sayanlardan- Yüksek göklerde kutsal ateşi gölgeleyen- Ağlayarak ümit için her saat sen...', ARRAY['Türk Edebiyatı','Şiir','Edgar Allan Poe']::text[], 8.5, '{"poet":"Edgar Allan Poe","poet_slug":"edgar-allan-poe","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/m-l-s-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsak', 'tutsak-sevilay-saban-o0oie', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni ilk öptüğün an ağlamak istedim

Bu benim ilk gerçek öpücüğümdü

O dudaklar yavaş yavaş dudaklarıma

Yaklaşıyor yaklaşıyordu

Allah''tan bir sandalyede oturuyordum

Karşılık bile verememiştim

Bilmiyorum, hatırlamıyorum bile

Kalbim o kadar hızlı atıyordu ki

Öleceğim sandım

Benim için bu öpücük herşeydi

Artık ben senindim

Kıyafetlerim, saçlarım değişti önce

Sonra yürüyüşüm, konuşmam değişti

Hepsi senin içindi

Bak bir öpücük ile neleri becerdin

Beni benden çıkardın

Kişiliğim değişti, psikolojim bozuldu

Asi kıskanç bir bayan oldum

Seni senden çok sevdiğim

Seni kendimden çok sevdiğim için

Artık ben ben değildim

Sana birinin bakışı beni öldürüyor

Senin ise bunlar hoşuna gidiyor

Tabii ya paylaşılamayan erkek

Ne mutlu sana, istediğin herşeyi yapan

Gözlerinin büyüsüne kapılan ben

Bir uçurumun dibindeyim

Kendimi tanıyamıyorum, bir çıkar yol arıyorum

Bulamıyorum, o çağırıyor ben gidiyorum

O istiyor ben yapıyorum

Ben artık yaşamayan bir robotum

Pilim yettikçe ben onunum', 'Beni ilk öptüğün an ağlamak istedim Bu benim ilk gerçek öpücüğümdü O dudaklar yavaş yavaş dudaklarıma Yaklaşıyor yaklaşıyordu Allah''tan bir ...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Saban']::text[], 8.5, '{"poet":"Sevilay Saban","poet_slug":"sevilay-saban","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/tutsak-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kandil', 'kandil-naime-erlacin-1p84k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'karanlık saatlere yakıldı kandil

sustu ölüm uğursuz pervanede

yükselirken canhıraş feryat ve sessizlik

söndü gök kubbe yas tutarak o yerde

düşünceli “son” karanlığı izlerken

ölüm imzalanıyordu acıklı bir fermanda

ilk günden yitirilen can haykırışı bu

onikiden vuruldu idam mangasında

hayat cömertti güya

boncuklar dağıtırdı maviden

donatırdı gökyüzünü şen bayramlarca

son kandil mevsimi vurunca damgayı

vakit sus''tadır artık kör alacasında

elveda kandil

elveda ışığım

zaman 

ayrılığı vurmakta derinden

(28 Haziran 2003)', 'karanlık saatlere yakıldı kandil sustu ölüm uğursuz pervanede yükselirken canhıraş feryat ve sessizlik söndü gök kubbe yas tutarak o yerde d...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kandil-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Anlayış', 'sevgiliye-anlayis-sevilay-saban-n9c7k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdin sende beni bir zamanlar

Ne oldu şimdi seni değiştiren ne

Benim sevgim gene senin

Bu gözler sana hep aynı bakıyor

Aynı içtenlikle gülüyor

Neden böylesin neden

Biri var yada birileri

Hangi limana demir atacağını

Bilemiyorsun anlaşılan

Biri mavi gözlü, sarışın bir afet

Biri 90-60-90 bir manken

Biri simsiyah gözleri ile esmer güzeli

Ve birde geriye bakıyorsun tabi

Eh bizede sana hak vermek düşer

İnsan onları gördükten sonra

Geriye, maziye hiç bakmaz

Olsun bana buda yeter

Beni sevdiğin günler yeter

Anılarımın en renkli bölümü

Senin ile geçen günler

Bana aşkı tattırdığın için

Sana sonsuz teşekkürler', 'Sevdin sende beni bir zamanlar Ne oldu şimdi seni değiştiren ne Benim sevgim gene senin Bu gözler sana hep aynı bakıyor Aynı içtenlikle gülü...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Saban']::text[], 8.5, '{"poet":"Sevilay Saban","poet_slug":"sevilay-saban","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevgiliye-anlayis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azrail', 'azrail-sevilay-saban-a3gr2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün herzamankinden farklı

Görünüşte aynı gün, ama bende farklı

Evde yalnızım, pencereden bakıyorum

Birşeyler olacak biliyorum

İçim kıpır kıpır, yüreğim ağzımda

Öylece oturmuş bekliyorum

Bakıyorum ama görmüyorum

Birden birşey oldu

Vücudum kaskatı kesildi

Yaşıyorum ama hissetmiyorum

Sen sende kimsin, nasıl girdin evime

O öyle bakıyordu

Kalkmak istiyorum, bağırmak istiyorum

Olmuyor bu kim, neden öylece bakıyor

Ben şaşkın, aklımda binlerce düşünce

Gel, gel benimle dedi

Ruhum sevinçle vücudumdan ayrılmak

Beni terk edip gitmek için

Hareket etmeye, kıpırdanmaya başladı

Dur dur dedim

Şimdi olmaz olmaz dedim

Daha çok erken

Çocuklarım geldi aklıma

Onlar daha küçük bensiz ne yaparlar

Götürme beni, onları büyüteyim

Elleri ekmek tutsun, mürvetlerini göreyim

O zaman gel götür beni

Ama şimdi olmaz, lütfen

Ağlıyordum, yalvarıyordum

Olmaz ömrün bu kadar benimle gel

Anladımki vazgeçmiyecek

Beni almadan burdan gitmiyecek

Birkere daha çocuklarımı göreyim

Onları sonkez öpeyim, vedalaşayım

Lütfen buna bari izin ver

Şimdi gelirler okuldan

Tamam ben beklerim dedi

Nekadar hızla geçiyor zaman

Evime, resimlerime bakıyorum sonkez

Hayır artık ağlamıyacağım

Yazılan yazı silinmez

Bukadarmış ömrüme biçilen zaman

Daha hiçbirşey yaşamamış, gün görmemişken

Gidiyorum buralardan

Ey Allah''ım duy sesimi

Ben bu dünyaya doyamadım

Sesler evet geldiler

Koştum öptüm, sarıldım şaşkın bakışlar altında

Beni izleyen o masum gözler

Öğütler veriyorum, onları çok sevdiğimi söylüyorum

Daha küçükler nerden bilecekler

Annelerinin onları son öpüşü olduğunu

O arkamda evet geldi gene

Bir damla gözyaşı döküldü

Bekle dedim

Çocuklar oynayın hadi siz

Yatağıma gittim, hadi al canımı

Ben bu dünyaya, çocuklarıma doyamadım

Ve boğazıma bir yumru takıldı

Artık konuşmak istesemde olmuyor

Canım yavaş yavaş çıkarken

Ruhum sevinçle özgürlüğün tadını çıkarıyordu

Elveda dünya, iyi bakın çocuklarıma.', 'Bugün herzamankinden farklı Görünüşte aynı gün, ama bende farklı Evde yalnızım, pencereden bakıyorum Birşeyler olacak biliyorum İçim kıpır k...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Saban']::text[], 8.5, '{"poet":"Sevilay Saban","poet_slug":"sevilay-saban","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/azrail-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahtına Eren Güller', 'bahtina-eren-guller-ethem-vayvayli-m16p4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zamandır ağır yenilgilerden uyandıran beni

Ellerimde güller...

Ricat emer dururken yalnızlığım

Rıhtımları boşaltıp, söküp iskeleleri

İncecik yollar açıp yeşil gözlerinden

Narin yüreğine demirledim şimdi. 

20 Haziran 2003/Ankara', 'Zamandır ağır yenilgilerden uyandıran beni Ellerimde güller... Ricat emer dururken yalnızlığım Rıhtımları boşaltıp, söküp iskeleleri İncecik...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bahtina-eren-guller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Anneciğim', 'ah-annecigim-sevilay-saban-wvriz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni ben eden bu yaşa getiren

Hüznü kendi yaşayıp, neşesini paylaşan

Kendini yalnız hissettiğinde gizli ağlayan

Benim dert yüklü güzel annem

Zamanı gelmiş kuşlar gibi nereye böyle

Birşeyler var sende

Sanki gitmek istiyorsun buralardan

Huzur dolu sakin diyarlara

Biliyorum gönlünce yaşamak isterdin

Hiç hesapsız, tasasızca

Olmadı değilmi anneciğim

Genç yaşında sorumluluk verdiler

Öyle birşeyki, boynuna takılan bir kement

Yıllarca peşinden sürükleyen

Ah anneciğim bir imkanın olsaydı

Beni buralarda sensiz bırakırmıydın

Düşün düşün anne

Beni gideceği yer belli olmayan 

Yaprak gibi rüzgara bırakırmıydın

Tombulum benim, senin özgür olmanı

Herşeyin gönlünce, istediğin gibi

Olmasını çok isterdim

Anlaşılan bu dünya sana yetmiyor

Dar geliyor, yerim dar diyorsun

Ama ben sensiz biçareyim

Elim, kolum, gözüm, kulağımsın

Sen olmassan ben sağır, körüm

Ben doğum sancısı çeken ama

Bir türlü doğuramayan bir kadının

Acısını, çaresizliğini çekerdim

Sen yanımdayken anneciğim

Her yıl meyve vereceğini

Bilerek neşelenen ağacım

Ah annem ne olurdu sanki

Benimle mutlu olmayı denesen

Ben sana yetmiyormuyum

Seni anlamıyormuyum

Seni senden çok düşünürüm

Belki sende aynı duygulardasın

Bir türlü unutamadığım senin o

Hüzünlü, mutsuz yüzüne baktıkça

Kahroluyorum, yok oluyorum

Bu zamanın getirdiği yada hediye ettiği

Yüzündeki harita gibi çizgiler

Beni benden ediyor

Ah anneciğim çokmu çektirdiler

Beni bile bırakmak istiyorsun

İnan orada herkese yer var

Ama benim yüreğimde sadece sana yer var

Lütfen bu yüreği yalnız bırakma

O toprak seni benden alacaksa

Önce beni alsın ki

Seni yalnız bırakmayayım

Ah anneciğim yüreğime serpilen 

Bir yudum su gibisin

Gönlümde açan çiçekler gibisin

Bu gözler sensiz görmez

Unutma unutma anneciğim

Gideceğin yer karatoprak bile olsa

Senden önce ilk yolcusu ben olacağım', 'Beni ben eden bu yaşa getiren Hüznü kendi yaşayıp, neşesini paylaşan Kendini yalnız hissettiğinde gizli ağlayan Benim dert yüklü güzel annem...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Saban']::text[], 8.5, '{"poet":"Sevilay Saban","poet_slug":"sevilay-saban","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/ah-annecigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardeşim ve Hastane', 'kardesim-ve-hastane-sevilay-saban-8qms5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçimde bir sızı anlaşılamayan feryadlar var

Elim kolum bağlı çaresizlik var

Doktor konuşuyor ben dinliyorum

O uçsuz bucaksız görünen hastane koridorları

Bir uzuyor, bir kısalıyor

Sesler, o sesler kan lazım

Acil kan lazım

Hemşireler koşturuyor, serum takılıyor

Ben 20 günlük yeğnim ile yapayalnız

Tanıdık kimse yok, herkes birşeyler söylüyor

Ben işitmeden duyuyorum

Kardeşim benim bitane küçüğüm

Büyümüşte çocuğu için hastanede

Ölümün kara pençeleriyle çarpışıyor

Uzaklarda güneş doğarken

Bizde heryer karanlık

Birtürlü aydınlanmıyor buralar

Çaresiz ameliyatı beklerken

Zamanın benim ile olan kavgasını unuttum

Geçmiyor birtürlü saatler

Biri kucağımda uyuyor, uğruna can verilen

Diğeri ise yanımda boş gözlerle bakıyor

Birgün önce içine doğmuş gibi

Abla çocuklarım sana emanet diyor

İyi bak onlara, ben gülüyorum

Aman ne olacak diye moral veriyorum

Şimdi ne olacağını bilmeden bekliyoruz

Doktor göründü haydi gözünüz aydın

Baktım çocukların yüzünde güller açmış

Küçücük kardeşim kazanmıştı savaşını

Tabi ilerde ne olacağını Allah bilir

Geçmiş olsun güzel kızıma

Çocukları ile bir ömür mutlu ola.', 'İçimde bir sızı anlaşılamayan feryadlar var Elim kolum bağlı çaresizlik var Doktor konuşuyor ben dinliyorum O uçsuz bucaksız görünen hastane...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Saban']::text[], 8.5, '{"poet":"Sevilay Saban","poet_slug":"sevilay-saban","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kardesim-ve-hastane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akliman Zamanları 4', 'akliman-zamanlari-4-zeki-ergin-ztb49', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sevdaları yorgun olsa da

gökkuşağı altındadır

bir yağmur sonrası

zeytinler ve onlar

sevdalarına tuz bassalar da

güneş altındadırlar

bir yağmur sonrası

güneş ve onlar

sevdaları

deniz üstündedir

bir yağmur sonrası

umutlarıyla

zeytin 

güneş

deniz

yağmur ve gökkuşağı sonrası

rastgele dediler bir ağızdan

_babakale haz03

_sevgiliye isyan yt:haz04', 'sevdaları yorgun olsa da gökkuşağı altındadır bir yağmur sonrası zeytinler ve onlar sevdalarına tuz bassalar da güneş altındadırlar bir yağm...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/akliman-zamanlari-4-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tenimdeki Mandal', 'tenimdeki-mandal-selda-baytas-z4kqw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vücudumu yatağıma serdim

Bedenimde sen..

Başımı yastığıma verdim

Yok

Taşlardan eser..

Mandallarımı ipe dizdim

Rüzgarda şimdi

Bendeki sen..', 'Vücudumu yatağıma serdim Bedenimde sen.. Başımı yastığıma verdim Yok Taşlardan eser.. Mandallarımı ipe dizdim Rüzgarda şimdi Bendeki sen.....', ARRAY['Türk Edebiyatı','Şiir','Selda Baytaş']::text[], 8.5, '{"poet":"Selda Baytaş","poet_slug":"selda-baytas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tenimdeki-mandal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-hilmi-kayihan-5i7mc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sonu başta

başta sonu

dipte zirveyi

zirveyi dipte gördüm

Susuz çamuru bataklıkta

çirkinliği güzellerde gördüm

Tosulayanda yaşlılığımı

Cetvelde gençliğimi gördüm

Sabunu kirimle

Suyu ateşimle yıkadım

Payanda yaptım deliliğime şiirleri

Düşler gördüm düşümde ben', 'Sonu başta başta sonu dipte zirveyi zirveyi dipte gördüm Susuz çamuru bataklıkta çirkinliği güzellerde gördüm Tosulayanda yaşlılığımı Cetvel...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Kayıhan']::text[], 8.5, '{"poet":"Hilmi Kayıhan","poet_slug":"hilmi-kayihan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dus-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçeğim', 'cicegim-sevilay-saban-6krso', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir şarkıdır seni bana hatırlatan

Günlerdir içimi kavuran ateştir senin hatıran

Gördüm, duydum birtürlü inanmak istemedim

Sen solmuş, çürümüşsün benim küçük çiçeğim

Sen benim umudum, dileğim, herşeyimdin

Seni ilk saksıya koyduğum günü hatırladımda

Boynu bükük, ufacık bir bitkiydin

Seninle saatlerce konuştum, dertlerimi anlattım

Sevinçlerimi paylaştım, sevgilimi söyledim

Hiç yorulmadan beni dinledin

Her hafta sonu silerdim, zeytinyağı ile yapraklarını

Parıl, parıl parlardın, güneş sana doğardı

Seni bırakalı şurda bir ay oldu, olmadı

Geldim sen karabasan gibi birden yok oldun

İnan izlerin yüeğimin ta köşesinde

Seni bıraktım mı sandın

Ah çiçeğim gelecektim, kavuşacaktık

Biraz daha sabretseydin, olmazmıydı

Yolcu yolunda gerek deme bana

Senin için yolda, yolcuda bendim,', 'Bir şarkıdır seni bana hatırlatan Günlerdir içimi kavuran ateştir senin hatıran Gördüm, duydum birtürlü inanmak istemedim Sen solmuş, çürümü...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Saban']::text[], 8.5, '{"poet":"Sevilay Saban","poet_slug":"sevilay-saban","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cicegim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağrı', 'cagri-hilmi-kayihan-c2rve', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Emzik ağzında demokrasi

Dağ yamaçları 

Ala alçak doğru

Yanlış kahkaha

Kuşkularım kalleş

Yatalak özlemlerim

Suskun tedirgin acım

Borçlu zevkim

Ayaklarım altında toprak kayıyor.', 'Emzik ağzında demokrasi Dağ yamaçları  Ala alçak doğru Yanlış kahkaha Kuşkularım kalleş Yatalak özlemlerim Suskun tedirgin acım Borçlu zevki...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Kayıhan']::text[], 8.5, '{"poet":"Hilmi Kayıhan","poet_slug":"hilmi-kayihan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cagri-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-sevilay-saban-pnc58', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağladım günlerce sana geleceğim diye

Yalvardım babama izin ver diye

Babam ermiş adam vesselam

Vallahide, billahide

Ağzından sadece bu sözler çıktı

''Gitme oğlum kaybolursun''

O zamanlar bu lafa çok gülmüştüm

Büyük sözü dinlemeyen çeker çilesini

Ah İstanbul ah neydim ne oldum

Sayende aileden oldum

Gelen bin pişman, gelmeyen bir pişman

Ne o kasvetli havana

Milyonlarca insanı sığdırdığın toprağına

Binlerce yıllık tarihine

Görkemli muhteşem binalarına

O güzelim denizine, köprüne

Müzelerine, camilerine, parklarına

Buram buram kokan balık ızgarana

Artık aldanmıyacağım

Ben seni tanıdım hemde en acı yanını

Biliyormusun ne ümitle geldiğim

Bu muhteşem şehir gitmiş

Yerine insanların kaybolduğu

Büyük bir bina yığını gelmiş

Ah İstanbul Ah

Ben ne ümitler ne hayallerle geldim

Bak ben işsiz, avare avare

Dolaşıyorum sokaklarında

Çevreme bakıyorum, kimseyi tanımıyorum

Hep yabancı çehreler, gülümsemeyen yüzler

Nerde istanbul insanı

Bağrına bastığın onca insana artık yetmiyorsun

Ah istanbul sana artık aldanmıyacağım

Beni kandıramassın

Ben sana aşık olduğumda 

Yeni yetme toy bir delikanlıydım

Sayende şimdi büyüdüm', 'Ağladım günlerce sana geleceğim diye Yalvardım babama izin ver diye Babam ermiş adam vesselam Vallahide, billahide Ağzından sadece bu sözler...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Saban']::text[], 8.5, '{"poet":"Sevilay Saban","poet_slug":"sevilay-saban","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/istanbul-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağla', 'agla-hilmi-kayihan-mprcl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çığlık yüklü şimşek

Ölüm çobanı gözyaşı

Cilalı cinayet

Yorgun yolcu ağla

Ağla kederli kızgın kıpırtı

Biçimsiz birlik

Yaklaşan kopuş ağla

Ağla heybesi kurşun ölüsü öğüt

Talihsiz tansık

Kümesteki yaralı karaca ağla

Ağla kan içinde yakaran umut

Yapıcı yıkıcı ders

Merhametsiz öpüş ağla

Hoşgörü tutsak horgörüye

Yerleşik acıya hısım

Sayrılı uykularda

Diz çöktü renkler

Ateş dansında

Yabanıl yürekler

Ağlayasıya kahkaha atıyor cehennemdekiler

Arılar balını acılar

Turnalar uluyor

Uçuyor karıncalar.', 'Çığlık yüklü şimşek Ölüm çobanı gözyaşı Cilalı cinayet Yorgun yolcu ağla Ağla kederli kızgın kıpırtı Biçimsiz birlik Yaklaşan kopuş ağla Ağl...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Kayıhan']::text[], 8.5, '{"poet":"Hilmi Kayıhan","poet_slug":"hilmi-kayihan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/agla-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçurum', 'ucurum-sevilay-saban-tqwoq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Birgün uzaklara bakıp dalar gidersen

Hatırla kırdığın kalbi

Senden sonra o uçuruma düştü

Onu oraya iten sen

Onu orada bırakan sen

Ateşten yelek giydirdin ateşten

Uçurumda seni bekliyor acılarıyla

Eden bulurmuş cezasını

Senide birgün, o olmasada

Senin gibi birisi çıkacak karşına

Oda seni uçuruma itecek

Gözlerine inanamıyacaksın

Orda tanıdık bir yüz göreceksin

Onda teselli arıyacak, bulamıyacaksın

Kalp kırmak bir saniyelik, 

Onarmak ise, yıllarını alacak

Değmez sana değmez

Geçde olsa anladım

Çek çileni giy sende ateşten yeleği

O zaman anlarsın beni', 'Birgün uzaklara bakıp dalar gidersen Hatırla kırdığın kalbi Senden sonra o uçuruma düştü Onu oraya iten sen Onu orada bırakan sen Ateşten ye...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Saban']::text[], 8.5, '{"poet":"Sevilay Saban","poet_slug":"sevilay-saban","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ucurum-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemin', 'yemin-hilmi-kayihan-x9gwh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çıplak sırtta gemsiz

Dört nala huylarım

Kadehler şaha kalkmış 

Yerde sürünür yeminlerim', 'Çıplak sırtta gemsiz Dört nala huylarım Kadehler şaha kalkmış  Yerde sürünür yeminlerim...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Kayıhan']::text[], 8.5, '{"poet":"Hilmi Kayıhan","poet_slug":"hilmi-kayihan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yemin-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader', 'kader-sevilay-saban-2niv9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünyada her yeri gezdim

Bulamadım eşimi

Gözlerim aradı

Kalbim yalvardı

Avuç açtım Allahıma

Seninle karşılaştırsın diye

Ve birgün sen

Çıktın karşıma

Görünce kanım ısındı

Gözlerim doldu mutluluktan

O an değerdi ölüm

Doydum bu dünyaya

Ölsemde gam yemem

Gökten indirmişler seni bana

Alnına yazmışlar benimsin diye

Sen benim, ben senin

Olduktan sonra

Dünya dönüyormuş

Zaman geçiyormuş

Kim takar.', 'Dünyada her yeri gezdim Bulamadım eşimi Gözlerim aradı Kalbim yalvardı Avuç açtım Allahıma Seninle karşılaştırsın diye Ve birgün sen Çıktın ...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Saban']::text[], 8.5, '{"poet":"Sevilay Saban","poet_slug":"sevilay-saban","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kader-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabus', 'kabus-sevilay-saban-jt4sh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güzel bir bahçedeydim rüyamda

Yeşil ile mavinin birleştiği yerde

Yeşil ben güzelim

Mavi ben güzelim

Dediği yerde 

Seni seni seyrediyordum

Yeşil gözlerim alelade sevinçle değil

Mutlulukla seyrediyordu seni seni sevgilim

Ama sen birden

Yok oldun

Sana bakmak

Doyasıya seyretmek istiyordum

Yolda seni bulmak amacıyla ilerliyordum

Birden seni güzel bir sarışınla gördüm

Kalbim buna inanmak istemiyor

Gözlerim buna zorluyordu

Çok hızla uzaklara koşmaya başladım

Ama sen gelmiyordun, yanındaydı o

Birden uyandım, ter içindeydim

Gözlerim yaşlarla dolmuştu', 'Güzel bir bahçedeydim rüyamda Yeşil ile mavinin birleştiği yerde Yeşil ben güzelim Mavi ben güzelim Dediği yerde  Seni seni seyrediyordum Ye...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Saban']::text[], 8.5, '{"poet":"Sevilay Saban","poet_slug":"sevilay-saban","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kabus-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ve Ben', 'sen-ve-ben-cahit-i-pekoglu-eq52b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgi 

gözden akan iki damla.

Aşk''sa

bu damlayla dolu derya.

Benim halim'' bu deryada rüya

sen benim dünyamda'' ki hülya...

Sen güzelliğinle sultan

ben aşkımla sana hayran.

Sen cilvenle, hicran

ben''se aşkını sana adamış insan...

Sen 

acı vermeyi seven sevgilim.

Ben

kahrını çeken kölenim.

Azat'' etmen öldürmenden beter

ben senin aşkınla divaneyim....', 'Sevgi  gözden akan iki damla. Aşk''sa bu damlayla dolu derya. Benim halim'' bu deryada rüya sen benim dünyamda'' ki hülya... Sen güzelliğinle s...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-ve-ben-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firez Yangınları', 'firez-yanginlari-turgay-akbulut-kfiv8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu memleketin akşamları güzeldir.

Mevsimse bahar, açmışsa leylaklar

Tutmuşsa elini, 

Dökülmüşse saçları omuzuna

Güneş göz kırpınca batmaya

Hafiften çıkar, 

Lavanta kokulu rüzgar...

Bu memleketin akşamları güzeldir.

Kızgın güneş dolanır tepesinde 

Al yanaklarını saklar, beyaz tülbentle

Yüreğinde çaba, elinde çapası

Binlerce vurur toprağa, binlerce

Yeşersin diye umutları

Güneş ayaklarının altına düşer

Toprakla kavgasından döner

Memleketimin cefakar kadınları...

Bu memleketin akşamları güzeldir.

Güneşle ay nöbet değişir

Mehtabı süsler zincir sesli böcekler

Karşı yamaçlar da, gecenin dansçıları, 

Firez Yangınları

Ocakta çay kokusu

Tepeden bir pilot  geçer

Takılır gözlerimiz ardına

Alır götürür bizi, belki de dünyanın öbür ucuna

Umutların hayaliyle geçer bağrımız

Kapanır göz kapakları

Güne meydan okuyan bedenler, geceye yenik düşer

Üzerimiz de kutsal bir el gezer

Kıyamaz uyandırmaya, okşar bahtımızı

Üstümüzü örter

Nöbetçi Anneler...

Bu memleketin akşamları güzeldir.

Bizi bekler hasret ağacı

Hasretinden sararmıştır dalları

Bir gün ansızın çıkar gelir, 

Çocuklardan biri

Tıklatır camınızı

O an sarsılır, hasret çınarı

Dökülür hasretinden sararmış yaprakları

Düşer kokunuz içeri

İlk doğduğunuz gün gibi, 

Koklar... 

Sevinç gözyaşları

İşte o akşam en güzel akşamdır

Hasretle yenir...

Hasretle içilir...

Bu memleketin akşamları güzeldir.

Ne kara kışlar geçti

Ne kıtlıklar yaşadık

Ama hiç biri söndüremedi, içimizdeki yangını

Hiç biri alamadı bizden, yarınlara olan inancımızı

Biz mesut iken, fukara halimizden

Onlar! Marifet saydı çalıp çırpmayı

Utanın be! Utanın! 

Bastığınız toprağa bir bakın! 

Öyle değil! Adamakıllı bakın

Binlerce isimsiz şehit kanı! 

Binlerce yetimin hakkı! 

Utanın be! Utanın! 

Şu insanların haline bir bakın

Bırakın! 

Vatan-Millet edebiyatını

Bırakın çalıp çırpmayı...

Bu memleketin akşamları güzeldir, 

İnsanları da

Yeter ki bozmasınlar, 

Havasını...

(haziran 03)', 'Bu memleketin akşamları güzeldir. Mevsimse bahar, açmışsa leylaklar Tutmuşsa elini,  Dökülmüşse saçları omuzuna Güneş göz kırpınca batmaya H...', ARRAY['Türk Edebiyatı','Şiir','Turgay Akbulut']::text[], 8.5, '{"poet":"Turgay Akbulut","poet_slug":"turgay-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/firez-yanginlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğrenmek', 'ogrenmek-mustafa-sureyya-sezgin-6ri9h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kara sevdan yüzünden

Sevmeyi öğreniverdim, 

Seninle birlikte, 

Taşı, toprağı, 

Ağacı, suyu ve çiçeği.

Kokusunu duyuyorum gülüşünün.

Ne zaman gözlerimi kapasam

Yüzün yansıyor düşüncelerimden.

Ayrılığı, özlemi

Bir de seviyorum seni

Senin yokluğunu.

Nasıl oluyor anlamıyorum

Ama gördüğüm her şey de sen varsın

Sen bile bunu anlayamazsın! .. 

Mustafa Süreyya Sezgin

İstanbul,27.05.2003', 'Kara sevdan yüzünden Sevmeyi öğreniverdim,  Seninle birlikte,  Taşı, toprağı,  Ağacı, suyu ve çiçeği. Kokusunu duyuyorum gülüşünün. Ne zaman...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ogrenmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeye Rağmen', 'herseye-ragmen-burcu-arda-a3lu2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ani değişimlerin insanı oldum hep

''Hayata sunulmuş bir armağan mıydım

yoksa hayat mı sunulmuş bir armağandı? ''

Çelişik düşlerim olmadı hiç.

Hep inanmakla başladı yaşam yolculukları

Ve her nedense bütün duraklar kaldırıldı vedalar vakti

Zaten bu da uzaktı hep

İstersen vardın istersen yoktun çünkü

Ne zaman, nerde, ne istersen senindi

Bu yüzden yer yoktu ayrılıklara da

Herşeye rağmen soluk alıp veriyordun 

Birşeyler biryerlerde sürüp gidiyordu belki apansız belki durağandı; ama sana aitti.

Enlerim de olmadı hiç.

Hep daha iyisi hep dahası vardı herşeyin.

Şimdiyse acı bir gülümseme size dair...

Yazık...Ne de güzelsiniz....', 'Ani değişimlerin insanı oldum hep ''Hayata sunulmuş bir armağan mıydım yoksa hayat mı sunulmuş bir armağandı? '' Çelişik düşlerim olmadı hiç. ...', ARRAY['Türk Edebiyatı','Şiir','Burcu Arda']::text[], 8.5, '{"poet":"Burcu Arda","poet_slug":"burcu-arda","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/herseye-ragmen-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susuyorsun', 'susuyorsun-mustafa-sureyya-sezgin-refrn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerin, gözlerime değince

Gülümsüyorsun.

Kaç voltluk bir düşünce akımı

Geçiveriyor beyninden, 

Negatif  mi, yoksa pozitif mi duyguların

Sen de bilmiyorsun.

Biraz acı

Biraz sitem okunuyor gözlerinden.

Bir şeylerden korkuyorsun.

Biliyorum, 

Gizli gizli ağlıyorsun.

Oysa konuşman lazım

Konuşmalısın

Fakat sen hep susuyorsun...

M.Süreyya Sezgin

İstanbul,04.06.2003', 'Gözlerin, gözlerime değince Gülümsüyorsun. Kaç voltluk bir düşünce akımı Geçiveriyor beyninden,  Negatif  mi, yoksa pozitif mi duyguların Se...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/susuyorsun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Herkesin Kadını', 'sen-herkesin-kadini-mustafa-sureyya-sezgin-18fqg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neden varolduğunu 

Düşünmüş insanoğlu

Sonra Tanrıyı keşfetmiş

Umudu, sevinci, çaresizliği

Anlam kazanmış varlığıyla

Ve derinden

Bağlanmış yüreğinden.

Diyor ki gönlüm; 

Bir yerlere bağlanmalı 

Yaşamalı yüce bir duyguyu

Ve yaşatmalı ölümsüzce.

Tek olmalı Tanrı gibi.

Sevinci ve hüznü 

Gözlerinde bulmalı

Bir tek bana ait olmalı

Söyleyemediğim adını

Sen, herkesin kadını! ..

Mustafa Süreyya SEZGİN                       

İstanbul,22.06.2003', 'Neden varolduğunu  Düşünmüş insanoğlu Sonra Tanrıyı keşfetmiş Umudu, sevinci, çaresizliği Anlam kazanmış varlığıyla Ve derinden Bağlanmış yü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-herkesin-kadini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevinçli Bir Gün', 'sevincli-bir-gun-mustafa-sureyya-sezgin-9wmqt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlığın  ardından gelen her  gün, 

Yeni bir sevdanın doğumudur.

Uyanır bütün doğa

Sevinçle parıldar güneş.

Çiçek gibi, 

Güneş yüzlü, 

Güzel bir kız

Gülümser sana uzaklardan

Isıtır yüreğinin derinliklerini.

İşte o zaman

Varolduğunu anlarsın.

Bugün, 

Bütün kederlerin yok olsun

Ufkuna yeni umutlar doğsun.

Ve o kıpır kıpır gönlüne

Bitmeyen  sevinçler dolsun...

Mustafa Süreyya Sezgin

İstanbul,24.06.2003', 'Karanlığın  ardından gelen her  gün,  Yeni bir sevdanın doğumudur. Uyanır bütün doğa Sevinçle parıldar güneş. Çiçek gibi,  Güneş yüzlü,  Güz...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevincli-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baş ağrısı', 'bas-agrisi-mustafa-sureyya-sezgin-n57ob', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sesin, bakışın, nefesin

Hücrelerime yer etmiş bir kere  neylersin

Sen olmadan yediğim meyvelerin

İçtiğim içkilerin tadı yok.

Bugün seninle yudumlarken anıları

Gönlümde yine sevdan kabardı

Duygularım taştı.

Yüreğin aralanmadı bana bir türlü

Sanırsın ki yontulmamış bir taştı.

Hala anlayamıyor musun? 

Dön bir bak

Uzaklardan, çok uzaklardan

Birbirini özlüyor kimyalarımız.

Zaptedemiyorum bu bedeni

Hele mevsim değişip

Çiçekler de açınca

Bahar  başıma vuruyor seni...

Mustafa Süreyya Sezgin

İstanbul,17.06.2003', 'Sesin, bakışın, nefesin Hücrelerime yer etmiş bir kere  neylersin Sen olmadan yediğim meyvelerin İçtiğim içkilerin tadı yok. Bugün seninle y...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bas-agrisi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Anlamı Var', 'ne-anlami-var-cahit-i-pekoglu-w5ru5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen

beni terkedip gittikten sonra.

Herşey burada bitti

dedikten sonra.

Beni sev demenin ne anlamı var...

Yaşama

hayata küstürdün beni.

Gülüpte 

oynamanın, ne anlamı var.

Yaşayan

ölüye döndürdün beni.

Sevipte, sevilmenin ne anlamı var...

Uzaktan bakıpta gördükten sonra

yanına gelmenin ne anlamı var.

Acı

vereceğini bildikten sonra.

Sana dönmenin ne anlamı var...

Acı

bir tebessüm bıraktın yüzüme.

En sitemli sözleri

attın gönlüme.

Sana

dönerim diye bekleme.

Nefretle dönmenin ne anlamı var...', 'Sen beni terkedip gittikten sonra. Herşey burada bitti dedikten sonra. Beni sev demenin ne anlamı var... Yaşama hayata küstürdün beni. Gülüp...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ne-anlami-var-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devinim', 'devinim-mustafa-sureyya-sezgin-vfrf1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Doğanın kendisiyiz

Sen, ben, Kelebekler ve çiçekler

Sanki hepsi gerçekler.

Sen var mısın sanki? 

Ben var mıyım? 

Yaşıyor muyuz bu gerçeği? 

Yaşananlara geçmiş

Yaşayacaklarımıza gelecek diyoruz değil mi? 

Belliyse Perşembenin gelişi Çarşambadan

Yarınımız daha bugünden belli değil mi? 

Bak dönüyor yine bir elektron

Hidrojen atomunun yörüngesinde

Dönüyor Dünya Güneşin çevresinde

Ve dönüyor düşüncelerim

Sen gülümseyince.

Görmüyor musun? 

Yörüngendeyim işte bak! ..

Seriverdim varlığımı tümüyle

Senin önüne, çırılçıplak...

Mustafa Süreyya Sezgin

İstanbul,17.06.2003', 'Doğanın kendisiyiz Sen, ben, Kelebekler ve çiçekler Sanki hepsi gerçekler. Sen var mısın sanki?  Ben var mıyım?  Yaşıyor muyuz bu gerçeği?  ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/devinim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avuntu', 'avuntu-mustafa-sureyya-sezgin-dx5p8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bak güzelim

Sıkma canımı 

Sonra şiir yazarım

Bir yazmaya başlarsam

Seni istediğim kılığa sokarım.

Mustafa Süreyya Sezgin

İstanbul,17.06.2003', 'Bak güzelim Sıkma canımı  Sonra şiir yazarım Bir yazmaya başlarsam Seni istediğim kılığa sokarım. Mustafa Süreyya Sezgin İstanbul,17.06.2003...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/avuntu-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çözüm', 'cozum-mustafa-sureyya-sezgin-qrxzf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çareleri tüketip, 

Sıkılırsam gün içinde ben

Düşünürüm

Önce seni

Sonra bu koskoca evreni

Birleştiririm dünyaları

Koyarım ortasına kendimi.

Mustafa Süreyya Sezgin

İstanbul,17.06.2003', 'Çareleri tüketip,  Sıkılırsam gün içinde ben Düşünürüm Önce seni Sonra bu koskoca evreni Birleştiririm dünyaları Koyarım ortasına kendimi. M...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cozum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlat Hatırı', 'evlat-hatiri-mustafa-sureyya-sezgin-2xelf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen de anlatacaksın ilerde oğlum; 

“Bir muhabbet kuşumuz vardı

Yağmurdu   adı.

Bizim gibi, 

Bir kaderi vardı.

Yıllar tükettikçe yaşamı

Tanrı onu da bizden aldı.

Geriye Yağmurdan

Hüzün ve anılar kaldı.”

Dünden bugüne akıyor zaman

Devam ediyor yaşam oğlum

Ve yarın gelecek belki bir an

Bütün güzelliklere, üzüntülere

Sen de; “ anıydı onlar” diyeceksin.

Bak Yağmurun yerini 

Şimdi de Türev aldı.

O da uçuyor  tepemizde

Bu da yetmezmiş gibi

Bir de evimize Nazar geldi.

Şimdi iki kuş ile uğraşın var

Her ne kadar bir kuş ise de onlar

Paylaşılacak bu hayatlar.

Mustafa Süreyya Sezgin

İstanbul,17.06.2003', 'Sen de anlatacaksın ilerde oğlum;  “Bir muhabbet kuşumuz vardı Yağmurdu   adı. Bizim gibi,  Bir kaderi vardı. Yıllar tükettikçe yaşamı Tanrı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/evlat-hatiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sue', 'sue-mustafa-sureyya-sezgin-8oorz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yirmi beş yıl oldu karşılaşmayalı Sue, 

Hatırlıyor musun düğünüme gelmiştin? 

Ve buruk bir gülümsemeyle

Beni tebrik etmiştin.

Yıllar ne çabuk geçiyor, 

Uzaklarda, çok uzaklarda

Sen bir koca daha eskittin, 

Çoluk çocuğa karıştın, 

Böyle yaşamaya alıştın.

İnsanoğlu bir varmış bir yokmuş işte! ..

İyi günler yakında diye diye

Yanıldık galiba Sue.

Yok artık o eski şarkılar

Dillerde tekrarlanan nakaratlar.

Sen uzaklarda, 

Ben buralarda

Mutluyuz belki ama

Var yine de eksik bir şeyler Sue.

Nasıl söylesem bilmem ki

Sen mutlu ol yeter ki...

Mustafa Süreyya Sezgin

İstanbul,26.06.2003', 'Yirmi beş yıl oldu karşılaşmayalı Sue,  Hatırlıyor musun düğünüme gelmiştin?  Ve buruk bir gülümsemeyle Beni tebrik etmiştin. Yıllar ne çabu...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sue-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Benim Gençliğim Nerde..', 'hani-benim-gencligim-nerde-yusuf-hayaloglu-jewzc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani benim gençliğim nerde

Bilyelerim topacım

Kiraz agacı altında yırtılan gömleğim

Çaldılar çocukluğumu habersiz.

Penceresiz kaldım anne

Uçurtmam tellere takıldı

Hani benim geçnçliğim nerde.

Ne varsa bu gençliği yakan 

Ekmek gibi aşk gibi

Ne varsa güzellikten yana 

Bölüştüm büyümüştüm.

Bu ne yaman çelişki anne 

Kurtlar sofrasına düştüm

Hani benim gençliğim nerde.

Hani benim sevincim nerde

Akvaryumum kanaryam', 'Hani benim gençliğim nerde Bilyelerim topacım Kiraz agacı altında yırtılan gömleğim Çaldılar çocukluğumu habersiz. Penceresiz kaldım anne Uç...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Hayaloğlu']::text[], 8.5, '{"poet":"Yusuf Hayaloğlu","poet_slug":"yusuf-hayaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hani-benim-gencligim-nerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir İstanbul Gecesi', 'bir-i-stanbul-gecesi-tolga-baydar-4t6kn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elimde yıllanmış şarabım, söylüyorum

Dilimde kırklardan kalma bir türküyü

Sanki şarap söylüyor, ben içiliyorum

Tersine çevrilmiş hayatıma bakıp

Gerçeği kendi yüzüme vuruyorum

Sevgilim dediğim, sevdiğim onca insan

Deryalar aşsam da bulunmaz bir oya

Kaderime ağlarken ince ince sızlayan

Kalbimin çevresinde dönen uydu misali

Tarlabaşı yokuşunda arkamdan koşan

Taksim''den Galatasaray''a edeplice yol alırken

Şakalaşan, bağırışan, küfürleşen bir İstanbul

Sağa döndü arkadaş aniden, bilmem neden

Yol almaya devam ettik usulca, sonra

Üç beş basamak indik, sanırsın mahzen

Eğlenmek bu mu acaba, delice, çılgınca

Yedi tepe üzerine kurulmuş bir tablo sanırsın

Gecen bu muydu, oysa gündüzün bambaşka

Kadehler kırılırcasına biribirine vurulurken çın-çın

Doyamadım, beni alıp götürdün doyamadım, aşka', 'Elimde yıllanmış şarabım, söylüyorum Dilimde kırklardan kalma bir türküyü Sanki şarap söylüyor, ben içiliyorum Tersine çevrilmiş hayatıma ba...', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-istanbul-gecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Yalnızım', 'yine-yalnizim-tolga-baydar-snd4n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gitarım ağladı bu gece

Sen yanımda değildin

Düğüm düğüm olan hayatım

Sana kavuşma arzusu ile yanan kalb-i cihanım

Sen sultanımdın, arkandan şiirler yazdığım

Tanışmışlığımızın üçüncü yılını kutlarken

Geçmiş iki yıldönümündeki gibi

Bu yıldönümünde ben yine yalnızım

Ve her yıldönümünde yine yalnız kalacağım', 'Gitarım ağladı bu gece Sen yanımda değildin Düğüm düğüm olan hayatım Sana kavuşma arzusu ile yanan kalb-i cihanım Sen sultanımdın, arkandan ...', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yine-yalnizim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbi: CEHENNEM YERİ', 'kalbi-cehennem-yeri-naime-erlacin-ciul5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir elinde aşk iksiri

ötekinde nefret zehri

vah ki kalbi 

cehennem yeri! 

tercihi intihardan yana

ya da cinayet

el değmemiş ruhuyla “yaşamak ne” bilmeden

akşam haresi düşmüş sevda yorgunluğuna

sırtı beli bükülmüş 

en zorlu bedellerden

dili ödünç alınmış ağulu bir yılandan

“aşk” koymuş adını

bağrında bebek saklar

akrep misali kendini sokacak sanki

bebeğinin kaderi 

ne yazık ki zehirden! 

aşk tutuyor elinde

vah ki kalbi 

cehennem yeri! 

(28 Haziran 2003)', 'bir elinde aşk iksiri ötekinde nefret zehri vah ki kalbi  cehennem yeri!  tercihi intihardan yana ya da cinayet el değmemiş ruhuyla “yaşamak...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kalbi-cehennem-yeri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Fasıl Gaziantepli bestekar-şair Erol Güngör şiiri', 'son-fasil-gaziantepli-bestekar-sair-erol-gungor-siiri-erol-gungor-nus4y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Son fasılda sazı iyi çalmalı

                                              Gönüllerden sevgi ile taşmalı

                                              Geç de olsa üzüntüyü terk edip

                                              Her saniye mutluluğu bulmalı.

                                              Kalan ömür her ödülden kıymetli

                                              Keyfi değil mantık ile geçmeli

                                              Sevenlerin kıymetini bilmeli

                                              Sevdiğini daha fazla sevmeli.

                                             Nasıl olsa çok şey yarım kalacak

                                             Varlığımız bir gün mazi olacak

                                             Olgun yaşta kararsızlık yakışmaz

                                             Son fasılda, nihaventte kalmalı.', 'Son fasılda sazı iyi çalmalı                                               Gönüllerden sevgi ile taşmalı                                    ...', ARRAY['Türk Edebiyatı','Şiir','Erol Güngör']::text[], 8.5, '{"poet":"Erol Güngör","poet_slug":"erol-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/son-fasil-gaziantepli-bestekar-sair-erol-gungor-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Renkler', 'renkler-cemal-ekren-uve9e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bana mavin tonlarını sayabilirmisin? 

yangın mavisi nedir bilirmisin? 

sevgimin ve hasretliğimin kesiştiği yerde; 

yeniden dogarım gözlerinde, 

sarı saçlarını her tardığında, 

acılarım düşer avuçlarına.

kan kırmızıdır bilirim.

acılarımın kanı ne renk bilirmisin gülüm? 

bak bir çocuk aglıyor gözlerimde, 

yalanda olsa ver yalancı emziğini, 

çocuklar aglamsın, 

yangın mavisinin içinde.

sevgimizin sıcaklığında çay demle gülüm, 

yudum, yudum; 

hasretliğimizi içelim.

sen beyazlarını giy, 

ben türkümüzü söylerim.

siyahı zeytin tanesinde, 

yeşili gzölerimden bilirim, 

kahverengi gözlerine bakınca.

sen yangın mavisibilirmisin? 

bana söyle gülüm? 

bana adını söyle, 

sevdiğini söyle, 

yalanda olsa sevmediğini söyle..

susma 

dilinde yorgun bir sevda yatar

uykusuz geceleri, 

bana ver..

renklerin dili vardır

konuşur

yangın mavisinin bende hatırası vardır içimde

içimi yakar yanarım.

bak bir çocuk aglıyor

yalancı emziği agzında

çocuklar aglamasın gülüm

hasretliğimiz bizi yakar

çocuklar yanmasın 

sigaran sönmüş, 

tazele

yangın mavisyle

gök mavi

deniz mavi

ve sen içimde

yangın mavisiisin gülüm yangın', 'Bana mavin tonlarını sayabilirmisin?  yangın mavisi nedir bilirmisin?  sevgimin ve hasretliğimin kesiştiği yerde;  yeniden dogarım gözlerind...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/renkler-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamın Işıkları', 'aksamin-isiklari-knight-errant-u5ctf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akşamın ışıklarına bakıp düşünürdüm önceden

Sevmek nasıl bir duygu diye? 

İki insan nasıl böylesine bağlanır tutkuyla

Ve bir insan nasıl acı çeker büyük bir zevkle...

Sonra sen çıktın karşıma; 

Saçların kızıldı, tam bir çocuk havasında...

Gözlerinse maviydi, okyanus edasında....

Ve akşamın ışıklarına bakıp düşünmeye başlamıştım

Bir meleği mi seviyorum diye...

Günler geçmez, saatler tükenmez olduğunda

Yine akşamın ışıklarında buldum kendimi.

Ve bu sefer neden diye düşündüm, 

Neden kalbim daha hızlı atıyordu? 

Neden seni gördüğümde, gözlerim kör oluyordu? 

Ve sonra dedim ki kendime:

“Neden değil? ”

Sonra buldum seni her istediğimde, 

Aradığımda hep oradaydın, ulaşabileceğim bir yerde.

Akşamın ışıklarında da aradım seni

Ve orada da buldum.

Çünkü akşamın ışıkları ben demekti, 

Bense sen demektim...

Şimdi bakıyorum akşamın ışıklarına; 

Yine seni görüyorum orada, 

Yine kalbim hızlı çarpıyor, 

Bakıyorum akşamın ışıklarına ve haykırmak istiyorum

“Seni seviyorum! ” diye...

Arasam yine ulaşabilir miyim, bulabilir miyim diyorum

Ama bilmiyorum, ağlamak istiyorum galiba

Yanımda sen yoksun diye...', 'Akşamın ışıklarına bakıp düşünürdüm önceden Sevmek nasıl bir duygu diye?  İki insan nasıl böylesine bağlanır tutkuyla Ve bir insan nasıl acı...', ARRAY['Türk Edebiyatı','Şiir','Knight Errant']::text[], 8.5, '{"poet":"Knight Errant","poet_slug":"knight-errant","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/aksamin-isiklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Gibi', 'ask-gibi-knight-errant-5o84y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk; 

Beni okyanusta kurtaran sandal, 

Uçurumda tutunduğum dal gibi.

Sonra azgın dalgalar ve

Dalı kıran rüzgar gibi.

Aşk; 

Açlığımı gideren simit, 

Sigaramı yakan kibrit gibi

Sonra mide sancısı ve

Yere düşen kül gibi.

Aşk; 

Issız adada gökyüzü, 

Yarin altın sözü gibi.

Sonra kara bulutlar ve

Bitmiş bir maden gibi.

Aşk; 

Soğukta bağıran bozacı, 

İçimdeki tatlı acı gibi.

Sonra şahit şıracı ve

Gönlümdeki kan gibi.

Aşk; 

Çocukların elindeki şeker, 

Ceylanlar seker gibi.

Sonra bitmiş bir çubuk ve

Acımasız aslan gibi.

Aşk; 

Yüz vermeyen sen, 

Mutlu gözüken ben gibi.

En sevmli düşman ve

Gözümdeki yaş gibi.', 'Aşk;  Beni okyanusta kurtaran sandal,  Uçurumda tutunduğum dal gibi. Sonra azgın dalgalar ve Dalı kıran rüzgar gibi. Aşk;  Açlığımı gideren ...', ARRAY['Türk Edebiyatı','Şiir','Knight Errant']::text[], 8.5, '{"poet":"Knight Errant","poet_slug":"knight-errant","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ask-gibi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Değilim', 'ben-degilim-knight-errant-kl9l7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sesini hiç duymadıysam o gün

Ya da görmediysem seni bir kez bile

Tenini tenimde, omzunu başımda hissetmediysem

O gün, gün değildir, bilesin...

Pürüzsüz gökyüzüne her baktığımda

Mavi gözlerin aklıma gelmediyse eğer

İliklerime kadar ıslandığımda ya da soğuktan titrediğimde

Sen yoksan yanımda

O mevsim, mevsim değildir bilesin...

Doğum gününde hediye telaşı yaşamadıysam

Ve bir gül bile almadıysam sana 14 Şubat’ta

Yılbaşını senle geçirmek için yalvarmadıysam

O sene hiç geçmemiştir, bilesin...

Unuttuysam seni bir anlığına

Ya da kalbim senin için çarpmadıysa

Sabah kalkınca yüzümü yıkamadan seni düşünmediysem

Şu dünya durmuş demektir, bilesin...

Sen üzgünken yoksam yanında

Ve sevinçliyken de beni arıyorsan

Gözyaşın gözyaşıma, gülüşün gülüşüme dönüşmediyse

Yanaklarını silen bir başka else

Yollarım tutulmuş demektir, bilesin...

Üzdüysem seni bir kez bile

Kırdıysam kalbini isteyerek

Bilerek görmediysem seni her varlıkta

Ve her resmine baktığımda, ağlamadıysam eğer

O ben, ben değilimdir bilesin....', 'Sesini hiç duymadıysam o gün Ya da görmediysem seni bir kez bile Tenini tenimde, omzunu başımda hissetmediysem O gün, gün değildir, bilesin....', ARRAY['Türk Edebiyatı','Şiir','Knight Errant']::text[], 8.5, '{"poet":"Knight Errant","poet_slug":"knight-errant","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ben-degilim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş', 'gunes-knight-errant-2jcu9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şafakta bir güzel kızıllık var, aynı saçların gibi.

Dokunamam şafağa biliyorum ama 

Eminim ki o da yumuşaktır seninkiler kadar.

Gökyüzü aydınlanınca, bir gözalıcı mavilik 

Aynı beni çalan gözlerin gibi.

Gökyüzü de ağlar biliyorum fakat

O da umut dolu mu gözlerin kadar? 

Hani bir de güneş doğarken huzur dolarya insanın içine? 

İşte bakışlarında öyle doğuyor içime...

Ben yeni günsem eğer, sen de doğan güneşsin...

Onun kadar güzel, onun kadar huzurlu

Bir o kadar da yenisin...

Güneş her doğduğunda sana yeniden aşık olmak, 

Sen her sabah uyandığında

Masum yüzüne bakmak istiyorum...

Güneşin batışı da çok güzel derler

Ama ben batmanı istemiyorum.', 'Şafakta bir güzel kızıllık var, aynı saçların gibi. Dokunamam şafağa biliyorum ama  Eminim ki o da yumuşaktır seninkiler kadar. Gökyüzü aydı...', ARRAY['Türk Edebiyatı','Şiir','Knight Errant']::text[], 8.5, '{"poet":"Knight Errant","poet_slug":"knight-errant","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gunes-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru-Cevap', 'soru-cevap-knight-errant-rizvm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Severken içimdeki heyacandın, 

Yalnızken bir umut kalbimde.

Unutulmaz mutlu bir andın

Kartpostaldaki beyaz örtü; kar...

Ağlarken bir damla gözyaşıydın, 

Gülerken parıltıydın gözlerimde.

Yürürken kaldırım taşıydın, 

Koşarken yüzümde rüzgar...

Nefes alırken atışıydın kalbimin, 

Ölürken son nefestin ciğerimde.

Giderken sordular: “Bu kırık kalp kimin? ”

Tek cevabı bendim yar...', 'Severken içimdeki heyacandın,  Yalnızken bir umut kalbimde. Unutulmaz mutlu bir andın Kartpostaldaki beyaz örtü; kar... Ağlarken bir damla g...', ARRAY['Türk Edebiyatı','Şiir','Knight Errant']::text[], 8.5, '{"poet":"Knight Errant","poet_slug":"knight-errant","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/soru-cevap-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Aşk', 'uzak-ask-knight-errant-34xmu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzaktan yaşadım ben bu aşkı

Bir kez gördüm yüzünü

Ve sadece bir kez duydum o güzel sesini

Bir kere dokundum sana saniyelik de olsa

Ama yetti bana o gün bu gündür

Yetti aklımı yitirmeme, dünyaya küsmeme

Yetti gecelerimi yıldızlardan çok süslemeye

Kabuslarımı en güzel rüyalara çevirmeye...

Belki sana hergün güller alamıyorum

Ama bir gül bahçesinde yaşıyorsun kalbimde.

Hergün senin iltifat saydığın gerçekleri söyleyemiyorum

Bil ki en güzel söz denizinde yaşıyorsun beynimde ve dilimde

Pembe de olsa yalanlar söylemiyorum sana

Gerçekte tutmuyorum elini aslında

Gerçekte tanımıyorum seni

Ve de sevmiyorum aslında, uzaktan da olsa...

İlk ve son sözlerimi söylüyorum sana şimdi

İlk ve de son şiirim bu sana

Ve sana ilk kez yalan söylüyorum – belki bu da son olur –

Seni sevmiyorum...', 'Uzaktan yaşadım ben bu aşkı Bir kez gördüm yüzünü Ve sadece bir kez duydum o güzel sesini Bir kere dokundum sana saniyelik de olsa Ama yetti...', ARRAY['Türk Edebiyatı','Şiir','Knight Errant']::text[], 8.5, '{"poet":"Knight Errant","poet_slug":"knight-errant","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uzak-ask-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor', 'zor-knight-errant-60jzj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zordu seni sevmeye başlamak

Hayat atılan yepyeni bir adım, 

Yarım kalmış bir sayfadan

Tertemiz, bembeyaz bir sayfaya geçmek gibiydi.

Artık eski aşka kefen, 

Yenisine gelinlik giydirme vaktiydi.

Artık sıcak kumlardan

Masmavi ve serinleten denize

O ilk, 

O ürkek, 

O çekinden adımı atma vaktiydi.

Başladım seni sevmeye

Ve sevdim seni.

Ama sevmek daha zordu.

Her kelimede seni duymak, 

Her yüzde seni görmek, 

Yüzde yüz seenle yaşamak zordu.

Güzeldi, tatlıydı ama zordu.

Ve bir gün Özgür kendine sordu:

“Senin sevdiğin ne? ”

Ama kendisi de cevaplayamadı.

Dili tutuldu konuşamadı.

Kelimeler yetmedi o yoğunluğu anlatmaya.

Zaten kelimeler yetse, zaman yetmeyecekti...

Sonra kelimeler de yetti...

Ama seninle konuşmak da zordu.

Bir yanda içime işleyen gözlerin, 

Bir yanda güneş...

Ömer Zülfü demiş ki:

“Gözlerin, güneşe, sen doğma da ben doğayım diyor.”

Doğru söze ne demeli, 

Besbelli sana sesleniyor...

Gün geldi konuşmadım seninle, konuşamadım...

Bu hepsinden daha zordu.

Ağzımda kelimeleri düğümlemek, 

Ellerimi kelepçelemek, 

Yanında duran herkesi delicesine kıskanmak...

Ve cesur sandığın yüreğimin

Sana atılan iki adımdan sonra susması...

Şimdi geriye bakıyorumda

Aslında hepsi kolaymış.

Asıl zor olan; unutmak, 

Seni unutmakmış...', 'Zordu seni sevmeye başlamak Hayat atılan yepyeni bir adım,  Yarım kalmış bir sayfadan Tertemiz, bembeyaz bir sayfaya geçmek gibiydi. Artık e...', ARRAY['Türk Edebiyatı','Şiir','Knight Errant']::text[], 8.5, '{"poet":"Knight Errant","poet_slug":"knight-errant","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/zor-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece', 'sadece-knight-errant-9djfa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne bekler insan hayattan? 

Aşk mı? Sevgi dolu, duygu dolu

Isıtan insanı taa içerlerden, gönlünden.

Gönlünden bir parça koparıp atan, 

Her zaman bir yanını eksik bırakan.

İlk önce; 

Gülücükler dağıtırken etrafa, 

Gerçeğe dönünce; 

Her gülümsemeyi asıklığa çeviren.

Çoğu zaman ayakta kalma sebebiyken, 

Seni ayakta duracak hale zor getiren.

Mutluluk denizinde yüzerken, 

Karaya, acı karaya vurmanı sağlayan rüzgar, 

Ve gözyaşı olup akan yağmur, 

Önünü görmeni engelleyen sis, 

Her düz yolda karşına çıkan duvar, 

O duvardaki yarıklar, çatlaklar...

Ne bekler insan hayattan? 

Para mı? Yazı dolu, değer dolu

Isıtan insaını taa içerlerden, gönlünden.

Aslında gönlünün üstünden; ceketin iç cebinden...

Her istediğini yaptıran, herkesin

Ama herkesin tanıdğı, bildiği, sayıp sevdiği, 

Olmadığında ise sayıp sövdüğü

Uğruna adam dövdüğü, adam öldürdüğü.

Aslında seni hayal dünyandan koparan

Ve sek gerçekliğe atıp

Seni sarhoş eden...

Tamamıyla bir duygusuzluk, değersizlik aslında

Ya da olan değerlerin ölmesi, değişmesi.

İnsanı değiştiren, kör eden, 

Öünün görmeni engelleyen sis, 

Her düz yolda karşına çıkan duvar, 

O duvardaki derin yarıklar, çatlaklar...

Ne bekler insan hayattan? 

Sağlık mı? Yaşam dolu, canlılık dolu

Isıtan seni taa içerlerden, gönlünden.

Gönlünü çalıştıran ve beynini, 

Mantıksızlığı ve mantıklı olmayı sağlayan.

Bir şeye lanet okuken, 

Küfür edilen ilk şey.

Kendine lanet okurkense, 

Alınmasını istediğin tek şey.

Ve aslında mutluluk olmadan 

Kocaman bir hiçbirşey...

Ne bekler insan hayattan? 

Ev mi? Işık dolu, eşya dolu

Hayatın boyunca sahip olabileceğin en büyük pinekleme noktası.

Islanmamak için şemsiye açmana

Uyumak için para vermeye gerek olmayan

Sıcacık bir yer, içini ısıtan...

Ne bekler insan hayattan? 

Araba mı? Dört teker, benzin dolu

Ayağımzı yerden kesiyor dedirten 

Ve zamlarıyla kafayı yedirten...

Ne bekler insan hayattan? 

Yat mı? Kat mı? Söyle ha, 

Ne bekler? 

Peki ben ne beklerim hayattan? 

Sadece seni...Ha bir de sevgi dolu bir kalp...

Pardon ya, unutmuşum...O zaten var!', 'Ne bekler insan hayattan?  Aşk mı? Sevgi dolu, duygu dolu Isıtan insanı taa içerlerden, gönlünden. Gönlünden bir parça koparıp atan,  Her za...', ARRAY['Türk Edebiyatı','Şiir','Knight Errant']::text[], 8.5, '{"poet":"Knight Errant","poet_slug":"knight-errant","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/sadece-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönülmez Yollar', 'donulmez-yollar-hikmet-karakus-rjm1e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bekledim onca zaman, 

Yok gelen giden, 

Göçmen kuşlar bile

      gelip geçti durmadan, 

O hala gelmedi, 

Dönülmez yollardan mı geçti? 

Eridi yüreğimin yağı

                      çaresiz aktı

                      gözyaşlarıma karıştı, 

Sevda türkülerinde

                       hep aradım teselli, 

Ne gezer? 

Bitirdi

        bitirecek bu hasret beni.

Sonra düşerim yollarına, 

Bir bu yana, 

Bir o yana

Gezerim deli divane, 

Kime ne? 

Öfkemi boğarım dumana

                bir cıgara

                bir daha

                bir daha, 

Bilmiyorum; 

   dayanabilir miyim başka bir bahara? 

(Ank.1991)', 'Bekledim onca zaman,  Yok gelen giden,  Göçmen kuşlar bile       gelip geçti durmadan,  O hala gelmedi,  Dönülmez yollardan mı geçti?  Eridi...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/donulmez-yollar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Karavana', 'hayat-karavana-derin-oger-y8czn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geçtiğini sandığın dağlar

Dönüşüne tek yön çizerler

Dakikalar saatlerle

Günler yıllarla

Kanatlanıp giderler

Bir de yağmur  başlarsa

Can düşer derin kuyulara

Hayat karavana

Alem se bambaşka.......', 'Geçtiğini sandığın dağlar Dönüşüne tek yön çizerler Dakikalar saatlerle Günler yıllarla Kanatlanıp giderler Bir de yağmur  başlarsa Can düşe...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hayat-karavana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz yaşayanlara', 'sessiz-yasayanlara-aysenur-yazici-qbuv0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hangi taşa sürtsen kimini

ne aşınır, ne taşta izi kalır

görünmeden de yaşasa yaptıklarında

boranlarda silinmez sözü kazınır...

Istırabın adı, her ademde aynı

dayanan ömürden gün verir, ders alır

elinde ip, boynuna asar derdin

kimi korkar gider, ''çekerim'' der kimi kalır...

kendin için ne yaptıysan, dünya içindir de

kavrulup kalma, bir oyundur kahır

demez kimi, yeryüzünde melektir de, 

kimi kaandır bilmez, kervan yükü ah alır....

sanma ölmen gerekir, varman için arşa

ermişlerin gönlünde dem tutmuştur sabır

sen böceği bile incitmemek için yaşa

geçtiğin  yerde sönmeyen bir mum kalır

29.Haziran 2003

       (03:30)', 'Hangi taşa sürtsen kimini ne aşınır, ne taşta izi kalır görünmeden de yaşasa yaptıklarında boranlarda silinmez sözü kazınır... Istırabın adı...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sessiz-yasayanlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İpe Un Sersem', 'i-pe-un-sersem-aysenur-yazici-ksp05', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aklım sersem

günüm sersem

işe gidip gelişim sersem sersem

boş bakıyor

boş dolanıyorum

ruhum çırpınıyor içersem...

gezişlerim sersem

deyişlerim sersem

uyuyup kalkışım sersem sersem

''hiç''i aranıyor

''hiç''le dolanıyorum

ağlama tutuyor gülersem...

üstüm sersem

başım sersem

geçmişi anışım sersem sersem

kendi kulağımı çekip

zincire vuracağım beni

bir daha böyle seversem...! 

29.06.2003

    (02:25)', 'Aklım sersem günüm sersem işe gidip gelişim sersem sersem boş bakıyor boş dolanıyorum ruhum çırpınıyor içersem... gezişlerim sersem deyişler...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ipe-un-sersem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kiracı', 'kiraci-cemal-ekren-lp852', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kiracı

gündüzü olmayan geceler satın  aldım, 

yokluğunun deminde, bu kaçıncı sigaram

içimden geçer 

Ankara treni

yolculara sorarım seni

dilimde bir türkü sigaram gibi yanık

gevrek bir dil 

simit satar 

Ankara treninde

Ardından pişmaniyeci bağırır avazı çıktığı kadar, 

Tüm tüneller karanlıkken 

Sen içimde doğarsın güneş gibi

Oysa güneş yaklaşırsa bana 

Firaridir vurulur.

Anaç ana bebe emzirir

Tütün kokulu kompartımanda 

bebek suskun şimdi

kentim gibi

adresin neresi, 

sen neredesin? 

Bu trenin kaçıncı yolcusuyum? 

Ben biletimi nereye kestim

Tüm geceleri satın aldım da

Yıldızlar nerede

Yokluğunun bekçisiyim biliyorum

Geceler üstüme üstüme geliyor

Sen doğuyorsun yeniden

Senin kiracın mıyım

Yoksa evsahibin mi? 

Acı bir fren

Son  durak  Ankara

Güneş çoktan batmış

Sen yoksun

Bilesin sevgili

Biletim gidiş gelişliydi

Merhaba  demeden sana

Elveda Ankara', 'Kiracı gündüzü olmayan geceler satın  aldım,  yokluğunun deminde, bu kaçıncı sigaram içimden geçer  Ankara treni yolculara sorarım seni dili...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/kiraci-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna', 'ayna-cemal-ekren-4ye4l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu akşam söz verdim 

Bir daha aynaya bakmıyacağım

Kırlaşmış saçlarımda

Sürgünlüğüm kokuyor

Ayna bana küskün ben kime küseyim

Anlımdaki çizgilerde kalınlaşmış

Acılarım voltaya çıkmış

Dün biri bana amca dedi

Ayna bana

İhtiyar diyor

Tek suçlu ben miyim

Tarağımda yok

Gerçi altın sarısı saçlarımdan eser yok

Ben aynaya baktıkça yaşlanırım

Aynalar yalanıcı

Sen yalancı

Yokluğuna  alıştım ama 

Ben yaşlandım galiba', 'Bu akşam söz verdim  Bir daha aynaya bakmıyacağım Kırlaşmış saçlarımda Sürgünlüğüm kokuyor Ayna bana küskün ben kime küseyim Anlımdaki çizgi...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ayna-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesap', 'hesap-berna-yilmaz-qopy4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gittin, 

Şimdi her gün hesap günüdür

Kalbim boş bir salıncak

Öfkem bir beni vurur

Gittin..

Şimdi her gün hesap günüdür.', 'Gittin,  Şimdi her gün hesap günüdür Kalbim boş bir salıncak Öfkem bir beni vurur Gittin.. Şimdi her gün hesap günüdür....', ARRAY['Türk Edebiyatı','Şiir','Berna Yılmaz']::text[], 8.5, '{"poet":"Berna Yılmaz","poet_slug":"berna-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hesap-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fener', 'fener-berna-yilmaz-v778l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşlerime rastladım

Kuytu bir köşesinde kalbimin.

Solgun yüzlerini okşarken

Bir deniz ağladim.

Bir nefes çaldim rüzgardan.

Bir kıvılcım günahlarimdan.

Yangın çıkardım.

Deniz feneri gibi bekledim kıyısında yaşamın

Yandım ve aydınlattım.', 'Düşlerime rastladım Kuytu bir köşesinde kalbimin. Solgun yüzlerini okşarken Bir deniz ağladim. Bir nefes çaldim rüzgardan. Bir kıvılcım güna...', ARRAY['Türk Edebiyatı','Şiir','Berna Yılmaz']::text[], 8.5, '{"poet":"Berna Yılmaz","poet_slug":"berna-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/fener-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzuhal', 'arzuhal-giray-ozer-3lqs7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Okyanuslar mürekkep olsa da yetmezdi

Arzuhalimi kaleme almaya.

Biçare kalırdı ferfigan eden çırpınışları yüreğimin, 

Umutsuzca yeis eden kaderime.

Kainatın bestesini ben yapsam, 

Güftesini de sen, sessizce ve utangaç.

Ne müderrisin ilmi yeterdi bu aşkı anlamaya, 

Ne de kalemi kıran hakimin çaresizliği.', 'Okyanuslar mürekkep olsa da yetmezdi Arzuhalimi kaleme almaya. Biçare kalırdı ferfigan eden çırpınışları yüreğimin,  Umutsuzca yeis eden kad...', ARRAY['Türk Edebiyatı','Şiir','Giray Özer']::text[], 8.5, '{"poet":"Giray Özer","poet_slug":"giray-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/arzuhal-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutku', 'tutku-okan-malgas-wcnl8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'anlatamadığım bir tutku içimde gitmek

vede kimsenin anlamadığı

gitmek uzaklara, ta uzaklara

kaçmak aslında

en başda kendimden

yarım yamalak sevdalardan

bir gün geceden bir gün gündüzden

dedimya bir tutku içimde gitmek

gidebildiğim yere kadar 

ve kaçabildiğim kadar kendimden.', 'anlatamadığım bir tutku içimde gitmek vede kimsenin anlamadığı gitmek uzaklara, ta uzaklara kaçmak aslında en başda kendimden yarım yamalak ...', ARRAY['Türk Edebiyatı','Şiir','Okan Malgaş']::text[], 8.5, '{"poet":"Okan Malgaş","poet_slug":"okan-malgas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tutku-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtiyar Balıkçı', 'i-htiyar-balikci-okan-malgas-rn45m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağzında bir kötü sigara

Yarıya kadar ıslak 

Çoktan sönmüş zaten

Yaşadığı aynı çaresizlik 

Boş ağları çekerken

İhtiyar balıkçı

Yüzünde sakalı ak

Omuzunda bir acı sızı ta Koreden

Köhne teknesinin kenarında oturduğu yerden

Her seferinde umuda uzanışı ellerinin

Ve her seferinde yaşadığı aynı çaresizlik

Boş ağları çekerken

Kızarda diyemez

Korkarda küfür bile edemez

Bilirya deniz

Bir gün ekmek verir adama

Bilirya bir gün adamı alır', 'Ağzında bir kötü sigara Yarıya kadar ıslak  Çoktan sönmüş zaten Yaşadığı aynı çaresizlik  Boş ağları çekerken İhtiyar balıkçı Yüzünde sakalı...', ARRAY['Türk Edebiyatı','Şiir','Okan Malgaş']::text[], 8.5, '{"poet":"Okan Malgaş","poet_slug":"okan-malgas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ihtiyar-balikci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dosttuk Biz', 'dosttuk-biz-okan-malgas-g6czp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dosttuk biz.

Deli dalgalı bir denizdi yüreğimiz.

Alabildiğine fırtınalı ve uçsuz bucaksız.

Yağmurda dolaşırdık hiç ıslanmadan,

Sonradan süslü lambalar ve rengarenk kaldırımlar yapılan yolda.

Yıldızları seyrederdik hiç konuşmadan

Ta ki hepsi gidene dek

Son sıgaramızıda paylaşırdık,umutsuz sevdalarımız gibi

Bazen üç bazen dört kişi.

Ve her dumanda ayrı bir hüzün kaplardı karanlık geceyi

Dosttuk biz eskiden

Göğsunü rüzgara vermiş asi dağların en zirvesinde açmış kardelenler gibi

Çiğ düşerdi üstümüze

Üşümezdik umursamazdık da

Düşerse düşsündü bizeneydi ki

Gün olur patlamaya hazır volkan gibi

Kıpır kıpır yerimizde duramazdık

Dolanırdık koca şehri en baştan en sona

Kimseyle yoktu işimiz alıp veremediğimiz

Kimsede bize bulaşmazdı ha

Öylesineydik kendi halinde

Otururduk bir köşede bilmeden

Bazen saatlerce bazen günlerce', 'Dosttuk biz. Deli dalgalı bir denizdi yüreğimiz. Alabildiğine fırtınalı ve uçsuz bucaksız. Yağmurda dolaşırdık hiç ıslanmadan, Sonradan süsl...', ARRAY['Türk Edebiyatı','Şiir','Okan Malgaş']::text[], 8.5, '{"poet":"Okan Malgaş","poet_slug":"okan-malgas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/dosttuk-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal', 'hoscakal-hikmet-yakisir-17ok7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hoşça kal arkadaşım.

Seni tanımak güzeldi, 

Arkadaşın olmak da güzeldi, 

Sana sarılmak, 

Seni öpmek bambaşkaydı.

Ama olmadı.

Hoşça kal arkadaşım, 

Karlı dağlarda, 

Buzlu yollarda

İçki sofralarında

Eşlik etmen güzeldi, 

Ama olmadı.

Hoşça kal arkadaşım, 

Bana katlandın, 

Kahrımı çektin, 

Bedenime sarıldın, 

Öptün beni, 

Ama olmadı.

Hoşça kal arkadaşım, 

Sana katlandım, 

Yalnızlığını paylaştım, 

Zaman oldu sana sarıldım, 

Hatta öptüm seni, 

Ama olmadı.

Hoşça kal arkadaşım, 

Bir engel var aramızda, 

Unutamadığın.

Benimleyken bedenin yanımda, 

Beynin ve kalbin başka yerde, 

Bu olmadı arkadaşım.

Israrla denedik ama olmadı.

Canın sağ olsun, 

Üzgünüm, 

Üzgünsün, 

Belki bir gün? 

Hoşça kal arkadaşım.

(29 Haziran 2003)', 'Hoşça kal arkadaşım. Seni tanımak güzeldi,  Arkadaşın olmak da güzeldi,  Sana sarılmak,  Seni öpmek bambaşkaydı. Ama olmadı. Hoşça kal arkad...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yakışır']::text[], 8.5, '{"poet":"Hikmet Yakışır","poet_slug":"hikmet-yakisir","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/hoscakal-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Gökyüzü Ah!', 'ah-gokyuzu-ah-naime-erlacin-f8rfr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ah gökyüzü! 

tutmuş da 

bırakmıyorsun yakamı bir türlü

vazgeçtim ulaşmaktan

paylaşmak, bölüşmekten

tepemden insen ya! 

ne ararım sende 

ne özlerim bilmeksizin

öylesine dalıp gidiyorum işte

kuş olup uçmak istiyorum koynunda

gözümü alamıyorum bir yıldızdan

maviden 

siyahtan 

boz buluttan

ah gökyüzü 

ben sana sevdalandım galiba

fırtına esip yağmur olup

tam huzur buldum derken 

kar yağdırıyorsun tepemden

seviyorum seni 

anla işte! 

ne fayda, gürlemedikçe 

ses vermiyorsun

neden? 

dayasam başımı sonsuzluğuna 

göğsüne yaslanır gibi aşkın

kuş olup 

pır pır etsem yüreğinde

bulut olup 

gezinsem her bir yerinde

kurtulur muyum ki acep senden

ah gökyüzü ah

ben sana sevdalandım galiba! 

(29 Haziran 2003)', 'ah gökyüzü!  tutmuş da  bırakmıyorsun yakamı bir türlü vazgeçtim ulaşmaktan paylaşmak, bölüşmekten tepemden insen ya!  ne ararım sende  ne ö...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ah-gokyuzu-ah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adem/Badem+', 'adem-badem-bayram-tunca-tlf0w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aah var ya sen benim bademim olsaydın

Olsaydım, ben de senin ela gözlü âdemin

Mesir macunu yapsaydık balla bademden

O vakit vazgeçer miydi âdem bademden? 

www.baysab.com/29.06.2003-12:29

''Aşk Ateşten Gömlek'' yayınlandı', 'Aah var ya sen benim bademim olsaydın Olsaydım, ben de senin ela gözlü âdemin Mesir macunu yapsaydık balla bademden O vakit vazgeçer miydi â...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/adem-badem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittiğin Gün....', 'gittigin-gun-ugur-deniz-ulkegul-o9c8e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Giderken bir çift bakış bıraktım omuzlarına, 

Avuçlarım taze ayrılık kokuyor, 

Henüz gitmişliğinin, hüznü çökmüş kaldırım taşlarına, 

Şimdi bu sessizlik, dokunuyor..............

Ağlarsam, ayıplama beni sakın, 

Küsersem yarına, 

Yorulursam sensizlikte, 

Yenilirsem yokluğuna....

Bu sana yazdığım son şiir güzel, 

Söylediğim son türkü, 

Son gazel....

Bu son düşünür oluşum seni, 

Son sigara yakışım, aklımda sen, 

Son çıkarışım elbiseni.....

Unutursam güzelliğini, kızma vefasız oluşuma, 

Darılma bir gölge gibi karanlıkta kayboluşuma, 

Ve mektuplar yollama aşka dair, sevdaya dair, 

Aldanma usulca uzanıp gecede, saçına dokunuşuma...

Bir yalana inandırma beni, 

Dönüşsüz bir yolun, isimsiz bir adresine gidiyorsun, 

Ve ''unutma beni, seni seviyorum'' diyorsun...

Unutma beni, 

Bölüştüğümüz ekmeği, 

Alıştığımız sokağı, 

Seviştiğimiz evi...

Artık yok hiç biri, biliyorsun.............

Çekip gidersem bir gün bu şehirden, 

Kırılma yokluğuma...

Çekip gidersem gözlerinden, 

Ve altın sarısı saçlarının her telinden, 

Karanfil kokusu teninden, sözlerinden, 

İntizar etme yüreğimin burukluğuna....

O gün, 

Bakışlarımın omuzundan yere düştüğü gündür...', 'Giderken bir çift bakış bıraktım omuzlarına,  Avuçlarım taze ayrılık kokuyor,  Henüz gitmişliğinin, hüznü çökmüş kaldırım taşlarına,  Şimdi ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gittigin-gun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısa Bir An', 'kisa-bir-an-i-smail-tas-doggv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tüm aşklarımı yitirdim dün gece bir bir

Karanlık, hayallerimde gecenin bir vakti

Dertli bir radyo ve eski bir şarkı

Bugünün yarına kalmamış merakı

Kaldırımlar ıslak, sessiz ve rüzgar esiyor

Dalıyorum, anlıyorum, ağlıyorum…

Vakit  gece sokaklar yorgun, düşünceli

Hayalleri mazide kalmış bir adam ve bir resim

Ve sokak lambalarında hep aynı hüzün

Sol yanımda her şey sensiz ve üzgün

Avuçlarımda eski bir şiirin göz yaşları

Siliyorum, anlıyorum, ağlıyorum…

Yitik bir aşkın ızdırabı mısralarda

Karşiki vitrinde cansızsız çocukluğum

Bu falcı nerden öğrenmiş hikayemi

Durmadan anlatıyor ne varsa eski ve yeni

Ve eski bir kadının hayali sokağın orta yerinde

Bakıyorum, anlıyorum, ağlıyorum....

                           			Mayıs 2000', 'Tüm aşklarımı yitirdim dün gece bir bir Karanlık, hayallerimde gecenin bir vakti Dertli bir radyo ve eski bir şarkı Bugünün yarına kalmamış ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Taş']::text[], 8.5, '{"poet":"İsmail Taş","poet_slug":"i-smail-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kisa-bir-an-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acılar', 'acilar-mustafa-sureyya-sezgin-4xsj9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Acılardan zevk almayı öğrendim

Yürüyüşünü, gülüşünü, 

Başka biriyle konuşmanı

Ve seni görmek bana acı veriyor.

Oysa bir başka duyguydu

Seni özlemek, seni gözlemek

Senin için ölebilmeyi düşünmek.

Tükendi artık  duygular.

Acı duyarak karşılaşıyoruz.

Yine de

Anılaşacak günler yaşıyoruz.

Zaman da acımasız geçiyor.

Seni düşünüyorum

Geçmiş zaman aralığında.

Gün gelecek

Birbirimiz için biz, 

“ Bir zamanlar “ olacağız.

Bugün gibi

İçim acı dolacak.

Tutku muydu duyulanlar

Anlamayacağız...

Mustafa Süreyya SEZGİN

İstanbul,28.06.2003', 'Acılardan zevk almayı öğrendim Yürüyüşünü, gülüşünü,  Başka biriyle konuşmanı Ve seni görmek bana acı veriyor. Oysa bir başka duyguydu Seni ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/acilar-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kargalar', 'kargalar-ali-ender-cemgil-xtq1x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yine üşüştüler

nerde görseler

nerde birinin düştüğünü görseler

üşüşürler.', 'yine üşüştüler nerde görseler nerde birinin düştüğünü görseler üşüşürler....', ARRAY['Türk Edebiyatı','Şiir','Ali Ender Cemgil']::text[], 8.5, '{"poet":"Ali Ender Cemgil","poet_slug":"ali-ender-cemgil","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kargalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görünenin Öteki Yüzü', 'gorunenin-oteki-yuzu-ali-ender-cemgil-hw357', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıkıldı şehrin duvarları

Kayboldu içinde zaman', 'Yıkıldı şehrin duvarları Kayboldu içinde zaman...', ARRAY['Türk Edebiyatı','Şiir','Ali Ender Cemgil']::text[], 8.5, '{"poet":"Ali Ender Cemgil","poet_slug":"ali-ender-cemgil","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/gorunenin-oteki-yuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özleyiş', 'ozleyis-sair-evindar-nf441', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne işim mi vardı o caddede bilmiyorum. Sıradan bir işti işte. Haftalar sonra yine oradan geçiyordum.Oysa hep kaçtığım içinden geçmemek için yaya yürümek pahasınada olsa farklı otobüslere bindiğim, bazende olurya içinden geçersem kendimi evine giden o sokağa bakmamak için koşullandırıp ama her seferinde yenilip hani olur ya belki seni görürüm diye son anda başımı çevirdiğim o caddedeydim işte. Caddeye ilk girişimle kalp atışım hızlandı, kan şekerim, tansiyonum allak bullak.üşümeye terlemeye başladım tüylerim diken diken.  Yolun o beraber yürüdüğümüz yanından yürümemeye özen gösterdim ve ilerledim... Karşımda sahne alan o caddeyi hızlı adımlarla geçmek istedim. Karşımda her tarafı senin hatıran olan bir yol uzanıyordu. Bir baklavacı dükkanı tüm anılarını döküyordu önüme seni beklediğim sokağın başındaki trafik lambası renk renk yanıp sönüyordu. Beraber oturduğumuz o pastane, para çektiğin o bankamatik ve adımlarının sıcaklığını, izlerini taşıyan yolun karşı kaldırımı...hızlı hızlı ilerledim. Neden ama korkuyordum. Korkuyorsam nedendi bu korku.kim bir caddeden korkardı ki. Ya deli olmalıydım ya da körkütük bir bir aşık yoksa ikiside aynı şeymiydi.

Yürüyordum başım önümde ve hızlıca. Yolda kaç kişiyeçarptım kaç küfür yedim hatırlamıyorumİşim yolun sonundaydı bitirip aynı yoldan hızlıca dönmeye karar verdim. Yürümeye başladım hızlıca ama sokağa yaklaştıkça ayaklarım söz dinlemez oldu. Birden yolun karşısına döndüm yüzümü pastane tam karşımdaydı. Canım yandı. Can havliyle kendimi yolunortasında buldum. Ne sağıma bakmıştım ne soluma veürküten o klakson sesiyle kendimi zorla yolun diğer yanına attım. Üstelik yaşlı bir kadın ben geçiyorum ve geçiyorsam müsaittir diye yanımda ilerlemiş o da son anda kurtulmuştu. Karşı tarafta gözgöze geldiğimizde anlamıştı benim normal olmayışımı, hadi ben aşıktım yaona ne olmuştu...Yürüdüm biraz daha, adım adım sokağına yaklaştım senin bıraktığın ayak izlerine basa basa ilerlermiş gibi. Dümdüz gidip o caddeden çıkıcaktım.Sokağın başına yaklaştıkça duralamaya başladım ve durdum o trafik lambasının yanında elimi cebime atıpbir sigara çıkardım ve yaktım. Gözlerimi sokağa dikip gelmeyeceğini bile bile bekledim. Sigaram bitti sonra gitme zamanımdı yürümeye başladım ama bir sorun vardı  ayaklarım gitmem gereken yönde gitmiyor senin ayak izlerini takip ediyordu ve sokağa girmiştim...O içinden kedi fırlayıp seni korkutan çöpkutusu hala ordaydı. Fotoğrafçı vitrindeki resimleri değiştirmişti. Meyve satan adam hala tezgahı dopdolusanki siftah yapmamış gibi duruyordu. Ağır ağıryürüyordum sokakta attığın her adımı tabanlarımda yaşayarak.Birden evinin olduğu binanın önünde buldum kendimi. Geri çekilip öylece baktım.ışıklar yanmıyordu gitmiştin odan karanlıktı yoktun. İzledim biraz karanlığı. İnce bir miyav sesi geldi kulağıma. Bir kedi yavrusu ayaklarımın arasında dolanıyordu. Eğildim okşamaya başladım. Ürkekçe ama isteyerek tüylerini okşatıyordu bana. Sanki bana ihtiyacı vardı ama korkuyor güvenemiyordu. Oysa ben öyle korkulacak biri değildim. Korkuttuklarım ve korkanlarım vardı ama öyle değildim. Senden de sakınmıştım zaten korkulası yanlarımı. Kediye seni sordum miyav dedi, gördünmü diye sordum miyav dedi, iyimiydi diye sordum yine miyav dedi. Zaten o bir kediydi hep miyav derdi benimbaşka cevap beklemem yanlıştı.yapabileceğim tek şey miyavları evet saymaktı iyi niyet adına bende öyleyaptım. Soracaklarım bitmiş kedide sanki bunları hissetmişçesine yanımdan uzaklaşmıştı...Bir süre daha evini izleyip kalkmaya karar verdim. Ayağa kalkıp adım atmaya başladım ama ayaklarım yine başına buyruk değildi. Buyruklarını kalbimden alıyorlardı. Binanın bahçesinde buldum kendimi önce sonra giriş kapısında ve merdivenlerden çıkıveriyormuşum meğer kapıya yaklaştıkça içim acıdı ve 13 numaralı kapının önünde buluverdim kendimi. Sonra birden ortalık karardı otomatik söndü. Gözlerim

alıştıkça alacakaranlık görmeye başladım ortalığı. Sonra kulağımı kapıya dayadım belki sesini sesini olmasada yankısını duyarım diye. Gözetleme deliğinden senin belki aylar önce bıraktığın o “kim gelmiş” meraklı bakışını aradım. Elim kapının tokmağına gidiverdi orda elinin sıcaklığını aradım sonra zile gitti elim parmak uçlarını hissetmek adına. Alacakaranlıkta seni hissetmeye çalıştım ve uzun zamandır hissedemediğim sıcaklığını. Kendimden geçmiş farklı bir boyutta bulmuştum kendimi. Sonra birden zil sesiyle irkildim. Zil düğmesine fazlaca basıp çalmasını sağlamışım. Panikledim dizlerim titredi.Kaçamayan tavşan gibi yerimde durdum bir an. Sonra hızla merdivenden indim sonra durdum ucunda bekledim

basamakların, kapıyı açanı görmek için durdum. Kimse açmadı unutmuşum işte ışıklar kapalıydı, evde kimse yoktu, sen yoktun...Sonra indim ve çıktım binadan. Tıpkı eskisi gibi her akşam üstü senden ayrılırken evime döndüğüm oyoldan yürümeye başladım. O yolda her zamanki gibiseni düşündüm. Ellerim sıkılı değildi dişlerimibirbirine kenetlemiyordum, acı çekiyordum ve tek bu acıya isyan etmiyordum. Seni düşünüyordum birde kendimi. Senin gidişinle başlayan kaybedişlerimi. Senin yerine sokmak istediğim insanların içimdeki boşluğu büyütüşlerini, hatalarımı, başarısızlıklarımı ve şimdiki bu halimi. İçimde özleyişininm yangısı cayır cayır ağzımdan şu mısralar çıkıyordu: 

Oldu olmaz bir sevda

Olmaz oldu bir sevda

Sen yoktun. İçim doluydu. Özleyişim gözyaşıma vuruyordu. Gel dedim Neredeysen gel artık... Bana bir ömür yetecek o sıcak bakışınla

dokun kalbime. Acı çekiyorum, isyan etmiyorum, 

seni seviyorum.', 'Ne işim mi vardı o caddede bilmiyorum. Sıradan bir işti işte. Haftalar sonra yine oradan geçiyordum.Oysa hep kaçtığım içinden geçmemek için ...', ARRAY['Türk Edebiyatı','Şiir','Şair Evindar']::text[], 8.5, '{"poet":"Şair Evindar","poet_slug":"sair-evindar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ozleyis-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-sadullah-bayar-vyx36', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'artık zor geliyor sensiz yaşamak

sensiz yatağımda sağa sola dönmek

dokunmak dudaklarıma ellerinin yokluğunda

gerçekten de zor geliyor.

oysa hiç düşünmemiştim sensizliği

sensiz geçen günleri hiç düşünmemiştim.

öyleki gün be gün seni arıyor

yanağımdan düşen yaşlar.

hani sigaram bile kar etmiyor desem bilki yalan olmaz.

nefesini arıyor ciğerlerim.

öpüşüne hasret dudaklarım.

tutmuyor artık ellerim ellerin olmadan.

inan eskisi gibi bakmıyor gözlerim.

sen yoksun ya

güneş bile doğmuyor dünyama.

dağlara taşlara yazsam adını

göğün mavisine kazısam

anlatabilirmi ki acaba sana olan sevgimi.

inan güzelim sazım bile özledi seni

her notada adın 

her telde yüzün

ve her seste sevgin

yokluğun boynumda bir kara yılan

hani yenik düşsem sensizliğe sıkacak boynumu

ayıracak beni senden', 'artık zor geliyor sensiz yaşamak sensiz yatağımda sağa sola dönmek dokunmak dudaklarıma ellerinin yokluğunda gerçekten de zor geliyor. oysa ...', ARRAY['Türk Edebiyatı','Şiir','Sadullah Bayar']::text[], 8.5, '{"poet":"Sadullah Bayar","poet_slug":"sadullah-bayar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sensizlik-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata Dair', 'hayata-dair-i-rem-yitmen-3d5vk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayat bir bilmecedir, 

Çoğu zaman çözemediğin

Umutlarla beslenen aç bir çocuk, 

Karnı doymadığında ağlayan

Hayat göçebe bir çingenedir, 

Obalarda konaklyan

Daldan dala konar çoğu zaman

Süzülür enginlere bir kuş misali 

Hayat topal bir körebedir, 

Köşebaşlarında saklambaç oynadığın

Dehlizlerinde tuzaklandığın

Girdaplarında sürüklendiğin

Hayat bir kasırgadır çoğu zaman

Yüreğin titrer şiddetinden

Yaprakların dökülür işte o zaman 

Kalırsın çıplak bir ağaç misali 

Hayat bir alevdir çoğu zaman, 

İçini tutuşturan bir sıcaklık

İşte o zaman anlarsın ki

Hayat, ''''BİZİM HİKAYEMİZDİR''''

iREM YİTMEN(1999)', 'Hayat bir bilmecedir,  Çoğu zaman çözemediğin Umutlarla beslenen aç bir çocuk,  Karnı doymadığında ağlayan Hayat göçebe bir çingenedir,  Oba...', ARRAY['Türk Edebiyatı','Şiir','İrem Yitmen']::text[], 8.5, '{"poet":"İrem Yitmen","poet_slug":"i-rem-yitmen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hayata-dair-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamlar', 'aksamlar-i-rem-yitmen-ssaf7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Akşam, pencerlerde bir kadın

Bir adamın yorgun ayak sesleri

Emekçi çocuğu buruk gülümsemesi

Bir barda içki şisesi

Bir pavyonda gönül eğlencesi

Akşam, sokaklarda bir hüzün

Bir çöplükte kedi hırıltısı

Bir köpeğin serseri havlaması

Bir sokak lambasının loş ışığı 

Gölgelerin koyu fısıltısı

Akşam, vefakar bir sevgili

Zavallı ruhların göğsüne yaslandığı

Teslimiyetin son durağı

Yeni bir canın ilk çığlığı

Uzun yolun bir başı

Akşamlar bir suçlu

Hüzünlü bir şarkıda

Yanlız bir şiirde

Bir içki şisesinde

Bir karakol köşesinde

Kalemimdeki bir damla mürekkepte

İrem Yitmen(1986)', 'Akşam, pencerlerde bir kadın Bir adamın yorgun ayak sesleri Emekçi çocuğu buruk gülümsemesi Bir barda içki şisesi Bir pavyonda gönül eğlence...', ARRAY['Türk Edebiyatı','Şiir','İrem Yitmen']::text[], 8.5, '{"poet":"İrem Yitmen","poet_slug":"i-rem-yitmen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aksamlar-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar Gelmeden', 'sonbahar-gelmeden-tolga-baydar-rgqtp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel güzelim gel kırlara kaçalım

Sonbahar gelmeden 

Bu güzelliğin tadına varalım

Çok uzaklara gidelim ki

Kimse görmesin bizi

Ve rahatsız etmesinler ikimizi

Konu-komşunun dırdırından uzak

Bir pınar kenarında uzanalım

Gökyüzüne bakıp

Düşlere dalalım

Gel güzelim gel

Bu güzelliği doya doya yaşayalım', 'Gel güzelim gel kırlara kaçalım Sonbahar gelmeden  Bu güzelliğin tadına varalım Çok uzaklara gidelim ki Kimse görmesin bizi Ve rahatsız etme...', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sonbahar-gelmeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİN YÜZÜ OLMALI İNSANIN (Düz Yazı)', 'bi-n-yuzu-olmali-i-nsanin-duz-yazi-naime-erlacin-kwekj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bin yüzü olmalı insanın. Olmalı ki, sıkmasın öz canını. 

Başkalarını yeterince sıkmıyor muyuz zaten?

Ayrıca sıkılmak, yarı ölüm demek değil midir bir anlamda.? 

Sözünü ettiğim bin yüzlülük, post-modern  çağın bukalemun sendromu ile  karıştırılmamalı. O tamamen farklı olup; içinde özenti, çıkarcılık, fırsatçılık ve bilgiyi yeterince sindirmemişlik barındıran değişik bir kavram. Ben bilgiyi sevdamsı bir tutkuyla özümsemek ve ortaya çıkan “öz” yardımıyla yeniden üretmekten söz ediyorum. Hiç değilse kendimize doğurgan olmaktan... 

Doğurdukça çoğalır insan. Sahip olduğu “yüz”lerin sayısı artar ve üretmeyi sürdürür. Kişisel görüşüme göre, insan iç yolculuklarında ve yalnızca kendi içinde büyür. Bunun için, sıradan bir ''prototip'' olmaktan öteye geçip, pek çok değişik ilgi alanına ve farklı yüzlere sahip olmak gerek.

Yaşamak, biteviye sorular sorarak keşfetmek ve öğrenmektir aslında. Kendini keşfetmek de dahil buna. Fikrimi sorarsanız eğer, ''soru'' yanıttan her zaman daha önemlidir. Sormayı bilmeyen kişi aldığı cevabın değerini de asla anlayamaz. Sormayı bilmek, içerideki “ben”leri çoğaltarak, bir anlamda “bin yüzlü” olarak ve bunu yaparken de “merak kapısı” ve ”gönül gözü”nü açık tutarak kolaylaşıyor ancak. En azından benim için böyle... 

Hayat ağacını, gönül gözünden açılmış çok sayıda pencereden bakarak ve bilgi ile zenginleştirerek sulamak gerek arada sırada. Gerçekleştirmek ise pekala mümkün bence. İnsan yeterince güçlü, derin ve kalabalık kendisine. 

Ama ne hikmetse daima yalnızlıktan şikayet edip durur! 

Bugün böyle bir konu açmak istedim size. Belki bir gün, başka bir sayfada yeniden buluşuruz. Bakarsınız o sefer de farklı bir yüzümle dikilirim karşınıza. Ben biliyor muyum sanki, bende benden içeri kaç kişinin var olduğunu?

Kalınız sağlıcakla dostlar…

(29 Haziran 2003)  - ''Gençler İçin Denemeler'' Dosyasından...', 'Bin yüzü olmalı insanın. Olmalı ki, sıkmasın öz canını.  Başkalarını yeterince sıkmıyor muyuz zaten? Ayrıca sıkılmak, yarı ölüm demek değil ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bin-yuzu-olmali-insanin-duz-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden', 'yeniden-sair-hacktrix-t6oci', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni severek gittim bu şehirden, 

Döndüğümde sevmemeyi ümit ederek.

Öğrendim sevmeyi, 

Severek ve giderek sevmeyi.

Giderayak terkettin beni, 

Sevmeyerek ve unutarak.

Soğuk gibi sensizdim, 

Ya da derin bir ırmak gibi dolu.

Dokunsalar ağlayacaktım ama, 

Dokunamadılar.

Çünkü ben bir tek, 

Gİderken ve sen dokunurken hissediyordum.

Ve seviyordum, 

Seni, sensizliği ve  gidişini.

Gidişim kadar sessizdin sen.

Susuşun kadar avazdı sesin, 

Gecenin ayazına karşı.

Ben yine sensizdim, 

Ben yine üşüdüm, 

Ve ben sadece

Seni yeniden sevdim', 'Seni severek gittim bu şehirden,  Döndüğümde sevmemeyi ümit ederek. Öğrendim sevmeyi,  Severek ve giderek sevmeyi. Giderayak terkettin beni,...', ARRAY['Türk Edebiyatı','Şiir','Şair Hacktrix']::text[], 8.5, '{"poet":"Şair Hacktrix","poet_slug":"sair-hacktrix","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yeniden-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balık Baba', 'balik-baba-zeki-ergin-832k5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '_____necdet abinin anısına

yorgun göçmen kuşlar gibi

kalakalmıştın bizim limanda

1940ların 50lerin istanbulunu anlatırdın

sabahları durakta

bir de sevdalarını

göremedin bu baharı

zemheri soğuklarına dayanamadı

yorgun bedenin

sen çocukların

fış babasıydın önceleri

derken 

hepimizin necdet babası olduydun

9,30 otobüsü hüzünlü

koltuğun boş

gülpınar kahvesinde masan boş

akliman kedileri öksüz

limanda

son sevgilin öksüz ve de mahzun

başüstünde bir kuş

seni bekliyor fiş baba

kuşlar öksüz 

_babakale haz03

_sevgiliye isyan yt:haz04', '_____necdet abinin anısına yorgun göçmen kuşlar gibi kalakalmıştın bizim limanda 1940ların 50lerin istanbulunu anlatırdın sabahları durakta ...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/balik-baba-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün', 'surgun-ozgur-hatem-bcqwe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-Harman yeri, adam senin yüreğin.

				        Başak sürmesi sarı, 

				        Güneş huylu ellerin-

Sıcaktı. Kamaşan karnımda sızı

Sayrılı bedenimde yarim, 

Bıçaktı.

Uzaklara kanadım sessizce

Kimsesiz bir aşka adandım.

Geceye yaslanmıştım

Can yorgun

	Düş suskun

		Güz paramparçaydı.

Dala yürüdü özsuyum

Kabuğumu kavlattı.

Aşı tuttum

Sürgünüm başladı.

Mersin 19.06.2003', '-Harman yeri, adam senin yüreğin. 				        Başak sürmesi sarı,  				        Güneş huylu ellerin- Sıcaktı. Kamaşan karnımda sızı Sayrılı b...', ARRAY['Türk Edebiyatı','Şiir','Özgür Hatem']::text[], 8.5, '{"poet":"Özgür Hatem","poet_slug":"ozgur-hatem","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/surgun-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ney', 'ney-burhan-gokoguz-x79ju', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir ney sesi duymak istiyorum Tanrım

Anne sevgisiyle beslenmiş

Sigaramın dumanıyla karışmış

İçimdeki yalnızlıkla yıldızlara ulaşmış

Bir ney sesi duymak istiyorum Tanrım...

Güneş ışığı kadar saf

Hatıralarım gibi...

Bir bebeğin kayıtsız ilk çığlığı gibi...

Bir ney sesi duymak istiyorum Tanrım...

Şarap gibi yıllanmış

Mahzenin kasvetli havasıyla yoğrulmuş

Sevgilinin sesiyle ızdıraplara boğulmuş

Bir ney sesi duymak istiyorum Tanrım...

Dalgalarla sevişen

Denizin tuzlu havasını getiren

Semanın maviliği kadar berrak

Bir ney sesi duymak istiyorum Tanrım...', 'Bir ney sesi duymak istiyorum Tanrım Anne sevgisiyle beslenmiş Sigaramın dumanıyla karışmış İçimdeki yalnızlıkla yıldızlara ulaşmış Bir ney ...', ARRAY['Türk Edebiyatı','Şiir','Burhan Gökoğuz']::text[], 8.5, '{"poet":"Burhan Gökoğuz","poet_slug":"burhan-gokoguz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ney-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deprem', 'deprem-hikmet-karakus-fuhq2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bütün şehir yıkıldı üstümüze

                                ölümüne

                                bir gece, 

Döküldü bütün yıldızlar bir bir

                                 sessizce 

                                 yere, 

Yok yok; 

Bu ölüm varya

           beyaz değil

              tam sarıbeniz, 

Yapıştı tenimize.

Üstümüzde 

     yüreğimizde deprem, 

Bilmem ne desem? 

(İst.1999)', 'Bütün şehir yıkıldı üstümüze                                 ölümüne                                 bir gece,  Döküldü bütün yıldızlar bir ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/deprem-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tek Alay', 'bir-tek-alay-jonathan-swift-to8l4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Küçük servetini aptallara ve delilere

Bir ev yapılsın diye bağışladı.

Bir tek alayla kanıtladı

Bunun en çok bu ulusa gerekliliğini.', 'Küçük servetini aptallara ve delilere Bir ev yapılsın diye bağışladı. Bir tek alayla kanıtladı Bunun en çok bu ulusa gerekliliğini....', ARRAY['Türk Edebiyatı','Şiir','Jonathan Swift']::text[], 8.5, '{"poet":"Jonathan Swift","poet_slug":"jonathan-swift","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-tek-alay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Metelik Vermedi', 'metelik-vermedi-jonathan-swift-7bx8p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eğer dilini de kalemini de tutsaydı, 

Başkaları gibi yükselirdi o da.

Ama iktidar hiç aklına gelmedi, 

Servete de hiç metelik vermedi.', 'Eğer dilini de kalemini de tutsaydı,  Başkaları gibi yükselirdi o da. Ama iktidar hiç aklına gelmedi,  Servete de hiç metelik vermedi....', ARRAY['Türk Edebiyatı','Şiir','Jonathan Swift']::text[], 8.5, '{"poet":"Jonathan Swift","poet_slug":"jonathan-swift","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/metelik-vermedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabul Ediyorum...', 'kabul-ediyorum-jonathan-swift-9f6dw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kabul ediyorum ki, Dean''in belki de

Fazlasıyla taşlama vardı damarında; 

Bu taşlama isteğini de doyurmaya kararlıydı; 

Çünkü hiç bir çağ böylesine hak etmemişti bunu.

Ne var ki, kötülemek değildi onun amacı; 

Ahlaksızlığı kamçılar, ama ahlaksızın adını vermezdi; 

Hiç bir birey ona içerleyemezdi; 

Çünkü binlercesini kasdederdi.', 'Kabul ediyorum ki, Dean''in belki de Fazlasıyla taşlama vardı damarında;  Bu taşlama isteğini de doyurmaya kararlıydı;  Çünkü hiç bir çağ böy...', ARRAY['Türk Edebiyatı','Şiir','Jonathan Swift']::text[], 8.5, '{"poet":"Jonathan Swift","poet_slug":"jonathan-swift","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kabul-ediyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cabalayan Budalaliga Atif', 'cabalayan-budalaliga-atif-jonathan-swift-6hgyj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gerçekten has bir aptallık merhamete getirdi onu, 

Nükteli konuşmaya kalkmadığı sürece.', 'Gerçekten has bir aptallık merhamete getirdi onu,  Nükteli konuşmaya kalkmadığı sürece....', ARRAY['Türk Edebiyatı','Şiir','Jonathan Swift']::text[], 8.5, '{"poet":"Jonathan Swift","poet_slug":"jonathan-swift","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/cabalayan-budalaliga-atif-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acılar Yürütür İçimde', 'acilar-yurutur-i-cimde-derin-oger-mkw2z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çiçekler açar

Renk renk çocuk ellerimde

Dibini kazırım gökyüzünün

Paylaşmak için  tüm mavilikleriyle

Oysa o

Yağmurunun yelini almış gidiyor

Olanca ıssızlığıyla

Daha dün bulutlarını sırtlamıştım

Bu gün bu umursamaz tavırlarıyla

Bilse ki ne acılar yürütür içimde

Unuttuğum ne varsa 

Hatırlatır bir bir

Hırpalanmış anılarım düşer peşime

Yerden bir taş alıp fırlatırım denize

Ağlasın diye....................', 'Çiçekler açar Renk renk çocuk ellerimde Dibini kazırım gökyüzünün Paylaşmak için  tüm mavilikleriyle Oysa o Yağmurunun yelini almış gidiyor ...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/acilar-yurutur-icimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nice Yıllar', 'nice-yillar-mehmet-sari-mjt3v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Derdim yağmurda değil benim, 

Yağmur sonrası gökkuşağında

Gökkuşağı nazlıdır çünkü, 

                                   çalım satar.

Çıkıvermez öyle her yağmura

İstiyorum ki....

Delicesine boşansın gökten yağmur

Kan ter içinde bıraksın toprağı

Ben kokusunu çekerken içime yaşamın

O renk cümbüşü

                          iniversin başına.

Ve  hep gül istiyorum sevdiğim

Girerken yeni yaşına.', 'Derdim yağmurda değil benim,  Yağmur sonrası gökkuşağında Gökkuşağı nazlıdır çünkü,                                     çalım satar. Çıkıver...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sarı']::text[], 8.5, '{"poet":"Mehmet Sarı","poet_slug":"mehmet-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nice-yillar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fenomen', 'fenomen-ozcelik-peker-qyv7h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yağmur saçlarını ıslattı sonra taradı

Uzun zamandır ilk kez sevindi yağarken

Saç tellerin camdan baktığımda kırılıyor

Canıma batıyor bakamıyorum

Cansız bir varlığı canlandıran güzelliğin

Düşün bende ne yaralar açtı

Sesin tırtıl, kabuğunu kırdıktan sonra

İlk kanat çırpışı rengarenk bir kelebeğin

Tabi sesin kısa bir ömür oluyor

Kelebekten önce yaratılmış gibisin

Sanki o sana benzetilmek istenmiş

Benzerin yok benzetilenlerin var

Tanrı dünyayı yaratırken

Çiçekleri, insanları çizmiş üstüne

Gülleri çizerken kararsız kalmış

Senin daha güzel olduğuna karar vermiş

07.01.2002', 'Yağmur saçlarını ıslattı sonra taradı Uzun zamandır ilk kez sevindi yağarken Saç tellerin camdan baktığımda kırılıyor Canıma batıyor bakamıy...', ARRAY['Türk Edebiyatı','Şiir','Özçelik Peker']::text[], 8.5, '{"poet":"Özçelik Peker","poet_slug":"ozcelik-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/fenomen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamın Başındasın', 'yasamin-basindasin-muammer-kurt-f2prl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşamın başındasın 

Uçurumun ucunda 

Her adım atışında hayat yolunda 

Kah mutluluğa koşacaksın... 

Kimi zaman acı duyacaksın 

Baharı selamlayan kar çiçeğisin 

Erken açarsın martın ayazı kurutur seni 

geç kalırsın nisan güneşi 

Yani olabildiğince hayatı 

Anında yaşayacaksın. 

Bazı şeyleri önemsemeyeceksin 

Bazı şeylere “adam sende” diyeceksin 

Bazı şeylere alışacaksın 

Çoğu şeylere boş vereceksin. 

Yani hayatı hep 

uçurumun kenarında yaşayacaksın 

Yaşam insafsız avcı 

Sense ürkek bir ceylan... 

Ama inat edeceksin... 

İnadına diyeceksin 

Ve insafa gelecek halden bilmez avcılar 

İmrenecekler yaşama 

İmrenecekler bahara 

Çiçeğe, çiğdeme 

Yeşile, yaprağa... 

İmrenecekler sana. 

İmrenecekler cana... 

Güzelim...be güzelim... 

İnadına gürül gürül...! 

İnadına pırıl pırıl yaşanmalı şu hayat. 

Dünya üzülecek kadar güzel 

ömürde uzun değil. 

Çirkin dünyada güzellik olacaksın 

Bir anlık ömrü dolu dolu yaşayacaksın. 

Boş bir hayat geçirirsen 

Maziye döneceksin... 

Eyvahlar diyeceksin... 

Baharı unutacaksın... 

Dalında tomurcuklar kurutup 

Ağlayacaksın...üzüleceksin. 

Gün olacak dikenler arasında bir gonca görüp 

Bülbül olacaksın dalına 

Umutlar uçuracaksın, 

sevinçler uçuracaksın 

Leylim dağlara.... 

Mor menevşelere... 

Yılkı yılkı papatyalara 

Kan kırmızı karanfillere 

sevdalar konduracaksın. 

Yaşam dediğin başka nedir ki be güzelim... 

Varsay ki yaşamın başındasın... 

Yada sonunda... 

Ama unutma... 

Unutma ki 

Geçmiş zaman 

Geri gelmez bir daha...', 'Yaşamın başındasın  Uçurumun ucunda  Her adım atışında hayat yolunda  Kah mutluluğa koşacaksın...  Kimi zaman acı duyacaksın  Baharı selamla...', ARRAY['Türk Edebiyatı','Şiir','Muammer Kurt']::text[], 8.5, '{"poet":"Muammer Kurt","poet_slug":"muammer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/yasamin-basindasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecikenlere', 'gecikenlere-ozcelik-peker-ar1c2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geç kaldın güzel sevgili geç

Sakallarım çıkıyor bak

Ana okulumdaki aşkımla

Sen bir olamazsın

O zaman içimde temiz

Yalansız akan ırmaklar vardı

Aşkı uçurtma gibi sanırdım

Elimde tutacaktım yapamadım

Irmaklara götürürdüm seni düşlerimle

Suda eğlenirdik simitlerle

Birer bisikletle gezerdik

Ama şimdi beraber otur, otur

Gemilerle getirdiler sevgiyi

Birinden bana yüklediler

Yüklediler çok, çok koydular

Taşıyamadım sonunda battım.

17.01.2002 pzr', 'Geç kaldın güzel sevgili geç Sakallarım çıkıyor bak Ana okulumdaki aşkımla Sen bir olamazsın O zaman içimde temiz Yalansız akan ırmaklar var...', ARRAY['Türk Edebiyatı','Şiir','Özçelik Peker']::text[], 8.5, '{"poet":"Özçelik Peker","poet_slug":"ozcelik-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gecikenlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NehirYaşam Düşünceler', 'nehiryasam-dusunceler-sule-aydemir-h5qtn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir nehirdir

akar deli dolu ya bazen

silip süpürüp yıkarak

bazen sessiz sakin bir  yaşam 

yatağı aynıdır kendine bulduğu yol

ve bir gün 

bir kaya oynar  yerinden

yol yön değiştirir isyanla yeniden

yoktur aynı yerde aynı bereket

beklenemez de zaten

doğduğu yere dönüşü 

belki bir dolu 

yağmur bulutu anılar 

fazlası yok

olağan doğallığında nehirden

yüzünü asar eski hükümdar kuraklık

uyanır sulanan tohumlar

hareketlenir nehirle bu uyanışla yaşam

yeni yarlar açılır

verim ulaşır kıraçlardan

başka vadilere

başka ovalara

çağlar nehir

yeniden yeni hayata 

yaşamlar geçirmek içinde 

bir Nil yeşertmek belki

yeni isim vermek 

bu NehirYaşam ''dır sanki', 'bir nehirdir akar deli dolu ya bazen silip süpürüp yıkarak bazen sessiz sakin bir  yaşam  yatağı aynıdır kendine bulduğu yol ve bir gün  bir...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/nehiryasam-dusunceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cahit Deyince', 'cahit-deyince-alaeddin-ozdenoren-qbbsn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cahit deyince

Cahit deyince aklıma sular yıldızlar

Alınlarında şafak örülü

Anneler babalar

Gözleriyle gül toplayan çocuklar

Çöl rüzgârları kervanlar

Denize atılmış ağlar

Kalbe dökülen ırmaklar gelir.

Cahit deyince aklıma

İçinde bütün çiçekleri taşıyan sevdalar

Aşklar arkadaşlıklar gelir

Sait gelir Akif gelir Erdem gelir Rasim gelir.', 'Cahit deyince Cahit deyince aklıma sular yıldızlar Alınlarında şafak örülü Anneler babalar Gözleriyle gül toplayan çocuklar Çöl rüzgârları k...', ARRAY['Türk Edebiyatı','Şiir','Alaeddin Özdenören']::text[], 8.5, '{"poet":"Alaeddin Özdenören","poet_slug":"alaeddin-ozdenoren","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cahit-deyince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güller ve İzmarit', 'guller-ve-i-zmarit-bekir-gedikoglu-p6aif', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hepsi farklı renklerde

Değişik kokular içeren

Bahçemi renk cümbüşüne çeviren

Yoldan geçen kişi’yi cezbeden

Ki “ bir tane alabilir miyim” diyene

Buket, buket giden

Onlara baktığımızda bizleri mest eden

Azıcık sulamadığımda yaprakları dökülen

Saydığınız zaman on iki ocaktan oluşan

Evimin önünde küçücük bir bahçeye doluşan

Gözlerim gibi esirgenen

Zaman, zaman koklanan

Güllerim var...

Aman Allahım! 

Tüm bu dünyamı yıkan

 Güllerimin dibinde yatan

...bir İZMARİT var

Ankara,14.06.2003', 'Hepsi farklı renklerde Değişik kokular içeren Bahçemi renk cümbüşüne çeviren Yoldan geçen kişi’yi cezbeden Ki “ bir tane alabilir miyim” diy...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/guller-ve-izmarit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Loş Odada Üç Zaman', 'los-odada-uc-zaman-abdulkadir-karaman-bxp9k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yakıtı, kirli, fitili bitmiş bir mum 

tiryakiliğinde donanan bir oda

olmayan yok uykuda

hep uyanık olandan başka…

Doğrusu bilinecek

İspatlanacak her yalan

geçen her ânın nasıl geçtiğini kayda alan

görünmez kalemler

ve şeffaf kağıtlar tutulan…

O hercai melodileri

o vızıltı nağmelerle çalan ve okuyan

uykuların koynuna siper tutan iki sivri sinekti

sessizlikte zevke dalan

ıssızlıktan hoşlanan

ve dans eden tatminsiz heyecanla

çılgıncasına eğlencenin sarhoşluğuyla

aklına hiç gelmeyen tufan…

herkese kafa tutan

geceye ve sessizliğe üslenen zaman…

Loşluğun esrârengiz çekiciliğinde

iki göz iki bakış

sevinç ışıltılarıyla parlayan

iki dil ve alev alev dudaklar

birbirlerine şehvet nağmeleri fısıldayan

zevk ve heyecanın serseri yolcuları

sözleri tahrikkâr

temasları tahripkâr

kurbanına hançer vurmak için sabırsızlanan

ve zevkin ölüm döşeğinde

zevkten öldürecek zevk kâtilini

dört gözle bekleyen kurban

ve depreşmiş çılgınlıkların

her hududunu zorlayan

düşüncesi ve irâdesi

o zevk ânına odaklanan

istemeyen ve anlamayan 

başka bir şey, yaşamaktan

zevk ve şehvetle beslenen zaman…

İsyanın kuraklığında mahzun

günah yalçınlığında harap

ve dinleyen karanlığın gözyaşına sığınan

yaşaması gerekeni şüphe gölgeleri büyüsüyle 

yanılgılarıyla ve aldanışlarıyla yaşayamayan

gözü küskün

sözü ağlayan

bir kaktüs yalnızlığında serâp

yitiğini yıpranmış yol kağıtlarında arayan

içinde binlerce yalnızlığın pus görüntüsü

yanılgıya öfke feverân

göç ânının dehşetiyle duygulanan

öylesine işlerle, öylesine oyalanan

merhametli kelimelerin ellerine sarılan

ve insaflı cümleleri gözyaşı ile koklayarak

pörsümüş vicdan resimlerini sulayan

duyguları bombalayan inlemelerle 

pişmanlıklar içinde kıvranan

teslim olmuşçasına 

ve kabullenmişçesine reddettiklerini

isyanından usanan vicdana yaslanan

ve bağışa seslenen zaman…

Bir loş oda

ve üç zaman

geceye ve sessizliğe üslenen zaman…

zevk ve şehvetle beslenen zaman…

isyanından usanan vicdana yaslanan

ve bağışa seslenen zaman…

nasıl istersen öyle ol

olmayan yok harman

işte bu

her canın harcandığı 

ve her yüreğin çiçek olmak istediği orman.

08.06.2003', 'Yakıtı, kirli, fitili bitmiş bir mum  tiryakiliğinde donanan bir oda olmayan yok uykuda hep uyanık olandan başka… Doğrusu bilinecek İspatlan...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/los-odada-uc-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Çöl Şiiri: DİNGİN İSYANLAR...', 'col-siiri-di-ngi-n-i-syanlar-naime-erlacin-sxw9e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '“bir uğultu kalıyor

bir uğultu, bir uğultu

hiçbir çölü geçemeyenlerin kalbinde…”*

çöl kolay geçilmez! 

olsa olsa

kumdur taşınan geceden gündüze

bir tepeden diğerine

kafan karışır sadece

“dingin isyanlar fışkırıyor yüreğinden”

dedi biri senin için

“çöl de geçilir! ” diyemedikçe

dönemedikçe 

baş kaldırıp yaşamın içine

isyanın suretini taşımaya mahkûmsun dizelerinde

sunturlu sevdaların koynundan yankılanarak

bir esintiye dönüşecek yaralı gönlün

isyan yetmez! 

eylemsizlik bu yalnızca

donup kalıvermek çöl ortasında

elli dereceden taş gibi atlamak

gecenin zemheri soğuğuna

yepyeni bir hayata yürüyüp geçebilir misin 

acıya filan boş verip ardını toplamaksızın

kırıp döküp, yaralanıp haykırıp

 “çöl de geçilir! ” diyerek 

sen ona bak işte! 

gerisi “dingin isyanlar” yalnızca

belki bir düş alıp koynuna

uyumak en doğrusu

……….

(*)   Murathan Mungan: OMAYRA – “Çöl İşaretçileri VII”

(30 Haziran 2003)', '“bir uğultu kalıyor bir uğultu, bir uğultu hiçbir çölü geçemeyenlerin kalbinde…”* çöl kolay geçilmez!  olsa olsa kumdur taşınan geceden günd...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/col-siiri-dingin-isyanlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalin', 'hayalin-filiz-kurun-uxpdl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geç kalınmış aşkın hüznü

Yaşanıyor bugün

Nice aşıkların yaşadığından farklı

Leyla Mecnun  misali

Geç kalınan aşkın kalıntıları

Vuruyor yüreğim ıssız limanına

Bir ışık beliriyor durgun gecede

Sen yoksun ama hayalin

Gözlerimin önünde.

(13.06.01)', 'Geç kalınmış aşkın hüznü Yaşanıyor bugün Nice aşıkların yaşadığından farklı Leyla Mecnun  misali Geç kalınan aşkın kalıntıları Vuruyor yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Filiz Kurun']::text[], 8.5, '{"poet":"Filiz Kurun","poet_slug":"filiz-kurun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hayalin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilruba', 'dilruba-giray-ozer-4wr8e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu benim işte insan-ı beşer, güçsüzdür kader

Natamam olmasa devr-i cihan bir gün

Mahremiyeti yek kalmış ari sevgim mi yeter

Hem hicri, hem hicvi, yaşamaya son gün

Hürriyeti mütemmim olsa da cümle alemin

Aşikardır nefsimin artık mazi oluşu

Ah ecel ah! ezeli sırdaş dostum benim

Çok işvekardır onun sessiz dokunuşu

Hanemdir karargahı aşkımın, senin bir nefesin

En karamsar günümde o ıslak buseni hissetim

Ey Dilruba, ey aşk-ı şahane, neredesin

Ben seni meleklerin musikisinden daha çok sevdim', 'Bu benim işte insan-ı beşer, güçsüzdür kader Natamam olmasa devr-i cihan bir gün Mahremiyeti yek kalmış ari sevgim mi yeter Hem hicri, hem h...', ARRAY['Türk Edebiyatı','Şiir','Giray Özer']::text[], 8.5, '{"poet":"Giray Özer","poet_slug":"giray-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dilruba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masmavi2', 'masmavi2-oguzkan-bolukbasi-t5e96', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gök tutar maviyi sever

denizlerde saçını tarar masmavi

kimse bilmez içinde bir gizli duygu tapınağı vardır

kıblesi yalnızlığı

sevmez karanlığı

yokolacağını bilir

kalabalık değildir oysa aydınlığı

maviye uzanır eller

küçük kağıtlara yazılmış hayaller

bir adak gibi taşınır 

yürek yatırlarında çözülür gösterilmeden

bin yoksul yürek giydirilir

aç arzular doyurulur

solan gündür maviyi çalan

batan güneştir

gecedir hırsızı aydınlık sabahların

tüllerde esen rüzgar olmasa

ya da umut yarin yanına uzanıvermiş

masmavi korkacak karanlıktan

ama bilir ki gün dönermiş

yokuş bitermiş', 'gök tutar maviyi sever denizlerde saçını tarar masmavi kimse bilmez içinde bir gizli duygu tapınağı vardır kıblesi yalnızlığı sevmez karanlı...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/masmavi2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaraptan Aşkı Uykuda Yakalamak', 'saraptan-aski-uykuda-yakalamak-sule-aydemir-owyys', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'diyor ki -seni seviyorum bebeğim

görünce seni yarıldı yüreğim 

yıllar var uyumuş kabuğunda hislerim 

yeniden seninle yazdı suskun kalemim

ve iste beyaz sayfaları yakar yıkar giderim

ölmüştüm bir yerlerde bende

kucaklıyorum dirilişi onun gözlerinde

ellerimi bırakıyorum ellerine sevgi güvende

aşk yüreğime akıyor kokusuzum bu birleşmede

kıskanacaklar deliler gibi biliyorum

ve binlerce engel var düşünüyorum

incir kokuyor iliklerimde eflatunum

güçleniyorum güç bu seviyorum 

düşüncenin tel örgüleri parmaklarımla eziyorum

bir mavi yelkenli çıkıyor o an enginlere

bir kardelen boynunu uzatıyor karlı zirvelere

kurban veriliyor kibir mal mülk isteklere

aşk bir serserinin ihanetidir haramilere

nice büyük aşklar ölmüştür bir rakı kadehinde 

şimdi ki şarabın zamanı yıllanmış kırmızı tecrübe

minnettar ölmeden yakaladı kapıldı şükretmeye

Allah’ım yarıldı yüreğim  bu nasıl sevgi diye diye', 'diyor ki -seni seviyorum bebeğim görünce seni yarıldı yüreğim  yıllar var uyumuş kabuğunda hislerim  yeniden seninle yazdı suskun kalemim ve...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/saraptan-aski-uykuda-yakalamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tüm Rüzgarlarım Senden Olsun', 'tum-ruzgarlarim-senden-olsun-mehmet-fatih-kahraman-ig84p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tüm rüzgarlarım senden olsun.

Usulca girsin; gözlerimden bedenime

Görsün, içimdeki seni...

Büyülensin kasırgalara dönüşsün

Ayrılırken benide götürsün geldigi yere...

Biten ilk rüzgarım bu işte

Ayrılık gibi hüzün dolu

Yasanması yasak yitik aşk gibi

Rüzgar, sen ve yalnızlıgım....', 'Tüm rüzgarlarım senden olsun. Usulca girsin; gözlerimden bedenime Görsün, içimdeki seni... Büyülensin kasırgalara dönüşsün Ayrılırken benide...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih Kahraman']::text[], 8.5, '{"poet":"Mehmet Fatih Kahraman","poet_slug":"mehmet-fatih-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tum-ruzgarlarim-senden-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Yakar Beni', 'askin-yakar-beni-cemil-neseliler-tz5l0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayna karşısında ağlıyor koca bir adam 

Süzülen damlaya kurban etmiş ömrünü

Derin çukur açılıverir yanağına ciğer renginde

Yoksunki yanımda, dinmez, sensizlik kederim

Hasretin ne olduğunu bilmezdim öğrettin bana

Sevdayı tanımazdım yıllardır çektirdin bana

Acılarıma rıza gösterdim boynum kıldan ince

Teselliyi bulurum sessiz; çağlayan şiirlerimle

Unutmaya çalıştım her sabah oluşunda adını

Çaresizliği bilir misin nasıl yakar insanı

Ezanlarla uyandım, tesbihle zikreyledim hülyanı

Mabedime mihrab ettim gül  dudaklarını

İrem bağından şıralı üzümler topladım sana

Volkan bağrımdan ateş lavlar sunarım sana

Bu kaçıncı yaz bilmemki, kaçıncı haziran

Hicranı tuz diye bastım sabahlara dek yarama', 'Ayna karşısında ağlıyor koca bir adam  Süzülen damlaya kurban etmiş ömrünü Derin çukur açılıverir yanağına ciğer renginde Yoksunki yanımda, ...', ARRAY['Türk Edebiyatı','Şiir','Cemil Neşeliler']::text[], 8.5, '{"poet":"Cemil Neşeliler","poet_slug":"cemil-neseliler","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askin-yakar-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişemem', 'degisemem-murat-demir-gsaxc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Denizlere atsanızda

Ağaçlardan assanızda

Çivilere çaksanızda

Ben buyum, ben değişemem

Söz verdiysem geri dönmem

Aleniyim hile bilmem

Dost sırrını ele vermem

Ben buyum ben  değişemem

Riyakarlara pas atmam

İnsanım insanı satmam

Kralı gelsede korkmam

Ben buyum ben değişemem

Ya bu gün ya başka zaman

Dertler vermezsede aman

Boyun eyip demem tamam

Ben buyum ben değişemem

Murat derki bir garibim

Yüreğimdir tek sahibim

Ne hocam var ne rahibim

Ben buyum ben değişemem', 'Denizlere atsanızda Ağaçlardan assanızda Çivilere çaksanızda Ben buyum, ben değişemem Söz verdiysem geri dönmem Aleniyim hile bilmem Dost sı...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/degisemem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bile', 'sen-bile-murat-demir-5xzqw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Alacağımı senden

Almadan asla gitmem

Severim adam gibi

Ölmeğince terk etmem

Ya sen yada hiç kimse

Kalbimde olmayacak

Aşkın bende oldukça

Kadehim dolmayacak

Ne olsa gönül kapım

Asla kapanmayacak

Varmı dünyada sana

Benden başka tapacak

Sen bile benim kadar

Sen seni sevemezsin

Yıllardır bir aşk için

Canını veremezsin', 'Alacağımı senden Almadan asla gitmem Severim adam gibi Ölmeğince terk etmem Ya sen yada hiç kimse Kalbimde olmayacak Aşkın bende oldukça Kad...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-bile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek', 'beklemek-murat-tali-ngkhx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sevgiliyi beklemek

hemde bilinmeyen bir sevgiliyi beklemek

beklerken nasıl düşler kurar insan, 

hele gece düşlere dalmışken, 

uzanır bir el inceden inceye, 

sessizliği bozan, 

pencerenin kenarına düşen bir gül olur. 

yada, 

bir kuş kanatlanır gece karanlığı içinde 

beyaz aydınlığıyla.

geleni beklemek gecelere mahsustur. 

gecede, 

gelmeyenleri saklar koynunda 

bu yüzden gece yalnızlıktır. 

beklerken sevgiliyi

ince belli bir bardaktan çay yudumlar, 

ve 

pencereden dışarı bakakalır gözler.. 

Gözler; 

sevgili hasretinde sislere batmış, 

ay doğuşu özlemlerle yüklü 

gemiler gibi.. 

Nuh''ûn gemisine yüklenerek gelecekse 

sevgi 

yağmuru şiddetlendirki 

kasırgalara dönsün zaman...

gelecekse o vakit gelsin 

sevgili', 'Bir sevgiliyi beklemek hemde bilinmeyen bir sevgiliyi beklemek beklerken nasıl düşler kurar insan,  hele gece düşlere dalmışken,  uzanır bir...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/beklemek-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kel Görünür', 'kel-gorunur-salim-solmazgul-9abqu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnsanadır benim sevdam

Diken bana gül görünür

Hor bakamam hiç kimseye 

Her çiçekte bal görünür

İçtiğim aşkın şerbeti

Sevgi yenecek nefreti

Budur dünya adaleti

Takke düşer kel görünür

Aşk deryasına dalınca

Yüreğe sevgi dolunca

Aslı gibi yar bulunca

Kerem yanar kül görünür

Solmazgül hallerim böyle

Sen dertleri derman eyle

Alıp verdiğim nefesle

Zaman geçer yol görünür', 'İnsanadır benim sevdam Diken bana gül görünür Hor bakamam hiç kimseye  Her çiçekte bal görünür İçtiğim aşkın şerbeti Sevgi yenecek nefreti B...', ARRAY['Türk Edebiyatı','Şiir','Salim Solmazgül']::text[], 8.5, '{"poet":"Salim Solmazgül","poet_slug":"salim-solmazgul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kel-gorunur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Defa Sevmek Nasip Oldu, Ahir Ömrümde', 'bir-defa-sevmek-nasip-oldu-ahir-omrumde-i-brahim-bayraktar-1h440', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimşekler çaktı, fırtınalar koptu gönlümde, 

Bir defa sevmek nasip oldu, ahir ömrümde, 

Yalnız seninle olmak istedim düğünümde.

        Yıllardır sevdandan yorgun kalbimi, 

        Masada bıraktım haberin olsun.

Her katresi aşk kokan güzel rüyanın, 

Gönlüme saldığı sonsuz ziyanın, 

Sensiz manası yok yalan dünyanın.

         Yıllardır sevdandan yorgun kalbimi, 

         Tasada bıraktım haberin olsun.

Seninle doğdum ben, senle yoğruldum, 

Seninle yandım ben, senle kavruldum, 

Bir toprak tanesi gibi göğe savruldum.

        Yıllardır sevdandan yorgun kalbimi, 

        Nadasa bıraktım haberin olsun.

Bu ışık sönmesin, hep daim olsun, 

Mutluluk gemisi seferden dönsün, 

Sen, benim dünyamda yeni bir günsün.

         Yıllardır sevdandan yanan kalbimi, 

         Hasada bıraktım haberin olsun.

26.06.2003', 'Şimşekler çaktı, fırtınalar koptu gönlümde,  Bir defa sevmek nasip oldu, ahir ömrümde,  Yalnız seninle olmak istedim düğünümde.         Yıll...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-defa-sevmek-nasip-oldu-ahir-omrumde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haksızlık Etmez Aşka Çiçekler', 'haksizlik-etmez-aska-cicekler-hasan-ejderha-r1uj7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akşamın hüzünlü kanatları çöker ikindilerime

aşk zamanı neden yorar, neden yorulur aşk zamandan

haykıran bir geceyi taşır göz kapaklarım

kalmadı sarı yapraklı güzden eser ruhumda

yarım kalan bir şiirin hüznünü yaşarım.

Haksızlık etmez aşka çiçekler

gece hüzün, uyku hüzün, rûya hüzün

neden çağrısı yok, ilhamı yok bende gündüzün

adamlar ve adımlar dolaşır oysa avuçlarımda.

Gene mayıs geldi ana, baksana yıldızlar gülüşür

dirildi her şey, doğrulup bulutlarla öpüşür

yorulup kaldım mı kimsesiz, ana yok muyum yoksa

söylenmemiş mısralar yüreğimde niye üşür

bensiz olacak ne varsa oldu mu dünyada

dirildim sanıyordum oysa

devasa bir ömrün, zarif kimliği sürünür ardımsıra.

Hatırı, haysiyeti yok mu ana, söylenen bunca sözün

neden çağrısı yok, ilhamı yok bende gündüzün

hangi yüzümle eş, hangi yüzümle babayım ve hangi yüzümle oğulum sana

hangi yüzü sen verdin, hangi yüzümle öleceğim, hangi yüzüm kalacak dünyada

ne çok yüzüm varmış, hangisi şair, adımla hangisi çağrılır yüzümün

gözümün gördükleri hangi yüzüme yansır

hangi yüzüm utanınca kızarır 

arsız olan yüzüm hangisidir.

''eyvah benim oğlum delidir'' deme ana

ben her mayıs böyle olurum, bir de ramazanda/

haykırır bütün azalarım. 

Ahh ana, bir şeyi anladım

öğrendiğim çok şey yok bundan başka

haksızlık etmezmiş ihanet 

etmezmiş çiçekler aşka', 'Akşamın hüzünlü kanatları çöker ikindilerime aşk zamanı neden yorar, neden yorulur aşk zamandan haykıran bir geceyi taşır göz kapaklarım kal...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ejderha']::text[], 8.5, '{"poet":"Hasan Ejderha","poet_slug":"hasan-ejderha","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/haksizlik-etmez-aska-cicekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarıldım II', 'sarildim-ii-adnan-adiguzel-kfbwi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yıllar geçti ömür denilen istasyondan

isyanlarla dolu ne geceler yaşadım

kahroldum üşüdüm dondum

şimdi

yanımda bir zambak gibi süzülüşün

zamanı kalıplardan çıkarışın

madem gideceksin

git 

ama unutma unutma 

sen diye bestelediğim rüzgarları

akan sulara ismini yazıp

susuz topraklara yol verdiğimi

hadi gidiyorsun

yolun açık olsun

bahtın günebakan çiçekleri gibi

hep ışıktan yana olsun

hadi yolun açık olsun', 'yıllar geçti ömür denilen istasyondan isyanlarla dolu ne geceler yaşadım kahroldum üşüdüm dondum şimdi yanımda bir zambak gibi süzülüşün zam...', ARRAY['Türk Edebiyatı','Şiir','Adnan Adıgüzel']::text[], 8.5, '{"poet":"Adnan Adıgüzel","poet_slug":"adnan-adiguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sarildim-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-i-rfan-unubol-agzjo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensiz hayatın anlamı yok.

Seninle var olmalı  her şey ve sensiz yok.

Adını herkes bilir ama hepsi  tanımaz.

Kimi kalplerden taşıyorsun, 

Kimisinde yok denecek kadar az.

Güzellikler hiç bir işe yaramaz, 

Ahu gözler sevgiliyi aramaz.

Sensiz, tatlı diller hatırını soramaz, 

Tabirciler rüyaları yoramaz.

Sensiz, yolcu menziline varamaz.

Sensiz, kollar ince beli saramaz.

Sensiz arı balı yapmazdı.

Sensiz bülbül güle bakmazdı.

Sensiz kuşlar yuva bile yapmazdı.

Sensiz kul yaradana tapmazdı.

Seni almak ne mümkün, hele satmak anlamsız, 

En küçük kırıntına paha biçmek imkansız.

Bazen suların akışında, 

Bazen gergefin nakışında, 

Ya da bir yavrunun bakışında saklısın.

Gözden göze dalar, kalpten kalbe akarsın.

Bir bakışa bin bir anlam katarsın.

Gönüllerde yücelir, enginlere bakarsın.

Damarlarda dolaşır, ateş gibi yakarsın.

Bazen sözde çok özde yoksun.

Bazen kalpte çok dilde yoksun.

Güzellikle birlikte anılır adın.

Sahnede bazen bir kadın, 

Ya da bir ağaç, bir çocuk, bir kuş, 

Veya rüyalarda bir uçuş yükseklere, 

Ve süzülerek inerken bakmak yere, 

Seni yaşatır gönüllere.

Haziran 2003', 'Sensiz hayatın anlamı yok. Seninle var olmalı  her şey ve sensiz yok. Adını herkes bilir ama hepsi  tanımaz. Kimi kalplerden taşıyorsun,  Ki...', ARRAY['Türk Edebiyatı','Şiir','İrfan Ünübol']::text[], 8.5, '{"poet":"İrfan Ünübol","poet_slug":"i-rfan-unubol","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sensiz-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunamam', 'dokunamam-cemal-ekren-6ldyl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aç ve iştahı kabarmış bir hayvan gibi, 

aramızda dizginsizdi ayrılık.

Hem sonra, gövdelerimiz  henüz çocuktu.

Yüreği kemik baglamış bir kente; 

Gdiderayak tanıdım seni.

sen ki; boynunda çivili tasmasıyla

ver  ha umutlarımı acıtırdın, kanatırdın.

Memelerimde yılların suskunluğu vardı

bir dokun, 

Bin ah işit

Gözyaşlarım kanardı, 

dudakalrın çatlak

Ve gövdende

 Bir iç savaş sonrası patlamamış mayınlar vardı

Dokunamazdım

daha teninle tanışmamıştı tenim

ki ellerin hala dünyanın en yalnız elleriydi

çıka geldin

hay seni doguran ananın canına saglık

hoş geldin kurtuluşum

hoş geldin

başım gözüm üzerine, 

gönlümün üzerine hoş geldin

ser seremin, 

ser çawemin, 

ser evinamın, 

bekletme beni

de haydi o zaman

gel

vur beni

acıt beni

umut beni

dokunamazsamda

sev beni', 'Aç ve iştahı kabarmış bir hayvan gibi,  aramızda dizginsizdi ayrılık. Hem sonra, gövdelerimiz  henüz çocuktu. Yüreği kemik baglamış bir kent...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/dokunamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Noel Agacım', 'noel-agacim-gokhan-pamukcu-lb3x3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen benim küçücük noel ağacımın

rengarenk ışıklarısın.

Hiç bir gün söndüremediğim ışıklarsın.

Çünkü sen her gün yeni bir yılsın.

Çünkü sen her gün beni yaşlandıransın.', 'Sen benim küçücük noel ağacımın rengarenk ışıklarısın. Hiç bir gün söndüremediğim ışıklarsın. Çünkü sen her gün yeni bir yılsın. Çünkü sen h...', ARRAY['Türk Edebiyatı','Şiir','Gokhan Pamukcu']::text[], 8.5, '{"poet":"Gokhan Pamukcu","poet_slug":"gokhan-pamukcu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/noel-agacim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkeolojik Yalnızlık', 'arkeolojik-yalnizlik-gokhan-pamukcu-uzgmz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen eski bir yalnızlığın, 

arkeolojik bulgususun.

Tırnaklarımla kazıyarak buldum seni.

Fakat aldı bir müze, 

şimdi alarmlı camların arkasından bakıyorum sana

dokunamıyorum.', 'Sen eski bir yalnızlığın,  arkeolojik bulgususun. Tırnaklarımla kazıyarak buldum seni. Fakat aldı bir müze,  şimdi alarmlı camların arkasınd...', ARRAY['Türk Edebiyatı','Şiir','Gokhan Pamukcu']::text[], 8.5, '{"poet":"Gokhan Pamukcu","poet_slug":"gokhan-pamukcu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/arkeolojik-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimden Kuşlar Göçüyor', 'yuregimden-kuslar-gocuyor-sair-evamir-3uiz5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her yeni başlangıçta, 

Bir yerden bir yere göç eden kuşlar gibi, 

Yüreğimde yeni başlangıçların heyecanı ve mutluluğu var, 

Ya sonra...

Sonra yüreğimde de sonbahar

Ve yüreğimdeki göçmen kuşları, 

Beni terkediverir birer birer, 

Ve her sonda da, 

Yine yalnız kalakalırım, 

Bir başıma

Ve yeni başlangıçların 

Umudunu yüreğimde taşıyarak.', 'Her yeni başlangıçta,  Bir yerden bir yere göç eden kuşlar gibi,  Yüreğimde yeni başlangıçların heyecanı ve mutluluğu var,  Ya sonra... Sonr...', ARRAY['Türk Edebiyatı','Şiir','Şair Evamir']::text[], 8.5, '{"poet":"Şair Evamir","poet_slug":"sair-evamir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yuregimden-kuslar-gocuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Köpeği', 'sokak-kopegi-erdem-alptekin-bj6x7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sende bilmezsin benim halimi

Nede sorarsın adımı yerimi

Her gece beklerim sokağın başında

Çıkıp bakmazsın kim bu virane

Bir ben birde sokak köpeği

Gezeriz sabaha kadar evinin önünde

Haftalar oldu ne adını bilirim ne sesini

Geçersin yanımdan çevirip bakmazsın yüzünü

Sorarım demezsin adını duyurmazsın sesini

Artık ben vazgeçtim gidiyorum utangaç kız

Sokak köpeğine sor o anlatır derdimi', 'Sende bilmezsin benim halimi Nede sorarsın adımı yerimi Her gece beklerim sokağın başında Çıkıp bakmazsın kim bu virane Bir ben birde sokak ...', ARRAY['Türk Edebiyatı','Şiir','Erdem Alptekin']::text[], 8.5, '{"poet":"Erdem Alptekin","poet_slug":"erdem-alptekin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sokak-kopegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otuzüç Yaş', 'otuzuc-yas-ensar-cevval-zsk0g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''''Bir Eylül''e ithafen''''

Otuz üç yaşındayım

yolun yarısına iki adımlı

otuz üç adımlı basamaktayım

Hz.isa''nın yaşındayım göklere yükselirken

israfil sur''a üflediği zaman 

Arafat da toplanacağımız yaştayım.

Beyaz ve siyahların buluştuğu baş; 

suların ılıdığı yaz gölgesiyim.

Otuzüç yaşındayım

uzun çöllerden kopmuş kum misali

ne yurdumu bilmekteyim, tarif edeyim

ne de geçmişimden bir remiz aklımda

bir dalga gibi kıyılarını dövdüm hayatın

yorulduğum zamanlar oldu, dinlendim

sevdalandığım zamanlar oldu, yoruldum

Kaç yıldız kaydı ben yokken

kaç yıldız uyandı ben uyurken

Otuz üç yaşındayım

başaklar boy verip sararmaya başladı

coşkun sular yavaşlıyor yokuş aşağı inerken

ben sevdim lafzı maziye karıştı.

mantık arıyorsun artık yeni aşklarında

yirmisinde tadına doyum olmayan sevdalar

yağmurlarda bir bakış için erkete bekleyişler

şimdi yerini sessiz buluşmalara bıraktı.

Artık  o coşkun su değilim

çağıl çağıl çağlayan, yaz serinliğinde

artık ıradı sevdalar, gönül bahçemden

bir bağ bozumu, sular coşmaz sinemde

ne çok yürekte yangınlar çıkardım dumansız, 

ne çok yürekler yaktı yüreğimi amansız, 

ne çok eller avuçlarımda eridi, 

ne çok avuçlarda yüreğim.

Geriye dönüp de bir pişmanlık arıyor insan

hükümranlık kadar uzun bu zamanda

sorgular öze dönük; acaba ne noksan? 

söylenmemişler yoğun çizgili, yüreklerde

ince çatlaklar oluşsa da duvarlarında

kurumuş, pıhtılaşmış kızıl tanecikler

artık ilk günkü gibi ağrıtmıyor.

Otuzüç yaşındayım

yaşadığım günlerden kalan tek pişmanlığım

tuttuğum avuçları erken bırakmamdı.

Dolu dolu yaşadığım bir yarı yoldu bıraktığım

Keşke dediğim anlar çok olsa da 

Yaşandı, gitti tüm güzellikleri ile

Otuz üç güzel yaş, yaşanmalı

Her yaşın güzelliği gibi

Önemli olan yaşayabilmek

Yaşadığını sindirebilmektir inandığım.

Anlık duygusallığımda döküldü..affola..', '''''Bir Eylül''e ithafen'''' Otuz üç yaşındayım yolun yarısına iki adımlı otuz üç adımlı basamaktayım Hz.isa''nın yaşındayım göklere yükselirken i...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/otuzuc-yas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aglıyorum', 'agliyorum-cemal-ekren-vv1ex', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'artık o sokak aralarında aglayan çocuk degilim, 

öfkemi  ve yetimliğimi saklayacak degilim

ben seni sevecek kadar büyüdüm artık, 

sevginin emek, 

sana ulaşmanında zor oldugunu biliyom

aglıyorum, 

yoksun  olmayacak kadar uzagımdasın

içimideki nefesimsin 

farkında degilsin gülüm

suçlusun kaçıyorsun

bir elveda demeden

sokak duvarları şahidimizdi

tırnaklarımla yazmıştım seni sevdiğimi, 

tüm derslerden ikmale kaldım

bir tek seni sevmek sınavından geçtim

ve seni sevmek suç oldu

aglıyorum

o sokak arsındaki mavi kızı arıyom

lüle lüle saçları olan kızı

benimle ekmegini bölüşen

yüreğini ortaya koyan

nerdesin ey ay yüzlü kız

aglıyorum

yokluguna

hasretliğimin karnı şişti

tüm haykırışlarım duraklardan geri geldi

hiç bir  yol beni kabul etmedi

biliyorum beni sevdiğini

ama 

yüregin diline hain

adresin neresi? 

ben sana gelirim

yokluğunun kaçıncı demi bilmiyorum

aglıyorum 

sana aglıyorum

ve çocukluk aşkıma aglıyorum

adresimi veriyorum

yanımda yer var

bekliyorum

kara toprakkkk', 'artık o sokak aralarında aglayan çocuk degilim,  öfkemi  ve yetimliğimi saklayacak degilim ben seni sevecek kadar büyüdüm artık,  sevginin e...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/agliyorum-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Nükleer Savaş', 'ask-nukleer-savas-ozcan-ozkan-9j2yd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana son günlerde güven duymaya başladım.

İşte bu kötü! 

Bu tehlikeli! 

Öyle insan insana değil, sevgiliye duyulanı.

Yani o, ürkütüyor artık beni.

Peşinden kıskanmalar, sahiplenmeler, 

İçi içini yemeler gelecek.

Tahta kurdu gibi....

İyisi mi bir şeyler yap.

İhanet et mesela.

Sonra gel anlat bana 

Yine eskisi gibi...

Dost kalalım böylece.

Dostluk ömür boyu.

Aşk nükleer savaş! 

Tekrar yeşermemeli...

(2003)', 'Sana son günlerde güven duymaya başladım. İşte bu kötü!  Bu tehlikeli!  Öyle insan insana değil, sevgiliye duyulanı. Yani o, ürkütüyor artık...', ARRAY['Türk Edebiyatı','Şiir','Özcan Özkan']::text[], 8.5, '{"poet":"Özcan Özkan","poet_slug":"ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ask-nukleer-savas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-i-hsan-aktas-3vl2k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eski evlerden küf kokusu yayılıyor 

Kediler saçakların altına doluşmakta

Öbek öbek leylaklar sırılsıklam

Dağınık saçlarıyla istanbul ıslanıyor

Neyzen bir hiç ugruna kaldırımmlar üstünde

Yaşlanıyor  sokakta deli yari beklerken

göklerden denize iğne yağıyor sanki 

Bir çocuk yüzünü göge kaldırmış', 'Eski evlerden küf kokusu yayılıyor  Kediler saçakların altına doluşmakta Öbek öbek leylaklar sırılsıklam Dağınık saçlarıyla istanbul ıslanıy...', ARRAY['Türk Edebiyatı','Şiir','İhsan Aktaş']::text[], 8.5, '{"poet":"İhsan Aktaş","poet_slug":"i-hsan-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/istanbul-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ortada', 'ortada-huseyin-kaya-jcp95', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'çözülmüyor  kollarım acının bedeninden 

surların önündeyim 

suların arkasında

bana

beni böylece anlatın bir ayet ver

bitti işte ömrümü çelen çalan bu büyü

şimdi

yaralarımı öpüyorum her gece

bitti hiç söylemeden o sonsuz sessiz ezgi

al

nereye istersen savur şimdiden geri

hem yolum hem  yolcuyum 

hem dağım hem dağlanan

hem tufanım hem gemi

anasız kuzu gibi kaldı ömrüm ortada

beni hayata değil

beni kendine bağla', 'çözülmüyor  kollarım acının bedeninden  surların önündeyim  suların arkasında bana beni böylece anlatın bir ayet ver bitti işte ömrümü çelen...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kaya']::text[], 8.5, '{"poet":"Hüseyin Kaya","poet_slug":"huseyin-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ortada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vaktim Olsa', 'vaktim-olsa-bahri-ozaslan-awgun', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ilk Kadinima...

Bir kahve kosesinde olabilirdim, 

			simdi.

Belki, 

	Bilmem kimlerin yaninda..

Basibos serseri de olurdum 

		İstanbul sokaklarinda, 

Ya da....

Ne bileyim iste, 

Aklima geleni yapardim 

Seni dusunmekten, 

Vaktim Olsa....', 'Ilk Kadinima... Bir kahve kosesinde olabilirdim,  			simdi. Belki,  	Bilmem kimlerin yaninda.. Basibos serseri de olurdum  		İstanbul sokakl...', ARRAY['Türk Edebiyatı','Şiir','Bahri Özaslan']::text[], 8.5, '{"poet":"Bahri Özaslan","poet_slug":"bahri-ozaslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vaktim-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanmistim ki..', 'sanmistim-ki-bahri-ozaslan-6ms0t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '‘’Giden bir kadının arkasından ‘’

Sanmıştım ki..

''''Bu yıl benim yeşim bağım kurudu.''''

''''Değmen benim gamlı yaslı gönlüme''''

Türkülerini, 

hep bir ağızdan

hep aynı heyecanla söylediğim kadın..

bir gün..

evet bir gün

dönüp gelecek.

Sanmıştım ki..

İş arasında, , 

veya herhangi bir yerinde hayatın, 

ansızın birisi çıkacak karşıma

ve; 

o ilk günkü gözlerin ve giysilerinle

sen olacaksın.

Sanmıştım ki..

sanki bir oyundu bu.

Uzun bir yolculugun bir yerlerinde, 

         			mola vermek gibi.

Mola bitiminde tekrar devam etmek gibi

Yolculuga

Omuz omuza, yürek yüreğe.

Kalıdıgımız yerden

Sanmıştım ki..

‘denenmiş ve sınanmış ‘’ lıklara

en azından dostlugumuz adına, 

 yazık etmeyiz.

Sanmıştım ki..

Evet hatalarımız olmuştu belki ikimizinde

Ama konuşabilirdik.

Yıllar sonra ortaya çıkan kültür ayrışmasını

Dünyalı kimliğimizle aşabilirdik.

Başka kaynaklardan gidermek yerine

Duygusal açlıgımızı

Bir gün..

Evet bir gün.

Tekrar birbirimize ellerimizi uzatabilir, 

Yüzümüzü dönebilirdik.

Sanmıştım ki..

Acılar olgunlaştırır insanı.

Ve en değerli şeydir dostlugu insanların

Vücudundaki tek olan organını vermek kolay iş mi? 

Öylesine adam gibi.

Sanmıştım ki.

Biz buna kıymayız. 

Sanmıştım ki.

artık bir yerlerde

''''sen''''

bir yerlerde ''''ben''''

değil...

eskisi gibi biz olacaktık..

Sanmıştım ki...', '‘’Giden bir kadının arkasından ‘’ Sanmıştım ki.. ''''Bu yıl benim yeşim bağım kurudu.'''' ''''Değmen benim gamlı yaslı gönlüme'''' Türkülerini,  hep...', ARRAY['Türk Edebiyatı','Şiir','Bahri Özaslan']::text[], 8.5, '{"poet":"Bahri Özaslan","poet_slug":"bahri-ozaslan","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/sanmistim-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kizima..', 'kizima-bahri-ozaslan-u330e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eylem Ezgi''ye   

Sana, 

Hep siradisiligi ogretmeye calistik

						                                      yavrum, 

Hep savundugumuz

	o evrensel ilkeleri.

Dunyali olabilmeyi ogretmeye calistik sana, 

En az, 

İsimsiz bir koyundeki cocuk kadar Anadolu'' nun

Ugandali, Etopyali cocugu dusunmeye ogretmeye					calistik..	

Hic hafife almadik seni

		kucuk dost...

O ilk kelimeyi soylemeye

Ve  anlamaya dair mimiklerin belirginlesmeye

                       basladigi andan itibaren

                       yuzunde o ilk kelimeyi

Hayati ogretmeye calistik sana, 

Calismayi, 

            Dinlenmeyi, 

                        Aglamayi, 

                                   Gulmeyi....

Ve....

Merhameti, 

     Mantigi oldugu kadar, 

Camin neden bugulandigini, 

Zaman zaman ayrilik, 

                               Neden...

Radyatordeki sicak suyu, 

Veya...

       Hep sorar ya kucukler

       Mesela nereden geldigini

Dunyanin en ciddi isini

       Ipek bir hali dokumanin ozeni ile, 

                                                    anlattik sana

''''Butun dunya cocuklari kardesimdir ''''

	Diyecek kadar cocuklari sevmeyi, 

''''En guzel cocuk dogdu ''''

	Diyecek kadar kendini sevmeyi, 

''''Yasamak ........''''

	Diye basladiktan sonra, 

	Tamamlayacak kadar buyuk sairi, 

Ve; 

'''' MAVİ GÖZLÜ DEVİ '''' Sevmeyi ogrettik sana.

Goruyorum ki bugun, 

	Epeyce mutlu ve bahtiyarim

	'''' Maya tuttu '''' diyorum.

Bazen de bir garip huzun, 

Acaba erken mi buyudu diyorum

         Bizim kucuk dost …..', 'Eylem Ezgi''ye    Sana,  Hep siradisiligi ogretmeye calistik 						                                      yavrum,  Hep savundugumuz 	o evrense...', ARRAY['Türk Edebiyatı','Şiir','Bahri Özaslan']::text[], 8.5, '{"poet":"Bahri Özaslan","poet_slug":"bahri-ozaslan","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/kizima-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşa Geçirme', 'bosa-gecirme-halil-soyuer-un8p1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkın gerçeğini yaşa ve yaşat, 

Yalancı sevgiyi başa geçirme.

Yeniden dünyaya gelme şansın yok, 

Yalanla vaktini boşa geçirme.

İnsan da bu kavga ve dövüş niçin? 

Söylemek mi gerek ders almak için, 

Yanına ömründen gün çalmak için, 

Gelenle vaktini boşa geçirme.

Gözünde halıysa evdeki hasır, 

Duygunu hiç kimse alamaz esir, 

Her gün her sözünde iki üç kusur, 

Bulanla vaktini boşa geçirme.

Çekinme yollardan tozuna bakıp, 

Yürü mutluluğa izine bakıp, 

Her an yalancıktan yüzüne bakıp, 

Gülenle vaktini boşa geçirme.

Eğer gerçek sevgi varsa özünde, 

Her bakışta güller açar yüzünde, 

Küçüle küçüle artık gözünde, 

Ölenle vaktini boşa geçirme.', 'Aşkın gerçeğini yaşa ve yaşat,  Yalancı sevgiyi başa geçirme. Yeniden dünyaya gelme şansın yok,  Yalanla vaktini boşa geçirme. İnsan da bu k...', ARRAY['Türk Edebiyatı','Şiir','Halil Soyuer']::text[], 8.5, '{"poet":"Halil Soyuer","poet_slug":"halil-soyuer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bosa-gecirme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağ Köyleri', 'dag-koyleri-halil-soyuer-s7iv6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bizim memleketin dağ köylerinde, 

Bataklık bilmezler, sazlık bilmezler.

Her taraf ormandır, çamlık, meşelik, 

Harman yeri hariç, düzlük bilmezler.

Ağaç diplerinde doğmuştur çoğu, 

Çok iyi bilirler tepeyi dağı, 

Elleri tutmamış viski bardağı, 

Sahillerde yazlık, mazlık bilmezler.

Dağlara öğüttür rüzgarın hızı, 

Yirmi kilo çeker bir aylık kuzu, 

Kışın derelerde görülür buzu, 

Dolap, molap, buzluk muzluk bilmezler.

Çiçekleri süsler yazın kırları, 

Bir başka güzledir kışın karları, 

Doksana diz vuran ihtiyarları, 

Ağızda takma diş, gözlük bilmezler.

Köpekleri havlar köye girişte, 

Elde tahta kaşık, bulgur erişte, 

Haktan ayrılmaz alış verişte, 

Hilekarlık, düzenbazlık bilmezler.

Hoş görürler başa gelen halleri, 

Türküden bilirler gurbet elleri, 

Ne deseler anlaşılır dilleri, 

Kitap mitap, sözlük mözlük bilmezler.', 'Bizim memleketin dağ köylerinde,  Bataklık bilmezler, sazlık bilmezler. Her taraf ormandır, çamlık, meşelik,  Harman yeri hariç, düzlük bilm...', ARRAY['Türk Edebiyatı','Şiir','Halil Soyuer']::text[], 8.5, '{"poet":"Halil Soyuer","poet_slug":"halil-soyuer","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dag-koyleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle', 'seninle-halil-soyuer-c2fq2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hasetten çatlasın çekemeyenler

Nerde görürlerse beni seninle

Bize yıllar çoktan açmış kucağı

Geçirsem haftayı günü seninle

Sevgin bende bir ebedi barıştır

Hayat senin ile sana varıştır

Her geceni, her geceme karıştır

Hep böyle göreyim seni seninle

Evlat başı benim, anne dizi sen

Böyle bilmelisin artık bizi sen

Yüz’ü ben alayım dokuz yüz’ü sen

Böyle paylaşalım bin’i seninle

Biz aşka en güzel manayı versek

Versek de aşktaki doruğa ersek

Biz ipek yaparız eğer istersek

Koyundan kırpılan yünü seninle

Gözle görülmez ki izler derinde

Bir bak her şeyimiz yerli yerinde

Kayıt var ecelin not defterinde

Ömrün gelemeyecek sonu seninle…', 'Hasetten çatlasın çekemeyenler Nerde görürlerse beni seninle Bize yıllar çoktan açmış kucağı Geçirsem haftayı günü seninle Sevgin bende bir ...', ARRAY['Türk Edebiyatı','Şiir','Halil Soyuer']::text[], 8.5, '{"poet":"Halil Soyuer","poet_slug":"halil-soyuer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seninle-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesleniş', 'seslenis-halil-soyuer-iwyt7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gönül şenlikleri senle başlamış

Senle mana bulmuş naz bu dünyada

Zeytin gözleriyle konuşsun diye

Bir sana verilmiş söz bu dünyada

Gönlün engindedir gözün yukarda

Hal mi kalır seni gören bekarda

Benim gibi seven tek- tük çıkar da

Senin gibi fettan az bu dünyada

Göklerden mi indin, soyun nereden? 

Desti doldurursun kuru dereden

Geçtiği her yanı yerle bir eden

Canlı afet misin kız bu dünyada

Baharı bekler ya çiçek dallarda

Tam işte öyleyim, gözüm yollarda

Kaybolup gidecek herkes yıllarda

Bir senden kalacak iz bu dünyada

Sevgiyi gönlüme sen oldun eken

Gül diken olmadı, gül oldu diken

Cihan karşı gelse canım sağ iken

Kondurmam üstüne toz bu dünyada', 'Gönül şenlikleri senle başlamış Senle mana bulmuş naz bu dünyada Zeytin gözleriyle konuşsun diye Bir sana verilmiş söz bu dünyada Gönlün eng...', ARRAY['Türk Edebiyatı','Şiir','Halil Soyuer']::text[], 8.5, '{"poet":"Halil Soyuer","poet_slug":"halil-soyuer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seslenis-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölette Durgun Bi''sudur Hayat', 'golette-durgun-bi-sudur-hayat-bir-mim-kemal-ertugrul-aujgz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '________________Sevgisi herşeyden üstündür kiminin

________________Kiminin yoktur sevdadan haberi......

İşin esası; 

Sevdalarca coşması

Ve kavuşmasıdır denizlere

__________koşarak ırmakların

Ne ırmaklar akar böyle

Ne yaşanabilir böylesi sevdalar

Setler dikilir suların önüne

Engeller çekilir hep yaşamın cevherine

Artık; 

Gölette durgun bi’sudur hayat

Ve sessiz  direnişidir sevdanın...

Kurur gün be gün gönülde

Babil’in Asma Bahçeleri...

25.06.1995 / 21:35 Ev', '________________Sevgisi herşeyden üstündür kiminin ________________Kiminin yoktur sevdadan haberi...... İşin esası;  Sevdalarca coşması Ve k...', ARRAY['Türk Edebiyatı','Şiir','Bir Mim Kemal Ertuğrul']::text[], 8.5, '{"poet":"Bir Mim Kemal Ertuğrul","poet_slug":"bir-mim-kemal-ertugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/golette-durgun-bi-sudur-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tenhâlığın Kuyu Başı', 'tenh-ligin-kuyu-basi-naime-erlacin-a4ebc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ıssızlığında yaşamın

gecenin yalnızlığında 

insan sürgün 

tek başına 

görmez dünyayı gözü

fışkırır sürgünler

ama deli 

ama kırgın

düşer 

sürgünün kucağına

tek başına çekilir yük

çıkılmaz içinden çilenin

taş olur, ağırlaşır 

hem tutsak olur

hem gardiyan

hançeriyle vurulur 

cehenneminde insan

tenhâlığın kuyu başında aşk

iki kişilik 

ve tek başına 

(01 Temmuz 2003)', 'ıssızlığında yaşamın gecenin yalnızlığında  insan sürgün  tek başına  görmez dünyayı gözü fışkırır sürgünler ama deli  ama kırgın düşer  sür...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tenhaligin-kuyu-basi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Temmuz ÇiftÖlüm TekDoğum', 'bir-temmuz-ciftolum-tekdogum-sule-aydemir-6qoc5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'güneşe teri yapışan 

sıcak ipekten gözlerim

tene değen bir ses

hazzın içinden

bir İstanbul o 

ciğerime 

çocukluğumda menenjitle yerleşen

ve aşk biz olduğumuzda 

çift yürek tek beden 

öldüğüm gün benim

bir temmuz

bir İstanbul gibi öptüğü gün

İstanbul gibi dinlediği her gün

benim yüreğimle dinlediğim

ve özlem büyüdükce

öldüğün gün senin

bir temmuz

bulduğumuz gün birbirimizi

ve aşkın ruhuna güvendiğimiz 

yüreğimiz avuçlarımızda kavradığımız 

çığlık çığlığa ter içinde sevdamızı haykırdığımız

doğduğumuz gün bizim 

bir temmuz

ölümüne diyerek sarmaşıklaşıp sarıldığımız

içimizi içimizden söküp yüreklerimize bıraktığımız

bir çok engele gülümseyerek söz verdiğimiz

doğduğumuz gün bizim

bir temmuz

aşk ki bu 

ölümüne mühür vurduğumuz 

aşkımıza efendi olduğumuz

nikah verip gönül koyduğumuz

iyiki varsın varız

doğum günümüz 

hoş geldin

bir temmuz

''bir temmuz 

ben sen ölüp 

gün bu gün 

çift beden ölüp tek doğduğumuz''', 'güneşe teri yapışan  sıcak ipekten gözlerim tene değen bir ses hazzın içinden bir İstanbul o  ciğerime  çocukluğumda menenjitle yerleşen ve ...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bir-temmuz-ciftolum-tekdogum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilsem ki Döneceksin', 'bilsem-ki-doneceksin-gunay-aktag-7shr2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Günlerdir aklımda sen, dolaşıyorum 

Ne ya baksam, hayalin karşılıyor beni

Garip bir düşünce sarmış beynimi kemiriyor, kemiriyor 

Ne yapsam ne etsem kurtulamıyorum..

Aklımda sen, fikrimde sen, 

Kalbimde sen

Deli oluyorum

Bilsem ki  döneceksin  beklemem seni

Bilsem ki  özlemişsin  özlemem seni

Bilsem ki  aklında  ben  düşümmem seni

Bilsem ki  seviyorsun  daha çok  sevmem mi seni

Aklımda sen, fikrimde sen, kalbimde sen

Seviyorum seni, seviyorum seni', 'Günlerdir aklımda sen, dolaşıyorum  Ne ya baksam, hayalin karşılıyor beni Garip bir düşünce sarmış beynimi kemiriyor, kemiriyor  Ne yapsam n...', ARRAY['Türk Edebiyatı','Şiir','Günay Aktağ']::text[], 8.5, '{"poet":"Günay Aktağ","poet_slug":"gunay-aktag","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bilsem-ki-doneceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğlum', 'oglum-erdogan-oner-qut8c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu garip başımdan çok şeyler geçti

Paslanmaz çeliktim kırıldım oğlum

Oğlum elimizden kuş gibi uçtu

Kötü kaderime darıldım oğlum

           Telefonda bir sen bana gel dedi

           Çok fazla üzülme sakin ol dedi

           Hastande durumunu bil dedi

           Hastane morgundan soruldum oğlum

Köye haber yollan oğlum gelmiyor

Yüzüme bakıpta artık gülmüyor

Yaptığım adaklar yerin bulmuyor

Acılar içine sürüldüm oğlum

           İş dönüşü beni yolda beklerdin

           İki elma olsa birin saklardın

           Boynuma sarılıp beni koklardın

           Evde elbisene sarılsım oğlum

Oğlum elimizde büyüdü nazlı

Şu yollar gözüme göründü tozlu

Üç gün yol yürüsem giderdim hızlı

Bir saat içinde yoruldum oğlum

         Kapımın önünden yol gelir geçer

         Başlarımdan türlü hal gelir geçer

         Nere baksam bir bulanık sel gelir geçer

         Herkes zannediyor duruldum oğlum

Erdoğanım buda geldi başına

Oğlum doyamadı küçük yaşına

Antep  gıran girsin pirket taşına 

Bende can evimden vuruldum oğlum', 'Şu garip başımdan çok şeyler geçti Paslanmaz çeliktim kırıldım oğlum Oğlum elimizden kuş gibi uçtu Kötü kaderime darıldım oğlum            T...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Öner']::text[], 8.5, '{"poet":"Erdoğan Öner","poet_slug":"erdogan-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/oglum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elleme elleme', 'elleme-elleme-mehmet-ali-kepez-697xq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin bu yaraya faydan dokunmaz

	Elleme elleme bırak elleme

	İkram eden zahmetinde çekinmez

	Elleme elleme bırak elleme

	Bırakki acımda kavrulup yanam

	Bırakki ben seni eski dost sanam

	Usul böyle diye bir kuru selem 

	Yollama yollama bırak yollama

	Yılan bile su içerken çatmazmış

	Sevdalılar tövbe''sini tutmazmış

	Her bahçede làle, sümbül bitmezmiş

	Belleme, belleme bırak belleme

	İçinda saklama kaldır kapağı

	Dost dediğin deyiştirmez kabuğu

	Sürüsüne kurt getiren köpeği

	Yallama, yallama bırak yallama', 'Senin bu yaraya faydan dokunmaz 	Elleme elleme bırak elleme 	İkram eden zahmetinde çekinmez 	Elleme elleme bırak elleme 	Bırakki acımda kavr...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/elleme-elleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerede', 'nerede-sair-eroltr-vs7ut', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ara  bir hanim arkadaşım vardı. 

Kasvetli günlerimde beni sevgi ile sarar

Cilveler yapardı

 Öyle güzel olurdu ki: 

Birden kayboldu

 Nerede ne yapiyor bilmiyorum Ama çok özlüyorum. 

Zor öylesini bulmak 

 cilvelerinde kaybolmak', 'Bir ara  bir hanim arkadaşım vardı.  Kasvetli günlerimde beni sevgi ile sarar Cilveler yapardı  Öyle güzel olurdu ki:  Birden kayboldu  Nere...', ARRAY['Türk Edebiyatı','Şiir','Şair Eroltr']::text[], 8.5, '{"poet":"Şair Eroltr","poet_slug":"sair-eroltr","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nerede-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerde kaldı', 'nerde-kaldi-mehmet-ali-kepez-s01nw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dostluk dilde kaldı gönülde çıkar

	Kime sarıldıysam göhsümü yakar

	Birazcık gam etsem sevdiğim bıkar

	Şimdiki sevdalar düşe benziyor

	Ne türküler kaldı, ne de ninniler

	Küsüp gitmiş doslar kalmış kinliler

	Top peşine koşan delikanlıar

	Verdiğin kavgalar boşa benziyor

	Hani koçyiğide yanan destanlar

	Hani alyazmalı güllù fistanlar

	Onurunu ucun, ucun satanlar

	Şeref''te işiniz yaşa benziyor

	Zenginler hep zengin fakir se fakir

	Davalı davasın nası bırakır

	Aç, susuz insanlar tutmuyor fikir

	Sanarsın kör, sağır taşa benziyor', 'Dostluk dilde kaldı gönülde çıkar 	Kime sarıldıysam göhsümü yakar 	Birazcık gam etsem sevdiğim bıkar 	Şimdiki sevdalar düşe benziyor 	Ne tür...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nerde-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçan günü vurmalımı', 'kacan-gunu-vurmalimi-mehmet-ali-kepez-xg5zb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vuran vurmuş şu Dünya''nın çarkına

	ömür geçti varamadım farkına

	Ata binip yari atıp terkine

	şu karşi dağları  aşmalımola

	Gece olur bir koyakta durmalı

	çalı  çırpılarla ocak kurmalı

	Silah alıp kaçan gùnù vurmalı

	Zamanın peşinde koşmalımola', 'Vuran vurmuş şu Dünya''nın çarkına 	ömür geçti varamadım farkına 	Ata binip yari atıp terkine 	şu karşi dağları  aşmalımola 	Gece olur bir ko...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kacan-gunu-vurmalimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dikenlerin Batar Diye...', 'dikenlerin-batar-diye-suleyman-saylan-nhqky', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'DİKENLERİN  BATAR  DİYE...

Dikenlerin batar diye

Koklayamam sanma sakın...

Yılda bir kez açsan bile, 

Sen gönlümde solacaksın.

Düş dünyamın sevgilisi, 

Vazgeçilmez aşk perisi...

Denizlere akar gibi

Yüreğime dolacaksın.

Baş döndüren kokun ile

Sineceksin benliğime...

Sen göğsünü gere gere, 

Beni esir alacaksın.

Yüreğimde kök salacak, 

Sevdam ile sulanacak, 

Bin bir renkli gül açacak...

Yediveren olacaksın.

Dikenlerin batar diye

Koklayamam sanma sakın...

Yılda bir kez açsan bile, 

Sen gönlümde solacaksın.

Süleyman SAYLAN

(Ankara,03.01.2002, Saat: 01.07) 

(Şarkı sözü olarak yazılmış ve bestelenmiştir.)', 'DİKENLERİN  BATAR  DİYE... Dikenlerin batar diye Koklayamam sanma sakın... Yılda bir kez açsan bile,  Sen gönlümde solacaksın. Düş dünyamın ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dikenlerin-batar-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirmisin', 'bilirmisin-cemal-ekren-lm7pi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey sancılı yüreğimin ev sahibi

ey kanayan yaram

bilirmisin? 

kaç gece, kaç sene

senin için keskin ve yüksek dağların karlarından, 

çay demledim, 

bilirmisin? 

günlerce yokluguna nöbet tuttum

aç kaldım uyumadım

dudagımın kıyısındaki filizlenen

sevgi tohumunu gözyaşlarımla besledim

ölmek istedim

toprak kabul etmedi

ve sen gelmedin

senin için yaşadıgımı  bilmedin

dagın başındaki çayın demi yenilendi

gözyaşalarım paslanmadı

ve şimdi, 

yoklugunun

açlıgını tadıyorum

tenim tenine hasret

üşüyorum..

çay içermisin? 

türkü severmsin? 

beni severmsin? 

anladım gelmiyeceksin

hiç olmazsa sıcaklığını gönder ısınayım

o zamam bırak dagbaşında agız tadıyla çayımı içeyim de

öleyim, 

dudagımda senin isminle

mavi kız', 'Ey sancılı yüreğimin ev sahibi ey kanayan yaram bilirmisin?  kaç gece, kaç sene senin için keskin ve yüksek dağların karlarından,  çay demle...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bilirmisin-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Oldum', 'sair-oldum-bekir-mutlu-gokcesu-fmma2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mevsimleri geçip geldim sana.

Yılları, yolları koşup

kendimden kaçıp geldim sana.

Sende tattıklarımı,

bana yaşattıklarını

alıp geldim sana.

Kimi beni benden ettin

çoğu beni bana verdin.

Tebessümlerinde dindi rüzgarlarım,

bakışında parladı yangınlarım,

ben senle yeniden doğdum,

seni severken yeniden yoğruldum

galiba ben senle tıpkı ben oldum.

Şiirsi fakat şiirsiz zamanlarım vardı

şiire zamanlarım çok dardı,

sen bende şiir

ben senle şair oldum.', 'Mevsimleri geçip geldim sana. Yılları, yolları koşup kendimden kaçıp geldim sana. Sende tattıklarımı, bana yaşattıklarını alıp geldim sana. ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sair-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahra nın yağmura doyduğu zaman', 'sahra-nin-yagmura-doydugu-zaman-mehmet-ali-kepez-htnjt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sahranın yağmura doyduğu zaman

	Ben seni gönlümde silerim belki

	Yüreğin ahımı duyduğu zaman

	Derdimi unutur gülerim belki

	Solmadın gönlümde gülün adıysan

	Doymadım acına aşkın tadıysan

	Sevdama kıydın yar cana da kıysan

	Yine de mutluluk dilerim bilki', 'Sahranın yağmura doyduğu zaman 	Ben seni gönlümde silerim belki 	Yüreğin ahımı duyduğu zaman 	Derdimi unutur gülerim belki 	Solmadın gönlümd...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sahra-nin-yagmura-doydugu-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağladım Her Seferinde', 'agladim-her-seferinde-mehmet-bor-b0bvs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen gittin.

Uzaklaştın ya kendince, 

sanma ki bu gönül uslandı.

Yorulmadı, bıkmadı biliyormusun.

Ne mevsimlere aldırdı.

Ne yağmurlara, ne çamurlara.

İşe  de yaradı yağmurlar..

Kimse anlamıyordu

evinin karşısında

Ağacın altında beklerken.

Kahvehaneye gitme bahanesiyle, 

hep sana koştum.

Her gece '' iyi geceler '' dedim.

Işıkların sönerken, 

duyuramadım.

İçime huzur doluyordu, 

Her gece orada beklerken.

Nasıl ki sönünce ışıklar..

Hep hüzün doldu yüreğime.

Bilmelisin ki; 

Ağladım her seferinde, 

eve dönerken.

26.06.2003

Mehmet BOR', 'Sen gittin. Uzaklaştın ya kendince,  sanma ki bu gönül uslandı. Yorulmadı, bıkmadı biliyormusun. Ne mevsimlere aldırdı. Ne yağmurlara, ne ça...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bor']::text[], 8.5, '{"poet":"Mehmet Bor","poet_slug":"mehmet-bor","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/agladim-her-seferinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin', 'nerdesin-mehmet-ali-kepez-6ttbp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçimi yaktı kavurdu

	Lapa yağan kar nerdesin

	Beni mecnun''a çevirdi

	Ey vijdansız yar nerdesin

	Bir görsem; dönüp gelede

	Basım bin türlü belada

	Gurbette kalmak helede

	Mapuslukta zor nerdesin

	Yar başını alıp gittin

	Yürğimi çalıp gittin

	Kaş, göz arasında yittin

	Hayal''misin dur nerdesin

	Aradım gündüz geceli

	Ömrümün gitti niceli

	Canım beklemez eceli

	Gel hiçbari vur nerdesin

	İslendi çıram sönüyor

	Dünya boşuna dönüyor

	Deşildi yaram kanıyor

	İnsaf eyle sar nerdesin

	Bir Kepezi sor nerdesin', 'İçimi yaktı kavurdu 	Lapa yağan kar nerdesin 	Beni mecnun''a çevirdi 	Ey vijdansız yar nerdesin 	Bir görsem; dönüp gelede 	Basım bin türlü be...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nerdesin-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yatmıyor gönùl', 'yatmiyor-gon-l-mehmet-ali-kepez-sjtij', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaç gùndùr ayakta deli divane

	Bir tùrlù uzanıp yatmıyor gönùl

	Karaya bùrùnmùs yastadır, yasta

	Ne desem sözùmù tutmuyor gönùl

	Bir yanı hapiste yanar bir yanı

	Bir yanı  iskence kanar biryanı

	Bir yanı sıcakyır donar biryanı

	Bugùnler dengeli atmı yor dönùl

	Sanarsın bağlanmış aıinmış esir

	İlaç ta veriyom etmiyor tesir

	Caımın suçu ne etmedik kusur 

	Feryadın, ağıdin bitmiyor gönùl

	Sonbahar gelipte gùller solunca

	Doğanın kulağı duymaz ölùnce

	Hayatın üstüne gölge düşünce

	Ne dùnya ne gùnes batmiyor gönùl', 'Kaç gùndùr ayakta deli divane 	Bir tùrlù uzanıp yatmıyor gönùl 	Karaya bùrùnmùs yastadır, yasta 	Ne desem sözùmù tutmuyor gönùl 	Bir yanı ha...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yatmiyor-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleket Toprağı', 'memleket-topragi-mehmet-ali-kepez-muh53', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kendimi kafeste kuşa benzettim

	Gurbetlik ruhumu sıkıyor artık

	Baharken ömrümü sattım güz ettim

	Mevsimler seyrinde çıkıyor artık

	Bir barakam olsun kara meşeden

	Tavanı naylonlu camı şişeden

	Dört köşe olurum inan neşeden

	Metropol şehirler kokuyor artık					

	Hasret kaldım vadi deki nehire

	Aldığım her nefes benzer zehire

	Ne Paris, ne Londra ne de Kahire

	Bozkırlar içimi yakıyor artık

	Yüreğini koru Kepez sımsıcak

	Tezekle ısınsın üç taşlı ocak

	Sıla hasretiyle sonun nolacak

	Memleket toprağı çekiyor artık', 'Kendimi kafeste kuşa benzettim 	Gurbetlik ruhumu sıkıyor artık 	Baharken ömrümü sattım güz ettim 	Mevsimler seyrinde çıkıyor artık 	Bir bara...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/memleket-topragi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskanmaktan Beni Sevemedin ki...', 'kiskanmaktan-beni-sevemedin-ki-suleyman-saylan-u7ea1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'KISKANMAKTAN  BENİ  SEVEMEDİN  Kİ...

Dünyanın yükünü çekmeye geldin; 

Dertler tükenmez hiç, bilemedin ki...

Ben seni yürekten sevmek istedim, 

Kıskanmaktan beni sevemedin ki...

Armudun sapı var, üzümün çöpü

Diyerek günlerin oldu dert küpü, 

Üstelik, şüpheler sardı ömrünü...

Kıskanmaktan beni sevemedin ki...

Bakarlar saçımın bir tek teline, 

Kıskanır da üzersin diye; 

Sevmemeye yemin ettim bin kerre...

Kıskanmaktan beni sevemedin ki...

Olmuyor sevgisiz, sensiz olmuyor; 

Damarlarım sustu, sanki vurmuyor.

Kıskansan da, gönlüm sensiz durmuyor.

Kıskanmaktan beni sevemedin ki...

Süleyman SAYLAN

(Ankara,05.08.1993, Saat: 13.05)     (Şarkı sözü olabilir.)', 'KISKANMAKTAN  BENİ  SEVEMEDİN  Kİ... Dünyanın yükünü çekmeye geldin;  Dertler tükenmez hiç, bilemedin ki... Ben seni yürekten sevmek istedim...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kiskanmaktan-beni-sevemedin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altın İşçisi', 'altin-i-scisi-nihat-tasdemir-igv9n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ALTIN İŞÇİSİ

Altın madeninden çıkmış, bir işçi gibiyim; 

Yüzümde buruk bir tebessüm, 

İçimde derin bir sızı var...

Ne o altın işçinin, 

Ne de sen benimsin! ..

Yorgun Yalnızlıklar isimli kitabımdan', 'ALTIN İŞÇİSİ Altın madeninden çıkmış, bir işçi gibiyim;  Yüzümde buruk bir tebessüm,  İçimde derin bir sızı var... Ne o altın işçinin,  Ne d...', ARRAY['Türk Edebiyatı','Şiir','Nihat Taşdemir']::text[], 8.5, '{"poet":"Nihat Taşdemir","poet_slug":"nihat-tasdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/altin-iscisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanmazlar...', 'utanmazlar-suleyman-saylan-mssbr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'UTANMAZLAR...

Sıkıntılarını biriktiriyor yüreğim

Karanlık geceler gibi; 

En karasından, en okkalısından...

Yağmur öncelerinin

Sıkıntılı bulutları boğazlıyor

Sanki

Yüreğimi.

Son aydınlıklar

Göç ediyor başka diyarlara, 

Göçmen kuşların kanatlarında.

Dalıp dalıp gidiyor gözlerim

Boşluklara, 

Bir çoban ateşinin özlemiyle...

Ateş böcekleri bile terkediyor

Yüreğimin evrenini, 

Tutsak bırakıyor beni

Karanlıklara.

Sık somak ediliyorum

Ağlamaklı...

Ne kaldı yaşamda

Ya da ne bıraktılar? ..

Değersizlik değer oldu, 

Erdemsizlik erdem.

Utanmak neydi unuttular, 

Utanmazlar...

Süleyman SAYLAN

(Ankara,12.08.2001, Saat: 23.02)', 'UTANMAZLAR... Sıkıntılarını biriktiriyor yüreğim Karanlık geceler gibi;  En karasından, en okkalısından... Yağmur öncelerinin Sıkıntılı bulu...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/utanmazlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Gidişin', 'son-gidisin-nihat-tasdemir-pvkz8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'SON GİDİŞİN

	

Sensiz kalan ömrümün ilk günü...

Biliyor musun? Güneş bile geç doğdu bugün.

belli ki o benden de moralsiz.

kuşlar konmamışlar bugün pencereme

yokluğunu mu sezdiler ne? 

O hantal kedin de görünmüyor ortalıkta, 

seni arıyor olmasın sakın sokaklarda? 

Halbuki,  bugün iyi davranacaktım ona

ilk defa da olsa kucağıma alıp sevecektim onu

ve tüylerine sinen kokunu, 

ciğerlerime kadar çekecektim bugün

hatta,  kendi ellerimle besleyecektim onu.

Daha ilk günün  bu kadar zor geçeceğini

bilmezdim...

Bilmezdim daha gün yarılanmadan 

ömrümün yarılanacağını...

Gitmen değil de, gitmen değil de bu gidişinin 

son gidişin olması koyuyor bana

bir daha dönmeyeceğin düşüncesi kemiriyor beynimi

umarım tüm bunlar lanet bir oyundur, 

umarım sınıyorsundur beni.

Haydi kapıyı açacağım, 

çık artık saklandığın yerden 

haydi gözlerimi yumacağım uzat artık ellerini 

biliyor musun biliyor musun daha şimdiden özledim

bağırarak ta olsa bana seslenişini.

Birden zilin sesiyle irkildim

gelen kapıcı kazım efendi

ekmeği gazeteyi ve senin vazgeçemediğin, 

o haftalık dergini getirmiş.

Buruk bir sesle seni sordu:

“Hayırdır, yenge uykuya mı daldı? 

her zaman kapıyı o açardı.”

Sormaz olaydı, 

gözlerim sulandı, 

içim  sızladı.

Sadece başımı sallayabildim.

Ve o da anladı ebedi bir uykuya gittiğini, 

Ve bir daha asla dönmeyeceğini...	

Yorgun Yalnızlıklar isimli kitabımdan', 'SON GİDİŞİN 	 Sensiz kalan ömrümün ilk günü... Biliyor musun? Güneş bile geç doğdu bugün. belli ki o benden de moralsiz. kuşlar konmamışlar ...', ARRAY['Türk Edebiyatı','Şiir','Nihat Taşdemir']::text[], 8.5, '{"poet":"Nihat Taşdemir","poet_slug":"nihat-tasdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/son-gidisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanılacak...', 'utanilacak-suleyman-saylan-5ja85', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'UTANILACAK...

Gözlerimin içine bak; 

Utanma, 

Söyle...

Sevgi

Utanılacak bir şey

Değildir.

Süleyman SAYLAN

(Ankara,09.08.2001, Saat: 00.50)', 'UTANILACAK... Gözlerimin içine bak;  Utanma,  Söyle... Sevgi Utanılacak bir şey Değildir. Süleyman SAYLAN (Ankara,09.08.2001, Saat: 00.50)...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/utanilacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz Geçirememek', 'soz-gecirememek-suleyman-saylan-ctsk6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SÖZ  GEÇİREMEMEK

Hissetmek var ya

Hissetmek; 

Taa derinlerde, 

Belirsiz bir yerde, 

Yüreğinde, 

Yüreğinin inlerinde...

Aşk odur işte, 

Yüreğine söz geçirememek...

Süleyman SAYLAN

(Ankara,09.08.2001, Saat: 00.42)', 'SÖZ  GEÇİREMEMEK Hissetmek var ya Hissetmek;  Taa derinlerde,  Belirsiz bir yerde,  Yüreğinde,  Yüreğinin inlerinde... Aşk odur işte,  Yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/soz-gecirememek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür Boyu', 'omur-boyu-suleyman-saylan-e3iu2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ÖMÜR  BOYU

Bir gece sürecek bir aşk

Aşk değildir...

Aşk dediğin

Ömür boyu sürmelidir.

Var mısın benimle, 

Bir ömür sürecek

Aşka? ! ..

.

Süleyman SAYLAN

(Ankara,09.08.2001, Saat: 00.33)', 'ÖMÜR  BOYU Bir gece sürecek bir aşk Aşk değildir... Aşk dediğin Ömür boyu sürmelidir. Var mısın benimle,  Bir ömür sürecek Aşka? ! .. . Süle...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/omur-boyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Gün''ü Doğurur', 'gun-gun-u-dogurur-arzu-dincer-3it26', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün veda ederken sana, 

Kırık hatıralar bırakmamalı...

Çiçeksiz yüzler...

Selamsız selamlar....

Parmak uçlarınla değil

Çelik pençelerle yakalayacaksın

Hayatın sınırsız güzelliğini

Renk renk banknotlar değil

Hayatla arana giren

Unuttun mu 

Ananla arandaki 

Pamuktan ince bağı...

Asırları aşıp 

Sana gelen genleri...

Rüzgar kürüyorsa saçlarını

Bırak buğday tarlalarını

Savrulsun dalga dalga...

Uzat avuçlarını...

Parmaklarından geçen, 

Hayatın ta kendisi!', 'Gün veda ederken sana,  Kırık hatıralar bırakmamalı... Çiçeksiz yüzler... Selamsız selamlar.... Parmak uçlarınla değil Çelik pençelerle yaka...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gun-gun-u-dogurur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işıl''a', 'isil-a-ayhan-cakir-brz6r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir değerdin gözümde, 

Bunu hiç anlamasan bile, hissettirmesemde

Değerdin ömrüme.

Hatalarımla kabul etmeni isterdim, 

Zaman geçti ki sonra farkettim...

Senin gözünde, değerdim..değmezdim.

İkileme iten neydi seni bilmiyorum, 

Sendenmi kaynaklanmıştı, yoksa bendenmi? 

Yazık..Hiçmi kalmadı duygu özünde? 

Üzüldüğünü bile bile, üstelik seve seve..

Nedensiz bir ayrılış bu.

Gereksiz bir saplantı bu..

Ama pesettim sonunda...

Özlemlerimle yaşatacağım seni..

Tam istediğin gibi.', 'Bir değerdin gözümde,  Bunu hiç anlamasan bile, hissettirmesemde Değerdin ömrüme. Hatalarımla kabul etmeni isterdim,  Zaman geçti ki sonra f...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Çakır']::text[], 8.5, '{"poet":"Ayhan Çakır","poet_slug":"ayhan-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/isil-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mi-Mı eki...', 'mi-mi-eki-hakan-komurcu-f3qdm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Alinin parası hep vardı

mi-mı ekiyse hep atrı yazılmalıydı

biz büyümeye hevesliydik

tamlamalar girdi hayatımıza

hep tamlanan olduk

tamlayamadık hiç

tamamlayamadık bizi, kendimizi

suyun azizliğini

suyun formülünden çok sonraları tanıdık, 

çok sonraları öğrendik paylaşamayı

üslü ifadelewrden sonra

oysa biz yüklemden hemen önce gelmek

ve cümlede anlatılmak istenen olmak isterdik 

alinin parasını bilmek bile istemezken

onun alışverişlerini takip edip

cebinin muhasebesini yapmak 

bu kadar önemlimiydi? 

mi mı eki mutlaka ayrımı yazılmalıydı..

sonra büyüdük

ikinci dereceden çok bilinmeyenli denklemler arasında

bedenimizle orantısız

bir benlik sıkıştırıldı avuçlarımıza

.............

o günden sonra

alinin parası hep oldu

mi mı ekiyse hep ayrı yazıldı

bir genç, 

çimlere basmayı hep yasak bildi....', 'Alinin parası hep vardı mi-mı ekiyse hep atrı yazılmalıydı biz büyümeye hevesliydik tamlamalar girdi hayatımıza hep tamlanan olduk tamlayama...', ARRAY['Türk Edebiyatı','Şiir','Hakan Kömürcü']::text[], 8.5, '{"poet":"Hakan Kömürcü","poet_slug":"hakan-komurcu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/mi-mi-eki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir sen değişmedin şu yüreğimde', 'bir-sen-degismedin-su-yuregimde-nuri-can-3fb3v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıllar   gelip   geçti   zaman   değişti

Bir  sen  değişmedin  şu  yüreğimde

Dağlara  kar  düştü  duman   değişti

Bir sen değişmedin  sevdiğim  bende

Ovalar   nehirler   düzler   değişti

Baharlar  rüzgarlar   güzler  değişti

İnsanlar   nesiller   yüzler   değişti

Bir  sen  değişmedin  şu  yüreğimde

Sen  hala  içimde  incecik  sancı

Biricik   sevdiğim   başımın   tacı

Sevenler  eskidi   herkes  yabancı

Bir  sen  eskimedin  şu  yüreğimde

Mevsimler  takvimler  yıllar  eskidi

Resimler   kavimler   kullar   eskidi

Gelenler   gidenler    yollar   eskidi

Bir sen  eskimedin  sevdiğim  bende

Şaşsada   yollarım   kesilsede   hız

Gözlerin  gönlümde  sönmeyen  yıldız

Hala  yavuklumsun  o  nazenin   kız

Bir  sen  değişmedin  şu  yüreğimde

Kurallar   töreler   bazlar   değişti

Sevdalar  sevgiler  hazlar  değişti

Kadınlar   gelinler   kızlar   değişti

Bir  sen  değişmedin  şu  yeryüzünde

Eserken   başımda   kavak   yelleri

Bağlanmıştı  gönlüm  öyle   serseri

Sen  hala   sevecen   nazlı   cilveli

Hiç mi  değişmedin  sevdiğim  bende

Bakışlar  işmarlar   gözler   değişti

Şarkılar   duygular   sözler   değişti

Saçlara  ak   düştü   yüzler   değişti

Bir  sen  değişmedin  sevdiğim  bende

Şehirler   sokaklar   evler   değişti

Bahçeler   tarlalar   köyler   değişti

Ağalar   köleler    beyler   değişti

Bir sen  değişmedin  şu  yeryüzünde

Can  Nuri’yim  yıllar  ne  çabuk  geçti

Avurtlarım   çöktü    şeklim   değişti

Doldu  vadem  ölüm  çağım   erişti

Bir  sen  değişmedin  durursun  öyle

İlk gençlik yıllarımda halk ozanlarına öykünerek yazdığım

Türkü Formunda şiirler', 'Yıllar   gelip   geçti   zaman   değişti Bir  sen  değişmedin  şu  yüreğimde Dağlara  kar  düştü  duman   değişti Bir sen değişmedin  sevdiğ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/bir-sen-degismedin-su-yuregimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmiş', 'gecmis-murat-tali-7d4n7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'nasıl bakakalır gözler aynaya 

derin ve solgun 

belki bir aşk yarası 

belki de 

bir tükenmişlik fırtınası yaşamış yüzde 

milyonlarca ifade kol geziyor. 

aşka doğru yol alıyorken 

durup 

çocukluğa dönüyor 

sonra 

ilk elele tutuşmanın yangınlarına 

eller ısınıyor 

kızarıyor yüz... 

aynada bir ışık 

geceden kopup geliyor 

bir yıldız takımından görüntülerle 

yırtılan perde rüzgarla giriyor içeri 

ve 

her gece 

başka gözlerle seyrediyor 

gökyüzü bakışlarını... 

ayna ise hep pencerenin karşısında 

ve soluk duruyor 

bir nefes 

ve 

bir el temizlemesi 

ile görüntüler netleşiyor 

zamana katılarak... 

Aynada

Donuklaşıyor zamanla ısınan eller

Kızaran yüzler

Paylaşılan, beraber yaşanan heyecanlar 

Zaman ve bizimle yitiyor

Belki bir zaman, başka bir bedende yada yine bizde

Alevleniyor bu geçiçi duygular

Kısa bir süreliğine ayna solgunluğunu yitiriyor...

Yeniden yaşamayı biliyoruz bir daha', 'nasıl bakakalır gözler aynaya  derin ve solgun  belki bir aşk yarası  belki de  bir tükenmişlik fırtınası yaşamış yüzde  milyonlarca ifade k...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gecmis-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hijyenik Harfler', 'hijyenik-harfler-yasar-aslan-iyx76', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sitemim yok uzaktan baktığım gökkuşağına

ne bir telaş ne hüzne batmışlık

korkum yok yere düşüp ağlamaktan

ve kırılmış harflere yalın ayak basmaktan 

çamura  battıkça harfler

avludaki çamaşır leğenine atacağım 

un serdiğim iplikte kurutacağım

kana bulandıkça ellerim 

yüzüme süreceğim 

çatlamış topraktan dirilip

harfleri yeniden şekillendireceğim 

annemin bana miras bıraktığı karanfil bahçemde 

kelimelerin her dem kifayetsiz

cümlelerin okunmadığı kitaplar yazacağım! 

kar tanelerinin rüzgarla dans ettiği zaman diliminde 

avucumdaki tozu yüzüne fırlatacağım

o zehir zemberek harflere inat

ben hijyenik harfler yaratacağım 

bembeyaz kar taneleri yapacak

yüzümdeki duvağı  o an kaldıracağım', 'sitemim yok uzaktan baktığım gökkuşağına ne bir telaş ne hüzne batmışlık korkum yok yere düşüp ağlamaktan ve kırılmış harflere yalın ayak ba...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Aslan']::text[], 8.5, '{"poet":"Yaşar Aslan","poet_slug":"yasar-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hijyenik-harfler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Can', 'bir-can-metin-usengec-aelgj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gönül soluyor yazık

Bir ömür bitiyor yazık

Değer miydi dünya üç günlük

Bir canı ölesiye kırdın gülüm..

1-Temmuz-2003  17:00

Kalbim Asla Azat Etmeyecek Seni..', 'Bir gönül soluyor yazık Bir ömür bitiyor yazık Değer miydi dünya üç günlük Bir canı ölesiye kırdın gülüm.. 1-Temmuz-2003  17:00 Kalbim Asla ...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-can-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Merhaba Gece! ...', 'merhaba-gece-naime-erlacin-8cqed', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'akışına bırakmalı geceyi

akarına

aşkı yazmalı 

yeşertmeli dünyayı

girmeli yepyeni bir âleme 

arınmalı düşünce 

yola koyulmalı basitten mücerrete

talana verirsem kendimi 

ölmeliyim

aşkı akışına bırakmak 

sevdayı geceye

işte o zaman anlamlı yaşamak 

ayak izlerime imler serdim

varsın okumasınlar

yazılsın yeter! 

acı bir yolculuktur gece

dostum dolunay  olsun 

ay ışığı

yıldızlar 

gök karanlıkmış ne gam 

severim demini tutmuş akşamları 

gecenin merhaba''sıdırlar

koyu düşler vardiyasında 

basitten mücerrete

tenhâ bir yolculuk başlar 

merhaba gece! 

(01 Temmuz 2003)', 'akışına bırakmalı geceyi akarına aşkı yazmalı  yeşertmeli dünyayı girmeli yepyeni bir âleme  arınmalı düşünce  yola koyulmalı basitten mücer...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/merhaba-gece-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En çok güzel havalarda seni yanıma alıyorum.', 'en-cok-guzel-havalarda-seni-yanima-aliyorum-ozcan-ozkan-nvc6w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'En çok güzel havalarda seni yanıma alıyorum.

Ver elini mavi, ver elini yeşil gidiyoruz.

Ağaçların gövdelerine dokunuyorum usulca, 

Ellerim senin...

Bir kuş ötüyor tek başına en yüksek dalda aranıyorum, 

Kulaklarım senin...

Kaç renk yeşil var diye tek tek diziyorum, 

Gözlerim senin...

Sana ağaçların adını, kuşların cinsini, 

Ve bilmediğim daha neler soruyorum

En çok güzel havalarda seni yanıma alıyorum.

Deniz kenarına iniyoruz, 

Hep gemilere bakıyorsun büyüklüğüne şaşarak, 

Ben sana...

Rüzgar çıkıyor üşüyorum, seni giyiniyorum.

Sen üşümüyorsun hiç.

Bir bardak çay istiyorum. 

İki şekerli geliyor, 

Birini geri veriyorum senin için.

Oturup okuyorum.

Hiç bir sayfada yoksun, özlüyorum.

Başımı kaldırıp bakınca karşımdasın, 

Kaşların çatık.

İçimi buruyor sessizliğin, boğuluyorum.

Ama olsun! 

Yine de güzel havalarda seni yanıma alıyorum...

(1997)', 'En çok güzel havalarda seni yanıma alıyorum. Ver elini mavi, ver elini yeşil gidiyoruz. Ağaçların gövdelerine dokunuyorum usulca,  Ellerim s...', ARRAY['Türk Edebiyatı','Şiir','Özcan Özkan']::text[], 8.5, '{"poet":"Özcan Özkan","poet_slug":"ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/en-cok-guzel-havalarda-seni-yanima-aliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babalar Günü', 'babalar-gunu-salih-ozalasan-8lrmx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ve bir babalar günü daha

Beni ağlatan; Ağlatan ama mutlu eden

Hüznü, acıyı, özlemi, acı geçmişimi

İki mevsimi bir güne sığdırdığım

Asla yaşamak istemediğim

Yaşadığım için sonsuz mutlu olduğum

Yılın özel günlerinden biri daha

Baba olduğum için kutlandığım

Evlat olduğum için hüzünlendiğim

Babama bir çiçek bile veremediğim

Elini öpüp naz yapamadığım

Velhasıl, doyasıya mutlu olamadığım

Özel, güzel ve acı bir gün daha

Ömrüm oldukça yaşayacağım

Belki bir çiçekle kutlanacağım

Veren için belki çok basit

Benim için elmas kadar değerli

Onlarca hediye alıp mutlu olacağım

Babalar günün kutlu olsun BABA

Asla diyemeyeceğim, 

Ona hediye alamayacağım

Bir gözümle gülerken

Diğer gözümle ağlayacağım

Çocuklarımı bağrıma basıp

Saçlarını gül koklar gibi koklayacağım

Evimin baş köşesindeyse

Daima seni arayacağım

Babalar günün kutlu olsun BABA

Y.Tarihi 16-06-2003 Saat 12.00

Salih ÖZALAŞAN', 'Ve bir babalar günü daha Beni ağlatan; Ağlatan ama mutlu eden Hüznü, acıyı, özlemi, acı geçmişimi İki mevsimi bir güne sığdırdığım Asla yaşa...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/babalar-gunu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustum Dİye', 'sustum-di-ye-salih-ozalasan-g27qz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sustum diye, unuttum sanma seni

Yüreğime yazdım sayfa, sayfa söyleyeceklerimi

Yaşanmış saymıyorum, sensiz geçen günlerimi

Sustum diye, mutlu sanma gecelerimi

Sustum diye, sanma ki demeyeceğim seviyorum seni

Kaderime yazdım nokta, nokta mahşere denk seni

Sanma ki can veririm, sen tutmadan ellerimi

Sustum diye, kabullendim sanma kaderimi

Sustum diye, başkasına açtım sanma yüreğimi

Karşı dağlara sor nasıl inlediğimi

Tanrı şahit, herkes biliyor seni beklediğimi

Sustum diye, yok sayma kalbimi yüreğimi

Dilim sustu bak, gör konuşan gözlerimi

Kim bilir belki kaybettim yüreğinde değerimi

Bir gün gelecek mahşerde alacağım yanında yerimi

Sensiz ölürsem cehennem azabı kaplayacak makberimi

Y.Tarihi 28-05-2003

Salih ÖZALAŞAN', 'Sustum diye, unuttum sanma seni Yüreğime yazdım sayfa, sayfa söyleyeceklerimi Yaşanmış saymıyorum, sensiz geçen günlerimi Sustum diye, mutlu...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sustum-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Beldem', 'benim-beldem-salih-ozalasan-xyyps', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İl Bursa, ilçe Nilüfer

Taşından saraylar kur

Toprağını gül bahçesine ser

Belde Akçalar

Toprağına taş eksen, gül biter

İnsanları cana yakın

Sen selam ver

Mutlaka vardır sizin için

Baş köşelerinde mütevazı bir yer

Gençleri hep sevdalı

Sanırsınız ki bunlar

Yeni yüzyılda yaşayan

Leyla Mecnun, Aslı Keremler

Boylar ne uzun ne kısa

Giyilmiş pantolon ve etekler

Değişmiş tüm gelenekler birer, birer

Salonlara taşınmış, cemiyetler, düğünler

Damatlar halaydan dönmüş çifte telliye

Gelin nişanı takarken der

İlk şartım mutlaka salon diye

İki şahitte yetmez

Yüzlerce şahit lazım burası köy demeye

Bizler çabalardık ilk okulu bitirsek diye

Şimdi hedef tek, mutlaka üniversite

Doktorlar, mühendisler, akçalarlı öğretmenler

Site usulüne dönüvermiş biranda evler

Çobanlar kalmış işsiz, ahırlarda sürüler

Üç beş kişi kalmış, nerde o tütün dikenler

Bağlar olmuş birer, birer tarla

Nerede Akçaların sembolü üzümler

Her evde bir araba, tedavülden kalkmış merkepler

Fabrika bacaları boy, boy kara dumanlar

Kalmamış toprağı yoğuran nasırlı eller

Matador ekmek fırını pek revaçta

Nerde mis kokan köy fırını ekmekler

İşçiyi çiftçiyi sollamış gitmiş

Kahveler dolmuş genç emekliler

Velhasıl modern bir Akçalar

Yok olup gidiyor tabiata dayalı güzellikler

Sanırım ülkemin kaderi

Köyleşen kentler, şehirleşen köyler

Eski resimlerde saklı kaldı

Bağlar, bahçeler, doğal güzellikler

Eski Akçaları anlatmalıydım ya size

Benimde aklımı çeldi

Sahte yapmacık güzellikler

Bir adı kaldı Akçalar

Kalksa mezarından erken ölenler

Sanırım hayretle gözleri açılır

Ne yaptınız bizim Akçalarımıza der

Yazım Tarihi 22-06-2003 Saat 12,20

Salih ÖZALAŞAN', 'İl Bursa, ilçe Nilüfer Taşından saraylar kur Toprağını gül bahçesine ser Belde Akçalar Toprağına taş eksen, gül biter İnsanları cana yakın S...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/benim-beldem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Uykuda Yaşanmaz', 'ask-uykuda-yasanmaz-numan-eksioglu-oo29x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Buzlarım buharlaşır eser durur yönüne

kirpiklerin bir tek damla çiğ almaz

gözlerin ışıldanmaz

Buzlarım eriyerek akar durur yönüne

Dudaklarından geçtim ayakların ıslanmaz

Adımların hiçbir yöne sıklanmaz

Suyun şarkılarını diyaframdan söylerim

Tarafından birtek notam duyulmaz

Dalgalar çıldırırlar

Aşkın yörüngesinde sevginin yöresinde

Aşk sıçrayıp çırpınır

Sevgi sana davranır

Ah sen hiç kıpırdanmaz

Yalvarırım yapına beynin hükmetsin artık

Yüreğin seziversin

Aşk uykuda yaşanmaz', 'Buzlarım buharlaşır eser durur yönüne kirpiklerin bir tek damla çiğ almaz gözlerin ışıldanmaz Buzlarım eriyerek akar durur yönüne Dudakların...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-uykuda-yasanmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk', 'mutluluk-numan-eksioglu-aezp5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün ışığı su

Ayın kendisi sabun

Yakamoz keçe

ben de bir gündelikçi

yürek yıkayıcısı', 'Gün ışığı su Ayın kendisi sabun Yakamoz keçe ben de bir gündelikçi yürek yıkayıcısı...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mutluluk-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El', 'el-numan-eksioglu-a43oq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'El bu

Sevgili de okşar çiçek de

El bu

Kalem de tutar çekiç de

El bu

Yumruk da olur gerektikçe', 'El bu Sevgili de okşar çiçek de El bu Kalem de tutar çekiç de El bu Yumruk da olur gerektikçe...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/el-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük', 'ozgurluk-numan-eksioglu-b0635', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Koltuğu yok

Olsun da istemiyor

Ayaklarının çekmeyin altından', 'Koltuğu yok Olsun da istemiyor Ayaklarının çekmeyin altından...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ozgurluk-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanı Mıydı', 'zamani-miydi-salih-ozalasan-d2fdp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüreğime böyle bir sevdanın

Habersizce girecek zamanı mıydı

Tam saçlarıma kırlar düşmüşken

Bir çift ela göze bağlanmanın zamanı mıydı

Yüreğimde açılan yaraya gücüm yokken

Aşk denen kangrene tutulmanın zamanı mıydı

Göz pınarlarım kurumaya yüz tutmuşken

Yokluğunda ağlamanın zamanı mıydı

Zamansız bir sevda bizimki

Yüreklerle beden uyumlu değil ki

Omuzlar çökmüş, beller eğimli

Ömrümüzün son demi, 

Sevdanın zamanımıydı şimdi

Gel desem gelemezsin ki

Gel desen ben hiç gelemem ki

Sadece yolunda ölürüm, 

Kolunda yürüyemem ki

Kör olası yürek sana sevdalı

Her şeyi bilir ama söz dinlemez ki

Çok kez derim keşke hiç doğmasaydım

Yirmi yıl erken doğmanın zamanı mıydı

Seni geç tanıyıp ölesiye sevmenin

Kanlı canlı kara sevdalı olmanın zamanı mıydı

Y.Tarihi 14-06-2003 Saat 16.10

Salih ÖZALAŞAN', 'Yüreğime böyle bir sevdanın Habersizce girecek zamanı mıydı Tam saçlarıma kırlar düşmüşken Bir çift ela göze bağlanmanın zamanı mıydı Yüreği...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/zamani-miydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Bitti Bebeğim', 'ask-bitti-bebegim-seval-kemertas-8mcxw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bitti demek ne kadar acı

artık kadehlerde tortu sevgimiz

bitti aldanışlar, bitti her keder

yenik düştük bu savaşta ikimiz...

aşk bitti bir tanem

dindi içimizdeki deli rüzgar

unutulduk, duruldu kalbimiz

ne beste kaldı, ne şiir

nice sevdaları aldı bu deniz...

şimdi birbirinden uzak ellerimiz

içimizde burgu burgu özlemlerin sancısı

başladığı anda bitti hikayemiz

umutlar savrulurken hazan misali; 

mevsimlerin kuytusunda yitip gittik biz...

aşk bitti bebeğim 

yavaş, yavaş topla şarkını

artık bütün kaygıların ötesindeyiz

unut bildiğin bütün aşk masallarını

durma öyle! tükendi kalmadı vaktimiz

bak! .. uzağımıza düşüyor kanayan kalplerimiz...

22/06/2003', 'bitti demek ne kadar acı artık kadehlerde tortu sevgimiz bitti aldanışlar, bitti her keder yenik düştük bu savaşta ikimiz... aşk bitti bir t...', ARRAY['Türk Edebiyatı','Şiir','Seval Kemertaş']::text[], 8.5, '{"poet":"Seval Kemertaş","poet_slug":"seval-kemertas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ask-bitti-bebegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belirtemediğim 6 NOKTA (...)', 'belirtemedigim-6-nokta-hey-marasko-yfva2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Belirtemediğim 6 NOKTA (......) 

Beni ben yapan gözlerini unutmak için 

Unutamadıklarından bir buket gül seriyorum önüne

Senin mis kokan tenini unutmak için 

Uzaklardan gelen bir merminin barutunu kokluyorum bu gece

Saçlarının kızıllığını güneşin batışında arayan bir aşık gibi

Çöllere düşmenin aksine tüm güzelliklerin icinde yaşayıp

Sensizliğin damgasını vuruyorum dünyaya

Sıradanlığın kadar sessiz, güzelliğin kadar gizli kalıyorum

ve gizli kalmış yanlarını arıyorum bu halimle

Anlatamadıklarımla bir dünya yaratıp, bu dünyada seni arıyorum

Hiç açılmamış bir kapı görüyorum

Ne benim sana açabildiğim nede senin açmak istediğin...

Seni unutamamanın ve anlatamıyor olmamın

Herkesi senle kıyaslayıp, 

bazı özelliklerini elin yosmalarında arayışımın

Yokluğunu bardaktan taşırıp etrafa saçmamın

Sensizlikler ülkesinde yanlız kalıp demir atmamın

ve kayboluşumun, yol bulamayışımın

Hesabını soruyorum şimdi sana

Sana övgüler yağdırmak yerine bir...... olduğunu belirtip

Aynı anda seni çok sevdiğimi

Ve son nefesime kadar seveceğimi belirtiyorum...

Kelimelerle oynatmak istiyorum seni bu gece

Yorulana kadar oynamanı ve bitişini görmek istiyorum

Bitirdiklerin yanında seninde bitmen her ne kadar doğru olsada

Doğruların çizdiği yolda sen her zaman yanlış olacaksın

''Bazı yanlışlar vardır ki telafisi olmaz''

Bunu sen söylemiştin bana

ve bana bunu unutmamamı, sana karşı yanlış yapmamamı istemiştin

İstemekle kalmayıp birde bana yemin ettirdin

Oysaki ben sana hiç yemin ettirmedim. Sadece güvendim...

Canımı koydum yoluna... 

Ve canları...

Sahi... Unutmadan sormalıyım sana.

Beni hiç düşünüyormusun bu aralar? 

Daha doğrusu vakit bulabiliyormusun buna? 

Nedense hiç vaktin olmaz bana karşı

Sen mükemmellesin, harikasın, gözümde bir devsin! 

Oysaki değilsin... 

Sende yemek yiyor, su içiyor ve uyuyorsun

Beni düşündüğünüde sanmıyorum, gereksiz bir davranıştır senin için

Peki rüyalarına misafir oluyormuyum? Buda senin elinde değil ya! 

Belki gecenin melekleri sana ceza verip rüyalarında beni anımsatıyorlardır

Bu arada ben her gece rüyalarımda seninle sevişiyorum

Bunu biliyormuydun? 

Nerden bileceksin; 

Sana söylemedimki, 

Daha doğrusu sen hiç sormadın...

Hep ben sordum sana soruları, 

sende kaçamak cevaplarla karşıladın yüreğinde beni

Yüreğinden bana ufak bir sevgi vermeye çalıştın hep

Bende yetinmeye çalıştım soğuk gecelerde

Soğuk alevlerde yandım her gece

Köz oldum, kül oldum, duman oldum

Ve ertesi gün tekrar doğdum 

Senin ellerinde şekil almak için...

Kaç zamandır sürüyor bu şekil oyunu

Kaç zamandır acılar içindeyim...

Bitiyor sanırım, oyuncağın bozuluyor...

Biliyormusun? 

Yapmak istediklerinle, yaptıkların arasında öyle bir fark varki 

Bunu iki zıt kelimeyle anlatmak yerine 

Ateşle barutu örnek gösteriyorum...

Eğer bunu anlatamıyorsam, anlamıyorsun demektir

ve sen anlamıyorsan kimsenin anlamaması gerekir...

Birkez olsun, bu dünyanın gerçeğini anla, 

benim vaziyetime gel bir süre

Eleştir birilerini, suçlu ara! (Kendinden başlamanı tavsiye ederim) 

Sana o kadar çok şeyi tavsiye ederimki

Yok yok edemem, çünkü sen artık yoksun, 

boş hayallere kapanmanın luzumu yok derim

Defteri kaparım...

En son geldiğinde benim için ne yaptın dedin 

Yaptıklarım inanki senin yapamadıklarından daha fazla bir yer kaplıyor

Mesela üniversiteyi senin yüzünden kazanamadım 

Kendi odama kapanıp yıllarca senin yüzünden herkesten kaçtım 

Kaçtım çünkü......lardan bıkar hale geldim

Oysaki hayatımda tek tanıdığım...... sendin! 

Bu kadar yeter, artık gitmeliyim

Sende olsan yeter derdin. Belkide hiç konuşturmazdın...

Ama hakkını yemek istemem, işin doğrusu gitmeme kızardın

Bende sana hep ''her gelişte bir gidiş vardır'' demek isterdim

Bugüne nasipmiş bunu demek 

Bak yine gece oldu, gece bende yanlız kaldı 

Gündüzler sende...

Birde senin kocanla seviştiğin saatlerin var 

Gecelerimde...

Benim ise hiçbir şeyim yok 

Gündüzlerinde...

Sonuç olarak

Ela gözlerine, kıvırcık ve aynı zamanda kızıl saçlarına, 

bal dudağına selam olsun.

Yok be! Olmasın... 

Olmasınki beni yanlız onlar anlasın, 

Yüreğinse sende kalsın... Bana dargın kalsın...

Bende sende kalayım, 

Herşey sende kalsın! ..

Elveda bebeğim... Elveda...

MAFYA BABASI, DENİZ ANASINA DİYORKİ; 

'''' HER AŞK HİKAYESİNDEN BİR SAHNE ALDIĞIM

YASAK AŞKIM 

HER AŞK HİKAYESİNE BİR SAHNE VERECEK KADARDA YÜCEDİR. ''''

(Ben kimsenin babası değildim. Sadece elinde oyuncağı olan garip bir adamdım.

  O oyuncağın babasıydım ben, 

  Onuda sana verdim. Gönlümü vermişim sana, o çokmu...

  Ama sen gerçek bir anneydin. 

  Annelik en yüce duygudur. 

  Anne olduğunu benden sakladığın için sana çok kızmıştım.

  Sen ise evli olduğunu öğrenmeme kızdığımı düşünmüştün.

  Oysaki çok yanlış düşündün...

  Neyse...

  Sana ailenle mutluluklar dilerim 

  Bende arada bir deniz anasıyla hasret gideririm

  Mutlu olurum bende dünyalarımda.

  Şu anda olduğum yer sanal dünyaysa

  Uyandığımda ise karşıma çıkacak yer yine yalan dünya olacaktır) 

                                            Hayatımda ilk kez sevdiğim..... ''ye', 'Belirtemediğim 6 NOKTA (......)  Beni ben yapan gözlerini unutmak için  Unutamadıklarından bir buket gül seriyorum önüne Senin mis kokan ten...', ARRAY['Türk Edebiyatı','Şiir','Hey Marasko']::text[], 8.5, '{"poet":"Hey Marasko","poet_slug":"hey-marasko","theme":"Türk Şiiri","is_hero":false,"total_lines":118,"source_url":"https://www.antoloji.com/belirtemedigim-6-nokta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Uykum Firari', 'uykum-firari-gunay-aktag-hrggn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğim çarpıyor sen gelince aklıma

Sesin kulaklarımda mûsikî

Gözlerimde hayâlin bir bûse sanki

Sensiz  gecelerde yine uykum firarî

Kaç gece geçti sensiz

Nerdesin ey sevgili! ...', 'Yüreğim çarpıyor sen gelince aklıma Sesin kulaklarımda mûsikî Gözlerimde hayâlin bir bûse sanki Sensiz  gecelerde yine uykum firarî Kaç gece...', ARRAY['Türk Edebiyatı','Şiir','Günay Aktağ']::text[], 8.5, '{"poet":"Günay Aktağ","poet_slug":"gunay-aktag","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/uykum-firari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapamadıklarının Bedeli', 'yapamadiklarinin-bedeli-hey-marasko-0r0b6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Onu görmüş gibi yap

Sessizliğin içinde

Onu düşünür gibi ol

Hayal kurduğun vakitlerde

Ondan nefret et

Seven kalbinle

Onsuz mutlu ol

Unutkan saatlerinde

Sessiz kal

Konuşma ve ağlama

Yazma, okuma, düşünme

Sus...

Karışık ol, 

Çözülme

Karıştır, 

Çözeme...

Kaybetmeyi kazan

Yanlızlığın ödülünü al

Yanlızlığı terket

Daha yalnız ol

Öl

Sevdiğin için

Diril

Ölemediğin için...

Git, gelemediğin için...', 'Onu görmüş gibi yap Sessizliğin içinde Onu düşünür gibi ol Hayal kurduğun vakitlerde Ondan nefret et Seven kalbinle Onsuz mutlu ol Unutkan s...', ARRAY['Türk Edebiyatı','Şiir','Hey Marasko']::text[], 8.5, '{"poet":"Hey Marasko","poet_slug":"hey-marasko","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yapamadiklarinin-bedeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirle Başım Dertte', 'siirle-basim-dertte-naime-erlacin-u3oml', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'düşünce yetmiyor sanki 

gölgem oldu şiir

düştü peşime

o gider 

ben giderim

birlikte bir meçhule gideriz işte 

sözün gurbetine düşmüş gibiyim

sözcükler desem 

öyle kalabalık

yerlerine sığdıramıyorum

dolu dolu geliyorlar üstüme

eğlence değil artık 

uğraş oldu 

yüreğim bir deli küheylân

o da koşar benimle

şiir başa belâymış meğer

(01 Temmuz 2003)', 'düşünce yetmiyor sanki  gölgem oldu şiir düştü peşime o gider  ben giderim birlikte bir meçhule gideriz işte  sözün gurbetine düşmüş gibiyim...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/siirle-basim-dertte-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar gibisin', 'sonbahar-gibisin-nazim-altundere-ujz62', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sonbahar gibisin şimdi

Sarartıyorsun, bir bir hayallerimi

Ve döküyorsun düşlerimi

Dökülüyor, bir birrrr

Usulca dibimdeki göle...', 'Sonbahar gibisin şimdi Sarartıyorsun, bir bir hayallerimi Ve döküyorsun düşlerimi Dökülüyor, bir birrrr Usulca dibimdeki göle......', ARRAY['Türk Edebiyatı','Şiir','Nazım Altundere']::text[], 8.5, '{"poet":"Nazım Altundere","poet_slug":"nazim-altundere","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sonbahar-gibisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aysel', 'aysel-elvan-akin-8ngfw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zamanlar vardi

Ortamlar vardi

birde güzel köyümüz vardi

icinde birde dedem vardi

severdi beni 

döverdi beni

severdim o dedemi

kovdular beni gurbete

sormadilar beni 

geldim gurbete

ne ana

ne baba

nede dedem yanimda

bilmem kimseyi

düsdüm karanliga

kör bir köstebek misali

bir sabah yine actim gözlerimi

karanlagimin ortasinda

gözlerimin körlestigini zan ettim

bir isik basti üstüme

gördüm etrafimi

acti güller

tapti sözler ona

aydinlatti etrafimi

esti sacti güzelligini

sevdim ben onu

o ya o ise bana yeni ufuklar verdi

Oldu o benim Aysel', 'Zamanlar vardi Ortamlar vardi birde güzel köyümüz vardi icinde birde dedem vardi severdi beni  döverdi beni severdim o dedemi kovdular beni ...', ARRAY['Türk Edebiyatı','Şiir','Elvan Akin']::text[], 8.5, '{"poet":"Elvan Akin","poet_slug":"elvan-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/aysel-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diğer Yanım...', 'diger-yanim-ugur-deniz-ulkegul-sa9an', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kayıp gidiyor ellerimden bu şehir, 

Yüreğim, koca bir yalnızlığa esir, 

İçime çektiğim duman, 

Sustuğum gece, 

Yazdığım şiir, 

Ve sen......

Yine ağlamaklı kapanıyor gözlerim, 

Adresi belirsiz, sitemkar sözlerim, 

Yazgısına kızdığım kader, 

Çektiğim hasret, 

Yenildiğim dert, 

Ve sen.......

Bir çift tebessümün gömüldüğü yer, 

Üstüne toprak atılmış keder, 

Bir ağaç gölgesi, 

Bir yol kenarı, 

Bir mezar, 

Ve sen.....

Boğazıma takılıp kalan kelimeler, 

Çizmediğim resim, boyasız renkler, 

Seni unutmayışım, 

Bir türlü affetmeyişim, 

Çelişkiler, 

Ve sen.....

Yaşamak sancısında, bilmek yokluğunu, 

Taşımak boynunda, silinmek burukluğunu, 

Gitmek ansızın bir gün, sebepsiz, 

Bakmak ardından, sessiz, 

Kalmak bir başına..

Tek, kimliksiz

Ve sen.....

Sonra gökyüzüne bakmak her gün, usanmadan, 

Umudu anlatmak insanlara, yarını umursamadan, 

Saçını okşamak küçük bir kızın, 

Soğan ekmek koymak sofraya, 

Yalnızlığıyla bölüşmek bir hayırsızın...

Ama sevmek yine de işte, 

Düşünmek, 

Her gün yeniden başlayan bir gidişte...

Aynalarda bir bakış, eskiyen, 

Yazamadığım mektup, 

İzmarit kokan oda, 

Diğer yanım, 

Ve sen.......', 'Kayıp gidiyor ellerimden bu şehir,  Yüreğim, koca bir yalnızlığa esir,  İçime çektiğim duman,  Sustuğum gece,  Yazdığım şiir,  Ve sen...... ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/diger-yanim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep O Şarkı', 'hep-o-sarki-mustafa-onder-o82te', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sakın erkekler ağlamaz deme

Sabaha kadar ağladım sana

Gözpınarlarım kurudu gene

Hicranla hasret yolladım sana

Gözyaşında güller büyüttüm de

Vefâsız feleğe kahrettim de

Sensiz şu ömrümü tükettim de

Mahşere ümit bağladım sana..', 'Sakın erkekler ağlamaz deme Sabaha kadar ağladım sana Gözpınarlarım kurudu gene Hicranla hasret yolladım sana Gözyaşında güller büyüttüm de ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Önder']::text[], 8.5, '{"poet":"Mustafa Önder","poet_slug":"mustafa-onder","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hep-o-sarki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Kalma', 'senden-kalma-mustafa-onder-ijwb2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senden kalma umut, 

Sabah mahmurluğu gibi gözlerimdeki hüzün, 

Göçebe kuşlar gibi konup göçen

Aynadaki yüzün

Senden kalma..

Senden kalma, 

Göğün bu sağanak yağmuru, 

Kalbimdeki öfkenin gururu

Senden kalma..

Senden kalma, 

Ayaklarımın yorgunluğu, 

Kafesteki muhabbet kuşu, 

Umutlarımın yokuşu

Senden kalma...

Yalnızlığın ikide bir bana sokuluşu, 

Kaldırımların bu garip berduşu

Senden kalma..', 'Senden kalma umut,  Sabah mahmurluğu gibi gözlerimdeki hüzün,  Göçebe kuşlar gibi konup göçen Aynadaki yüzün Senden kalma.. Senden kalma,  G...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Önder']::text[], 8.5, '{"poet":"Mustafa Önder","poet_slug":"mustafa-onder","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/senden-kalma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arıyorum', 'ariyorum-goktan-guler-64py8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tek taraflı olsada

Sevdamı yüreğime gömüyorum

Şimdi sensizliğin baharında

Seni sensiz yaşıyor

Vermediğin umudun ışığını arıyorum



                                                                     Konya-1998', 'Tek taraflı olsada Sevdamı yüreğime gömüyorum Şimdi sensizliğin baharında Seni sensiz yaşıyor Vermediğin umudun ışığını arıyorum            ...', ARRAY['Türk Edebiyatı','Şiir','Göktan Güler']::text[], 8.5, '{"poet":"Göktan Güler","poet_slug":"goktan-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ariyorum-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gittin Gideli', 'sen-gittin-gideli-ergun-yildiz-219qt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüzündeki hüznü döktün yüzüme

Yağmurları serptin gülen gözüme

Giderken ateşi attın özüme

Sen gittin gideli gülemez oldum

Al kana boyadın sinemi benim

Yıktın harap ettin hanemi benim

Çaldın gittin bunca senemi benim

Yitik  yıllarımı bulamaz oldum. 

Artık boyun eğdim alın yazıma

Yandım dedim, inanmadın sözüme 

Dünya zindan görünüyor gözüme

Gecemi, gündüz mü bilemez oldum.

Bir dal idim, kırdın beni sonunda

Eğilmedim ama, düştüm önünde

Ne en güzel, ne de kötü gününde

Ben senin yanına gelemez oldum

Düşüp şu toprağa çürümek için

Hasretinle yanıp erimek için

Dön deyip ardından yürümek için

Bedenimde derman bulamaz oldum.

Kimselere boyun eğmez biriydim 

Yüreğine sevda koymaz biriydim

Gözlerine hüzün değmez biriydim

Şimdi gözyaşımı silemez oldum.

Oysa nasıl ölesiye sevdim ben

Nasıl bağlanmıştım sana bir bilsen

Yüreğimde ümidini beslerken

Düşlerimi gerçek kılamaz oldum

Teli kırık saza çevirdin beni

Susuz kurak yaza çevirdin beni

Ayrılık yeline savurdun beni

Ben artık yönümü bulamaz oldum.

Gökte yıldız idim, yere indirdin

Na^rımı aldın da beni söndürdün

Akil idim, divaneye döndürdün

Ben bile kendimi bilemez oldum. 

Bir kara geceden ayrılıp geldin

Eski yaşamından sıyrılıp geldin

Sandım ki benimsin, hep benim oldun

Meğer yalan imiş, gülemez oldum

Gerçek ile düş arası bir şeysin

Bahar ile kış arası bir şeysin

Kahkahayla yaş arası bir şeysin

Seni koyacak yer bulamaz oldum.

Çok uzattım hiç tutmadın elimi

Çok anlattım anlamadın halimi

Bir meçhule yönlendirdin yolumu

Yürüsem de sana gelemez oldum

Hep bir sır olarak kalsa da yüzün

Bil ki  hep ruhumda kalacak izin

Anladım yarını yok ikimizin

Şu dünyadan bir tad alamaz oldum

Sevdim seni, yine pişman değilim

Çok kırıldım, ama düşman değilim

Artık, o savaşan insan değilim

Direnecek gücü bulamaz oldum.

Ergun YILDIZ.

13.11.2002', 'Yüzündeki hüznü döktün yüzüme Yağmurları serptin gülen gözüme Giderken ateşi attın özüme Sen gittin gideli gülemez oldum Al kana boyadın sin...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/sen-gittin-gideli-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vay Babam vay vay! , Oy Anam oy oy!', 'vay-babam-vay-vay-oy-anam-oy-oy-bekir-gedikoglu-b7vhf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu dünyanın oku, Adem doğduğunda kırılmış

Yalanın bini, beş bini dünyaya yayılmış

Hal böyle iken bunlara, birde şeytan karışmış

Oy Anam oy oy, vay Babam vay vay

Doğru söyleyeni dokuz köyden kovarlar

Mert insanları tam sırtından vururlar

Daha adamı devirmeden puşluk çukuruna atarlar

Vay Babam vay vay, oy Anam oy oy

Çalışanla çalışmayanı aynı kefe’ ye koyarlar

İnsanın tembelini el üstünde tutarlar

Hatta çalışanın üstüne birde semer koyarlar

Vay Babam vay vay, oy Anam oy oy

Mühendis yapar projeyi dünya ya parmak ısırtır

Afaki konuşmaksa, insanın fesatına yakışır

Defteri dürmek için hemen ferman yazılır 

Oy Anam oy oy, vay Babam vay vay

Birlik ve beraberliği kurmak için çalıştım

Şeytanı ve putperesti kırmak için çalıştım

Tüm bunlara ramak kalmıştım ki! Ağır bir sille ile karşılaştım

Vay Babam vay vay, oy Anam oy oy

Peygamberler, Fatihler diyarında yaşarım

Allah’ı kalbime koyar öyle dolaşırım

Hak-hukuk –adaleti gel birlikte yazalım

VAY VAY İLE, OY OY İLE BU KOCA HAYATI BOŞUNA DOLDURMAYALIM

Ankara,01.07.2003-07-01

Bekir Gedikoğlu', 'Bu dünyanın oku, Adem doğduğunda kırılmış Yalanın bini, beş bini dünyaya yayılmış Hal böyle iken bunlara, birde şeytan karışmış Oy Anam oy o...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/vay-babam-vay-vay-oy-anam-oy-oy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dur, Düşün, Söyle', 'dur-dusun-soyle-ayse-mattaogullari-zr24h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dur, 

Kalbini dinle

Doğruyu bulacaksın.

Düşün, 

Aklını kullan

Hayatı kolaylaştıracaksın.

Dinle, 

İnsanlardaki 

Saygıya varacaksın.

Söyle

Daima

Gerçeği göreceksin.

Sev, 

Çok sev, 

En çok sev, 

Çünkü mutlu olacaksın.', 'Dur,  Kalbini dinle Doğruyu bulacaksın. Düşün,  Aklını kullan Hayatı kolaylaştıracaksın. Dinle,  İnsanlardaki  Saygıya varacaksın. Söyle Dai...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Mattaoğulları']::text[], 8.5, '{"poet":"Ayşe Mattaoğulları","poet_slug":"ayse-mattaogullari","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dur-dusun-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadakat', 'sadakat-oznur-saka-10fbs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kere kalbime yazmışım seni, 

Başka yar sevmeyi ihanet saydım, 

Aylarca yıllarca görmesem seni, 

Bir an unutmayı ihanet saydım.

Aklımdan çıkar mı  mahsun bakışın, 

Kabulümdür senin yazın ve kışın, 

Senden daha güzel, daha sarışın, 

Olsa aramayı ihanet saydım.

Ölesiye sevdim, çeksem de cefa, 

Ömrümce görmesem, sürmesem sefa, 

Senden başkasına inan bir defa, 

“Yar” diye bakmayı  ihanet saydım.

Aklımdasın gezsem sokakta, yolda, 

Baktığım yerde sen sağımda, solda, 

Kolundan başka bir yabancı kolda, 

Uyuyup yatmayı ihanet saydım.

Dileğim o düşmeyesin dillere, 

Kokunu verme hiç esen yellere, 

Kıskandığım için, senin ellere, 

Adını demeyi ihanet saydım.', 'Bir kere kalbime yazmışım seni,  Başka yar sevmeyi ihanet saydım,  Aylarca yıllarca görmesem seni,  Bir an unutmayı ihanet saydım. Aklımdan ...', ARRAY['Türk Edebiyatı','Şiir','Öznur Saka']::text[], 8.5, '{"poet":"Öznur Saka","poet_slug":"oznur-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sadakat-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüküm Gam Yüküdür', 'yukum-gam-yukudur-i-brahim-bayraktar-zje3b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüküm gam yüküdür, güler geçerim, 

Dalgalı denize rüzgâr ekerim, 

Ruhum daralırsa yelken açarım, 

Çıkarım deryaya uçar giderim.

Tehdide aldırmam, vurdum duymazım, 

Nasihat kâr etmez tam bir aymazım, 

Dilde Köroğlu, gönülde ayvazım, 

Hayatı deli dolu yaşar giderim.

İzzeti nefsime hürmetim çoktur, 

Kimseye verecek hesabım yoktur, 

Doğruluk sırtımda ağır bir yüktür, 

Bütün zorlukları aşar giderim.

Ne bir amacım var, ne bir kederim, 

Yarını düşünmem heder ederim, 

Herkes birey ise ben de liderim, 

Kadere kollarımı açar giderim.

Dünyayı han sanıp, devrilip yattım, 

Söylenen sözleri yabana attım, 

Üç günlük beyliği bir pula sattım, 

Şimdi kıyamete naçar giderim.

18.04.2003', 'Yüküm gam yüküdür, güler geçerim,  Dalgalı denize rüzgâr ekerim,  Ruhum daralırsa yelken açarım,  Çıkarım deryaya uçar giderim. Tehdide aldı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yukum-gam-yukudur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzzam', 'huzzam-hakan-kose-3h27d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir Hüzzam şarkı aşk, bestekârı mâlum, 

Cennet gibi bir sabah, kıyamet gibi bir akşam

Ne kadar doğruysa o kadar büyük yalan 

Ne varsa ki hakkında söylenen, yazılan

Hiç biri değil, her biri ayrı ayrı yalan

Bir Hüzzam şarkı aşk, bestekârı mâlum...

Nice tamburlar yandı, ne udlar yıkıldı

Re, mi-bemol, üç komalık fa-diyez

Kapı kapı gezip Segâh''da karar kılmak

Yekvücûd iken ayrılıp parça parça dağılmak

Ne büsbütün ölmek, ne tastamam yaşamak

Gözler ufukta, dil suskun, gönül yaralı

Bir Hüzzam şarkı aşk, bestekârı mâlum...

Sabah sabah birdenbire kâbusla uyanmak

Re, mi-bemol, üç komalık fa-diyez

Arayıp bulamamak, bulunca alamamak

Buldum sanıp yanılıp, yanıldığın an bulmak

Kapı kapı gezip Segâh''da karar kılmak

Gözler ufukta, dil suskun, gönül yaralı

Bir Hüzzam şarkı aşk, bestekârı mâlum...

-Hüzzam Klasik Türk Musikisi''nin en hüzünlü makamlarından biridir, Türk Musikisi''nin bilinen ilk notası olan ''Segâh'' (si)   notasında karar verir, temeli aşk acısıdır...', 'Bir Hüzzam şarkı aşk, bestekârı mâlum,  Cennet gibi bir sabah, kıyamet gibi bir akşam Ne kadar doğruysa o kadar büyük yalan  Ne varsa ki hak...', ARRAY['Türk Edebiyatı','Şiir','Hakan Köse']::text[], 8.5, '{"poet":"Hakan Köse","poet_slug":"hakan-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/huzzam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Sev, Ya Terket', 'ya-sev-ya-terket-i-brahim-bayraktar-4gn1e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ya güneşim ol yak beni, 

Ya gölgem ol serinlet. 

Ya güldür beni kahkahayla, 

Ya da inim inim inlet.

Gücüm kalmadı artık, 

Sabret, sabret, 

Ya delice sev beni, 

Ya da nefret et.

Yüreğinde hisset beni, 

Yanakların kızarsın.

Söküp at kalbinden, 

İçin rahatlasın.

Ortası yok bu işin, 

Bu manasız gidişin, 

Ya delice sev beni, 

Ya da hemen terk et.

04.07.2000/Ankara', 'Ya güneşim ol yak beni,  Ya gölgem ol serinlet.  Ya güldür beni kahkahayla,  Ya da inim inim inlet. Gücüm kalmadı artık,  Sabret, sabret,  Y...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ya-sev-ya-terket-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıvılcım', 'kivilcim-i-brahim-bayraktar-svi4j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bakışın delip geçsin istemiyorum.

Bir kıvılcım sadece, 

Sana her bakışımda istediğim.

İçim cızzz! etsin istiyorum, 

Dokunmuş gibi ateşe.

Ama yakma ne olur.

Çünkü sana baktıkça erimek, 

Erimek istiyorum.

Belki sana kızıyorum, 

Belki kıskanıyorum da, 

Belki rahatsızlık da veriyorum, 

Benden kurtulmak, 

Uzaklaşmak da istiyorsundur.

Hepsini iste ama; 

Ben, yine içinde olayım, 

Hep seninle olayım, 

Kalbinde yer bulayım, 

Damarındaki kan gibi. 

23.2.1993/ANKARA', 'Bakışın delip geçsin istemiyorum. Bir kıvılcım sadece,  Sana her bakışımda istediğim. İçim cızzz! etsin istiyorum,  Dokunmuş gibi ateşe. Ama...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kivilcim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan-ı Kamiller Anlar Halinden', 'i-nsan-i-kamiller-anlar-halinden-salim-solmazgul-vodhh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sakın umudunu yitirme gönül

Mecnun isen Leyla geçer çölünden

İnsan gibi yaşa insan gibi öl

İnsan-ı kamiller anlar halinden

Bilirsin bu dünya fanidir fani

Var mı hiç ölmeyen var ise hani

Gel boş yere üzme bu garip canı

Ağlasan da gülmek gelir elinden

Bir sen misin dertli elde neler var

İnsan hep gülmez ki bazen de ağlar

Akşam batan güneş sabaha doğar

Anla artık Solmazgül ün dilinden', 'Sakın umudunu yitirme gönül Mecnun isen Leyla geçer çölünden İnsan gibi yaşa insan gibi öl İnsan-ı kamiller anlar halinden Bilirsin bu dünya...', ARRAY['Türk Edebiyatı','Şiir','Salim Solmazgül']::text[], 8.5, '{"poet":"Salim Solmazgül","poet_slug":"salim-solmazgul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/insan-i-kamiller-anlar-halinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rehavet Yağmurları', 'rehavet-yagmurlari-i-brahim-bayraktar-g7zjp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün yine parçalı bulutluyum, yıldızım kaydı, 

Bana hayat veren ne güneşti, ne ay’dı, 

Sevdaya susamış, çatlak dudaklarım, 

Hedefi gözlerinde gergin bir yaydı.

Ruhumda zelzeleler, 

Gözlerim alev alev...

İçimdeki fırtınalar isyana yelken açtı, 

Sıklet bulutlarından katre katre akan, 

Rehavet yağmurları sel oldu, 

Damarlarımı bastı.

Damarlarımdaki kan, deli dolu...

Ne bentler dayanır, ne setler, 

Önüne sur diksen kaç yazar, 

Yıkar her yeri, deler geçer.

Gönül kuşum uçtu gitti, 

Ellerimden kaçtı gitti, 

Benim gönlüm benden geçti, 

Ne yapsam nafile.

02.07.2003', 'Bugün yine parçalı bulutluyum, yıldızım kaydı,  Bana hayat veren ne güneşti, ne ay’dı,  Sevdaya susamış, çatlak dudaklarım,  Hedefi gözlerin...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/rehavet-yagmurlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredeydiniz', 'neredeydiniz-murat-demir-juoiw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vatandaşı söğüşleyen hırsızlar

Kanunları zedeleyen kansızlar

Utanmayan şerefsizler, arsızlar

Haysiyet dersinde neredeydiniz

Yalanlarla bol, bol, nutuk atanlar

Yedeğine her gün, servet katanlar

Haksız yere, yetim hakkı satanlar

Yurtaşlık dersinde neredeydiniz

Kurtlar sofrasında, yemek yiyenler

Yediyi zıkkıma, helal diyenler

Boşa ahkam kesen, vay sürüngenler

Hak hukuk dersinde, neredeydiniz

Yalan, dolan ile, fetva verenler

Senin vucudunda, cin var diyenler

Elin namusunu, zevk edinenler

Din ahlak dersinde, neredeydiniz

Bukalemun gibi, güne uyanlar

Neme gerek diye, yanda duranlar

Uyanık görünüp, hep uyuyanlar

Yurtta sulh dersinde, neredeydiniz

Kanun kaçakları, din tüccarları

Koruyanlar nerde, bu alçakları

Küçük cücelerin, kahramanları

Anayasa dersinde, neredeydiniz', 'Vatandaşı söğüşleyen hırsızlar Kanunları zedeleyen kansızlar Utanmayan şerefsizler, arsızlar Haysiyet dersinde neredeydiniz Yalanlarla bol, ...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/neredeydiniz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirin Gizemi', 'siirin-gizemi-naime-erlacin-g8701', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'şiir 

gül olur 

sevda olur 

aşk olur 

kederdir 

hasret olur

bir karanfildir sunulan

adı vuslat olur 

kâh boynu bükük menekşe 

kâh vahşidir kimi gün

âşığın göğsüne takılan

çılgın orkide 

titreyerek ihtiras olur

şiirler bazen 

bağ olur 

bostan olur 

(02 Temmuz 2003)', 'şiir  gül olur  sevda olur  aşk olur  kederdir  hasret olur bir karanfildir sunulan adı vuslat olur  kâh boynu bükük menekşe  kâh vahşidir k...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/siirin-gizemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nice Canlar Vere Vere', 'nice-canlar-vere-vere-salim-solmazgul-j7jp5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Savunuruz gerçekleri

Göğsümüzü gere gere

Uygarlığa yürüyoruz

Nice canlar vere vere

Bilimdir bizim gıdamız

Yer içeriz hiç kanmayız

Biz cahile inanmayız

Aydınlığı göre göre

Solmazgül der gülün canlar

Bize yakın mutlu günler

Karanlığı isteyenler

Düşünsünler kara kara', 'Savunuruz gerçekleri Göğsümüzü gere gere Uygarlığa yürüyoruz Nice canlar vere vere Bilimdir bizim gıdamız Yer içeriz hiç kanmayız Biz cahile...', ARRAY['Türk Edebiyatı','Şiir','Salim Solmazgül']::text[], 8.5, '{"poet":"Salim Solmazgül","poet_slug":"salim-solmazgul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nice-canlar-vere-vere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Darda Kalmadıkça', 'i-nsan-darda-kalmadikca-salim-solmazgul-zfz1j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gül dalında güzel imiş

Koparılıp solmadıkça

Bilinmiyor dostla düşman

İnsan darda kalmadıkça

Cahil şaşkın şaşkın gezer

Her sözü bir canı üzer

Gönül viraneye benzer

Gerçek aşkı bulmadıkça

Solmazgül der Mevla kerim

Elbet biter bu dertlerim

Ben o yare yar mi derim

Derde derman olmadıkça', 'Gül dalında güzel imiş Koparılıp solmadıkça Bilinmiyor dostla düşman İnsan darda kalmadıkça Cahil şaşkın şaşkın gezer Her sözü bir canı üzer...', ARRAY['Türk Edebiyatı','Şiir','Salim Solmazgül']::text[], 8.5, '{"poet":"Salim Solmazgül","poet_slug":"salim-solmazgul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/insan-darda-kalmadikca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖNÜL GÖZÜYLE BAKINCA (Düz Yazı)', 'gonul-gozuyle-bakinca-duz-yazi-naime-erlacin-62j7w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''İncelikler''den söz eden birisi düşünce ve sözcüklerin değerini anlattı bir gün. Onların en kıymetli mücevherlerim olduğunu fısıldadı kulağıma. Sözleri efsunlayıcı bir  hale gibi sardı dünyamı.

Kiminin malı mülkü parası; kiminin tutkuları; kiminin gençlik ve güzelliği;  bir başkasının ise bilgeliği veya bilgiçliği ön sıradaydı. Benim ilk tercihim ise, düşüncelerim oldu daima. Meğerse ne denli ucuzlatmış ve ne kolay dağıtmışım onları. İyi mi, kötü müdürler; yanlış veya doğru mudurlar, bilemem. Veya onları bu tür öznel kıstaslara vurmak hakça mıdır derseniz, onu hiç bilemem işte…

Düşünsel dünyamda uzun zamandır süregelen kaotik bir dönem geçirdiğimin farkındaydım. Ne yana dönsem kargaşa ve fırtına sarmıştı çevremi. Kavga ile kuşatılmıştım. Oysa söyleyecek bir sözüm, dillendirecek bir şarkım vardı, biliyordum. Zaman, zaman da vuruyordum sazın tellerine. Ama heyhat, hep yanlış adreslere postalıyordum kendimi.

O güne dek hayata karşı olan genel duruşum, zorunlu olarak “muhalif” yapmıştı beni. Muhalefet ise biraz hırçınlık ve biraz da  acımasızlık içerir doğasında. Vardığım noktada bunları kaldıramıyordum artık. İç barışı seven ve öyle yaşamayı seçen birisine düşüncelerini silah gibi kullanıp kavgaya girişmek hiç de uygun düşmüyordu. Öncelikle bunu fark ettim... Kavga ederken gerçek duyguları, ama aslında gerçeğin kendisini gözden kaçırıyordum. Bu ise beni büyütmek bir yana körleştirip sağırlaştırıyor; diğer bir deyişle giderek daha da eksik kılıyordu. Yeni ufuklara doğru, yepyeni bir yolculuğa çıkmalıydım. Yazılan yazılmış, çizilen çizilmiş, doğum sancıları bitmiş ve dönüşüm yaşanmıştı artık. Böylece beyaz bir sayfa koydum önüme. Bu kez yolum hangi adreslere varacaktı, görecektik bakalım.Yaşamın bu döneminde düğümler çözülüyor; kilitler  açılıyordu beynimde. Artık yalnızca yazmak istiyordum. 

Vardığım noktada, “geç kalmış olabilir miyim? ” diye sormuyorum bile. ''Geç'' nedir? ''Erken'' nedir? Biz karar verebilir miyiz buna? “Erken” in bittiği yerde “geç” mi başlar? Veya geç kalmamak için erken yola çıkmak mı gerekir? 

Ayrıca  yaşamsal süreçte göreceli olarak nerede durduğumuzu ne kadar biliyoruz?  Kendimizi, birbirimizi yeterince tanıyor muyuz? Hangi budala beni tanıyabilir; veya ben nasıl bir budalayım ki sizleri tanıyabileyim? Sorular, sorular; hiç bitmeyen ve yanıt bekleyen sorular. Hayatım boyunca yanıtlardan çok sorularla ilgilenmiştim. Şimdi ise sorular elimden tutmuş,  beni pek de iyi tanımadığım bir aleme doğru götürüyordu.

Bana sorarsanız eğer, tanımanın yolu gönül gözüyle bakmaktan geçer. O halde gönül gözümü açıyorum sonuna dek. Bu gözün değerini kavrayamayan dostlara ise şimdilik “hoşça kalın” diyorum. Onlar da sağ olsunlar. Belki bir gün, bir başka yerde; ama bu kez doğru adreste buluşuruz  bakarsınız. 

Kim bilebilir ki! 

Şimdilik yepyeni bir yolculuktayım. Söyleyebileceğim tek şey bu! 

Kalınız sağlıcakla…

(02 Temmuz 2003)  - ''Gençler İçin Denemeler'' Dosyasından', '''İncelikler''den söz eden birisi düşünce ve sözcüklerin değerini anlattı bir gün. Onların en kıymetli mücevherlerim olduğunu fısıldadı kulağı...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gonul-gozuyle-bakinca-duz-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyandım', 'uyandim-sair-masmavi-uouut', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yasak zamanların tatlı rüyalarındaydım

Hani o çocuklar kadar öncesiz

Çocuklar kadar sonrasız duygularda

Bir o kadar da çaresiz

Yasak zamanların tatlı rüyalarındaydım

Hani o kalabalıklar içinde yapayalnız

Ağustos sıcağında titrerken

Bir o kadar da umarsız

Uyandım....

Uyandım! 

26/6/2003', 'Yasak zamanların tatlı rüyalarındaydım Hani o çocuklar kadar öncesiz Çocuklar kadar sonrasız duygularda Bir o kadar da çaresiz Yasak zamanla...', ARRAY['Türk Edebiyatı','Şiir','Şair Masmavi']::text[], 8.5, '{"poet":"Şair Masmavi","poet_slug":"sair-masmavi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/uyandim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hal Diliyle', 'hal-diliyle-ensar-cevval-ndgaf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Martı acıktığı zaman

önce karın üstü iner suya

''''Ey deniz! duy midemin çğlıklarını

sun artık nimetlerini'''', der, hal diliyle

Ağaç susadığı zaman, 

en uçta kalan yaprağını

sallar nehire doğru

''Ey nehir! yüzünü dön bana

bak kurumaya yüz tuttu

en yeşil yaprağım bile'', der, hal diliyle.

İnsan öyle mi ya! 

acıkan martıyı doyurur vapur arkasında

en taze simitleri ile

susayan ağaca arklar yapar da

kendi susamışlığını, acıkmışlığını

anlatamaz birtürlü hal diliyle.', 'Martı acıktığı zaman önce karın üstü iner suya ''''Ey deniz! duy midemin çğlıklarını sun artık nimetlerini'''', der, hal diliyle Ağaç susadığı z...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hal-diliyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki Yarın...', 'belki-yarin-ogun-hakan-kucukunal-12ek1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Belki yarın gözyaşın susar

Bir el değer uykuna ansızın

Sis açılır, ışık taşar karanlığın üstüne

Ürpertisi kalır kaldırımlarda 

Yitip gitmiş zamanların sancısı.

Tütsülenmiş akşamlardır çaresizliğin

Tutsak bir dünde kelepçeler, acıtan

Yıkılır kendinde kurşuni zaman

Gri bir günü karşılar sokaklar

Kıvamı unutulmuş bir avuç kan

Anımsatır yeniden yaşam sancını.

Belki yarın gözyaşın susar

Dal kırılır, ağaç yalnızlaşır, yol biter

Salıncaklar soğur kimsesiz saatlerde

Bir dalga vurur uykunun en derin yerine

ÇIğlık çığlığa martılar, karabataklar, poyraz...

Yorulan küreklerde el değişir, ter değişir

Eski zaman şarkıları değişir

Dün değişmez bir tek

Yarın değişir.

Belki yarın gözyaşın susar

Tuz kayar yanaklarından

Güneş akşamdan kayar

Bir dağdan kar kayar

Rüzgarda uçurtma

Denizde gemiler kayar

Kampanalar, sirenler, deniz fenerleri

Devriyelerin kirli ayak izleri

Duvar diplerinde unutulmuş çocuk sesleri...

İlk kimin soluğu kesildi? 

Kim unuttu aşkını durakta? 

En uzun kim ağladı trene? 

Belki yarın

Gözyaşın

Susar

Kurumuş yaprakların tortusu dolar

Yalnız yürüyen ayak diplerine

Ateşin içinden geçen her yolculukta

Bir salkım su sallanır yaprakların ömrüne

Yapraklar ilk solouğudur hayatın

Yapraklar kapısıdır durakların

Uzadıkça raylar gözyaşları da uzar...

Duraklar koyu yeşil mezarlık

Duraklar ıssızlık

Duraklar kül

Kesik bir dil duraklar

Beklenen gün kokusu

Eylül kokusu diyelim

Nisan kokusu

Bir akşamüstü kokusu

Bir el değer büyümüşlüğüne ansızın

Gözyaşın susar belki yarın

Bütün kokuları toplarsın bahçende

Saksılardan taşan akşam sefaları

Fulyalar, menekşeler, çiğdemler

Ne ürpertisi kalır o saat kaldırımlarda

Ne zamanın kelepçe acısı

Eğilip dokunabildikçe bir çiçeğin rengine

Belki yarın

Gözlerin Susar

Kana kana içersin gökyüzünü

Bir utkuda toplandıkça bütün bakışlar.', 'Belki yarın gözyaşın susar Bir el değer uykuna ansızın Sis açılır, ışık taşar karanlığın üstüne Ürpertisi kalır kaldırımlarda  Yitip gitmiş ...', ARRAY['Türk Edebiyatı','Şiir','Ogün Hakan Küçükünal']::text[], 8.5, '{"poet":"Ogün Hakan Küçükünal","poet_slug":"ogun-hakan-kucukunal","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/belki-yarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Anda', 'su-anda-evrim-boyukelhan-yrhum', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani hiç güneş görmemiş dağlar var ya

Oralarda ki kar gibiyim

Şu anda eriyorum

Hani baharın gelmesiyle yuvalarına dönen kuşlar var ya

Onlar gibiyim

Şu anda içimde bir heyecan var

Hani şırır şırır akan akarsular var ya

Önlerinde hiç bir engeli kabul etmeyen

Onlar gibiyim

Hani yuvalarından ayrılan göçmen kuşlar var ya

Onlar gibiyim

Baharı bekliyorum', 'Hani hiç güneş görmemiş dağlar var ya Oralarda ki kar gibiyim Şu anda eriyorum Hani baharın gelmesiyle yuvalarına dönen kuşlar var ya Onlar ...', ARRAY['Türk Edebiyatı','Şiir','Evrim Böyükelhan']::text[], 8.5, '{"poet":"Evrim Böyükelhan","poet_slug":"evrim-boyukelhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/su-anda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalar', 'sevdalar-evrim-boyukelhan-910em', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdalar kolay olmamalı

İnsanı gerektiğinde bir mecnuna

Gerektiğinde bir leylaya...

Sevdalar kolay olmamalı

İnsanı gerektiğinde bir kar tanesine

Gerektiğinde buharlaşan bir damla suya...

Sevdalar kolay olmamalı

İnsanı gerektiğinde susuz kalan bir balığa

Gerektiğinde balsız kalan bir arıya...

Sevdalar kolay olmamalı

İnsanı gerektiğinde yuvasız kalan bir kuşa 

Gerektiğinde güneşsiz bir gökyüzüne...', 'Sevdalar kolay olmamalı İnsanı gerektiğinde bir mecnuna Gerektiğinde bir leylaya... Sevdalar kolay olmamalı İnsanı gerektiğinde bir kar tane...', ARRAY['Türk Edebiyatı','Şiir','Evrim Böyükelhan']::text[], 8.5, '{"poet":"Evrim Böyükelhan","poet_slug":"evrim-boyukelhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevdalar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazı Günler', 'bazi-gunler-evrim-boyukelhan-z0hdq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazı günler oluyor

Karadeniz gibi oluyorum

Hırçınlaşıyorum

Sana ulaşmak için dalgalarla yarışıyorum

Bazı günler oluyor

Kızıl Deniz gibi oluyorum

Durgunlaşıyorum

Senin gelmeni bekliyorum

Bazı günler oluyor 

Akdeniz gibi oluyorum

Hasret içinde bekliyorum

Sevdalıları seyrediyorum', 'Bazı günler oluyor Karadeniz gibi oluyorum Hırçınlaşıyorum Sana ulaşmak için dalgalarla yarışıyorum Bazı günler oluyor Kızıl Deniz gibi oluy...', ARRAY['Türk Edebiyatı','Şiir','Evrim Böyükelhan']::text[], 8.5, '{"poet":"Evrim Böyükelhan","poet_slug":"evrim-boyukelhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bazi-gunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar ve Sevdalar', 'daglar-ve-sevdalar-evrim-boyukelhan-qi25d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şu dağlara imrenek bakıyorum! 

Baktığın zaman çok yakınlarda 

Elini uzatsan dokunacakmış gibi

Ama ulaşmaya çalışırsan 

Birçok tepe  yol ve akarsu geçmek zorundasın

Sevdalar da dağlar gibi

Baktın zaman çok yakınlarda 

Elini uzatsan dokunacakmış gibi

Ama ulaşmaya çalışırsan

Birçok engel şahıs ve zaman geçmek zorundasın', 'Şu dağlara imrenek bakıyorum!  Baktığın zaman çok yakınlarda  Elini uzatsan dokunacakmış gibi Ama ulaşmaya çalışırsan  Birçok tepe  yol ve a...', ARRAY['Türk Edebiyatı','Şiir','Evrim Böyükelhan']::text[], 8.5, '{"poet":"Evrim Böyükelhan","poet_slug":"evrim-boyukelhan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/daglar-ve-sevdalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader', 'kader-evrim-boyukelhan-k4pc2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç ummadığın bir anda

Hiç ummadığın bir insanı karşına çıkarır

Belki tekdüze giden hayatına

bir neşe getirir

Baharda çiçek açan doğaya dönersin

Belki de son hızla giden hayatına 

bir set duvar ördürür

Hayatını kara kışa döndürür

Ama biliyorum ki

Sen yine de beklemeye değersin 

Kader', 'Hiç ummadığın bir anda Hiç ummadığın bir insanı karşına çıkarır Belki tekdüze giden hayatına bir neşe getirir Baharda çiçek açan doğaya döne...', ARRAY['Türk Edebiyatı','Şiir','Evrim Böyükelhan']::text[], 8.5, '{"poet":"Evrim Böyükelhan","poet_slug":"evrim-boyukelhan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kader-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Kuyunun Kör Aşkı', 'kor-kuyunun-kor-aski-hatem-gokcek-80631', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dogan çocuk nasıl habersizse dünyadan 

Öyle habersizim işte senden

Yemin olsun şahitti, seni seviyorum dediğimgecelere yıldızlar

Aşinaydı beni sana getiren ayakları

Ömrümden ömür çaldın İstanbul Gözlüm

Birime bin kattın

İstanbul uda, sevdamıda o gece sen yaktın

Şimdi hangisine yanarım gün gece

Konuşmadan adınla başlayan geceleri

Kime, niye anlatırım İstanbul Gözlüm

Kanıyan avuçlarımı kime sardırırım

O gece

Kapının önünde durup allaasmarladık

Dediğin gece 

Kimi şahit yazarım terkedişine

Sen görmesende usul usul yavaş yavaş kanarım

Susarım anlatamam İstanbul Gözlüm

Şimdi martıları kim doyurur

Kim  Kızkulesinin bekçisi olur

Terkettiğin sevdayı kim korur gözbebekleriyle

Kim dokunur bıraktığın ellere

Baktığın gözlere kim bakar senin gibi

Aşkı körkuyuya atmaksa niyetin

Bir ömür boyu ip atan olmasın

Bırak adım kör kuyunun kör aşkı kalsın', 'Dogan çocuk nasıl habersizse dünyadan  Öyle habersizim işte senden Yemin olsun şahitti, seni seviyorum dediğimgecelere yıldızlar Aşinaydı be...', ARRAY['Türk Edebiyatı','Şiir','Hatem Gökcek']::text[], 8.5, '{"poet":"Hatem Gökcek","poet_slug":"hatem-gokcek","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kor-kuyunun-kor-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salıtesi', 'salitesi-melek-midikoglu-zazfa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ilık bir yaz mevsimi

Mavilere aldı, yeşillere verdi, 

Varlığın beni serinletti! 

Tutuk aşkın ruhuma aktı

Okyanus kadar istedim ya, 

Geldi içti doyamadı! 

Sana ben umut verdim, 

Yıldızlar misali düşlerimi

Kapına serdim.

Olmadı...

Gittim. 

Bölünme, gelme akma gönlüme! 

Sen salı''da ertesiye gittin; 

Sonra sevdin...

Bittin.', 'Ilık bir yaz mevsimi Mavilere aldı, yeşillere verdi,  Varlığın beni serinletti!  Tutuk aşkın ruhuma aktı Okyanus kadar istedim ya,  Geldi iç...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/salitesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidenin Ardından', 'gidenin-ardindan-omer-bayhan-v232k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gidiyorsan eğer, 

geri dönüp bakma ne olur.

Ela ışıltıların güneşinde, 

kavruk yanığı istemiyorum.

Gidiyorsan eğer, 

dönüp gülümseme ne olur.

Ak ışıltıların arasında, 

müzip çığlık istemiyorum.

Gidiyorsan eğer, 

ne olur açma yakıcı kollarını.

Kızıl uzantılar arasında, 

boğuşan titreklik istemiyorum.

Eğer gidiyorsan, 

sadece yüreğime bak.

            izle gözyaşlarımı, 

şaşırdığım yolları izle, 

bakışlarımda ki donukluğu hisset..

Ve bil ki; 

    her harfim arasında gizli, 

             her kelimemde sır, 

                   her düşüncemde özlem olduğunu..', 'Gidiyorsan eğer,  geri dönüp bakma ne olur. Ela ışıltıların güneşinde,  kavruk yanığı istemiyorum. Gidiyorsan eğer,  dönüp gülümseme ne olur...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bayhan']::text[], 8.5, '{"poet":"Ömer Bayhan","poet_slug":"omer-bayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gidenin-ardindan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen Hırçın, Bazen Kuzu', 'bazen-hircin-bazen-kuzu-omer-bayhan-qb259', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bazen bir aç kurt gibisin, bazen meleyen kuzu, 

bazen hırçın bakışlı, bazen çocuksu..

Berrak bir kızıllıkta çırpınır yüreğin.

sade ve yumuşak, tüy hafifliğinde.

Kör eden ışıltılarla bakar gözlerin, 

derin ve ıslak, mıknatıs çekerinde.

Kayısı baharında kokar bedenin, 

yeşil ve sarımsı, bir orman engininde.

Bazen bir aç kurt gibisin, bazen meleyen kuzu, 

bazen hırçın bakışlı, bazen çocuksu..', 'Bazen bir aç kurt gibisin, bazen meleyen kuzu,  bazen hırçın bakışlı, bazen çocuksu.. Berrak bir kızıllıkta çırpınır yüreğin. sade ve yumuşa...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bayhan']::text[], 8.5, '{"poet":"Ömer Bayhan","poet_slug":"omer-bayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bazen-hircin-bazen-kuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-hikmet-karakus-7n4j0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu şehirde acı çeksem de

               gözlerim iki düğme

               hep  aklımı iliklerim körlüğüme, 

Gizlerim duygularımı

            kapatırım Kızkulesi''ne, 

Şahidim Galata Kulesi

              hep kızarır utançtan, 

Göz kırpar Ahırkapı Feneri

        çok şey görmüş gibi ispiyondan, 

İstanbul gizemli mi gizemli bir güzel

        hem de kahpe 

               kimleri yakmadı ki..

Ama öldüğümde yine de Boğaziçi''nden

               selam götürmek isterim Orhan Veli''ye... 

      

(İst.1996)', 'Bu şehirde acı çeksem de                gözlerim iki düğme                hep  aklımı iliklerim körlüğüme,  Gizlerim duygularımı            ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/istanbul-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlkyaz', 'i-lkyaz-nihat-albayrak-t1343', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlk yazın sürgün verdiği günler, 

Buğday tarlasında gelincikler, 

            Öbek öbek, 

Bir serçe bir şeyler söylüyor

            Kıpır kıpır, 

Yüreğimde bir çoşku, bir fırtına; 

            Cilvelerin geliryor aklıma, 

            Gelincikler dudakların gibi, 

ilk yazın sürgün verdiği günler, 

Sabahın örtüsü kalkmış, 

Ağaçlar çiceğe vurmuş, 

Ufuk cizgisinde kuşlar kanat çırpıyor, 

O tarlalarda umut çıçekleri de açmıştı, 

Gözlerine baktım; 

Kirpiklerinde çiğ damlaları yoktu.

Mutluydum, mutluydun, mutluyduk..

İlk yazın sürgün verdiği günler, 

Yıldızlar kıyamet gibi gökyüzünde, 

Bir sabah; yarı küskün Kumkapıda uyanıyorum, 

            Sahilde güneş yanığı yüzlü balıkçılar, 

Hüzün; kırılgandı yüreklerde, 

Sen; anlamsız kavgalardan yorgun düşmüş, 

             Denizi seyrediyordun.

Gözlerin uzak bir aşkın rengindeydi, 

İçinde bir sevinç, bir tutku, 

Biliyorum aşktı hüküm süren o zamanlarda 

Gözbebeklerinde kırlangıçlar havalanıyordu...', 'İlk yazın sürgün verdiği günler,  Buğday tarlasında gelincikler,              Öbek öbek,  Bir serçe bir şeyler söylüyor             Kıpır kı...', ARRAY['Türk Edebiyatı','Şiir','Nihat Albayrak']::text[], 8.5, '{"poet":"Nihat Albayrak","poet_slug":"nihat-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ilkyaz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-berna-yilmaz-yvgxr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tut ki hiç karşılaşmadık seninle

Açılmadı paslı kilitleri kapımın

Senin hediyen değil yüzümdeki çizgiler

Ne güldürdün ne ağlattın

Tut ki hiç duymadım sesini

İçimden taşıp bedenine akmadım

Gözlerinin aksiyle şenlenmedi gözlerim

Dualarımla buluşmadı adın

Tut ki hiç öğretmedin sabretmeyi

Hiç bükülmedi boynum, bilmedim kabullenmeyi

Nefesime düğümler atmadı ayrılık

Seni düşündükçe ferahlamadım', 'Tut ki hiç karşılaşmadık seninle Açılmadı paslı kilitleri kapımın Senin hediyen değil yüzümdeki çizgiler Ne güldürdün ne ağlattın Tut ki hiç...', ARRAY['Türk Edebiyatı','Şiir','Berna Yılmaz']::text[], 8.5, '{"poet":"Berna Yılmaz","poet_slug":"berna-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sitem-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hediye', 'hediye-berna-yilmaz-fckld', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Can''a

''Hayat sana yeni bir sabah verir

ya da yeni bir insan''

Gecenin mührüyle kapansa da gözlerin

Rüyalar verir en derin uykulara sızan

Hayat sana bir nefes verir

Değdiği yeri yakan

Bir yürek kumbara misali

İsyanla dolan..', 'Can''a ''Hayat sana yeni bir sabah verir ya da yeni bir insan'' Gecenin mührüyle kapansa da gözlerin Rüyalar verir en derin uykulara sızan Haya...', ARRAY['Türk Edebiyatı','Şiir','Berna Yılmaz']::text[], 8.5, '{"poet":"Berna Yılmaz","poet_slug":"berna-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hediye-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hareler', 'hareler-naime-erlacin-nlsmf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hareler büyüyor rüyamda

büyüyor hareler 

ruh yalnızlığımda

bir hayat eskittik

aşkla şiire 

yenik düştük 

fikrim oynaşıyor 

içeri dışarı zihnimin çıkrığında 

büyüyor hareler

düşler büyüyor

su uyanık

gül uykuda

zaman ise zayi 

hayat boşluğunda! 

(02 Temmuz 2003)', 'hareler büyüyor rüyamda büyüyor hareler  ruh yalnızlığımda bir hayat eskittik aşkla şiire  yenik düştük  fikrim oynaşıyor  içeri dışarı zihn...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hareler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-berna-yilmaz-wh12m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gece ay doğmadı gökyüzüme

Kum gibi dağıldı ellerimde yıldızlar

Yoruldum ardında bitmeyen düşlerimin

İçimde bir karanlık geceden daha siyah

Kayboluyor o deli kahkahalar sesimden

Artık şekillenmiyor hayalimde bulutlar

Bakınca gözlerimin aynadaki aksine

Sadece can çekişen ateş böcekleri var

Kaçırdım elimden uçan balonlarımı

Gece korkularıma ilaç değil masallar

Ömür boyu mutluluk eski, koca bir yalan

Acı bir tat bırakıp gidiyor mutluluklar

Çapa tutmuyor şimdi hiçbir sevda yürekte

Artık ufukta değil gözlerimde uzaklar

Bu düğüm çözülmüyor bir değil bin nefeste

Varsın eriyiversin avucumda yıldızlar', 'Bu gece ay doğmadı gökyüzüme Kum gibi dağıldı ellerimde yıldızlar Yoruldum ardında bitmeyen düşlerimin İçimde bir karanlık geceden daha siya...', ARRAY['Türk Edebiyatı','Şiir','Berna Yılmaz']::text[], 8.5, '{"poet":"Berna Yılmaz","poet_slug":"berna-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gece-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma! ! !', 'unutma-ender-guncelik-2yz01', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bakalım hatırlayacak mısın beni? 

O son telefonda söz verdiğinden beri geçen zamanda 

Unuttun mu acaba? 

Yoksa hala hatırlıyor musun yanan şu kalbi? 

Yüreğime söz geçirebilsem hiç durmam arardım seni

Ama ya unuttuysan, ne yaparım bundan sonra? 

İnan sevmediğini söyleyince bu kadar üzülmemiştim, en fazla hayattan umudumu kestim

Ya şimdi, o sevdiğini söyleyen gözlerde unutulmuş bulursam kalbindeki yeri

Ölüm bile paklamaz inan bana, dünya ve ahirette yerim yoktur o saatten sonra

Ne olur unutma beni

Senden şimdiye dek ne istedim? sevgi dışında 

Sevmeyi çok gördün, bana nasip etmedin ama kızmıyorum sana 

Sadece unutma, hatırla beni

Sokakta gördüğün bir ayyaşın simasını hatırladığın kadar unutma beni, unutma...', 'Bakalım hatırlayacak mısın beni?  O son telefonda söz verdiğinden beri geçen zamanda  Unuttun mu acaba?  Yoksa hala hatırlıyor musun yanan ş...', ARRAY['Türk Edebiyatı','Şiir','Ender Günçelik']::text[], 8.5, '{"poet":"Ender Günçelik","poet_slug":"ender-guncelik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/unutma-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorum...', 'bilmiyorum-ender-guncelik-9ukif', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiç mutluyken bir satır bile karalayamadım

“Mutluyum, seviyorum, seviliyorum” demeyi hiç bilemedim

Ya da şiir yazmak, aşk yarası alan gönüller içindi 

Bu yüzden gülerken hiç kağıt kalem almadım elime, oturup yazmadım

Ama bir dakika şimdi hatırlıyorum

Ben şu hayatta hiç mutlu olamadım ki

Ya seven kalpler yalancı çıktı ya da hiç sevilmedim

Sevgiyi sadece sevdiğim için biliyorum

Hele en büyük aşkı bulduktan, yani en büyük yarayı aldıktan sonra 

Kendimi unuttum ben, 

Yaşadım mı, öldüm mü ya da en sahte halimle güldüm mü? Hiç bilmiyorum

Yani şiirler belki gülerken de yazılıyor, 

Ama ben yazamıyorum, çünkü gülmek nedir? Bilmedim, bilmiyorum...', 'Hiç mutluyken bir satır bile karalayamadım “Mutluyum, seviyorum, seviliyorum” demeyi hiç bilemedim Ya da şiir yazmak, aşk yarası alan gönüll...', ARRAY['Türk Edebiyatı','Şiir','Ender Günçelik']::text[], 8.5, '{"poet":"Ender Günçelik","poet_slug":"ender-guncelik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bilmiyorum-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayaldir Hatırlayışlar', 'hayaldir-hatirlayislar-burhan-gokoguz-03p12', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayaldir hatırlayışlar

Gözlerinden dökülen yaşa bir buse düşer

Tenini okşayan zaman

Eski bir tahta kapının arkasında saklanır

Seyre dalarım bir çınarın gölesinde, hatıraları

Ve şahin gözleriyle uzakları grmeye çalışırım

Uzaklar, uzaklar ise bulanık

Sadece arap bülbüllerinin aşk cıvıltıları

Gelir, konar yüreğimin yıllanmış dallarına

Işıkların gölesinde raks eden insanları görür

Görür de gülerim gülerkende ağlarım

Güneşi balçıkla sıvamaya çalışırlar

Ay ışığını kara bulutlarla örtmeye

Çalışırlarda mutlu olurlar

Sonbaharda göç eden kazları

Sararmış yapraklarını döken çınarları düşün

düşün de üzül üzülürken de ağla ve feryad eyle

çünki; 

Zamansız geçen zaman avucumuzun içinde

Yıllarımızı, günlerimizi, hatıralarımızı, hayallerimizi

Ve yüreğimizde büyüttüğümüz, ilahlaştırdığımız

Aşklarımızı elimizden alır

O karabasanlarla dolu rüyadan uyanırken

Kendimi gecenin tekerlekli sandalyesinde bulur

Yakamozlarla köpüklenen denize

Buğulu gözlerle iki damla gözyaşı bırakırım

(Manisa 02.07.2003)', 'Hayaldir hatırlayışlar Gözlerinden dökülen yaşa bir buse düşer Tenini okşayan zaman Eski bir tahta kapının arkasında saklanır Seyre dalarım ...', ARRAY['Türk Edebiyatı','Şiir','Burhan Gökoğuz']::text[], 8.5, '{"poet":"Burhan Gökoğuz","poet_slug":"burhan-gokoguz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hayaldir-hatirlayislar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Basildik', 'basildik-huseyin-poyraz-5qr1a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sesiz sedasiz parkta

Karsilikli asildik, 

Yemyesil bir yatakta

Tukenmeyen fasildik...

Sicacik bir geceydi, 

Bakislar bilmeceydi, 

Elin elime degdi, 

Kasim kasim kasildik! ..

Mehtabin ortasin da, 

Calinin arkasin da, 

Zevkin uc noktasin da, 

Soylesene nasildik? ..

Bir tek bitkiler gordu, 

Bedenler sefa surdu, 

Agustos''un on dort u, 

Ay dede''ye basildik! .. 

Ay dede cok lafciymis, 

Hem de intikamciymis, 

Dili sanki kamciymis, 

Mansetlere basildik...

agustos 1994', 'Sesiz sedasiz parkta Karsilikli asildik,  Yemyesil bir yatakta Tukenmeyen fasildik... Sicacik bir geceydi,  Bakislar bilmeceydi,  Elin elime...', ARRAY['Türk Edebiyatı','Şiir','Huseyin Poyraz']::text[], 8.5, '{"poet":"Huseyin Poyraz","poet_slug":"huseyin-poyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/basildik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satış', 'satis-ahmet-kurt-siech', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Fabrika, işletme her türlü emlak, 

Satıyorum, satıyoooruuum, saaaaatttıııım. 

Sizlerde varsınız hiç yok mu merak, 

Satıyorum, satıyoooruuum, saaaaatttıııım. 

Yolları kanımla kazıdım önce, 

Hesaplar yaparım inceden ince, 

Mal benim size ne kendi keyfimce, 

Satıyorum, satıyoooruuum, saaaaatttıııım. 

Değeri önemsiz müşteri olsun, 

Kasalarım cebim ve cüzdan dolsun, 

Ormanlar kesilmiş, solarsa solsun, 

Satıyorum, satıyoooruuum, saaaaatttıııım. 

Anılar kötüydü, tarihi geçtim, 

Anıtları mezar, sitleri seçtim, 

Yumdum gözlerimi ağzımı açtım, 

Satıyorum, satıyoooruuum, saaaaatttıııım. 

Bana ne gelecek, yeni kuşaktan, 

Hızla döneceğim inan kavşaktan, 

Müşterim hokkabaz ve de yavşaktan, 

Satıyorum, satıyoooruuum, saaaaatttıııım. 

Gazete, dergiler övgüler düzer, 

Yandaşlarım yandan kıyıdan yazar, 

Ölüye gömecek kalmasın mezar, 

Satıyorum, satıyoooruuum, saaaaatttıııım. 

Can mı verdim sanki, vatan edecek, 

Bunlar işgalciydi zaten gidecek, 

Babamsa uzaydan haber verecek, 

Satıyorum, satıyoooruuum, saaaaatttıııım. 

Hicive sığmıyor boyutlar büyük, 

Dağıtın tümseği kalmasın höyük, 

Asıl ondan sonra en büyük göçük, 

Satıyorum, satıyoooruuum, saaaaatttıııım. 

Kurdoğlu bu derde derman değilsin, 

Sen dik tut başını, onlar eğilsin, 

Şu namluya çifte sular verilsin, 

Satıyorum, satıyoooruuum, saaaaatttıııım.', 'Fabrika, işletme her türlü emlak,  Satıyorum, satıyoooruuum, saaaaatttıııım.  Sizlerde varsınız hiç yok mu merak,  Satıyorum, satıyoooruuum,...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/satis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yesim...Yesim...', 'yesim-yesim-i-brahim-ozcan-wsxil', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gidiyorsun... aciyor yüregim / hüzün dolu 

Agliyorsun... yaniyor içerim / gözün dolu 

Kal... demek gelir de içerimden 

Hal... gitmekse  ne gelir elimden 

Oy Yesim Yesim, Sevdan bugulu dert çekisim 

Vay Yesim Yesim, Durmaz gözlerimden yasim 

Çal demek kolay bitmeyen sarkimizi 

Eller duymasindi ölümcül askimizi 

Buralar sensiz, sen bensiz, ben kimsesiz 

Besteleri basima kalkar, sarkilar densiz 

Gel Yesim Yesim, Sevdan ekmegim asim 

Gül Yesim Yesim, yakar beni bir bakisin', 'Gidiyorsun... aciyor yüregim / hüzün dolu  Agliyorsun... yaniyor içerim / gözün dolu  Kal... demek gelir de içerimden  Hal... gitmekse  ne g...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özcan']::text[], 8.5, '{"poet":"İbrahim Özcan","poet_slug":"i-brahim-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yesim-yesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-yasar-aslan-5lpf1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'benzi solmuş  tuzlanmamış bir derinin  güneşe bırakılmış hali

unutma bahanesiyle terkedilmişlik 

gecedeki dolunay ve yakamoz 

tam bir hüzün senfonisi 

gece ağaç gölgesini kim sevdi ki? 

kim çiçekler topladı.! 

tam görünmeyen nefretin özlemle kucaklaşmış hali

sesin kuyu dibine inerken çıkardığı boğuk bir yankının

yüreğe çığlıkla verilen melodisidir.

birazda ezgidir, 

kuşların sabahki ritmik dansına benzer 

rüzgarın gitar dinletisidir aşk...', 'benzi solmuş  tuzlanmamış bir derinin  güneşe bırakılmış hali unutma bahanesiyle terkedilmişlik  gecedeki dolunay ve yakamoz  tam bir hüzün ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Aslan']::text[], 8.5, '{"poet":"Yaşar Aslan","poet_slug":"yasar-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-158-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraf', 'i-tiraf-charles-bukowski-47f2a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir kedinin yatağa sıçramasını

bekler gibi

beklerken

ölümü

karım için çok

üzülüyorum

sertleşmiş

solgun

bedenimi

görecek

bir kez, belki de 

iki kez sarsacak:

''Hank! ''

cevap vermeyecek

Hank.

ölüm değil beni

endişelendiren, bu hiçlik

yığını ile kalacak olan

karım.

ama birlikte uyuduğumuz

bütün o gecelerin

hatta yararsız tartışmaların

bile

harikulade şeyler

olduğunu bilmesini istiyorum

ve bu güne kadar

söyleyemediğim

o zor sözcükler

artık söylenebilir:

seni

seviyorum.', 'Bir kedinin yatağa sıçramasını bekler gibi beklerken ölümü karım için çok üzülüyorum sertleşmiş solgun bedenimi görecek bir kez, belki de  i...', ARRAY['Türk Edebiyatı','Şiir','Charles Bukowski']::text[], 8.5, '{"poet":"Charles Bukowski","poet_slug":"charles-bukowski","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/itiraf-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Demet Yağmur', 'bir-demet-yagmur-emrah-polat-97646', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağmurlu bir akşam, 

Dışarı da fırtınalar kopuyor, 

İçimdeki fırtınalar gibi.

Yerler ıslanıyor, 

Rüzgâr almış başını gidiyor, 

Yüreğimdeki dertler gibi.

Camdan insanları seyrediyorum, 

Yağmur yağıyor üzerlerine.

Islanmak istemiyorlar, 

Sağa sola kaçıyorlar, 

Tıpkı senin benden kaçtığın gibi aşkım.

Yağmur damlacıkları göz yaşlarım, 

İçime akıttığım, 

Sana nedenini açıklayamadığım gözyaşlarım.

Kaçanlar ise, 

Ben ve benim dert ortaklarım.

Yağmur bitecek aşkım, 

Bu fırtınalar, bu rüzgâr elbet dinecek.

Ama benim sana olan sevgim

Ve gözyaşlarım, 

Hiçbir zaman bitmeyecek.

Yine üşüme geldi içime, 

Seni hayâl ederken.

Soğukta titreyen insanlar gibi, 

Gücüm kalmadı, 

Artık sabredemiyorum, 

Duygularını itiraf edemeyen aşıklar gibi.

Bak güneş açıyor, 

Bulutlar yavaş yavaş gidiyor, 

Sana dememişmiydim aşkım, 

Yağmur dindi, fırtınadan ise eser yok, 

Döndü gene yaşama insanlar, 

Kimi rol yapıyor, kimi gerçekten seviyor, 

Tıpkı benim seni sevdiğim gibi aşkım...

Gün boyunca yaptıklarım işte bunlar, 

Bir parça beyaz kâğıt, 

Üzerinde kalemim oynar.

Tüm duygularım akar gider bir yağmur gibi

Ve gözyaşlarım son noktayı koyar...', 'Yağmurlu bir akşam,  Dışarı da fırtınalar kopuyor,  İçimdeki fırtınalar gibi. Yerler ıslanıyor,  Rüzgâr almış başını gidiyor,  Yüreğimdeki d...', ARRAY['Türk Edebiyatı','Şiir','Emrah Polat']::text[], 8.5, '{"poet":"Emrah Polat","poet_slug":"emrah-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/bir-demet-yagmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem''e', 'annem-e-ensar-cevval-o1kqf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kapkaranlık bir geceye düşmüş nur 

bir cennet bahçesi miydi saklandığım yer? 

ve, bir tıkırtı; huzur veren zamanların başlangıcı

bir damlanın yaprağa verdiği huzur.

Aydınlığa açarken gözlerimi, ağlayarak

bir Melek durmuştu başucumda mütebessim

bembeyaz ırmaklarda doyururken bedenimi

o tıkırtıyı duydum; sol göğsündeyken nefesim.

Asumanın berraklığı vardı nurlu yüzünde

parmaklarına geçirdiği bulutlarla okşarken tenimi; 

ince bir esinti sandım, ürperti sardı tüm bedenimi

ve Melekleri gördüm, gıpta ile seyrederken annemi

Sen mi Melektin, yoksa penceremden gözleyenler mi? 

geceleri yanımda olduğunu bilmek adına ağlayışlarımı

yüzünde tebessüm görmek adına oynayışlarımı

mukayese ederken, penceremde kimsecikler kalmamıştı.

Şimdi büyüdüm; serpildi tomurcuk evladın

bir bilsem ömrümün senden fazla mühletini

ve bilsem ardımdan yas tutup ağlamayacağını

hediye der altın tabakta sunardım yaşamdaki payımı.

''''Tüm Annelere ''''', 'Kapkaranlık bir geceye düşmüş nur  bir cennet bahçesi miydi saklandığım yer?  ve, bir tıkırtı; huzur veren zamanların başlangıcı bir damlanı...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/annem-e-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Sen Koy', 'adini-sen-koy-emrah-polat-eqh94', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün yine yapayanlızdım, 

Eski günlerimi hatırladım biran, 

Melul melul ağladım sen yokken.

Eğer birgün gerçekten seversen, 

Tıpkı benim seni sevdiğim gibi, 

Ne yapacağını bilemiyecek olursan, 

Adeta benim gibi çıkmaza girersen, 

Sevipte değer bulamadığın vakit, 

Işıkların söndüğünü anlayacaksın.

Lakin zaman sin için artık ilerlemiyecek, 

Masumiyetin yerini öfkeye bırakacak, 

Izdırap çekmeye bailayacaksın.

Şuan da sana söyliyemediğimi 

Belki ileride fısıldayacağım kulağına, 

Uykudan kalktığın da, 

Dönüp arkana bir bakacaksın ki, 

Utanacaksın kendinden, 

Yanlış yaptığını anlayacaksın er ya da geç, 

Gene de bunu söylememe engel olamayacaksın, 

Uyan arık Demet uyan da, 

Yukarıda aşağıya doğru

Ağır ağır oku

! 

! 

!', 'Dün yine yapayanlızdım,  Eski günlerimi hatırladım biran,  Melul melul ağladım sen yokken. Eğer birgün gerçekten seversen,  Tıpkı benim seni...', ARRAY['Türk Edebiyatı','Şiir','Emrah Polat']::text[], 8.5, '{"poet":"Emrah Polat","poet_slug":"emrah-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/adini-sen-koy-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharlar Yaratıyorum Gönlümde', 'baharlar-yaratiyorum-gonlumde-ensar-aktas-2fxeo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hatırlıyor musun sana rastladığım o ilk geceyi

Sabah üçlere kadar süren ateşli sohbetlerimizi

Anlattıkların içimi gıdıklayıp hoplatırken yerinden

Kalbime düşürdüğün o dayanılmaz aşk ateşini

Hatırlıyor musun hani beni o ilk aradığın akşamı 

İstasyon merdivenlerinden iniyorken heyecanla aşağı 

Kalbim benden üç basamak önde inmeye başlamıştı 

Ve ben ona yetişmek için koşuyordum peşinden

Hatırlıyor musun o ilk buluştuğumuz cumartesiyi

İstasyon da bekliyordum, sense kaçırmıştın treni

Dayanamayıp hasretine çıkıp geldim de ayağına dek

Elini bile tutamadan kucaklayıp öptüğümü seni

Hatırlıyor musun o soğuk ellerini ilk tutuşumu

Serinlettiği halde beni, kalbimin yanıp tutuşuşunu

Dünyalar benimdi, sanki bir çocuk sevinişiydi bu

Tombişim diye okşayıp tattırırken o ilk öpüşünü

Hatırlıyor musun o ilk veda sarılmalarını, öpüşlerini

Gözlerim dolu dolu oldu da bırakamadım ellerini

Nasılda söküp yerinden götürdün kalbimin yarısını 

Tesellimse bana bırakman oldu kendi kalbinin yarısını

Hatırlamak ne kelime, biliyorum hiç unutamadığını 

Heran her saniye beni düşünüp beni arzuladığını 

Bense heran seni yaşıyorum dolu dolu kalbimde

Ve baharlar yaratıp gönlümde sana koşuyorum düşlerimde

Rotterdam,17.02.2002', 'Hatırlıyor musun sana rastladığım o ilk geceyi Sabah üçlere kadar süren ateşli sohbetlerimizi Anlattıkların içimi gıdıklayıp hoplatırken yer...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/baharlar-yaratiyorum-gonlumde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toplu İğne', 'toplu-i-gne-ensar-aktas-8rrw1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir toplu iğne

Senelerdir duruyor cebimde 

Senden bana tek hatıra diye

Hayalin hep gözlerimde

İsmin her an dilimde

Batıp duruyor kalbime

O toplu iğne

Sen düşünce aklıma

Ve sen aklımdasın her saat başında

Rotterdam,23.08.2002', 'Bir toplu iğne Senelerdir duruyor cebimde  Senden bana tek hatıra diye Hayalin hep gözlerimde İsmin her an dilimde Batıp duruyor kalbime O t...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/toplu-igne-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her İnsan Bir Roman', 'her-i-nsan-bir-roman-ensar-aktas-3xv7e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her insan bir roman; 

Çevirsen sayfaları bir okusan

Ne sevdalar saklı, ne aşklar

Ne entrikalar var, ne aldanışlar

Bir masal bitmeden diğeri başlar

Ne sırlar gizli her birinde, bir sorsan

Her insan bir roman; 

Adem ile yazıldı önsözü

İsrafil’in Sur’u söyleyecek son sözü

Rotterdam,09-06-2003', 'Her insan bir roman;  Çevirsen sayfaları bir okusan Ne sevdalar saklı, ne aşklar Ne entrikalar var, ne aldanışlar Bir masal bitmeden diğeri ...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/her-insan-bir-roman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vur Emri', 'vur-emri-abdurrahim-karakoc-ufzlf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir haber dolaşır semada pulpul; 

Kılınçlar bilensin akın var Çin’e.

Yiğitler at sürer düşman içine; 

Tarihe hükmeden bir ses duyulur:

- Vur!  TÜRKLÜK aşkına vur! 

Yüklenir bir ülke oymak ve avul, 

Sel olur ordular, batıya akar.

Uçar elden-ele bozkurtlu bayraklar.

Emreder bir başbuğ, sade ve vakur:

- Vur!  BAYRAK aşkına vur! 

Karışır top sesi, nal sesi, davul..

Çağdan çağa çığır açar gemiler.

Bir hâkan atını denize sürer

Ve der ki: “Yıkılsın Bizans’ı koruyan sur, ”

- Vur!  FETİH aşkına vur! 

 Parçalanmak istenir bir ülke, Anadolu’dur:

Şahlanır bir anda bin yıllık hınçlar; 

Eser poyraz poyraz eğri kılınçlar, 

Kütahya düzünde kelle savrulur...

- Vur!  TOPRAK aşkına vur! 

Ya... işte tarihin böyledir oğul! 

Geçmişten hız alsın geleceğin de..

Göster Türklüğünü tunç bileğinle! 

Bu dine, bu ırka ve bu toprağa

Sataşmak isterse herhangi  gavur:

-  Vur!  ALLAH aşkına vur! 

(Vur Emri)', 'Bir haber dolaşır semada pulpul;  Kılınçlar bilensin akın var Çin’e. Yiğitler at sürer düşman içine;  Tarihe hükmeden bir ses duyulur: - Vur...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/vur-emri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlat Acısı', 'evlat-acisi-nazan-danacioglu-vwkvc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşlerime konuk olur bir çocuk bazen; 

Gözleri ışıl ışıl, elleri beyaz...

Uzattığım şekerleri asla geri çevirmez.

Irmaklarda yalın ayak yürüyüp, 

Ağacından elma yeriz. 

Öğrettiğim türküyü kurbağalara söyleriz.

Bir kayının gölgesinde anlatırım, 

En sevdiği masalı; 

Ben toprağın üstünde, o göğsümde uyuruz.

Giderek yaşlanırım, hiç büyümez çocuğum, 

Hayal gücüm buna yetmez, uyanırım gerçeğe...

Çöreklenir yüreğime acıların acısı; 

Bir yangın ki, söndüremez cümle su! 

6-6-2003', 'Düşlerime konuk olur bir çocuk bazen;  Gözleri ışıl ışıl, elleri beyaz... Uzattığım şekerleri asla geri çevirmez. Irmaklarda yalın ayak yürü...', ARRAY['Türk Edebiyatı','Şiir','Nazan Danacıoğlu']::text[], 8.5, '{"poet":"Nazan Danacıoğlu","poet_slug":"nazan-danacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/evlat-acisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşça Kal', 'hosca-kal-nazan-danacioglu-3fri4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen anlarsın, neden ellerim soğuk, 

Yüreğim ateş! 

Neden batarken de doğarken de

Kızıldır güneş! 

Tercihin gülmek de olsa, 

Ağlarsın bazen...

Kalmak istesen de, 

Nafile, gitmen gerekir.

Sevsen de üşürsün, 

Ve sıcaktır gözyaşı...

Sohbetin tatlı yerinde

Susasın gelir.

Uzanan her el, 

Çare değildir derdine, 

Kapanan her kapıysa son...

İyisi mi hoşça kal! 

10-6-2003', 'Sen anlarsın, neden ellerim soğuk,  Yüreğim ateş!  Neden batarken de doğarken de Kızıldır güneş!  Tercihin gülmek de olsa,  Ağlarsın bazen.....', ARRAY['Türk Edebiyatı','Şiir','Nazan Danacıoğlu']::text[], 8.5, '{"poet":"Nazan Danacıoğlu","poet_slug":"nazan-danacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hosca-kal-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Altında', 'yagmur-altinda-nazan-danacioglu-ui40d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyor, 

Ahmak ıslatan cinsinden...

Ve ben ıslanıyorum, 

Ve hiç komik değil! 

Satırlar sıralanıyor

Boş beyaz bir sayfaya..

Anlatmaya yetmiyorlar yaşadığım anı, 

Yine de deniyorum.

Yorgunluğu üstümde, 

Geçip giden günün...

5 çayımı içiyorum bölümün bahçesinde, 

Çayım da ıslanıyor.

Yağmur ve ben, 

Çay ve sigara, 

Kağıt ve kalem, 

Başbaşayız bir masada...

Dört duvar arasına sıkışmamış bir yalnızlık, 

Ve ıslak bir defterim var.

Ve ilk defa, nedeni gözlerim değil! 

4-6-2003', 'Yağmur yağıyor,  Ahmak ıslatan cinsinden... Ve ben ıslanıyorum,  Ve hiç komik değil!  Satırlar sıralanıyor Boş beyaz bir sayfaya.. Anlatmaya...', ARRAY['Türk Edebiyatı','Şiir','Nazan Danacıoğlu']::text[], 8.5, '{"poet":"Nazan Danacıoğlu","poet_slug":"nazan-danacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yagmur-altinda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı Reçete', 'aci-recete-nazan-danacioglu-fgsk0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dediler ki: “Ölecekmişsin! ”

Öylesine kurulmuş bir cümle gibi, 

Kolayca çıkıverdi ağızlarından.

İki dudak arasında, 

Başıma yıkıldı dünya.

Seninle unuttuğum ölüm, 

Yine seninle yanımda...

Anlara sığdırdığımız onca mutluluk için, 

Şükretmem mi gerek şimdi? 

Seninle gelen hayat, 

Seninle mi gidecekti? 

Asıl garip olan, 

Sana ömür biçenlerin, 

“Allah’tan umut kesilmez” demesiydi.

Bense, 

Bizden kesmedim umudu, 

Bir hafta daha eksildi, kalan zamanımızdan... 

Beyaz önlük giymiş gerçek, 

Acı bir reçete yazdı.

Demek ki, 

Böylesine bir mutluluk, 

Bedelsiz olamazdı! 

15-6-2003', 'Dediler ki: “Ölecekmişsin! ” Öylesine kurulmuş bir cümle gibi,  Kolayca çıkıverdi ağızlarından. İki dudak arasında,  Başıma yıkıldı dünya. S...', ARRAY['Türk Edebiyatı','Şiir','Nazan Danacıoğlu']::text[], 8.5, '{"poet":"Nazan Danacıoğlu","poet_slug":"nazan-danacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/aci-recete-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terin Düşmeye Görsün', 'terin-dusmeye-gorsun-nazan-danacioglu-7hltl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İlk terim düştüğünde toprağa, 

Ak saçlı bir dede; 

Artık onunsun dedi, 

Ne yapsan kopamazsın. 

Nerede olursan ol, 

Rüyalarına girecek; 

Bu yemyeşil dağlar, 

Bu buz gibi pınarlar...

Hep yüreğinde olacak; 

Terini toprağına akıttığın

Bu şehir...

Hep özleyeceksin, 

Güneşin alnında ekin biçmeyi, 

Sabahın köründe tütün kırmayı...

Hep yad edeceksin, 

Nasırlı ellerinde öptüğün, 

Bu nasırlı elleri...

Yüreğindeki tarlada, 

Bitse de ayrık otları, 

Asla devrilmeyecek

Çocukken ektiğin çınar...

Belki bir gün, 

Dalında düşler kurduğun

Dut ağacı kesilecek, 

Ak saçlı deden gidecek.

Sen yine de döneceksin.

Toprak çağıracak seni, 

Ormanın gümbürtüsü, 

Güzinede pişmiş

Taze ekmek kokusu...

Çoktan ot bürümüş patikalarda

Genç bir kadın olarak

Yürüyeceksin onunla...

Geri döndüm diyeceksin! 

24-6-2003', 'İlk terim düştüğünde toprağa,  Ak saçlı bir dede;  Artık onunsun dedi,  Ne yapsan kopamazsın.  Nerede olursan ol,  Rüyalarına girecek;  Bu y...', ARRAY['Türk Edebiyatı','Şiir','Nazan Danacıoğlu']::text[], 8.5, '{"poet":"Nazan Danacıoğlu","poet_slug":"nazan-danacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/terin-dusmeye-gorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehrayin Şarkıları 1', 'sehrayin-sarkilari-1-nurullah-genc-ge6lx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seni yaşamadan ölmeyeceğim

aşka özgü zakkum bahçelerinde

gene acılara kalıyorum ben 

deniz ölesiye yakın ayaklarıma

ey ülkemin pusatsız kahramanları

erzurum garında, banklar üstünde

sükut-u hayale uğrayan kalbim

geceyi kavrayan parmaklarımla

bu hasret, bu hicran zelzelesinde

beni kurtarmaya gücünüz yetmez

çünkü mutsuzluğun mekteplerinde

ıstırap dersleri alıyorum ben



gittikçe yaklaşan bir afet gibi

intihar yanılgısıyla

yolar beni esarete çekiyor

şehrayin şarkıları söylüyorum içimden 

şarkılar ki, hep aynı nakaratla bitiyor

sen bir garip delisin 

gözleri perdelisin



erzurum garında, banklar üstünde

susuzluktan ağlayan bir güvercin 

içime vuruyor kanatlarını

nağmelerin ateşinde parlayan

kuşlar bölük bölük hayatıma giriyor

bütün çığlıkları kuşanmış ölüm 

dudaklarında siyanür

oysa bilmiyor ki, bu yolculuktan

yollar tükense de, dönmeyeceğim

seni yaşamadan ölmeyeceğim

o çin harikası bakışlarını

o pekin gözlerini

gözlerin ki, gece donanmasıdır

yoksul ve yabancı mısralarımın



bedenimde çıban çıban ağrılar

ben bu ağrılardan zevk alıyorum 

ejder tepesinde bunalıyorum

bir yanda kum frıtınası

diğer yanda esrarengiz 

karakalem çalışması bir deniz

rüzgarla, yağmurla ve yıldızlarla

başlamak üzere son ayinimiz 



erzurum garında gece yarısı

bankların üstünde şimşekler konar

bazen bir yıldırım gezinir saçlarımda

bazen bir melek saatler boyu 

yakama ölümsüz çiçekler takar

erzurum garında gece yarısı

hıçkırıklar boğazıma tıkanır

nemrut ateşiyle sabaha kadar 

içimde binlerce ibrahim yanar



koltuğumda efsaneler kitabı

kafdağından nergis devşiriyorum 

başını dayamış omuzlarıma

o eski, o yaşlı zümrüdüanka

ben bir çin şarhoşu samanyolunda

denizi tartışan bakışlarını

geçmişime asla gömmeyeceğim

seni yaşamadan ölmeyeceğim



perdeler kalkıp da sabah olunca 

aldırma aras’ın öyle bulanık 

öyle mahsun aktığına 

palandöken yine sisli, aldırma

ben hem sise, hem çamura alıştım

senelerdir bu acıyla buluştum 

mutluluk ne zaman çıksa karşıma

yalnızlık bir zindan, çöker başıma', 'seni yaşamadan ölmeyeceğim aşka özgü zakkum bahçelerinde gene acılara kalıyorum ben  deniz ölesiye yakın ayaklarıma ey ülkemin pusatsız kahr...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/sehrayin-sarkilari-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehrayin Şarkıları 2', 'sehrayin-sarkilari-2-nurullah-genc-l5ivb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'daha dokunmadan kurudu irem

çöllere birtürlü yağamıyorum

yeni bir koşunun başlangıcında

biraz deprem sonrası

biraz şehir hülyası

bir kalp yangınından geriye kalan 

siyah gözlerine beni de götür

artık bir bu yerlere sığamıyorum

pembe uçurtmalar yolladığından beri

sarardı tiryaki menekşeleri

sonbaharın tozlu kafeslerinde 

sevgi turnalarına yakalanıyorum

turnalar gidiyor; ben kalıyorum

avareyim, asudeyim, yorgunum 

bilmiyorum neden sana vurgunum

erzurum garında, banklar üstünde

uyku tutmuyor karanlıkları

yitik düşlerimi kovalıyorum

gölgeler gidiyor; ben kalıyorum

binbir türlü kokuyorsa yaylalar

siyah gözlerine beni de götür

baharın koynundan koparıp sana

ipek bir mendille sardığım yüreğimle 

şehzade gülleri gönderiyorum

umutlar kalıyor; ben gidiyorum

bütün yalkanlileri, deniz fenerleri 

kaptanları sorgulayan

yanından geçen küheylanların

korku tufanına yakalandığını

siyah gözlerine beni de götür

güneş ülkesinden gelen yiğitler

benzeri olmayan bir dünya kursun 

cellat, ayrılığın boynunu vursun 

usul usul intizarı çürüten 

bu hercai diken, bu çılgın arzu

sürüklüyor imkansız muştuların 

eşiğine gönül vadilerini

bir ağaçtan düşen yapraklar gibi

düşüyorum tanyerine 

ya topla yaralı kırlangıçları

ya da bu vefasız şarkıyı bitir

özgürlüğe giden tutsaklar gibi

siyah gözlerine beni de götür', 'daha dokunmadan kurudu irem çöllere birtürlü yağamıyorum yeni bir koşunun başlangıcında biraz deprem sonrası biraz şehir hülyası bir kalp ya...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/sehrayin-sarkilari-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düğme', 'dugme-mehmet-tombuloglu-lg4vq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Ne bilinçli yaşamdan engin sancı

 ne can taşımaktan daha büyük

 bir acı vardır''

                                 Darıo

bütün sesler uydu ışığın ahengine				

tek yıldız, tek ay, gergin yay olarak kaldı			

sakin bir gecenin tam ortasında				

sütten ak, rüzgardan saydam, gizli bir akıntıya kapılarak	

duysaydım sesini, zorlardım yazgımın kapısını

talihimi çevirecek bir çılgın alev kalsaydı elerimde

çırpınan utangaçlığıyla, tutardım yüzümü başka baharlara

bir harfin peşine düştüm de öyle geçtim

unutulmuş korkularla eksilttiğim kıyısız sulardan

peşimde iz bırakmadım, oturmuş imler

dizelerin arasına sakladığım sırdan başka

bağışla telaşını kanatlarını sınayan dilimin

suskun ünlemi bir rüzgarın peşinde uzun zamandır

güz bitti; ufkunda çift örgülü suskunluğun izi

bak bir duyguya tutundun bütün imler uyandı

çoktan kapını çaldı, beklediğin habercilerin

zaman; ki gerçeği içinde taşıyarak yol alırmış

rüzgar serin ve gölgeli sularda açarken mührünü

zaten çok geçtin uzun heceli köprülerden

düşürüp takma adını uyuyan suyun sessiz akışına

ah dilimin kıvrımında bekleyen düğümlü söz

yitirdim gömleğimin son düğmesini de

anladım işte, gözlerin bir başka nehrin suyu

anladım da bekledim, yeni zaman dilimleri eklerken yüreğime

ne ki; bakışındaki yalansız davete karşı koyamazdım

yoksa yanılgıların ekseninde büyüyen yüzümdeki çizgi

hangi dize, hangi imgede anlam bulabilir ki

üstelik çağırırken, düşlerimi taşlarda yuyan geceler 

işte, gündelik yüzüme dar gelen siyah beyaz bir resimle

titreyen sesimdi o; henüz menziline ulaşmamış

rüzgar içine rüzgar serpiştirilmiş

bak hala sayıkladığım o eski rüya

bir seher düşün sevgilim

bütün bir geceyi yıldızlarıyla içti bugün', '''Ne bilinçli yaşamdan engin sancı  ne can taşımaktan daha büyük  bir acı vardır''                                  Darıo bütün sesler uydu ış...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tombuloğlu']::text[], 8.5, '{"poet":"Mehmet Tombuloğlu","poet_slug":"mehmet-tombuloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/dugme-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Eski Şarkılar...', 'eski-sarkilar-naime-erlacin-e1sm0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kayboldu say aşkı

bir koku kalır geride

bir de eski şarkılar 

ruha yapışan

ıssız bir kıyıda 

aksisedadır bazen

kumlara sağılır 

gece sesi duyulur derinden 

dalga sesi

aşk sesi 

şarkı dilinden

“caddeden sokaklara” inciler dökülür

soyutlanır cisminden insanoğlu 

safi yürek kalır geride

bazen geçmişten bir ezgi

“huysuz ve tatlı kadın” diye seslenen

“ayrılık” ne içli söylenirdi bir zamanlar 

şarkılarda vurulup düşerdi insan

sevdada ayrılık olmaz oysa

ayrılık şarkılarda kalır

(03 Temmuz 2003)', 'kayboldu say aşkı bir koku kalır geride bir de eski şarkılar  ruha yapışan ıssız bir kıyıda  aksisedadır bazen kumlara sağılır  gece sesi du...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/eski-sarkilar-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seveceksin Kardeşim', 'seveceksin-kardesim-muhtesem-oksel-t1dhw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bak kardeşim, seveceksin.

Sana kötülük yapanları, 

Hiç ayırt etmeden

Topunu, alayını, 

Cümlesini seveceksin.

Yakışmaz bize kin, nefret.

Silk at bu düşünceleri.

Günü gelene dek bekleyeceksin.

Fırsat çıkana dek sabret.

Geldiğinde zamanı, 

Sana haksızlık yapanları, 

Hiç ayırt etmeden

Gelmişini, geçmişini, 

Yolunu, yordamını, 

Tüm içtenliğinle seveceksin.

Bekle, görecekler elbet, 

Her şey sevmekle başlar insanı.

Sevdikçe artar kıymetin.

Bu bir hayat dersi kardeşim.

Sevdikçe seveceksin.

Sana kötülük yapanları, 

Sana adil olmayanları, 

Severek affedeceksin.

Sevmeyi iyi öğren, 

Bu bir hayat dersi kardeşim.

El üstünde tutarlar seversen, 

Kulağına küpe olsun, 

Muhteşem, demişti dersin.', 'Bak kardeşim, seveceksin. Sana kötülük yapanları,  Hiç ayırt etmeden Topunu, alayını,  Cümlesini seveceksin. Yakışmaz bize kin, nefret. Silk...', ARRAY['Türk Edebiyatı','Şiir','Muhteşem Oksel']::text[], 8.5, '{"poet":"Muhteşem Oksel","poet_slug":"muhtesem-oksel","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/seveceksin-kardesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Hayvan, Kim İnsan?', 'kim-hayvan-kim-i-nsan-muhtesem-oksel-npwjs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne bileyim işte, merak ederim.

Yavrusunu cami avlusuna bırakan mı insan? 

Yavruları için avlanan aslan mı hayvan? 

İnsan mı zevk için avlanan, 

Ya da öldürüp birbirini soyunu kurutan? 

Hayvan mı acaba köpek, bir kediyi emziren? 

Veya insan mı acaba tabiatı kirleten? 

Durup, düşünür, sorarım.

Kim hayvan, kim insan? 

Ne bileyim işte, merak ederim.

Düşünür de bulamaz, 

Böyle düşüncelere boğulur, giderim.', 'Ne bileyim işte, merak ederim. Yavrusunu cami avlusuna bırakan mı insan?  Yavruları için avlanan aslan mı hayvan?  İnsan mı zevk için avlana...', ARRAY['Türk Edebiyatı','Şiir','Muhteşem Oksel']::text[], 8.5, '{"poet":"Muhteşem Oksel","poet_slug":"muhtesem-oksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kim-hayvan-kim-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahi Biz Neden Küsmüştük?', 'sahi-biz-neden-kusmustuk-muhtesem-oksel-1jrks', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her günümüz, dünden iyi geçerdi.

Ne güzel arkadaşlığımız vardı değil mi? 

En çok da sinir etmeye bayılırdım seni, 

Gıcıklığına yanlış söyleyerek ismini.

Sonra ne oldu? 

Bir gün her şey bitti.

Hatırlıyorum, 

Sana çok kızmıştım o zamanlar.

Senin de hatırladığın, 

Bana çok kızdığın bir zamanlar.

Ama neye kızmıştım? 

Şimdi hatırlamıyorum.

Sana soruyorum, 

Sen de hatırlamıyorsun.

Aradan geçmiş altı yıl.

Hem de koca altı yıl.

Küsmüştük, 

Neden küstüğümüzü hatırlamadığımız bir şeylere

Bir gün yine karşılaştık, 

Hayret ediyorduk geçen günlere, 

Çocukça gururumuza, öfkelerimize, 

Kayıp senelerimize.

Ve o an geldik göz göze.

Gülemedik yaşadıklarımıza, 

Gülemedik bizden hesap soran yaşayamadıklarımıza.

Sahi biz neden küsmüştük? 

Neden küsmüştük Cale?', 'Her günümüz, dünden iyi geçerdi. Ne güzel arkadaşlığımız vardı değil mi?  En çok da sinir etmeye bayılırdım seni,  Gıcıklığına yanlış söyley...', ARRAY['Türk Edebiyatı','Şiir','Muhteşem Oksel']::text[], 8.5, '{"poet":"Muhteşem Oksel","poet_slug":"muhtesem-oksel","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sahi-biz-neden-kusmustuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zoraki Aşk', 'zoraki-ask-faruk-polat-x39ek', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben  pipo icmeyi severdim

O hep tutun sarardi.

Yuzu bazen tutun sarisiydi

Bazen solgun bir gulu andirirdi

severdik birbirimizi

Bir kaktusun col topragini sevdigi gibi

Bazen kizardi bana

siktir cektigi zamanlar olurdu

Ama sonra

Gozlerinde son bulurdu

Butun kini butun nefreti.

Severdik birbirimizi

Bir kaktusun col topragini sevdigi gibi..', 'Ben  pipo icmeyi severdim O hep tutun sarardi. Yuzu bazen tutun sarisiydi Bazen solgun bir gulu andirirdi severdik birbirimizi Bir kaktusun ...', ARRAY['Türk Edebiyatı','Şiir','Faruk Polat']::text[], 8.5, '{"poet":"Faruk Polat","poet_slug":"faruk-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zoraki-ask-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret çiçeğim (uyaklı)', 'hasret-cicegim-uyakli-nuri-can-dy206', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hasret çiçeğim  (uyaklı) 

Yağmurlar düşerken körpe bağına 

süzülür damlalar gül yaprağına

takılıp gurbetin hüzün ağına

bir sen mi solarsın hasret çiçeğim

Sarıp dikenlere gönül acını

indirme başından ümit tacını

rüzgarda savrulan ipek saçını

bir sen mi yolarsın hasret çiçeğim

Estikçe başından gurbet yelleri

okşarsın hasretle  açan gülleri

mutluluk seyrinde eski günleri

bir sen mi anarsın hasret çiçeğim

Dalıp anıların buruk seyrine

gözyaşı dökersin hasret nehrine

yediğin ekmeği gurbet zehrine

bir sen mi banarsın hasret çiçeğim

Denizler dalgalı alınlar sisli

yollar sıra sıra engel dizili

herkesin ateşi içinden gizli

bir sen mi yanarsın hasret çiçeğim

Seller feryad eder dağlar ses verir

bir ömre bir sevda sanma az gelir

şimdi her gönülde bir ah yükselir

bir sen mi ağlarsın hasret çiçeğim

Coşkun akan seldim duruldu kalbim

gurbet eller gezdim yoruldu kalbim

aşkın hançeriyle vuruldu kalbim

bir sen mi kanarsın hasret çiçeğim

Bir tek sen değilsin hasretlik çeken

 gizli köşelerde boynunu büken 

sılada sevdalar gül gül iken 

bir sen mi  ağlarsın hasret çiçeğim

Can Nuri'' yim nice canlar canıyım 

diyar diyar gezen garip arıyım

gurbetin hasretin en kör yanıyım

bir sen mi dolarsın hasret çiçeğim

Nuri CAN 

10/06/ 1977  Amsterdam', 'Hasret çiçeğim  (uyaklı)  Yağmurlar düşerken körpe bağına  süzülür damlalar gül yaprağına takılıp gurbetin hüzün ağına bir sen mi solarsın h...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/hasret-cicegim-uyakli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İste(r) diklerim', 'i-ste-r-diklerim-semih-bagci-zxoq4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimi İstanbul''u dinler gözü kapalı, 

Ben dört gözle seni dinlemek isterdim.

Kiminin babası beslenme çantasında otlu peynir kokusu, 

Benim şuram buram seni koklamak isterdi.

Kimi sabahın dördünü bekler ekmek, şarapla

Ben seni beklerim tüm senliğimle.

Kimi hayatta en çok babasını sevmiştir, 

Bense ''CAN''dan çok seni sevdim, 

Ve aslında tüm şairlere kinim

Seni anlattıkları için...', 'Kimi İstanbul''u dinler gözü kapalı,  Ben dört gözle seni dinlemek isterdim. Kiminin babası beslenme çantasında otlu peynir kokusu,  Benim şu...', ARRAY['Türk Edebiyatı','Şiir','Semih Bağcı']::text[], 8.5, '{"poet":"Semih Bağcı","poet_slug":"semih-bagci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/iste-r-diklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gülün Hikayesi', 'bir-gulun-hikayesi-abdulkadir-karaman-w5ikg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Buz gibiydi toprak 

gökyüzü karmakarışıktı

üşüyordu elleri 

bulutların donuk donuktu gözleri

tesadüfen atılmış bir tohumun 

beklentisi çok az bir ışıktı

henüz dalına doğru yönelmemişti yaprak…

kar yağdı lapa lapa

rüzgar esti çılgıncasına

raks ettiren melodiler çalarak

sürgün yapraklara

dallarda çiçek yerine kuşlar açıldı

ay saklandı bulutlar arkasına

yıldızlar çıkmayı hiç istemedi

ayazın tipili balosuna

bir fidanda bir zerre uzandı dal ucuna

dudağında 

her renkten renkler vardı hediye

son verdi zaman üşüten orucuna

yeniden fırsat doğdu sürgündeki sevgiye

güneşin gitti ürkekliği

ay salınmaya başladı sereserpe

yıldızlar dansa tutuştu 

burçlarla her gece

depreşti gülnihâlin yürekliliği

duyguları heyecanlarla tutuştu

ısındı toprak 

ne kadar şükretse azdı cemreye

su ısındı 

nazlanmalar kendiliğinden bitti

açıldı yaprak

goncalarla doldu fidanlar

duygular tomurcuklandı

bir gül açıldı binlerce güle bedel

sevgiden 

her yüreğe saçıldı

İtiraz yükselmedi kimseden

San ki o güldü…özlenen…beklenen! .

Bütün güllerin sevildiği 

ondandır

güle benzetildiği sevgililerin…sevenlerin

bütün güller soldu

kurudu bütün fidanlar

sevgi gülü solmayacak

görecek yaşayanlar

gülün sevgisi tükenmeyecek

ölmeyecek…ölmemeli…sonsuza kadar.

01.07.03', 'Buz gibiydi toprak  gökyüzü karmakarışıktı üşüyordu elleri  bulutların donuk donuktu gözleri tesadüfen atılmış bir tohumun  beklentisi çok a...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/bir-gulun-hikayesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaylalar', 'yaylalar-bekir-gedikoglu-n1xva', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaylanın çimenini,  kuzu yayılır kuzu

İnsana içirirler yayla da, buz gibi suyu

Yediğinde çavdar ekmeğini, bir güzel uyu

Buğdayı sorarsan tarlada, oldular diz boyu

Gök kubbede yankılanır akşam ezanı

Yaylanın sürüsü, çobanın çaldığı nağmeye  bağlı

Davarlar doldururlar her akşam ağılı

Anaların, bacıların elinde, vardır süt kazanı

Yaylada ormana girersen kaybolur gidersin

Çamın belinde, çam sakızı düğmesini ararsan bulursun

Ormanda bir peteğe  rast gelirsen, ağzını balla doldurursun

İşin aslına bakarsan yaylalarda,  ömrüne ömür katarsın

Ağustos ayında gelir harmana buğday ve çavdarı

Varsa iki baş öküzün,  döğen tanır harmanı

Ezer harmana serilmiş çavdarı ve buğdayı

Akşam olunca toplar harmancı, harmandan hasatını

Ormanın içleri çiçek ile doludur

Sümbülü, zambağı, duduyası ve papatyası çok boldur

İnsan, çiçeklerin kokusundan adeta sarhoş olur

Har gibi çiçek kokusunu, doldur içine doldur

Yaylanın atlarını salarsın çayırlara

Otlandıkça otlanır, bayılırlar yoncaya

Her akşam at yarışı, var ovadan obaya

Dört nala kalkacaklar, süvariler bu yolda

Bazı günler sis çöker, göz gözü görmez yaylada

Kaybolur ormanda, bir koyun birkaç dana

Ya kurda yem olacaklar, ya da gidecekler yabana

Çok mutlu oluyorsun! ,  sis dağılıp ta onları bulduğunda

Yaylalara yolculuk sayfiyeden iyidir

Anlatmaya gerek yok, dizelerden bellidir

Sen aşıksan arkadaş, yaylalara gidilir

Bu yaylalar herkese çok mutluluk getirir.

Ankara,02.07.2003', 'Yaylanın çimenini,  kuzu yayılır kuzu İnsana içirirler yayla da, buz gibi suyu Yediğinde çavdar ekmeğini, bir güzel uyu Buğdayı sorarsan tar...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yaylalar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Buluşmaları - 2', 'ayrilik-bulusmalari-2-sule-aydemir-7ly9b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kahırda dem tuttu bu engebeli yol

bir oturdu duygular bir kalktı ayağa

ağlama dedi toprak hüzünden buluta

eller çağırdı o an dudaklar biçare suskun

beden duaya uzandı 

sanki duyan olmadı 

bu ayrılığın ayini 

doğa kabus irkildi

sesler sessizleşti

maviyi gökler tutmuş deniz siyah sakindi

kadın boynunu büktü erkek yere eğildi

bir rüzgar hüznü aldı üstlerine üfledi

yürekten geldi bir çatırtı yeniden

kadın gülümsedi erkek bakışlarında alevdi

yürüdüler derine düşündüler delice bir hızla:

-içinde açmak tüm kapıları

gündüz ortası

kuyruk takmak yıldızlara ve kaydırmak akılda

her birine bir dilek yapıştırmak papatyalardan

fal niyetine şarkılar tutmak

çoklu seçeneklerden kurtulmak 

bir bakışta yüreği yarmak ve kafesten çıkmak 

uçmak özgürlüğü takıp da kanadına

mutsuz olmamak umutla yer değişmek huzura

yerleşti dudaklara çarpık nahoş gülümseme

gözkapakları aralandı kirpik arası aşkın yakıcı okları

bu sevdaysa yaşanmalı 

bedel öderken ayrılık bedenden kopan parçaları

aşk yüreğe aşk 

aşk nakış incecik

sağlam aşk

ayrılık buluşmaları

yamamalı', 'kahırda dem tuttu bu engebeli yol bir oturdu duygular bir kalktı ayağa ağlama dedi toprak hüzünden buluta eller çağırdı o an dudaklar biçare...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ayrilik-bulusmalari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuru çeşmenin aşkı', 'kuru-cesmenin-aski-elif-sebnem-akal-q4p1h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çeşmenin aşkıydı su, 

Bilmezdi bunu...

Akardı fütursuzca bulup yolunu...

Çeşme, okşar severdi akarken onu, 

Açıldıkça, sunardı suya...

Gönüllü vücudunu....

Su öğrenmedi bu aşkı, 

Sadece, coşkuyla aktı...

Anlamadı... ona yol veren vücudunu okşamadı...

Zamanla, 

Karşılıksız bu aşka küstü çeşme...

Kesti suyuna yolları, 

Kurudu...kaldı öyle...

Şimdi her açıldığında, 

Derin bir iniltisi var...

Suya olan hasretiyle...

Kuru çeşmeye yazdılar

'' aşık ol...karşılık bekleme...''', 'Çeşmenin aşkıydı su,  Bilmezdi bunu... Akardı fütursuzca bulup yolunu... Çeşme, okşar severdi akarken onu,  Açıldıkça, sunardı suya... Gönül...', ARRAY['Türk Edebiyatı','Şiir','Elif Şebnem Akal']::text[], 8.5, '{"poet":"Elif Şebnem Akal","poet_slug":"elif-sebnem-akal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kuru-cesmenin-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Adım Rüzgar', 'benim-adim-ruzgar-veli-altioglu-k3lwp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nerede estiğim bilinmez, 

Bakarsın güzelliklere meltem olurum, 

Bakarsın delikanlılığa fırtına...... 

Bazen demir kapı dört duvar yurdum, 

Bazen dağlarda haran olurum... 

Kimi kaldırımlarda toz kaldıran, 

Kimi balkonlarda kapı yaran, 

Bazen zenginlere ceza olurum, 

Sonra hoyratlarda kaybolurum.... 

Delikanlının bağrında, erenlerin otağında, 

Azrail in ocağında, Keskin bıçağın sırtında, 

Kör kurşunların yanında, onlara rehber olurum, 

Bir işkence odasında mahkuma çığlık olurum.... 

Gamlı türkülerin adında, uçan kuşun kanadında,,, 

Tel örgülerin ardında, 

Mahkuma sırdaş olurum.... 

BENİM ADIM RÜZGAR NEREDE ESTİĞİM BİLİNMEZ.....', 'Nerede estiğim bilinmez,  Bakarsın güzelliklere meltem olurum,  Bakarsın delikanlılığa fırtına......  Bazen demir kapı dört duvar yurdum,  B...', ARRAY['Türk Edebiyatı','Şiir','Veli Altıoğlu']::text[], 8.5, '{"poet":"Veli Altıoğlu","poet_slug":"veli-altioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/benim-adim-ruzgar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresi Yok', 'caresi-yok-veli-altioglu-te12q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dışarıda yağmur içimde rüzgar 

Kopsa da yüreğimde fırtınalar, 

Söyleyemezsin ya 

Bakamazsın ya yüzüne; 

Her gördüğünde duman gözlüyü 

Serde erkeklik var ya, 

Ağlayamazsın. 

Buz kesse de ellerin, 

Dağlardaki karı eritir 

Gönlündeki yangın. 

Hangi fırtına dindirir, 

Hangi yağmur söndürür bu yangını. 

Öyle bir yangın ki; 

İlacı yok, merhemi yok, çaresi yok 

Zaman ilacıdır derler 

İnanmıyorum onlara yalan söylüyorlar 

Zaman söndürür mü dağları eriten yangını 

Yaş otuz beş dediler yolun yarısı eder. 

Yirmisinde yarıyı geçtim 

Sona geldiğimde gönlümdeki yangın 

Bedenimi de yakacak biliyorum', 'Dışarıda yağmur içimde rüzgar  Kopsa da yüreğimde fırtınalar,  Söyleyemezsin ya  Bakamazsın ya yüzüne;  Her gördüğünde duman gözlüyü  Serde ...', ARRAY['Türk Edebiyatı','Şiir','Veli Altıoğlu']::text[], 8.5, '{"poet":"Veli Altıoğlu","poet_slug":"veli-altioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/caresi-yok-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanılmışlıklar Var', 'yasanilmisliklar-var-veli-altioglu-8axm1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşanılmışlıklar var

Silip bir kenara atamazsın

Sen benden değil 

Kendinden kaçamazsın

Sararır her şey sararır yüzün

Aynaya bile bakamazsın

Uykuların kaçar kabuslar basar

Geceleri rahat yatamazsın

Solmuş bir gül gibisin 

Artık güzel kokamazsın

Yok oldu kayboldu bitti her şey

Sen beni bir daha bulamazsın', 'Yaşanılmışlıklar var Silip bir kenara atamazsın Sen benden değil  Kendinden kaçamazsın Sararır her şey sararır yüzün Aynaya bile bakamazsın ...', ARRAY['Türk Edebiyatı','Şiir','Veli Altıoğlu']::text[], 8.5, '{"poet":"Veli Altıoğlu","poet_slug":"veli-altioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasanilmisliklar-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Adım Barış', 'benim-adim-baris-mehmet-akar-znyx1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim adım Barış ama ben savaşlarla büyüdüm.

Henüz yedi yaşındaydım evimiz yıkılırken, 

ve bombaların sesine karışırdı ağlamalarım.

Benim gerçek bir oyuncağım olamadı; mermilerle oynardım.

Savaşa giderken babam eve ben babalık ederdim.

Ve bir gün gitti yine babam, dönmedi bir dahada.

Anam ben ve kardeşlerim yalnız kaldık savaşın ortasında.

Sonra göçe zorlandık barış dedikleri toprağa doğru, 

ama ya babam gelirse diye ben evimde bıraktım umudumu.

Şimdi yeni bir savaşın ortasındayım; açlık ve sefalet.

Hastalık var buralarda da, kardeşlerim hasta, anam hasta.

Bende hastayım ama umutsuzluktan, çaresizlikten.

Biz burdayız umudum orda, ben burda, babam orda.

Oysa benim adım Barış, nerede benim babam? 

Nerede benim oyuncaklarım, oyunlarım, hayallerim, 

umutlarım? 

Benim adım Barış!', 'Benim adım Barış ama ben savaşlarla büyüdüm. Henüz yedi yaşındaydım evimiz yıkılırken,  ve bombaların sesine karışırdı ağlamalarım. Benim ge...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akar']::text[], 8.5, '{"poet":"Mehmet Akar","poet_slug":"mehmet-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/benim-adim-baris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorumsuz (!)', 'yorumsuz-elif-kerenciler-6t75b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sadece bana diyorsam bak

dinle; 

gülüşlerimle hıçkırmak bu

ya da? 

17:40

03.07.2003

Biga', 'sadece bana diyorsam bak dinle;  gülüşlerimle hıçkırmak bu ya da?  17:40 03.07.2003 Biga...', ARRAY['Türk Edebiyatı','Şiir','Elif Kerenciler']::text[], 8.5, '{"poet":"Elif Kerenciler","poet_slug":"elif-kerenciler","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yorumsuz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkılarda Ayrılık', 'sarkilarda-ayrilik-naime-erlacin-vnvd1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şarkı dedim 

aklıma düştü

türküyü acıda yakmadık mı biz

tesbih gibi dizmedik mi 

gözyaşını ezgilere 

isyanımız yatıyordu içlerinde

ağır yürek yangınlarımız ah! 

sızılarımız

kâh birlikte ağladık mahur bir bestede

kâh takılıp kaldık hicazda nihaventte

sustuk 

gönüller lâl 

söyledik yine şarkılarımızı

nağmelere gizlendi aşklar

mektup olup uçtular birer birer

her yerde duyar olduk seslerini

çalınmasalar 

söylenmeseler de

de ki ayrılık saati gelip çattı

“ayrılık şarkılarda kalır” demiştim

bir şarkın yoksa eğer saklayacak 

ayrılığı gömecek içine

işte o zaman yalnızsın 

istesen 

istemesen de...

(03 Temmuz 2003)', 'şarkı dedim  aklıma düştü türküyü acıda yakmadık mı biz tesbih gibi dizmedik mi  gözyaşını ezgilere  isyanımız yatıyordu içlerinde ağır yüre...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sarkilarda-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Duvar', 'dort-duvar-i-smail-tas-zjwyq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dört duvarım sadece dört duvar

Ne arayanım var, ne soran var

Camların buğusudur yokluğun

Dört duvar mahzun yıllardır

Yasını tutar, içimdeki boşluğun

Benim kadar yalnız değil ki yıldızlar

Ve aylak aylak gezen şu bulutlar

Yağmurda ardın sıra gitti

Şimdi benden uzaklarda yağar

Yeşiller sökün etti, bahar seni arar

Ay ışığı unutmuş penceremi çoktan 

Umut kesilir mi? Hiç umuttan

Gittiğin yollar, yıllardır uzar gider

Göz yaşım dökülür dertli bir buluttan

Dört duvarım dört duvar sadece taştan

Şimdi; kırık bir cam, yanmış bir kapı

Dertten, kederden harap bir yapı

Yokluğunda umutlar hep seni arar

Dört duvar arasında unutulmuş bir canı

Kim arar, kim sorar

Kim bulmuş ki yitirilmiş, kayıp zamanı 

Dört duvarım sadece dört duvar

Ne arayanım var, ne soran var…

İsmail taş 2003', 'Dört duvarım sadece dört duvar Ne arayanım var, ne soran var Camların buğusudur yokluğun Dört duvar mahzun yıllardır Yasını tutar, içimdeki ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Taş']::text[], 8.5, '{"poet":"İsmail Taş","poet_slug":"i-smail-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dort-duvar-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümün Yeşil Gözleri', 'omrumun-yesil-gozleri-i-smail-tas-bzl14', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğimde tatlı ilkbahar havası

Saçlarımda esen rüzgarın sesi

Gönlümde bir lale bahçesi

Seyrediyor ömrümün yeşil gözleri

Çiçekli yollarda bekleyen bahar 

Savurur yaprakları bir deli rüzgar

Avuçlarımda zavallı bir güvercin var

Kanatlanacak her an ömrümün yeşil gözleri

Yine gökten kaydı talihsiz bir yıldız

Yine mutsuz, kararsız duygulu bir kız

Ne zaman bitecek bu ayrılığımız

Hasret kokar ömrümün yeşil gözleri

Dağlarda beklerim baharı gelmesi için

Her anında mutluluk tüm gölgeler bizim

Denize doğru uzanan ellerim

Yol ister ömrümün yeşil gözleri

Ne ömrümün baharı geldi ne gençliğim

Beklenen yollarda tükendi günlerim

Şimdi ne yaşıyor ne tam bir ölüyüm

Her an kapanacak ömrümün yeşil gözleri

Artık görünüyor beyaz günlerim

Üzerimde kalsın çıkartmayın gömleğim

Fark etmez taşım toprağım

Bırakın yerinde kalsın ömrümün yeşil gözleri.

İsmail taş 2002', 'Yüreğimde tatlı ilkbahar havası Saçlarımda esen rüzgarın sesi Gönlümde bir lale bahçesi Seyrediyor ömrümün yeşil gözleri Çiçekli yollarda be...', ARRAY['Türk Edebiyatı','Şiir','İsmail Taş']::text[], 8.5, '{"poet":"İsmail Taş","poet_slug":"i-smail-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/omrumun-yesil-gozleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah', 'sabah-i-smail-tas-dvlrn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Erkenden açtım odamın penceresini

Kuş sesleri doldu odamın her tarafına

Rüzgarlar uçuştu şirin şirin

Benim küçük mavi yeşil dünyamda

Erkenden umutlarımı bıraktım kapına

Aynalarla gülüyorum artık

Bu sabah serçe şarkı söylüyor bana

Benim küçük mavi yeşil dünyamda

Erkenden ocağa koydum çayımı 

Odam hala gecenin mateminde

Bir başka heyecanlı kuşlar bu sabah

Benim küçük mavi yeşil dünyamda

Erkenden her sabah kuşlar ötüşür

Umut tükenmez gönüldür benim ki

Hayat kısa uzun geçer habersiz

Benim küçük mavi yeşil dünyamda

Erkenden çaldım kapısını hayatın

Sonra bir dilim ekmek bir yudum çay

Mutluluklar alır beni bu sabah

Erkenden istiyorum yaşama sevincini

Benim küçük mavi yeşil dünyamda

	Nisan 2002 ismail taş', 'Erkenden açtım odamın penceresini Kuş sesleri doldu odamın her tarafına Rüzgarlar uçuştu şirin şirin Benim küçük mavi yeşil dünyamda Erkende...', ARRAY['Türk Edebiyatı','Şiir','İsmail Taş']::text[], 8.5, '{"poet":"İsmail Taş","poet_slug":"i-smail-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sabah-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolculuk', 'yolculuk-i-smail-tas-kxr3b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hazin, esrarengiz, dalgın, sessiz

Garip, telaşlı, yorgun, kimsesiz

Mutlu, mutsuz, yalnız, neşesiz

Bir hayat hikayesidir yolculuklar

Uzun kısa, gece gündüz

Bazen bir yokuş bazen dümdüz

Yolların  sonu  belli belirsiz

Bir hayat hikayesidir yolculuklar

					

Kasım 2001 ismail taş', 'Hazin, esrarengiz, dalgın, sessiz Garip, telaşlı, yorgun, kimsesiz Mutlu, mutsuz, yalnız, neşesiz Bir hayat hikayesidir yolculuklar Uzun kıs...', ARRAY['Türk Edebiyatı','Şiir','İsmail Taş']::text[], 8.5, '{"poet":"İsmail Taş","poet_slug":"i-smail-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yolculuk-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Loş Zamanlar', 'los-zamanlar-kemal-sumer-l39vb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çılgın bir çiçek gibiyim seninle

aynı dağbaşında açan

Ne anlamak mümkün varlığımı

Ne soluşumu böyle erkenden.

-

Bazen bir kişi için döner dünya

Bazen bir kişi için doğar güneş

Bir kişi için katlanılır bazen yaşama

Ve bir kişi sevilir yalnızca bazen.

-

Yanlış bir rüzgargülü olmalıyım ben

Senden yana dönüyor çünkü

Her rüzgarda ibrem.

-

Bir gülüşte saklı olan nedir

Sevgi dolu bir bakışta ya da

Saklı olan ne var içimizde.

Bir dokunuşta saklı olan nedir

Bir öpüşte ya da

Saklı olan bir şey var içimizde.

-

Bir bahara adanmış

Yağmurlar gibiydi.

Farkına varamamıştık

Gözyaşlarımızın

Zaman saklamıştı sanki

Anlamları

Uzattığımızda ellerimizi

Başka biriydik

Çoktan dönmüştü mevsimler.

-

Bir gölge ustasıyım artık

Her gece seni düşürmekten

Karanlık duvarlarıma

Bir düş ustasıyım

Gerçekleşmez birliktelikler

Yaratmaktan yana

Belalı uykularda

Yalnızlık ustasıyım

Küçülerek yaşıyorum şimdi

Varlığınla bölündüğüm her parçada.

-

Anlamsız hüzünler taşıdık

Yıkılmış mezar taşları gibi

İzini sürdük solgun gülüşlerde

Sanal mutlulukların.

-

Yoluna çıkacağım

İçten içe seveceksin beni

Bu senin gerçeğin olacak

Düşüne gireceğim

Anlayacaksın sevdiğini

Bu senin gerçeğin olacak

Yanında başka biriyle

Uyanacaksın bir sabah

Yaşam

İşte böyle bir şey diyeceksin

Bu senin yanılgın olacak.

-

Keskin bir bıçak gibi

Böler zamanı sözler

Ve hep yanlış vakitleri gösterir

İtiraf saatleri

Çalmadan kaçırır uykuları.

-

Birbirini ezerek geçiyor

Çığlık çığlığa kıyametler

Ölüyorum, doğuyorum

Doğuyorum, ölüyorum

Kıyametler tarihi takvimim.

-

Kalmak zordur gitmekten

Unutmak sevmekten

Birlikte olmak ayrılıktan zordur.

Bahar zordur kıştan

Şeftali ağacı çamdan

Yaşam ölümden zordur.

-

Yalnızsın sen küçüğüm

Ağaçlar gibi

Denizler ortasında kalmış

Adacıklar gibi yalnız.

İnsanlar hep yalnızdır küçüğüm

Ne sözcükler ne duygular

Ne de bedeni bir başkasının

Yok edemez yalnızlığı.Üzülecvek bir şey yok yine de 

Meyve vermediği görülmemiştir

Hiçbir ağacın

Yalnızlıktan ötürü.

Ortasında denizin

Yitip gidecek gibi duran adacık

Kim bilir

Gün gelir mekan olur birine.

Sözün kısası küçüğüm

Güzeldir yalnızlık bile 

Öğrendikçe katlanmayı yaşama.

-

Daha iyi çıkıyor ortaya

Her geçen gün

Yerine oturan toprak gibi

Yetmeyecek ömrüm ne yazık

Bu aşkı karşılamaya.

-

İpucu vermiyordu sevgiye dair

Yapraklarını dökmüş

Papatyalar gibi

Başka biriydi sanki gülüşü.

Kapıda bekletmeye gelmez

Kırılgan bir misafirdir aşk.

-

Hep aynı aldanış bu

Hep aynı tükeniş 

Yorgunuz yürümekten

Kendimize ait olmayan yollarda

Acıtmakta içimizi

Tıkanmış bir damar gibi

Tıkanmış hayatlarımız.

-

O kadar güzeldi ki

Önemsiz kılıyordu

Geri kalanını yaşamın

Her şeyi yeniden düşünmeliydi

Bağışlanmış bir hayatı yaşarcasına.

-

Kapkara bulutlarım günlerce yağdılar

İçime düşürdüm güz yapraklarını

Biliyorum ölümcül her şey

Ölümü seviyorum

Seni sevdiğim gibi.

-

Nefret

Yüz elli bıçak darbesi

Geçmişin muhasebesi

Nefret

Yüreklere yağan kurum

Anıların derinleştiği uçurum

Nefret

Aşkın karanlık yüzü

Baharı yitirilmiş yolculukların güzü.

-

Karar verdim bu gece

anıları öldürmeye

Ne yüzler

Ne dokunuşlar kalacak geriye

Belli ki

Böyle sonlanmayacak bu hikaye

Varmıyor yine de dilim

Öldürürken öleceğimi söylemeye.

-

Karşılık beklemedi

Ölüm gibi

Karanlık ve derindi

Ayrıldık buluşmak üzere

Sonsuza ayarlayıp saatleri.

-

Karışmış yatağımda birbirine

Kadın kokuları

Zamanlar

Umutlar, düşler

Yatağıma karışmışım ben.

-

Giydirmişler üstümüze

Bir deli gömleği gibi zamanı

Sıkışıp kalmışız

Varolmakla yokolmak arasında

aşkımız da ondan

Nefretimiz de.

-

Belleğini yitirdi ayaklarım

Silindi sanki bastığım yerler

Kaç aldanışa dayanır bir yürek

Hangi ağacın meyvesidir umut.

Nedenini unuttum varoluşumun

Belki de hiç bilmemiştim

Düşlere terk ettim sahneyi

Yalanlara teslim ettim kılıcımı.

Böyle geçip gidecek bu hayat

Nerede görülmüş

Geriye döndüğü saatlerin

Bir sevgilinin hayaliyle bitecek her şey.

-

Cinnet tarlalarında

Aradık birbirimizin 

Ayak izlerini

Herkes kendi cehenneminde

Yanıyordu 

Bulamadık.

-

Geçmişe saldık ışıklarımızı

Çoktan yitmiş yıldızlar gibi

Sürükledi yine de aydınlığımız

Zaman yeşertir çiçekleri.

-

Duygu hamalıyım ben

Şiirler taşırım ipek heybemde

Yalanlar söylerim

Gözlerinin içine baka baka gerçeğe

Rüzgarlar estiririm

İlk beni uçuran

Güneşler doğururum

İlk beni yakan

Zamanlar yaratırım

İlk beni yok eden.

-

Sığ sulara sığamam

Derinlere götür beni

Boğulmak pahasına.

-

Buraya kadar bu iş

Seninle kapattım defteri

Gitsin artık isterse hayat

Gittiği yere kadar.

-

Hep daha fazlasını istemek

Ve elde edememektir aşk.', 'Çılgın bir çiçek gibiyim seninle aynı dağbaşında açan Ne anlamak mümkün varlığımı Ne soluşumu böyle erkenden. - Bazen bir kişi için döner dü...', ARRAY['Türk Edebiyatı','Şiir','Kemal Sümer']::text[], 8.5, '{"poet":"Kemal Sümer","poet_slug":"kemal-sumer","theme":"Türk Şiiri","is_hero":false,"total_lines":215,"source_url":"https://www.antoloji.com/los-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelimeler', 'kelimeler-oguzkan-bolukbasi-p0pfq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir cümlesinde geçen zamanın

Seninle ilgili kelimeler vardı

Mevsimlerden yaz

Günlerden pazardı

Sıcak bir akşamüstü

Nedense üşümüştük

Kelimelerin vardı sen yoktun

Sen vardın kelimelerin yoktu

Bir taklit sevdaydı, bir varsayım

Bir hayal kurmaydı yaşadıklarımız

Yıldızlara gitme düşüydü

Güneşi zaptetme

Kimseye değil

Aklımızaydı zararımız

İzinsiz tutkulara koşan yüreğimiz

O yüzden titrerdi sıcak akşamüstlerinde

Zemheride kan ter içinde

Bir cümlesinde geçen konuşmanın

Senin kelimelerin vardı

Ödünç mü vermiştin

Yoksa biz mi bulmuştuk

Hatırımıza geldin gülüştük

Nedense o gün zilzurna sarhoştuk

Gece bitinceye kadar seni konuştuk

Bir yokluktu varlığımız, var sandığımız

Bir ruyaydı yaşadıklarımız

Ölümsüzlüktü aradığımız aslında

Varolmaktı gerçekten

Kimseye değil

Kendimizeydi zararımız

Olurolmaz düşüncelerde yüzen beynimiz

O yüzden esrik dönerdi

Ne zaman ayılsak 

İçimizdeki ışıklar sönerdi', 'Bir cümlesinde geçen zamanın Seninle ilgili kelimeler vardı Mevsimlerden yaz Günlerden pazardı Sıcak bir akşamüstü Nedense üşümüştük Kelimel...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/kelimeler-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gideceğim', 'gidecegim-sema-senel-dru6f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gideceğim elebet bir gün

Yaşlar gözümde sürgün

Kapına bir beyaz gül

Birakıpta gideceğim



04/06/2002', 'Gideceğim elebet bir gün Yaşlar gözümde sürgün Kapına bir beyaz gül Birakıpta gideceğim 04/06/2002...', ARRAY['Türk Edebiyatı','Şiir','Sema Senel']::text[], 8.5, '{"poet":"Sema Senel","poet_slug":"sema-senel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gidecegim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgililer günü', 'sevgililer-gunu-gunay-aktag-hxqcf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gün ondört şubat sevgililer günü

Sevgililer, bir birini sevenler

Senden başka kimseyi sevemem diyenler

Bu gün sizin, sizin gününüz

Sevginizin günü, sevgililer günü

Ya ben 

Ben hangi günü benim günüm diyeyim...

Sevgilim yoksa yok, beni sevende yok

Şimdi benim sevgililer günümde mi yok

Ya o çılgınça sevdigim günler

Delice özlemini çektigim günler

Uğruna canımı bile seve, seve 

Veririm dediğim günler....

Benim günüm deyilmiydi

Sevgilimin günü deyilmiydi

Sevgililer günü deyilmiydi

Biz  birbirimizi  sevmedikmi..

Bu gün ayrıysak 

Biz ayrıldıysak  birbirimizden

Bir sebebi vardı elbet

Bu günü hatırla

Elini viçdanına koy

Kalbini yokla

Aklına beni getir

Sonra cama koş 

Yola bak ve oku

Sevgilim  günün kutlu olsun 

Sevgililer günün kutlu olsun

Seni seviyorum, seni seviyorum, 

Ve seni seviyorum........', 'Bu gün ondört şubat sevgililer günü Sevgililer, bir birini sevenler Senden başka kimseyi sevemem diyenler Bu gün sizin, sizin gününüz Sevgin...', ARRAY['Türk Edebiyatı','Şiir','Günay Aktağ']::text[], 8.5, '{"poet":"Günay Aktağ","poet_slug":"gunay-aktag","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sevgililer-gunu-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gücüme Gidiyor', 'gucume-gidiyor-derin-oger-s6nsq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gücüme gidiyor

Zamanın ötesinde 

Eriyip yitmek

Kolay olmadı susmak

Dedim ya kolay olmadı 

Ölüyken yaşamak

Hep gücüme gitti 

Şu deli kalbime 

Seni anlatamamak

Gücüme gidiyor

Bir geceden bir geceye 

Gözümü kırpmamak

Sabahın solgun ışıklarını 

Sen diye karşılamak

Hep gücüme gitti

Nice yorgunlukların ardından

Uyuya kalmak

Gücüme gidiyor

Düğümlenmiş duyguları

Bir bir açmak

Bulutlarda gözlerini aramak

Gülmek arası ağlamak

Hep gücüme gitti.

Kanayan yaralara 

Tuz üstüne tuz basmak.....', 'Gücüme gidiyor Zamanın ötesinde  Eriyip yitmek Kolay olmadı susmak Dedim ya kolay olmadı  Ölüyken yaşamak Hep gücüme gitti  Şu deli kalbime ...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gucume-gidiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hata', 'hata-onder-gencer-k3i9t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatı hiç bitmeyecek upuzun bir roman zannederdim

Fakat; yanılmışım, 

Bir fıkra kadar kısaymış, 

Ve; 

Sonunda bitti...', 'Hayatı hiç bitmeyecek upuzun bir roman zannederdim Fakat; yanılmışım,  Bir fıkra kadar kısaymış,  Ve;  Sonunda bitti......', ARRAY['Türk Edebiyatı','Şiir','Önder Gençer']::text[], 8.5, '{"poet":"Önder Gençer","poet_slug":"onder-gencer","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hata-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul, Aşk Çıkmazı', 'i-stanbul-ask-cikmazi-turgay-kadiroglu-xsdwd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kız kulesi Üsküdar''a aşıktı, 

Üsküdar İstanbul''a

Ve İstanbul gökteki aya.

İstanbul Üsküdar''a sahipti, 

Üsküdar kız kulesine

Ve kız kulesi

Geceleri İstanbul''u kaplayan

Aydan bir parçaydı yeryüzünde.', 'Kız kulesi Üsküdar''a aşıktı,  Üsküdar İstanbul''a Ve İstanbul gökteki aya. İstanbul Üsküdar''a sahipti,  Üsküdar kız kulesine Ve kız kulesi Ge...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/istanbul-ask-cikmazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Büyük', 'en-buyuk-nazim-altundere-ss2nz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'En büyük düşümdün sen 

En  büyük hayalim, 

En asi duruşumdun sen

En masum gözyaşım

En büyük savaşımdın sen

En büyük yenilgim

En büyük mutluluğumdun sen

En büyük acım

Ve En büyük aşkımdın sen

En büyüklüklerle dolu olan...', 'En büyük düşümdün sen  En  büyük hayalim,  En asi duruşumdun sen En masum gözyaşım En büyük savaşımdın sen En büyük yenilgim En büyük mutlul...', ARRAY['Türk Edebiyatı','Şiir','Nazım Altundere']::text[], 8.5, '{"poet":"Nazım Altundere","poet_slug":"nazim-altundere","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/en-buyuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırkından Sonra', 'kirkindan-sonra-cemal-ekren-pylyg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sarımtırak bir akşamın hükmünü, 

Yokluğunda tadıyorum

Bir şiir dinletisinden arta kalan, 

Aşıkların gözyaşlarını topluyorum

Yitik ve mağrur

Bir bebeğin memeye  saldırışı gibi

Geceye saldırırım

Tüm gecelerime yokluğunu demlerim, 

Ya da

Sigaramın tütünü olursun

Her nefesimde

Hasretliğinin acısı gibi, 

Sana yanarım sana ağlarım

Yada bir kara trenin yorgunluğu oturur gözlerime, 

tüm düşlerim maviye çalar

boncuk mavisi gözlerinle

sokak aralarındaki sesler  içimin sessizliğine ortak olur

boynumda, anamdan kalan  muskam

elimde baba  yadigarı kalem

tüm sermayem bu olmalı

birde sana vereceğim yüreğim

ne tuhaf

kırkından sonra aşkı tanımak

seni tanımak', 'Sarımtırak bir akşamın hükmünü,  Yokluğunda tadıyorum Bir şiir dinletisinden arta kalan,  Aşıkların gözyaşlarını topluyorum Yitik ve mağrur ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kirkindan-sonra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yirmi yaşındayım', 'yirmi-yasindayim-cemal-ekren-auyob', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yirmi yaşındayım

Hep yaraydı

yaraydın etimde

diger gündü tuzdun yaramda

umutsuz bir gökyüzüne fişeklel atardık, 

ne güzelde gürlerdin öyle

gidebildiğin hep gündemdeydi

her an eyvallah deyip çıkıp gidebilirdin

bense gebeydim sana

ne etsen susuyordum

inkar etme, 

azıcık zorlasam seni hasretliğin dogacaktı

ipe un serecektin neredeyse

bende biçare elime yazıyordum yaptıklarını

bir gün hesap sormak vardı

hemde ensturmal bir sevdanın tutkusunda

ve beni hep dövüyorlardı

tükürüyorlardı

gülüyorlardı

bende gülüyorum, 

beş adımlık hücremin kocamanlıgında

inada / inat

bilmezlerdi acıyordum

ben tam yirmi senedir 

yirmi yaşındayım', 'Yirmi yaşındayım Hep yaraydı yaraydın etimde diger gündü tuzdun yaramda umutsuz bir gökyüzüne fişeklel atardık,  ne güzelde gürlerdin öyle g...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yirmi-yasindayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adım barış', 'adim-baris-cemal-ekren-v96ej', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Adım barış

siyah bir yüzü, 

moncuk mavisi gözleri vardı

mavi gözlerde dogardım yeniden

yeşile döner, 

zeytin karası gözlerde

ben çocuktum tüm gözlerde

tüm haykırışım, 

duvarlardan geri dönerdi

öfkemin adresi belliydi.

güneş; 

kemikleri sayılan kentimden doğardı

ben üşürdüm tüm çocuk gözleriyle

adına yoksulluk derdim.

haber ajanslarında

boncuk mavisi gözler aglardı

yetimlik önlüğünü giyerlerken..

insanlar ölmesin, 

bebeler aglamsın, 

analar agıtlar yakmasın isterdim, 

arçı depremler kentimde her gün olurdu

korkunun ve öfkenin kesiştiği yerde

bebeler büyürdü

bir ananın çıglıgıyla

töreler böyle derdi

dilimiz vardı konuşamazdık

tüm yaralarımız kangran olmuştu

yaralarımızdan beyaz güvercinler uçardı

sonsuzluğa.

adımız çocuktu

zenci, 

arap

melez

beyaz tenli

ama; 

hiç bir nufus kütüğüne akyıtlı degildik

oysa biz yaşıyorduk

dirhem dirhem öldüğümüzde

gözlerimizde selamlar yeşerirdi

okyanuslar ötesinde dökülen gözyaşlarıyla

ismini benden alırdı, 

afrikadaki bebe

benim adım barış

bana kurşun işlemez', 'Adım barış siyah bir yüzü,  moncuk mavisi gözleri vardı mavi gözlerde dogardım yeniden yeşile döner,  zeytin karası gözlerde ben çocuktum tü...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/adim-baris-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Liseli kız', 'liseli-kiz-cemal-ekren-gafyz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Liseli kız

ey mavi entarili 

kızıl gömlekli liseli kız, 

sen artık arama beni

eli silahlı adamalar

ayırdı sevdamızı

lakin sormak gelirse aklına beni; 

polis nezaretlerinde

hapishanelerde ara

bir öglenden sonraydı ellerim baglandı

insan çıglıkları gelen bir yere götürüldüm

o çıglıklarki sohbetine doyamadığım dostlarımın  çıglıklarıydı

ayakalrım yerde çıplak 

çıplaklığa baglanmıştı

hain manyato.

her çevirilişinde haykırışım

sendin liseli kız

sendin diyarbakır', 'Liseli kız ey mavi entarili  kızıl gömlekli liseli kız,  sen artık arama beni eli silahlı adamalar ayırdı sevdamızı lakin sormak gelirse akl...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/liseli-kiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyku', 'uyku-selvi-celik-gdovx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sensiz yasamak cok zor oluyor.

Bu düsmanligin neden? 

Gündüzler geceler karisti sayende.

Mutsuzum huzursuzum     sensiz gecelerde.

Gün degil ay degil yillardir hasretim.

Gel yillarin ozlemi var.

Hep küskünüm yastigima.

Gözlerim yastigimi yikamaktan usandi yaslarla.

Kavgalarim hic bitmedi.

Artik bahaneler bitti.

Suclamalar bitti.

Yorganim dagin tasi gibi agir geliyor.

Dösegim tikenler icinde tuzak dolu.

Korkuyorum yatmaktan.

Bu düsmanligin neden? 

Bu kiskancligi bitir.

Gel ne olursun kurtar azaptan uykum.

Yasanmiyor tadi yok dünyanin sensiz

Arada bir geldiginde biliyormusun? 

Nasil sevinclerimin costugunu...

Hayallerimi rüyamda gördügümde, 

Hic geliyor korkular kabuslari görsemde.

Yalvarmadim hic kimseye bu kadar.

Kücülmedim onursuzca hic bir zaman.

Bak.. sana yalvariyorum.

Gel zalim''de olsam zulum''da olsam.

Seni benden cok özleyen yoktur.

                                               Uykum....', 'Sensiz yasamak cok zor oluyor. Bu düsmanligin neden?  Gündüzler geceler karisti sayende. Mutsuzum huzursuzum     sensiz gecelerde. Gün degil...', ARRAY['Türk Edebiyatı','Şiir','Selvi Çelik']::text[], 8.5, '{"poet":"Selvi Çelik","poet_slug":"selvi-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/uyku-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık gecede mehtabım olsan', 'karanlik-gecede-mehtabim-olsan-nuri-can-lk4q7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karanlık gecede mehtabım olsan

Süzülsen o hayal sessizliğinle

Dilinde nağmeler elinde keman

Okşasan ruhumu güzel sesinle

Özge canım olsan gönül yoldaşım

Bir ömür dizinde dinlense başım

Akarsa uğruna aksın gözyaşım

Yakarsa ateşler yaksın elinle

Bir daha sönmesin içimde közün

Bir daha çalmasın kapımı hüzün

Çiçekler açtırsa gülünce yüzün

Dağılsa efkarım gül nefesinle

Kimse okşamasın al yanağını

Öpmesin başkası gül dudağını

Bana bağışlasan gönül bağını

Sevgiden bir yuva kursak seninle

16/12/1977  Arnhem', 'Karanlık gecede mehtabım olsan Süzülsen o hayal sessizliğinle Dilinde nağmeler elinde keman Okşasan ruhumu güzel sesinle Özge canım olsan gö...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/karanlik-gecede-mehtabim-olsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalabalık', 'kalabalik-sair-masmavi-tat0o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şaşırdım önce

Bakakaldım karşımdaki ''ben''e

Çocukluğumun çıkmaz sokaklarının başındaydım.

Korktum önce

Elimi tutunca o ''ben'' sakinleştim

Adımladım ürkekçe sokağı.

Gülümsedim sonra

Gülümseyince ''ben'' yüzüme

O yüksek avlu kapısının önünde.

Duruldum sonra

''ben''lerden ''biz'' olup

Çocukluğumun karadutlu bahçesine girince.', 'Şaşırdım önce Bakakaldım karşımdaki ''ben''e Çocukluğumun çıkmaz sokaklarının başındaydım. Korktum önce Elimi tutunca o ''ben'' sakinleştim Adım...', ARRAY['Türk Edebiyatı','Şiir','Şair Masmavi']::text[], 8.5, '{"poet":"Şair Masmavi","poet_slug":"sair-masmavi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kalabalik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuyruklu Yıldız', 'kuyruklu-yildiz-murat-tali-pupa8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ne güzeldir düşlere dalmak 

bir bulutun koynunda, 

bir sabah uyanıp 

güneşin kollarında 

yada sarınıp yatmak samanyolunda. 

Aşk nereye gider 

kaç ışık yılı uzaklıktadır bize... 

Bir ışık yılı aşk yükledim terkine zamanın. 

sevdanı da yükle 

yalnız değilsin yollarda 

bak bir kuyruklu yıldız daha geçti 

peşine en güzel 

sevdaları takarak...', 'ne güzeldir düşlere dalmak  bir bulutun koynunda,  bir sabah uyanıp  güneşin kollarında  yada sarınıp yatmak samanyolunda.  Aşk nereye gider...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kuyruklu-yildiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-hikmet-yakisir-fxtwe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gel dersem gelirmisin dedi, 

Biraz düşündüm, 

Hayır dedim.

Ertesi gün tekrar sordu, 

Gelirmisin diye, 

Evet dedim bu kez, 

Gittim.

Bir akşam üstü, 

Denizin kucağına attım kendimi, 

Martılar eşlik etti bana yolculukta.

Vardım gittiğim yere, 

Bir köprü altında bekliyordu beni, 

Buluştuk.

Sarıldık...Koklaştık...Öpüştük.

Dalgaların notalaştığı, 

Martıların uçuştuğu, 

Balık kokulu bir yere oturduk.

Salaş bir yer.

Balık olurda rakı olmaz mı? 

Rakı-Roka-Balık üçlüsü 

Eşlik etti bize o akşam üstü.

Kafalar dumanlı, 

Gözler ihtiraslı 

Bakıyoruz birbirimize.

El ele tutuşup yürümeye başladık, 

Yosun kokulu sahilde.

Deniz havasını solurken

Kulağına tatlı sözler fısıldıyordum.

Özlem derindi, 

Alkol körüklemişti, 

Sarılıp koklaştık önce, 

Ateş dudaklar yakarken, 

Bedenler birleşti, tek vücut olduk.

Alkol kokan tenler

Sarhoş etmişti ikimizi de.

Mest olmuş bedenlerimiz, 

Sarılarak derin bir uykuya daldık.

Ne kadar zaman geçti bilmiyorum, 

Uyandığımda yalnızdım.

Sessizce gitmiş miydi? 

Bırakıp ta beni... düşündüm.

Tatlı bir rüyadan uyanıyordum.

(04 Temmuz 2003)', 'Gel dersem gelirmisin dedi,  Biraz düşündüm,  Hayır dedim. Ertesi gün tekrar sordu,  Gelirmisin diye,  Evet dedim bu kez,  Gittim. Bir akşam...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yakışır']::text[], 8.5, '{"poet":"Hikmet Yakışır","poet_slug":"hikmet-yakisir","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/dus-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nostalji', 'nostalji-i-brahim-bayraktar-9w215', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ocağın başında elimde bir maşa,

Külleri, ince ince ezmek isterim.

Şöyle sıra, sıra bir baştan, bir başa,

Közlere, katıkları dizmek isterim.

Pek lezzetlidir, mercimekli tarhana, 

Kahveye girsen bir gırgır, bir şamata,

Şimdi işim-gücüm var, karnım toksa da,

Çarşıda aylak aylak gezmek isterim.

Elimde bir çubuk, ucunda da olta,

Çiçek toplarken kırlarda, bayırlarda,

Ayağımı çıkarıp, tozlu yollarda,

Topraklara adımı yazmak isterim.

Yazın balık tutardık biz Uluçay’da,

Şimdi bir damla su kalmadı ne fayda,

Mektep kapanıp karne aldığım ayda, 

“Yaşasına” atlayıp yüzmek isterim.

Önümde bir çift öküz, ardında saban,

Boyunduruğa koyup ağır bir taban,

Oku oğlum! Uğraşma, dese de babam,

Hiç olmazsa bir evlek çizmek isterim.

Şöyle epeyce büyük bir tarla bulup,

Serin esen rüzgârı ardıma alıp,

Üç beş kişi toplanıp, bir de kol kurup,

Tarladaki ekini biçmek isterim.

Tınazları savurup çeçi alınca,

Harmanla, fiyen dibi bize kalınca,

Hava kararıp yat zilleri çalınca,

Bağları, bahçeleri bozmak isterim.

Karnım acıksa anam bir ekmek verse,

Soğan ile peyniri güzelce dürse, 

Önüme baklavayı, böreği serse, 

Yine de cizlemeyle doymak isterim. 

Sabahtan akşama dönse düvenler,

Güneşten kavrularak kararsa tenler, 

Çalışmaktan kabarsa nasırlı eller,

O nasırlı elleri öpmek isterim. 

Yuvalardan yavru kuşları almayı,

Yarı çıplak atlayıp suya dalmayı,

Bahçelere dalıp da acı elmayı,

Ceplerime doldurup tüymek isterim.

Kuzular meleşir anneyi görünce,

Sanki mani söylerler gelin, görümce,

Tan ağarıp da kuşluk vakti gelince,

O manalı sözleri duymak isterim.

Unutmak mümkün değil tahta beşiği,

Bin bir renge boyanmış şimşir kaşığı,

Çecin yanına serip kaba döşeği, 

Gökteki yıldızları saymak isterim.

Meyveyi “ağır ağırına” alırdık,

Sepetle gelirken uzaktan tanırdık,

Hayatı hep böyle kalacak sanırdık,

O günlerin sırrına ermek isterim.

Çan sesleriyle çağlayan dereleri,

Dağ, bayır demeden gezen sürüleri,

İçip içip nara atan delileri,

Nur yüzlü velileri görmek isterim.

Her bayram çıkışında dursam sıraya,

İtişip, kakışarak girsem araya, 

Ara sıra da olsa gelip sılaya,

Yüzümü topraklara sürmek isterim.

Mandalar maalesef oldular mazi

Kara öküz, boz eşek çoktan arazi,

Anadutları sorma hepsi de gazi!

Onlara yeniden kavuşmak isterim.

Yayıklar çatlamış, pişekler kırılmış,

Kızılcık şerbeti anılarda kalmış,

Ayranın yerini meşrubatlar almış,

Ben, yoğurdu özeyip içmek isterim.

Tırmık ile yabayı astık tavana,

Dibeğin işini bıraktık havana,

Sergende dizili kapaklı sahana,

Cevizleri doldurup kırmak isterim.

Çelik çomak oynardık hayvan önünde,

Kapı, kapı gezerdik bayram gününde,

Şimdi bilgisayar olsa da önümde,

Ben, o eski günlere dönmek isterim. 

Sacdan yeni alınmış hamurlu bulsam,

Ortasını yarıp bir kepçe yağ koysam,

Bandırarak yiyip de iyice doysam,

Yanında da bir tepsi keşkek isterim.

Bir kucak tezek ile ateşi yaksam,

Patatesleri söküp içine atsam,

Üzerine tuz döküp küllüyle yutsam,

Koyutmaç bulamazsam kaymak isterim.

Hey Atkaracalar! Ben, sana aşığım,

Bu yoldan dönersem kırılsın kaşığım,

Düven taşı çakmağım, saban kışlığım,

Şimdi vatan uğruna yanmak isterim.

O muhabbetli günler dönmez ki başa, 

Hepsi uçup gittiler döndüler kuşa,

Özlemedim dersem hâşâ! Sümme hâşâ!

Maziyi, önünüze sermek isterim.

İbrahim Bayraktar, Çankırı’dır İl’im,

Bundan fazlasını söylemiyor dilim,

“Küçük Çayırlığa” serip de bir kilim,

Geçmişi hayalimde görmek isterim.

16.08.1998/ANKARA', 'Ocağın başında elimde bir maşa, Külleri, ince ince ezmek isterim. Şöyle sıra, sıra bir baştan, bir başa, Közlere, katıkları dizmek isterim. ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":97,"source_url":"https://www.antoloji.com/nostalji-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Olsam', 'ben-olsam-naime-erlacin-jb7ur', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-Şule’ye sevgilerimle..

kocaman bir yudum sevda al

terli bir rüya bırak geceye

iyi bak 

sıcak mı ''yar'' yüreği! 

yaz ateşi mi yanmakta gözlerinde

gecekarası bir aşk mı 

sarmalayan “şeker karası” hüzünleri

çiçeğe vurmuş dallarda 

anlamı ne 

ilk sağanakta küskün durmanın hayata

koş ey âşık! 

devam et yoluna

koşardım ben senin yerinde olsam

gizlendiğin köhne kenti unutacaksın bir gün

gözbebeği ol şafağın, rüzgârın kendisi

açık denizde şarkılar söylenmeli 

tutunmayı unutma deniz kuşlarına

uçardım ben onlarla senin yerinde olsam

keyfini çıkar tutuşarak sevmenin

yağmur düşmeden yürek yangınlarına

kapılar kapanmadan henüz 

ne olur hercaileş 

çocuklaş 

havaileş

şımart kendini kuyularda saklayarak hüznünü

saklardım ben senin yerinde olsam 

şimdi büyücü ol kendine şeker kız

bak birileri bayram ediyor

bugün dörtTemmuz

böyle yapardım ben senin yerinde olsam 

(04 Temmuz 2003)', '-Şule’ye sevgilerimle.. kocaman bir yudum sevda al terli bir rüya bırak geceye iyi bak  sıcak mı ''yar'' yüreği!  yaz ateşi mi yanmakta gözler...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ben-olsam-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Geceler', 'sensiz-geceler-i-brahim-bayraktar-33imd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sensiz geçen şu uzun gecelerde, 

Yapayalnız kaderinle baş başa, 

Düşünmek, sadece ve sadece seni, 

Senin özlemini duymak, hayalinle yaşamak, 

Şiirler yazmak senin için.

İçine kapanmak, duygularını mısralara dökmek, 

Seninle olmayı düşünmek sadece...

Uzaklardan sana seslenmek, 

Fakat, sesimi duyuramamak, 

Çaresizlik içinde uykuya dalmak, 

Ne kadar zor bir bilsen.', 'Sensiz geçen şu uzun gecelerde,  Yapayalnız kaderinle baş başa,  Düşünmek, sadece ve sadece seni,  Senin özlemini duymak, hayalinle yaşamak,...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sensiz-geceler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir yürek...', 'bir-yurek-ensar-cevval-sm9wu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yüreğe ateş düşünce

yüz üstü kapaklanır toprağa

toza, çamura bulanır, ayaklanır

yaralanır, kanar her yanı

ayıplanır..

Bir el uzanır sıcak mı sıcak

alır koynuna, ısıtır, 

doyurur. büyütür göğsünde

bir ana şefkatinde, sıcaklığında.

Miske, reyhana, nura yatırır

cennet bahçelerinin esintisinde.

Sadakat bekler o sıcak eller

bir gül, bir söz, bir tebessüm

özveri bekler, minnet bekler

ya koynunda soldurur kendi solunca

ya da çamura yollar gururu kırılınca.', 'Bir yüreğe ateş düşünce yüz üstü kapaklanır toprağa toza, çamura bulanır, ayaklanır yaralanır, kanar her yanı ayıplanır.. Bir el uzanır sıca...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz', 'deniz-cennet-sengul-924xn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni almıştı...Gecenin karanlığından 

bir deniz yaptım kendime 

Balıklar çizdim, dalgalar köpürttüm.

Bir gemi çizdim çılgın dalgalara, 

Ve bir denizci...Koskoca karanlığımın denizinde, 

 Yapayalnız, tek başına bir denizci..

Dalgaların çıkardığı seslere şarkılar, rüzgarın uğultusuna şiirler besteliyor, Yosun kokusuna ''sen'' diye hitap ediyordu.Her şey tam, hiç bir şey eksik değil gibi, 

Denizci rahat, gemi rotasında.

Karanlıklar içinde bir fener ışığı parıldadı...Yaklaştıkça büyüyor, büyüyordu...

Denizci kovalıyor, fener kaçıyordu, 

Rüzgar kesildi aniden..! 

Dalgaların sesi yok artık, Yosunda kokmuyor, 

Dünya karanlığa gömüldü sanki.Fenerde kayboldu... 

Birden kabardı deniz, Kabardı, kabardı.. 

Patladı şimşekler ardı ardına, 

Denizciyi çağırıyor, onu istiyordu sanki...Bir şeyler vardı karanlığın altında...''Gel'' diyordu, 

''Gel bekliyorum'' diyordu... Ve...Sıyrıldı çatlak elleri, 

boyası soyulmuş o eski dümenden...

Sese yöneldi ve hiç tereddütsüz kayboldu karanlıkta...! 

 Deniz dindi...Dalgalar yine sesli, Rüzgar yine şiirsel...

''Evet'' karanlığım istediğini almıştı..

.Beni, benliğimi...

Seni almıştı...', 'Seni almıştı...Gecenin karanlığından  bir deniz yaptım kendime  Balıklar çizdim, dalgalar köpürttüm. Bir gemi çizdim çılgın dalgalara,  Ve b...', ARRAY['Türk Edebiyatı','Şiir','Cennet Şengül']::text[], 8.5, '{"poet":"Cennet Şengül","poet_slug":"cennet-sengul","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/deniz-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-seyit-ahmet-duzen-jhicf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne aşklarda eskimişim 

Senden bi_haber ben

Ne aşklara mezar olmuşum

Mayin tarlasinda

Seni arayan ben', 'Ne aşklarda eskimişim  Senden bi_haber ben Ne aşklara mezar olmuşum Mayin tarlasinda Seni arayan ben...', ARRAY['Türk Edebiyatı','Şiir','Seyit Ahmet Düzen']::text[], 8.5, '{"poet":"Seyit Ahmet Düzen","poet_slug":"seyit-ahmet-duzen","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ben-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Kuyuları', 'gece-kuyulari-naime-erlacin-vipnv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gece kendini gömer

kazdığı mezara

karanlıkta parçalanır uyku

bir düşünür bir durur

bir durur bir düşünürüm

gül damlası yaşlarla yanağımda

gecenin paslı çarkları 

goncalaşır akşamda

kazarım sineme derin bir kuyu

bağrımda hançer saklı

bırakırım ıssızlığa kendimi

gecenin karanlık sularında

(04 Temmuz 2003)', 'gece kendini gömer kazdığı mezara karanlıkta parçalanır uyku bir düşünür bir durur bir durur bir düşünürüm gül damlası yaşlarla yanağımda ge...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gece-kuyulari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçim Acıyor', 'i-cim-aciyor-ozlem-aman-mjblh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'içim acıyor.

gülün dikenleri batıyor bir bir yüreğime, 

hemde kırmızı gülün

uğrunda kanımla suladığım, 

kırmızı gülün dikenleri bir bir batıyor yüreğime.

batıranda bülbül misalii sevdiğim insan

asıl bu yüreğimi kanatıyor.

bu kadar mı değersizdim

bu kadar mı bir hiçtim onun için

yelkovan misali akrebi kovalayan

hep benmiydim

benmiydim tek seven canından çok

benmiydim kokundan ayrılamayan

acı çeksede 

sevgisi uğruna katlanan ben miydim? 

şimdi bir hiç uğrunda üzülen 

gururunu artık kaldıramayan bu benmiyim', 'içim acıyor. gülün dikenleri batıyor bir bir yüreğime,  hemde kırmızı gülün uğrunda kanımla suladığım,  kırmızı gülün dikenleri bir bir batı...', ARRAY['Türk Edebiyatı','Şiir','Özlem Aman']::text[], 8.5, '{"poet":"Özlem Aman","poet_slug":"ozlem-aman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/icim-aciyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
