INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duyarsız', 'duyarsiz-i-zzet-selcuk-cumaoglu-4fqyi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin bir saatinde

Hiç işim gücüm yok gibi

Kalkarım yataktan

Ve seni düşünürüm

Sanki bir matah gibi.

Hoş

Yattığım zaman da

Gün boyunca olduğu gibi

Hep aklımdasın aslında.

Yatağım çivilerle dolu

Uyku gözlerime küsmüş

Gelmek bilmiyor.

Gece hayallerimde eriyip tükeniyor

Hayalin dudak uçlarımda.

Yıldızların çığlıklarını dinliyorum

Sana ninni söylüyor.

Sende ise, değil ben 

Dünya bile umurunda değil 

Kim bilir şu saatte

Kaçıncı pire uçuşuyor.', 'Gecenin bir saatinde Hiç işim gücüm yok gibi Kalkarım yataktan Ve seni düşünürüm Sanki bir matah gibi. Hoş Yattığım zaman da Gün boyunca old...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/duyarsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudum Kırıldı', 'umudum-kirildi-i-zzet-selcuk-cumaoglu-r34yu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hafta sonları yürüyüş yaptığın 

Bel ki görürüm diye

O parkura geldim

Ama yoktun.

Birkaç kez ben yürüdüm boydan boya

Senin yerine

Gelmedin

Umudum kırıldı.

Belki duyarım sesini diye

Telefonla aradım seni

Kâh evini kâh işyerini

Cevap bile vermedin.

Umudum kırıldı.

Sabahın köründe

Evinin etrafında dolaşıp durdum

Sokak itleri gibi.

Yaşadığın o sokak

Gecenin yorgunluğunu

İçine sindiriyordu.

Sanırım sen uyuyordun

Pencerende yoktun.

Çıldıracak gibi oldum

Umudum kırıldı.

Bu yaşta bu karasevda

Öldürecek beni biliyorum

Dünyamı karartıp

Umutlarımı yıktın

Senin de umutlarını yıkmalarını diliyorum.', 'Hafta sonları yürüyüş yaptığın  Bel ki görürüm diye O parkura geldim Ama yoktun. Birkaç kez ben yürüdüm boydan boya Senin yerine Gelmedin Um...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/umudum-kirildi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köpek', 'kopek-i-zzet-selcuk-cumaoglu-b4w6p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen başımın belası tatlı bir cadısın, 

Baktın mı gözlerime içim titrer ürperirim.

Dizlerimin çözülür de bağları

Köpeğin olurum.

Yoksan yanımda, 

Kızar hatta küfrederim ağız dolusu

Yanımdayken, 

Bir de sevgi dolu okşamışsan saçlarımı

İçim bir tuhaf olur da 

Erir adeta kemiklerim.

Sanki iliğim boşalır, 

Elim ayağım birbirine dolaşır, 

Sakarlığım tutar

Sarhoş olurum.

Sen başımın tatlı belası sevimli cadı

Aç susuz vaziyette

Bil ki

Hâlâ köpeğin seni beklemekte.', 'Sen başımın belası tatlı bir cadısın,  Baktın mı gözlerime içim titrer ürperirim. Dizlerimin çözülür de bağları Köpeğin olurum. Yoksan yanım...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kopek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adak', 'adak-i-zzet-selcuk-cumaoglu-wjbbt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir özgürlük uğruna canlar verilir

Gönüllü tutsak oldum senin aşkına

Çekilir de kılıçlar, başlar kesilir

Ben başımı severek adadım sana.

Esirgemem sevgimi yeter ki iste

Derdimin çaresi yok, yüreğim hasta

Sevdam çırpınır durur bu can kafeste.

Ben canımı severek adadım sana.

Akıp gitmez şu gönlüm başka güzele

Erdi yaşım kemale, döndüm gazele

Damarımda kanım ol orda gezele

Ben kanımı severek adadım sana.', 'Bir özgürlük uğruna canlar verilir Gönüllü tutsak oldum senin aşkına Çekilir de kılıçlar, başlar kesilir Ben başımı severek adadım sana. Esi...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/adak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşkınım', 'saskinim-i-zzet-selcuk-cumaoglu-66p5t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saplanıp kaldı aklım kör bir çıkmaza, 

Girdaba düşmüş gibi döner dururum.

Yağmurdan medet uman akasya gibi, 

Beklerken sevgi senden, kurur dururum.

Halim nicedir benim, var mı haberin, 

Kahrını çekiyorum yaban ellerin, 

Sevmesen de sadece vefa beklerim, 

Kâinattan bihaber olur dururum.

Sudan çıkmış bir balık gibiyim şimdi, 

Çırpınır dururum susuz kovada.

İntihara yeltenen balina gibi, 

Okyanustan karaya vurur dururum.', 'Saplanıp kaldı aklım kör bir çıkmaza,  Girdaba düşmüş gibi döner dururum. Yağmurdan medet uman akasya gibi,  Beklerken sevgi senden, kurur d...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/saskinim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Anlat Biraz', 'hadi-anlat-biraz-i-zzet-selcuk-cumaoglu-7w3p2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nasıl bir şeydir, 

Yosunu koklamak gibi mi gül dururken

Ya da dar bir pabucu giymek gibi mi? 

Nasıl bir şeydir, 

Hadi anlat biraz.

Hadi anlat biraz nasıl bir şeydir

Görüp de görmezden gelmek.

Kalbi çarpıyor mu insanın

Yoksa umursanmıyor mu? 

Hatırı geçmiyor mu sevdanın.

Nasıl bir şeydir, 

Hiç akla gelmiyor mu

Sevişmiş, öpüşmüş, koklaşmış olmak.

Hatıraların yeri yok mu? 

Hadi anlat biraz.

Tanımıyormuş gibi yanından geçip gitmek kolay mı? 

Bakmadan bulut kümesi gözlerine, 

Kokusunu duymadan.

Hadi anlat biraz

Kalbin ıpıldamıyor mu? 

Gönlün rahat mı? 

Hadi anlat biraz huzurlu musun? 

Yoksa içinden ağlıyor musun? 

Gerçekten öyle pervasız olabiliyor musun? 

Hadi anlat biraz, 

Görüp de görmezden gelmek

Gelebilmek 

Gerçekten bu kadar kolay mı?', 'Nasıl bir şeydir,  Yosunu koklamak gibi mi gül dururken Ya da dar bir pabucu giymek gibi mi?  Nasıl bir şeydir,  Hadi anlat biraz. Hadi anla...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hadi-anlat-biraz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakışmıyor Hiç Sana', 'yakismiyor-hic-sana-i-zzet-selcuk-cumaoglu-fwe0c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne kadar da zalimsin bakmadın gözlerime, 

Bir baksaydın derinden, üzülürdün halime, 

İçirdim gözyaşımı hüzün dolu gönlüme, 

Bu kadar vefasızlık yakışmıyor hiç sana.

O hırçın bakışların ateş gibi kavurdu, 

Deli bir rüzgar gibi yerden yere savurdu, 

O aldırmaz duruşun beni sırtımdan vurdu, 

Bu kadar vefasızlık yakışmıyor hiç sana.

Seviyorum diyerek, hiç durmadan okşadın, 

Beklemediğim anda ağır geldi tokadın, 

Kendi elinle yıktın, gönlümdeki mabedin, 

Bu kadar vefasızlık yakışmıyor hiç sana.', 'Ne kadar da zalimsin bakmadın gözlerime,  Bir baksaydın derinden, üzülürdün halime,  İçirdim gözyaşımı hüzün dolu gönlüme,  Bu kadar vefasız...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yakismiyor-hic-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-mustafa-kemal-sen-xsose', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ne kadar şanslı yaşadığın şehir, 

ve ne kadar şanslı evin, 

yanındaki dostların, 

giydiğin elbisen, 

dokunduğun her sey...

bir kapı kolu, 

tuttuğun telefon, 

dudağındaki ruj, 

gözünde rumelin, 

parmağını saran yüzüğün, 

boynundaki gerdanlığın...

Saçındaki tarak, 

bastığın toprak, 

ne kadar şanslı, 

seni gören ne varsa şimdi...

ne kadar şanslı ey sevgili', 'ne kadar şanslı yaşadığın şehir,  ve ne kadar şanslı evin,  yanındaki dostların,  giydiğin elbisen,  dokunduğun her sey... bir kapı kolu,  t...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kemal ŞEN']::text[], 8.5, '{"poet":"Mustafa Kemal ŞEN","poet_slug":"mustafa-kemal-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgiliye-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilerim', 'dilerim-i-zzet-selcuk-cumaoglu-li641', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dileklerim tutacak bak nasıl yanacaksın, 

Gözyaşın dinmeyecek, her an ağlayacaksın, 

Merhametsiz sevdanın içini yakışında, 

Binbir sızı duyarak adımı anacaksın.

Bakmaya kıyamazken o ela gözlerine, 

Kanıp da nasıl gittin şeytanın sözlerine, 

Gözyaşında rastlarsın  kalbimin izlerine, 

Buz gibi bir sevdada, üşüyüp donacaksın.

Oynuyorsun benimle, aslında sen haklısın, 

Biliyorsun ki benim yüreğimde saklısın.

Ne kadar sevsem bile, sevgime yasaklısın, 

Yapayalnız kalınca beni anlayacaksın.', 'Dileklerim tutacak bak nasıl yanacaksın,  Gözyaşın dinmeyecek, her an ağlayacaksın,  Merhametsiz sevdanın içini yakışında,  Binbir sızı duya...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dilerim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kasılıp Durma', 'kasilip-durma-i-zzet-selcuk-cumaoglu-7gbsa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güzel olmak yetmiyor, ruhun güzel olmalı, 

Sohbet edince insan, içi huzur dolmalı, 

Baktıkça gözlerine, aşkı sende bulmalı, 

Kasılıp durma güzel, kof bir ağaç gibisin.

Dünyayı yaratmışsın sanılıyor halinden, 

Acı sözler dökülür bal damlayan dilinden, 

Hiçbir farkın yok gibi, dün evlenen gelinden, 

Kasılıp durma güzel, kof bir ağaç gibisin.

Var mı benim gibisi, şefkat ile bakacak, 

Arama bulamazsın, hasretinden yanacak, 

Bu zamanda yok gibi, tatlı dile kanacak, 

Kasılıp durma güzel, kof bir ağaç gibisin.

Güzel günler yaşadık, hatırın var yanımda, 

Sen dolaşır durursun, bozulmamış kanımda, 

Unuturdum ben seni olmasaydın canımda, 

Kasılıp durma güzel, kof bir ağaç gibisin.', 'Güzel olmak yetmiyor, ruhun güzel olmalı,  Sohbet edince insan, içi huzur dolmalı,  Baktıkça gözlerine, aşkı sende bulmalı,  Kasılıp durma g...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kasilip-durma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok mu Gördün', 'cok-mu-gordun-i-zzet-selcuk-cumaoglu-pivtd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'çok mu gördün yüzüme bir anlık tebessümü, 

Hicrana boğdun beni,  doyurdun hasretine, 

Yaktın benim canımı, güldürmedin yüzümü, 

Ah’ımdan başka senin, bir şey geçmez eline.

Bu kadar büyük aşka layık mıdır bu zulüm, 

Bir gün sen de çekersin, bu kadar olma zalim, 

İbret olmalı sana, yanıp kavrulan halim, 

Hırpalayıp durmasın, sahip ol da diline.

Varsa biraz insafın, yüreğime kulak ver, 

Bırakıp gitmek kolay, hüner sevebilmekte.

Tattın mı hiç bilmem ki, aşkın ne olduğunu, 

Diliyorum senin de ateş düşsün içine.', 'çok mu gördün yüzüme bir anlık tebessümü,  Hicrana boğdun beni,  doyurdun hasretine,  Yaktın benim canımı, güldürmedin yüzümü,  Ah’ımdan baş...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cok-mu-gordun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Mümkün', 'ne-mumkun-i-zzet-selcuk-cumaoglu-i0anm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ay ışığı topladım yakamozlardan

Bin deniz yıldızı attım denize

Çıplak ayaklarımla yedim toprağı

Yine de sönmedi yüreğimin yangını.

Bu derdin ne olduğunu bilmiyorum.

Gökyüzündeki yıldızların 

Gözbebeklerine baktım

Baştan çıkartmak ne mümkün.

Dağınık saçlarını yoldum huysuz gecenin

Ağlatmak ne mümkün.

Yine de sönmedi yüreğimin yangını.', 'Ay ışığı topladım yakamozlardan Bin deniz yıldızı attım denize Çıplak ayaklarımla yedim toprağı Yine de sönmedi yüreğimin yangını. Bu derdin...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ne-mumkun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Beri', 'gel-beri-mustafa-tanrikulu-h7zri', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gel...

rüzgar sana kanat olsun 

uçmak sana sanat olsun

gel...

gel...

öpeyim  nûr  ellerini

dinleyeyim dillerini

gel...

gel

hasret sana hissim fikrim 

gel dökülsün pasım kirim

gel

gel 

yurdum yuvam sensin ki bil

bütün hasretlerimi sil

gel...

gel 

hasid kıldın ma''şukları....

leyl u şirin aslıları

gel', 'gel... rüzgar sana kanat olsun  uçmak sana sanat olsun gel... gel... öpeyim  nûr  ellerini dinleyeyim dillerini gel... gel hasret sana hissi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gel-beri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama Yeter ki', 'aglama-yeter-ki-i-zzet-selcuk-cumaoglu-mmv5k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Akmasın gözlerinden bir yudum göz yaşı, 

İçime düşen sızıya dur diyemem çünkü

Varsın boş kalsın gönüller, sen ağlama yeter ki

İçimde ki o boş çırpınışlar yaksa da beni

Kıyamam, dökme göz yaşlarını boşuna

Haydi kurula kirpiklerini.

Çaresiz değiliz 

Kör kütük bağlansak da hayata, 

Umarsız dertlere düşmedik ki hiç birimiz

Kim ne derse desin aldırma sakın

Göster yüreğini, cesaretini

Daha neyin varsa hepsini.

Yıkılma sakın, dökme gözyaşlarını, 

İçime düşen sızıya dur diyemem çünkü

Boş ver sensizliğime, sen ağlama yeter ki.', 'Akmasın gözlerinden bir yudum göz yaşı,  İçime düşen sızıya dur diyemem çünkü Varsın boş kalsın gönüller, sen ağlama yeter ki İçimde ki o bo...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aglama-yeter-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllara Sitem', 'yillara-sitem-i-zzet-selcuk-cumaoglu-2cdt3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uçup giden yıllara çok sitemim var, 

Neden böyle habersiz vurup gittiniz.

İnsafsız davranıp da boynumu bükük, 

Acı dolu yürekle koyup gittiniz.

Gençliğimi tüketip serdim yollara, 

Açtım da gonca gibi döndüm güllere, 

Döküldüm salkım salkım verdim ellere, 

Kurumuş bir dal  gibi kırıp gittiniz.

Ömür olmuş dört mevsim, gelip geçerken, 

İnsanoğlu dünyadan konup göçerken, 

Kimileri keyifle  bade içerken, 

Bana bir kadeh zehri sunup gittiniz.', 'Uçup giden yıllara çok sitemim var,  Neden böyle habersiz vurup gittiniz. İnsafsız davranıp da boynumu bükük,  Acı dolu yürekle koyup gittin...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yillara-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canımı Alır', 'canimi-alir-i-zzet-selcuk-cumaoglu-8d7y0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne zaman bir telefon çalsa

Sen sanırım

Yüreğimi bir telaş alır

Açtığımda telefonu

Duyamazsam sesini

İçimi saran o heyecan

Bir hıçkırık olur

Boğazıma tıkanır.

Ne zaman kapı vurulsa

Sen sanırım

Yükselir ateşim

İçim yanar.

Gelen sen değilsen

Yığılır kalırım oracığa

Gözlerim sulanır.

Bu telaş bu heyecan

Kangren olur da

Canımı alır.', 'Ne zaman bir telefon çalsa Sen sanırım Yüreğimi bir telaş alır Açtığımda telefonu Duyamazsam sesini İçimi saran o heyecan Bir hıçkırık olur ...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/canimi-alir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı..', 'adi-melek-midikoglu-9in4x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin adın eziyet

Türlü türlü meziyet

Bin cefada ceksem

Binbire canımı serem

Siyahla beyaz gibiydik

Griye eğilmedik

Yendik yenildik ama

Yolu bize çevirmedik

Senin adın ne? 

Halim nedir! 

Derman kim...', 'Senin adın eziyet Türlü türlü meziyet Bin cefada ceksem Binbire canımı serem Siyahla beyaz gibiydik Griye eğilmedik Yendik yenildik ama Yolu...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/adi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '80.Yılımız', '80-yilimiz-sair-erdinc67-v74n8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dünyanın merkezi ülkem kucaklar herkesi

atatürkün yurdu milletimi doğurdu

yurdum sana canım bayrağıma kanım feda

milletim milletim sarılalım ana yurda

milletler geldi geçti türk kalacak

türkü türk yapan gençlerim olacak

milletime nice şanlar yaşatacak

milletim milletim sarılalım ana yurda

bu gün   80. yılımız kutlu olsun

şehitlerimize hak baki olsun

ülkemize canımız feda olsun

milletim milletim sarılalım ana yurda

bu ülke bu ülke nasıl kurtuldu bilirmisin

can vermek o kadar kolaymı sen veririmisin

türk türk oğlu isen feda edersin canını

milletim milletim sarılalım ana yurda

ana yurdum için savaştı dedelerimiz

sana miras kaldı bu vatan tertemiz

daha ileri götür ey benim gençliğim

milletim milletim sarılalım ana yurda

bayrağım şehitler kanıdır yıkamam

vatanım şehitler vatanıdır bırakmam

askerim barış timsalidir bozamam

milletim milletim sarılalım ana yurda

türkü türk yapan atam sen rahat uyu

bu gençlik var oldukça türk ölmeyecek

dünyaya barışı senin gençliğin getirecek

milletim milletim sarılalım ana yurda

gençiğime bakınca içime güneş doğuyor

vatanıma baktıkça barış dünyaya yayılıyor

türk vatanından  sıkça söz ettiriyor

milletim milletim sarılalım ana yurda

yok türkten başka barışı sağlayacak

barışı isteyen baki atatürk kalacak

gençler  uyun atamın  emirlerine

milletim milletim sarılalım ana yurda', 'dünyanın merkezi ülkem kucaklar herkesi atatürkün yurdu milletimi doğurdu yurdum sana canım bayrağıma kanım feda milletim milletim sarılalım...', ARRAY['Türk Edebiyatı','Şiir','Şair Erdinc67']::text[], 8.5, '{"poet":"Şair Erdinc67","poet_slug":"sair-erdinc67","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/80-yilimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atam Yolundayız', 'atam-yolundayiz-sair-erdinc67-z0xw8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'türkü türk yapan atam yolundayız

vatanıma göz dikenin kanındayız

milletimle askerimle yanındayız

vatanım bayrağım sana canım feda

barış timsali türk milleti

gurur duyun atatürk gençliği

vatanıma bayrağıma kanım feda

atamın  yoluna canım feda

askerim sensin türkü yücelten

sensin barış yolunu gösteren

varmı dünyada barış askeri

askerimdir dünyada barışın lideri

kurtuluş savaşından ak çıktık

vatanıma göz dikenlerle savaştık

bayrağım uğruna kanımı verdim

atam yoluna canımı verdim', 'türkü türk yapan atam yolundayız vatanıma göz dikenin kanındayız milletimle askerimle yanındayız vatanım bayrağım sana canım feda barış tims...', ARRAY['Türk Edebiyatı','Şiir','Şair Erdinc67']::text[], 8.5, '{"poet":"Şair Erdinc67","poet_slug":"sair-erdinc67","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/atam-yolundayiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atamdan Sevgi', 'atamdan-sevgi-sair-erdinc67-yiv1a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İstanbul’dan gizli geçtim samsuna

Dokunamazlar benim dostuma

Vatanımı-milletimi bırakmam düşmana

Savaşalım milletime kan kusturana

Samsundan destek aldım hak yoluna

Türk türk oldu atanın bir buyruğuna

Nice kanlar akıttılar vatan uğruna

Milletçe sarıldık yurduma-bayrağıma

80 yıl geçti unutmadınız yücelttiniz beni

her meslekten yetiştirdiniz kendinizi

korudunuz-savundunuz milletinizi

anıtkabirde bekliyorum selamlıyorum hepinizi.', 'İstanbul’dan gizli geçtim samsuna Dokunamazlar benim dostuma Vatanımı-milletimi bırakmam düşmana Savaşalım milletime kan kusturana Samsundan...', ARRAY['Türk Edebiyatı','Şiir','Şair Erdinc67']::text[], 8.5, '{"poet":"Şair Erdinc67","poet_slug":"sair-erdinc67","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/atamdan-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devre96', 'devre96-sair-erdinc67-bq7ru', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Devre96 çıktı okuldan kışlaya

Meydan okudu her safta düşmana

Vatan-bayrak-millet aşkına

Verdi en güzellerinden beş asker Allah aşkına

Gelmez İbrahim ÖZTÜRK şehidim geri

Dolmaz derler şehitlerin yeri

Yetişmezki Fatih ONGÜN gibileri

Dolmaz derler şehitlerin yeri

Engin, yavuz, barış neredesin

Ülkemin en güzel yerindesin

Aşkınızla yanıyor en derin yerim

Saygı duyuyoruz size güzel şehitlerim.', 'Devre96 çıktı okuldan kışlaya Meydan okudu her safta düşmana Vatan-bayrak-millet aşkına Verdi en güzellerinden beş asker Allah aşkına Gelmez...', ARRAY['Türk Edebiyatı','Şiir','Şair Erdinc67']::text[], 8.5, '{"poet":"Şair Erdinc67","poet_slug":"sair-erdinc67","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/devre96-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hava Harp Okulu I', 'hava-harp-okulu-i-sair-erdinc67-ba068', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'harbiyede savaş var uğruna

vatanımın taşına toprağına

bayrağım sana kanım feda

hoş geldiniz hava harp okuluna

yerde gökte askerim 

ben ülkemi daima beklerim

ey gençlik senide beklerim

hoş geldiniz hava harp okuluna

ben bir askerim

atam yolunu beklerim

yeşilyurtda emeklerim

hoş geldiniz hava harp okuluna

sancağımı gençlere verdim

kışlama kendimi koy verdim

vatanıma bayrağıma and verdim

hoş geldiniz hava harp okuluna', 'harbiyede savaş var uğruna vatanımın taşına toprağına bayrağım sana kanım feda hoş geldiniz hava harp okuluna yerde gökte askerim  ben ülkem...', ARRAY['Türk Edebiyatı','Şiir','Şair Erdinc67']::text[], 8.5, '{"poet":"Şair Erdinc67","poet_slug":"sair-erdinc67","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hava-harp-okulu-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hava Harp Okulu II', 'hava-harp-okulu-ii-sair-erdinc67-vsb2i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'harbiyeyede öğrenciyiz

atamın izindeyiz

hava harp okulu servetiyiz

bizler türk gençliğiyiz

dostuma güven verdim

düşmana korku saldım

hava harp okulu servetiyiz

bizler türk gençliğiyiz

vatanım için asker oldum

uğruna canımı koydum

taşına toprağına kurban olduğum

bizler türk gençliğiyiz

barışta savaşta varım

atatürktür eş anlamım

tarihte ben varım

bizler türk gençliğiyiz

geçmişte gelecekte göklerde

türk askeri her yerde

barışta savaşta her yerde

bizler türk gençliğiyiz', 'harbiyeyede öğrenciyiz atamın izindeyiz hava harp okulu servetiyiz bizler türk gençliğiyiz dostuma güven verdim düşmana korku saldım hava ha...', ARRAY['Türk Edebiyatı','Şiir','Şair Erdinc67']::text[], 8.5, '{"poet":"Şair Erdinc67","poet_slug":"sair-erdinc67","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hava-harp-okulu-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Servetim Bayrağım', 'servetim-bayragim-sair-erdinc67-rznc7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'benim servetim vatanım

yoktur başka bayrağım

türk oğlu türktür adım

ne mutlu türküm diyene

nice canlar verdim taşına

nice savaşlar yaptım uğruna

milletim unutma geçmişi unutma

ne mutlu türküm diyene

dostlarımız düşman oldu

düşman askeri milletimi yasa boğdu

bir güneş selanikten doğdu

ne mutlu türküm diyene

askerimdir bana güven veren

türkü türk diye yücelten

sabahı akşamı bekleyen

ne mutlu türküm diyene', 'benim servetim vatanım yoktur başka bayrağım türk oğlu türktür adım ne mutlu türküm diyene nice canlar verdim taşına nice savaşlar yaptım uğ...', ARRAY['Türk Edebiyatı','Şiir','Şair Erdinc67']::text[], 8.5, '{"poet":"Şair Erdinc67","poet_slug":"sair-erdinc67","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/servetim-bayragim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asker Ocağı', 'asker-ocagi-sair-erdinc67-dmrot', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'atatürktür adım

türktür soy ağacım

milletimdir toprağım

vatanıma bayrağıma and içerim

gökte yerde ben varım

türk oğlu türktür kanım

ben türk askeriyim

vatanıma bayrağıma and içerim

kanımla yıkandı bayrağım

bedenimle oluştu toprağım

nasıl vermem canımı

vatanıma bayrağıma and içerim

şevkat var bu ocakta

merhamet var her safta

asker oldum uğruna

vatanıma bayrağıma and içerim.', 'atatürktür adım türktür soy ağacım milletimdir toprağım vatanıma bayrağıma and içerim gökte yerde ben varım türk oğlu türktür kanım ben türk...', ARRAY['Türk Edebiyatı','Şiir','Şair Erdinc67']::text[], 8.5, '{"poet":"Şair Erdinc67","poet_slug":"sair-erdinc67","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/asker-ocagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatanım', 'vatanim-sair-erdinc67-5t5d8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ruhum milletim

bedemim vatanım

elbisem bayrağım

nasıl ben bu servete kıyarım

atatürk komutanım

şehittir ecdadım

göz dikeni yakarım

nasıl bu servete kıyarım

güneş gibisin vatanım

deniz gibisin bayrağım

seni kıskanırım

nasıl bu servete kıyarım

derdim sevincim sensin

dünyada servetsin

göz dikeni yakarım

nasıl bu servete kıyarım.', 'ruhum milletim bedemim vatanım elbisem bayrağım nasıl ben bu servete kıyarım atatürk komutanım şehittir ecdadım göz dikeni yakarım nasıl bu ...', ARRAY['Türk Edebiyatı','Şiir','Şair Erdinc67']::text[], 8.5, '{"poet":"Şair Erdinc67","poet_slug":"sair-erdinc67","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/vatanim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalım', 'sevdalim-sair-erdinc67-scn1l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Derdim dermanım kaderimsin

Gönlümde kalbimde servetimsin

Sevdan ile yanan yüreğim

Seni arar sevdalım seni arar

Sormadım soramadım kimselere seni

Gönlüme yüreğime gömdüm seni

Ne arar ne sorarsın şu garibi

Yaşamadım yaşatamadım ben seni

Her gün ama her gün anarım seni

Bir gün tek bir gün görebilsem güzelim seni

Nasıl severdim bilemezsin bilemezsin seni

Ne olur göster bir defa göster güzel yüzünü

Gençliğim geldi gidiyor ararım seni

40ımdan sonra çıkma karşıma kırarım seni

gençliğimi heba ettim aramakla seni

ne olur ne olur gel artık güzelim.', 'Derdim dermanım kaderimsin Gönlümde kalbimde servetimsin Sevdan ile yanan yüreğim Seni arar sevdalım seni arar Sormadım soramadım kimselere ...', ARRAY['Türk Edebiyatı','Şiir','Şair Erdinc67']::text[], 8.5, '{"poet":"Şair Erdinc67","poet_slug":"sair-erdinc67","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdalim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İt İti Isırmaz...', 'i-t-i-ti-isirmaz-suleyman-saylan-wslrj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İT  İTİ  ISIRMAZ...

Ne günlere kaldık Allah''ım! 

Kim bilir

Hangi umutlarla hamile kalmıştı

Gariban anamız? ! 

Dünyaya

Ne beklentilerle doğurmuştu bizi...

Gördüğü, 

Bildiği tüm erdemlerle donatarak eğitimiş, 

Vatana, millete 

Hayırlı bir evlat yetiştirmenin aşkıyla

Harcamıştı yoğunu, varını, 

Dişine takarak canını...

Oysa biz; 

Yitire yitire

İşte bu erdemleri

Nerelere geldik...

Kazancımız olmadı hiç, 

Hep verdik.

Aç kurtlardan daha aç

İt sürüleri içinde kaldık; 

Ne hak tanıdılar, ne hukuk, 

Allah korkusunu da unuttular.

Doymadı aç itler, 

Nankördü açgözlüler.

Hani; 

''İt iti ısırmaz''dı? ! 

O da yalan çıktı.

Şimdi

İt bile ısırıyor iti...

Süleyman SAYLAN

(Ankara,23.01.2002, Saat: 23.55)', 'İT  İTİ  ISIRMAZ... Ne günlere kaldık Allah''ım!  Kim bilir Hangi umutlarla hamile kalmıştı Gariban anamız? !  Dünyaya Ne beklentilerle doğur...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/it-iti-isirmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asma ve Hece', 'asma-ve-hece-kader-sevinc-hkirn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I



     - Nerede? 

       Uçurumlarımın sesine döküldüğü yerde.

       Eskimiş, terkedilmiş.







 II  

        Hece hece tükürürler bizi

        Çorak vadiye…



       Yağmurlar mektuplarla yoklar ara sokakları, 

       martılar yankılarla

       tutuştururken  sözcüklerle 

       ıslak mendilini

       günsüz penceremde Van Gogh sarıları





 III





       Zaman yok, kumlar azaldı.

       Yapraklanıyor yüzüm, 

       dilsiz ve sağır bir merhaba uzuyor.

       Asmalar üzgün bugün.





  IV





      Unutmadım.

    - Neyi? 



      Uçurumlarımın sesine döküldüğü yerde, 

      ayışığının çisil çisil yağdığını, 

      papatyalar eskidikçe.', 'I      - Nerede?         Uçurumlarımın sesine döküldüğü yerde.        Eskimiş, terkedilmiş.  II           Hece hece tükürürler bizi         ...', ARRAY['Türk Edebiyatı','Şiir','Kader Sevinç']::text[], 8.5, '{"poet":"Kader Sevinç","poet_slug":"kader-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/asma-ve-hece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bari Mutlu Ol...', 'sen-bari-mutlu-ol-suleyman-saylan-t3k4p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SEN  BARİ  MUTLU  OL...

Anlatamam; 

Gücü tükendi sözcüklerin, 

Sürüngenden beter oldu, 

Sustu kalemim.

Duyguları çekildi, 

Külçe gibi bedenim, 

Ölümcül hasta...

Sanki, 

Dünya çöktü üstüme; 

Sensizlik dünyası...

Sensiz boğuluyorum.

Ölü müyüm, sağ mıyım belli değil.

Yüreğimi ayrık otu gibi saran

Duygular avare

Ve sefil.

Sensizlik, 

Umutlarımı yiyen obur bir fil

Sanki...

Hava tükendi, 

Şimdi ben zehir soluyorum, 

Can veriyorum.

İçimdeki ateşine yağan kar

Bıkmadı inadından; 

Buz dağlarının altında kaldım.

Buzların bile söndüremediği

Ateşinin acısıyla

Yaşaya yaşaya

Ölüyorum...

Sen bari mutlu ol.

Süleyman SAYLAN

(Ankara,20.01.1988, Saat: 00.15)', 'SEN  BARİ  MUTLU  OL... Anlatamam;  Gücü tükendi sözcüklerin,  Sürüngenden beter oldu,  Sustu kalemim. Duyguları çekildi,  Külçe gibi bedeni...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sen-bari-mutlu-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Gölüm', 'ben-bir-golum-bekir-gedikoglu-57u9a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dağlar arasında her yağmurda dolan

Yazları susuz kalan

Unutulmuş şiir suları

Zemzem suları ile 

Dolu, dopdolu olarak

Sense beni arayan

Şiirlerine konu olarak

Kalbine ise yerleşmiş

En büyük sevgilin olarak

Karşına bir gün

Çıkacağım bana inan

Sen beni göreceksin

Taa,  o yüksek tepelerin birinden

Yolunun tam ortasında

İçime girdiğinde

İçin heyecan ile dolacak

Heyecan, umut, ürperme, bekleyiş, arzu...

Hepsi sana birer, birer sahip olacak

	Sen sessiz, sessiz olacaksın

	Belki de hatunlardan hatun

	Belki de Jan Dark

Belki de Nene Hatun

Belki de en lal

Belki dee en mecalsiz

Olarak kalacaksın bir an

Işıl, ışıl gözlerine, pırıl, pırıl yakamozlarımın

Verdiği milyonlarca parıltı ile bakacağım sana

Yavaş,  yavaş 

Beni çevreleyen otlara, sana uzanan orman güllerine

Seni ürperten seslere tutuna tutuna ineceksin

Taa sana parıldayan, kucak açan maviliğime kadar ineceksin 

İNAN

Bahane olacak bastığın yosunlar ve taşlar

Düşeceksin o maviliğin sonsuz derinliğine kadar

Yıl olan zamanlar, bir dem gibi geçiverecek üstünden

Feryatlarına, imdatlarına, neşelerine, acılarına

Yine ben çare olmayacak mıyım? 

O mavi derinlikler sana

Cıbıl, cıbıl bir aşk, sonsuz bir sevgi, çiçek bir dünya verecek inan

Senin yerin burası. İşte bu göl

..........

Bu göl

Ankara,11.06.1974', 'Dağlar arasında her yağmurda dolan Yazları susuz kalan Unutulmuş şiir suları Zemzem suları ile  Dolu, dopdolu olarak Sense beni arayan Şiirl...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/ben-bir-golum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tirebolu ve Sevgilim', 'tirebolu-ve-sevgilim-bekir-gedikoglu-tb6i8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tirebolu’ nun dağlarına 

Kar yağıyor, yağıyor

İnsan sevdiklerini 

Gece gündüz arıyor

Tirebolu dağlarında

Keklik avlarım keklik

Gördünüz mü yarimi? 

Onda var pek güzellik

Tirebolu dağlarında 

Ava çıkarım ava

Yarimi sorarsanız? 

Tadı benziyor bala

Tirebolu’nun merkezinde 

Bak yarim oturuyor

Çok uzaklarda da olsam

Hal-hatırım soruyor

Tirebolu dedikleri

Hamsidir yedikleri

Öldürüyor ah beni

Yarimin dedikleri

Tirebolu,27.01.1985', 'Tirebolu’ nun dağlarına  Kar yağıyor, yağıyor İnsan sevdiklerini  Gece gündüz arıyor Tirebolu dağlarında Keklik avlarım keklik Gördünüz mü y...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tirebolu-ve-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah Olursa...', 'sabah-olursa-suleyman-saylan-l21cp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SABAH  OLURSA...

Baykuş sesidir sanma

Geceyi yırtan, 

Kör karanlıklara kafa tutan

Hasretimin çığlığıdır...

Yalnızlığımın siren sesleri

Gözleri tırmalar, 

Sabaha kadar.

Yüreğimin fırtınaları

Öldürücü dalgalar koparır

Sevda denizinde.

Sevgiyi oyuncak sanan gemiler

Batarlar birer birer.

Yıkılır

Kumsaldaki kumdan evler, 

Kırılır

Sevgiyle kurulmuş sırça saraylar...

Yüreğim isyan eder

Susadığı sevgilerin güçsüzlüğüne, 

Acizliğine, 

Umduğu sevgilerin hiçliğine.

Ey

Dünyanın sevgilerini sunduğum

Biriciğim, 

Yangınlarımda boy veren, 

Sevda kokan nar çiçeğim.

Yalnızlıklarımın perisi, 

Prensesim.

Az kaldı sabaha, 

Gece can çekişiyor...

Sabah olursa, 

İstemem seni.

Süleyman SAYLAN

(İstanbul-Ankara yataklı treni,25.11.2001, Saat: 02.22)', 'SABAH  OLURSA... Baykuş sesidir sanma Geceyi yırtan,  Kör karanlıklara kafa tutan Hasretimin çığlığıdır... Yalnızlığımın siren sesleri Gözle...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sabah-olursa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili', 'sevgili-filiz-kurun-akm4d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayata sevgiyle başladım

Sevgiyi  toz duman ettiler

Bir sevdam olsun dedim

Sevdamı benden ettiler

Gözlerim gece gündüz arar seni

Nerdedir bilinmez

Giden

Gidipte dönmeyen sevgili.', 'Hayata sevgiyle başladım Sevgiyi  toz duman ettiler Bir sevdam olsun dedim Sevdamı benden ettiler Gözlerim gece gündüz arar seni Nerdedir bi...', ARRAY['Türk Edebiyatı','Şiir','Filiz Kurun']::text[], 8.5, '{"poet":"Filiz Kurun","poet_slug":"filiz-kurun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgili-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldız Düşmüştü Denize', 'yildiz-dusmustu-denize-murat-tali-d3n2w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'süreyyalar sarmıştı 

denizleri, 

semalara öykünmüştü okyanuslar 

süreyyalara bürünerek 

laciverte dönmüştü gece 

ama hüzün kokmuyordu saatler, 

Ay 

med cezirlerle alıp götürürken suları 

okyanuslar halen kendini 

sema sanıyordu 

büründüğü süreyyalarla

gündüz oldu 

okyanuslar halen kendini 

sema sanmaya devam ettiler

güneşi 

içine alarak', 'süreyyalar sarmıştı  denizleri,  semalara öykünmüştü okyanuslar  süreyyalara bürünerek  laciverte dönmüştü gece  ama hüzün kokmuyordu saatle...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yildiz-dusmustu-denize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neye Yarar ki? ...', 'neye-yarar-ki-suleyman-saylan-uscdn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'NEYE  YARAR  Kİ? ...

Çok dağıldım son günlerde; 

Göre göre, 

Duya duya insansızlıkları

Yaralar açıldı yüreğimde.

Dağıttığım sevgi kırıntılarını toplasalardı, 

Deprem olurdu evrende, 

Sevgilerimin şiddetinden...

Ama gel gör ki; 

Sevgi görmedim karşılığında

Tanrı''nın aciz kullarından.

Öğrenmemişlerdi sevgiyi, 

Kırıntısı yoktu yüreklerinde.

Yaşamları nakitti, 

Girememişlerdi duygu evrenine.

Sorarsanız; 

''İyi yaşıyoruz, mutluyuz'' derler, 

Yalan söylerler

Yalan.

Duygusuz yaşam

Yaşam olamaz ki.

Ürün vermeyen toprak, 

Meyve vermeyen ağaç, 

Çocuksuz kadın

Kısırdır, çoraktır, 

Neye yarar ki? ...

Bu dünyaya bir daha gelirsem, 

Namerdim, 

Dünya sizin olsun.

Süleyman SAYLAN

(Ankara-İstanbul yataklı tren restoranı-Eskişehir,17.11.2001, Saat: 23.35)', 'NEYE  YARAR  Kİ? ... Çok dağıldım son günlerde;  Göre göre,  Duya duya insansızlıkları Yaralar açıldı yüreğimde. Dağıttığım sevgi kırıntılar...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/neye-yarar-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçurumlar Ülkesine Bir İlticacıdır Çünkü Aşk', 'ucurumlar-ulkesine-bir-i-lticacidir-cunku-ask-fatih-pasali-4jzgf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-debisi yüksek bir akarsuda yazılmalı şiir 

ve bir koyak bulunmalı şairin akışkan gözlerine-

haydi bir uçurum yarat kendine

ateşte sına beynini

yanan bir kalkan gibi olsun ayrılık

örs dövelim tenimizde

haydi eylem yarat 

terket beni, sonra kendini

sonra belki tüm kıyılarını

gölgeni bile kendine yalancı ve yabancı say

beni de koy aralarına / yabancılaştır

utanan taraflarını paylaş benimle / utanıp susayım

sustur beni

ya da 

fitili ateşlenmiş bir dinamit koy aramıza

zamanı eskitelim

Kül kırıkları serp üstüme

ateşin torunlarını tadayım

sonra yine terket beni

zindan et mülteci yalnızlıklara

aşk ile yoğrulan yanlarımı sına

afaroz et beni

ama sana olan dindarlığımdır bu

yaşamak istediğin neresi varsa oraya koy beni

bir deniz, bir dağ, bir koyak olabilir bu

sonra bırak

kendi dentiritlerimde kaybolayım

ıslanmak istemeyen bir akarsu sevinci benimkisi

yetişmeye çalıştığın geç kalınmışlıkları sırala bana

beyinlerdeki uyuşukluğu

tütün ve alkol kokularıyla gel

varolduğunu anlayayım

sonra git

rüzgarın ateşi söndüremeyişi bu

ayraçlardan arın

beni sına

kredi limitimi araştır

başkalarını koy yanıma

gözlerimi al eskit / ya da tenimi ödünç ver bana

bir deniz mayını kadar serseri ve ıslak ol

önemsemediğim değil doğru olan

aramayışlarındaki hesapsızlığım

rüzgarlarla dostluğumdandır

(şimdi)   izin ver  kaybolayım

uçurumlar ülkesine bir ilticacıdır çünkü aşk

ve sadece

şovalye ruhlu dostum anlar beni.', '-debisi yüksek bir akarsuda yazılmalı şiir  ve bir koyak bulunmalı şairin akışkan gözlerine- haydi bir uçurum yarat kendine ateşte sına beyn...', ARRAY['Türk Edebiyatı','Şiir','Fatih Paşalı']::text[], 8.5, '{"poet":"Fatih Paşalı","poet_slug":"fatih-pasali","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/ucurumlar-ulkesine-bir-ilticacidir-cunku-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik Yağmursuzlukla Eşdeğer', 'sensizlik-yagmursuzlukla-esdeger-fatih-pasali-ftg7h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şimdi tenin kokuyor gece

bi''ağaç kumunu yadırgıyor

kuruluğun hüznü bu

sensizliğin, 

yağmursuzluğun hüznü

sensizlik yağmursuzlukla eşdeğer

çok çalışılmış bir ders kitabının

son hecesinde yakalıyorum seni

umut kuşanmış gelecek günler için; 

kitabı ele veren bir şifre gibisin

sen

yarı açık yalnızlıkların

görüş günlerinde bulduğumsun; 

mahkumun demir parmaklıkla / 

arasındaki yakınlık

bir de

aşk; eğer bir cellatsa

ve altımdaki sehpaysa tek derdi

onu beklemeden kendim atlıyorum

yeter ki darağacına borcum kalmasın

Varsın kaygılı dalgalara

liman olsun esrik duruşum

hayatı duru deminde yaşayamamam

iveceliğimdendir

bunu da düşerim

aykırılıkların güncesine

acemi bir bahçevanın

makasıyla değiştiriyorum şimdi dilimi

yüzümü ödünç veriyorum sevgiliye

bedenim köksüz ve kaygılı

ormanda kesilen ilk ağacım

vakitsiz öten horoz yani

gecenin içinde asimine oluyorum

kendi kalabalığımla

yokluğun kuraklığın diğer adı (!) 

beklentilerim çöl kadar büyük ve yalnız

bırak kurağımda açayım

yaşamımdaki en büyük özlem olarak kal

ki; 

ağrı ve aşk unutulmasın

her gece derin bir boşluk 

açmazda kundaklıyor özlemi

kuraklık / kuraklık / kuraklık

arkasından yine

yağmursuzluğun hüznü

diyorum ya; 

sensizlik yağmursuzlukla eşdeğer (!) 

ve ben

sensiz yanlarıma 

şiir sürüyorum şimdi (!) 

        ıslak duvardan kayan

        bir kertenkele ürkekliğiyle baş başayım.', 'şimdi tenin kokuyor gece bi''ağaç kumunu yadırgıyor kuruluğun hüznü bu sensizliğin,  yağmursuzluğun hüznü sensizlik yağmursuzlukla eşdeğer ço...', ARRAY['Türk Edebiyatı','Şiir','Fatih Paşalı']::text[], 8.5, '{"poet":"Fatih Paşalı","poet_slug":"fatih-pasali","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/sensizlik-yagmursuzlukla-esdeger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamak', 'aglamak-filiz-kurun-fl411', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağlamak neyi çözmüş ki

Bu fani dünyada

Seni geri getirsin

Gözlerimden süzülen yaşların 

Seni geri  getireceğini bilseydim

Daha çok ağlardım

Ne arkandan gelebildim

Ne de ağlayabildim

Ağlasaydım seni geri getirebilirmiydim? 

(13.06.01)', 'Ağlamak neyi çözmüş ki Bu fani dünyada Seni geri getirsin Gözlerimden süzülen yaşların  Seni geri  getireceğini bilseydim Daha çok ağlardım ...', ARRAY['Türk Edebiyatı','Şiir','Filiz Kurun']::text[], 8.5, '{"poet":"Filiz Kurun","poet_slug":"filiz-kurun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aglamak-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim Kendini Saklama', 'sevgilim-kendini-saklama-gokhan-uckaya-ydx12', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-Filiz''e

öpüşlerimin izini silmene gerek yok tebessümünden

yanakların daha kırmızı aşka düşeli, 

 bırak gerek yok saklama kendini.

bırak taşırsın kalbin tutku kıvılcımları

taşsın yanaklarından  sevincin tohumları

taşsın güpegündüz şehrin ortasına

oğul verir elden ele aşk bile

sevgilim  kendini saklama

koyver gitsin en uzağa ittiğin dileği

koyver akan bir yıldıza çığlık çığlığa

yüzüm geceye çizilsin tırnaklarınla

seviliyorsun çünkü kendini saklama

en sevdiğim yerine yazdım kendimi

en aymaz bencilliğimle sardım tenini

dudaklarının yanağını kestiği o mercan köşede

tomurcukların toprağa çatlayana dek beklemeli, 

seviliyorsun çünkü delicesine

koyver gitsin gökkuşağına sarılı kalbinin

yangınlar kaçağı o en kırmızı kurdelesini

açılsın bir bir ten üstüne aşkın bukleleri 

seviliyorsun çünkü saklama kendini

bir sedef hat gibi taşı yüzünde aşkı

en güneşli tenhalarda sevdiğini arzula

ve çiçek tenine yakıştığı gibi

                                 savur hayatın hayhuyuna

                                 sevgilim kendini saklama

(kızılay, Mart 2003)', '-Filiz''e öpüşlerimin izini silmene gerek yok tebessümünden yanakların daha kırmızı aşka düşeli,   bırak gerek yok saklama kendini. bırak taş...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Üçkaya']::text[], 8.5, '{"poet":"Gökhan Üçkaya","poet_slug":"gokhan-uckaya","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sevgilim-kendini-saklama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelsen', 'gelsen-filiz-kurun-jef7x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kopup gelsen

Sonbahar rüzgarlarının

Kuru yaprakları  savurduğu gibi

Sen de  gelsen

öyle usul usul

öyle çaresiz

sen gelsen

bana doğru kuru yapraklar gibi

gelsen

öylece bana huzur versen

sen öyle bir gelsen ki

seni bende

seni benle

bütünlesen.

08.01.2003', 'Kopup gelsen Sonbahar rüzgarlarının Kuru yaprakları  savurduğu gibi Sen de  gelsen öyle usul usul öyle çaresiz sen gelsen bana doğru kuru ya...', ARRAY['Türk Edebiyatı','Şiir','Filiz Kurun']::text[], 8.5, '{"poet":"Filiz Kurun","poet_slug":"filiz-kurun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gelsen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylemedin Deme Sakın,', 'soylemedin-deme-sakin-mine-ozdemirtas-0iy36', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben Gittiğimde; Sen,  ıssız sokaklarda yürüyor olacaksın / yapayalnız.

Islak bir Kara Kedi çıkacak önüne./ Duraklayacaksın.

Gözlerinin içine bakacak uzun uzun. Buz kesecek yüreğin.

Ve ; o andan sonra bir daha / asla,  /aynı adam olamayacaksın.

Sen henüz bilmiyorsun ama; Ben Gittiğimde Bir şeyler eksilecek sende.

Biraz yaşamaktan yana aşkı, /çokça da yaşayamamış olmaktan yana.

Ben gittiğimde / gittiğim günde kalır gidişim ve silinirim sanma.

Kapkaranlık bir gölge gibi; üstüne düşeceğini biliyorsun yokluğumun

Henüz farkında değilsin ama; Gidiş o gidiş ki / uzaklığı bencilliğinin

Çok yakın. Çok yakın seyrediyor. Dibi görünmeyen sonsuz uçurumlara.

Kaldırımlar gibi uzayıp gitse de önünde; isimleri /ya da yüzleri

Kullanıp bir kenara attığın kadınların hiç biri / ama hiç biri

Benden başka. Hiç kimse / parmak damgası vurmayacak yarınlara.

Onlar Sarışın ve ya esmer di  önemsemedin. Kimi uzundu  kimi de kısa.

Kimi bir nefes oldu sadece.. kimi ise sadece basıt bir mola.

Omuz silkip geçtiğin bu orduya; adsız bir nefer de ben olurum sanma.

Ben gittiğimde; söküp alacağım yüreğini asılı durduğu yerden. / Bunu bil. 

Ardımdan ve her gece, kanatacaksın kara Kedili  kabusları beni hatırladıkça.

Ben gittiğim gün. Bir daha hiç /ama hiç olmayacağım  parsellenmiş yaşamında.

Şimdiden yok say beni /. Say ki; zaten hiç olmadım.  /Ben hiç olmadım ama; 

Yine de ben gittiğimde; Yağmur yağacak yollarına / hiç durmamacasına.

Zaten uzun süredir yağıyor;  / ama; sen körsün  /o yüzden görmüyorsun. 

Sadece; gözlerin nemleniyor sanıyorsun / şöyle bir duraklıyorsun ara sıra.

Hele dur / çok, ama çok ıslanacaksın bensiz / daha kirpiklerin buzlanmadı henüz

Ben gittiğimde; kuruyacak ya  yavaşça sevda /çölleşme başlayacak ya kıraç toprağında

İşte; tam o zaman /  durduracağım yağmurlarımı aniden/iyice ısınacak hava.

Benim yağmurlarımla yıkanıp arınacağını / sonra yavaşça yeniden yeşereceğini

Ve hele ki   / bensiz bir dünyada / nefes alabileceğini/Hiç; ama  hiç sanma..', 'Ben Gittiğimde; Sen,  ıssız sokaklarda yürüyor olacaksın / yapayalnız. Islak bir Kara Kedi çıkacak önüne./ Duraklayacaksın. Gözlerinin içine...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/soylemedin-deme-sakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonunda Ayrılık Olmasaydı', 'sonunda-ayrilik-olmasaydi-halil-kesken-myy57', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen hakimmisin ki hüküm veriyorsun bittiğine

Böylesine sebepsiz, böylesine gereksiz olmasaydı

Inan ki hiç yanmazdım gittiğine

Sevdanın çiçekleri kuruduysa

Sulasaydık, solmasaydı

Ne engeller atlattık, ne zorluklar yaşadık birlikte

Keşke, keşke birtanem

Sonunda ayrılık olmasaydı

Kaç defa kavgalar ettik kaç defa

Ama birbirimize saygımızı kaybetmemiştik

Ve hiç kimseyi böylesine sevmemiştik.

Neler yaşadık bu üç yıl içinde

Hiç birşeyin aramıza girmesine izin vermemiştik

Sonunda hüzün, sonunda keder, 

Sonunda ölüm olsaydı da

Keşke, keşke birtanem

Ayrılık olmasaydı

Açık bir kapı bile bırakmadın bu kez

Demekki sözlerimiz tutulmamaya

Aşkımız unutulmaya mahkummuş

Demekki benim zavallı yüreğim; 

Bir ömürlük sevdayı boşuna ummuş

Demekki bütün bunlar

Sence birer oyunmuş

Sobe diyip gitseydin, bir ömür uyutsaydın beni böyle

Gözlerim kör olana dek seni arasaydı

Keşke, keşke birtanem

Sonunda ayrılık olmasaydı…', 'Sen hakimmisin ki hüküm veriyorsun bittiğine Böylesine sebepsiz, böylesine gereksiz olmasaydı Inan ki hiç yanmazdım gittiğine Sevdanın çiçek...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sonunda-ayrilik-olmasaydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmak ya da Olmamak, İşte Bütün Mesele Bu!', 'olmak-ya-da-olmamak-i-ste-butun-mesele-bu-william-shakespeare-lr59e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Olmak ya da olmamak, işte bütün mesele bu! 

Düşüncemizin katlanması mı güzel,

Zalim kaderin yumruklarına, oklarına

Yoksa diretip bela denizlerine karşı

Dur, yeter! Demesi mi? 

Ölmek, uyumak sadece! Düşünün ki uyumakla yalnız

Bitebilir bütün acıları yüreğin,

Çektiği bütün kahırlar insanoğlunun.

Uyumak, ama düş görebilirsin uykuda, o kötü! 

Çünkü ölüm uykularında,

Sıyrıldığımız zaman yaşamak kaygısından,

Ne düşler görebilir insan, düşünmeli bunu.

Bu düşüncedir uzun yaşamayı cehennem eden.

Kim dayanabilir zamanın kırbacına? 

Zorbanın kahrına, gururunun çiğnenmesine,

Sevgisinin kepaze edilmesine

Kanunların bu kadar yavaş

Yüzsüzlüğün bu kadar çabuk yürümesine

Kötülere kul olmasına iyi insanın

Bir bıçak saplayıp göğsüne kurtulmak varken? 

Kim ister bütün bunlara katlanmak

Ağır bir hayatın altında inleyip terlemek

Ölümden sonraki bir şeyden korkmasa,

O kimsenin gidip de dönmediği bilinmez dünya

Ürkütmese yüreğini? 

Bilmediğimiz belalara atılmaktansa

Çektiklerine razı etmese insanı? 

Bilinç böyle korkak ediyor hepimizi:

Düşüncenin soluk ışığı bulandırıyor

Yürekten gelenin doğal rengini.

Ve nice büyük, yiğitçe atılışlar

Yollarını değiştirip bu yüzden.

Bir iş, bir eylem olma gücünü yitiriyorlar.', 'Olmak ya da olmamak, işte bütün mesele bu!  Düşüncemizin katlanması mı güzel, Zalim kaderin yumruklarına, oklarına Yoksa diretip bela denizl...', ARRAY['Türk Edebiyatı','Şiir','William Shakespeare']::text[], 8.5, '{"poet":"William Shakespeare","poet_slug":"william-shakespeare","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/olmak-ya-da-olmamak-iste-butun-mesele-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgisinin Kepaze Edilmesine', 'sevgisinin-kepaze-edilmesine-william-shakespeare-j05wt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgisinin kepaze edilmesine, 

Kanunların bu kadar çabuk yürümesine, 

Kötülere kul olmasına iyi insanın 

Bir bıçak saplayıp göğsüne kurtulmak varken? 

Kim ister bütün bunlara katlanmak 

Ağır bir hayatın altında inleyip terlemek, 

Ölümden sonraki bir şeyden korkmasa, 

O kimsenin gidip de dönmediği bilinmez dünya 

Ürkütmese yüreğini? 

Bilmediğimiz belâlara atılmaktansa 

Çektiklerine razı etmese insanı? 

Bilinç böyle korkak ediyor hepimizi: 

Düşüncenin soluk ışığı bulandırıyor 

Yürekten gelenin doğal rengini. 

Ve nice büyük, yiğitçe atılışlar 

Yollarını değiştirip bu yüzden, 

Bir iş, bir eylem olma gücünü yitiriyorlar. 

Ama sus, bak güzel Ophelia geliyor. 

Peri kızı dualarında unutma beni, 

Ve bütün günahlarımı', 'Sevgisinin kepaze edilmesine,  Kanunların bu kadar çabuk yürümesine,  Kötülere kul olmasına iyi insanın  Bir bıçak saplayıp göğsüne kurtulma...', ARRAY['Türk Edebiyatı','Şiir','William Shakespeare']::text[], 8.5, '{"poet":"William Shakespeare","poet_slug":"william-shakespeare","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevgisinin-kepaze-edilmesine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işık Oyunu', 'isik-oyunu-hanife-efendioglu-x5xm7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gece ışıklarla oynadım, 

Gözlerimi kapadım, hayal ettim, 

Bir parfüm şişesinden çıkan, 

Işıkları izledim.

Yıldızların göz kırpışlarını, 

Ayın ağlamasını seyrettim.

Bir martı gözyaşlarımın arasından geçti, 

Kahkahalarla, 

Kanadının ucundaki kanı izledim.

İçinde parlayan gökkuşağını

Yedi rengini, yedi pırıltısını

İzledim.

Kan damladı, 

Yüzüme düştü.

Gözyaşımla karıştı, 

Gömleğim kana bulaştı.

Kurşun yarası mıydı, aşk yarası mı

Hangisi daha fazla kanatır, 

Bir martının beyaz kanadını? 

Güzüme tüy kaçtı, çıkaramadım.', 'Bu gece ışıklarla oynadım,  Gözlerimi kapadım, hayal ettim,  Bir parfüm şişesinden çıkan,  Işıkları izledim. Yıldızların göz kırpışlarını,  ...', ARRAY['Türk Edebiyatı','Şiir','Hanife Efendioğlu']::text[], 8.5, '{"poet":"Hanife Efendioğlu","poet_slug":"hanife-efendioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/isik-oyunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üsküdar Kıyısında Görüşmek Üzere', 'uskudar-kiyisinda-gorusmek-uzere-hatem-gokcek-0xfgj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İstanbul üstüme yıkıldı bu gece, 

Taş taş, duvar duvar, sokak sokak, 

Mahalle mahalle İstanbul üstüme yıkıldı bu gece

Hangi denize atsam kendimi şimdi

Hangi kuleye assam sensiz bedenimi

Biliyordum....

Sussanda konuşmasanda 

Bakmasanda yanımdaydın eftelya gözlüm

Bir çiçek nasıl solarsa işte öyle solucam

İstanbul un bir kıyısında

Tutmayacagım verdiğim sözleri

Ağlamıcam demiştim, ağlıcam

Ağlıcam

Mektupları yak demiştin yakmıcam

Yakmıcam

Mektup yanmaz adam yanar eftelya gözlüm

Adam yanar

Vurmucam demiştim kafamı duvarlara

Ya duvarları ya kafamı parçalıcam bu gece

Seni nasıl sevdiğime yanağımdan süzülenler şahittir

Şahittir ayla gece

Heeey gidi Hatem Gökçek

İstanbul yansa bu gece yorganın yok içinde, 

Tutunacak dalın, çalıcak kapın yok

Yok yok yok....

Anladım 

Sensizken bu şehrin anlamı yok

Üsküdar kıyısında görüşmek üzre', 'İstanbul üstüme yıkıldı bu gece,  Taş taş, duvar duvar, sokak sokak,  Mahalle mahalle İstanbul üstüme yıkıldı bu gece Hangi denize atsam ken...', ARRAY['Türk Edebiyatı','Şiir','Hatem Gökcek']::text[], 8.5, '{"poet":"Hatem Gökcek","poet_slug":"hatem-gokcek","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/uskudar-kiyisinda-gorusmek-uzere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Yağıyordu', 'kar-yagiyordu-gokhan-uckaya-m8sam', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kar yağıyordu 

yankısız sessizliğinde yürüyordum

artık içimde hiçbir şeyi yerinden oynatmayan anıları bırakarak

köşebaşı, kapı içi, kertenkele kuytularına 

gecelerin soğuk soluklularını duyuyordum her adımda

yürüyorum böyle ama basmıyorum ömrün boş basamaklarına

yarın ne olacak ilgilenmiyorum

            hiç düş görmüyorum dedim neden sonra

hiç bir yere gitmediğimden mi acaba? 

soramadım sana: nasıl döner bu geceler beyaza? 

ıpılık, insanca

nefesimiz yetmemişti de bir zamanlar geceleri ısıtmaya

gitmediğim yerler ağrıyor şimdi başımda

atılmamış adımlar arkadaş yalnızlıklarında

anıları yitirerek kararıyorum

istemeden karıştırılıyorum gecelerin soğuk soluklularına

yankısız bir sessizlikte kar yağmaya devam ediyor 

ömrün boş basamaklarına

(kavaklıdere, Aralık 2002)', 'kar yağıyordu  yankısız sessizliğinde yürüyordum artık içimde hiçbir şeyi yerinden oynatmayan anıları bırakarak köşebaşı, kapı içi, kertenke...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Üçkaya']::text[], 8.5, '{"poet":"Gökhan Üçkaya","poet_slug":"gokhan-uckaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kar-yagiyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Aşk Haydi Gel Artık', 'ey-ask-haydi-gel-artik-gokhan-uckaya-zzrvj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ey aşk haydi gel  artık

aşk haydi gel

ağırlaşan kalbimi

kuştüyü bulutlara sarda hafiflesin

gözlerim yola bakmaya başlasın

kim gelecek umursayayım

aşk gelsin

serçenin kanat pıtırtısı göğsümün içinde

bol ezanlı bir ikindi sofrası

günbatımı gözlerimin önünde

damağımda dilinin tadı sevgilinin

ne oluyor? 

dünyayı önemseyeyim

ey pembe pamuk helvası hayatın

haydi gel artık

(kavaklıdere, Eylül 2002)', 'ey aşk haydi gel  artık aşk haydi gel ağırlaşan kalbimi kuştüyü bulutlara sarda hafiflesin gözlerim yola bakmaya başlasın kim gelecek umursa...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Üçkaya']::text[], 8.5, '{"poet":"Gökhan Üçkaya","poet_slug":"gokhan-uckaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ey-ask-haydi-gel-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-mustafa-tanrikulu-ta8w5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Başımdan aklım alan o nurani gözlerdi

bir parçacık kor alıp kalbime sokuverdi

nasıl yandığımı bilse idi kays-ı divâne 

çekilirdi meydan-ı aşktan ''sen buyur ''derdi

müşteki değilim halimden...hatta memnunum 

zirâ rabbim bana aşkın hayr-âbından verdi', 'Başımdan aklım alan o nurani gözlerdi bir parçacık kor alıp kalbime sokuverdi nasıl yandığımı bilse idi kays-ı divâne  çekilirdi meydan-ı aş...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ask-159-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İster', 'i-ster-mustafa-tanrikulu-zfm66', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'heceyle bir gazel

yare malum olmuştur aşkım ki benden can ister

kalbimden ülke veririm almaz bir cihan ister

daima kasideler gazeller  söylerim ona 

o ise şimdiye dek söylenmemiş sühan ister 

aşk-ı hafi ona leziz mi geliyor acaba

belki bunun için benden de aşk-ı nihan ister

yar onau nasıl sevdiğimi bilmez görünür de 

hürmetime sebeb muhabbetime nişan ister.

neden bana   bu aşk cefasını çektirir bilmem 

sanırım ki o yar halim daim perişan ister

lisan-ı tayr bilmem, hükmüm de geçmez cinnlere 

ama yine de benden devlet-i süleyman ister

gözler i nur ile dolu inanmaz mı aşkıma

ki ism-i allah üzere  edilmiş peyman ister.

mustafa cananından şikayetle bahseder ki:

kalbimden ülke veririm almaz bir cihan ister', 'heceyle bir gazel yare malum olmuştur aşkım ki benden can ister kalbimden ülke veririm almaz bir cihan ister daima kasideler gazeller  söyle...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ister-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düştü', 'dustu-mustafa-tanrikulu-7d2w3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sensizlik ateşiyle tutuşan bu gönüle 

yüreğinden fışkıran bir damlacık kan düştü.

ibrahim''e yüz binlerce selam olsun ki 

bana da ateşler içinde bir mekan düştü, 

ateş içinde gül bahçesi neymiş anladım

bunca zaman cansız duran bedene can düştü.', 'sensizlik ateşiyle tutuşan bu gönüle  yüreğinden fışkıran bir damlacık kan düştü. ibrahim''e yüz binlerce selam olsun ki  bana da ateşler içi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dustu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nuraynım', 'nuraynim-mustafa-tanrikulu-e19yi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'nuraynım  aşkın yakmış  misl-i nar beni 

dertliyim ki tatmin etmez bahar  beni.

ben unutmam  o nur-sima yari lakin 

tanımaz bile nasıl unutsun yar beni', 'nuraynım  aşkın yakmış  misl-i nar beni  dertliyim ki tatmin etmez bahar  beni. ben unutmam  o nur-sima yari lakin  tanımaz bile nasıl unuts...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nuraynim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiğ Damlaları', 'cig-damlalari-ufuk-nazim-mqrbs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaprakların hışırtısında; 

Ormanın soluğu.

Uzak bir yamacın; 

Son ağaran dalıyım şimdi.

Bu baharda; 

Kar yağdı dallarıma.

Yollar ıradı.

Ya olmasaydı; 

Çiğ damlaları; 

Ne kadarda; 

Yalnız kalırdı, 

Yapraklarım.', 'Yaprakların hışırtısında;  Ormanın soluğu. Uzak bir yamacın;  Son ağaran dalıyım şimdi. Bu baharda;  Kar yağdı dallarıma. Yollar ıradı. Ya o...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cig-damlalari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlere Düşme', 'duslere-dusme-ufuk-nazim-77xvc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşlere düşme; 

Düşüp de üşüme.

Her şeyin; 

Bir hikayesi

Ve sonu vardır.

Düşlere düşme; 

Düşüp de üşüme.

Hayallere kapılıp; 

Unutma yüzümü.

Kırlangıçların; 

Kapkara yüreklerindeki

Hüznünü  bilir misin? 

Göç edip ıraklara, 

Uzaklardan sever; 

Kırlangıçlar.', 'Düşlere düşme;  Düşüp de üşüme. Her şeyin;  Bir hikayesi Ve sonu vardır. Düşlere düşme;  Düşüp de üşüme. Hayallere kapılıp;  Unutma yüzümü. ...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/duslere-dusme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pencerem', 'pencerem-ufuk-nazim-96nbh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Pencerem; 

Karanlığa açıldı.

Ve rüzgar taşıyor; 

Gizemli bir fısıltıyı.

Yaprakların fısıltısı bu.

Dut ağacım; 

Bu akşam, 

Bende onun kadar yalnızım, 

O da benim kadar yalnız.

Dut ağacı fısıldıyor geceye; 

Bana olan aşkını.

Ben gidince, 

Solan yapraklarını.

Kararan bahtı; 

Kapkara dutlarını.', 'Pencerem;  Karanlığa açıldı. Ve rüzgar taşıyor;  Gizemli bir fısıltıyı. Yaprakların fısıltısı bu. Dut ağacım;  Bu akşam,  Bende onun kadar y...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/pencerem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülü Sev', 'gulu-sev-ufuk-nazim-6ikbj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni sevme; 

Seveceksen, 

Gülü sev.

Ben dikenim.

Beni sevme; 

Seveceksen, 

Günü sev.

Ben bulutum.

Beni sevme 

Seveceksen; 

Bülbülü sev.

Ben kafesim.', 'Beni sevme;  Seveceksen,  Gülü sev. Ben dikenim. Beni sevme;  Seveceksen,  Günü sev. Ben bulutum. Beni sevme  Seveceksen;  Bülbülü sev. Ben ...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gulu-sev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgede', 'golgede-ali-ender-cemgil-k4vyd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gölgesinde kaldı güzelliği

Hüzünlü bir aşk sonrası', 'Gölgesinde kaldı güzelliği Hüzünlü bir aşk sonrası...', ARRAY['Türk Edebiyatı','Şiir','Ali Ender Cemgil']::text[], 8.5, '{"poet":"Ali Ender Cemgil","poet_slug":"ali-ender-cemgil","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/golgede-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanız Ve Yalın', 'yaniz-ve-yalin-ufuk-nazim-iys69', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İşte yalnızım; 

Yalın derin

Ve kapkara.

Sessiz kederli, 

Ve umutluyum.

Gözlerin yanı başımda; 

Duvarlara kazılmış, 

Sözlerin karşımda.', 'İşte yalnızım;  Yalın derin Ve kapkara. Sessiz kederli,  Ve umutluyum. Gözlerin yanı başımda;  Duvarlara kazılmış,  Sözlerin karşımda....', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yaniz-ve-yalin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkılma Öyle', 'yikilma-oyle-ufuk-nazim-rbl7p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıkılma öyle geceye.

Sanma ki saklanırsın; 

Sen o pırıl pırl gözlerinle; 

Saklanamazsın geceye.

Rimeller içinde, 

Tutsak mı gözlerin.? 

Ah o; 

Kapkara zülüflerin.

Amansız gülüşlerin.

Kaç benden, 

Kapkara geceye.

Yarın olur; 

Dönersin göğüme.', 'Yıkılma öyle geceye. Sanma ki saklanırsın;  Sen o pırıl pırl gözlerinle;  Saklanamazsın geceye. Rimeller içinde,  Tutsak mı gözlerin.?  Ah o...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yikilma-oyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanatmayın', 'kanatmayin-ufuk-nazim-r7wtg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey! 

Bembeyaz; 

Teninden yansıyan, 

Kızıl gün.

Kıyma ona.

Zamanın kara delikleri; 

Huzme huzme yayılıp, 

Karartmayın, 

Bembeyaz tenini.

Kanatmayın savaşlar; 

O güzelim.

Bembeyaz, 

Canım dünya, 

Entarisini.', 'Ey!  Bembeyaz;  Teninden yansıyan,  Kızıl gün. Kıyma ona. Zamanın kara delikleri;  Huzme huzme yayılıp,  Karartmayın,  Bembeyaz tenini. Kana...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kanatmayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-ufuk-nazim-n977h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ses ver; 

Yırt canım geceyi; 

Işıl ışıl gel.

Gören olsa da; 

Olmasa da.

Usulca değil; 

Hızlı hızlı gel.

Zincirlerinle  gel.

Sessizce değil, 

Şangur şungur gel.

Yüreğ, ndeki; 

Odla gel.

Saklamadan alevini; 

Geceyi tutuştur, 

Öyle gel.', 'Ses ver;  Yırt canım geceyi;  Işıl ışıl gel. Gören olsa da;  Olmasa da. Usulca değil;  Hızlı hızlı gel. Zincirlerinle  gel. Sessizce değil, ...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gel-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dut', 'dut-ufuk-nazim-cmihm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir dut ağacı gibi, 

Dutların düşerken; 

Sen büyüme telaşında, 

Yükselensin.', 'Bir dut ağacı gibi,  Dutların düşerken;  Sen büyüme telaşında,  Yükselensin....', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Tortusu', 'sevgi-tortusu-ufuk-nazim-2swev', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Umut çaylarından geriye; 

Bir tutam, 

Sevgi tortusu  kalır.

Usanmadan iç.

Umudun çayını.

Tortusunda; 

Elbet yeşerir, 

Çaydan umut filizleri.', 'Umut çaylarından geriye;  Bir tutam,  Sevgi tortusu  kalır. Usanmadan iç. Umudun çayını. Tortusunda;  Elbet yeşerir,  Çaydan umut filizleri....', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgi-tortusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudun Gibi', 'umudun-gibi-ufuk-nazim-ypld4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zincirlerin; 

Gülleridir özgürlüğün.

Sırtla onları; 

Taşı umudun gibi.

Zincirlerin gülüm; 

Gülsen sen, 

Dikenlerindir.

Taşı onları; 

Kurtuluşun gibi.', 'Zincirlerin;  Gülleridir özgürlüğün. Sırtla onları;  Taşı umudun gibi. Zincirlerin gülüm;  Gülsen sen,  Dikenlerindir. Taşı onları;  Kurtulu...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/umudun-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüznün', 'huznun-ufuk-nazim-odot7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hüznün, 

Titretir yüreğimi; 

Hüznünden geçemem, 

Yarının umut iklimine.

Takılır kalırım; 

Akarsuyun, 

Dingin taşlarına.

Ulaşamam denizime.

Hüznün gülüm; 

İsyanımdır doğan güne.', 'Hüznün,  Titretir yüreğimi;  Hüznünden geçemem,  Yarının umut iklimine. Takılır kalırım;  Akarsuyun,  Dingin taşlarına. Ulaşamam denizime. H...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/huznun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam', 'yasam-ufuk-nazim-es9v2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Soğuk bir zeminde; 

Eşelenen böcek.

Zamanda eğik bir, 

Çınar dalı.

Yokuşlarda kambur, 

Bir insan mı? 

Ezgilerle yayılan, 

Bir türkü mü? 

Yaşam.', 'Soğuk bir zeminde;  Eşelenen böcek. Zamanda eğik bir,  Çınar dalı. Yokuşlarda kambur,  Bir insan mı?  Ezgilerle yayılan,  Bir türkü mü?  Yaş...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasam-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usandı', 'usandi-ufuk-nazim-d5f84', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Usandı; 

Ellerinde umutları, 

Ve gözlerinde, 

Parıldayan ışığıyla; 

Uzandı upuzun, 

Göğün; 

Sonsuz döşeğine.', 'Usandı;  Ellerinde umutları,  Ve gözlerinde,  Parıldayan ışığıyla;  Uzandı upuzun,  Göğün;  Sonsuz döşeğine....', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/usandi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göğe Bak', 'goge-bak-ufuk-nazim-5qe8b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karaysan her şeye.

Ve yıkılmışsa; 

İnsandan kuleler.

Göğe bak.

Bir yudum mavi çek; 

Göz pınarlarına.

Geç karanın tarlasından; 

Mavi göz yaşlarınla.', 'Karaysan her şeye. Ve yıkılmışsa;  İnsandan kuleler. Göğe bak. Bir yudum mavi çek;  Göz pınarlarına. Geç karanın tarlasından;  Mavi göz yaşl...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/goge-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sardunyam', 'sardunyam-ufuk-nazim-b3lvk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Damla damla; 

Yağıyorsun bedenime.

Ve ben; 

Bu yağmurlu havalarda, 

Daha bir seviyorum seni.

Açıp bağrımı; 

Sırılsıklam 

Senle doluyorum.

Sonra seni doğuruyorum, 

Sardunyam.', 'Damla damla;  Yağıyorsun bedenime. Ve ben;  Bu yağmurlu havalarda,  Daha bir seviyorum seni. Açıp bağrımı;  Sırılsıklam  Senle doluyorum. So...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sardunyam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asi', 'asi-ufuk-nazim-nd1tq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Küçük; 

Elleri narin.

Ve ellerim, 

Kaba kıran.

Gözleri yumuşak, 

Sevecen.

Gözlerim asi; 

Yaralayan.', 'Küçük;  Elleri narin. Ve ellerim,  Kaba kıran. Gözleri yumuşak,  Sevecen. Gözlerim asi;  Yaralayan....', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/asi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangi Zerresi', 'hangi-zerresi-ufuk-nazim-1l6vd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yamaçlarında dolanan; 

Gözlerinde boğulan, 

Hangi zerresindedir, 

Zamanın.', 'Yamaçlarında dolanan;  Gözlerinde boğulan,  Hangi zerresindedir,  Zamanın....', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hangi-zerresi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tortusu Yalnızlığın', 'tortusu-yalnizligin-ufuk-nazim-jts66', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yaz akşamı; 

Hüznü.

Yüreğinde; 

Tortusu yalnızlığın.

Ve gözlerinde; 

Yiten ayın, 

Son  yakamozu.', 'Bir yaz akşamı;  Hüznü. Yüreğinde;  Tortusu yalnızlığın. Ve gözlerinde;  Yiten ayın,  Son  yakamozu....', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tortusu-yalnizligin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden Yeniden', 'yeniden-yeniden-ufuk-nazim-uwyt4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yeniden yeniden, 

Çarpmak kıyılara.

Ve yeniden ıramak; 

Doğup ufuklardan, 

Göğün düzüne.

Yıkmak yeniden yeniden; 

Yıkmak.

Ve ıramak; 

Uzak ufuklara.', 'Yeniden yeniden,  Çarpmak kıyılara. Ve yeniden ıramak;  Doğup ufuklardan,  Göğün düzüne. Yıkmak yeniden yeniden;  Yıkmak. Ve ıramak;  Uzak u...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yeniden-yeniden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma Umutlarını', 'unutma-umutlarini-ufuk-nazim-f3nq4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Unutma umutlarını, 

Hafızanın zerrelerine; 

Kazı umutlarını.

Sakla altın gibi.

Unutma umutlarını, 

Onlar ki; 

Yalnızlığın bozkırını, 

Yeşertecek bulutturlar.

Onlar ki; 

Seni yaşamın çarmıhına, 

Acılarla çakan, 

Kapkara mıhtırlar.', 'Unutma umutlarını,  Hafızanın zerrelerine;  Kazı umutlarını. Sakla altın gibi. Unutma umutlarını,  Onlar ki;  Yalnızlığın bozkırını,  Yeşert...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutma-umutlarini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimin Kıyıları', 'yuregimin-kiyilari-ufuk-nazim-srnny', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yapraklar oynuyor; 

Rüzgarda.

Alına salına; 

Bir vapur geçiyor, 

Yüreğimin kıyılarından

Dalgalar kırılıp, 

Akıyor uzaklara.

Ve bir gün daha; 

Sönüyor ufuklarda.', 'Yapraklar oynuyor;  Rüzgarda. Alına salına;  Bir vapur geçiyor,  Yüreğimin kıyılarından Dalgalar kırılıp,  Akıyor uzaklara. Ve bir gün daha;...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yuregimin-kiyilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göğün Tortusu', 'gogun-tortusu-ufuk-nazim-ke06y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Göğün masmavi tortusu mu; 

Birikmiş gözlerine.

Ayın saçakları mı? 

Sinmiş tenine.

Yüreğinin kızıl deltasında; 

Yatan, 

Hangi aşkın tohumu? 

Haydi sula aşkını, 

Masmavi gök gözlerinle.', 'Göğün masmavi tortusu mu;  Birikmiş gözlerine. Ayın saçakları mı?  Sinmiş tenine. Yüreğinin kızıl deltasında;  Yatan,  Hangi aşkın tohumu?  ...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gogun-tortusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayı Ürkütmeden', 'ayi-urkutmeden-ufuk-nazim-ugtfr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kokular sürün; 

Öyle gel.

Sessizce; 

Ayı ürkütmeden.

Ve kaçırmadan, 

Serçeleri.

Parmaklarının ucunda; 

Parmaklarını; 

İncitmeden gel.', 'Kokular sürün;  Öyle gel. Sessizce;  Ayı ürkütmeden. Ve kaçırmadan,  Serçeleri. Parmaklarının ucunda;  Parmaklarını;  İncitmeden gel....', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ayi-urkutmeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lirik Bahçen', 'lirik-bahcen-ufuk-nazim-ewcr8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Susma; 

Karanlıklar bassada, 

Lirik bahçeni.

Ve gözlerine insede; 

Perde perde, 

Zulmün kalkanları.

Susma.', 'Susma;  Karanlıklar bassada,  Lirik bahçeni. Ve gözlerine insede;  Perde perde,  Zulmün kalkanları. Susma....', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/lirik-bahcen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duymuyorsun', 'duymuyorsun-ufuk-nazim-csd44', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duyuyor musun  sesini? 

Sesin; 

Bir salıncağın, 

Paslı gıcırtısından, 

Daha eski ve cılız.

Ve duymuyorsun, 

Lanet gıcırtını.

Göz yaşların; 

Binlerce hançer, 

Acıtmıyor tenini

Kanın bitmiyor.

Susmuyorsan susma.', 'Duyuyor musun  sesini?  Sesin;  Bir salıncağın,  Paslı gıcırtısından,  Daha eski ve cılız. Ve duymuyorsun,  Lanet gıcırtını. Göz yaşların;  ...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/duymuyorsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezgilerimiz', 'ezgilerimiz-ufuk-nazim-apg04', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Göğün harmanında; 

Maviye belenip yağacak, 

Ezgilerimiz.

Yürekten doğaçlanıp, 

Tamamlanacak, 

Ezgilerimiz.', 'Göğün harmanında;  Maviye belenip yağacak,  Ezgilerimiz. Yürekten doğaçlanıp,  Tamamlanacak,  Ezgilerimiz....', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ezgilerimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memur', 'memur-ufuk-nazim-78qhj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir son.

Yaşamda ağrılı; 

Buhranlarda ezik.

Duvarlarının altında kalmış; 

Bir kent.

Soluk bir sonbaharda; 

Tüten bir sobadır memur.

Soluk bir sonbaharda; 

Dökülen yapraklarını, 

Tutuşturur ve ısınır memur.

Kendine kalır gövdesi.

Ve güne güler; 

Açık da kalan kökleriyle.

Uzanır döşeğine.', 'Bir son. Yaşamda ağrılı;  Buhranlarda ezik. Duvarlarının altında kalmış;  Bir kent. Soluk bir sonbaharda;  Tüten bir sobadır memur. Soluk bi...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/memur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öküz', 'okuz-ufuk-nazim-9er6m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '.

Dünyayı boynuzlamış; 

Uzayı sürüyor, 

Öküz.

Dönüyor ha dönüyor.', '. Dünyayı boynuzlamış;  Uzayı sürüyor,  Öküz. Dönüyor ha dönüyor....', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/okuz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Gün İçinde', 'gun-gun-i-cinde-ufuk-nazim-55mfz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün gün içine saklanır.

Ve susar insan, 

Gün içinde.

Yaşar insan gün içinde.

Gün gün içine saklanır.

Ve susar insan, 

Gün içinde.

Yaşar insan gün içinde.

Gün gün içinde; 

Hep aynı karaya çarpan, 

Dalgalar gibi, 

Devinerek yaşar insan.', 'Gün gün içine saklanır. Ve susar insan,  Gün içinde. Yaşar insan gün içinde. Gün gün içine saklanır. Ve susar insan,  Gün içinde. Yaşar insa...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gun-gun-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gök Nar', 'gok-nar-ufuk-nazim-ervx3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '.Bilinmez bir uğraş.

Amaç ki; 

Çok uzaklarda, 

Yıkılan gök narların, 

Soyulan teninden.

Tomruklar ki her biri; 

Uzun uzun yatan cesetler.

Otopsilerinde çıkan; 

İki kurdun, 

Dar ağacı olmaktan  öte; 

Ne işe yarar tomruklar.', '.Bilinmez bir uğraş. Amaç ki;  Çok uzaklarda,  Yıkılan gök narların,  Soyulan teninden. Tomruklar ki her biri;  Uzun uzun yatan cesetler. Ot...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gok-nar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tutam Yalnızlık', 'bir-tutam-yalnizlik-ufuk-nazim-zhkb5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir tutam yalnızlıktır, 

Uzaklardan sunulan.

Ve çenkirirken köpekler, 

Uzaklardan; 

Soluk soluğa kalan, 

Yorgun bir atlıdır, 

Zaman.

Ve sonda, 

Belkilerin sonunda ki; 

Nokta kadar karadır.

Göz bebeklerinin; 

Korkudan küçülen, 

Dut karası.', 'Bir tutam yalnızlıktır,  Uzaklardan sunulan. Ve çenkirirken köpekler,  Uzaklardan;  Soluk soluğa kalan,  Yorgun bir atlıdır,  Zaman. Ve sond...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-tutam-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yırtılan Gök', 'yirtilan-gok-ufuk-nazim-jqa1u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yırtılan göğün; 

Kızıl tortusu kalmış, 

Ufuklarda.

Ve güneş; 

Renk ahenk, 

Kahkahalarla boyamış, 

Tutuşan bir gök kuşağını, 

Ancak yağmurlar harlar.

Unutma su; 

Her an yaratandır.

Ve renklerin maviden aksini; 

Tayf tayf yayandır.', 'Yırtılan göğün;  Kızıl tortusu kalmış,  Ufuklarda. Ve güneş;  Renk ahenk,  Kahkahalarla boyamış,  Tutuşan bir gök kuşağını,  Ancak yağmurlar...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yirtilan-gok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzun Uzun', 'uzun-uzun-ufuk-nazim-2zkz4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzun uzun, 

Sıra sıra, 

Renk renk, 

Göğe ağar, 

Gök narlar.

Gök onlara ağlar, 

Gök narlar göğe ağar.', 'Uzun uzun,  Sıra sıra,  Renk renk,  Göğe ağar,  Gök narlar. Gök onlara ağlar,  Gök narlar göğe ağar....', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/uzun-uzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maşay İm Lezüg Ecnes', 'masay-i-m-lezug-ecnes-oguzkan-bolukbasi-eoyps', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'başaşağı uyumayı denedin mi

ya da ters yürümeyi

etten duvar örülmüş gördün mü

duvardan et yapanlar vardı bir yerlerde

insan bu

çiğ süt emmiş

başka da süt bulamamış

annesi bilse sütünü ısıtmaz mıydı  emzirirken

akıl mı çok 

akılsız mı

saymaya kalkarsan

kendini akılsızdan say

beni de

''ölümün karşıtı doğum

yaşamın karşıtı yoktur''

dedi genç çocuk filmde

yeni birşeyi kabullendim

şaşırdım 

çok ta doğru

yaşamla değiştirecek neyimiz var

herşey yeniden olur

yaşam asla

sabah uyandığımda 

elimde bir gün daha var

uyanmadığımda

bir gün daha yok

bir gün daha yoksa

aşk yok

sevda yok

macera yok

iyilik yok

kötülük yok

yaşam güzel mi sence', 'başaşağı uyumayı denedin mi ya da ters yürümeyi etten duvar örülmüş gördün mü duvardan et yapanlar vardı bir yerlerde insan bu çiğ süt emmiş...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/masay-im-lezug-ecnes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''u Seviyorum Ama', 'i-stanbul-u-seviyorum-ama-kamil-aydemir-uhnne', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'istanbul düşünce aklıma

ilk sen dikilirsin karşıma

ve alçakların inadına

istanbul''un güzellikleri dizilir ardına

gözlerimi yatıramam

umut değirmeni beyoglu sokaklarına

üniversiteli kızlar başka hava katar beyazıt meydanına

her biri bir ışık yarına

sevgimle yüreğindeki hüzününü kuruturum

insanların her çeşitini bulurum eminönü''nde saati unuturum

kendimi de senin yanında

türküler limanımdır efkârlı anımda

kelebek oluruz beykoz sırtlarında

elele gideriz karakartalın maçlarına

ve yaslanırız düşlerimizin yamaçlarına

evine ekmek ile dönen işsizin sevincini taksam saçlarına

yaralanırsın değme gözyaşlarıma

kimselere göstermeden ağlarım

sokak kedisi gibi garip

bir çocuk sokulsa yanıma

keşke yetsem bütün anaların imdadına

tepende kuşlar sokaklarında çocuklar istanbul seni nakışlar

biraz da özlemin kokar gözlerimden akan yaşlar

kavgaların sevdaların şehri nice aşklar sende başlar

tarih dürüst olanı aklar arkadaşlar

sevgiler büyütürüm yürekte kimseye olmaz zararım

bütün güzelliklerde istanbul''u ararım

gözlerim göğüslerine konar yanarım

çoruh''un dudaklarında açan 

                 çiçeklerden de önde tutarım seni maralım

sırtını sevgime yasla yürekten yaralım

güzellikleri yarınlarımıza saralım

çaresin yürek ağrıma

kulak ver çağrıma

sen heycan doğrarsın

sen ateş kanıma

aşkında tutuşur yanarım

azdır sensiz rüyalarım

istanbul''u seviyorum ama

önce gözlerine dalarım', 'istanbul düşünce aklıma ilk sen dikilirsin karşıma ve alçakların inadına istanbul''un güzellikleri dizilir ardına gözlerimi yatıramam umut de...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/istanbul-u-seviyorum-ama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöz Beni', 'coz-beni-fatih-kagan-yucel-u6j9w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Al vuslatı ver gurbeti cananım

Derde salıp hasretinle üz beni

Hem aşikar hem muamma olayım 

Gör özümü bul gizimi çöz beni

Yüreğinden duy diyerek sızımı 

Esirgedim aşk haykıran sözümü

Turabındır öyle farzet özümü 

Karış karış adım adım gez beni

Bir sır olup aşinadan arınsam

Aydınlıkta karanlığa bürünsem

Sen ismimi yâd ettikce görünsem

Söner iken körüklesen köz beni

15 ekim 2001', 'Al vuslatı ver gurbeti cananım Derde salıp hasretinle üz beni Hem aşikar hem muamma olayım  Gör özümü bul gizimi çöz beni Yüreğinden duy diy...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kağan Yücel']::text[], 8.5, '{"poet":"Fatih Kağan Yücel","poet_slug":"fatih-kagan-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/coz-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-gunay-aktag-n2yer', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen o ki varlığınla insanları büyüleyen

Sen ki yere göğe sığmayan 

Hep kalp lerde taşınan

Keskin ateşinle yürekleri dağlayan

Kimi zaman insanın canına can katan

Kimi zaman canından can alan

Sen bu dünyada eşi benzeri bulunmayan

Yüce varlık

Aşkı sende hissettiğim o tek ışık

O tek aydınlık..

Sevgi, sevgi, sevgi........', 'Sen o ki varlığınla insanları büyüleyen Sen ki yere göğe sığmayan  Hep kalp lerde taşınan Keskin ateşinle yürekleri dağlayan Kimi zaman insa...', ARRAY['Türk Edebiyatı','Şiir','Günay Aktağ']::text[], 8.5, '{"poet":"Günay Aktağ","poet_slug":"gunay-aktag","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevgi-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoş', 'sarhos-fatih-kagan-yucel-06zy4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kadehler hapsedildi sakiler intiharda

Vuslatın şarab oldu hasret körkütük sarhoş

Razı olmak var şimdi arzularım firarda

Senin cehennemin de senin cennetin de hoş...', 'Kadehler hapsedildi sakiler intiharda Vuslatın şarab oldu hasret körkütük sarhoş Razı olmak var şimdi arzularım firarda Senin cehennemin de ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kağan Yücel']::text[], 8.5, '{"poet":"Fatih Kağan Yücel","poet_slug":"fatih-kagan-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sarhos-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gülü Birde Seni Çok Sevdim', 'bir-gulu-birde-seni-cok-sevdim-bulut-sengul-vpral', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sir gülü bir de seni

çok sevdim

sen gittin güllerim soldu

seni aldılar elimden 

gülümü kopardılar dalından

yalancı bir bahardı 

geldi geçti

senin resimlerin

güllerin kurusu 

kaldı elimde

bir seni birde gülü

çok özledim

güller umudumdu

sense sevdiğim

güllerin dikeni

senin apansız gidişin

kanattı yüreğimi

bir gülün kokusunu

birde senin dönüşünü 

beklerim

kaç baharda daha 

geçecek bilmem

güller kokmadan 

sen gelmeden

ben bekliyorum

güller kokmuyor

inatla

sende gelmiyorsun', 'Sir gülü bir de seni çok sevdim sen gittin güllerim soldu seni aldılar elimden  gülümü kopardılar dalından yalancı bir bahardı  geldi geçti ...', ARRAY['Türk Edebiyatı','Şiir','Bulut Şengül']::text[], 8.5, '{"poet":"Bulut Şengül","poet_slug":"bulut-sengul","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-gulu-birde-seni-cok-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölene Kadar', 'olene-kadar-fatih-kagan-yucel-e8ghs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Koy iki gözümü gözün yerine

Ağla gözlerimle solana kadar

Sazın bil gönlümü göm yüreğine

Sakla türkülerde çalana kadar

Feryadın feryadım acın acımdır

Yaptığın sitemler başa tacımdır

Yaşıyorsam eğer senin içindir

Nefesim ol ecel gelene kadar

Gönlün bahçesinde gül olup solam

Aşkının yolunda dolmasın çilem

Gözlerin mürekkep bakışın kalem

Karala gönlümü ölene kadar

eylül 2001', 'Koy iki gözümü gözün yerine Ağla gözlerimle solana kadar Sazın bil gönlümü göm yüreğine Sakla türkülerde çalana kadar Feryadın feryadım acın...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kağan Yücel']::text[], 8.5, '{"poet":"Fatih Kağan Yücel","poet_slug":"fatih-kagan-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olene-kadar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyemediklerim', 'diyemediklerim-fazli-cinar-qg6p2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Diyemediklerimin biriktirdiği hüzün 

Her gece yarası bir kurşun yarası açar

Umudun orta yerinden

Çırılçıplak ruhunla

Sen geçerken sevgili

Hasretinin en dokunduğu saatte

Bir yalnızlık senfonisi başlar

Kulakları sağır eden bir uğultu duyulur

Bir çığlık atacak gücü yoktur

İçimdeki çocuğun

Kalbi açtır ve ağladığı duyulmamaktadır', 'Diyemediklerimin biriktirdiği hüzün  Her gece yarası bir kurşun yarası açar Umudun orta yerinden Çırılçıplak ruhunla Sen geçerken sevgili Ha...', ARRAY['Türk Edebiyatı','Şiir','Fazlı Çınar']::text[], 8.5, '{"poet":"Fazlı Çınar","poet_slug":"fazli-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/diyemediklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelişki', 'celiski-fatih-kagan-yucel-ysrbt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerimde bir telaş vuslatı bulmuş gibi 

Lakin kelimelerim herdem hasret kokuyor

Bu nasıl bir ikilik bu nasıl bir çelişki

Deryada serinlerken sular beni yakıyor

9 kasım 2002', 'Gözlerimde bir telaş vuslatı bulmuş gibi  Lakin kelimelerim herdem hasret kokuyor Bu nasıl bir ikilik bu nasıl bir çelişki Deryada serinlerk...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kağan Yücel']::text[], 8.5, '{"poet":"Fatih Kağan Yücel","poet_slug":"fatih-kagan-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/celiski-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pul', 'pul-askin-gungor-uf7mt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yırtıp da atamıyorum

sevgili

(sevmegili) , 

arkasını dilinle

ıslatıp da

biteviye, 

o sarı çirkin zarfın üzerine 

yapıştırdın diye

kırmızı çiçeklerin

(neredeyse) 

koktuğu arsız pulu

ve okunmaktan yorulan

uykusuz veda mektubunu. (04.07.2003)', 'yırtıp da atamıyorum sevgili (sevmegili) ,  arkasını dilinle ıslatıp da biteviye,  o sarı çirkin zarfın üzerine  yapıştırdın diye kırmızı çi...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Güngör']::text[], 8.5, '{"poet":"Aşkın Güngör","poet_slug":"askin-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/pul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Geç', 'cok-gec-omer-serdar-cek88', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ayrılık bilmezken biz bilmiştik istanbul

türdeş yenilmiştik, darbelenmiştik

çağdaş bir esintiyle bölünmüştü uykumuz

adalardan yelken doldurmuştuk karaipler’ e

kara derili insanlara tutunmuştuk

durgundu sular fenerbahçe’ de

tuzundan ayrılmış bir deniz

buruk bir sılaya göç tutmuş

zaman yağmur olmuş

yoğuşmuştu göz oyuklarımızda

bir arya duyulmuştu yaylalarda

şişli, levent ardında bostanlar

lay lay lay... yaa!  haydarpaşa

moda, ‘piyer loti’ idi o zamanlar işte

iskeleyse ‘rüzgârlı bayır’ hani

kadıköyde rıhtıma dalga aşırırdı buluşmalar 

o noktada tutardı ellerden

sen orada bir bebek doğurmuştun 

salacak’da sular kumsalı

yanağından okşamıştı o zamanlar

orada bir şiir yakmıştın, iki olmuştu

bir vapura binmişti bizim gibi

bizim gibi ayrılmıştı limandan

ve türdeşti tüm gemi kazanlarında ateş

pervaneler karıştırırken ard sularını

yanan yüreğimizle dönmüştü başımız 

“gık” ımız çıkmadı o gün bugün

barbaros bulvarı kaç kez kazıldı

kaç kez ağlattı anasını arazözlerin

kaç martı göçüp gitti boğazdan

kızkulesi kaç şairin yazlığı oldu

ağladılar harem’ de yalnız yolcularla

istanbul kaç istanbul’ u ağlattı

ve biz kaldık

                  gıkımız çıkmadı

sen kaç istanbul

                   kaç git ve kurtul

bize çok geç firardan', 'ayrılık bilmezken biz bilmiştik istanbul türdeş yenilmiştik, darbelenmiştik çağdaş bir esintiyle bölünmüştü uykumuz adalardan yelken doldurm...', ARRAY['Türk Edebiyatı','Şiir','Ömer Serdar']::text[], 8.5, '{"poet":"Ömer Serdar","poet_slug":"omer-serdar","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/cok-gec-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sobe', 'sobe-askin-gungor-zhdgv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Başka bir denizin kıyısındasın.

Örtüyorsun gözlerini

(Bakışlarında kanat vuran martıları

     görmesinler diye mi?) 

Boğazında eskimiş sevda tadı, 

     geçmişi ezerce adımlarken ıslak kaldırımları

          atıyorsun dalgalara yüreğinden koparıp

               şiirleştirdiğin o sevgili adları.

Kim bilir hangi ırak tende geziyor parmakların? 

Hangi gölgeleri tanıdık buluyorsun? 

Ve kim bilir nasıl bir taze kan arayışıyla

     yüreğindeki sızıları dindirmeye uğraşıyorsun? 

Hayat hoyrat elleriyle eskitirken

     çocuk bakışlı kocaman adamları

         sen belki de 

              ellerin aynı düş tenlerinde

                  ve sevdayı ıskalayacak raylarda öksüren

                       şiir yoksulu trenlerde

                            (beklendiğinden habersiz) 

                                 uyukluyorsun.

Başka öykülere uzaklaşırken

     sesin kalıyor geride.

Dokunduğun her tende 

     beni ''sobe''liyorsun.

Ah sevdiceğim, bilmezsen bilme; 

     aldığın her nefeste

          bana dönüşüyorsun.

(şimdi durmuş bu şiirin kıyısında, 

gelene geçene dil çıkarıyorsun...)

27.06.2003 Işıklı bir gün...', 'Başka bir denizin kıyısındasın. Örtüyorsun gözlerini (Bakışlarında kanat vuran martıları      görmesinler diye mi?)  Boğazında eskimiş sevda...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Güngör']::text[], 8.5, '{"poet":"Aşkın Güngör","poet_slug":"askin-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sobe-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efgar', 'efgar-mehmet-ali-kepez-e0nkf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir efgar buludu durdu üstüme

	Yağdi sicim gibi sel etti beni

	Aktım bozbulanık çakıl taş ile

	Dümeni kırılmış sal etti beni

	Deryanın dibinde yalnız başına

	Koymadı acılar geldi peşime

	Niyeti götürmek böyle hışıma

	Efgar''ın buludu yol etti beni

	Saldırdı üstüme anı ordusu

	Yıkıldi gönlümün gecekondusu

	Bir sinsi hayinin dedi kodusu

	Dostların gönlünde el etti beni

	Deme Kepez şu Dünyada harcım var

	Agzına dek keder dolu hurcum var

	İyi ki feleğe bir can borcum var

	Her aksam uğrayıp del etti beni', 'Bir efgar buludu durdu üstüme 	Yağdi sicim gibi sel etti beni 	Aktım bozbulanık çakıl taş ile 	Dümeni kırılmış sal etti beni 	Deryanın dibin...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/efgar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle güle', 'gule-gule-mehmet-ali-kepez-m9nhe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne olur yar söylesene

	Neden geçmiyor bu sene

	Gidilmez haber vermeden

	Durduk yerde öylesine

	Ağamam neyine yarar

	Gönül bu sevdiğin arar

	Bağ dikip şivga vermeden

	Ayırılığa verdin karar

	Gölge edermiyim güle

	Yanip dönmüşüm ben küle

	Kanayan yaram sarmadan

	Gidiyorsan güle güle

	Helal olsun emeklerim

	Susuz çatlar damaklarım

	Yoluna bakıp durmadan

	Bir ömùr seni beklerim', 'Ne olur yar söylesene 	Neden geçmiyor bu sene 	Gidilmez haber vermeden 	Durduk yerde öylesine 	Ağamam neyine yarar 	Gönül bu sevdiğin arar 	...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gule-gule-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne dokunaklı fiildir ''unutmak''....', 'ne-dokunakli-fiildir-unutmak-elif-sebnem-akal-tp39c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne dokunaklı fiildir ''unutmak''

Ne hazin öyküleri vardır....unutuldum sananların, 

Ne yürek acısı yalandır, söylemek....''unuttum''...

Ve, 

Sonu gelmez şarkıda, şiirde... yalanların....

Oysa...iyileşmiş yaradan düşen kabuk izidir aşklar, 

Bilir yazan, okuyan da bilir oysa...

Kabul görmez içten içe.... o yalanlar....

Sevmenin sonu gelir...

Ya hatırlamanın? 

Açılır bir hatırayla Unuttum sandıkların...

Unuttum sandıklarına sığdıramadıkların..

Bilinmez ki, o sevdalar  ''unutmaya'' yakışmaz, 

Unutmak bilgiye mahsus...

Sevgili unutulmaz...', 'Ne dokunaklı fiildir ''unutmak'' Ne hazin öyküleri vardır....unutuldum sananların,  Ne yürek acısı yalandır, söylemek....''unuttum''... Ve,  Son...', ARRAY['Türk Edebiyatı','Şiir','Elif Şebnem Akal']::text[], 8.5, '{"poet":"Elif Şebnem Akal","poet_slug":"elif-sebnem-akal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ne-dokunakli-fiildir-unutmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ki', 'ki-sair-masmavi-b5d2h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kendinden geçerek bakmalısın sevdiğine

İçini görecek gibi, taa içini

Öyle bir sevgiyle

Ki, seni sevsin

İçin kanayarak ağlamalısın ayrılığa

Yüreğin parçalanır gibi

Bitmeyen bir özlemle

Ki, sana dönsün

Altını çizerek yaşamalısın hayatı

Dikkatle okunan bir kitap gibi

Delicesine bir özenle

Ki, senin olsun.', 'Kendinden geçerek bakmalısın sevdiğine İçini görecek gibi, taa içini Öyle bir sevgiyle Ki, seni sevsin İçin kanayarak ağlamalısın ayrılığa Y...', ARRAY['Türk Edebiyatı','Şiir','Şair Masmavi']::text[], 8.5, '{"poet":"Şair Masmavi","poet_slug":"sair-masmavi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ki-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karasevda', 'karasevda-cahit-sitki-taranci-6r1x7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kere sevdaya tutulmaya gör; 

Ateşlere yandığının resmidir.

Aşık dediğin, Mecnun misali kör; 

Ne bilsin alemde ne mevsimidir.

Dünya bir yana, o hayal bir yana; 

Bir meşaledir pervaneyim ona.

Altında bir ömür dönedolana

Ağladığım yer penceresi midir? 

Bir köşeye mahzun çekilen için,

Yemekten içmekten kesilen için,

Sensiz uykuyu haram bilen için,

Ayrılık ölümün diğer ismidir.', 'Bir kere sevdaya tutulmaya gör;  Ateşlere yandığının resmidir. Aşık dediğin, Mecnun misali kör;  Ne bilsin alemde ne mevsimidir. Dünya bir y...', ARRAY['Türk Edebiyatı','Şiir','Cahit Sıtkı Tarancı']::text[], 8.5, '{"poet":"Cahit Sıtkı Tarancı","poet_slug":"cahit-sitki-taranci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/karasevda-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''a Kar Yağıyordu', 'i-stanbul-a-kar-yagiyordu-i-brahim-sadri-gicls', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yetmişdokuzun kışıydı, 

Sertti, soğuktu 

İstanbul''a kar yağıyordu. 

Kömür yanıyordu sobalarda 

Geceleri polisler, bekçiler oluyordu. 

Bir de biz oluyorduk 

Ölümüne üşüyorduk ha 

Yalan yok polisler de üşüyordu 

Onaltı yaşındaydım.. 

Her şeyi bükecek bileğim vardı 

Onaltı yasındaydım 

Aslan gibi ortadaydım 

Gündüzleri okulda coğrafya defterimin arkasına 

Senin için şiirler, 

Geceleri duvarlara ülkemi kurtarmak için 

Kahrolsun yazacak kadar adamdım 

Onaltı yaşındaydım 

Ne senin haberin oluyordu şiirlerimden 

Ne de birileri kahroluyordu 

Mahalle duvarlarına çiziktirdiğim harflerimden 

Onaltı yaşındaydım 

Yalan yok 

Ben yazmaya böyle başladım 

Coğrafya defterim bir eskiciye kurban gitti 

Duvarlarına yüreğimi bağırdığım o evler birer birer 

Yıkıldı gitti. 

Simdi güzel kağıtlara yazıyorum, 

Kocaman laflar ediyorum 

Marşlar biliyordum, 

Kitaplar okuyordum. 

Koşarak ve ıslanmadan geçiyordum sulardan 

Koşarak ve ıslanmadan yaşıyordum. 

Bak 

İstanbul''u seviyordum 

Seni seviyordum 

Dualar öğreniyordum 

Meydanlarda toplanıp bağırıyordum 

Herkes gibiydim, 

Herkes kadar cesur 

Herkes kadar korkak 

Herkes kadar filinta delikanlı 

Ve herkes kadar buralı... 

Yetmişdokuzun kışıydı, 

Sertti, soğuktu 

İstanbul''a kar yağıyordu... 

Ağzımızdan dumanlar çıkıyordu konuşurken. 

Haliç’ in arkasında toplanıyorduk 

Gece adamı içine çekiyordu 

Biz geceyi içimize çekiyorduk... 

En güzel ben yazıyordum duvarlara yazıları 

Herkes beni seviyordu... 

En güzel şiirleri de ben yazıyordum oysa 

Coğrafya defterimin arkasına... 

Bunu kimse bilmiyordu 

Sizin evin duvarına kahrolsun diye yazıyordum 

Ve hızla kaçıyordum 

Sizin evin duvarına bir kez olsun 

Seni seviyorum diye yazamadım 

O zaman duvarlara öyle şeyler yazılmıyordu 

Dedim ya 

Yetmişdokuzun kışıydı 

Sertti, soğuktu 

İstanbul''a kar yağıyordu...', 'Yetmişdokuzun kışıydı,  Sertti, soğuktu  İstanbul''a kar yağıyordu.  Kömür yanıyordu sobalarda  Geceleri polisler, bekçiler oluyordu.  Bir de...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sadri']::text[], 8.5, '{"poet":"İbrahim Sadri","poet_slug":"i-brahim-sadri","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/istanbul-a-kar-yagiyordu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Er Mektubu', 'er-mektubu-ugur-arslan-l01f3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O elinde tuttuğun zarf 

bir ihanet anında örülmüştür 

Ve zarfın içindeki kağıt 

er mektubudur görülmüştür 

Doğum günüm bu gün 3 Aralık 

Ve şafak karanlık 

Bu mektubu sana yazıyorum anne 

Dün sevdiğimle ayrıldık 

Son mektubuymuş bana yazdığı 

Bir daha yazmayacakmış 

Demek sevda ayrılığa bir ay dayanırmış 

Ve asker ocağında terkedilmek de varmış 

Bu mektubu sana yazıyorum anne 

Bu gün doğum günüm 3 Aralık 

Ve şafak karanlık 

3-5 nöbetindeydim dün gece 

Bir şarjörün boşluğunda içtim son sigaramı 

Ve yorgan gibi üstümü örttü kar siperde 

Sabaha karşı biraz içim geçmiş 

Hayalin gözümün önüne geldi anne 

Kızkardeşimi de verdiğinden beri sevdiğine 

Bir ben bir de sen kaldın geriye 

Üzülme anne üşümüyorum 

Bekliyorum elim tetikte 

Bekliyorum memleketi ve seni 

Ve artık beklemiyorum beni beklemeyen sevdiğimi 

Beklemiyorum yüreğimi ve aşkımı 

Soğuk siperde yalnız bırakan sevgiyi 

Ve bekliyorum anne elim tetikte 

Eğer girerse menzile vurup öldüreceğim 

Hem aşkı hem sevgiyi 

Geçen gece karakolu bastılar 

Kurşunlar yağmur gibi yağdı üzerimize 

Garip gelecek belki sana ama 

Ortalık bayram yeri gibi oldu anne 

Biliyormusun o an hiç korkmuyorsun 

Herkes kendini bir sipere atıyor 

Ve gecenin karanlığında kurşun yerine 

Işıl ışıl yıldızlar yağıyor sanki üzerimize 

Ve ölüm bile aklımıza gelmiyor anne 

Canlar canlar gidiyor 

Gidiyor canlar 

Ve kimbilir ne zaman bahar', 'O elinde tuttuğun zarf  bir ihanet anında örülmüştür  Ve zarfın içindeki kağıt  er mektubudur görülmüştür  Doğum günüm bu gün 3 Aralık  Ve ş...', ARRAY['Türk Edebiyatı','Şiir','Uğur Arslan']::text[], 8.5, '{"poet":"Uğur Arslan","poet_slug":"ugur-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/er-mektubu-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evet, İsyan', 'evet-i-syan-i-smet-ozel-dimrf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Demirden sağnaklar altında uyur sevdiğim

göğsünde hazin ayak izleri eski Şubatların

onu yaralar kıpırdatıyor

ve o sertelmektedir yaralardan

kasıklarına boşalmaktadır nal sesleri 

saçları bukleli bir çocuğu öperek uyandıran

içimize güneşler bırakan nal sesleri. 

Keserle yontulmuş bir ağzı var sabahın

varınca bayrakları, marşları duyuyorum

başım çılgınca sarsılan dallarla uğraşıyor

durup dineliyorum bütün taframla

bütün taframla, bütün yumruklarım, bütün

hantal yüreklerin olduğu orda.

Kesik kolları var aşkın

döl ve inat barındıran.

Hırpanî bir okşayışla akşam

yanaşınca çocuklara

ben karakavruk yüzümün arkasında

kırbaçlayarak büyüttüğüm ağrıyı bırakıyorum

bana ne çerçilerden, çerilerden, kullardan

halksa kal''am onu kal''a kılan benim

boşanır damarlarıma yılların kahraman gürültüsü

çünkü kavganın göbeğidir benim yerim.

Ay vurunca çatlatır göğsümdeki mahşeri

çünkü kavganın göbeğidir benim yerim

canlarım, kollarında Parti pazubentleri

dik başlar, erkek haykırışlarla

göndere, en yukarlara çekiyorlar

en yukarlara çatlıycak kadar aşkî yüreklerini.

Yıllardır çocuk başları akıyor yamacımızdan

yıllardır balçıklı bir hayvan çeperlerimizde

kentlimiz cebinde cinayet fotoğraflarıyla sofraya oturuyor

köylü  -biraz sessizlik-  ne tuhaf bir kelime? 

Asfalt yakıyor genzimi

asfalt adamlarını topluyor aramızdan

yıkılıp omuzdaşlarının seslerine

yıkılıp bir boran içinde toplayarak çiçeklerimi.

Ben merd-i meydan

yani toprağın ve kanın gürzü

güllerin bin yıllık mezarı bendedir

yukardan bakarım efendilerin pusatlarına

insanların bütün sabahlarını merak ederim

gök hırpalanmaktadır merakımdan

ıtır kokan benim yumruklarımdır

benim kavgamdır o, aşk diye tanınan.

Alanlara çok bilenmiş yüreğim alanlara

vurulsun kösleri şu gâvur sevdamızın

vursun isyanın bacısı olan kanım karanlığa

Zülküf de vursun.

Yüzüne ay kırıkları çarpıp uyansın sevdiğim.', 'Demirden sağnaklar altında uyur sevdiğim göğsünde hazin ayak izleri eski Şubatların onu yaralar kıpırdatıyor ve o sertelmektedir yaralardan ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/evet-isyan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamadın Sen', 'yasamadin-sen-ahmet-kaya-ip9s8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensiz geçmiyor bu günler biliyor musun

Yüreğine beni, beni soruyor musun

Öyle yalnız kaldım biliyor musun

Türküler söyledim sana duyuyor musun

Yıllar oldu oralardan çıkamıyorsun

Bağlanmış elin ayağın kaçamıyorsun

Bir kuş oldun gökyüzünde uçamadın sen

Nehir oldun, ırmak oldun taşamadın sen

Çocuk oldun sokaklarda oynamadın sen

Doğdun da büyüdün ama yaşamadın sen', 'Sensiz geçmiyor bu günler biliyor musun Yüreğine beni, beni soruyor musun Öyle yalnız kaldım biliyor musun Türküler söyledim sana duyuyor mu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kaya']::text[], 8.5, '{"poet":"Ahmet Kaya","poet_slug":"ahmet-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yasamadin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıkta', 'karanlikta-ahmet-kaya-fk766', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akşam olur karanlıklar çökende

Devriyeler adım, adım gezen de

Kar kaplamış solmuş güller gören de

Sarılıp dallarına öpesim gelir.

San ki gökten kar yerine kan yağıyor

Kar altında üşümüş bir çocuk ağlıyor

Yaşlı gözler ile bana bakıyor

Akan gözyaşını içesim gelir.

İşte böyle karanlıklar çökende

Devriyeler adım, adım gezen de

Yar uykuda ben yine pencerem de

Doğacak güneşi göresim gelir.', 'Akşam olur karanlıklar çökende Devriyeler adım, adım gezen de Kar kaplamış solmuş güller gören de Sarılıp dallarına öpesim gelir. San ki gök...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kaya']::text[], 8.5, '{"poet":"Ahmet Kaya","poet_slug":"ahmet-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/karanlikta-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gri', 'gri-sule-aydemir-wirxd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hangi kitapları okursun diyor beriki

öteki gömüyor yaşamını kitaplara

anlatıyor hayatını 

anlıyor dinliyor beriki

fark ediliyor dinleniyor olmak kendini 

başka kitaplarda yazarlarda

kaldırıp başını bakıyor 

gözlerde aşk başlıyor 

nereden nasıl gelinmiş bu yere

binlerce hüsran binlerce beklenti

bir bir ezilip içinde büyütmüş adam ve kadını

-en son ne zaman aşık olmuştum 

soruyor zamana beriki öteki

zaman diyor -yıllar var belki

bir ying bir yang 

vardı nasıl gri olunmuştu

beyaz kim kim siyahtı

gözlere çizildi resmi 

yüreğe kopyalandı yeniyetme duygular

yaşanılmışlığında yaşlı duyguların', 'hangi kitapları okursun diyor beriki öteki gömüyor yaşamını kitaplara anlatıyor hayatını  anlıyor dinliyor beriki fark ediliyor dinleniyor o...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gri-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Seni Seviyor', 'o-seni-seviyor-bekir-mutlu-gokcesu-rxi38', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir tebessümsen dudaklarında

Ve bir parıltıysan gözlerinde

Ve hiç kıyamıyorsa sana

O seni seviyor', 'Bir tebessümsen dudaklarında Ve bir parıltıysan gözlerinde Ve hiç kıyamıyorsa sana O seni seviyor...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/o-seni-seviyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuru Ayaz', 'kuru-ayaz-naime-erlacin-t9wvq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'avazım oldu şiir

savunmasız çığlıklar

dost dergahında niyazdım

sevda bağında naz

durmadı 

susmayı bilmedi çileli saz

şiire yazdım gönlümün pasını

yaz’ımla güz’ümle şiire farzdım

dönüp arkama baktım da şöyle

“hiç”mişim meğer! 

henüz pek az’dım

safi kuru ayaz! 

(10 Temmuz 2003)', 'avazım oldu şiir savunmasız çığlıklar dost dergahında niyazdım sevda bağında naz durmadı  susmayı bilmedi çileli saz şiire yazdım gönlümün p...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kuru-ayaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trafik', 'trafik-bekir-gedikoglu-p5hxb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yayaların, arabaların, uçakların seyrüseferlerine derler TRAFİK

Bilirsiniz trafikte vardır üç ışık

Çitayı görmüş karaca gibi zınk diye duracaksın, kırmızı ışıkta

Taarruza kalkacak asker gibi hazırlanacaksın sarı ışıkta

Mahmuz yemiş at gibi koşacaksın yeşil ışıkta

HAA! 

Bu kurallara uymadığında

Neler,  neler gelecek  bak şu cahil başına...

Hız tahditlerine uymayan Otobüs şarampole yuvarlanınca

Otuz yıl kullandığı bu araç döndü hurdaya

25 yolcu öldüğünü okudum gazete başlıklarında

Savaşa giren ordunun başına, gelmez bu kaza

Suçu yükledik yine Azrail’e, işimiz kaldı yine  Allaha

“Karşıdan gelen aracı tam görmeden sollama “

Söylediğim bu kurala  uymamazlık ta yapma

Sollama yapılmaz levhaları varsa yol kenarlarında

Sakın, sakın sakın ha, sollamaya başlama

Fecaat istiyorsan, sana ve arabana

Yol senin koçum!  ÖLÜM yarışına başla

Kırmızı ışıkta durmayan araba, geldi yolun ortasına

Kalbinde korku yok, akılda mı yok bu adamda? 

Yandan hızla gelen kamyon, akılsız araçla geldi kafa kafaya

Şaşırmayan kalmadı, oluşan bu kazaya

İnsanlarda,  araçlarda gidecekler hurdaya

Sarhoş olunca hiç binilir mi otomobile? 

Meraklı mısın adam?  sen cennete gitmeye! 

Hiç izan kalmadı mı artık araç üstünde? 

Eğitimciler nerede?  ekabirler nerede? 

Keskin viraja hızlı girilmez

Limit hızda girmesen, bu dönemeçler  şoförleri affetmez

KESKİN VİRAJ”  levhası her şoföre çok bakar

İkazlarına uymayanların inan canını yakar

İşte...! ! ! 

 Almanya’dan gelmiş Giresun’a kadar

Tirebolu’ya 2 Km var

Kayaların  üzerinde ters düşmüş Almanya plakalı bir araba

Araçta 2 ceset,  kavuşmuş mevlasına

Cıyak, cıyak ağlayan 9 aylık bir yavru,  kalmış arabada

İzan, eğitim olmadan

Hızlar tahdit olmadan

Bakımlı araçlar almadan

Kırmızı ışıkta durmadan

Trafik levhalarına aldırmadan

Allah’tan hiç korkmadan

Hiç kimse sağ çıkamaz, bu hengamedan

Ankara,09.09.2203', 'Yayaların, arabaların, uçakların seyrüseferlerine derler TRAFİK Bilirsiniz trafikte vardır üç ışık Çitayı görmüş karaca gibi zınk diye durac...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/trafik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Bir Yerdeyim ki', 'oyle-bir-yerdeyim-ki-hasan-huseyin-korkmazgil-8axfm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öyle bir yerdeyim ki

ne karanfil ne kurbağa

Bir yanım mavi yosun

Dalgalanır sularda

Dostum dostum

Güzel dostum

Bu ne beter çizgidir bu

Bu ne çıldırtan denge

Yaprak döker bir yanımız

Bir yanımız bahar bahçe

Öyle bir yerdeyim ki

Bir yanım çığlık çığlığa

Öyle bir yerdeyim ki

Anam gider Allah Allah

Öyle bir yerdeyim ki ne karanfil, kurbağa

Öyle bir yerdeyim ki 

Bir yanım mavi yosun çalkalanır sularda

Dostum, dostum güzel dostum

Bu ne beter çizgidir bu

Bu ne çıldırtan denge

Yaprak döker bir yanımız

Bir yanımız bahar bahçe

Öyle bir yerdeyim ki bir yanım çığlık çığlığa

Öyle bir yerdeyim ki

Anam gider Allah, Allah dölüm düşmüş sokağa.', 'Öyle bir yerdeyim ki ne karanfil ne kurbağa Bir yanım mavi yosun Dalgalanır sularda Dostum dostum Güzel dostum Bu ne beter çizgidir bu Bu ne...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Korkmazgil']::text[], 8.5, '{"poet":"Hasan Hüseyin Korkmazgil","poet_slug":"hasan-huseyin-korkmazgil","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/oyle-bir-yerdeyim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nidalı Yolculuk', 'nidali-yolculuk-cemil-neseliler-k7wtm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'nidalarla başladı sabah... 

giysilerini giymeye fırsat bırakmadı bekleyenlere... 

saf halinizle binin dedi hadi iskelemden... 

demir almaya az kaldı... 

vira vira sesleri yükseldiii.... 

ne yelken vaarr....ne motor...ne dümenn....ilginç mi ilginççç.. 

yolu biliyor....tam yol ileriiii..... 

dalgalar yeter banaa....onlar öteler beni ilerilereee....öteliyor daaa... 

hele şu ilk adayı döneyimm....ardı açık denizzzz.... 

güneş doğuşundan beri nazlıca yükseliyor... 

bulutlar hepsi saygı duruşunda... 

gölge etmemeye yemin etmişler... 

dalgalar sesi duydular ya...! :  tam yol ileriiiii.... 

etmiyorlar hiç itaatsizlik... 

vuruyor bordaya olabildiğincee... 

duran kiiimmm... 

şıpırtılar saçlarımı ıslatıyor... 

rüzgarsa tenimii.... 

nemli mi nemliii... 

durulur mu karşısında...durulmaz elbettt...devaammm.... 

yunuslar var sadece yoldaş... 

bir de üstümde martı....tek... 

açıklara yolculuktayımm....seyerandayımm.... 

terlediğim yaştayımm... 

yüklerimin hepsi güvertede... 

emin mi eminn... 

yüreğimin atışı derin mi derinnn... 

ulaşmada her çarpışta... 

sevdiğine yarine... 

elini uzatmış.... 

çağırıyor beni sakin bir ses... 

katıldım deryaya tek nefes... 

yelek de sal da istemem... 

değil bu süfli bir heves... 

bırakmışım kendimi suya... 

ruhum yüreğim ıslak... 

bilmesin herkes...', 'nidalarla başladı sabah...  giysilerini giymeye fırsat bırakmadı bekleyenlere...  saf halinizle binin dedi hadi iskelemden...  demir almaya ...', ARRAY['Türk Edebiyatı','Şiir','Cemil Neşeliler']::text[], 8.5, '{"poet":"Cemil Neşeliler","poet_slug":"cemil-neseliler","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/nidali-yolculuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Hüzünlü Bir İsyan...', 'huzunlu-bir-i-syan-naime-erlacin-o4nxz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'günlerden nedir bugün

mevsimlerden hangisi 

malûmatım yok! 

ancak biliyorum 

iklim hüzünden

şiir kucaklıyor beni

söz perileri tutuyor elimden 

dönüyor dönüyor da 

ebedi bir girdapta ölüyoruz

aykırı bir ''ah'' çalınıyor kulağıma

kaderin sesi bu 

bir ses ki 

isyanımı inleyen

(09 Temmuz 2003)', 'günlerden nedir bugün mevsimlerden hangisi  malûmatım yok!  ancak biliyorum  iklim hüzünden şiir kucaklıyor beni söz perileri tutuyor elimde...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/huzunlu-bir-isyan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Gönlüm', 'su-gonlum-guven-aktas-43bfk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Su gönlüm cok sevdi ama sevilmedi, 

Bir fidan gibi göge yükseldi ama, 

Kimse budamadı, temizlemedi eski dalları

Su gönlüm cok sevdi ama, 

Sevdigini söyleyemedi…

Delicesine sevdi su gönlüm, 

Parçalarcasına attı yüregim her gördügünde, 

Taş degilki yüregim söküp atayım

Baska bir tas koyup hayata bastan baslayayım, 

Su gönlüm cok sevdi ama, 

Sevdigine kavusamadı..

Gözlerim cok güzel gördü ama, 

Sende takılı kaldı, 

Dilim cok isim söyledi ama, 

Senin kini üstüne kazıdı, 

Ellerim cok eller tuttu ama, 

Seninkilere kavusamadı, 

Gözlerim cok yas döktü ama, 

Seninkileri durduramadı, 

Bedenim cok acı cekti ama

Seninkinin tarifi bile bulunamadı, 

Su gönlüm seni sevdi ama

Beni sevmedigini anlayamadı', 'Su gönlüm cok sevdi ama sevilmedi,  Bir fidan gibi göge yükseldi ama,  Kimse budamadı, temizlemedi eski dalları Su gönlüm cok sevdi ama,  Se...', ARRAY['Türk Edebiyatı','Şiir','Güven Aktaş']::text[], 8.5, '{"poet":"Güven Aktaş","poet_slug":"guven-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/su-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Beni,', 'sen-beni-guven-aktas-aspdz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sevda atesiyle yakıp gönlümü, 

Ucmak istedim kollarında, 

Nerden bilecektim ki, 

Yakıp bütün bedenimi, 

Gömecegini yasarken diri diri, 

Bir masalla hareket ettim, 

Nerden bilirdim ki prenses devrinin bittigini, 

Öpüp dudaklarından prensesin, 

Sadece hayat vermek istedim, 

Nerden bilirdim ki masal devrinin bittigini, 

Alev gibi bakıslarıyla, 

Yakıp bütün bedenimi, 

Ve ruhumu alıp, 

Nerden bilirdim ki gidecegini, 

Tutsam ellerini, 

Gitme dur diye aglasam, 

Geceler boyunca feryatla karısık

Göz yasları akıtsam..

Gitmekten vaz gecermisin, 

Elimi uzatsam tekrar ellerini verirmisin, 

Umutlarımı tekrar diriltirmisin, 

Bir yıldız gibi doğup geceme, 

Sabahım olurmusun, 

Sen beni ömür boyunca, 

Sen beni benim oldugum gibi, 

Sen beni sadece seni sevdigim gibi

Sen beni sevebilirmisin benim seni sevdigim gibi…..', 'Bir sevda atesiyle yakıp gönlümü,  Ucmak istedim kollarında,  Nerden bilecektim ki,  Yakıp bütün bedenimi,  Gömecegini yasarken diri diri,  ...', ARRAY['Türk Edebiyatı','Şiir','Güven Aktaş']::text[], 8.5, '{"poet":"Güven Aktaş","poet_slug":"guven-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sen-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostumsun Diyor', 'dostumsun-diyor-guven-aktas-2nwtg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben sana seviyorum dedim, 

sen dost kalmamızı istedin, 

Söyle bahar tenli, söyle

Kardesligi olurmu sevenlerin, 

Yarim demek istiyorum sana, 

Elini tutup sarılmak istiyorum, 

Aglamak istiyorum dizine kapanıp, 

Sen ise dost kalalım istiyorsun, 

Dünyada bu büyük acıyı, 

Cekecek yürek acaba varmı, 

Sevenlerin kardes olması, 

Hangi kitapta yazılı, 

Allahım nedir bu cilem

Sevsem bile sevilmemem, 

Gözlerine bakıp seviyorum desem, 

Dostumsun  diyecek bahar tenli, 

Soldurdu benzimi, 

Yıkıp kül etti ümitlerimi, 

Sanki bir zarfa koyup hayallerimi, 

Adresi olmayan yere gönderdi, 

Sanki beni yasarken, 

Gömdü diri diri, 

Dostlugunu  Kabul edemem dedim, 

Ne selam ver nede ismimi anmanı isterim, 

Seni kırmak en son ihtimalim, 

Dostunu sevecek kalles degilim,', 'Ben sana seviyorum dedim,  sen dost kalmamızı istedin,  Söyle bahar tenli, söyle Kardesligi olurmu sevenlerin,  Yarim demek istiyorum sana, ...', ARRAY['Türk Edebiyatı','Şiir','Güven Aktaş']::text[], 8.5, '{"poet":"Güven Aktaş","poet_slug":"guven-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dostumsun-diyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giremessem Yüregine', 'giremessem-yuregine-guven-aktas-b1ro8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağlayamam herkesin içinde bu hasret yüzünden, 

Bir köşede yere çömelir ağlarım gizlice, 

Kimseye göstermem göz yaşlarımı, 

Akar gider gönlüm yaşlarıma karışıp, 

Belki, belki  bir pınara karışır, 

Gâm payı bırakılmış  bardak içinde Sana gelir, 

Kana kana içersin, göz yaşlarımla karışmış, 

Hüzün dolu ve Aşk kokulu suyu...

O zaman dolaşırım vücudunda, 

Belki o zaman anlarım beni sevip sevmediğini, 

Hayalimi göremessem yüreğinde

Unutulmak acı verir bedenime, 

Cehemdemde yanmak değil, 

Unutulmak kül eder beni, 

Ama, 

Hiç giremeden vücudunun derinliklerine, 

Elin bir şeye  çarpıp suyu yere dökerse! 

İşte o zaman kâhrolurum sevdiğim, 

Giremediğimde  yüreğine, , , ,', 'Ağlayamam herkesin içinde bu hasret yüzünden,  Bir köşede yere çömelir ağlarım gizlice,  Kimseye göstermem göz yaşlarımı,  Akar gider gönlüm...', ARRAY['Türk Edebiyatı','Şiir','Güven Aktaş']::text[], 8.5, '{"poet":"Güven Aktaş","poet_slug":"guven-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/giremessem-yuregine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçma Zamanı', 'kacma-zamani-mehmet-erdogdu-335uy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaçmalı artık bu şehirden

Yenildikçe bahar

Legalleştikçe

Korsan aşklar

Kaçmalı artık bu şehirden

Hayatı ikiletmeden

İğreti hasretleri yüklenip

Düşmeli yollara yeniden

Kaçmalı artık bu şehirden

Sustalı yüreği

Kandan silerek

Gitmeli gölgenin peşinden...', 'Kaçmalı artık bu şehirden Yenildikçe bahar Legalleştikçe Korsan aşklar Kaçmalı artık bu şehirden Hayatı ikiletmeden İğreti hasretleri yüklen...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Erdoğdu']::text[], 8.5, '{"poet":"Mehmet Erdoğdu","poet_slug":"mehmet-erdogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kacma-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz Ve Yalnız', 'sonsuz-ve-yalniz-nuri-can-6gqka', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Trenler gelip geçiyor

usumun uzayan raylarında lanetli

ağır bir ağrıyı taşıyor bedenime yıllar

kalbimin sızısında gam

dilimin yakarışında ürperiyor yapraklar.

usul usul yağmurlarda gözlerim

ellerim fırtınalarda kopmuş dal

dillerim lal

bitkinim.. ve yurtsuz

‘uy hawar’

yaralıyım

bakışlarımda yavrusu vurulmuş bir ceylan inliyor

melanet yağmurları iniyor üzerime

suların buz kestiği yerdeyim

rüzgarın acı kestiği yerde

yüreğine tutunduğum bunu bilmiyor.

dalları tutuşmuş bir ormanda

sevgilime yazdığım bütün dizeleri yakıyorum şimdi

bütün umutları terkediyorum bir bahardan ödünç aldığım

gençliğim yarım kalmış bir şiir değil miydi zaten? 

ve kanayan bir kalem değil miydi kalbim? 

bırak ömrümün bütün dallarını silkelesin hayat 

… uy hawar 

bu günde gelmedi beklediğim bahar 

gülmedi karabahtım

kalbimin üstüne üstüne yağıyor kar

uçup gitti kuşlar çoktan.

nereye saklanır içimdeki incinmişlikler

inince gözlerimde ince bir sızı

ve süzülünce yanağımda bu gam müziği

…uy havvar güz geldi

solan çiçeklerime su bekledim

yanan yüreğime kar

düşmedi bir damla yağmur

gelmedi beklediğim bahar 

kirpiklerim yaralı yolcuları gözlerimin

sesim uçurumlara düşmüş çığlık

nereye uçsunki,

kalbimdeki kuşun kanadı kırık.

son trende kalktı boşaldı istasyonlar

kimsenin gelmediği yerdeyim

acıların bitmediği yerde

güz geldi, gelmedi beklediğim tren

yoruldum bunca ağrıyı taşımaktan

sevgiye tanımlar aramaktan

bir serseri gibi yaşamaktan yoruldum

yoruldu yüreğim, beynim, dilim, ellerim, gözlerim

… uy hawar

bu günde doğmadı güneş 

dağlar erimedi

gelmedi beklediğim bahar

/', 'Trenler gelip geçiyor usumun uzayan raylarında lanetli ağır bir ağrıyı taşıyor bedenime yıllar kalbimin sızısında gam dilimin yakarışında ür...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/sonsuz-ve-yalniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar', 'yar-mehmet-ali-kepez-lnctq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bahar çatlayınca mayıs ayında

	Dört duvar içinde durulurmu yar

	Kalırmı demişsin bizim yaylada

	Hastaya hiç ilaç sorulurmu yar

	Sen bàri yerime dağlarda dolan

	Gurbette ömrùmù eyledim talan

	Kim derse doyulan''yer''vatan''yalan! 

	Hasretlik yarası sariımıyor yar', 'Bahar çatlayınca mayıs ayında 	Dört duvar içinde durulurmu yar 	Kalırmı demişsin bizim yaylada 	Hastaya hiç ilaç sorulurmu yar 	Sen bàri yer...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yar-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elle *', 'elle-engin-kahraman-6oh21', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'şuh kahkahalar gibi umarsız

durağan kadavra gözyaşı

gözleri yaz bulutları

yüreği kötürüm arkadaşı

saçlarına yuva 

ayaz yelleri

dışarıda meryem

dışarıda kilise

içeride çarmıh

içeride hadise

arada mızmız havari

çivi dağıtır durur

kan bulaşığı elleri

* french', 'şuh kahkahalar gibi umarsız durağan kadavra gözyaşı gözleri yaz bulutları yüreği kötürüm arkadaşı saçlarına yuva  ayaz yelleri dışarıda mery...', ARRAY['Türk Edebiyatı','Şiir','Engin Kahraman']::text[], 8.5, '{"poet":"Engin Kahraman","poet_slug":"engin-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/elle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Isınmak için', 'isinmak-icin-gunay-aktag-0qgh7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu akşam seni düşünüyorum

Yalnız odamda, gözlerim kapalı

Hayalinle hayalimi 

Buluşturuyorum durmadan

Isınmak için...

Dışarıda lapa, lapa kar yagıyor

Odamsa soguk, 

Bense hep seni, 

hep seni düşünüyorum seni

Isınmak için...

Aklımda bir kelime, 

Dudaklarımda ise hece, hece

Hep ismini anıyorum durmadan...

Isınmak için...

Bu akşam seni düşünüyorum

Bıkmadan, usanmadan

Hayalinlede olsa 

Isınmak için....

Fırtınalı bir gece rüzgarsa soğuk

Ellerim titriyor, bedenim üşüyor

Bedenim sana hasret...seninle sevişmek için

Benliğim hep seni istiyor seni, 

Seninle ısınmak için

Bu akşam seni düşünüyorum seni

Yalnız, yalnız ısınmakn için...

Isınmak için.....', 'Bu akşam seni düşünüyorum Yalnız odamda, gözlerim kapalı Hayalinle hayalimi  Buluşturuyorum durmadan Isınmak için... Dışarıda lapa, lapa kar...', ARRAY['Türk Edebiyatı','Şiir','Günay Aktağ']::text[], 8.5, '{"poet":"Günay Aktağ","poet_slug":"gunay-aktag","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/isinmak-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyanlardayım', 'i-syanlardayim-murat-demir-yjwzf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Babalanıp bre haddini aşma

Gün gelir sanada tokat atılır

Gücüm var sanarak şaşırma şaşma

Yoksa anlamadan kıta’n sarsılır

Sağa sola saldırırken it gibi

Salyaların dökülüyor etrafa

Sanki aç kalmışsın dağda kurt gibi

Bilesinki bize gelmez bu cefa

Ben bilirim beni kızdırma sakın

Kuşanır çıkarım er meydanına

Öcünü alırım senden Irak’ın

Bi tarih olursun dünya adına

İyiki paran var kağıt parçası

Altın olsa benim için ne yazar

Asla boyun eğmem gelse paşası

Gün gelir bu yerden kalkar bu pazar

Süleymaniye’de yaptıklarının

Hesabını vereceksin zamanla

Dün bugün ve yarın aldıklarının

Karşılığı çoktur, olmaz paranla

Bu nasıl müttefik yaptığına bak

Düşündükçe çıldırasım geliyor

Yat komutu verip Mehmede tokat

Atanları yok edesim geliyor

Hava atmıyorum o gün gelecek

Hiçbir gücün sonu sonsuz değildir

Biz yada başkası dünya görecek

Barbarlığın geleceği bellidir

Murat der yazarım rahatsızlıktan

Rahatsızlık neki isyanlardayım

Memnun olan varmı böyle dostluktan

Varsa anlatsında rahatlayayım', 'Babalanıp bre haddini aşma Gün gelir sanada tokat atılır Gücüm var sanarak şaşırma şaşma Yoksa anlamadan kıta’n sarsılır Sağa sola saldırırk...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/isyanlardayim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir Gibi', 'bir-siir-gibi-bekir-gedikoglu-2zkpf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün, bir ay, bir yıldır

Bin yıldır

Gün suratımı soldurur

Yaz ve kış bir arada 

Güzeller beni düşündürür

BİR ŞİİR GİBİ

Hepsi acı, hepsi vesvese

Kara, kara düşündürür

Merdivenlerden inerken

Bir tatlı bakış, bir tatlı ses

Hücuma geçen acılarıma

İndirirlerdi müthiş bir darbe

Hepsi geldi ve geçti

BİR ŞİİR GİBİ

Bir akşam çok güldüm

Hem de katılırcasına

Sanki bu bir isyan dı

İçimdeki acılara

Acı, acı, çok acı

Gülüşler peydahlandı

Suratımın taa ortasında

O ne gülüş,  o ne surat? 

BİR ŞİİR GİBİ

Bir gün bir akşam

Elimde kalem

Karşımda Babam

O söyledi ben yazdım

Bir saatte bin yıllık

Bir gündem

Mektup elimde, sözleri içimde

Koskoca adamdım

Utanmam olmasa ağlayacaktım

Hem belki de hiç durmadan

BİR ŞİİR GİBİ

Yazılan mektup uzağa gider

Gurbettekilere selamlar eder

Bir yara vardı o gün, bugün içimde

Siliniverdi mektup elimde

Ağlayacaktım son satırında

Hiç utanmadan,  hiç sıkılmadan

BİR ŞİİR GİBİ

Güneşi özledim her gün ve her an

O ne iştahtı o ne umuttu

Bir heves ile koşardım pencereye

Tıpkı kuş gibi

Fakat ne gördüm! 

Perdeler açılmaz

Asılırdım perdelere kornişler kırılacak

Bağırırdım o anlarda, krişler koparacak

İşte ben buydum amma...

Çizgi, çizgi karanlıklar girerdi içeriye

TIPKI BİR ŞİİR GİBİ

Ekmeğim olmasa bile, neşem eksilmezdi hiç

Yüreğimde

Kolay mı açlık? 

Dile kolay bee! 

Hiç düşünmedim o anı ve o günleri

Var o anılardan yüreğimde

Birkaç topal söz izi

TIPKI BİR ŞİİR GİBİ

Tüm bu acılara hiçbir şey demiyorum

Gün geçtikçe o anılardan tecrübe ediniyorum

Varsa da azıcık bir burukluk, bir kırıklık

Zaman, zaman yüreğime inse de

Sonuç olarak; 

BİR ŞİİR GİBİ

Bakmıyorum artık 

Eski acılara ve kayıplara

Özlem ile sarılıyorum

Gelecek umutlara

TIPKI BİR ŞİİR GİBİ

BİR ŞİİR GİBİ

Ankara,28 Ocak 1974', 'Bir gün, bir ay, bir yıldır Bin yıldır Gün suratımı soldurur Yaz ve kış bir arada  Güzeller beni düşündürür BİR ŞİİR GİBİ Hepsi acı, hepsi v...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/bir-siir-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir Gibi-II', 'bir-siir-gibi-ii-bekir-gedikoglu-2xatb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '3 gün 3 sabah

Horozlarla kuşlardan

Önce kalktım

Bir şiir gibi uyandım

Daha güneş konmamıştı

Dağlara, yollara, gecekondulara

Hatta, hatta

Gökdelenlerin tepesine bile

Ben ise sokak, sokak dolaştım

Saatlerce

Gök, dağ, yol, şehir

Bir şiir gibiydi

Günlerce, 

Akla gelmez acıları, 

Yudum, yudum yudumladım

Dereler gibi çağladım, 

İçin, için ağladım

Yıllar geçtikçe 

Zamanla yok oldu

Gene de hepsi 

Bir şiir gibiydi

Hoyratlıklar, küfürler

Geldi geçti sinemden

O dert küpü

İsyan nedir bilmiyordu ki

Tümünü kabullendi

Bir şiir gibi

Ankara,07.04.1974', '3 gün 3 sabah Horozlarla kuşlardan Önce kalktım Bir şiir gibi uyandım Daha güneş konmamıştı Dağlara, yollara, gecekondulara Hatta, hatta Gök...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-siir-gibi-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizli Sokakları', 'denizli-sokaklari-filiz-kurun-r9k9q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugünlerde içim sıkılıyor

Gözyaşlarım benden kaçar oldu

Gönlüm dertle hüzünle doldu

Artık sen yoksun

Ne yakınımda ne uzağımda

Seni aradım köşe bucak

Yollarda, kaldırımlarda

Sen  yoktun 

Ne yakınımda ne uzağımda

Bulamadım ne seni ne de hayalini

Denizli sokaklarında.

(23.07.02)', 'Bugünlerde içim sıkılıyor Gözyaşlarım benden kaçar oldu Gönlüm dertle hüzünle doldu Artık sen yoksun Ne yakınımda ne uzağımda Seni aradım kö...', ARRAY['Türk Edebiyatı','Şiir','Filiz Kurun']::text[], 8.5, '{"poet":"Filiz Kurun","poet_slug":"filiz-kurun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/denizli-sokaklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lİman', 'li-man-filiz-kurun-9i0ou', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yoğun duygular içinde  limana doğru sürükleniyorum

Beni bu havalar mahvetti dermişcesine sallanıyorum

Tam limana yaklaştım diyorum

Gördüğüm liman değil hayal imiş

Kahroluyorum

Dalgalar eskimiş bedenime vuruyor

İçime su çekmişim

Bazı yerlerim delik deşik olmuş

Ben hala o hayal limanın gerçeğini arıyorum

Görüyorum yaklaştım zannediyorum

Tam demir atacağım kayboluyor

Liman ne olur benden kaçma

Aç, al beni o sımsıcak koynuna.

(27.04.01) 



(27.04.01)', 'Yoğun duygular içinde  limana doğru sürükleniyorum Beni bu havalar mahvetti dermişcesine sallanıyorum Tam limana yaklaştım diyorum Gördüğüm ...', ARRAY['Türk Edebiyatı','Şiir','Filiz Kurun']::text[], 8.5, '{"poet":"Filiz Kurun","poet_slug":"filiz-kurun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/liman-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak', 'toprak-filiz-kurun-glbn4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözündeki ışıltı

Yüzündeki ben

Bir ben severim seni  bir ben

Birbirimizi yeni bulmuşken

Ayırdı bizi

Bizi meydana getiren toprak

Sen şimdi ayaklar altında

Ben senin üstünde geziniyorum

Seni öyle sevmişim ki

Bir an önce  kavuşalım diye

Toprakla didiniyorum

(15.06.01)', 'Gözündeki ışıltı Yüzündeki ben Bir ben severim seni  bir ben Birbirimizi yeni bulmuşken Ayırdı bizi Bizi meydana getiren toprak Sen şimdi ay...', ARRAY['Türk Edebiyatı','Şiir','Filiz Kurun']::text[], 8.5, '{"poet":"Filiz Kurun","poet_slug":"filiz-kurun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/toprak-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua', 'dua-guven-aktas-zzgfr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duydum ki ellerden beni bırakıp gitmişsin

O güzel günleri bir kalemde silmişsin

Ne bir not ne bir selam göndermişsim

İşte buna dayanamadım….

Yanlız bırakıp gittin bir gece vakti

Elimden gelmedi bir şey seni göremedim

Belki bir gören olup mesaj gönderir dedim

Gören olmamış beni bırakıp gittiğini

Sanki bir mezara koydular sevgimi 

Üstüne tabutları çivileyip gittiler

Karartılar içinde düşündüm seni

Belki başıma gelip sandım ki dua eder', 'Duydum ki ellerden beni bırakıp gitmişsin O güzel günleri bir kalemde silmişsin Ne bir not ne bir selam göndermişsim İşte buna dayanamadım…....', ARRAY['Türk Edebiyatı','Şiir','Güven Aktaş']::text[], 8.5, '{"poet":"Güven Aktaş","poet_slug":"guven-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dua-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanları seyrediyorum', 'i-nsanlari-seyrediyorum-guven-aktas-lgj1f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsanları seyrediyorum

Çaresiz olanları

Bir lamba altında, 

Her gün yaşlananları, 

Kaderine küfür etmeyen

Ekmeğini yerden eşen

Kardeşliğe önem veren

Gerçek insanları, 

Mazlumun ahını almayanları

Fakirin kalbini kırmayanları

Yetimin hakkını savunanları

Delikanlı olanları

Her pisliği yapanları, 

Hayatında iyilik yapmayanları

Sevgiden yoksun yaşayanları, 

Suni insanları, 

Bu alemde kalleşlik  yapanları

Binlerce kişiyi işsiz bırakanları

Sevenleri ayıranları

İnsan kılığındaki canavarları, 

Düşünüyorum boşuna

Her kes gelmiş bu dünyaya

Kaşka bakkal gibi bu hayattında 

Veresiyesi  olsa', 'İnsanları seyrediyorum Çaresiz olanları Bir lamba altında,  Her gün yaşlananları,  Kaderine küfür etmeyen Ekmeğini yerden eşen Kardeşliğe ön...', ARRAY['Türk Edebiyatı','Şiir','Güven Aktaş']::text[], 8.5, '{"poet":"Güven Aktaş","poet_slug":"guven-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/insanlari-seyrediyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni çok seviyorum', 'seni-cok-seviyorum-guven-aktas-iqtid', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne olur konuş benimle son kez olsada, 

Duymak istediğimi söyle dudaklarının arasından, , 

Sadece sen konuş dursun bütün zaman! 

Şarkılar söyle sesizce sadece benim kulağıma, 

Belki, söyleyemeyeceksin bir daha! 

Senden çok şey istemiyorum sadece söyle bana, 

Beni düşünürken uykusuz kalıyormuydun geceler boyunca, 

Yoksa çok rahatmı yatıyordun seni seven yokmuşcasına, 

Seni bilmem ama ben her gece boyunca, 

Seni düşünüyorum, çok rahat uyuyorum hayaline sarılınca, 

Belki kendimi teselli ediyorum, kendimi adıyorum aşkıma, 

Ama senden çok şey mi istedim yıllar boyunca, , , , , 

Şimdi bırakıp gittin beni yanlız başıma, 

Bir daha gelmeyeceksin bu dünyaya, 

Ama seni hala görüyorum rüyalarımda, 

Ve o kelimeyi duymak istiyorum kendi kulaklarımla, 

Haykır bana seni seviyorum diye, 

Dağları deleyim bir çırpıda bakarak gözlerine, 

Gelip kurtarayım seni her neredeysen yaslayayım başını göğsüme

Ama,  nerdesin bilmiyorum artık yoksun yanımda, 

Unutma sakın  aşkım seni seviyorum, 

Her nefes aldığımda, 

Seni düşünüyorum her yastığa başımı koyuduğumda, , 

Ve yanına geliyorum her seferinde gözlerimi kapayınca, 

Çünkü seni çok seviyorum........', 'Ne olur konuş benimle son kez olsada,  Duymak istediğimi söyle dudaklarının arasından, ,  Sadece sen konuş dursun bütün zaman!  Şarkılar söy...', ARRAY['Türk Edebiyatı','Şiir','Güven Aktaş']::text[], 8.5, '{"poet":"Güven Aktaş","poet_slug":"guven-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seni-cok-seviyorum-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Oldum', 'asik-oldum-bekir-gedikoglu-w04n3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilmiyorum...

Geceleri uykusuz

Gündüzleri bir berduş

Yağmur altında çok gezen

Çılgın rüzgarlı havalarda yürüyen

Dağdaki karlar üstünde yatan

.....Bir Aşık Oldum

Ankara,  09.10.1977', 'Bilmiyorum... Geceleri uykusuz Gündüzleri bir berduş Yağmur altında çok gezen Çılgın rüzgarlı havalarda yürüyen Dağdaki karlar üstünde yatan...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/asik-oldum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam', 'babam-guven-aktas-3ow75', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşlanmıştı artık tükenmişti hayat onuda bitirmişti, 

Hastaneye yattı bir anda eridi bitti, 

Ölmek istemiyordu daha onun için erkendi, 

Çünkü daha oğlu dokuz yaşına girmişti....

Pazarlık yapamadı babam yaradanla, 

Rahmetli oldu eylül’ün yağmurlu bir sabahında, 

Yastığını almış hastaneden anam getirip koydu yatağına, 

Bir kelebek vardı, büyüktü babamın en sevdiği oda da, , , 

İnanamamıştım hiç bir zaman onun artık ekmek getirmeyeceğini, 

Köşeden görünce benim ona koşarak gidemeyeceğimi, 

Herkes baba derken benim boynum bükük yere düşeceğini, 

Bilemiyordum  onun artık gelmeyeceğini....

Büyüdüm geldim bu zamanlara babam yoktu yine arkamda, 

Yılmadan dualar ettim onun ruhuna, 

Görüyordu beni heryerde her zaman her ne yapsamda, 

Kızıyordu sanki mezarında her ağladığımda, 

Elbette bende eriyip biteceğim

Gözlerim deki ateşi kendim bile göremeyeceğim

Hakk’ın huzuruna çıktığım vakit

İşte o zaman babamı öpeceğim....', 'Yaşlanmıştı artık tükenmişti hayat onuda bitirmişti,  Hastaneye yattı bir anda eridi bitti,  Ölmek istemiyordu daha onun için erkendi,  Çünk...', ARRAY['Türk Edebiyatı','Şiir','Güven Aktaş']::text[], 8.5, '{"poet":"Güven Aktaş","poet_slug":"guven-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/babam-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu gece', 'bu-gece-guven-aktas-j4xlq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kan akıyor yaş yerine gözlerimden, 

Umutsuzluk hakim olmuş, mutlulukların yerine, 

Ümitsizlik kol geziyor penceremde., 

Sesini duyamadım ya hani  bu gece, , 

Hani neredesin? hangi yıldıza bakıyorsun, , 

Ayaz rüzgarların ortasında beni mi düşünüyorsun? 

Vefasızlıklarını unutupda yoksa benden

Af dilemek mi istiyorsun? 

Kader deyipte bu yaptıklarına, 

Avutma taş yüreğini sakın

Lanet olsun yalan sürüp baktığın bakışlarına, 

Bu gece seni düşünüp sarhoş olmayacağım....', 'Kan akıyor yaş yerine gözlerimden,  Umutsuzluk hakim olmuş, mutlulukların yerine,  Ümitsizlik kol geziyor penceremde.,  Sesini duyamadım ya ...', ARRAY['Türk Edebiyatı','Şiir','Güven Aktaş']::text[], 8.5, '{"poet":"Güven Aktaş","poet_slug":"guven-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-gece-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana birde...', 'bana-birde-guven-aktas-pijhw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gitti, bir daha ne aradı ne de sordu, 

Ümitlerim bir bir tükendi soldu, 

Hayattan aldıgım heves kursagımda durdu, 

Beni giderken ne aradı, nede sordu, 

Yardım ellerini bir bir geri cevirdim, 

Dostlarıma hakkında kötü söyletmedim, 

O bilir dedim nasılda sevmistim, 

Gittiginden beri aglamaklıyım…

Bana simdi bir sigara lazım, 

Bana simdi bir kadeh icki lazım, 

Bana simdi bir nester birde oksijenli bez lazım, 

Bana yoklugunda bir gönül lazım, sana verdigimin  yerine…

Senin adının ve hayalinin olmadıgı, 

Bana birde yanlızlık lazım, 

Seni tanımayan, 

Bana birde hayat lazım, 

Seni hic yaşamadıgım

Bana birde……….

Bosver be güzelim, 

Zaten bitti mürekkebim…….', 'Bir gitti, bir daha ne aradı ne de sordu,  Ümitlerim bir bir tükendi soldu,  Hayattan aldıgım heves kursagımda durdu,  Beni giderken ne arad...', ARRAY['Türk Edebiyatı','Şiir','Güven Aktaş']::text[], 8.5, '{"poet":"Güven Aktaş","poet_slug":"guven-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bana-birde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin?', 'nerdesin-tayfun-basdemir-sx2gy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Daha şimdiden özledim sensiz olmuyor...

Ayrılalı henüz birkaç saat oldu.

İnan bu ayrılık beni çok boğdu.

Gün bitiyor, akşam oluyor nerdesin? 

Günler haftalar geçmek bilmiyor.

Dilim başka kelime telafuz etmiyor.

Her geçen zaman bana eziyet ediyor.

Bahar bitiyor, güz başlıyor nerdesin? 

Yeter yaklaştım artık sonlarıma...

Yutkunamıyorum sen takıyorsun gırtlağıma...

Halen niye gelmiyorsun ki yanıma

Ömür bitiyor, ölüm yaklaşıyor nerdesin?', 'Daha şimdiden özledim sensiz olmuyor... Ayrılalı henüz birkaç saat oldu. İnan bu ayrılık beni çok boğdu. Gün bitiyor, akşam oluyor nerdesin?...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Başdemir']::text[], 8.5, '{"poet":"Tayfun Başdemir","poet_slug":"tayfun-basdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nerdesin-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Ülke Hepimizin', 'bu-ulke-hepimizin-ali-girgin-f97u8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneşi arıyoruz gündüz karanlığında, 

Güneşi arıyoruz masmavi gökyüzünün altında

Anadolu''nun dört bir yanında.

Kimimiz sağda, kimimiz solda, 

Kimimiz ortalarda dolaştık yıllarca.

Şunu çok iyi bilin ki! 

Hepimiz sevdalıyız bu topraklara.

Bir o kadar da umutsuz, 

Bakıyoruz gündüz karanlığında ufuklara.

Yorgun ve çaresiz.

Kendimiz için değil, 

Çocuklarımız için bir umut ışığı özlemimiz.

Ey Ankara! 

At şu üzerindeki ölü toprağını.

Gör artık dahili ve harici bedhahlarını.

Ne bu gaflet, nedir bu üzerimize çöken kabus, 

Dön de bir geçmişine bak, 

Ne mucizeler yaratmış bu ulus.

He he heyyt be! 

Selam olsun beş yüz bin cana.

Selam olsun iki yüz elli üç bin canla

Çanakkale''yi geçilmez kılanlara.

Ey Ankara! 

Hatırla 1920''lerin koşullarını.

Hatırla cepheye mermi taşıyan Ayşe''lerini Fatma''larını.

He he heyyt be! 

Selam olsun ayağı çarıklılara, 

Selam olsun lokmasını askeri ile paylaşıp

O''nu Ata''sıyla İzmir''e ulaştıranlara.

Selam olsun 29 Ekim''e,23 Nisan''a, 

Selam olsun tüm şehitlere, gazilere, Ata''ya ve arkadaşlarına.

Ey Ankara! 

Kulak ver söylediğimiz marşa.

Kulak ver  dağ başını duman almış diyen gençlerin kararlılığına.

Kulak ver söylediğimiz onuncu yıl marşına, 

Söylerken duyduğumuz hüzne ve gurura.

Ey Ankara! 

At şu üzerindeki ölü toprağını.

Dağıt Anadolu''nun üzerinde dolaşan kara bulutları.

İnan koşullar dünden hiç de zor değil, 

Kaldırın aranızdaki politik ayrılıkları.

Yalvarıyoruz! 

Güneşi aratmayın bize gündüz karanlığında, 

Olun güneşimiz.

Biz sizinle beraberiz.

Kendimiz için değil, 

Çocuklarımız için bir umut ışığı özlemimiz.

Gerekiyorsa bu uğurda son lokmamızı, 

İsteyin.

Seve seve, seve seve veririz.', 'Güneşi arıyoruz gündüz karanlığında,  Güneşi arıyoruz masmavi gökyüzünün altında Anadolu''nun dört bir yanında. Kimimiz sağda, kimimiz solda,...', ARRAY['Türk Edebiyatı','Şiir','Ali Girgin']::text[], 8.5, '{"poet":"Ali Girgin","poet_slug":"ali-girgin","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/bu-ulke-hepimizin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız Kulesi', 'kiz-kulesi-seyit-ahmet-duzen-dmxk5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Denizin kucağında büyüttüğü

Biricik yavrusudur Kız Kulesi

Deniz fenerleriyle martılar

Ondan öğrenmiştir

Denize selam verip

Sahile vuran yıldızları toplamayı

Kız Kulesidir

Her gece yakamoz yakan

Gece içinde gizli gözlerini

Düşlerimin sahiline vuran.', 'Denizin kucağında büyüttüğü Biricik yavrusudur Kız Kulesi Deniz fenerleriyle martılar Ondan öğrenmiştir Denize selam verip Sahile vuran yıld...', ARRAY['Türk Edebiyatı','Şiir','Seyit Ahmet Düzen']::text[], 8.5, '{"poet":"Seyit Ahmet Düzen","poet_slug":"seyit-ahmet-duzen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kiz-kulesi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyimserlik', 'i-yimserlik-recep-kupcu-vv8nj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beklediğim sabah hala uyuklar

Garip kucağında dumanlı gözün

Saadeti dünya kimlere saklar

Kemirir içimi ezeli hüzün

Şimdi şu belirsiz günlerimde ben

Derinden ah çeker, ümit izlerim

Gözlerim nemlenir çaresizlikten, 

Yine yeri öpmez ama dizlerim.

Zaman akıcıdır, tezelden geçer

Zaman sonsuzluğun içinde özgür

Elbette yılmayan murada erer

Yaz yağmuru gibi geçse de ömür', 'Beklediğim sabah hala uyuklar Garip kucağında dumanlı gözün Saadeti dünya kimlere saklar Kemirir içimi ezeli hüzün Şimdi şu belirsiz günleri...', ARRAY['Türk Edebiyatı','Şiir','Recep Küpçü']::text[], 8.5, '{"poet":"Recep Küpçü","poet_slug":"recep-kupcu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/iyimserlik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimle Vedalaşan Yaprak', 'benimle-vedalasan-yaprak-recep-kupcu-fdz75', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Böyle miydim ben önceden

Bütün umutlarım ölgün

Yağmur çiseler inceden

güz müdür başlıyan bugün? 

Güzle gelen bu hüzünden

Ağacım da sarktı dal dal

Gitmek var dünya yüzünden

Gidiyorum ben hoşçakal...', 'Böyle miydim ben önceden Bütün umutlarım ölgün Yağmur çiseler inceden güz müdür başlıyan bugün?  Güzle gelen bu hüzünden Ağacım da sarktı da...', ARRAY['Türk Edebiyatı','Şiir','Recep Küpçü']::text[], 8.5, '{"poet":"Recep Küpçü","poet_slug":"recep-kupcu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/benimle-vedalasan-yaprak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Yaprağa Cevabım', 've-yapraga-cevabim-recep-kupcu-tyebz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gittin yaprağım dünyadan

Gidişin belimi büktü

Bir söz nedir konuşmadan

Dostluğumuz ne büyüktü

Dediklerimi sır bildin

Söylemedin bir yaprağa

Suskunluğunla güzeldin

Ah verdim seni toprağa

Hep sevilen gider ilkin

Böyle dünyanın düzeni

Tedirgin olma sen lakin

Yaşatacağım ben seni.', 'Gittin yaprağım dünyadan Gidişin belimi büktü Bir söz nedir konuşmadan Dostluğumuz ne büyüktü Dediklerimi sır bildin Söylemedin bir yaprağa ...', ARRAY['Türk Edebiyatı','Şiir','Recep Küpçü']::text[], 8.5, '{"poet":"Recep Küpçü","poet_slug":"recep-kupcu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ve-yapraga-cevabim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmayı çok zor sanırdım', 'unutmayi-cok-zor-sanirdim-guven-aktas-ws92o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Unutmayı cok zor sanırdım, 

Ama kolaymıs hemen unuttum seni, 

Sahilde yürüdügümüz günleri, 

Bir bir martılara simit attıgımız vapuru, 

Karsıdan karsıya gecerken bana delice sarıldıgını, 

Unuttum her seyi, 

Oysa ki zor sanırdım unutmayı, 

Oturup bir parka basımı omzuna koydugumu unuttum

Zor degilmis unutmak seni, 

Ben cok zor sanırdım oysa ki, 

Hatırlıyormusun hani bir gün, 

Güneş tepedeydi mevsimlerden bahardı, 

Ele ele dolasırken üsküdar sahilinde, 

Bir anda bulutlar kaplamıstı havayı, 

Ben yağmur yagacak demiştim, 

Sen ise bana inanmamıştın 

Cok kızmıstım sana sevgilim, 

Ama yagmıştı yagmur gökyüzünü delercesine

Ve demiştim ki sana bende, 

Üzerine gelen her yagmur damlası kadar

Sen beni sev, 

Gelmeyenler kadarda ben seni seviyorum…

Bakmıştın bana öyle sessizce…

Ve öpmüştün beni ilk defa…

Hatırlıyormusun bunları, 

Ben unuttum bile, zor sanırdım oysa unutmayı, 

Unuttugumdan yazıyorum bı mısraları, 

Sen unuttu say beni sevgilim, 

Unuttu bil beni, 

Ben seni unutsamda, yüregim unutmuyor ki, 

Sen gülüyor, egleniyor san beni, 

Bedenim eğlensede, ruhum hala seninle

Seni seviyorum delicesine..', 'Unutmayı cok zor sanırdım,  Ama kolaymıs hemen unuttum seni,  Sahilde yürüdügümüz günleri,  Bir bir martılara simit attıgımız vapuru,  Karsı...', ARRAY['Türk Edebiyatı','Şiir','Güven Aktaş']::text[], 8.5, '{"poet":"Güven Aktaş","poet_slug":"guven-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/unutmayi-cok-zor-sanirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir bilsen..', 'bir-bilsen-guven-aktas-a7is3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aaah bir bilsen seni ne kadar çok sevdiğimi, 

Sen yokken çıldırdığım vakitleri, 

Sesini duymak için neler yaptığımı bir bilsen...

Devamlı yanımda olmanı ne kadar çok istediğimi, 

Yaşlı gözlerle sadece sana bakıp, , 

Göz yaşlarım kuruyana kadar ağlamak istediğimi, 

Bir bilebilsen seni ne kadar çok sevdiğimi, 

Kelimelerin anlatmaya yetmediğini, 

Geceleri seni düşünürken ne kadar çok rahat uyuya bildiğimi, 

Bir bile bilsen sana deliler gibi aşık olduğumu ahhh bir bilsen....

Yakarmısın güzelim dünyayı bana kavuşmak için? 

Her şeyden vazgeçebilirmisin yanımda olabilmek için? 

Sabahlara kadar seni seviyorum diyebilirmisin? 

Her şeyi bırakıp sadece beni sevebilirmisin? 

Benim düşüncemi sorma güzelim biliyorsun zaten..! ! 

Yakarım bu dünyayı yakmamı istersen..

Hiç düşünmeden feda ederim canımı, istersen, 

Yıldızları indiririm ayaklarına basıp üstlerinden geçmek istersen, 

Deliler gibi aşığım sana, yemek yerken, yürürken, 

Her nefes alıp verdiğimde bile seni seviyorum diye biliyorsam, 

Demek ki seni seviyorum güzelim sen biliyorsun zaten,', 'Aaah bir bilsen seni ne kadar çok sevdiğimi,  Sen yokken çıldırdığım vakitleri,  Sesini duymak için neler yaptığımı bir bilsen... Devamlı ya...', ARRAY['Türk Edebiyatı','Şiir','Güven Aktaş']::text[], 8.5, '{"poet":"Güven Aktaş","poet_slug":"guven-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-bilsen-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen yoksun', 'sen-yoksun-gunay-aktag-8uz76', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine bu gün yalnız bir gün yaşıyorum.

Sen yoksun, o yok, hiç kimse yok, 

Bu gün yapayalnızım, hemde çok yalnız

Canım çok sıkılıyor, mutsuzum, huzursuzum

Ağlamak istiyorum, haykırmak istiyorum....

Seni seviyorum diye bağırmak istiyorum....

Bir anda seni düşünmek geliyor aklıma, 

Ve seni düşünüyorum....

Gözümün önünde sen, 

Hayalimde sen, 

Ruhumda sen, 

Bütün benliğimde sen, sen, sen

Ama yoksun  yanında sen

Başımı omzuna yaslamak istiyorum

Saçlarını okşamak istiyorum

Sana sarılmak, gözlerinin içine bakıp

Seni seviyorum...

Seni seviyorum diye fısıldamak istiyorum...

Ama sen yoksun, 

Sen yoksun  bitanem  söyleyemiyorum...

Bu gün yalnız bir gün yaşıyorum

Sensiz ve sessiz...

Seni seviyorum, seni seviyorum

Ve seni hala seviyorum......', 'Yine bu gün yalnız bir gün yaşıyorum. Sen yoksun, o yok, hiç kimse yok,  Bu gün yapayalnızım, hemde çok yalnız Canım çok sıkılıyor, mutsuzum...', ARRAY['Türk Edebiyatı','Şiir','Günay Aktağ']::text[], 8.5, '{"poet":"Günay Aktağ","poet_slug":"gunay-aktag","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-yoksun-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanınmazım Ben', 'taninmazim-ben-yasar-aslan-jztfk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni ne siyaha boyanmış geceler 

Ne  güneşe aldanmış gündüzler tanır

Ne sıcak tenlere yakın gelirim

Ne  soğuk iklimlere

Sesimi ne rüzgardan aldım 

ne gök gürültüsünden

Ne denizdeki dalgadan 

ne hoyrat esen yelden

Rengim ne sarı ne mavidir ne  beyaz  kefen 

Beni ne onlar tanır nede sen

Kokum az kekik az da  ıhlamur 

Hani şu göğse iyi gelen,

Beni tanımaz

Ne dost bildiğim aynalar 

Beni tanırsa hüzün tanır

Kefensiz ölüm tanır

Bir dost bildiğim şiirim tanır

Beni ne sen tanırsın ne de senin gibiler...', 'Beni ne siyaha boyanmış geceler  Ne  güneşe aldanmış gündüzler tanır Ne sıcak tenlere yakın gelirim Ne  soğuk iklimlere Sesimi ne rüzgardan ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Aslan']::text[], 8.5, '{"poet":"Yaşar Aslan","poet_slug":"yasar-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/taninmazim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı Bahardır Akşamlar', 'yalanci-bahardir-aksamlar-ruzgar-gezgini-3fjlf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalancı bahardır akşamlar

Delirtircesine sarar bedeni

Alır yaldızlı karanlığına

Sana vermeden seni..

Kucaklar, sokakları insanı

Gününü unuttururcasına 

Kendi gerçeğini her defasında

Sana vermeden seni...

Kadehten bakmak mı? 

Yoksa kadehe bakmak mı? 

Kollarında akşam nedensizce

Sana vermeden seni...

Baharda akşamlar şen

Baharda cümbüş, kahkaha

Siyah, beyaz, gri fotoğraflarda

Sana vermeden seni.....', 'Yalancı bahardır akşamlar Delirtircesine sarar bedeni Alır yaldızlı karanlığına Sana vermeden seni.. Kucaklar, sokakları insanı Gününü unutt...', ARRAY['Türk Edebiyatı','Şiir','Rüzgar Gezgini']::text[], 8.5, '{"poet":"Rüzgar Gezgini","poet_slug":"ruzgar-gezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalanci-bahardir-aksamlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beşinci Mevsim', 'besinci-mevsim-fatih-kagan-yucel-fan0l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gördüğüm her simâda herkes kadar sen varsın

Duyduğum mısralarda baktığım her resimde

Aramıza özlemi muhanneti katarsın

Buluşmak mı dersin...Belki beşinci mevsimde

Yüzünü arıyordu attığım her adımda

Fark etti yokluğunu Cebeci sokakları

Karanlık asi oldu geceler çıldırdı da

Şafaga isyan etti çigneyip yasakları

Sen hayat gibi yalan Tanrı kadar gerçeksin

Gönlümü gönlün ile boğup öldüreceksin

Omzumda raks ediyor döktüğün göz yaşları 

Deniz kadar berraktır cehennem gibi sıcak

Benden bu günahları soracak mahşer yeri

Ruhum gözlerindeki kıvılcımla yanacak

Adını anmak yasak sesini duymak haram

Elinden kor fışkırır istesem de tutamam

İpek saçların hâlâ güneş kadar sarı mı? 

Nurunda gizlemiştim en âşikar sırrımı

Bir sırdı ki dünyanın hazinesine bedel

Bir sırdı ki aynı sen çözebilseydin eğer

Verilmemiş son nefes yaşanmamış an gibi

Tadılmamış bir duygu lal olmuş isyan gibi

Ölüm fermanı çıktı kınımdaki hançere

Urgan ile tanıştı daha bir kez kesmeden 

Celladın gözyaşına dönüp bakmadı bile

Hâla gülümsüyordu sehpaya uzanırken

Dilin namludur bana sense dostsun bir ömür 

Dertlerin kurşun olsun vur son bulsun bir ömür

Sen en mutlu gününde beyaz giymiş bir peri 

Tebessümünün rengi baharı kıskandırır

Dilimde o ‘’Monna’’ nın hüzün dolu şiiri 

Âlemdeki mevsimi bir hazana döndürür

Yüreğimde sonsuzluk sonsuzlukta ise sen

Yaşaması kolay hadi öl ölebilirsen

Tüm ömrüme rest çekip kaderden daha önce

Gözlerin ruhum için vur emrini verince 

Yere düşer bedeni yan çizen bu bahtımın

Altına turab olur attığın her adımın

Lâkin yalvarır sanma böyle gelmiş ve gider

Derman yokluğundadır gölgen gelince biter

Bu yara ebediyen ateşlerde dolansın 

Kor alevdir merhemi bırak yanarsa yansın

Yangında sönmek değil suda yanmaktır murat 

Katletmek özgürlüğü gönlüne esir olmak

İstemem gelme artık sevdadan ötesi var

Tattım hasret zevkini sevsen de neye yarar

Sen beşinci mevsimin ulaşılmaz menzili 

O tomurcuk güllerin firar eden katili

Ve ben aynı ben kim ne derse desin

Ve sen hâlâ gurbette beşinci mevsimdesin...

                                              27 mart 2003', 'Gördüğüm her simâda herkes kadar sen varsın Duyduğum mısralarda baktığım her resimde Aramıza özlemi muhanneti katarsın Buluşmak mı dersin......', ARRAY['Türk Edebiyatı','Şiir','Fatih Kağan Yücel']::text[], 8.5, '{"poet":"Fatih Kağan Yücel","poet_slug":"fatih-kagan-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/besinci-mevsim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Gidiyorum', 'i-ste-gidiyorum-fatih-kagan-yucel-45fnb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İşte gidiyorum

Belki de son defa dönmemek üzere

Belki de son defa geziyorum sokakları 

Son defa izliyorum gün batımını bu şehirde 

Ve en son defa gizleniyorum

Gözlerin gözlerimden habersiz

Gözlerim bir kuytuda

Geçeceğin kaldırımlara bakarak.

İşte gidiyorum

Elimde birkaç çanta

Yüreğimde otogar yalnızlığı

Bir de yalnızlığın kulak delici çığlığı

Kızıyorum kendime 

Neden nişanlısıyım yalnızlığın

Ve neden sessizliğin çığlığını bir ben duyuyorum diye

Neden ağlıyorum 

Neden iç çekiyorum ve neden her dem pişmanlık var içimde

Haykırıştır belki de bu neden deyişler isyandır

Öyleyse bile tek kendime

Ama tek kendime ama tek bana

Benliğimin bir yarısında acı 

Diğer yarısında isyanla

Gidiyorum

İşte gidiyorum

Sana bir yüreğimi

Birde yüreğine atfedilen birkaç hece bırakıyorum

Zaten değersiz bir iki saçma kıta

Ve paramparça bir kalpten başka

Hiçbir varım yok ki! ! ! 

Bunlarla tatmin olmayacaksın belli ki

Varsın olma

Varsın gözlerin kurşun

Kirpiklerin ok olsun 

Vur vurabildiğin kadar öldür.

Ben zaten alıştım tatmaya can vermenin zevkini

Hem de her gün hem de her gece ve her saat

Hem de her an

Hadi

Hadi çabuk yak yüreğimi

Çabuk sök kalbimi yerinden

Gitmem gerek acele et

Yedi otobüsü beni bekliyor 

Hasret beni gurbet beni

Beni bekliyor gözyaşı

Sen bilmezsin belki amma

Gece ve karanlık beklemeyi sevmez 

Bekletilmeye hiç gelmez

Keşke bilseydin

Şimdi gözlerim kalabalık bir otogar yalnızlığında 

Seni arıyor

Bir nevi sensizliği bir nevi kaybolan beni

Belkide hiç kimseyi kimsesizliği ve hiçbir şeyi

Bakışlarım 

Umutsuzca boşluklarına dalar yolların

Sanki kimsesizlikten başka hiç kimse gelecekmiş gibi

Biliyorum

Bir kendim olacağım bana eşlik eden

Bir de kendim kalacak geride

Uğurladıktan sonra beni...

Sırf bu nedenle 

Ama sırf bu nedenledir ki

Gidiyorum

Bak sonunda gidiyorum

İşte işte gidiyorum

İşte gidiyorum...

3 kasım 2001 / Konya', 'İşte gidiyorum Belki de son defa dönmemek üzere Belki de son defa geziyorum sokakları  Son defa izliyorum gün batımını bu şehirde  Ve en son...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kağan Yücel']::text[], 8.5, '{"poet":"Fatih Kağan Yücel","poet_slug":"fatih-kagan-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/iste-gidiyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Gözlüm', 'yagmur-gozlum-yesim-acar-cxt1x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beklenen telefon, gelmiyor hala, 

Yüreği, büyük bir sabırsızlıkta, 

Seni düşünüyorum.

Seni düşünürken, gökyüzüne salıncak kuruyorum.

Telefon suskun, 

Çalmayacak biliyorum.

Sesinin rengini, hayal ediyorum.

İnan ki, yağmur gözlüm, 

Seni çok seviyorum.', 'Beklenen telefon, gelmiyor hala,  Yüreği, büyük bir sabırsızlıkta,  Seni düşünüyorum. Seni düşünürken, gökyüzüne salıncak kuruyorum. Telefon...', ARRAY['Türk Edebiyatı','Şiir','Yeşim Açar']::text[], 8.5, '{"poet":"Yeşim Açar","poet_slug":"yesim-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yagmur-gozlum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vedasız veda', 'vedasiz-veda-yusuf-guler-qkmjb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nerdesin kalbimin kalpsiz sahibi nerdesin

Aniden nereye kaybolup gittin

Beni bu karanlık gecelerde yalnız bıraktın

Bilmez misin gecenin karanlığından korktuğumu

Hatırlasana sensiz gecelerin beni nasıl ağlattığını

Bir veda busesini bana çok mu gördün

Niye bu sessizce veda niye

Unuttun mu seni ne kadar çok sevdiğimi

Ne oldu sıkıldın mı artık sevilmekten

Mutsuzluğu, hüznü mü merak ettin

Bu yüzden mi gittin isimsiz diyarlara

Madem gidiyorsun o zaman

Niye kalbimi yanına alıyorsun

Korktun mu oralarda sevgiyi bulamamaktan

Bu yüzden mi acımasızca koparıyorsun yüreğimi benden

Bıraksana kalbimi yerine koysana

Sana diyorum bıraksana kalbimi bıraksana

Hiç aklına gelmedi mi, hiç düşünmedin mi

Sabahları sensiz uyanamayacağımı

Sensiz yaşayabileceğimi nasıl düşündün

Yaşamak senin için yemek, içmek mi sadece

Bilmiyor musun benim yaşam kaynağım olduğunu

Bilmiyor musun gündüzleri güneşim geceleri yıldızım olduğunu

Ne oldu ne yaptım sana

Sevdim diye suçlu mu oldum

Adını kalbime yazdım diye mi

Yoksa senin için ölümü göze aldığım için mi

Bu yüzden mi beni cezalandırıyorsun

Öyleyse hiç durma öldür beni

Öldürsene beni sana diyorum öldürsene

Benim olmadın hiç olmazsa ECELim ol', 'Nerdesin kalbimin kalpsiz sahibi nerdesin Aniden nereye kaybolup gittin Beni bu karanlık gecelerde yalnız bıraktın Bilmez misin gecenin kara...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Güler']::text[], 8.5, '{"poet":"Yusuf Güler","poet_slug":"yusuf-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/vedasiz-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Kefen', 'kara-kefen-yusuf-guler-yk080', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duydumki evleniyormuşsun

Düğün günü orada olacağım

Son bir kez de olsa seni görmeye geleceğim

En ön masaya oturacağım

Seni tebrik edeceğim

Ve alnından son bir kez öpeceğim

Sonra arkama bile bakmadan

Çekip gideceğim karanlık sokaklara doğru

Ben karanlık sokaklarda kaybolurken

Gözlerin dolacak

Belki de ömründe ilk defa gerçekten ağlayacaksın

Arkamdan bağırmak isteyeceksin

Seviyorum seni geri dön demek isteyeceksin

Sesin kısılacak konuşamayacaksın

Olduğun yere yığılıp kalacaksın

Sesini kimselere duyuramayacaksın

Ve orada öylece can vereceksin

Beyaz gelinliğin ise senin kefenin olacak aşkım', 'Duydumki evleniyormuşsun Düğün günü orada olacağım Son bir kez de olsa seni görmeye geleceğim En ön masaya oturacağım Seni tebrik edeceğim V...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Güler']::text[], 8.5, '{"poet":"Yusuf Güler","poet_slug":"yusuf-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kara-kefen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Kefenlik', 'kara-kefenlik-yusuf-guler-7qrak', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Duydumki evleniyormuşsun

Düğün günü orada olacağım

Son bir kez de olsa seni görmeye geleceğim

En ön masaya oturacağım

Seni tebrik edeceğim

Ve alnından son bir kez öpeceğim

Sonra arkama bile bakmadan

Çekip gideceğim karanlık sokaklara doğru

Ben karanlık sokaklarda kaybolurken

Gözlerin dolacak

Belki de ömründe ilk defa gerçekten ağlayacaksın

Arkamdan bağırmak isteyeceksin

Seviyorum seni geri dön demek isteyeceksin

Sesin kısılacak konuşamayacaksın

Olduğun yere yığılıp kalacaksın

Sesini kimselere duyuramayacaksın

Ve orada öylece can vereceksin

Beyaz gelinliğin ise senin kefenin olacak aşkım', 'Duydumki evleniyormuşsun Düğün günü orada olacağım Son bir kez de olsa seni görmeye geleceğim En ön masaya oturacağım Seni tebrik edeceğim V...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Güler']::text[], 8.5, '{"poet":"Yusuf Güler","poet_slug":"yusuf-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kara-kefenlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-yusuf-guler-jnmxt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ya ben sana kavuşamazsam

Seni unutabilecekmiyim ki

Belki zaman herşeyi silebilir

Seni hiç bir şey ama hiç bir şey silemez

Çünkü ben seni kalbime kazımışım

Adın dudağımda sen ise kalbimdesin

Ya sen, ya sen ne olacaksın

Hiç düşündün mü

Karanlık gecelerde tek başına kalmayı

Belki yanında biri olacak

Ama kalbin boş olacak

Yalnızlık seni saracak

Unutmaya çalışacaksın yalnızlığını

Ama ne zaman kendinle

Başbaşa kaldığın an 

Beni hatırlayacaksın

Keşkeler deyip, pişman olacaksın

Tutamayacaksın gözyaşlarını 

İşte o zaman gözlerindeki yaşlar

Yavaş yavaş kana dönüşecek

Gün gelecek zamanı, günü unutacaksın 

Zamanın senin için anlamı kalmayacak

Mutluluk sana haram olacak

Her yeni güne mutsuzlukla uyanacaksın

Gülmeyi unutacaksın

Ama en çokta  sevilmeyi unutacaksın

Nerde bir sevgili görsen beni hatırlayacaksın

Gözlerin dolacak ağlamak isteyeceksin

Sen bunları yaşarken

Sanki ben yaşıyor olacakmıyım

Seni mutsuz görmeyi nasıl katlanabilirim

Sen bir parçacık üzülsen

Bilki ben yeniden öldüm demektir

İşte aşkım bu yüzden

Mutlu olmaya çalış yalandan da olsa

Çünkü bu hayata bir daha gelmeyeceksin

Bir daha karşına ben çıkmayacağım

Belki çıkmamı çok isteyeceksin

Tanrı sevdiği kulların karşısına

Benim gibi birisini bir defa çıkarır

Sen bu şansı geri çevirdin

Bu yüzden mutsuzluk kaderin olacak', 'Ya ben sana kavuşamazsam Seni unutabilecekmiyim ki Belki zaman herşeyi silebilir Seni hiç bir şey ama hiç bir şey silemez Çünkü ben seni kal...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Güler']::text[], 8.5, '{"poet":"Yusuf Güler","poet_slug":"yusuf-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sen-ve-ben-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim', 'sen-benim-yusuf-guler-qkk6f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O ilk bakışta gözlerde bir kıvılcım çakar

Yüreklere bir ateş düşer

Kalpler deli deli atmaya başlar

Bir gülüşü için can verilir

Bir damla gözyaşına dünyalar yakılır

İşte böyle başlar ölümsüz sevdalar

Sen benim alınyazım, yarınsız sevdam

Sen benim bitmeyen nefesimsin

Sen benim ilk gözağrım

Ve ömür boyu

Son aşkım olarak kalacaksın

Bu aşk bir ömür boyu sürüp gidecek

Sözler anlatacak aşkımızı

Sözlerin bittiği yerde kalpler konuşacak

Tüm dünya bilecek sevdamızı

Ve yıllarda sonrada anlatılacak

Sen benim alınyazım, yarınsız sevdam

Sen benim bitmeyen nefesimsin

Sen benim ilk gözağrım

Ve ömür boyu

Son aşkım olarak kalacaksın', 'O ilk bakışta gözlerde bir kıvılcım çakar Yüreklere bir ateş düşer Kalpler deli deli atmaya başlar Bir gülüşü için can verilir Bir damla göz...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Güler']::text[], 8.5, '{"poet":"Yusuf Güler","poet_slug":"yusuf-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-benim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberler', 'haberler-oguzkan-bolukbasi-vvspq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hayat sana bana aldırmadan sürüyor

gazeteleri okuyorum her sabah

çok üzüldüm iran lı kızlara

ne umutluydu gülüşleri ameliyat öncesi

ayıramadılar doktorlar

aşık olmuşlar mıydı acaba onlar da

sevmişler miydi birini

ellerini tutan olmuş muydu

ya da yürekleri ayrı ayrı sevdalara atmış mıydı

keşke sorsalardı

ne güzel de gülüyorlardı umutla

ırakta derdest edilen askerler korkmuşlar mıydı kafalarına çuvallar geçirilince

hayatı mı düşünmüşlerdi önce

sevdalarını mı

vatanlarını mı

böylesine meraklar akla zarar mıdır dostlar

zararsız bir akıl işe yarar mı  acaba

hesap ettim kabaca

ençok  işe yarayan o çocukluktan bu yana

şehir ortasında sıvı yakıt istasyonu patlamış

pişmişkelle yetkililerin sırıtmalarına biterim hep

en çok ta beyanatlarına

söz söylenmesi zor olan bir ülkede suratlarına

ölümsüz patlamalara şükredip duralım

kaldırımlar yenileniyor bir zevksizlik örneği derme çatma

bu ülkede usta yok

ara sokaklar asfaltlanıyor rezalet

utanmadan.............belediyesi çalışıyor levhaları

seçim yaklaşıyor

bunlar bizi salak sanıyor

salak mıyım

evet yahu salağım

dostlarım kızmayın bana benim işim yaşamak olmalı

ben yaşamaya bakacağım', 'hayat sana bana aldırmadan sürüyor gazeteleri okuyorum her sabah çok üzüldüm iran lı kızlara ne umutluydu gülüşleri ameliyat öncesi ayıramad...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/haberler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu gece bir başka ihtiyacım var sana', 'bu-gece-bir-baska-ihtiyacim-var-sana-baris-akm-yxdn9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu gece bir başka ihtiyacım var sana 

Yumuşacık ellerinin şefkatine 

Rengini bilmediğim gözlerinin tenhalarına 

Hiç dokunmadığım saçlarının gölgesine 

Bilemezsin, ne kadar ihtiyacım var 

Bu gece bir başka yanıyor hasret ateşin 

Gözlerim nafile yıldızların karanlığında 

Nefesim ilmik boğazıma 

Bu gecede gelmez isen bu köhne kıyıya 

Yarın, istemem artık gelme 

Bu gece, başka gece 

Dertli başımın en çok bu gece ihtiyacı var omzuna 

Bu boşluğun teninin varlığına 

Sesin gelecekse bu gece gelmeli düşlerden beriye 

Yarın çok olacak ikimizede 

Bu gece, işte öyle bir gece', 'Bu gece bir başka ihtiyacım var sana  Yumuşacık ellerinin şefkatine  Rengini bilmediğim gözlerinin tenhalarına  Hiç dokunmadığım saçlarının ...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-gece-bir-baska-ihtiyacim-var-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Esintiler', 'sensiz-esintiler-baris-akm-fm2wp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiç bir şey yormuyor artık beni 

Hayat denen yolun ayrımlarında 

Bir tek kendimden korkar oldum 

Kendimle başbaşa kalmak tek kabusum 

Sensizliğe ve yokluğuna de ki alıştım 

Ya kendi içimde kendime? 

Orada yaşanıyor savaşların en acısı 

Çocukların gözleri hep yaşlı 

Onun için gecelerden başka korkar oldum 

El ayak çekilince namlulara sürülür askerlerim 

Dost kendim düşman kendim 

Ben bu savaşlarda hep yenilmek zorundayım 

Şimdi yine öyle bir zaman 

Gece uzanmış yarının kollarına 

Ben yenilginin kanlı gözlerine 

Sensiz düşen her yaprak zehir yaralarıma', 'Hiç bir şey yormuyor artık beni  Hayat denen yolun ayrımlarında  Bir tek kendimden korkar oldum  Kendimle başbaşa kalmak tek kabusum  Sensiz...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sensiz-esintiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Dudakları', 'gecenin-dudaklari-baris-akm-6i78h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneş günden el ayak çekince 

Sadece sensizlik doğar gecelerime 

Elinde karanlık şişe 

Hep aynı şarkı dudaklarında 

Başka öper gecenin dudakları 

Ellerinde kalırsın bir sessizliğin 

İçinde geçmiş sayfalardan hüsran kırıkları 

Gözlerinde o hep aynı düşün tozları 

Hayat bu mu olmalıydı 

Hasretinde yarınlar tükendi 

Çuvallar almıyor artık sensiz günleri 

Zaman ha tükendi ha tükeniyor sevgili', 'Güneş günden el ayak çekince  Sadece sensizlik doğar gecelerime  Elinde karanlık şişe  Hep aynı şarkı dudaklarında  Başka öper gecenin dudak...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gecenin-dudaklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmuyor', 'olmuyor-baris-akm-2jcoz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Olmuyor 

Bir gece daha doluyor damarlarıma 

Saat kaç olmuş kimin umurunda 

Bir tıkırtı işte 

Her tık bin kurşun ömre 

Yokluğunun karlı zirvelerinde 

Olmuyor 

Ne gün ne gece var sensizlikte 

Bir siyah çarşaf pencerenin ötesinde 

Berisinde bir yaprak rüzgar bekliyor düşmeye 

Yoksun, heceler düğümleniyor gözlerimde 

Sen doluyorsun sensizliğime 

Olmuyor 

Bu gecede yürümüyor yarına 

Yarın gelmiyor geceye 

Gelecek geldi sen gelmedin yine 

Sessiz sessiz ağlıyor istasyonlar sarmaş dolaş raylarla 

Boşa bekledim gelirsin diye 

Bir gece daha eskiyorum yokluğun koynumda', 'Olmuyor  Bir gece daha doluyor damarlarıma  Saat kaç olmuş kimin umurunda  Bir tıkırtı işte  Her tık bin kurşun ömre  Yokluğunun karlı zirve...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/olmuyor-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve hep sen', 've-hep-sen-baris-akm-3nolb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hepimiz sen varsın diye geldik Dünya''ya 

Kimimiz bulut oldu sen-i bulunca 

Ilık rüzgarlar dost saçlarına 

Kimimiz tükendi yolunda 

Yazlar ateşli humma 

Kışlar karadan öte 

Baharlar sensiz yazıldıkça günlüklere 

Şimdi birkaç adım var sıfır noktasına 

Ve ben de sensiz varacağım o taşa 

Dev gibi yılların çöplüğü ardımda 

Karalı dostlar bir bir safta 

Sensizliğin son perdesi inecek bakışlarıma 

Selam olsun hayat denen çöplüğe', 'Hepimiz sen varsın diye geldik Dünya''ya  Kimimiz bulut oldu sen-i bulunca  Ilık rüzgarlar dost saçlarına  Kimimiz tükendi yolunda  Yazlar at...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ve-hep-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Gelin', 'sari-gelin-bulent-isik-evza4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Endamı yüzünden ince belinin

Ah çeker görenler büker başını

Saçları parıldar sarı gelinin

Yakamoz sanırsın hilal kaşını

Şavkı vurur göze sırma telinin.

Şu dağların hayduduna kurduna 

Aldırmaz şanını duyup gelenler

Nice yolcu ulaşamaz yurduna

Gelinin yarini görüp bilenler

Çaresiz ağlayıp sızlar derdine', 'Endamı yüzünden ince belinin Ah çeker görenler büker başını Saçları parıldar sarı gelinin Yakamoz sanırsın hilal kaşını Şavkı vurur göze sır...', ARRAY['Türk Edebiyatı','Şiir','Bülent Işık']::text[], 8.5, '{"poet":"Bülent Işık","poet_slug":"bulent-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sari-gelin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk Üzerine', 'mutluluk-uzerine-garip-bir-yolcu-chkye', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Merhaba gülen gözlü arkadasim! Dudagindaki tebessümü kaybetmemissin daha.

Ne güzel dünyaya gülen gözlerle bakabilmek ve insanlara tebessümler saçabilmek senin gibi

Biliyorum, üzülüyorsun donuk gözlerle karsilasinca

Ne yapalim arkadasim! Herkes senin gibi olamaz...

Duyabiliyorum ''hayir olmali'' dedigini.

Haklisin arkadasim! Aslinda bütün insanlar senin gibi olmali

Bilseler bir tebessümle neler yapabileceklerini, 

Bir çocugun gözlerindeki isiltiyi, bir tebessümle nasil görebileceklerini, 

Sikintilarla dolu bir insana, nasil dünyalari verebileceklerini bilseler, 

Ve gülen gözlerin buzlari nasil erittigini, kalpleri nasil birlestirdigini bilseler, 

minim onlar da senin gibi olmak isterlerdi...

Ve sevgi saçiyorsun gülen gözlerinle arkadasim.

Saf ve hiç beklentisi olmayan bir çocuk gibi...

Hayir arkadasim! Sevgi, sadece sevgiliye duyulmaz.

Sevgi evrenseldir...

Hiç kimse altin yiginlari gibi kasasina kilitleyemez onu.

O''nun yeri kalplerdedir...

Bir annenin kalbindedir o''nun yeri, çocuguna verebilmek için.

O''nun yeri bir bahçivanin ellerindedir, sevgi tohumlari saçabilmek için...

Evet, sevgi heryerdedir.

Yeter ki sen onu bulmak iste.

Sevgiyi bulmak kolay, zor olan onu elinde tutabilmekte.

Unutma arkadasim! Sevgiyi duyabilmekle de is bitmiyor.Sevgiyi göstermek te gerekiyor.

Hayat kisa arkadasim, bugün olan yarin yok! 

Sevgiyi göstermek beklemeye gelmez, yarin çok geç olabilir...

Elindekini kaybetmeden kiymetini bilmelisin.

Biliyorum arkadasim, bana hak veriyorsun.

Simdi kos sevdiginin yanina! 

Önce ona gülen gözlerle simsicak bir gülümse ve ''seni seviyorum'' deyiver, içinden gelen en sicak sesinle..

Hayir, bunlar komik seyler degil arkadasim...

Seni seviyorum anne, seni seviyorum baba, kardesim, arkadasim demek komik degil.

Bu senin gibi bütün canlilara karsi sonsuz bir sevgi duyan bir insan için hiç de zor degil..

Sadece biraz cesaret arkadasim.

Bu yalnizca, yüreginin buz kapladigini zanneden insanlara biraz zor gelecektir, 

Ama onlar da senin gösterdigin cesareti gösterdiklerinde, kalplerinde sevgi kipirtilarini hissetiklerinde

Ve aglamayi ögrendiklerinde, inan hersey onlar için ve bütün insanlar için daha güzel olacak.

Evet arkadasim! Gülmek varken surat asmak niye, 

güldürmek varken aglatmak niye, 

güzel sözler söylemek varken, kalpleri kirmak niye? 

Hayat çok kisa arkadasim ve bu dünyadaki hiç bir sey kirilan kalplere degmez.

Simdilik hosçakal arkadasim...Yine gel.

Yanina senin gibi gülen gözlü, yüregi sevgi dolu insanlari alip yine gel olur mu? 

Beni fazla bekletme.

Çünkü yarin burada olamayabilirim..', 'Merhaba gülen gözlü arkadasim! Dudagindaki tebessümü kaybetmemissin daha. Ne güzel dünyaya gülen gözlerle bakabilmek ve insanlara tebessümle...', ARRAY['Türk Edebiyatı','Şiir','Garip Bir Yolcu']::text[], 8.5, '{"poet":"Garip Bir Yolcu","poet_slug":"garip-bir-yolcu","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/mutluluk-uzerine-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcu Gök', 'yolcu-gok-gok-tengri-2wcz6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gök tengri! sana edilen iltifatları duyup da şişme

Anadolu''na; O''nun alçakgönüllülüğüne etme ihanet! 

Unutma! Sen ne tam bir öğrencisin, ne tam bir öğretmen

Sen bir yolcusun

Geldiğin yerlere öğrencisin; bir şeyler öğrendiğinden

Geçtiğin  yerlereyse öğretmensin

O öğrendiklerini öğrettiğinden! ..', 'Gök tengri! sana edilen iltifatları duyup da şişme Anadolu''na; O''nun alçakgönüllülüğüne etme ihanet!  Unutma! Sen ne tam bir öğrencisin, ne ...', ARRAY['Türk Edebiyatı','Şiir','Gök Tengri']::text[], 8.5, '{"poet":"Gök Tengri","poet_slug":"gok-tengri","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yolcu-gok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarım Sensiz Yaşanan Gecelere', 'aglarim-sensiz-yasanan-gecelere-gunay-aktag-gky6t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gecem daha sensiz geçiyor, 

Yokluğun dayanılmaz

Sensiz geçen gecemde seni düşlüyor, 

Ve seni düşünüyorum

Zindan gibi odam, kapkara duvarlar, 

Sensiz aydınlanmıyor 

Karanlığın içinde hep seni, 

Hep seni hayal ediyorum; çaresiz 

Benimki bir umut, bir düş işte, 

Sen, nerdesin, nerde

Senin yokluğunda ağlarım sensiz yaşanan gecelere

Hayalinle avutuyorum kendimi, 

Bir çocuk misâli, bir kuş misâli 

Unutamıyorum seni, çıkmıyorsun aklımdan 

Beynime çakılan bir çivi misâli

İçtiğim su, aldığım nefes gibi muhtacım sana, 

Yokluğun dayanılmaz

Yakıyor hasretinin ateşi bedenimi, tüm benliğimi

Seni unutamıyorum işte unutamıyorum

Senin yokluğunda ağlarım 

Sensiz yaşanan gecelere 

Unutamıyorum seni unutamıyorum.', 'Bir gecem daha sensiz geçiyor,  Yokluğun dayanılmaz Sensiz geçen gecemde seni düşlüyor,  Ve seni düşünüyorum Zindan gibi odam, kapkara duvar...', ARRAY['Türk Edebiyatı','Şiir','Günay Aktağ']::text[], 8.5, '{"poet":"Günay Aktağ","poet_slug":"gunay-aktag","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aglarim-sensiz-yasanan-gecelere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adil Düzen', 'adil-duzen-i-brahim-bayraktar-3osq0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saat altıyı on geçe servis yola koyuldu.

İçerisi memurlarla doluydu.

Kimi kara kara düşünürken, 

Çoğu sohbete koyuldu.

Kimi, geçim derdinde, 

Kimi, terfi peşinde, 

Kimi, tatili düşünür, 

Kimi, ekmek görür düşünde.

İki evi olana hemen lojman verilir.

Kiradaki memura niye bekle denilir? 

1990/ANKARA', 'Saat altıyı on geçe servis yola koyuldu. İçerisi memurlarla doluydu. Kimi kara kara düşünürken,  Çoğu sohbete koyuldu. Kimi, geçim derdinde,...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/adil-duzen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlığın Tüneli', 'karanligin-tuneli-fusun-sayan-d22jy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaman dediğin nedir ki? 

Bir anla bir ömür, bir olur bazen

Ne anı yaşarsın ne de ömrü (!)

Ölüm dediğin diken, gül olur bazen

Bir odasında mutluluk saklı

Bir odasında hayal

Bir odasında gerçek

Hayat üç oda bir salon değil ki

Sürekli arayıp bulman gerek

Buldum dersin, bulduğun sensin

Kral gibi yaşasan da

Garip gibi göçersin

Zaman tarlası verimli

Ektiğini biçersin

Ne hanın kalır

Ne dönecek yanın

Karanlığın tünelinden

Geldiğin gibi gidersin.................', 'Zaman dediğin nedir ki?  Bir anla bir ömür, bir olur bazen Ne anı yaşarsın ne de ömrü (!) Ölüm dediğin diken, gül olur bazen Bir odasında mu...', ARRAY['Türk Edebiyatı','Şiir','Füsun Sayan']::text[], 8.5, '{"poet":"Füsun Sayan","poet_slug":"fusun-sayan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/karanligin-tuneli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Acısı', 'ayrilik-acisi-fusun-sayan-viof4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senden ayrı günler geçer mi sandın? 

Gönül başka bir yar seçer mi sandın? 

Hasreti zamanla içer mi sandın?        

İçilmez bu zehir içilmez  gülüm       

Çağırdığın an gelmez ki ölüm (!)     

Ayrılık yolları taştan dikenden 

Kanatır kalbini candan bedenden  

Kurtulmazsın biçilmiş bu bedelden     

Ha deyince serden geçilmez  gülüm

Çağırdığın an gelmez ki ölüm (!)    

   

Sen bir çiğ tanesi temiz ve duru  

Ben bir kır lalesi dalında kuru     

Güldürmez kaderin ne benle zoru     

Boyun büktüm su vermedin bir  gülüm 

Çağırdığın an gelmez ki ölüm (!)

   

Dön de bir arkana bak ne bıraktın  

Dosdoğru sevdama bin yalan kattın   

Kurusa gözyaşım, dinmez ki ahım     

Mahşere kaldı bak  hesabın  gülüm

Çağırdığın an gelmez ki ölüm(!) .....', 'Senden ayrı günler geçer mi sandın?  Gönül başka bir yar seçer mi sandın?  Hasreti zamanla içer mi sandın?         İçilmez bu zehir içilmez ...', ARRAY['Türk Edebiyatı','Şiir','Füsun Sayan']::text[], 8.5, '{"poet":"Füsun Sayan","poet_slug":"fusun-sayan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ayrilik-acisi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-fusun-sayan-zs9xd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayrılık içimde kara bir gece      

Mutluluk dilimde silinmez hece    

Can evime  hayali dikilince          

Kapıyı aç içeri al geceler              

 Zifiri yar, ışığa var geceler           

Yalnızlık kervanı sessizce yürür     

Kalbimi bir anda hasreti bürür      

Çölde serap hayali, izim sürür      

Ellere ayaz, bana har geceler        

Dağlara hasret beyaz kar geceler

Bir damla gözyaşı döktüğüm benim   

Gül olmaz bahçede diktiğim benim    

Kimseler görmez ki çektiğim benim   

Derdime yanan tek sırdaş geceler      

Bağrına basan  has kardaş geceler      

Sesim çıkmaz bilirsiniz dilsizim              

Yar yoksa, Han Sarayında evsizim          

Mecnun gibi çöllerde bir yersizim           

Aşka varan merdiven, yol geceler          

Kuytu kucak, saran bir kol  geceler         

Geceler gelince  zevke dalalım      

Yarin hayaliyle pür-nur olalım           

Sabaha ermeden aşkla yanalım   

 Derde derman ilaç gibi geceler

Hak''ka varan Miraç gibi geceler......', 'Ayrılık içimde kara bir gece       Mutluluk dilimde silinmez hece     Can evime  hayali dikilince           Kapıyı aç içeri al geceler      ...', ARRAY['Türk Edebiyatı','Şiir','Füsun Sayan']::text[], 8.5, '{"poet":"Füsun Sayan","poet_slug":"fusun-sayan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/geceler-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Yağmuru', 'hasret-yagmuru-fusun-sayan-vtqn5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünyanın kanunu

Gülmeden ölmek

Bir hasret yağmuru

Seni çok sevmek

Mezarımda güller

Duvağında tüller

Sevgim toprak oldu

Geçiyor bak günler

Yakışır mı sana

Ellerin olmak

Tertemiz sevdama 

Karalar çalmak

Şimdi git

Ardına bile bakmadan

Ne anlar yüreğin

Gerçek sevdadan

Ellerin oldun sen

Oldun ne oldu? 

Yüreğim ah eder

Gözüm yaş dolu

Mezarımda güller

Duvağında tüller

Sevgim toprak oldu

Geçiyor bak günler....', 'Dünyanın kanunu Gülmeden ölmek Bir hasret yağmuru Seni çok sevmek Mezarımda güller Duvağında tüller Sevgim toprak oldu Geçiyor bak günler Ya...', ARRAY['Türk Edebiyatı','Şiir','Füsun Sayan']::text[], 8.5, '{"poet":"Füsun Sayan","poet_slug":"fusun-sayan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hasret-yagmuru-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arjin', 'arjin-mehmet-eyuboglu-boosl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine sabaha vardı gece

Hasretinle....

Ne kadar gitme dedimse de dinletemedim

Ah be Arjin, 

Ah be ateşin kızı, 

Nerdesin? 

Neden her gidişte başroldesin? 

Ve neden her buluşmada figüransın? 

Ne güzellik varsa bende kalan 

Hayata dair, 

Senin izin

Nerdesin Arjin? 

Neden kapıyı çalan değilde

Hayaldekisin? 

Ne vardı ki gidecek? 

Geri dön desem şimdi; 

Kim bilir hangi yalanla dolu beynin, 

Hangi alçağın sözlerine kandı yüreğin? 

Neden bitmezki sendeki nisan yağmurları.

Gel desem şimdi, 

Yolumu bulabilirmisin? .............', 'Yine sabaha vardı gece Hasretinle.... Ne kadar gitme dedimse de dinletemedim Ah be Arjin,  Ah be ateşin kızı,  Nerdesin?  Neden her gidişte ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Eyüboğlu']::text[], 8.5, '{"poet":"Mehmet Eyüboğlu","poet_slug":"mehmet-eyuboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/arjin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Hayat', 'sen-ve-hayat-eren-serbest-h4zt8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hafiften çiselenen bir yağmur damlası gibiydi senle hayat, 

Yarı ıslak, yarı mat. 

O hafif yağmurdan sonraki gökkuşağında aşk, 

Bir o kadar renkli ve bir o kadar uzak bana... 

Ay ışığında gizli mehtabın büyüsü, 

Ve okyanusta gizli aşkın serüveni, 

Ne rüzgarlar belli ne akıntılar belli kalbimde, 

Nede hoyrat bir gemi var ellerimde...

Bir buse gülle yaşamaya benzerdi senle yaşamak! 

En solgun anında bile gizli bir tılsım vardı.

En ücra köşesinde limanlarımın 

Nefes almaya çırpınan bir balık vardı...

En kötü şiirlerimde bile senin adın var, 

Her şiirimde biraz sen var. 

İhtiras dolu şehvetli gecelerimde bile 

Senin gizeminden bir buse anı var', 'Hafiften çiselenen bir yağmur damlası gibiydi senle hayat,  Yarı ıslak, yarı mat.  O hafif yağmurdan sonraki gökkuşağında aşk,  Bir o kadar ...', ARRAY['Türk Edebiyatı','Şiir','Eren Serbest']::text[], 8.5, '{"poet":"Eren Serbest","poet_slug":"eren-serbest","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-ve-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melike''ye', 'melike-ye-fusun-sayan-hsmwp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Daha küçüksün bebeğim

Büyüyeceksin

Hayatın dikenli yollarında

Yürüyeceksin

Önünde ben

Dikenleri ayıklayan annen

Tırmanacaksın merdivenleri

Yavaş yavaş

Zirvede mutluluk

Seni bekleyen

Tırmanacaksın

Arkanda ben

Düşmene engel olmaya çalışan annen

Daha küçüksün bebeğim

Büyüyeceksin

Sen şaşkın gözlerle 

Bakarken yaşama

Yanında ben

Görmediklerini gören annen

Gün gelecek bir tanem

Kendin olacaksın

Dört elle sarılacaksın yaşama

Başarın başarım olacak

Sevgin gururum

Başın dik yürürken sen

Yanında yine ben

Her zaman 

Yanında olan annen.....', 'Daha küçüksün bebeğim Büyüyeceksin Hayatın dikenli yollarında Yürüyeceksin Önünde ben Dikenleri ayıklayan annen Tırmanacaksın merdivenleri Y...', ARRAY['Türk Edebiyatı','Şiir','Füsun Sayan']::text[], 8.5, '{"poet":"Füsun Sayan","poet_slug":"fusun-sayan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/melike-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salıncak', 'salincak-fusun-sayan-dg1r7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karlı bir kış günü

Bir parka götürdü beni ayaklarım

Karşımda ağır ağır sallanan

Boş bir salıncak

Gözümde canlandı çocukluğum

Bir zamanlar

Böyle bir salıncağa binebilmek için

Sıra beklerdik heyecanla

Sonra bir ileri bir geri

Sanki uçardık bulutlara

Peki sonra ne oldu? 

Birden büyüdük

Ama hep içimizde kaldı büyümeyen çocuk

Şimdi duygularım

Hayat denen salıncakta sallanıyor

Aradaki tek fark

Çocukluğumun salıncağı beni göklere uçururdu

Hayat salıncağı, yerden yere vuruyor......', 'Karlı bir kış günü Bir parka götürdü beni ayaklarım Karşımda ağır ağır sallanan Boş bir salıncak Gözümde canlandı çocukluğum Bir zamanlar Bö...', ARRAY['Türk Edebiyatı','Şiir','Füsun Sayan']::text[], 8.5, '{"poet":"Füsun Sayan","poet_slug":"fusun-sayan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/salincak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcu', 'yolcu-i-zzet-selcuk-cumaoglu-wqojo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgiye yolculuk yapmak istersen

En son treni kaçırma sakın

Çabucak bin.

Farkında olmadan kaybeder gideriz

Tüm sevdiklerimizi

Sevdiğimiz şeyleri.

Çok az zaman var

Çığlık çığlığa bağırıyor

Adeta gardan ayrılacağını haykırıyor

Haydi yakala treni.

Çok değil, bir adımlık mesafedesin

Bir adım atacaksın o kadar

Fazla değil.

Gidenleri görebilmen

Belki bir daha mümkün olmayacak

Belki çok özleyeceksin

Belki ağladığın da olacak arkalarından

Pişmanlığının bir anlamı olmayacak sonradan.

Yüreğinin sevgi dolu sesini dinle

Bakma kötü gözeneklerine.

Haydi oyalanma, 

Haydi harcama zamanı

Bin artık şu son sevda trenine.', 'Sevgiye yolculuk yapmak istersen En son treni kaçırma sakın Çabucak bin. Farkında olmadan kaybeder gideriz Tüm sevdiklerimizi Sevdiğimiz şey...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yolcu-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaten', 'zaten-i-zzet-selcuk-cumaoglu-wctop', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu kadar aşağılamana gerek yok beni

Ben zaten kendi hesabımı görüyorum

Acı sözlerle öldürmene gerek yok beni

Damla damla her gece ben zaten ölüyorum.

Kalmadı gururum ne ezer durursun

Vicdanın yok mu senin, vurur durursun

Bir rüzgara benzer, eser savurursun

Umarsız dert doluyum kuruyup duruyorum.', 'Bu kadar aşağılamana gerek yok beni Ben zaten kendi hesabımı görüyorum Acı sözlerle öldürmene gerek yok beni Damla damla her gece ben zaten ...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zaten-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kedi İle Yılanın Hikayesi', 'kedi-i-le-yilanin-hikayesi-i-zzet-selcuk-cumaoglu-8uxt1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uysal mı uysaldı 

Yumuşak tüyleriyle kedicik.

Evin her köşesinde

Hoplaya zıplaya oynardı.

Arasıra sahibine

Kendisini sevdirmek için

Sırnaşdığı da olurdu hani

Bazı gün bulunduğu evin

Yakınındaki ormana da kaçardı

Kimi gün kuş yakalar

Kimi gün deredeki kurbağalarla oynardı.

Neler neler vardı o güzel ormanda

Binbir çeşit kuş, binbir çeşit böcek

Ve yılanlar.

Nedense herkes nefret eder yılandan

Oysa tüm suçu yılan olmak

Ve Şahmaran’ın ölümünden bu yana

Kendini insanlardan korumak.

Gezer ormanda ıslık çalarak

Günlük nafakasını buldu mu çocuklarının

Keyfi gelir yerine.

Onların yumurtalarını kırıp

Kıpır kıpır ortaya çıkışları gelir gözlerinin önüne.

İçine sıcak bir mutluluk dolar

Daha bir hazla bastırır

Toprağı bedenine.

İşte tüm bunları düşünürken

Vücuduna bir ateş yayılır ensesinden.

Önce bir can havliyle çırpınır

Kurtulmaya çalışır ısırılan yerinden.

Sonra tatlı bir ıslaklık ve yalanma hisseder

Dişlenen bölgesinden.

Seviliyorum zannederek gevşerken

Gevşemenin doruğunda

Bir daha dişlenir aynı yerden.



Anlar ki sonu gelmiştir artık.

Düşünmezdi ölümün geleceğini

Bir kedinin dişlerinden.

Bir daha, bir daha

Bir yalanma bir dişlenme derken

Canı çıkıverdi desenli, güzel teninden.', 'Uysal mı uysaldı  Yumuşak tüyleriyle kedicik. Evin her köşesinde Hoplaya zıplaya oynardı. Arasıra sahibine Kendisini sevdirmek için Sırnaşdı...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/kedi-ile-yilanin-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyorum', 'usuyorum-i-zzet-selcuk-cumaoglu-0othg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Üşüyorum, 

Damarlarım boşalmış

Kanım çekip gitmiş başına buyruk.

Üşüyorum.

Kalbim bomboş

Düşlerim öksüz

Güneşim boğuldu deniz ortasında

Kutup yıldızımı yuttu karanlıklar

Çaldılar mihenk taşımı

Kaybettim nirengi noktamı

Üşüyorum.

Bir yetim yosma

Aldattı sevdamı

Gözlerini çekip aldı düşlerimden

Soydular aşkımı

Çırılçıplak bıraktılar beni

Üşüyorum.

Ne kadar sevgi varsa

Örtün üstüme n’olur

Çok… çok üşüyorum.', 'Üşüyorum,  Damarlarım boşalmış Kanım çekip gitmiş başına buyruk. Üşüyorum. Kalbim bomboş Düşlerim öksüz Güneşim boğuldu deniz ortasında Kutu...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/usuyorum-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürsün', 'ozgursun-i-zzet-selcuk-cumaoglu-7g7oo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mahpus kaldı

Duvarımda gölgen

Düşlerimde hayalin

Yüreğimde aşkın.

Bir hıçkırıktın boğazımda

Kördüğüm oldun.

Karasevdamdın

Kara talihim oldun 

Alnıma yazılan.

Ateşimdin beni tetikleyen

Suyum oldun 

Tepemden aşağı dökülen.

Cennetimdin huzur bulduğum

Cehennem oldun 

Beni yakıp kavuran.

Karanlık gecelerimin

Pembe düşüyken

Karabasanım, kâbusum oldun

Uyanmak isteyip de uyanamadığım.

Aşkımdın, canımdın

Düşmanım oldun

İçimden söküp atamadığım.

Mahpus kaldı

Duvarımda gölgen

Düşlerimde hayalin.

Yüreğimi boşaltıp

Seni özgür bıraktım.', 'Mahpus kaldı Duvarımda gölgen Düşlerimde hayalin Yüreğimde aşkın. Bir hıçkırıktın boğazımda Kördüğüm oldun. Karasevdamdın Kara talihim oldun...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ozgursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balım', 'balim-i-zzet-selcuk-cumaoglu-5b3ij', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensiz geçen her günüm bin ıstırap içimde, 

Döner misin bilmem ki ummadığım bir günde

Değerim yok mu benim o güzel gözlerinde

Seni böyle vefasız görmeye alışmadım.

Sen bu gönül bahçemde nadide bahar dalı

Ömrümün kovanında şifalı anzer balı

Koruyucu meleğim, Allah’ımın bir kolu

Sana bir söz söyleyip kırmaya çalışmadım.', 'Sensiz geçen her günüm bin ıstırap içimde,  Döner misin bilmem ki ummadığım bir günde Değerim yok mu benim o güzel gözlerinde Seni böyle vef...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/balim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Aşk Ve Serçeler', 'i-lk-ask-ve-serceler-mirkan-acar-uvh98', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir metreden fazla karla karşılaştım sabahın ilk ışıklarında... 

sokağınızdan geçerken o an aralamıştın pencereyi, 

sokakta bir ben vardım bir de serçeler.. 

ilk kez yüreğimden koptu bir şeyler.. 

yüreğimde pır pır serçeler… 

o zaman deniz görmemiştim 

ilkokul çağında yüreğim.. 

dünyam o küçücük kasabaydı 

kocaman bir şehirden gelmiştin.. 

ellerin kar beyazı, 

gözlerin bahar yeşili, 

saçların sarıydı.. 

camın buğusuna ‘’seni seviyorum’’yazdığında 

kanatlandı yüreğimdeki serçeler.. 

seninle iki mevsim geçti…. 

zemheri ve bahar.. 

hazan mevsiminde göçüp gittin

uzak kocaman şehirlere… 

bu küçücük kasabanın uzun çekilmez kış gecelerinde

ne sen varsın artık, nede serçeler..

Hala geçerken sokağınızdan, 

Perde aralanmasa da

O bakışın duruyor pencerede

yitik bir aşkın hüznüyle

bir ben kaldım…

birde yüreğimin buzdan yaktığı ateşler...', 'bir metreden fazla karla karşılaştım sabahın ilk ışıklarında...  sokağınızdan geçerken o an aralamıştın pencereyi,  sokakta bir ben vardım b...', ARRAY['Türk Edebiyatı','Şiir','Mirkan Acar']::text[], 8.5, '{"poet":"Mirkan Acar","poet_slug":"mirkan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ilk-ask-ve-serceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyandığımda', 'uyandigimda-agah-ozbek-1dc33', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her sabah 

İçimde

Sönmeyen bir alev

Coşkuyla kalkan gözkapakları

Parlak beyaz ortasında

Bir zeytin tanesi gözlerim.

Canlı bir müzik ritmine

Kapılmış akardiyon peteği gibi

Yüreğim.

Elim, kolum bacaklarım

Sanki savunmaya hazır

Bir silah gibi...

Gerneşirken büyüdüğümü hissediyorum

O eski küçüklüğümden, 

Ve üşüyor ayaklarım...

                                            12-12-1983-Mensa', 'Her sabah  İçimde Sönmeyen bir alev Coşkuyla kalkan gözkapakları Parlak beyaz ortasında Bir zeytin tanesi gözlerim. Canlı bir müzik ritmine ...', ARRAY['Türk Edebiyatı','Şiir','Agah Özbek']::text[], 8.5, '{"poet":"Agah Özbek","poet_slug":"agah-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uyandigimda-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısır', 'kisir-askin-gungor-mv84m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçinde topal bir hüzün

     ağır aksak ilerleyerek

          fethetmeye çalışırken gönlünü, 

               pencereden doğuşunu gördüğü

                    güneşin sarı saçlarına

                         yaslamış kırık gülüşünü.

Tophane’li Rabia, 

     şiirler tasarlayarak gözyaşı tadında

           bir bebek kokusuna verebilirdi

                acılarla harmanlanan ömrünü.

Ah, bir doğurabilse...

Doğurabilse ilkbahar kokulu

     ağlaması çiçekli bir bebecik...

Doyasıya sarabilse nazlı gülünü...

“Anne” dediğini dahi duymadan

     ölmek bile kabulüydü.

Kokusunu sindirerek, 

     pembe yüzünü seyrederek doyasıya

           öpebilse bir kerecik, 

                Tophane’li Rabia, 

                     içinde mutluluklarla beklerdi ölümünü.

Henüz kendi gencecik... 

(12.04.1995)', 'İçinde topal bir hüzün      ağır aksak ilerleyerek           fethetmeye çalışırken gönlünü,                 pencereden doğuşunu gördüğü     ...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Güngör']::text[], 8.5, '{"poet":"Aşkın Güngör","poet_slug":"askin-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kisir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fahişe', 'fahise-askin-gungor-pz2df', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sokakta, 

     çiseleyen yağmurun ıslattığı

          pervasız karanlıkta, 

               alevi kendini ısıran

                    güçlü bir kibrit yardımıyla

                         sigarasını yaktı kadın.

Sarı saçlarını duman aldı.

Bir tütün gibi tükettiği

     yaşantıdan geriye

          filtre gibi emilmiş, 

              ısırılıp örselenmiş, 

                   hayalleri duman olan

                        bitkin bedeni kaldı. 

(02.01.1996)', 'Sokakta,       çiseleyen yağmurun ıslattığı           pervasız karanlıkta,                 alevi kendini ısıran                     güçlü bi...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Güngör']::text[], 8.5, '{"poet":"Aşkın Güngör","poet_slug":"askin-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/fahise-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Delirdim', 'sana-delirdim-askin-gungor-ssw2m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '“Sana delirdim, ” desem...

“Delirdim sana, ” desem...

Hani sen...

Sen varsın ya...

Varırsın ya İstanbul gibi üstüme kimi zaman...

Gözlerin özletir ya zelzeleleri...

Sudan çıkmış balık gibiyim ya

     sesinle seviştiğim zaman.

Mutluluk oyunları anlatırsın ya, 

     dinlerim, 

          Sezen Aksu’yu dinler gibi...

Kendimi dinlerim ya

     sesinden yıldız toplarken hani.

Susarsın ya birden

     Attila İlhan’ın şiirlerini okurmuşum da

         dinlermiş gibi...

Diyesim gelir ki o vakit, 

“Unut tüm sevdiklerini.

Hepsinin sevgisiyle sevmelisin beni.

Unut.

Hadi, bir annenin sevgisi kalsın sende.

En az onunki kadar benimki...”

“Öp beni, ” desem, “sanki erkeğini öper gibi.”

Öper misin? 

“Cumartesi banyosu yap, ” desem, “benimle, 

     dökünüp tüm giysilerini.”

Beni yine çocuk gibi sever misin? 

“Sana delirdim, ” desem...

Kağıda üç yıldız çizsem; 

     “Biri sen, 

     biri ben, 

     biri hiçbir şeyimiz, ” desem...

“Delirdim sana, ” desem...

“Sana delirdim, ” desem...

Etrafımıza mavi bir evren çizer misin? 

“Sana delirdim, ” desem...

Bana güler misin? 

(02.10.1993)', '“Sana delirdim, ” desem... “Delirdim sana, ” desem... Hani sen... Sen varsın ya... Varırsın ya İstanbul gibi üstüme kimi zaman... Gözlerin ö...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Güngör']::text[], 8.5, '{"poet":"Aşkın Güngör","poet_slug":"askin-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sana-delirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse Bilmesin', 'kimse-bilmesin-erdem-demirkol-wd2dq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'KİMSE BİLMESİN

Kimse bilmesin bu geceyi.

Bir sen, bir ben, bir de Allah.

Gözlerin gözlerimi bilsin, 

Sözlerin sözlerimi.

Ve başka kimse bilmesin, 

Seni ne çok sevdiğimi.

Kimse bilmesin neden sustuğumuzu.

Kimse görmesin yaşlı gözlerimizde, 

Ne fırtınalar koptuğunu.

Ve duymasınlar ellerimizin bulutuğunu.

Kimse bilmesin bu geceyi.

Bir sen, bir ben, bir de Allah.

(27.06.2003-Yesilyurt-iZMiR-saat:02.30)', 'KİMSE BİLMESİN Kimse bilmesin bu geceyi. Bir sen, bir ben, bir de Allah. Gözlerin gözlerimi bilsin,  Sözlerin sözlerimi. Ve başka kimse bilm...', ARRAY['Türk Edebiyatı','Şiir','Erdem Demirkol']::text[], 8.5, '{"poet":"Erdem Demirkol","poet_slug":"erdem-demirkol","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kimse-bilmesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsin Sen', 'kimsin-sen-erdem-demirkol-na2hq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevda nedir, aşk nedir? 

Ben neyim, bilmem ki kimim.

Bildiğim tek şey onun ateşidir.

Yanıp tutuşan bir divaneyim.

Ben yanmasam o incinir.

O yakmasa ben tükenirim.

Onun ateşiyle can bulur yüreğim.

Onun nefesiyle huzura ererim.

Bir gülse su serpilir gönlüme.

O gülüş can suyudur ömrüme.

Ateşim, suyum, her şeyim.

Yakanım da o, söndürenim de.

Hasretiyle gecelerde üşürüm.

Aşığım, avare sokaklarda yürürüm.

Hayalini yıldızlarda görürüm.

Kavuşmak düşmez bana.

Varlığı da, yokluğu da ayrı zulüm.

Boş duvarlar suskun gecelerde.

Hüznümü anlatmaya yetmez, 

Onsuz geçen sözler de, heceler de.

Gökyüzü ağlar, hasretiyle gecelerce.

Ben bu yüzden yağmurlarda üşürüm.

Göz pınarlarım kurur o ağladığında.

Üzülürse ben üşürüm gözyaşlarında.

Hüznüm de, sevincim de dudaklarında.

Kim üşütür, kim yakar beni? 

Rüzgarda esen saçları, gül yanaklarıyla.

Kimsin sen ey güzel peri? 

(08.07.2003-Yesilyurt-iZMiR-saat:18.00)', 'Sevda nedir, aşk nedir?  Ben neyim, bilmem ki kimim. Bildiğim tek şey onun ateşidir. Yanıp tutuşan bir divaneyim. Ben yanmasam o incinir. O ...', ARRAY['Türk Edebiyatı','Şiir','Erdem Demirkol']::text[], 8.5, '{"poet":"Erdem Demirkol","poet_slug":"erdem-demirkol","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kimsin-sen-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koşu Bandındaki Piyonlar Borçludur Bize', 'kosu-bandindaki-piyonlar-borcludur-bize-bahadir-absin-30oab', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yazın kumrallığı

ve aşkın melez teni

iki yakın dosttur

ikamet yerleri İzmir olan

İkameti İzmir olan

birileri daha vardır

Temmuzun  ortasında

ilikleri buzulda dövülenlerden

Kabul ediyorum; 

şimdi yalnızım.

Göğsümde, 

güneşin batışına ateş yakan

yaşlı bir kabile oturuyor.

Beynimin solungaçlarını

tıkamak isteyenler var

Ege''nin firari mavisinde.

Dilimin, 

idamını istiyor ucuz söz tacirleri

üstelik satırlarının/çocuklarının

önünde

/Sonra kalabalığa sesleniyor kalemim:

''Petrolün düştüğü denizde

can çekişen martıya bakarak; 

havaya acıklı sözler söyleyen güzel kız, 

kendi kirlettği denizi görmez aslında

çünkü piyonu olmuştur

bataklıktaki satrancın

/Ama her koşulda; 

bize bir martı borcun var, adı ''onur'' dur onun.''', 'Yazın kumrallığı ve aşkın melez teni iki yakın dosttur ikamet yerleri İzmir olan İkameti İzmir olan birileri daha vardır Temmuzun  ortasında...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Abşin']::text[], 8.5, '{"poet":"Bahadır Abşin","poet_slug":"bahadir-absin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kosu-bandindaki-piyonlar-borcludur-bize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Adam Bir Kadın Ve İki Çocuk', 'bir-adam-bir-kadin-ve-i-ki-cocuk-ozcan-ozkan-ncmcz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kadın odanın ortasında diz çökmüş.

Gözleri dehşetle açık, sırılsıklam kan çanağı.

Kapkara bakıyor...

Adam odanın ortasında diz çökmüş.

Kadının tam karşısında.

Gözleri alev topu, öfkeli.

Bir eli kadının saçına dolanmış, 

İnce ve hesaplı acılar peşinde.

Öteki elinde gaz lambası, 

Ha vurdu ha vuracak...

Oda alaca karanlık.

Soğuk kuytu köşelerde gölgeler büyüyor.

Kadının arkasında bir çocuk.

Nasıl küçülebileceğini kuruyor.

Korkusu büyüdükçe...

Adamın dizi dibinde bir çocuk.

Çoktan küçülmüş.

      *    *     *

Ne zaman bir cocuk “babacığım”dese

Bir yerlerde...

Bir adam...

Bir kadını...

(2003)', 'Kadın odanın ortasında diz çökmüş. Gözleri dehşetle açık, sırılsıklam kan çanağı. Kapkara bakıyor... Adam odanın ortasında diz çökmüş. Kadın...', ARRAY['Türk Edebiyatı','Şiir','Özcan Özkan']::text[], 8.5, '{"poet":"Özcan Özkan","poet_slug":"ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-adam-bir-kadin-ve-iki-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceviz Hikayesi', 'ceviz-hikayesi-murat-kayali-tj9f9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'mutluluk

varliginda tükenmez sanki

ufak bir cocugun avuclarina sigmayan akide sekerleri gibi

tatli

ask

bir bayram yeri

atlikarincalarin dönmelerinin hic bitmedigi

ebedi

sen

gözümün bebegi

sen

dar gönlümün genis nefesi

sen bende her ikisi

varligin

dayandigim yoklugunun bedeli

yalnizligin borcu ödendi

sana gecmisimden bir hikayeyi

anlatmadan edemiyecegim

“avuclarimda taze ceviz lekeleri

saklayamam ellerimi

yalanyamam gögsümdeki bereleri

mintanimin kopuk dügmeleri ele verir beni

agactan düstügüm, her halimden belli“

söylediklerim belki bir ceviz kabugunu doldurur

ama cevizin kabugu ne kadar kuruysa

icindeki ceviz o kadar olgundur

ve bir insan ne kadar cok düstüyse

o kadar cok tutunur

biliyorum

sussamda anlardin 

ve

bulurdun

sen beni

kör bir tirtilin yesil bir yapragi buldugu gibi

cünkü

yüregim

her zaman ele verir beni', 'mutluluk varliginda tükenmez sanki ufak bir cocugun avuclarina sigmayan akide sekerleri gibi tatli ask bir bayram yeri atlikarincalarin dönm...', ARRAY['Türk Edebiyatı','Şiir','Murat Kayalı']::text[], 8.5, '{"poet":"Murat Kayalı","poet_slug":"murat-kayali","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ceviz-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bozkır Yamacı Gibi', 'bozkir-yamaci-gibi-derin-oger-gteq5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Demir almalıyım

Düşlerimin limanından

Terk edip gitmeliyim

İçimde beni sarhoş eden büyüden

Rüyalarıma hapsetmeliyim 

Küçük yolculukları

Toplamalıyım çamaşır iplerinden

Bir bir yalan aşkları

Güneşin batışıyla....

Yeniden doğmalı güneş

Sahte şehir ışıkları yerine

İsimsiz dağ rüzgarlarıyla havalanmalı saçlarım

Unutulmuş maniler tadında demli

Ve mısra mısra sevgilinin sesi

Yüreğine yaslamalıyım yüreğimi

Bozkır yamacı gibi

Hiç kimse bilmemeli bendeki yerini

Ne deniz ne güneş ne bulut

Şehir bile

Bir tanrı olmalı bir de sen

Uğruna ölebileceğim...........', 'Demir almalıyım Düşlerimin limanından Terk edip gitmeliyim İçimde beni sarhoş eden büyüden Rüyalarıma hapsetmeliyim  Küçük yolculukları Topl...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bozkir-yamaci-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmeyin üstüme', 'gelmeyin-ustume-cemal-ekren-doq5l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sana kocaman bir çınar gönderiyorum

gölgesinde uyu

gövdesinden nice umutlar topla

benim kayıp bir çocukluğum

yitik bir gençiğim var

bilmiyorsun sen..

ve tecritli bir sevdadayım şimdi

önüm, arkam, sağım, solum gözyaşı

nedendir bu anlamsız insan çıglıkları? 

gelmeyin üstüme.

kırmızı bir gök yüzü düşünemiyorum ben

yeşil bir ateş yalımı

mavi bir yagmur yada

ve yılları bulan mart ayazları

üşüyorum yoklugunda

bırakma beni

ve hastalıklı bir çocuk gibiyim artık

sıtmalı gecelerden kaçtımda geldim

bileklerimde ip sag göksümde muskam var

ayakalrımdan çıkmadı hal

kınamızın kokusu

gel artık sevdiğim

seve bildiğim', 'sana kocaman bir çınar gönderiyorum gölgesinde uyu gövdesinden nice umutlar topla benim kayıp bir çocukluğum yitik bir gençiğim var bilmiyor...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gelmeyin-ustume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayn-Ana Yüreği', 'kayn-ana-yuregi-ozcan-ozkan-fp57d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elin ekmek tutsun hele bir

Seni koluma takıp

Sürüp sürüştürüp

Cümle aleme nispet

Elin ekmek tutar tutmaz

Körolası seni koluna taktı

Sürüp sürüştürüp

Bana nispet

Cümle aleme nispet

(2003)', 'Elin ekmek tutsun hele bir Seni koluma takıp Sürüp sürüştürüp Cümle aleme nispet Elin ekmek tutar tutmaz Körolası seni koluna taktı Sürüp sü...', ARRAY['Türk Edebiyatı','Şiir','Özcan Özkan']::text[], 8.5, '{"poet":"Özcan Özkan","poet_slug":"ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kayn-ana-yuregi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Yanar', 'can-yanar-gulay-yildiz-gp4zs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yangın yeri kalbim, yanıyor.

İçimde sızı, yüreğim dağlanıyor

Mahşer yeri avuçlarım

Gözlerim yolda, bekliyor...

Aldırma, yanarım alev alev

Aldırma, saçlarımda aklar

Ağlama, biterim elbet

Ağlama, sevda ölmüş, can yanar...', 'Yangın yeri kalbim, yanıyor. İçimde sızı, yüreğim dağlanıyor Mahşer yeri avuçlarım Gözlerim yolda, bekliyor... Aldırma, yanarım alev alev Al...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/can-yanar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk 1', 'ask-1-sair-masmavi-6x6b9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözüm kamaştı renginden

Dilim kamaştı kalakaldım

Özüm kamaştı aşkından

Güldün sen donakaldım!', 'Gözüm kamaştı renginden Dilim kamaştı kalakaldım Özüm kamaştı aşkından Güldün sen donakaldım!...', ARRAY['Türk Edebiyatı','Şiir','Şair Masmavi']::text[], 8.5, '{"poet":"Şair Masmavi","poet_slug":"sair-masmavi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-1-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk 2', 'ask-2-sair-masmavi-fzo7i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sancılar sarıyor bedenimi

Tanrım! ! ölmek üzereyim

Tek bir gözüm bırak hayatta

Hep sevdiğimi göreyim!', 'Sancılar sarıyor bedenimi Tanrım! ! ölmek üzereyim Tek bir gözüm bırak hayatta Hep sevdiğimi göreyim!...', ARRAY['Türk Edebiyatı','Şiir','Şair Masmavi']::text[], 8.5, '{"poet":"Şair Masmavi","poet_slug":"sair-masmavi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-2-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birazdan O Kapıdan Çekip Gideceksin', 'birazdan-o-kapidan-cekip-gideceksin-tulay-sustam-p5927', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(Yağmur tanesine...) 

Ne çok seviyorsun bana acı çektirmeyi

Birazdan o kapıdan çekip gideceksin

Geride bir tek ben ve o kahrolası yalnızlığım kalacak

Düşünmeyeceksin! ...

Senden sonra ne olacağımı

Neler yapacağımı, nasıl sensiz ayakta kalacağımı

Birazdan o kapıdan çekip gideceksin

Ben yine başımı masaya koyup hıçkırarak ağlayacağım

Her gün hayalin gözümün önünden gelip gidecek

Sanki hiç gitmemişsin gibi...

Geldiğim de yine sana ''günaydın'' diyeceğim

Ama senden ses çıkmayacak

İşte o zaman dünya başıma yıkılacak

Seni çok özleyeceğim

Bunu sana belli etmemek istiyorum ama olmuyor

Bilirsin beni; ben duygularımı saklayamam

İyi ki görmüyorsun senden sonra ki halimi

İyi ki bilmiyorsun senden sonra çocuklar gibi ağladığımı

Ben senin kadar güçlü değilim işte

Yıkılışım da sevgim kadar büyük benim

Birazdan o kapıdan çekip gideceksin

Biliyorum gözün arkada kalmayacak

Ama ben gittiğin yollar da dönüşünü bekleyeceğim

Geldiğin gün çocuklar gibi sevinip, boynuna sarılacağım

Anlamıyor musun? 

Sana çok alıştım, sensiz yapamıyorum

Kimse senin yerini doldurmuyor.

Kimse senin bana verdiğin değeri vermiyor.

Kimse senin beni dinlediğin gibi dinlemiyor.

Kimse senin gibi benimle ağlayıp, benimle gülmüyor.

Dedim ya; seni çok özleyeceğim

Sen dönene kadar kimseyle konuşmayacağım

Fırçayı aldım elime tuvale senin resmini çizeceğim

Kalemi aldım elime satırlara senin yokluğunu yazacağım

Sensiz yapamam, sensiz olamam diyorum anlıyor musun? 

Söyle ne yapabilirim gitmemen için

Söyle ne yapabilirim benimle kalman için

Ne olur gitme, yalvarıyorum sana gitme

Ufaklığın dediği gibi ''gidemezsin no '' demek istiyorum

Ama anlamıyorsun beni...

Kafaya koymuşsun bir kere gitmeyi

Birazdan o kapıdan çekip gideceksin

Git, git, git artık yolun açık olsun.

Ben geri döneceğin günü bekleyeceğim

Döndüğün de seni eskisinden daha çok seveceğim', '(Yağmur tanesine...)  Ne çok seviyorsun bana acı çektirmeyi Birazdan o kapıdan çekip gideceksin Geride bir tek ben ve o kahrolası yalnızlığı...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/birazdan-o-kapidan-cekip-gideceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evim Evim Güzel Evim', 'evim-evim-guzel-evim-esma-ozdemir-qxiyh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güzel bir yaşantın yoksa

Güzel bir evin olsun

Beyaz çamaşırlara asılı

Mandal gibi sıkı düşlerin...

Tapusu olmasın, ne çıkar? 

O güzel evin

Kiracısı olursun.

Bahçesi yoksa üzülme

Nasıl olsa vardır

Balkonda yetişecek

Saksı saksı çiçeklerin.

Pencerelerinde 

Beyaz panjurları yoksa

Beyaz tül perdelerin olsun.

Koltukların olmasın da

Bir küçük kanepesi olsun.

Karyolan, yoksa hazır yatağın...

Vardır başını koyacağın küçük

Bir yastık ve döşeğin.

Bir evin olsun

İster kira, 

İsterse gecekondu...

İster köhne bir yapı

İsterse acar yeni olsun; 

Yeter ki 

Tek başına

En güzel hayalleri kurabileceğin

Küçük, mutlu bir köşen olsun.

Nerede, nasıl, 

Ne şekilde yaşadığının

Ne önemi var ki! 

Tepeni örtecek bir çatın, 

Gönlünde yemyeşil umutların, 

Koynunda sakladığın

Altın kaplı düşlerin, 

Ağzında incili sözlerin, 

Ve kalbinin içinde, 

Ruhunun derinliklerinde, 

Herkesten sakındığın, 

Ve, günden güne

Büyütüp beslediğin, 

Kendine ve 

Sevdiklerine yetecek kadar 

Büyük

Huzurun olsun.

Bil ki, o zaman

Dünyanın en mutlu

En rahat insanısın

Sevgili dostum!', 'Güzel bir yaşantın yoksa Güzel bir evin olsun Beyaz çamaşırlara asılı Mandal gibi sıkı düşlerin... Tapusu olmasın, ne çıkar?  O güzel evin K...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/evim-evim-guzel-evim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ses', 'ses-mustafa-i-lhan-guldemir-t5cje', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ses gelmiyor artık

Ne kalemden, 

Ne yürekten

Her nedense bilmem

Yazmıyor kalemim

Küstü yine kalbim

Her nedense bilmem

Sıkıntıdan daraIdım

Gelmiyor ilham

Kendimi zorluyorum

Tekrar şair olamıyorum

Bittim artık biliyorum

Böyle devam ederse 

Bu hayattan bende gidiyorum..', 'Ses gelmiyor artık Ne kalemden,  Ne yürekten Her nedense bilmem Yazmıyor kalemim Küstü yine kalbim Her nedense bilmem Sıkıntıdan daraIdım Ge...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İlhan Güldemir']::text[], 8.5, '{"poet":"Mustafa İlhan Güldemir","poet_slug":"mustafa-i-lhan-guldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ses-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nar', 'nar-mustafa-tanrikulu-gvyzp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'esip rüzgar kalb-i narinime bıraktı nar

aşk denilen siması ile kalbimi yaktı nar

bir defacık baktım o dildârın nûrlu gözlerine 

bir defada gözlerinden gözlerime aktı nar 

kalbime girdiği o mes''ut gün oydu kalbimi   

o ne şiddetti ya Rabbim? sanki bir bıçaktı nar

hakikat şudur:aşk ateşi kırmızı değildir

-ki benim kalbime girdiği zaman aktı nar                                           

esrarına ehl-i dehrin akl û fikri erişmez

onlara sorarsan hasm-ı mutlaktı nar

onlar haberdâr değildir ateşin bin yüzünden 

yerine göre su yerine göre topraktı nar', 'esip rüzgar kalb-i narinime bıraktı nar aşk denilen siması ile kalbimi yaktı nar bir defacık baktım o dildârın nûrlu gözlerine  bir defada g...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sever', 'sever-mustafa-tanrikulu-nzi7f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'canı kim cananı için sevse cananın sever

canı için kim ki cananın sever canın sever*

kalbi aşkın ateşiyle yanan kimseler ise 

bir yar için sineden yükselen figanın sever

hakikî âşık cananın o kadar çok sever ki 

yare bir söz dahi söyleyenin ziyanın sever

aşkı gizli yaşamanın  da tadı var amma 

âşık yine de cananın apaçık beyanın sever

âşıklar her biri elbet sever gayrı gayrı yar

mustafa ancak nuranî-çeşm nun u dal''ın sever

*:bu beyit  fuzuli hazretlerine  aittir', 'canı kim cananı için sevse cananın sever canı için kim ki cananın sever canın sever* kalbi aşkın ateşiyle yanan kimseler ise  bir yar için s...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sever-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çeşm-i Yâr', 'cesm-i-y-r-mustafa-tanrikulu-br40k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'nurlu gözlerinde koca bir alem hâfidir

ve malumumdur kalbin nur gibi sâfidir.

birer süreyya gibi parlıyor o gözlerin

bir bakışın dahi ölmem için kâfidir. 

faydalısın ferseng  ferseng ırak da olsan 

yaşaman bile hayatım için pek nâfidir.

sen varlığınla bana dayanak, barınaksın 

kalbim kalbine  dost, kalbin kalbime  müdâfidir.', 'nurlu gözlerinde koca bir alem hâfidir ve malumumdur kalbin nur gibi sâfidir. birer süreyya gibi parlıyor o gözlerin bir bakışın dahi ölmem ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cesm-i-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...İki Kere İki...', 'i-ki-kere-i-ki-naime-erlacin-cqf5t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'filizlendi aşkın buğday teni

korkma rüzgârdan tipiden

sana bir tebessüm verdi ey! 

narin 

ipincecik 

hüzünden

“sevmek iki kez yaşamak”* öyle mi 

kovalama düşleri ne olur 

düşsüz kalıp da ne yapacaksın

sen düşlerde yaşayansın

“yine de bir iştir beklemek”**

yanık teninde kavurucu aşkın

kokuda, rüzgârda savrularak 

ölümden iyidir beklemek

sen 

acıda çoğalansın 

acıdır acıda aşk 

iki kere iki 

dört kez 

yaşayarak 

                        …………….

(*)         George Sand

(**)        Cesare Pavese

(11 Temmuz 2003)', 'filizlendi aşkın buğday teni korkma rüzgârdan tipiden sana bir tebessüm verdi ey!  narin  ipincecik  hüzünden “sevmek iki kez yaşamak”* öyle...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/iki-kere-iki-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşündüm Gece', 'seni-dusundum-gece-mustafa-i-lhan-guldemir-zxg0g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni düşündüm dün gece

Su gibi azizdin bence

Güzeldi sensiz meyhane

Yavaş, yavaş giderken eve

Düştün aklıma yine 

Zordu sensiz mey, 

Zordu sensiz eğlence.

Yine seni düşündüm

Odamda bütün gece 

Gece kadar derindin bence

Seni aradım kadehlerde 

Bu sır ne kadehte, ne bende, 

Bu mey sensiz bedende 

Ne meşk eder, ne neşe...', 'Seni düşündüm dün gece Su gibi azizdin bence Güzeldi sensiz meyhane Yavaş, yavaş giderken eve Düştün aklıma yine  Zordu sensiz mey,  Zordu s...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İlhan Güldemir']::text[], 8.5, '{"poet":"Mustafa İlhan Güldemir","poet_slug":"mustafa-i-lhan-guldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-dusundum-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demirci', 'demirci-bekir-gedikoglu-dgm2y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Açmıştı

Sabahleyin dükkanını demirci

Katıksız

Masmavi bir günde

Evvela bir sağa sonra da sola döndü

Baktım ki emektar dostu çekici

Eelinde göründü

Sonra ağlar gibi gözleri sulandı

Belli ki gözlerine dolan kömür tozlarından olacaktı

Isıttığı demire tav gelmiş olacaktı

Kıskacı ile tuttuğu demiri örsün üzerine aldı

Çekiç sesleri dükkan  içini çınlattı

DAN dan,  DAN dan,  DAN dan 

Sokuldum yanına yavaştan, yavaştan

Söz alarak başladım ben şundan bundan

“ Kaç yıldır demircisin ey büyük usta “ dedim

Hemen konuşamadı, birazcık soluklandı

Bir bakışı var ki yorgun,  argındı

Biraz nefes alarak cevabı saldı

“ Bu meslek,  Baba yadigarı oldu “

Gözümüm açtığımda iş beni buldu

Hazanda dökülecek yapraklarla

Yaşım altmışı buldu “ dedi

Yaş altmış ise de,  iş bitmemiş

Demirci çalışıyordu

Bir iki dakika demeden

İşini bitiriyordu

Demirci demirleri

Her ocağa çekip çıkarışında

Ocağın ateşi bir kere horluyor

Uçurduğu kül ve korlarla

Havayı kapkara ediyordu

Demirci demiri ocaktan aldığında

Kor parçası olmuştu demir ocakta

Önce bir mana etmeyen bu demir

Sonra çekiç darbeleri ile şekillenir

En sonunda birde su verilir

Satılacak mal haline gelir

Ama, ya bundan önce

Demirci her çekiç vuruşunda

Gençliğinin gittiğini belirten ıhh,  ıhh

Sesleri çıkıyordu ağzından

Bazen de çekicin ağzı

Kızgın demirlere vurmaktan ısınmış olacaktı

Ve o zaman demirci

Kürüne soktu tuttuğu çekici

Vurduğu çekiçten akan sular

Kızgın demir üstünde

Ancak bir an durdu

Demircinin yüzünde beliren derin çizgiler

Belli ediyordu

Yılların verdiği mutluluğu

Ya, ya ellerinde

Neler ifade edecek çizgiler

Bu is pas arasında kaybolup gitmişler

Gene de ellerindeki nasırlar

Bu ellerin yıllarca

Çekiç tuttuğunu anlatırlar

Ayakkabısı, pantolonu, çorabı

İs, pas ve kömür tozlarının içinde kaybolmuşlardı

Bu saydığım bazı, bazı yerlerde

Kızgın demirlerin bıraktığı 

İzler kalmıştı

Saçlarının  üstüne kar yağmıştı kar! 

Bu karlar simsiyah karlar

Kömür tozlarıydı

Zaten saçları da zeytin karasıydı 

Eğer dikkatli bakmaksanız

Ayıramazdınız bu iki karayı

Bu  adamın dükkanı

Çilingir, demirci dükkanı

Dükkanın önünde var bir tabelası

DEMİRCİ....................................

Tirebolu,3 Şubat 1971', 'Açmıştı Sabahleyin dükkanını demirci Katıksız Masmavi bir günde Evvela bir sağa sonra da sola döndü Baktım ki emektar dostu çekici Eelinde g...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/demirci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Aldattın', 'nasil-aldattin-mustafa-i-lhan-guldemir-d7jjp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Görünce seni koptu fırtına 

Saygı duydum hayata, yaşama.

Eğildim ulu Tanrıya, 

El açtım seni bağışlasın, 

Yalvardım benim olasın diye.

Kim demiş verir isteyince, 

Hani nerdesin, istedim ölesiye, 

Neden göndermedi isteyene.

Yoksa sen mi atlattın

Hem beni, hem tanrıyı, 

Engel olan mı var gelmene

Yoksa seveni bilmezmisin, 

Ya''da sevgisiz, duygusuzmusun

Hani sevgiyi, seveni arıyordun

Hani vefasız değil, sevgi doluydun

Nasıl aldattın hem beni, hem tanrıyı

Nasıl yıktın sana olan aşkımı, 

Neden ağlattın aşığını, 

Neden dindirdin sevgi rüzgarımı.

Nasıl başardın durdurmayı

Sana doğru esen aşk fırtınamı.', 'Görünce seni koptu fırtına  Saygı duydum hayata, yaşama. Eğildim ulu Tanrıya,  El açtım seni bağışlasın,  Yalvardım benim olasın diye. Kim d...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İlhan Güldemir']::text[], 8.5, '{"poet":"Mustafa İlhan Güldemir","poet_slug":"mustafa-i-lhan-guldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nasil-aldattin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Albüm', 'album-filiz-kurun-lm89a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüzüme bak dedim

Başı öne eğikti

Bakamam dedi

Ben yüzünü kaldırdım

İnci tanesi yaşlar

Yüzünü ıslatmıştı

Belli ki o da sevdaya kapılmıştı

Hadi anlat dedim

Anlatamam çok uzun

Zamanımız bol dedim

Nasıl geçecek böyle

Mapushane günleri

O anlattı ben dinledim

Günlerce sürdü hikayesi

Anlatırken kendimi zor tuttum

Saatleri, günleri unuttum

Bir insan bu kadar zor

Yaşayabilirmiydi hayatı

Bu hayatımın vesikalık fotoğrafı dedi

Bir de albümü görmelisin

(14.06.01)', 'Yüzüme bak dedim Başı öne eğikti Bakamam dedi Ben yüzünü kaldırdım İnci tanesi yaşlar Yüzünü ıslatmıştı Belli ki o da sevdaya kapılmıştı Had...', ARRAY['Türk Edebiyatı','Şiir','Filiz Kurun']::text[], 8.5, '{"poet":"Filiz Kurun","poet_slug":"filiz-kurun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/album-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Ankara', 'sensiz-ankara-mehmet-erdogdu-mozw3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Demli bir çay tadında

Acı tütünün yoldaşlık ettiği

Hüzünlü bir Ankara akşamı

Ve yağmur yağıyor

Burnumda şarabii toprak kokusu

Hasret

Tıpkı İstanbul gibi

Çok bilinmeyenli bir denklem

Girdabına kapılırken hayatın

Düşlerden umutlardan

                            senden uzak

Senden güzel gözlerinden uzak

Gelde çöz bu denklemi

Çözebilirsen...

Şimdi ankara sokakları

Islak

Ve yorgun

Şimdi Ankara sokakları

Soluk resimler gibi

Ben ise hüzün giyinmişim

Tıpkı yağmurlu gecelerde

İstanbul gibi

Seni mi arıyorum boş sokaklarda

Kendimden bir izmi? 

Seni mi kaybettim karanlık dehlizinde ömrümün

Kendimi mi? 

Bilmiyorum.

Belki çıkıp gelsen ansızın

Düzelir herşey diyorum

Gelmeyeceksin biliyorum

Ankara hep öksüz kalacak

Ankara hep yokluğuna ağlayacak

Kabullenemiyorum.

Kapanıp işte böyle daracık odama

Penceremden yağmuru seyrediyorum

Bak! Bahar geldi Mimoza

Son bir umutla

Bahçemde açmanı bekliyorum...

                                                    (2 / 4 / 2003-Ankara)', 'Demli bir çay tadında Acı tütünün yoldaşlık ettiği Hüzünlü bir Ankara akşamı Ve yağmur yağıyor Burnumda şarabii toprak kokusu Hasret Tıpkı İ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Erdoğdu']::text[], 8.5, '{"poet":"Mehmet Erdoğdu","poet_slug":"mehmet-erdogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sensiz-ankara-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-filiz-kurun-yx2cm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdaya susamışım  yıllar yılı

Susuz yaşanmaz derler ya 

Aşksız da yaşanmaz elbet

Seni sevene bir tebessüm et

Sevmeyene eyvallah

Bir gün önüne çıkar inan 

İnan ki umutla yaşa.

(13.06.01)', 'Sevdaya susamışım  yıllar yılı Susuz yaşanmaz derler ya  Aşksız da yaşanmaz elbet Seni sevene bir tebessüm et Sevmeyene eyvallah Bir gün önü...', ARRAY['Türk Edebiyatı','Şiir','Filiz Kurun']::text[], 8.5, '{"poet":"Filiz Kurun","poet_slug":"filiz-kurun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umut-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anti Hijyen', 'anti-hijyen-mehmet-erdogdu-k394k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şimdi anlıyorum ki

Okadar da pürüzsüz

Okadar da temiz

Olmak zorunda değiliz

Azıcık bulaşmalı çamur

Pantolunumuzun paçalarına

 Ve azıcıkta kötü kokmalıyız

Enaz çöpçüler kadar

Ve tinerci çocuklar gibi

Yarı sarhoş

                          (Eylül 2002- İstanbul)', 'Şimdi anlıyorum ki Okadar da pürüzsüz Okadar da temiz Olmak zorunda değiliz Azıcık bulaşmalı çamur Pantolunumuzun paçalarına  Ve azıcıkta kö...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Erdoğdu']::text[], 8.5, '{"poet":"Mehmet Erdoğdu","poet_slug":"mehmet-erdogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/anti-hijyen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Deniz Akşamı', 'bir-deniz-aksami-bekir-mutlu-gokcesu-ntvjk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Buram, buram deniz akşamı,

bir balık kıpırtısı içlerimizde.

Sahile kurduk masayı

e tabi açtık koca rakıyı

deniz geldi ayaklarımıza

buyur ettik soframıza.

Bir sohbet, bir muhabbet

ardından başladı fasıl,

eski şarkılardan geçtik,

yıldızlar toplandı başımıza

deniz coştu, biz içtikçe içtik.

Burnumda  denizin kokusu,

gözlerimde bir balığın pulu,

dudağımda bir tebessüm, sen

öyle kalakalmışım geceden...', 'Buram, buram deniz akşamı, bir balık kıpırtısı içlerimizde. Sahile kurduk masayı e tabi açtık koca rakıyı deniz geldi ayaklarımıza buyur ett...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-deniz-aksami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çatamıyorum', 'catamiyorum-yusuf-pangal-cvkmo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dilin söylese de bir başka adı 

Resmini öpmeden yatamıyorum 

Her an taşıdığım gizli muradı 

Üstümden bir türlü atamıyorum 

Çok büyük lütuftun, büyük hediye 

Hiçbir şey demeden terkettin, niye? 

Beddua yerine geçecek diye 

İnsafsız feleğe çatamıyorum 

Hayat pınarımdan içseydin abı 

Doldururdum yine boşalan kabı 

İçtiğin ömrümden kalan şarabı 

Utanırsın diye satamıyorum 

Rafın üstü bütün örümcek ağı 

Diyorum, öpmüştü onun dudağı 

Çok sevdiğim halde canım bardağı 

Kırılırsın diye tutamıyorum 

Gittin ya unuttum, mutlu olmayı 

Zindanda geçirdim sanki bir ayı 

Giderken içtiğin son demlik çayı 

Bardağa bir türlü katamıyorum', 'Dilin söylese de bir başka adı  Resmini öpmeden yatamıyorum  Her an taşıdığım gizli muradı  Üstümden bir türlü atamıyorum  Çok büyük lütuftu...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pangal']::text[], 8.5, '{"poet":"Yusuf Pangal","poet_slug":"yusuf-pangal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/catamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-yusuf-pangal-2476k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mecnun başka şeye ağlardı sanma 

Leyla''nın yerine kimse konmadı 

Her derdin çaresi bulundu amma 

Aşığın yarası hiç kapanmadı 

İçine düştü mü tuttuğu ferdin 

Çilesi aynıydı  merdin, namerdin 

Aklını zay edip, bu garip derdin 

Peşine düşenler geri dönmedi 

İster alim olsun isterse dağlı 

Eli kelepçeli; gözleri bağlı 

Başka bir kederden Adem''in oğlu 

Gördüğü civcivi tavuk sanmadı 

Gönül tarlasına hüzün ekmeyen 

Aşk narına yanıp sevda çekmeyen 

Çok söz işetse de  bülbül dilinden 

Duyduğu yalana hemen kanmadı 

Özenle baktığı gülü solsa da 

Ömründen her anı zaman çalsa da 

Terk etse dostları, yalnız kalsa da 

Çölün ortasında kimse donmadı 

Her zaman böyledir sevenin hali 

Yanılır, inanır, buzkeser eli 

Hararet bastı mı kurutur gölü 

İnsan başka şeyden böyle yanmadı', 'Mecnun başka şeye ağlardı sanma  Leyla''nın yerine kimse konmadı  Her derdin çaresi bulundu amma  Aşığın yarası hiç kapanmadı  İçine düştü mü...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pangal']::text[], 8.5, '{"poet":"Yusuf Pangal","poet_slug":"yusuf-pangal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ask-160-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haydut', 'haydut-mehmet-tombuloglu-1c673', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kimi zaman derin kuyular açıyorum

acıdan süzülmüş yüreğime; sustukça birikiyor

biriktikçe çekiyorum arınmış suyunu

parmaklarımın hünerini sınayan bu maceram

bir haydut gibi yakıp meşalesini, ilerliyor

defterimin gizli geçitlerinde; ışığından köprüler kurarak 

ey eşsiz hazinesi (ya) saklı yanımın! 

gün gelir, belki saçılırsın diye dizelerin arasına

aç kurtlar gibi sığındım toprağına

oradan uzandım imlere; onların dilimdeki aksine 

istedim ki nuru sönmesin ufkumun

geçmiş zaman efsanesi gibi, benden çok uzak olsun

eskiden beri sokağa dalgın çıktığım akşamlar', 'kimi zaman derin kuyular açıyorum acıdan süzülmüş yüreğime; sustukça birikiyor biriktikçe çekiyorum arınmış suyunu parmaklarımın hünerini sı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tombuloğlu']::text[], 8.5, '{"poet":"Mehmet Tombuloğlu","poet_slug":"mehmet-tombuloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/haydut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuna Düşse', 'tuna-dusse-yusuf-pangal-w71rs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şah otağı dört bir yandan vuruldu 

Ilgıt ılgıt akar al kan, bizimdir 

Kahpe düşman, gücümüz mü kırıldı? 

Kılıç düşse elde kalkan bizimdir 

Tuna boylarında erler dövüşür

Nice paslı kılıç kanla sevişir

Yiğit can verirken namert sıvışır

Şehit olup göğe kalkan bizimdir

Emanettir bizde, canlar Allah''a 

Yolumuzda yer yok:figana, aha 

Geceler mutlaka varır sabaha 

Tuna düşse; yine Balkan bizimdir', 'Şah otağı dört bir yandan vuruldu  Ilgıt ılgıt akar al kan, bizimdir  Kahpe düşman, gücümüz mü kırıldı?  Kılıç düşse elde kalkan bizimdir  T...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pangal']::text[], 8.5, '{"poet":"Yusuf Pangal","poet_slug":"yusuf-pangal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tuna-dusse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayali Sevgili', 'hayali-sevgili-hikmet-yakisir-0pk35', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle bir sevgili olmalı ki...

Uzaklarda bile olsa.

Mesafeleri dert etmeyen, 

Yanı başında hisseden.

Mesafelerin kilometreler olmadığını, 

Beyinler arasındaki mesafelerin 

Uzaklaştırdığını bilmeli sevgilileri.

Öyle bir sevgili olmalı ki... 

Seveceğim.

Beyinlerin anlaştığı tenlerin uyuştuğu

Mesafeleri sorun etmeden sevecek

Yanı başımda gibi hissettirecek.

Aradaki kilometrelerin hasreti ile, 

Özleyen biri olmalı.

Öyle bir sevgili olmalı ki...

Özleyen

Kavuşma anı geldiğinde

Özlemden bahsetmemeli.

Sarılarak, öperek hissettirmeli, 

Gözleri, elleri, teni söylemeli, 

Ne kadar çok özlediğini. 

Öyle bir sevgili olmalı ki...

Özlenen.

Öpüşleri yakmalı dudaklarımı.

Teni kavurmalı bedenimi.

Aşk ateşi ile yakmalı, 

Sevda denizinde boğmalı beni.

Böyle biri olmalı.

(05 Temmuz 2003)', 'Öyle bir sevgili olmalı ki... Uzaklarda bile olsa. Mesafeleri dert etmeyen,  Yanı başında hisseden. Mesafelerin kilometreler olmadığını,  Be...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yakışır']::text[], 8.5, '{"poet":"Hikmet Yakışır","poet_slug":"hikmet-yakisir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hayali-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümsüz Aşk', 'olumsuz-ask-hikmet-yakisir-qn938', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne sevgiydi yaşadığımız, 

Sarıldık mı birbirimize, 

Ayrılmak aklımıza gelmezdi.

Koklaşırdık uzunca, 

Öpüşürdük dakikalarca.

Nasıl bir aşktı bu, 

Var mı böyle bir sevgi.

Bilemiyorum.

Ölümsüz aşk gibi.

Ömürlük bir aşktı bizimkisi, 

Hiç bitmeyecekmiş gibi.

Doyasıya yaşadık, 

Ölümsüz aşk gibi.

Kalbimizle, 

Beynimizle, 

Ruhumuzla.

Doymak bilmeyen iki kişi, 

Sevgiye ac, 

Aşka muhtaç.

Bitmeyecekmiş gibi hoyratça

Kullanmıştık o cümleyi.

Seni Seviyorum diye.

Hiç tükenmeyecekmiş gibi, 

Sunuyorduk sevgimizi.

Ölümsüz bir aşkla.

Işıl ışıl gözlerimiz, 

Delice çarpan kalbimiz.

Bitmesini istemediğimiz.

Ne geceler yaşadık biz.

Yıldızlar şahidimiz.

Ve gün geldi tükendi, 

Bitmeyecek sandığım sevgisi.

Başkası oturdu belki, 

Kalbindeki taht’a 

Seni seviyorum cümlesi, 

Anlamını yitirmişti onun için.

Ara sıra kullansak da, 

Sarılsak da.

Eski hazzı duymasak da, 

Benim için bitmedi, 

Hiç bitmeyecek, 

Ölümsüz aşk bu.

(08 Temmuz 2003)', 'Ne sevgiydi yaşadığımız,  Sarıldık mı birbirimize,  Ayrılmak aklımıza gelmezdi. Koklaşırdık uzunca,  Öpüşürdük dakikalarca. Nasıl bir aşktı ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yakışır']::text[], 8.5, '{"poet":"Hikmet Yakışır","poet_slug":"hikmet-yakisir","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/olumsuz-ask-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Armağan', 'armagan-galip-ozdemir-p9nb2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ben sana 

bir yalnızlık

bir hüzün yollayayım

sen bana 

bir ince gülüş yolla

ben sana

bir Yılmaz Güney duruşu yollayayım

-boynu bükük-

sen bana

bir şiir atlasının içinde

elini yolla

ben sana

soru işareti yollayayım

sen bana 

ünlem yolla', 'ben sana  bir yalnızlık bir hüzün yollayayım sen bana  bir ince gülüş yolla ben sana bir Yılmaz Güney duruşu yollayayım -boynu bükük- sen ba...', ARRAY['Türk Edebiyatı','Şiir','Galip Özdemir']::text[], 8.5, '{"poet":"Galip Özdemir","poet_slug":"galip-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/armagan-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşlar', 'kuslar-galip-ozdemir-2v8qc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kuşlar süzülüyordu

Mavilerin kesiştiği yere

Yaz aşkları taşıyorlardı

Yorgun kanatlarında

Ve herbiri vurulup düşüyordu

Mavilerin derinliklerine

Kızıllanıyordu gözlerim

Herbiri vurulup düşüyordu

Minörlerin hüzünlerine

Ve –yerleşik- bir martı viyolensel çalıyordu

Ben, kıyısında kavruk bir denizin

çırıl çıplak ceplerimde 

kalbimi arıyordum.', 'Kuşlar süzülüyordu Mavilerin kesiştiği yere Yaz aşkları taşıyorlardı Yorgun kanatlarında Ve herbiri vurulup düşüyordu Mavilerin derinlikleri...', ARRAY['Türk Edebiyatı','Şiir','Galip Özdemir']::text[], 8.5, '{"poet":"Galip Özdemir","poet_slug":"galip-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kuslar-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Faili Malûm', 'faili-mal-m-galip-ozdemir-dnpdw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sen 

mutsuz sevdaların militanı

beni pera’da vurmalıydın

tek kurşunla

ve yağmur yağmalıydı

sana fulya demeti sunarken

venseremos’u söylemeliydi sokaklar

ve kalbimde ağlamalıydı ay carmella

sen bir keman solosu geçmeliydin

biracı’da terasta vurmalıydın beni

serhoş olmalıydım adam akıllı

ve bir şilep geçmeliydi boğazdan

tek kurşunla vurmalıydın beni

kızkulesi sulietinin önünde

sonra birlikte yakmalıydık ağıtlarını', 'sen  mutsuz sevdaların militanı beni pera’da vurmalıydın tek kurşunla ve yağmur yağmalıydı sana fulya demeti sunarken venseremos’u söylemeli...', ARRAY['Türk Edebiyatı','Şiir','Galip Özdemir']::text[], 8.5, '{"poet":"Galip Özdemir","poet_slug":"galip-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/faili-malum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-galip-ozdemir-kjdxr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'seni her buluşumda 

kente yağmur yağardı

ben sarhoş olurdum

belki 

bu yüzden sevdim bu kenti

bir de seni

vefasız olsan da seni

ayazda titreyen

yağız bir türküde buluşurduk

-kente yağmur yağardı-

sonra çelimsiz bir çocuğun kara bahtında

sonra isyanlarda

ve sürgünlerde…

kente yağmur yağardı

üşürdü senin ellerin

benimse yüreğim

sen 

yıldızlar gizlerdin düşlerinde 

bu yüzden

kente yağmur yağardı

kente yağmur yağardı

dökülürdü boyaları maskelerin

ben ağlardım

biraz daha yitirirdim seni

boynu bükülürdü fulyaların 

ve ben 

bir gece daha alacaklı olurdum kentten

kente yağmur yağacak

ben sarhoş olacağım

kente yağmur yağacak

üşümeyecek ellerin

kente yağmur yağacak

boynumda titreyecek nefesin

ve sen gelmeyeceksin', 'seni her buluşumda  kente yağmur yağardı ben sarhoş olurdum belki  bu yüzden sevdim bu kenti bir de seni vefasız olsan da seni ayazda titrey...', ARRAY['Türk Edebiyatı','Şiir','Galip Özdemir']::text[], 8.5, '{"poet":"Galip Özdemir","poet_slug":"galip-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yagmur-79-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bozlak', 'bozlak-galip-ozdemir-h61ub', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kuzey tanrılarınca

deport verilmiş bir deniz sürgünüyüm

hayal dünyasının kehkeşanında

recmedilmiştir sevdam

ve serapların sırsız aynalarında

susuzluğumun dudak izleri kanar rûyalara

sunaklarda çınlar kalbimin sesi

                    duyulur dokuz gökte

                                duyulur suda, havada

                                             ve toprakta ve ateşte

ah benim sevdam

     yol kenarlarında makam taşıdır şimdi

           masallar ağladıkça yosun tutan

ve kan sızar

     geçen yıldız yolcularının attığı her taştan

atılan her taştan su yürür özüme

          bir bozlaktır sesim 

                             dağlarda ve koyaklarda

ah benim sevdam

    bir korsan ganimeti

          benim kırık pusulam

ah, beni dalgalarda assınlar

ve kalbimin ritmiyle

     geçip dursun içimde

                geçip dursun siya siya

                           limansız forsalar', 'kuzey tanrılarınca deport verilmiş bir deniz sürgünüyüm hayal dünyasının kehkeşanında recmedilmiştir sevdam ve serapların sırsız aynalarında...', ARRAY['Türk Edebiyatı','Şiir','Galip Özdemir']::text[], 8.5, '{"poet":"Galip Özdemir","poet_slug":"galip-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bozlak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık İkindiler', 'kirik-i-kindiler-galip-ozdemir-k39ca', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'parke taşlarında çınlayan

nal seslerini duyuyor musun

geçen her faytonun içinde ben varım

sivas kalesi’nde 

kırık ikindilere, 

yalnızlıklara sığınan 

ey kalbim! ...

akasyalar sonbahar türküleri söylemekte

tatlısu keşiklerinde bir çocuk unutulmuş

sırtı dönüktür kente

cıbıllar parkı’nda 

salkımsöğüdün altındaki tahta masada

iki bardak çay durur

dumanı tütmektedir hâlâ…', 'parke taşlarında çınlayan nal seslerini duyuyor musun geçen her faytonun içinde ben varım sivas kalesi’nde  kırık ikindilere,  yalnızlıklara...', ARRAY['Türk Edebiyatı','Şiir','Galip Özdemir']::text[], 8.5, '{"poet":"Galip Özdemir","poet_slug":"galip-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kirik-ikindiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nostalji', 'nostalji-galip-ozdemir-5wb64', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabahlara sakladığım yıldızlar da düşecek

Belki bir sığırtmacın kalbine

Belki yolum yine patikalara düşecek

Vuracaklar beni bir papatya bahçesinde

İklimsiz bir çocuk sırtını dönecek', 'Sabahlara sakladığım yıldızlar da düşecek Belki bir sığırtmacın kalbine Belki yolum yine patikalara düşecek Vuracaklar beni bir papatya bahç...', ARRAY['Türk Edebiyatı','Şiir','Galip Özdemir']::text[], 8.5, '{"poet":"Galip Özdemir","poet_slug":"galip-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/nostalji-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedel', 'bedel-yavuz-turhan-ymk36', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir hayali gerçeğe dönüştürme çabası içinde, 

hayatımızdan yaptığımız tüm harcamalar, 

(Ruhsal-tensel-zaman) ...

bir bedeldir.

Akıp giderken yaşam, 

karşına çıkmıyorsa hayallerin, 

korunmasızsan her köşe başında, 

bir kuşun kanat çırpışları ürpertiyorsa seni, 

tenin bir sıcaklığı arıyorsa, 

ve..yoksa..yalnızsan

Gözden geçirmelisin hayatı

hayalleri...', 'Bir hayali gerçeğe dönüştürme çabası içinde,  hayatımızdan yaptığımız tüm harcamalar,  (Ruhsal-tensel-zaman) ... bir bedeldir. Akıp giderken...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Turhan']::text[], 8.5, '{"poet":"Yavuz Turhan","poet_slug":"yavuz-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bedel-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yana Yana', 'yana-yana-galip-ozdemir-mkks9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İstanbul bir martı uykusunda

Dağlanmış sesimi arıyorum,

Kör duvarlarda

Yana yana..

Islık çalıyor

Bir yalnızlık

Kıyısında mahzun bir denizin

Yana yana...

İstanbul bir martı uykusunda

Tüm çizgilerini yitiriyor ellerim; 

Dokunuyorum sessiz yıldızlara,

Sokuluyorum yoldaşlara

Kör duvarlarda

Yana yana...

Ve gözleri çöl oluyor annelerin

Sessiz yıldızlara

Yana yana...', 'İstanbul bir martı uykusunda Dağlanmış sesimi arıyorum, Kör duvarlarda Yana yana.. Islık çalıyor Bir yalnızlık Kıyısında mahzun bir denizin ...', ARRAY['Türk Edebiyatı','Şiir','Galip Özdemir']::text[], 8.5, '{"poet":"Galip Özdemir","poet_slug":"galip-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yana-yana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Tehlikeli Bir dygu Demiştin', 'ask-tehlikeli-bir-dygu-demistin-bir-tanem-qy3z7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk tehlikeli bir duygu demiştin..

Ama sevgi masum..

Aşk ile nefret arasındaki ince çizgiden bahsederken de, 

Sevginin sonsuzluğundan söz etmiştin..

Bedenimde bu sözler yankılanırken seni ilk gördüğüm 

An hiç çıkmıyor aklımdan! ''

Çok sevenim oldu, çok ahlar aldım, 

Deli gönlüm hep hoştu! ama boştu''diyor en sevdiğim şarkılardan birisi..

İlk defa bir aşk bedenimde titremeye, kan basıncımın yükselmesine ve böylesine uykusuz gecelerime neden oluyor..

Beni etkileyen hiç hesapsız karşıma çıkman mı? 

Yoksa bunların hepsi planlımıydı..

Yoksa yoksa sen..

Hani o hiç tanımadığım adına şarkılar yazdığım 

Kış güneşimmiydin yoksa yakamozummuydun? 

Benim duygularıma cevap verebilirmisin? 

Yoksa hiç bilmediğin birşeymiyim ben..

Bu yazıyı yazıyorum, neden? 

Sana alıntı birşeyler gönderebilirdim.

Ama denedim! bir kere olsun kendime bile doğru dürüst 

 

Hani şu bir şeyler eksik bir şeyler fazla...

Hatırladın mı? ya..

İnan ben seni çok seviyorum.

Gecenin bir yarısı yollara düşecek kadar..

Yaslanıp omuzlarına, KIZIL saçlarına bağlayıp

Gönlümü sonsuza dek ağlayıncaya kadar

GUZEL kara GOZLERINI SEYRETMEK İSTİYORUM

 ÇOK SEVİYORUM SENİ...ben!', 'Aşk tehlikeli bir duygu demiştin.. Ama sevgi masum.. Aşk ile nefret arasındaki ince çizgiden bahsederken de,  Sevginin sonsuzluğundan söz et...', ARRAY['Türk Edebiyatı','Şiir','Bir Tanem']::text[], 8.5, '{"poet":"Bir Tanem","poet_slug":"bir-tanem","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ask-tehlikeli-bir-dygu-demistin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hain Papatya', 'hain-papatya-hikmet-yakisir-9egbl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevmek güzel, 

Bir anda dünyan değişir, 

Hayatının akışı güzelleşir.

Pembe bulutlarda gezinmek, 

Toz pembe görmek her şeyi.

Aldığın nefeste, 

İçtiğin suda, 

Yediğin yemekte, 

Hayatının her anında, 

Hissetmek, düşünmek birini.

Sevilmek güzel, 

Bir sevgili tarafından 

Ay olup gecelerini aydınlatmak, 

Güneşi olup ısıtmak, 

Denizi olup kucaklamak, 

El ele, göz göze, 

Bulutlarda uçurmak birini, 

Düşünülmek, 

Hissedilmek, 

Ve bundan emin olmak.

Sevmek ve sevilmek, 

En güzel duygu, 

Sevdiğinden eminsin, 

Ya sevildiğinden? 

Boşver emin olma.

Papatyaya sığınma, 

Seviyor...Sevmiyor, 

Seviyooooorrrr...Sevmiyooooorrrr.

Hain papatya

Ne olurdu sanki, 

Bir yaprağın daha olsaydı.

Seviyor olacaktı deme.

(10 Temmuz 2003)', 'Sevmek güzel,  Bir anda dünyan değişir,  Hayatının akışı güzelleşir. Pembe bulutlarda gezinmek,  Toz pembe görmek her şeyi. Aldığın nefeste,...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yakışır']::text[], 8.5, '{"poet":"Hikmet Yakışır","poet_slug":"hikmet-yakisir","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hain-papatya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyenler İçin', 'bekleyenler-i-cin-bir-tanem-zmqwf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir ayak sesi duymayayim

Kapiya kosuyorum

Gelen sen misin diye

Bir siyah sac görmeyeyim

Yüregim burkuluyor

Aglamakli oluyorum

Her sey bana seni hatirlatiyor

Gökyüzüne baksam

Gözlerinin binlercesini görürüm

Bir rüzgar degse yüzüme

Ellerini düsünmeden edemem

Yaktigim bütün sigaralarin dumanlari sana benzer

Tadi senden gelir

Yedigim yemislerin

Ictigim ickilerin

Ve icimdeki bu dayanilmaz sIkinti

Bu emsalsiz hüzün

Seni bekledigim icindir

Resmine bakamaz oldum

Uykulardan korkuyorum artik

Utaniyorum odamdaki bütün esyalardan

Su sedir hala gelip oturmani bekliyor

Su ayna karsisinda güzelligini seyretmeni

Su kadeh dudaklarina degebilmek icin duruyor masada

Ve su saat geldigin anda

Durabilir sevincinden

Zaman cildirabilir

Cünkü benim dünyamda

Ölümsüzlük, seni sevmek demektir.

Bir cocuk dogmayi bekler

Bir agir hasta ölmeyi

Bitkiler yagmur ve günesi bekler

Yalniz bir kadin sevilmeyi

Ve düsün ki bir adam

Icinde bütün bekleyenlerin korkusu ve ümidi

Seni bekler

Asilmayi bekleyen bir idam mahkumu gibi

Sen gelinceye kadar

Pencerem kapali duracak

Rüzgar gelmesin diye

Artik perdeleri acmayacagim

Gün isigi girmesin diye

Sonra kahrolacagim

Bu karanlikta, bu derin yalnizlikta

Ve günlerce gecelerce haykiracagim

Nerdesin diye, Nerdesin? 

Bir gün bu kapidan sen gireceksin

Biliyorum

Ergec bu bekleyisin bir sonu gelecek

Yillarca sonra

Öldügüm gün bile gelsen

Bütün bu bekleyisimi ve oldugumu unutup

Cocukler gibi sevinecegim

Kalkip sarilacagim ellerine

Uzun uzun agliyacagim.', 'Bir ayak sesi duymayayim Kapiya kosuyorum Gelen sen misin diye Bir siyah sac görmeyeyim Yüregim burkuluyor Aglamakli oluyorum Her sey bana s...', ARRAY['Türk Edebiyatı','Şiir','Bir Tanem']::text[], 8.5, '{"poet":"Bir Tanem","poet_slug":"bir-tanem","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/bekleyenler-icin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değirmenimiz Var Arkımız Yok', 'degirmenimiz-var-arkimiz-yok-i-brahim-bayraktar-mknwi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Değirmenimiz var arkımız yok, 

Belediyemiz var narhımız yok, 

Toplamışız bir sürü dalkavuğu, 

Halka hizmet edecek çarkımız yok.

Esnaf beşe olanı ona satınca, 

Verilen vaatler yerini bulmayınca, 

Kırdığınız yumurta kırkı sollayınca, 

Sizi destekleyecek oyumuz da yok.

Bu gidişe yakında dur denilecek, 

Kötü olanın cezası bir gün verilecek, 

Adaletsiz iş yapana ömür boyu sövülecek, 

Eğer bunlarda bir ders vermezse, 

Size söyleyecek sözümüz de yok.

15.4.1986', 'Değirmenimiz var arkımız yok,  Belediyemiz var narhımız yok,  Toplamışız bir sürü dalkavuğu,  Halka hizmet edecek çarkımız yok. Esnaf beşe o...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/degirmenimiz-var-arkimiz-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece ve Efendisi', 'gece-ve-efendisi-ensar-cevval-n3ba5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İstanbul sokaklarında ayak sesleri

seyrekleşir, karanlığın hükümranlığında

gecenin yeni sahipleri artık meydanlarda

fahişesi, tinercisi, arsızı, hırsızı, evsizi...

dilsiz, hafızasız gecede yarı özgür adımlar, 

duyulmaz hengamesinde gündüzlerin.

Bir korku, gölge, düş gibi yaklaşan

uzaktan uzağa bir insan silueti

yaklaştıkça sisi dağıldı, İstanbul sabahı gibi

belli ki karışık düşünceli

saçına, sakalına dağıtmış serseriliğini; 

iskeleye yanaşan vapur sarsıntısından

yarı serhoş, paytak yürüyüşlü...

Kurşun yemiş ceylan sersemliğinde

düşmekten korkar gibi her düşüşünde

toparlanıyordu iki adımlık nefesle

Düştü o kuş ağırlığındaki bedeni kollarıma.

burun sızlatan bir koku yaygın üstüne

bir silgi, hafızayı bertaraf eden bir rayiha 

bir bez parçasına sarılı tiner şişesi

belli ki elindeki tek sermayesi

neyi unutmak için kokluyordu 

neyi hatırlamak istiyordu

koklarken o çaputu.

Acılarına mı direnişti yüzündeki tebessüm

Yoksa tahayyülündeki sevgili mi öpüyordu

Döndü, yüzüme baktı sessizce

çakır gözlerindeki o yorgun bakışlar

çizgi çizgi, derin yalnızlıklar barındırıyordu; 

bir anlatımlık bir sohbetti istediğim; 

cevabını bulmak için gözlerindeki pırıltının

nereli olduğumu sorarken üşüyordu

Vanlıyım.dediğimde güzel şehir dedi. 

görmüşmüydü, yoksa laf olsun muydu sözleri! ..

-Sen nerelisin? diye sorduğumda

-Kafam iyi olmaz ise hatırlarım...şeydi.! ..? 

bir sigara yaktı ve kayboldu dumanında

son kez dönüp baktı ardına ve seslendi:

-''''Her yıldız kayması ve gece bir ölüm demektir

bu yüzden gökyüzüne hiç bakmam ve  uyumam geceleri

uyanıkken görmediklerimi görmek korkusuyla.''''-

ve süklüm püklüm sefaletiyle, 

çekip gitti; gecenin kollarında.

gözlerimde bir sis bırakarak geldiği gibi.', 'İstanbul sokaklarında ayak sesleri seyrekleşir, karanlığın hükümranlığında gecenin yeni sahipleri artık meydanlarda fahişesi, tinercisi, ars...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/gece-ve-efendisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağrı', 'agri-arif-nihat-asya-2cuyn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir âbide istersen eğer, Ağrı''ya git! 

Yükseklerden gelen büyük çağrıya git! 

Çıkmışken yolcu, Ağrı''nın zirvesine, 

Dönmek ne demek? Kanatlanıp Tanrı''ya git!', 'Bir âbide istersen eğer, Ağrı''ya git!  Yükseklerden gelen büyük çağrıya git!  Çıkmışken yolcu, Ağrı''nın zirvesine,  Dönmek ne demek? Kanatla...', ARRAY['Türk Edebiyatı','Şiir','Arif Nihat Asya']::text[], 8.5, '{"poet":"Arif Nihat Asya","poet_slug":"arif-nihat-asya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/agri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayak İzleri', 'ayak-i-zleri-arif-nihat-asya-i9p4t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Varlığından şu güzel ülkeyi kurtarsak da; 

Adımından kalan izler, lekedir toprakta!', 'Varlığından şu güzel ülkeyi kurtarsak da;  Adımından kalan izler, lekedir toprakta!...', ARRAY['Türk Edebiyatı','Şiir','Arif Nihat Asya']::text[], 8.5, '{"poet":"Arif Nihat Asya","poet_slug":"arif-nihat-asya","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ayak-izleri-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balıklıgöl', 'balikligol-arif-nihat-asya-n33cv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senin ey gönül, siyah balıklarına

Yem atar yolcular, gelip, burdan

Ver derinden bakanların gözüne

Görünür bir beyaz balık, nurdan.', 'Senin ey gönül, siyah balıklarına Yem atar yolcular, gelip, burdan Ver derinden bakanların gözüne Görünür bir beyaz balık, nurdan....', ARRAY['Türk Edebiyatı','Şiir','Arif Nihat Asya']::text[], 8.5, '{"poet":"Arif Nihat Asya","poet_slug":"arif-nihat-asya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/balikligol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlara', 'daglara-arif-nihat-asya-is8a6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Doruk beyaz, dere mavi; 

Etekler, yeşil çuhadan..

Dağlar, koskoca dünyayı

İkiye böler ortadan...

Ki nesi kalır dünyanın

Dağları çeksen aradan? 

Kartal, süzülür yuvadan; 

Yuvası vardır kayadan.

Dağlarda kartopu diye

Birbirine ay atan

Kızlar... ki dudakları al...

Alları, değil boyadan.

Dağ uykulariyle mahmur

Yüzlerini, gün doğmadan, 

Seyrederler, ya suyun ya

Ayın tuttuğu aynadan.

Yaratırken şu dünyayı

Yeri, göğüyle yaradan, 

Dağı sahiden yaratmış, 

Geri kalanı şakadan! 

Kurtlarına helâl olsun

Ne alırlarsa ovadan!', 'Doruk beyaz, dere mavi;  Etekler, yeşil çuhadan.. Dağlar, koskoca dünyayı İkiye böler ortadan... Ki nesi kalır dünyanın Dağları çeksen arada...', ARRAY['Türk Edebiyatı','Şiir','Arif Nihat Asya']::text[], 8.5, '{"poet":"Arif Nihat Asya","poet_slug":"arif-nihat-asya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/daglara-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırat', 'firat-arif-nihat-asya-8xs5k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şu mavi dağların uzaklarında

Bir akar suyun adıdır ''Fırat''

Ve sevdiğim çocuğun dudaklarında

Sevdiğim bir türkünün adı...

Türkünün tadına karışır

Söyliyen dudakların tadı.

Ey beyaz çocuk, sarışın çocuk, 

Dilinde her şey güzelleşen

Cana yakın çocuk...

Kızım, kardeşim...

Günler, geceler ötesi, 

Gelirse beklediğim

Masal gecesi; 

Şu fani dünyada her murad olsun

Ve senden doğacak kızımın

Adı ''Fırat'' olsun!', 'Şu mavi dağların uzaklarında Bir akar suyun adıdır ''Fırat'' Ve sevdiğim çocuğun dudaklarında Sevdiğim bir türkünün adı... Türkünün tadına kar...', ARRAY['Türk Edebiyatı','Şiir','Arif Nihat Asya']::text[], 8.5, '{"poet":"Arif Nihat Asya","poet_slug":"arif-nihat-asya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/firat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzellik', 'guzellik-arif-nihat-asya-kt7gr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hastalık, sevgisizlik, öksüzlük...

    Neler geçirdim ben! 

Çıkabilseydi bir, ''güzel'' diyecek

    Güzelleşirdim ben!', 'Hastalık, sevgisizlik, öksüzlük...     Neler geçirdim ben!  Çıkabilseydi bir, ''güzel'' diyecek     Güzelleşirdim ben!...', ARRAY['Türk Edebiyatı','Şiir','Arif Nihat Asya']::text[], 8.5, '{"poet":"Arif Nihat Asya","poet_slug":"arif-nihat-asya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guzellik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hisse', 'hisse-arif-nihat-asya-qp5c5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Onlar, almakta parsadan hisse...

Bize kalmakta kıssadan hisse!', 'Onlar, almakta parsadan hisse... Bize kalmakta kıssadan hisse!...', ARRAY['Türk Edebiyatı','Şiir','Arif Nihat Asya']::text[], 8.5, '{"poet":"Arif Nihat Asya","poet_slug":"arif-nihat-asya","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/hisse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pazar Ola...', 'pazar-ola-suleyman-saylan-4qudj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'PAZAR  OLA...

Adaletin bir terazisi varmış

Bir zamanlar, 

Evvel zaman içinde.

Çok hassas tartarmış...

Gide gide pazara düşmüş

Bizim terazi, 

Pazarcının elire.

İşin içine girince pazarcı, 

Hile karışmış bizim teraziye.

Sütüne kalmış; 

Tek tük doğru tartsa da, 

Çoğunda eksik tartmaya alışmış

Bizim pazarcı.

Dedim ya sütüne kalmış...

Cüzdan vicdanı yenmiş, 

Rüşvet adaleti satın almış

Bizim pazarcının elinde.

Haklının hakkı da

Allah''a kalmış...

Terazinin günahı ne? 

Kabahat pazarcıda.

Haydi bakalım

Pazar ola...

Süleyman SAYLAN

(Ankara,23.07.2001, Saat: 01.07)', 'PAZAR  OLA... Adaletin bir terazisi varmış Bir zamanlar,  Evvel zaman içinde. Çok hassas tartarmış... Gide gide pazara düşmüş Bizim terazi, ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/pazar-ola-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kubbe-i Hadra', 'kubbe-i-hadra-arif-nihat-asya-qnoyu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimi, boşlukta sızar asude; 

Kimi, bekler gecelerden seheri..

Farkı yoktur gecenin gündüzden, 

Ne çıkar yanmasa ufkun feneri

Tunç taslarda içerler kaderi

Bu ecel şerbetinin bekrileri.

Kim bilir, belki giden yolcuların

Bu sefer son seferi

Sisli gözlerde cihetler silinir, 

Kimsenin kimseden olmaz haberi

Ne semavatı görürler, ne yeri

Bu ecel şerbetinin bekrileri.

İçlerinden biri vardır ki aba

Bilerek sırtına çekmiş kederi

Yolda lakin onu dimdik yürütür

Belde imanının altın kemeri

Gecenin, gölgelerin şaheseri

Bu ecel şerbetinin bekrileri.

Seslenir da’veti bir meçhulün; 

Bir nida der: İleri! 

Ki nihayet bir ilahi gecenin

Kapısından süzülürler içeri

Ve aşarlar o karanlık kemeri

Bu ecel şerbetinin bekrileri', 'Kimi, boşlukta sızar asude;  Kimi, bekler gecelerden seheri.. Farkı yoktur gecenin gündüzden,  Ne çıkar yanmasa ufkun feneri Tunç taslarda i...', ARRAY['Türk Edebiyatı','Şiir','Arif Nihat Asya']::text[], 8.5, '{"poet":"Arif Nihat Asya","poet_slug":"arif-nihat-asya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kubbe-i-hadra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-arif-nihat-asya-q76mi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Koku, tad, sıcak... sende her aradığım vardı:

Seni soğuk bulanlar, ısıtamayanlardı.', 'Koku, tad, sıcak... sende her aradığım vardı: Seni soğuk bulanlar, ısıtamayanlardı....', ARRAY['Türk Edebiyatı','Şiir','Arif Nihat Asya']::text[], 8.5, '{"poet":"Arif Nihat Asya","poet_slug":"arif-nihat-asya","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/sen-273-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigara Çeşitleri', 'sigara-cesitleri-arif-nihat-asya-g9jbd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dolup taşar camekanlarda her çeşit sigara; 

           O eskidir, bu yeni... 

''En zararlı olan, hangi cinstir? '' dersen 

           Derim: ''İçilmeyeni! ''', 'Dolup taşar camekanlarda her çeşit sigara;             O eskidir, bu yeni...  ''En zararlı olan, hangi cinstir? '' dersen             Derim: ''...', ARRAY['Türk Edebiyatı','Şiir','Arif Nihat Asya']::text[], 8.5, '{"poet":"Arif Nihat Asya","poet_slug":"arif-nihat-asya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sigara-cesitleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tepeler', 'tepeler-arif-nihat-asya-n15za', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çadırtepe, Dumlupınar, 

Türbetepe, Adatepe...

Ki üstlerinden bir bulut

Geçti güller serpe serpe.

Türbe, otağ. kubbe, eyvan...

Adları Dicle''de Seyran, 

Fırat yollarında Aslan, 

Çukurova''da Kurttepe.

Kültür, Tınaz, Dua, Fikir...

Say sayabilirsen bir bir

Kemerlerdir, kubbelerdir

Bir yeni imana gebe.

Uzar sınırlar aşırı

Tepelerin kervanları; 

Biri mordur akşamları, 

Biri şafaklarla pembe.

Süslemişler yurdu yer yer...

Ki çocuğun geçer gider

Rüzgârlar alnını, seller

Eteğini öpe öpe.

Lâle, Menekşe tepesi...

Fakat hepsinin kubbesi

Allahüekber dağında

Allahüekber tepesi.', 'Çadırtepe, Dumlupınar,  Türbetepe, Adatepe... Ki üstlerinden bir bulut Geçti güller serpe serpe. Türbe, otağ. kubbe, eyvan... Adları Dicle''d...', ARRAY['Türk Edebiyatı','Şiir','Arif Nihat Asya']::text[], 8.5, '{"poet":"Arif Nihat Asya","poet_slug":"arif-nihat-asya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tepeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Van Gölü', 'van-golu-arif-nihat-asya-lvkwa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Selahattin Arıkan''a

Nerde istersen orda kal... yerleş; 

Yolcu, rü''yaya benziyor burası...

İşte bak: Bir küçük denizdir göl; 

Bir küçük kıt''a Ahtamar adası!', 'Selahattin Arıkan''a Nerde istersen orda kal... yerleş;  Yolcu, rü''yaya benziyor burası... İşte bak: Bir küçük denizdir göl;  Bir küçük kıt''a...', ARRAY['Türk Edebiyatı','Şiir','Arif Nihat Asya']::text[], 8.5, '{"poet":"Arif Nihat Asya","poet_slug":"arif-nihat-asya","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/van-golu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utansana', 'utansana-suleyman-saylan-que4b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'UTANSANA

Adama bak

Böbür böbür böbürleniyor, 

Kasım kasım kasılıyor; 

Çorabı elli milyonmuş adamın, 

Kravatı da öyle...

Yüz milyonluktan aşağı gömlek, 

Milyarlıktan aşağı takım giymezmiş.

Ne demekse; 

Pabuçları da İtalya''dan gelirmiş...

Zavallım

Bunlarla insan olunur sanıyor, 

Terör kusuyor

Çevresine.

Dibi yok, 

Kökeni yok, 

Gövdesi, dalı, 

Yaprağı, meyvesi yok...

Aşamamış kendini, 

Cahil.

Bunlarla örtüyor komplekslerini, 

Bakmıyor kökenine, 

Nereden geldiğine...

Senin gömlek paranla

Ev geçindiriyor insanlar

Bu memlekette.

Utansana, 

Sevineceğine.

Süleyman SAYLAN

(Ankara,22.07.2001, Saat: 01.15)', 'UTANSANA Adama bak Böbür böbür böbürleniyor,  Kasım kasım kasılıyor;  Çorabı elli milyonmuş adamın,  Kravatı da öyle... Yüz milyonluktan aşa...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/utansana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükettik', 'tukettik-suleyman-saylan-b1iiq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'TÜKETTİK

Evrene doğduğumuzdan beri

Neyi tüketmedik ki! 

Yıllarımız tükettik bir bir; 

Çocukluğumuzu tükettik ilkin...

Arasak, 

Anılarda bulabilin miyiz bilmem, 

Çocukluk aşkımızın ilk heyecanını? 

Kaç atardı damarlarımızda kan, 

Kaç vururdu yürek kıpırtılarımız? 

Tükettik sevdalarımızı, 

Sızılarımızı, 

Sahte gülücüklerle süslediğimiz

Acılarımızı.

Tadını tatmadığımız sevgilerimizi, 

Elini tutmadığımız sevgililerimizi, 

Umut bağladığımız umutsuz aşklarımızı

Tükettik.

Hep yaralandık yüreğimizden; 

Yaralarımızı tükettik.

Yüreğimizi de...

Sağlığımızı tüketip hastalandık, 

Sonra

Hastalıklarımızı tükettik.

Bir de baktık ki; 

Tüketmişiz gençliğimizi bile.

Aç kurtlar gibi saldırdık düşlerimize, 

Düşlerimizi tükettik.

Tükete tükete anladık sonunda, 

Ömrümüzü tüketmişiz...

Ama, 

Bir şeyi tüketemedik, 

Tüketmeyi.

Süleyman SAYLAN

(Ankara,16.07.1999, Saat: 18.45)', 'TÜKETTİK Evrene doğduğumuzdan beri Neyi tüketmedik ki!  Yıllarımız tükettik bir bir;  Çocukluğumuzu tükettik ilkin... Arasak,  Anılarda bula...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/tukettik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '... Biti.', 'biti-suleyman-saylan-zqepe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '... BİTİ.

Ben çok sahtekarlar gördüm, 

Düzenbazlar, 

Üçkağıtçılar gördüm; 

Hazımsız, altyapısız, 

Kompleksli hıyarlar tanıdım

Kendini bir bok sanan...

Dipsiz, kökensiz

Kupkuru ağaçlardan, 

Çiçeksiz, meyvesiz dallardan

Farkları olmayan...

Denizli horozu gibi

Ötüp ötüp de, 

Yaralı parmağa bile işemeyen.

Attıklarında

Mangalda kül bırakmayan

İnsanlarla yaşadım, 

Birlikte yaşamaya mecbur bırakıldım

Hak etmediğim halde.

Yüreksizler ordusunun

Kendini general sanan

Yalaka neferleriydi

Bu şerefsizler...

İnsanların insanlara

Taktıkları sıfatları duydum, 

Yakıştırmaları bilirim, 

Evrende yaşayan

Her türlü karaktersizi tanıdım, 

Yakıştırılan sıfatları ezberledim

Ama; 

Sana tanım bulamadım

... biti...

Süleyman SAYLAN

(Ankara,29.04.2000, Saat: 00.55)', '... BİTİ. Ben çok sahtekarlar gördüm,  Düzenbazlar,  Üçkağıtçılar gördüm;  Hazımsız, altyapısız,  Kompleksli hıyarlar tanıdım Kendini bir bo...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/biti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip', 'garip-emirzad-demirel-8png6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Garip...

Son kez öldügüm gün dogacak sevgim yüreginde

Ve ilk kez kabul gören yürekte

Bensiz kalacaksın

          sakın üzülme 

                           garip...', 'Garip... Son kez öldügüm gün dogacak sevgim yüreginde Ve ilk kez kabul gören yürekte Bensiz kalacaksın           sakın üzülme               ...', ARRAY['Türk Edebiyatı','Şiir','Emirzad Demirel']::text[], 8.5, '{"poet":"Emirzad Demirel","poet_slug":"emirzad-demirel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/garip-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakar Ağlatır.', 'bakar-aglatir-suleyman-saylan-9vhwc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'BAKAR  AĞLATIR.

Göz yaşlarım akar ha akar, 

Kuruyan göz pınarlarımı

Çağlatır sanki.

Kirpikleri

Gönlüme batar ha batar, 

Kanatır...

Öyle suçsuz bakar ki; 

Üzer, ağlatır.

Dünyamı altüst eder bakışı bile, 

Nasihat kar etmez

Yanan yüreğime; 

Boşuna dil dökmeyin, 

Sözler nafile...

Öyle ürkek bakar ki; 

Yakar, ağlatır.

Titreyen bir heves

Yaşlanır kalbimde.

Çılgın yangınlar tutuşur

Hep içimde; 

Aşkı tatmış gibiyim

Ahir ömrümde...

Öyle masum bakar ki:

Bakar, ağlatır.

Süleyman SAYLAN

(Ankara,20.07.2001, Saat: 16.45)', 'BAKAR  AĞLATIR. Göz yaşlarım akar ha akar,  Kuruyan göz pınarlarımı Çağlatır sanki. Kirpikleri Gönlüme batar ha batar,  Kanatır... Öyle suçs...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bakar-aglatir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuğunun Boynu', 'kugunun-boynu-ozcelik-peker-k74af', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kuğuyla bir kadının ortak yanı

İkisinin de boyunları çok güzeldir

Ama ikisininkine de dokunamazsın

Bakamayacağın gibi

Gülün dikenlerine sorun

“Yaptığın zor bir iş mi? ” diye

O atasözünü kullanamayacaktır

Gülü seven dikenine katlanır

Bir kuyruk acısıdır gider

Sağ yanına daha iyi kullanır

Belki de saglaktır

Sol eli ustura tutan aşık

Elimi tutan eldir beni bu çukurdan kurtaran

27.06.2002', 'Bir kuğuyla bir kadının ortak yanı İkisinin de boyunları çok güzeldir Ama ikisininkine de dokunamazsın Bakamayacağın gibi Gülün dikenlerine ...', ARRAY['Türk Edebiyatı','Şiir','Özçelik Peker']::text[], 8.5, '{"poet":"Özçelik Peker","poet_slug":"ozcelik-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kugunun-boynu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olanaksız', 'olanaksiz-ozcelik-peker-m15d8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir müzayededeyim

Aşık yürekler

Kitap kahramanları

Oyun karakterleri

Dünyanın en güzel şiiri

Satışa çıkarılmış hepsi

Sıra şiire gelir

Adam şiiri yorumlar

İkinci satırda çözemez

Ayağa kalktım şiiri anlattım

Meğer benim yazdığımmış

Karanlıkta uyandım sersem gibi

Rüyası bile zevkli

Gerçeği olanaksız tabii

08.01.2002', 'Bir müzayededeyim Aşık yürekler Kitap kahramanları Oyun karakterleri Dünyanın en güzel şiiri Satışa çıkarılmış hepsi Sıra şiire gelir Adam ş...', ARRAY['Türk Edebiyatı','Şiir','Özçelik Peker']::text[], 8.5, '{"poet":"Özçelik Peker","poet_slug":"ozcelik-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/olanaksiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
