INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arap Saçı Beklemek', 'arap-saci-beklemek-tayfun-kasapoglu-co4s0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ümit etmek midir beklemek

yada ölmek, 

uzak kalmak sevdiğinden

özlemek, 

gel demesini 

belkide sev demesini beklemek.

....

gecelerin tadında bir aşk benimkisi

katran kıvamında ve 

siyanür yoğunluğunda

bir gece daha akıyor göz yaşlarımdan 

benden habersiz

sana doğru

bir nehir çağlıyor yatağından

aşktan uzağa bana doğru

bir yudum suyla boğuluyorum

....

aklımı başımdan alan 

rüzgar esiyor yine

elimde olmayan resmin 

güzelliğin tazeliğin 

birde sığdıramadığım 

yüreğime sevgin var

zaten onunlada başım dertte 

ne git desem gidiyor 

ne kal desem oturuyor yüreğime

tuhaf bir hal içindeyim arap saçıyım

gel çöz işte

...

küçücük ellerin var 

bedenimin her yerinde

ve nasıl yanıyorum her değdiğinde

uzatma sürgünümü

gümüş gözlerinden öteye

dört yanım seninle çevrili 

ADA''da olmak varken ruhumla

sensizlik cehennemini ben yakıyorum

alevlerimle

gel diyorum yazdığım mısralarla

dön diyorum sana 

açtığım kucakla

ümit etmek midir beklemek

gözlerinden uzağa düşmek

ve ağır bir aşk komasında 

rehin kalmak mıdır seni sevmek

gel dindir içimdeki bu ateşi

mısralarımla kanıyorum

ölüyorum...', 'ümit etmek midir beklemek yada ölmek,  uzak kalmak sevdiğinden özlemek,  gel demesini  belkide sev demesini beklemek. .... gecelerin tadında...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Kasapoğlu']::text[], 8.5, '{"poet":"Tayfun Kasapoğlu","poet_slug":"tayfun-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/arap-saci-beklemek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanımda Olmasanda', 'yanimda-olmasanda-suleyman-cakir-nzwsi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her ne kadar yanımda olamsanda

