INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüme Ölüm', 'olume-olum-numan-eksioglu-f3fdc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaldırın ellerinizi kardeşler

Duaya duracağız

Haydi hep bir ağızdan

Ölüm ölsün

Ölüm ölsün ey tanrı

Sanırım duyulmadı

Bizi biz güldürelim

Ölümü öldürelim

Ölüm ki bunca kanlı', 'Kaldırın ellerinizi kardeşler Duaya duracağız Haydi hep bir ağızdan Ölüm ölsün Ölüm ölsün ey tanrı Sanırım duyulmadı Bizi biz güldürelim Ölü...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/olume-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-numan-eksioglu-2giog', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düşümde 

Oldukça büyük bir kasayı 

Daktilonun başına oturmuş 

Yasa yazarken gördüm', 'Düşümde  Oldukça büyük bir kasayı  Daktilonun başına oturmuş  Yasa yazarken gördüm...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dus-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var mı Yaşamak Gibisi?', 'var-mi-yasamak-gibisi-naime-erlacin-qzw8s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çıksam pencereye meselâ

bağırsam avaz avaz:

“seni seviyorum dünya! ” 

hayır uğraşmam bile

“oyun teorisi” kurarım 

onun yerine 

dert çökmüş üstüme 

karabasanlar inmiş gökten

karışmış kafam

ne umurum! 

içim şarkısını inler hayat kafesinde

sever yaşamayı delice

kâh su olur ateşime

kâh ateşe savurur 

gözlerim acıya düşer 

yaşlar kalbime

yok ki ama yaşamak gibisi

tutunmak hayata

oyun kurmak 

en büyük oyunun peşinde

hayal ne 

gerçek ne

yaşamak bir oyun değil mi

yalanların içinde…

(14 Temmuz 2003)', 'çıksam pencereye meselâ bağırsam avaz avaz: “seni seviyorum dünya! ”  hayır uğraşmam bile “oyun teorisi” kurarım  onun yerine  dert çökmüş ü...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/var-mi-yasamak-gibisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çivi', 'civi-numan-eksioglu-yrl05', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kızım Ezgi''ye

Çiviliğinle övünebilirsin kızım

Postalı ancak 

Bir çivi delebilir', 'Kızım Ezgi''ye Çiviliğinle övünebilirsin kızım Postalı ancak  Bir çivi delebilir...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/civi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Şarap Severler', 'gercek-sarap-severler-numan-eksioglu-ukiar', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hilton oteline bakıp nazik sözler eden  şarapçıya 

  Üzüm yetiştirdiler

  Saraya götürüldü 

  Katlanalım diyerek

  Bir kısmını saklayıp

  Şaraba çevirdiler

  Saray haberdar oldu

  Yasak koydu şaraba 

  Saraylı baş beyefendi

  Çogunluk korktu uydu 

  Tadını bilirdi ya 

  Saraylılar şarapsız

  Tek sofra kurmuyordu                                         

   Ol nedenden gerçek şarap severler

   Nerde saraya benzer bir yapı görürseler

   Hala hınç almak için 

   Nazik sözler ederler', 'Hilton oteline bakıp nazik sözler eden  şarapçıya    Üzüm yetiştirdiler   Saraya götürüldü    Katlanalım diyerek   Bir kısmını saklayıp   Şa...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gercek-sarap-severler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'tavir', 'tavir-numan-eksioglu-34pez', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hızır Civelek''e

Son paracıklarını

Ekmeğe takdim etti

Kuyumcular sokağı

Yöneldiği adresti

 Her dükkana bir parça

 Kırıp atması dersti', 'Hızır Civelek''e Son paracıklarını Ekmeğe takdim etti Kuyumcular sokağı Yöneldiği adresti  Her dükkana bir parça  Kırıp atması dersti...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tavir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Kaybı', 'kan-kaybi-numan-eksioglu-v5yb7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gökkuşağını öpene yargılar

Sonuç

Öpen dudaklarda sargılar

İnsanlar genellikle trübinde kaldılar

Bölüşülse acılar kururdu kaynakları

Kanatlar kanamazdı

Yere yakın olmazdı bu uçuşlar

Dudaklar kanamazdı

Kan kaybından düşüvermezdi kuşlar

Acının mal sahibi sevinç yarıcısı kalp

Gökkuşağı görmeyen seni ne kadar anlar', 'Gökkuşağını öpene yargılar Sonuç Öpen dudaklarda sargılar İnsanlar genellikle trübinde kaldılar Bölüşülse acılar kururdu kaynakları Kanatlar...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kan-kaybi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakar Gözyaşlarımız', 'yakar-gozyaslarimiz-numan-eksioglu-ljgby', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüzyıllardır taşınan genlerin nedeniyle

Akar gözyaşlarımız

Bizim burda sorunu çözmüyor çalışmamız

Her zaman bir neden vardır yokluğa

Ekmeğimiz saklıdır çocuklardan

Ekmek istediğinde

Dayak yer öz anneden

Demin verdim diye de

Nasihat dinler sonra

Daha sonra annenin sel gözleri

Ekmekli ufuklarda

Akar gözyaşlarımız

Düşleri yasta kurmak

Kuraldır buralarda

Tüm zamanlar birşeylere yaslıdır

Akar gözyaşlarımız

Tok olmayan hayvandan

Süt sağmak nice zordur

Hasta olan insana ve hayvana

Dua en yoğun yoldur

Erken kırışan tendir

Akar gözyaşlarımız

Ölümüzün gözleri dirimizden canlıdır

 Buzlu camda yağmurdur

Akar gözyaşlarımız

Marş ıssızsa nedeni

Aşkın şarkılarıdır

Gözyaşını taşlama

Yakar gözyaşlarımız', 'Yüzyıllardır taşınan genlerin nedeniyle Akar gözyaşlarımız Bizim burda sorunu çözmüyor çalışmamız Her zaman bir neden vardır yokluğa Ekmeğim...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yakar-gozyaslarimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Vapurla Aldattım...', 'seni-vapurla-aldattim-yavuz-i-gret-6vh9u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bozkırları hiç görmemiştim

Dünyanın bütün sokaklarında çatışmış 

Savaşmaktan yorulmuş bir bedende yok oldum

Ömürsüzlüğüm ölümsüzleşti

Ben bir kelebektim aslında

Okyanuslara kafa tutan

Üzerinde kaderim yazılı 

Bir ceylan derisinde kurtlanmış

Ve kanatlanmıştım 

Alıp ceylandan eksik kaderini tenine işleyen

Sana kavuşabilmek için denizlere diklenen

Akdeniz''e yenik düşen bir kelebek

Pul pul yayıldı kaderim dünyanın bütün denizlerine

Kasırga bora ne kadar anlamsızlaştılar

Senin bedeninde yaşadığım afetlerde

Belki de pitonları öldüren

Binlerce aşığa mezar olan 

Geçmişinin içinde 

Ölümcül zamanları 

Tercih etmek yakışırdı aşka

Ancak Sahtiyan''a kaderim eksik yazılmıştı

Ayrılırken limandan

Boğazımda gemici düğümleri 

Kapına bir not bırakıp

Kendime iftira attım

Seni Haydarpaşa Karaköy hattında

Bir vapurla aldattım', 'Bozkırları hiç görmemiştim Dünyanın bütün sokaklarında çatışmış  Savaşmaktan yorulmuş bir bedende yok oldum Ömürsüzlüğüm ölümsüzleşti Ben bi...', ARRAY['Türk Edebiyatı','Şiir','Yavuz İgret']::text[], 8.5, '{"poet":"Yavuz İgret","poet_slug":"yavuz-i-gret","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/seni-vapurla-aldattim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-zafer-donmez-806oy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bebeğin gözleri olurum pırıl pırıl

Gamzesi olurum bazen sıcacık, 

Dalgalarda köpük olur kıyıya vurur, 

Kum tanesi olup unutum açıkları bazen

Ve duyduğumda şarkımı

Yağmur kadar temiz, 

Gözyaşı kadar masum, 

Işık kadar aydın, 

ve ana kucağı gibi sıcak

Ben olurum, yoktur artık yalnızlık.', 'Bir bebeğin gözleri olurum pırıl pırıl Gamzesi olurum bazen sıcacık,  Dalgalarda köpük olur kıyıya vurur,  Kum tanesi olup unutum açıkları b...', ARRAY['Türk Edebiyatı','Şiir','Zafer Dönmez']::text[], 8.5, '{"poet":"Zafer Dönmez","poet_slug":"zafer-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yalnizlik-114-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sosyalizm Oldu diyenlere', 'sosyalizm-oldu-diyenlere-bulent-celal-1ze0r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bunlari da gorecekmisiz meger.

Kolelerin kanlariyla degilde, 

Nemrut sahiplerin

gonul rizasiyla girilecekmis

yeni bir caga.

Dehsetli savaslarin ardindan, 

meydanlarda, cesetlerle 

koyun koyuna degil de, 

cokuluslu tekellerin 

yonetim kurullarinda 

kutlanacakmis meger.

Yani, 

yeni caga gecis

yumusak olacakmis

Ustelik bu yeni cagda

Ne 

bir damla eksik akacakmis gozyasimiz, 

Ne

Bir halka eksilecekmis zincirlerimizden, 

Ne de 

bir kursun eksik saplanacakmis bagrimiza.

Damlaya damla, 

zincire zincir, 

kursuna kursun eklenecekmis.

Yani, elemizin

ve beynimizin

butun aydinlik huneri

yine uzaktan, 

yine yabanci bakakmis bize.

Ve

yeni bir dunya duzeni

olacakmis

butun bunlarin adi da

sosyalizm sonrasi mutluluk cagi! ! 

Bunlari da gorecekmisiz meger.

Duymustuk da

anasini susleyip de

babasina satani, 

beklemiyorduk dogrusu

bu kadarini.

Bakin, tarih nasil da

gevrek gevrek guluyor 

sivazlayarak

ak saclarini.

Nerede gorulmustur

cocugun 

annesini dogurdugu! ! 

Insanligin can simidinin

yalan denizlerinde

bogulmasi mumkun mu! ! 

Koca bir palavrami yon verecek

Duslerimize! 

Biliyoruz, 

sizin butun sorununuz

SOSYALIZM le.

kurban olun siz SOSYALIZM''e! 

ZATEN OLACAKSINIZ DA...', 'Bunlari da gorecekmisiz meger. Kolelerin kanlariyla degilde,  Nemrut sahiplerin gonul rizasiyla girilecekmis yeni bir caga. Dehsetli savasla...', ARRAY['Türk Edebiyatı','Şiir','Bülent Celal']::text[], 8.5, '{"poet":"Bülent Celal","poet_slug":"bulent-celal","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/sosyalizm-oldu-diyenlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümsüz ve Sorunsuz', 'olumsuz-ve-sorunsuz-numan-eksioglu-o3eht', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yak kendini karanlık 

Kış artık kendin üşü 

Biz kurmasak kim kuracak bu düşü

Bir yaşam yaklaşıyor

Ölümsüz ve sorunsuz

Uzakta görülmüyor ölümün yenilişi

Çalışma saatleri aşk fazlası zamanlar

Herkes yeteneğince beceriyor bir işi

Bir dünya yaklaşıyor 

Ölümsüz ve sorunsuz

Acı yok çekilmiyor artık kimsenin dişi 

Savaş yok sömürü işkence de 

Bir alkış kadar yakın özgürlüğün gelişi

Bir evren yaklaşıyor 

ölümsüz ve sorunsuz', 'Yak kendini karanlık  Kış artık kendin üşü  Biz kurmasak kim kuracak bu düşü Bir yaşam yaklaşıyor Ölümsüz ve sorunsuz Uzakta görülmüyor ölüm...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/olumsuz-ve-sorunsuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rabbe Yalvarış', 'rabbe-yalvaris-bayram-tunca-vzgrz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mecnunu, Leylâ’yı çöllerde aratan

Yusuf’u dipsiz kör kuyuda yaşatan

Ferhat’ı Şirin için dağları kazdıran

Ne olursun kaldır engelleri aradan

Yaradan Yaradan sensin bizi yaradan

Ne olursun engelleri kaldır aradan

Bak kalbimiz göz göz oldu yaradan

Sensin, her şeyi topraktan yaratan

Cisimleri fırıldak gibi evirip çeviren

Yeryüzüne binbir çeşitli sofra seren

Sensin bizleri canlılara sultan eden

Ne olur tüm engelleri kaldır aradan

O der o gün fayda yok anadan babadan

Bir tek ümidimiz sendedir yüce Yaradan

Ne olursun, tüm perdeleri kaldır aradan

Sensin her şeyi en güzel şekilde yaratan

Severiz her şeyi Sen’den ötürü yaradan

Her şeyi ayrı ayrı rol vermişsin yaradan

Kimine uç/kimine kaç demişsin yaradan

Ne olursun, tüm engelleri kaldır aradan

B. Tunca/13.07.2003-13.07', 'Mecnunu, Leylâ’yı çöllerde aratan Yusuf’u dipsiz kör kuyuda yaşatan Ferhat’ı Şirin için dağları kazdıran Ne olursun kaldır engelleri aradan ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/rabbe-yalvaris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Henüz Olmadı', 'henuz-olmadi-numan-eksioglu-iqw4g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Olması gereken hiçbirşey olmadı henüz 

Yüreklerle beyinler büyümedi 

Baharın yamurları insanların içini bir yıkayıvermedi

Biri çıkıp sevinçin saçlarına tane tane örmedi

Biri çıkıp sessizliği şarkıya dönüştürüvermedi

Biri çıkıp ölümü öldürmedi

Tüfeklerle bombalar müzedeki camekana girmedi 

Kelebek konuşmadı çiçekler yürümedi 

Kimseler aşk sözünü tanımlayıvermedi

Sorunsuzluk evreni emzirmerdi

Olması gereken hiç birşey olmadı henüz

Yüreklerle beyinler büyümedi', 'Olması gereken hiçbirşey olmadı henüz  Yüreklerle beyinler büyümedi  Baharın yamurları insanların içini bir yıkayıvermedi Biri çıkıp sevinçi...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/henuz-olmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldin', 'hosgeldin-sair-masmavi-vwoa5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Parmak uçlarım değiyor denizin sakin ıslaklığına

Taş atıyorum dalgın dalgın

Düştüğü yerde sen büyüyorsun

Güneşten artan aydınlık vuruyor büyüyen dalgalara

Dalgaların aydınlığı yüreğime.

Başımı gömüyorum dizlerimin arasına

Hafif bir akşamüzeri esintisi kokunu taşıyor bana

Gözlerim yanıyor! 

Bir taş daha atıyorum denize

Büyüyen dalgalarını izliyorum sonra

Ayak ucuma dokunan son dalga ile

İçime akıttığım yaşların arasına karışıyorsun

Yüreğim gülümsüyor sana

Hoşgeldin!', 'Parmak uçlarım değiyor denizin sakin ıslaklığına Taş atıyorum dalgın dalgın Düştüğü yerde sen büyüyorsun Güneşten artan aydınlık vuruyor büy...', ARRAY['Türk Edebiyatı','Şiir','Şair Masmavi']::text[], 8.5, '{"poet":"Şair Masmavi","poet_slug":"sair-masmavi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hosgeldin-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gider mi?', 'gider-mi-tamer-akarsu-d65ax', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim nazlı yarimi istiyorlarmış

Ne zaman büyüdü anlamadım ya

Çocukluk aşkıma eller göz koymuş

Beni unutup da gider mi Hülya

Kırlarda koşardık güler oynardık

Eleleyken yıldızlara bakardık

Nasıl geçti yıllar anlayamadık

Varlığımı bilse gider mi Hülya

Yollarına sersem gonca gülleri

Hatırlatsam ona eski günleri

Ya beni görmezse güzel gözleri

Ardına bakmadan gider mi Hülya', 'Benim nazlı yarimi istiyorlarmış Ne zaman büyüdü anlamadım ya Çocukluk aşkıma eller göz koymuş Beni unutup da gider mi Hülya Kırlarda koşard...', ARRAY['Türk Edebiyatı','Şiir','Tamer Akarsu']::text[], 8.5, '{"poet":"Tamer Akarsu","poet_slug":"tamer-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gider-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göçmen', 'gocmen-yavuz-turhan-dh5yr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Göçmen kuşların izinde 

bulmak istiyorum 

düşlerini..

senin peşin de, 

senin kokunla yakalamak istiyorum

güzelliğini..

Özlemini, kanatlarının serinliğinde hissedip, 

avuçlamak istiyorum bedenini..

Sen yüreğini serin tut bebeğim...bir gün yaslanacağım..

ve yüreğin, beynimde atacak.. 

işte o an..hiç bir zaman kurumayacak

bir sevgi yeşerteceğiz..

birlikte..', 'Göçmen kuşların izinde  bulmak istiyorum  düşlerini.. senin peşin de,  senin kokunla yakalamak istiyorum güzelliğini.. Özlemini, kanatlarını...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Turhan']::text[], 8.5, '{"poet":"Yavuz Turhan","poet_slug":"yavuz-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gocmen-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savunma', 'savunma-numan-eksioglu-8n26x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dilimiz yabancı dillerin kölesi oluyor demedim

Biliyorum desem artar gerilim 

Türkiye çölleşiyor diyen ben miyim

Tema vakfı üyesi bile değilim

Yurdumuz emperyalizmin kıskacında çırpınıyor diye 

Bir cümle mi kurmuşum 

Bu kapitalistlerin yakıştırması

Çünkü kapitalist değilim 

Eş itlik değil

Eşitlik istiyoruz diye 

Ben mi slogan atıp pankart taşıdım 

Benim tek söylediğim ''sevelim sevilelim''

İşkence sistemli bir şekilde uygulanıyor  demişmişim

Bu muhbirlerin uydurması

Yoktur bende kötülüğe eğilim

Asgari ücret açlık sınırının yarısıymış

Bunu söylemek ne haddime

Ne ölü ne diriyim 

Hem benim ağzım sıkıdır

Düşüncesinden ötürü hapis yatanlar olsa bile

Kimseye söylemem geveze değilim

Şaire gözdağı vermek için

Kapısına ceset bırakılıyormuş

Bana ne bundan henüz şair değilim

Bazı aydınlar faili meçhul cinayetlere

Kurban gidiyor veya ortadan kayboluyormuş

Ağzımdan sözcük çıkmaz

Ben deniz sahiliyim

İnsanlar diri diri yakılıyorsa

Annem beni etliye sütlüye karışmamakla 

Öğütleyerek büyütmüş

Büyük sözünü dinleyen biriyim

Bütün bunları halk söylüyor artık beyler

Yani artık beyler

Ben halktan duyuyorum

Birilerini tutuklamak gerekiyorsa

Halkı tutuklayın

Ben hapislik değilim', 'Dilimiz yabancı dillerin kölesi oluyor demedim Biliyorum desem artar gerilim  Türkiye çölleşiyor diyen ben miyim Tema vakfı üyesi bile değil...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/savunma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takip', 'takip-numan-eksioglu-jcxjp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Siz şimdi benim bir gece

Aniden geri dönünce

Gölgemle çarpıştığıma inanır mısınız', 'Siz şimdi benim bir gece Aniden geri dönünce Gölgemle çarpıştığıma inanır mısınız...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/takip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhumun Adresi Sen', 'ruhumun-adresi-sen-numan-eksioglu-9kitz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimin artıklarını dışladım

Dizeler ki güldüren aynalardır

Duygularım sızlayıncaya kadar

Ben seni dizelerle alkışladım

Ruhumun adresi sen

İçinin saydamlığında kışladım

Sonsuzluğa varacak

Kendine de yürüyen adımlardır

Sargılarım çözülünceye kadar

Sevincimi acıyla yarışladım 

Ruhumun adresi sen

Yüreğimde türkülerle başladım

Sorunsuzluk dediğin

Türkülerin ürkü vermemesidir

Sevdalar prangadan kurtuluncaya kadar

Dirençlerle kendimi barışladım

Ruhumun adresi sen', 'İçimin artıklarını dışladım Dizeler ki güldüren aynalardır Duygularım sızlayıncaya kadar Ben seni dizelerle alkışladım Ruhumun adresi sen İç...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ruhumun-adresi-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çay', 'cay-numan-eksioglu-h9mle', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmurların altında çay toplayıp

Atın gidemediği iniş ve yokuşlardan

Sırtımızda ağırlığımızca yük 

Yüz metreler bin metreler yürüdük 

Tırnaklarımız bile terledi yük altında

Yükümüzü indirince bayıldık

ve beyin kanaması 

Romatizma ve tansiyon hastası

Ve kalp hastası olduk

Yanıtlayın ey bilim insanları

Annenin taşıdığı yükten etkilenmez mi

Anne karnında çocuk

Kanaması arttı tüm kadınların 

Ve sayısızca düşük

Kimseler tat alamaz taşıyan kadar çaydan

Çünkü ocağa suyu  yürek terinden koyduk

Gözleri terledi gören turistin 

Kameraya sarıldı utancımızdan kızdık

Eksperlerde kapristen yana bolluk 

Ve eksperin bin beteri müdürlük

Kontenjan koydu devlet 

Artık özel sektöründe kuluyduk 

Sattığımız çayların parasını 

En az bir yıl beklemekti özgürlük 

Çaya emek verenler 

Yürekler öpsün sizi 

Ve ruhlar kucaklasın 

Ve gözlerden gözünüze gülücük', 'Yağmurların altında çay toplayıp Atın gidemediği iniş ve yokuşlardan Sırtımızda ağırlığımızca yük  Yüz metreler bin metreler yürüdük  Tırnak...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/cay-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öküzlere Yapılan', 'okuzlere-yapilan-numan-eksioglu-8gu3s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kazım Köroğlu''na

Öküz öküzlüğünü yaptı

İnekleri kovarak ot yığınını kaptı

Baba babalığını yaptı 

Öküzü kovalayıp otu ineklere bıraktı

Oğul uyanıverdi ve görevini yaptı

Cezası görevden atılmaktı

Baba ''neden görevden atıldın'' diye sorunca

''Senin öküze yaptığını yaptım''derken

Pişmanlıktan uzaktı', 'Kazım Köroğlu''na Öküz öküzlüğünü yaptı İnekleri kovarak ot yığınını kaptı Baba babalığını yaptı  Öküzü kovalayıp otu ineklere bıraktı Oğul u...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/okuzlere-yapilan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Havada Yürümek', 'ah-havada-yurumek-numan-eksioglu-tgm3u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaç balığı öldürdük

Kaç koyunu ve kaç ineği kestik

Beslenelim diyerek

Günü gelecek bilim

Öldürmeden beslenmenin yolunu

Elbet formülleyecek

O zaman insanlarla bitkilerle hayvanlar

Mikroplar parazitler

Kardeşleşiverecek

Kaç karınca can verdi

Ayağımız altında

Ve kimbilir kaç böcek

Ah havada yürümek

Ah havada yürümek', 'Kaç balığı öldürdük Kaç koyunu ve kaç ineği kestik Beslenelim diyerek Günü gelecek bilim Öldürmeden beslenmenin yolunu Elbet formülleyecek O...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ah-havada-yurumek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-enver-ciftci-jh0ze', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sergileniyor cansız vücudum 

ibret alsın diye korkak

Yürürken sevda yüklü yoldaşlar

Ve deler iken karanlıkları 

Kızıl keskin ışıklar', 'Sergileniyor cansız vücudum  ibret alsın diye korkak Yürürken sevda yüklü yoldaşlar Ve deler iken karanlıkları  Kızıl keskin ışıklar...', ARRAY['Türk Edebiyatı','Şiir','Enver Çiftçi']::text[], 8.5, '{"poet":"Enver Çiftçi","poet_slug":"enver-ciftci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/umut-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorular', 'sorular-numan-eksioglu-1uo0p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sözünün gözü kör mü

Dilsiz mi sevinçlerin

Giremeyecek kadar sevdalar ve sevgiler

Yüreginin giriş kapısı dar mı

Neden bütünlüğünü parça parça gösteriyor aynalar

Ellerin hiç bütünlüğü okşar mı

Heykele mi şarkı söyle diyorsun

Çalmaya çalıştığın buzdan enstrümanlar mı

Fırtına mı tayfun mu esiyorsun çiçek bahçelerine

Dökünerek durduğun karlar ve dolular mı

Duyguların gerçekle ve kendinle kandırmaca oynar mı

Alkışlayıp durdugun öldüren ordular mı

Çekinerek soruyorum bagışla 

Bükülmenin nedeni kavrayamayışlar mı

Ah yoksa yılgılar mı', 'Sözünün gözü kör mü Dilsiz mi sevinçlerin Giremeyecek kadar sevdalar ve sevgiler Yüreginin giriş kapısı dar mı Neden bütünlüğünü parça parça...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sorular-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Acısı', 'ask-acisi-tolgahan-yildiz-62sor', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne resmin var elimde, 

Ne de anlatacak anılar var dilimde, 

Var olan, kulağımdaki sesin, 

Bir de gözlerimdeki hayalin.

Sesin ve hayalinle seviyorum seni, 

Şarkıların namelerinde buluyorum seni, 

Rüzgarların esintisinde hissediyorum seni, 

Bir de güllerin kokusundan çekiyorum ben seni.

Artık şarkılarda anlatamaz oldu sevgimi, 

Ferhat''ın Şirin''ine, Mecnun''un Leyla''sına, 

Lutfettiği sevgide arıyorum ben seni, 

Aşk acısıdır, Çeken bir başka seviyor seni.

Geceleri kaçan benim uykularım, 

Düşüncelerde sana ait sevdalarım, 

Toprağın suya olan hasreti gibi, 

Gel, güle oynaya kavuşalım.

23.06.2003, ANKARA', 'Ne resmin var elimde,  Ne de anlatacak anılar var dilimde,  Var olan, kulağımdaki sesin,  Bir de gözlerimdeki hayalin. Sesin ve hayalinle se...', ARRAY['Türk Edebiyatı','Şiir','Tolgahan Yıldız']::text[], 8.5, '{"poet":"Tolgahan Yıldız","poet_slug":"tolgahan-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ask-acisi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karga Yuvası', 'karga-yuvasi-numan-eksioglu-1vizx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çocukken amca oğlu 

Bir ağaçtaki karga yuvasına tırmanmıştı vay aman

Yuvada yavrular vardı aman aman 

Yavruyu eline alıp bize gösteriyordu ki 

Anne karga çıka geldi ay aman 

Ve bağırıp yardım istedi 

Ortalık sis pus duman 

Bir kaç dakika içinde yüzlerce karga geldi 

Ve ona saldırdılar bi harman 

Kafasını yüzünü gagaladılar bir zaman 

Kendini savunmak için 

Ellerini kafasına yüzüne tutarken 

Ağaçtan düşüverdi ah derman 

Şansa bir yeri kırılmadı kafası saman 

Biz ordan kaçıverirken 

Kargalar hala bizi takip ediyordu oy aman aman 

İbret olsun size büyükler 

Küçüklerin yuvasını ellemeyin sakın

Küçükler de güçlüdür birleştikleri zaman', 'Çocukken amca oğlu  Bir ağaçtaki karga yuvasına tırmanmıştı vay aman Yuvada yavrular vardı aman aman  Yavruyu eline alıp bize gösteriyordu k...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/karga-yuvasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baskı Coşku Sönlemez', 'baski-cosku-sonlemez-numan-eksioglu-o78s1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İsteğimiz kuş olmak

Kuşlar silahsız kuşlar

İsteğimiz düş olmak

Düşler ilahsız düşler

Kuşlar düşler ölür ama inlemez

Bize bizi dinleyin der durur da

Çanlar ezan imam papaz dinlemez

Boşa umutlanmayın

Gözyaşımız önünüzde baş eğmez

Böceklerimiz bile yönünüzde yürümez

Toplar toplardamarımız sevgiyi

Sunar atardamarımız sevdayı

Ve sürdürür kavgayı yüreğimiz

Çünkü korku acıları önlemez

Yonttuğumuz heykeller önüne katar sizi

Kalemle kağıttaki mürekkep yutar sizi

Çünkü baskı coşkuları sönlemez', 'İsteğimiz kuş olmak Kuşlar silahsız kuşlar İsteğimiz düş olmak Düşler ilahsız düşler Kuşlar düşler ölür ama inlemez Bize bizi dinleyin der d...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/baski-cosku-sonlemez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelin Yola Girelim', 'gelin-yola-girelim-numan-eksioglu-v4jvn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uçurum çıkınca köprünüz benden

Dağ çıkınca yapraktan kanat yaparım size

Suyu aşıvermeye geminiz salınız ben

Gelin yola girelim

Yüreğimizin atına binelim

Yönümüzü önümüze dönelim

Yalnızlığı ve hüzünü yenelim

Gelin yola girelim

Orda artık hükümsüzdür haksızlık

En büyük suçtur orada aşksızlık

Sözlüklerden silinmiştir şanssızlık

Gelin yola girelim

Acımız baş tacımız olmamalı

Göz yaş yürek toprak taş dolmamalı

Sevincin evrenine

Omuz omuza kol kola girelim', 'Uçurum çıkınca köprünüz benden Dağ çıkınca yapraktan kanat yaparım size Suyu aşıvermeye geminiz salınız ben Gelin yola girelim Yüreğimizin a...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gelin-yola-girelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evladiye', 'evladiye-murat-demir-t174y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dost bildiğim, dost çıkmadı, düşmanım kadar

Güvendiğim tüm dağların, hepsinde kar var

Sağı gördüm, solu gördüm, bozulmuş ahval

Yarınına yanıyorum, evladiyenin

Kulak duymaz, gözler görmez, zihin karışmış

Gözü dönmüş vahşi kurtla, kuzu barışmış

Riyakara, düzenbaza, insan alışmış

Yarınına yanıyorum, evladiyenin

Ne sevgiler sahte çıktı, sevdadan yana

Ne soylular, soysuzlara, oldu maraba

Çapulcuya, soyguncuya, denirse baba

Yarınına yanıyorum, evladiyenin

Murat söyler sözlerini, susturulmazsa

Yola revan olamayız, su durulmazsa

Derde deva, aç mideye, aş bulunmazsa

Yarınına yanıyorum, evladiyenin', 'Dost bildiğim, dost çıkmadı, düşmanım kadar Güvendiğim tüm dağların, hepsinde kar var Sağı gördüm, solu gördüm, bozulmuş ahval Yarınına yanı...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/evladiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünce Düşününce', 'dusunce-dusununce-naime-erlacin-qx91x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '“fe nev zat’a 

gözü var 

sözü var

imbikten damlayan 

özü var düşüncenin

dedi

“kimlere meydan okumaz insan

tek başına düşündüğü zaman…”*

düşünce düşündüğünde

biter ağırlıksız düşünce

susmaz hiç hafif olanlar

''dilsizdir oysa derin acılar**

ki acıya benzemez düşünce

imbikten damlayan öz gören gözedir ancak! 

(*)   La Fontaine

(**)   Seneca

(14 Temmuz 2003)', '“fe nev zat’a  gözü var  sözü var imbikten damlayan  özü var düşüncenin dedi “kimlere meydan okumaz insan tek başına düşündüğü zaman…”* düşü...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dusunce-dusununce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Sazı Ele Aldı', 'dus-sazi-ele-aldi-numan-eksioglu-lx67c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çalgını kimler çaldı

Kim robot sandı seni

Algını köle aldı

Sonra sürüye saldı 

Cenaze namazını

Ölmeden kimler kıldı

Avcının köpekleri

Ruhuna bile daldı

Sana sevgi açlığı

Ekmeğin ilaçlığı

Aşktan yoksunluk kaldı

Dinle dinlemelisin

Düş sazı ele aldı', 'Çalgını kimler çaldı Kim robot sandı seni Algını köle aldı Sonra sürüye saldı  Cenaze namazını Ölmeden kimler kıldı Avcının köpekleri Ruhuna...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dus-sazi-ele-aldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esrik Gönül Rüzgarları', 'esrik-gonul-ruzgarlari-nuri-can-u4qyl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimdi esrik gönül rüzgarları esiyor 

uzak dağ başlarında 

kuşlar göçüp gidiyor mevsimsiz 

hatıralar yürüyor içimin dehlizlerinde 

yaralı bir ırmak akıp gidiyor sessiz 

yorgunum 

yazgülüşlü bir kıza gönül yaktığımdan beri 

hangi çiçeği koklasam güz gelir 

hangi güzü beklesem kış 

ateşgözlü kuşlar kar taşır saçlarıma 

bütün baharlara küserim sebepsiz 

gece olur rıhtımlarda yıldızlar dalgalanır 

ay vurur gönlümün sularına 

her kıyıda bir şarkı depreşir 

her şarkıda bir yürek 

dayanamam, alır başımı giderim 

bütün mevsimler kalır bensiz 

11/10/85/  İstanbul', 'Şimdi esrik gönül rüzgarları esiyor  uzak dağ başlarında  kuşlar göçüp gidiyor mevsimsiz  hatıralar yürüyor içimin dehlizlerinde  yaralı bir...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/esrik-gonul-ruzgarlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tamamlanmak', 'tamamlanmak-numan-eksioglu-bp578', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kızım Özlem''e

Çalış yaratıcı ve üretici ol

Sev sez oku yaz

Hakedene saygıda kusur etme

Böceklerle bile dost ol

Sabret ve coşkunu kaybetme

Sevincini günden güne artır

Önce toplum de toplumun içindesin nasılsa

Adil ol

Diren ki elde et paylaş ki art

Gerçekçi ol çünkü sende bir gerçeksin

Korkma ölürsen ölümsüzleşirsin

Heyecanlan ve yen heyecanını

Sor ve yanıtlamaya çalış

Baş kaldır kendine bile

İlgilen mikroplarla bile

Acı mikroplara bile

Huzurunu bozdurma hiçbir şeye

Özveri şart disiplin şart

Ve cesaret biraz daha

Kararlı ve tutarlı ol

Ara ve bul

Barışı düşle

İnan ölümsüzlüğe ve sorunsuzluğa

Özgür ol yönetenleri rahatsız edecek kadar

Bilim sanat ve felsefe kutsaldır

Onlara kul ol

Çiçekler kadar dürüst

Ve onurlu ve aşık

Tamam ol', 'Kızım Özlem''e Çalış yaratıcı ve üretici ol Sev sez oku yaz Hakedene saygıda kusur etme Böceklerle bile dost ol Sabret ve coşkunu kaybetme Se...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/tamamlanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serkisof', 'serkisof-aziz-ahmet-bulut-cbdju', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'asılı çürüyorum

saatlerde

serkisof.

sendenmiş ölüm

sende kalsın ölüm

serkisof.

Nilde boğuldu güneş

kaçma akrepten

serkisof...', 'asılı çürüyorum saatlerde serkisof. sendenmiş ölüm sende kalsın ölüm serkisof. Nilde boğuldu güneş kaçma akrepten serkisof......', ARRAY['Türk Edebiyatı','Şiir','Aziz Ahmet Bulut']::text[], 8.5, '{"poet":"Aziz Ahmet Bulut","poet_slug":"aziz-ahmet-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/serkisof-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üçüncü Şiir', 'ucuncu-siir-melek-midikoglu-rj59j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana rüyamda bir şiir yazdım

Unutmayayım diye tekrarladım

Sabah hatırlamadım

Sana yazılan o şiiri

Kimse okuyamayacak

Evrenin bir köşesinde hep yeri olacak

Martılara anlattığımda vay vay vay dediler

Günü güne sormak gerek

O söyleyecek', 'Sana rüyamda bir şiir yazdım Unutmayayım diye tekrarladım Sabah hatırlamadım Sana yazılan o şiiri Kimse okuyamayacak Evrenin bir köşesinde h...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ucuncu-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Nedir, Şair Kimdir?', 'siir-nedir-sair-kimdir-ensar-aktas-it3bx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Etrafında sürüyle insan deyip gülüp eğleniyorlarken

Sen kendini yapayalnız hissediyorsan

İçindeki boşluk büyüyor büyüyor seni yutuyorsa

Ve sen o boşlukta kaybolup gidiyorken

Geçiyorsa aklından iki güzel sözcük, gülümsüyorsan

Ve yalnızlığını unutturuyorsa sana o tek gülücük

İşte şiir o iki sözcükle o bir gülücüktür

Ve etrafında kimseler yokken, yapayalnız kalmışken

İçinde çiçekler açtırıp açtırıp mutlu oluyorsan

Ve aklından geçenleri aklının bir kenarına

Ya da bir eski kağıt parçasına not ediyor, yazıyorsan

Hele birde gözünden iki damla yaş katıyorsan

İşte şair duygularını gözyaşlarıyla yoğurandır

İşte şair sensindir, sen

Rotterdam,21.08.2002', 'Etrafında sürüyle insan deyip gülüp eğleniyorlarken Sen kendini yapayalnız hissediyorsan İçindeki boşluk büyüyor büyüyor seni yutuyorsa Ve s...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/siir-nedir-sair-kimdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suna Gelinin Türküsü', 'suna-gelinin-turkusu-ensar-aktas-mm8tl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sattınız beni bir mal gibi

Ne yaptınız siz, ne bana? 

Kırdınız beni bir dal gibi

Ne yaptınız siz, be ana? 

Nere gidem ben, ne yana? 

Ağlıyorum yana yana

Gelde kıyma şu canına

Girmektense el koynuna

Ne yaptınız siz, ne bana? 

Nere gidem ben, ne yana? 

Getirdiniz beni yol sonuna

Nere gidem ben, ne yana? 

Ağlıyorum yana yana

Gençliğimi siz çaldınız

Yaşamadan doya doya

Yüreğimi siz yaktınız

Sevemeden kana kana

Nere gidem ben, ne yana? 

Ağlıyorum yana yana

Gelde kıyma şu canına

Girmektense el koynuna

Ne yaptınız siz, ne bana? 

Nere gidem ben, ne yana? 

Getirdiniz beni yol sonuna

Nere gidem ben, ne yana? 

Ağlıyorum yana yana

Değer miydi dünya malına? 

Üç beş kuruş başlık parasına

Ne yaptınız siz, be ana

Attınız beni kurtlar sofrasına

Nere gidem ben, ne yana? 

Ağlıyorum yana yana

Gelde kıyma şu canına

Girmektense el koynuna

Ne yaptınız siz, ne bana? 

Nere gidem ben, ne yana? 

Getirdiniz beni yol sonuna

Nere gidem ben, ne yana? 

Ağlıyorum yana yana

(24.09.1986 tarihinde yazdığım

`Nere Gidem` isimli şiirimin türkü formatıdır.)  

Rotterdam,20.07.2002', 'Sattınız beni bir mal gibi Ne yaptınız siz, ne bana?  Kırdınız beni bir dal gibi Ne yaptınız siz, be ana?  Nere gidem ben, ne yana?  Ağlıyor...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/suna-gelinin-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirimsi', 'siirimsi-melek-midikoglu-z0tpk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana bir buse 

Vermek isterdim, 

Bir buse... 

İki buse... 

Üç buse...

Bütün buseleri, 

Sana vermek isterdim.', 'Sana bir buse  Vermek isterdim,  Bir buse...  İki buse...  Üç buse... Bütün buseleri,  Sana vermek isterdim....', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/siirimsi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Verdiysem de Ömrü', 'verdiysem-de-omru-fatih-kagan-yucel-jshzg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Verdiysem de ömrü yarin yoluna

Hala nazarında yokmuş kıymetim

Yoksa benzemem mi Tanrı kuluna

Bende ümmetiyim ol Muhammedin

Ademin neslisin soydan beşersin

Bazı gelir şaşar bazı düşersin

Gün olur bu yoldan sende geçersin

Yad el sevdan olur, ben muhannetin

ağustos 2002', 'Verdiysem de ömrü yarin yoluna Hala nazarında yokmuş kıymetim Yoksa benzemem mi Tanrı kuluna Bende ümmetiyim ol Muhammedin Ademin neslisin s...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kağan Yücel']::text[], 8.5, '{"poet":"Fatih Kağan Yücel","poet_slug":"fatih-kagan-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/verdiysem-de-omru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dudak Bildi', 'dudak-bildi-ensar-cevval-g7zmn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Suyun kıymetini bilirdi toprak

duysaydı, kuruyan damağın hasretini

görseydi, titreyen dudağın ıstırabını

hiç bırakır mıydı tatlı damlalarını

gözden düşen tuz sarılmışken dudağa.

Sözün kıymetini bilirdi dudak

bilseydi bir sevda türküsündeki hasreti

tutsaydı bir yüreğe düşmüş nefreti

hiç açık bırakırmıydı âh''ın kapısını

tenindeki can düşüyorken kucağa.

Ne su, ne toprak..

hiçbiri çare olamadı, yüreğe düşen sevdaya

ne yananı su söndürebildi

ne de göçeni toprak döndürebildi

sadece, dudak bildi; ''seni seviyorum'' dedi', 'Suyun kıymetini bilirdi toprak duysaydı, kuruyan damağın hasretini görseydi, titreyen dudağın ıstırabını hiç bırakır mıydı tatlı damlalarını...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dudak-bildi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdicek', 'sevdicek-fatih-kagan-yucel-3q82d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşünme hiç sonunu atla karşı kıyıya

