INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Adam', 'beyaz-adam-sunay-akin-d4wla', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beyaz adam 

küçücüktü ilk geldiğinde 

ve oturmaktan 

bütün kemikleri sızlıyordu 

büyük teknesinde 

Beyaz adam 

kızılderililerin sunduğu yiyeceklerle beslenip 

topraklarına uzandığında büyüdü 

bulutlar arasında 

barış içinde yaşayan 

manitu yerine 

tapmamızı istediği de 

işkence görüp 

çarmıha gerilen 

bir ölüydü 

Beyaz adam 

özgürlük adına 

dev bir kadın heykeli dikti 

doğu denizinin kıyısına 

ve her gece 

altında dans ettiğimiz yıldızları 

bayrak diye tutsak etti 

bir bez parçasına 

Beyaz adam 

özgürlük gibi adaleti de 

bir kadın heykeliyle simgeledi 

ama elinde terazi tutan 

zavallı kadın 

gözleri bağlı olduğu için 

kendisine tecavüz edenin 

kim olduğunu göremedi...', 'Beyaz adam  küçücüktü ilk geldiğinde  ve oturmaktan  bütün kemikleri sızlıyordu  büyük teknesinde  Beyaz adam  kızılderililerin sunduğu yiye...', ARRAY['Türk Edebiyatı','Şiir','Sunay Akın']::text[], 8.5, '{"poet":"Sunay Akın","poet_slug":"sunay-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/beyaz-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sone 66', 'sone-66-william-shakespeare-do5pd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vazgeçtim bu dünyadan tek ölüm paklar beni, 

Değmez bu yangın yeri, avuç açmaya değmez.

Değil mi ki çiğnenmiş inancın en seçkini, 

Değil mi ki yoksullar mutluluktan habersiz, 

Değil mi ki ayaklar altında insan onuru, 

O kızoğlan kız erdem dağlara kaldırılmış, 

Ezilmiş, hor görülmüş el emeği, göz nuru, 

Ödlekler geçmiş başa, derken mertlik bozulmuş, 

Değil mi ki korkudan dili bağlı sanatın, 

Değil mi ki çılgınlık sahip çıkmış düzene, 

Doğruya doğru derken eğriye çıkmış adın, 

Değil mi ki kötüler kadı olmuş Yemen'' e 

Vazgeçtim bu dünyadan, dünyamdan geçtim ama, 

Seni yalnız komak var, o koyuyor adama.

Çeviren: Can Yücel', 'Vazgeçtim bu dünyadan tek ölüm paklar beni,  Değmez bu yangın yeri, avuç açmaya değmez. Değil mi ki çiğnenmiş inancın en seçkini,  Değil mi ...', ARRAY['Türk Edebiyatı','Şiir','William Shakespeare']::text[], 8.5, '{"poet":"William Shakespeare","poet_slug":"william-shakespeare","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sone-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Sokağı', 'sevda-sokagi-i-brahim-sadri-1y7mo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben sevdanın oturduğu sokakta oturuyorum,

geceler hiç bitmiyor, ben hiç uyumuyorum 

gecenin efkarı iniyor perde perde, 

sevdanın hayali vuruyor arada bir içime. 

Ben sevdanın oturduğu sokakta oturuyorum,

hani şu perdelerinde mavi kuş resimleri olan 

Ali bakkalın hemen yanında, 17 numara, 

o kırgın hayatın tam ortasında 

hani duvarlarında hala yazılar olan o sokakta 

biri gurbetin, biri ihanetin, 

biri de seni böyle sevmenin hikayesi. 

Sevdanın camı bana bakıyor, ben cama 

ve bak sen şu serencama 

pencere önünde menekşeler, hatmiler 

bi de gece sefası, bi de haytalığı adamın 

abi bi de sevdanın hayali vuruyor arada içime,

iyi oluyor diyorum bu sana iyi oluyor. 

Arada bir arkadaşlar geliyor, laflıyoruz ordan burdan 

anlarsın ya güzel abim, 

iç cebimde bir umut doğuyor, 

bi de nerden bulduysam resmi sevdanın, 

resimde sevda inadına gülüyor, 

sevdam gayriresmi bilmekteyim 

gel ki benim abim 

biraz da üstümüzde macera güzel duruyor

yani yakışıyor adama yakışıklı bir sevda. 

Hayat haybeye vurmuyor yüzümüze belasını,

hayat sokağımızda bir kehribar tespih gibi, 

döküyor tanelerini takır takır yüzümüze. 

Ben sevdanın oturduğu sokakta oturuyorum, 

geceler hiç bitmiyor, ben hiç uyumuyorum, 

ağzımda fiyakalı bir ıslık, 

zulamda ağır yarası sevdanın. 

Ali bakkalın çırağı Metin anlıyor halinden insanın. 

Metin nedir senin niyetin? 

Kap bakalım abine bir taze ekmek, biraz zeytin 

bu akşam yine odamda efkar var 

anlarsın ya Metin, adamın halinden adam anlar...', 'Ben sevdanın oturduğu sokakta oturuyorum, geceler hiç bitmiyor, ben hiç uyumuyorum  gecenin efkarı iniyor perde perde,  sevdanın hayali vuru...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sadri']::text[], 8.5, '{"poet":"İbrahim Sadri","poet_slug":"i-brahim-sadri","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sevda-sokagi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakarken', 'bakarken-sair-masmavi-ryb6v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben bakarken 

