INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönek', 'donek-erdogan-cokduru-r9gtf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Darağacı 

Ol 

Ihlamur ağacı. 

Ihlamur ağacı 

Ol 

Darağacı...', 'Darağacı  Ol  Ihlamur ağacı.  Ihlamur ağacı  Ol  Darağacı......', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çokduru']::text[], 8.5, '{"poet":"Erdoğan Çokduru","poet_slug":"erdogan-cokduru","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/donek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Bir Sabah', 'guzel-bir-sabah-jacques-prevert-gpho3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Korkmazdı kimseden

Ya da hiçbir şeyden

Fakat bir sabah güzel bir sabah

Bir şey gördüğüne inandı

Ama bir şey yok dedi

Ve haklıydı

Hiç şüphe duymadığı mantığıyla

Bir şey yoktu

Fakat sabah aynı sabah

Birisini duyduğuna inandı

Ve açtı kapıyı

Ve kapattı kimse yok diyerek

Ve haklıydı

Hiç şüphe duymadığı mantığıyla

Kimse yoktu

Aniden bir korkuya kapıldı

Ve anladı ki yalnızdı

Ama yapayalnız da değil

Yaşıyordu beraberce

Karşısındaki hiç kimseyle

(fransızcadan, Faruk Günay)', 'Korkmazdı kimseden Ya da hiçbir şeyden Fakat bir sabah güzel bir sabah Bir şey gördüğüne inandı Ama bir şey yok dedi Ve haklıydı Hiç şüphe d...', ARRAY['Türk Edebiyatı','Şiir','Jacques Prevert']::text[], 8.5, '{"poet":"Jacques Prevert","poet_slug":"jacques-prevert","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/guzel-bir-sabah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahvaltı', 'kahvalti-jacques-prevert-gdmu8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kahveyi

Fincana koydu

Sütü 

Kahveye koydu

Şekeri 

Sütlü kahveye koydu

Ve fincanı bıraktı

Benimle konuşmadan

Bir sigara

Yaktı

Sigara dumanıyla

Yuvarlaklar yaptı

Külleri

Küllüğe koydu

Benimle konuşmadan

Bana bakmadan

Kalktı

Yağmurluğunu giydi

Yağmur yağıyordu

Ve gitti

Yağmurun altında

Tek bir kelime etmeden

Bana bakmadan

Ve ben 

Alıp başımı 

Ellerimin arasına 

Ağladım.

(fransızcadan, Faruk Günay)', 'Kahveyi Fincana koydu Sütü  Kahveye koydu Şekeri  Sütlü kahveye koydu Ve fincanı bıraktı Benimle konuşmadan Bir sigara Yaktı Sigara dumanıyl...', ARRAY['Türk Edebiyatı','Şiir','Jacques Prevert']::text[], 8.5, '{"poet":"Jacques Prevert","poet_slug":"jacques-prevert","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kahvalti-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gezgin Foto', 'gezgin-foto-erdogan-cokduru-qayd4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '- Hakkı’ya – 

Hakkı’ya göre yaşamak 

Şip - şak...', '- Hakkı’ya –  Hakkı’ya göre yaşamak  Şip - şak......', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çokduru']::text[], 8.5, '{"poet":"Erdoğan Çokduru","poet_slug":"erdogan-cokduru","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/gezgin-foto-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Porsuk Çayı', 'porsuk-cayi-erdogan-cokduru-g1zgl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Demiryolu boyunca Porsuk 

Usul usul akıyordu.

Büyümesi ağacın, meyvenin 

Çoluğun, çocuğun gülmesi hep 

Porsuk’a bakıyordu..

Demiryolu boyunca Porsuk 

Duymadan 

Anlamadan olan-biteni

Usul usul akıyordu...', 'Demiryolu boyunca Porsuk  Usul usul akıyordu. Büyümesi ağacın, meyvenin  Çoluğun, çocuğun gülmesi hep  Porsuk’a bakıyordu.. Demiryolu boyunc...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çokduru']::text[], 8.5, '{"poet":"Erdoğan Çokduru","poet_slug":"erdogan-cokduru","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/porsuk-cayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askin Gözünde', 'askin-gozunde-faruk-unal-4ltpd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'askin gözünde bir cocuktum

beni büyütmeden gitdin

sarmadan koklamadan

sevip öpmeden gitdin

gitdin beni dertlere gömdün

hasretin avcuna koyup gitdin

beni deli edip gitdin

arkanda bir yetim koydun gitdin

yeniden sincirlere vurun, yüreyimi

atin anahtarini bir nehire

nehir götürsün bir denize

deniz atsin ta en derin yerine

görmeyeceksem birdaha

istemiyorum ben aski bir da

alip gitsin benide sürgüne

o bana gelmiyorsa', 'askin gözünde bir cocuktum beni büyütmeden gitdin sarmadan koklamadan sevip öpmeden gitdin gitdin beni dertlere gömdün hasretin avcuna koyup...', ARRAY['Türk Edebiyatı','Şiir','Faruk Ünal']::text[], 8.5, '{"poet":"Faruk Ünal","poet_slug":"faruk-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askin-gozunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmek', 'olmek-erdogan-cokduru-abf8x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben varım diye var yaşamak...', 'Ben varım diye var yaşamak......', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çokduru']::text[], 8.5, '{"poet":"Erdoğan Çokduru","poet_slug":"erdogan-cokduru","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/olmek-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugünce', 'bugunce-erdogan-cokduru-a1q7z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İyi 

Sen bekle burda 

Ben birazdan gelirim

Şu pis var ya 

Şu kötü 

Şu dönek..

Senden önce onla görüşmem

İyi 

Sen bekle burda 

Ben birazdan 

Gelir sana acırım...', 'İyi  Sen bekle burda  Ben birazdan gelirim Şu pis var ya  Şu kötü  Şu dönek.. Senden önce onla görüşmem İyi  Sen bekle burda  Ben birazdan  ...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çokduru']::text[], 8.5, '{"poet":"Erdoğan Çokduru","poet_slug":"erdogan-cokduru","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bugunce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek', 'beklemek-erdogan-cokduru-t644x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Milyar milyar bekliyoruz bunca yıl 

Anlamıyor gözlerimiz renklerin dilinden. 

O şey gene aynı yerde 

Gene aynı açlıkla tetikte duyarlığımız 

Beklemek oldukça sözlüklerde...', 'Milyar milyar bekliyoruz bunca yıl  Anlamıyor gözlerimiz renklerin dilinden.  O şey gene aynı yerde  Gene aynı açlıkla tetikte duyarlığımız ...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çokduru']::text[], 8.5, '{"poet":"Erdoğan Çokduru","poet_slug":"erdogan-cokduru","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/beklemek-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Macar Rapsodisi', 'macar-rapsodisi-erdogan-cokduru-aoxkf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '- İhtilâl Macaristanına – 

Tanrı birlikte yaratmıştır 

Özgürlüğüyle kulunu. 

Çağlar sonraki sen 

Bil bunu.. 

Öldüm özgürlüğüm için şimdi 

Öldürdüler çoluk - çocuğumu. 

Tarih yazmasın istemiyorum 

Çağlar sonraki sen 

Bilme bunu...', '- İhtilâl Macaristanına –  Tanrı birlikte yaratmıştır  Özgürlüğüyle kulunu.  Çağlar sonraki sen  Bil bunu..  Öldüm özgürlüğüm için şimdi  Öl...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çokduru']::text[], 8.5, '{"poet":"Erdoğan Çokduru","poet_slug":"erdogan-cokduru","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/macar-rapsodisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
