INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönemeç', 'donemec-erdogan-cokduru-835lx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ko dursun aramızdaki duvar 

Ben hep burada olacağım. 

İster orada ol sen, ister olma 

Seni orada bileceğim...', 'Ko dursun aramızdaki duvar  Ben hep burada olacağım.  İster orada ol sen, ister olma  Seni orada bileceğim......', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çokduru']::text[], 8.5, '{"poet":"Erdoğan Çokduru","poet_slug":"erdogan-cokduru","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/donemec-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep', 'hep-erdogan-cokduru-lr26i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnsan bu 

