INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adsız', 'adsiz-erdogan-cokduru-9nyo0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen belki bir şarkısın rüzgârların getirdiği 

Belki de bir rüzgârsın şarkı söyleyen...', 'Sen belki bir şarkısın rüzgârların getirdiği  Belki de bir rüzgârsın şarkı söyleyen......', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çokduru']::text[], 8.5, '{"poet":"Erdoğan Çokduru","poet_slug":"erdogan-cokduru","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/adsiz-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoş Geldin', 'hos-geldin-erdogan-cokduru-q9y37', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '- Oya’ya – 

Hep böyle bahar akşamlarında gel emi 

Saçlarını bahar yelleri savursun ağır-aksak 

Ve dudaklarında mutluluğun en güzeli 

Gayrı gözlerim yaşarmıyacak.. 

Sarmaşıklar gibi sarılacağım sana 

Gözlerim gözlerine değecek sabahlara kadar. 

Yarım-yamalak türküler mırıldanacağım 

Yarım-yamalak anılar.. 

Göreceksin baştan sona varlığını yalnızlığımda 

Ve neden sevdiğimi anlıyacaksın insanları. 

Onlara bunca seslenişim boşuna değil 

İnsanlar sen demek aşağı-yukarı..', '- Oya’ya –  Hep böyle bahar akşamlarında gel emi  Saçlarını bahar yelleri savursun ağır-aksak  Ve dudaklarında mutluluğun en güzeli  Gayrı g...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çokduru']::text[], 8.5, '{"poet":"Erdoğan Çokduru","poet_slug":"erdogan-cokduru","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hos-geldin-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Kavusuyordu', 'deniz-kavusuyordu-faruk-unal-nefi9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Deniz Kavusuyordu

Geceleri sahilde yildizlara bakardik seninle

Elimi tutardin gözlerime bakardin 

Kulagima sessisce seni seviyorum derdin

o anda hic bir sey istemezdim

                     Simdi yalniz kaldim sahilde

                     Gözyaslarim doldu denize

                     Kiskandim sahili bile

                     Deniz kavusuyordu sahiline

                                            Faruk Ünal', 'Deniz Kavusuyordu Geceleri sahilde yildizlara bakardik seninle Elimi tutardin gözlerime bakardin  Kulagima sessisce seni seviyorum derdin o ...', ARRAY['Türk Edebiyatı','Şiir','Faruk Ünal']::text[], 8.5, '{"poet":"Faruk Ünal","poet_slug":"faruk-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/deniz-kavusuyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelince', 'gelince-erdogan-cokduru-ovr3h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzat ellerini minnacık 

Yaklaştıkça daha derin gözlerin. 

Geceler böyle güzel olurmuş demek 

Uzat ellerini minnacık 

Sabahı mı özlerim.. 

Konuş, daha konuş, hep konuş 

«Sen» de, «Ben» de ikide bir. 

Takvimler değişsin duvarlarda sonsuz 

Konuş, daha konuş, hep konuş 

Seven nasıl susabilir..', 'Uzat ellerini minnacık  Yaklaştıkça daha derin gözlerin.  Geceler böyle güzel olurmuş demek  Uzat ellerini minnacık  Sabahı mı özlerim..  Ko...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çokduru']::text[], 8.5, '{"poet":"Erdoğan Çokduru","poet_slug":"erdogan-cokduru","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gelince-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ibret-i Alem', 'ibret-i-alem-faruk-unal-2u4yp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ibret-i alem

askimizin tek suclusu benim

beni sincirlere verin

sokak sokak dolasdirin

ibrret-i alem icin

boynuma bir levha asin

korkak diye yazin

sokak sokak dolasdirin

ibrret-i alem icin

buda azgelir bana 

askimi gömdüyüm gibi kalbime

benide canli canli topragagömün

ibret-i alem icin

      

       Faruk Ünal', 'ibret-i alem askimizin tek suclusu benim beni sincirlere verin sokak sokak dolasdirin ibrret-i alem icin boynuma bir levha asin korkak diye ...', ARRAY['Türk Edebiyatı','Şiir','Faruk Ünal']::text[], 8.5, '{"poet":"Faruk Ünal","poet_slug":"faruk-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ibret-i-alem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Kayib Ettimya', 'seni-kayib-ettimya-faruk-unal-dyemc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sana askimi oldurürken

hic aklima gelmezdi

tekrar canlanacagini

kabuz gibi gelecegini

sana haksizlik etim biliyoyrum

kendimi afedemiyorum

ne yapsan haktir

beni vursan haktir

sanmaki seni sevmedim 

seni senden cok sevdim

kalbimde vardi yaran

yeniden acildi yaran

kimini koluma yazdim 

kimini duvarlara 

kimini agaclara 

seni kalbime yazdim gülüm

günesin atesi hic kalir 

senin hasretin yaninda

yanipta ölmemek varya

sana öyle hasretim gülüm

beni yetim biraktin

hasretin eline

yas dolar gözlerime

garip gönlüm sitemde

umutlara muhtac oldum

seni bir gün görürüm diye

sakin düsme birinin eline

felegini sasirtir gelir diye

seni bir gün unutmadim 

sen unutsan bile

sen heran aklimdaydin

sen beni düsünmesen bile

askin simiyor icime

bana bu iskence

sensiz kalbim 

seni arar koca sehirde

yillar sonra gönlümde uyandin

beni sen yeniden vurdun

öncesinden beter oldum

sana yeniden agsik oldum

hayalin beni deli ediyor

gönlüm bana isyan ediyor

bu aci bana az geliyor

beni cikmazlara sürüklüyor

artik bitdim sensis

kaldim kimsesis

her sey isteksis

ölüyorum sensis

kanniyor hertaraf sensis

yikildim caresis

askim pencesis

ariyor seni habersis

hertaraf aci kokuyor

hasret kahbece gülüyor 

icim icime simiyor

hasret kahbece gülüyor

seni seviyorum 

seni zaten seviyordum

seni daha da cok seviyorum

seni hic unutmadimki gülüm', 'sana askimi oldurürken hic aklima gelmezdi tekrar canlanacagini kabuz gibi gelecegini sana haksizlik etim biliyoyrum kendimi afedemiyorum ne...', ARRAY['Türk Edebiyatı','Şiir','Faruk Ünal']::text[], 8.5, '{"poet":"Faruk Ünal","poet_slug":"faruk-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/seni-kayib-ettimya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cizgiler Yetmiyor', 'cizgiler-yetmiyor-faruk-unal-r277r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yidizlar senin cemalini cizer gökyüzünde

seni her gün göreyim diye

cizgiler yetmiyor bana

gercek olup gelsene kollarima

gercek olsa her rüya

ne güzel olurdu dünya

hayel etme bosua

kahrolursun sonunda

karsiliksiz hic bir sey olmaz

zorla güzelik olmaz

iste beni ac yüreyini

gel artik sabrimi tasirma', 'yidizlar senin cemalini cizer gökyüzünde seni her gün göreyim diye cizgiler yetmiyor bana gercek olup gelsene kollarima gercek olsa her rüya...', ARRAY['Türk Edebiyatı','Şiir','Faruk Ünal']::text[], 8.5, '{"poet":"Faruk Ünal","poet_slug":"faruk-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cizgiler-yetmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonra', 'sonra-erdogan-cokduru-mxyix', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen gittikten sonra 

Bu şehre İzmir demiyeceğim. 

Gözüm ısırmayacak bu palmiyeleri 

Bu rıhtımda hiç gezmemiş olacağım. 

Sen gittikten sonra 

Kimbilir ne’olacağım..', 'Sen gittikten sonra  Bu şehre İzmir demiyeceğim.  Gözüm ısırmayacak bu palmiyeleri  Bu rıhtımda hiç gezmemiş olacağım.  Sen gittikten sonra ...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çokduru']::text[], 8.5, '{"poet":"Erdoğan Çokduru","poet_slug":"erdogan-cokduru","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sonra-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '18.10 Vapuru', '18-10-vapuru-erdogan-cokduru-184js', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Onsekiz-on vapuruna binme Karşıyaka’dan 

Nedenleri sorma söyleyemen dilimi kestiler 

İki bıçak dayadılar sırtıma sana gelemem

Salonda siyah bir kedi dolaşacak ayaklarına 

Bir adam cigarasını yakacak yanıbaşında: işte o 

İskelenin ucunda bir adam duracak: işte o 

İkinci mevkide cilet satacak bir adam; işte o 

İşte o adam yapacak sana napacaksa

Kadifekale’den işaret verecekler 

Alsancak açıklarında ışıkları söndürecekler 

Bir kayık duracak gümrük’e doğru göremiyeceksin

Onsekiz-on vapuruna binme Karşıyaka’dan 

Seni öldürecekler.', 'Onsekiz-on vapuruna binme Karşıyaka’dan  Nedenleri sorma söyleyemen dilimi kestiler  İki bıçak dayadılar sırtıma sana gelemem Salonda siyah ...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çokduru']::text[], 8.5, '{"poet":"Erdoğan Çokduru","poet_slug":"erdogan-cokduru","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/18-10-vapuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahraman', 'kahraman-erdogan-cokduru-60bti', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '- Atila İlhan’a – 

Saçakların altına çekilince insanlar 

Yapa-yalnız dolaşırım sokaklarda 

Düşünürüm ki bütün pencerelerde sen varsın 

Sakın bana acıma..', '- Atila İlhan’a –  Saçakların altına çekilince insanlar  Yapa-yalnız dolaşırım sokaklarda  Düşünürüm ki bütün pencerelerde sen varsın  Sakın...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çokduru']::text[], 8.5, '{"poet":"Erdoğan Çokduru","poet_slug":"erdogan-cokduru","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kahraman-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karnaval Gecesi', 'karnaval-gecesi-erdogan-cokduru-5n3xh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir karnaval gecesindeyim şimdi 

Anasını yitirmiş çocuklarca şaşkın. 

Ellerinin sıcaklığı hala ellerimde 

Akasyaların şarkısını sen de duyuyor musun? . 

Akvaryumdaki balıklarla konuşuyorum saatlardır 

Gözleri sanki senin gözlerin 

Sanki senin ağzın ağızları. 

Öylesine dolmuşsun ki içime 

Unutamıyorum buncacık anıları. 

Luna parkın orta yerinde taşım 

Bütün döner dolaplarda sen varsın 

Senin eteklerin uçuşuyor bütün atlıkarıncalarda. 

Luna parkın orta yerinde taşım 

Şarkıların bana ettiğini sayma.. 

Şarkıların bana ettiğini sayma 

Sen bu kadar benim değildin aslında 

Ben şiirler dolusu yalan söyledim. 

Dudaklarım dudaklarına değmemişti daha 

Değdi dedim. 

Sen bu kadar benim değildin aslında 

Ben öyle istedim.. 

Şimdi seni olmadığın şehirlerde arıyorum 

Mutlu insan çığlıkları dolduruyor kulaklarımı. 

Bu gece yüzüme yıldız yağıyor nedense 

Ben bu insanlardan değilim 

Tek başıma taşıyamam bu gökyüzünü. 

Hadi gel; yalnız koma beni 

Hadi gel; işte ellerim.. 

Bir karnaval gecesindeyim yapa-yalnız 

Bütün döner dolaplar boş 

Bütün atlıkarıncalar terkedilmiş. 

Bir karnaval gecesindeyim diyorum 

Delirmiş..', 'Bir karnaval gecesindeyim şimdi  Anasını yitirmiş çocuklarca şaşkın.  Ellerinin sıcaklığı hala ellerimde  Akasyaların şarkısını sen de duyuy...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çokduru']::text[], 8.5, '{"poet":"Erdoğan Çokduru","poet_slug":"erdogan-cokduru","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/karnaval-gecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '565. Sokak', '565-sokak-erdogan-cokduru-he1gl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yarın yağmur yağacak dediğim sokağa 

Yarın yeşil bereni giymeyi unutma. 

Ben belki bir meyhanede olacağım o gün 

Küçük insanlarla omuz-omuza içeçeğim 

Onlara seni anlatacağım kulakların çınlıyacak 

Ufacık burnundan bahsedeceğim 

İncecik dudaklarından 

Aşksız adamlar beni vuracaklar. 

Birdenbire şarkılar bitecek kulaklarımda 

Beni bir direğin altına atacaklar 

Reklam ışıkları farlar bölemiyecek uykumu 

Bütün ayak sesleri bende bitecek. 

Orhan sana durumu bildirecek söyledim 

Oyuncağını yitirmiş çocuklarca ağlıyacaksın 

Biliyorum koşamıyacaksın bana gelirken 

Parke taşları takılacak ayaklarına 

Sarhoş adamlar sana gülecekler sıkılacaksın 

Beni göreceksin yüzü-koyun yerdeyim 

Bir çocuk kuğular şarkısını söyliyecek karanlıklarda 

Zambaktan gemileri batıracaklar. 

Sol iç cebimde mektupların olacak alırsın 

İki resmin mutlaka cüzdanımdadır bak 

Benimkileri Orhan’a ver o napacağını bilir. 

Ağlıyacaksan yüzünü geri çevir de ağla 

Yoksa sana acıyacağım kızacaksın 

Seni ıslak yanaklarından bilecekler yoksa 

Beni hiç görmemiş gibi yaparsın 

Yüzüme kaybolmuş bir adam gibi bakarsın 

Sonra üstünde o eski kimsesizliğin 

Kirpiklerinin arasında ebem kuşakları 

Çelimsiz vücudunda kasılmış bir zenci kahrı 

565. sokağa çıkarsın.', 'Yarın yağmur yağacak dediğim sokağa  Yarın yeşil bereni giymeyi unutma.  Ben belki bir meyhanede olacağım o gün  Küçük insanlarla omuz-omuza...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çokduru']::text[], 8.5, '{"poet":"Erdoğan Çokduru","poet_slug":"erdogan-cokduru","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/565-sokak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Aşkı', 'guz-aski-erdogan-cokduru-h3dtr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gece düşün şimdi sonbahardan 

Yağmurlar daha başlamamış olsun. 

Bir tek koy bunca çift arasına 

Yalnızlığımı anlıyor musun? . 

Tut ki otobüs duraklarında ağlıyorum 

Tırnaklarımı yiyorum hıncımdan. 

Tut ki geceler bir hançer gibi saplanıyor bağrıma 

Bir hançer gibi utanmadan.. 

Ben asiyim, isyankarım yaşamalar arasında 

Mutluluğun inadına yumuyorum gözlerimi. 

Susmuşsam, dayanıyorsam, katlanıyorsam erkekçe 

Anla biraz 

Biraz duy beni.. 

Bu kahpece terkediliş yok mu 

Ellerinin kurtuluşu yok mu ellerimden. 

Gözlerin gözlerime yabancı bakmıyor mu 

Ölüyör kalbim kendiliğinden.. 

Artık bu şarkıyı hatırlama 

Bu şehri, bu sokakları aklından çıkar. 

Yaprak dökümü demişler adına 

Bu da bir aşkta bir sonbahar.. 

Dedim ya 

Bu da bir aşkta bir sonbahar. 

Bir gece düşün şimdi sonbahardan 

Uğultulu, soğuk ve yoksul 

Ve bir adam düşün parklarda sabahlıyan..', 'Bir gece düşün şimdi sonbahardan  Yağmurlar daha başlamamış olsun.  Bir tek koy bunca çift arasına  Yalnızlığımı anlıyor musun? .  Tut ki ot...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çokduru']::text[], 8.5, '{"poet":"Erdoğan Çokduru","poet_slug":"erdogan-cokduru","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/guz-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı', 'yalanci-erdogan-cokduru-n4gmy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hani sen benim karım olacaktın 

Bana çocuk doğuracaktın 

Yemeğimi pişirecektin günde üç öğün 

Hani sen bütün bunları yapacaktın 

Ne diye öldün..', 'Hani sen benim karım olacaktın  Bana çocuk doğuracaktın  Yemeğimi pişirecektin günde üç öğün  Hani sen bütün bunları yapacaktın  Ne diye öld...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çokduru']::text[], 8.5, '{"poet":"Erdoğan Çokduru","poet_slug":"erdogan-cokduru","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yalanci-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Körebe', 'korebe-erdogan-cokduru-267xa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İlk kadehi şerefine kaldırıyorum 

Son kadehin şerefsiz dediği 

Bunlar hep gece yarıları oluyor - yirmidörtlerde 

Susuk bir yalnızlığım oluyor - anasonlu 

Sen aslında yoksun ama gözlerin var 

Ama gözlerinin kalleş seslenişi var yol ağızlarında 

Bu kentler dufy’den böyle 

Böyle çıt kırıldım böyle korkak 

Sonra bütün ışıkları söndürmek işten değil 

Ellerini ayaklarını mesela -yani seni- işten değil 

Biz nasıl olsa hiçiz biliyorsun - olan çiçeklere oluyor 

Biliyorsun bir yumduk mu gözlerimizi açmamacasına 

Olan gökyüzüne oluyor - kahrımıza yetmiyor maviliği 

Ya da ellerini sallama rıhtımlarda 

Dudaklarını ısırıp ısırıp ağlama yenileceğim 

Üstelik son yenilgim olacak haberin olsun 

Bu bir kaçış değil - bir kurtuluş hiç değil 

Belki de bir arayış bir körebemsi yaşantıda 

İyisi mi indir perdelerini - bir başına çoğalırsın', 'İlk kadehi şerefine kaldırıyorum  Son kadehin şerefsiz dediği  Bunlar hep gece yarıları oluyor - yirmidörtlerde  Susuk bir yalnızlığım oluyo...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çokduru']::text[], 8.5, '{"poet":"Erdoğan Çokduru","poet_slug":"erdogan-cokduru","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/korebe-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ansıma', 'ansima-erdogan-cokduru-07lmu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İşi ne gözlerinin bağışlamasız karanlıkta 

