INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Duası', 'yagmur-duasi-erdogan-cokduru-ia7yc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '- Ömer Rıza Doğrul’a – 

Sürme 

Sürme tarlayı Memiş. 

Sal gitsin sabanı, öküzü 

Sil gitsin terler yabana. 

Sürme 

Sürme tarlayı Memiş 

Madem Allah istememiş...', '- Ömer Rıza Doğrul’a –  Sürme  Sürme tarlayı Memiş.  Sal gitsin sabanı, öküzü  Sil gitsin terler yabana.  Sürme  Sürme tarlayı Memiş  Madem ...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çokduru']::text[], 8.5, '{"poet":"Erdoğan Çokduru","poet_slug":"erdogan-cokduru","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yagmur-duasi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ama', 'ama-erdogan-cokduru-82xe2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu sokaklar seni tanlmasa da olur 

Bu insanlar seni görmese de olur. 

Sen onları bilmezsen 

Olan sana olur..', 'Bu sokaklar seni tanlmasa da olur  Bu insanlar seni görmese de olur.  Sen onları bilmezsen  Olan sana olur.....', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çokduru']::text[], 8.5, '{"poet":"Erdoğan Çokduru","poet_slug":"erdogan-cokduru","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ama-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hamal Recep', 'hamal-recep-erdogan-cokduru-ckjo9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüklendi sandığı Recep 

Yürüdü, 

 yürüdü, 

  yürüdü.. 

Ter sızıyordu alnından yanaklarına 

Gerdanından karnına ter sızıyordu. 

Bir sancı vardı bir yerinde bilinmedik 

Durdu.. 

Ekmek parası vardı işin içinde 

Çoluk-çocuk nafakası vardı. 

Yaşamak 

Yaşatmak vardı düpe-düz.. 

Yüklendi sandığı Recep 

Deh dedi eşek kaderine bir yol daha 

Yürüdü...', 'Yüklendi sandığı Recep  Yürüdü,   yürüdü,    yürüdü..  Ter sızıyordu alnından yanaklarına  Gerdanından karnına ter sızıyordu.  Bir sancı var...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çokduru']::text[], 8.5, '{"poet":"Erdoğan Çokduru","poet_slug":"erdogan-cokduru","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hamal-recep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
