INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgeler', 'golgeler-oguzkan-bolukbasi-okzoo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gölgelerimize basmayı denerdik çocukken, 

gizlice bizi görse kaçacakmış gibi, ne gölgemize basabildik ne de gölgemiz bizi bıraktı, ne zaman bir ışık düşse üzerimize gölgeler görünüverirdi.

Gölgesiz bir aydınlığın süresi kısacıktı

Tam öğle üzeri

Sen görünürdün

Bir gözaçıp kapama mesafesinde zamanın

O zaman anlamıştım

Diyalektiğini aşkın

Tüm çelişkilerini varolmanın

Ve mümkünatsızlığını gölgelere basmanın

Ve gölgesiz yaşamanın

Alıştık bu beraberliğe, hayallerimiz karıştı gölgelerimizle, 

umutlarımız çelişti hayallerimizle, merkezi bir kuvvetle çekilirken anaforuna hayatın, dışavurmak için direndik yapıştık kaldık duvarlarına bir sirkin, hayat dursa düşeceğiz, döndükçe başımız dönecek midemiz bulanacak tutunacak biryer de yok, kaygan duvarlarında yaşamanın.

Senin ismini bağırdım

Tut beni aşağıdaysan

Ya da çek beni yukardaysan

Işığın hızı geçti sesimin hızını

Uzadıkça uzadı gölgeler

Zamanın o vahşi çizgilerinde

Yüzümde yer yer karanlık

Yer yer aydınlık girişimler

Ve o duygusal kırınımlar

Sen duymadın sesimi

Sen gelmedin

Herşeyi tam bilemezdim

Bir belirsizlik hengamesinde

Seni bilsem beni bilemiyordum

Beni bilsem seni bilemiyordum.

Işığın geçmesini istiyorum içimden, gölgemin yokolmasını saydam, görünmez ve renksiz, 

ateşi elimde tutmak istiyorum yanmadan

evrenin adacıklarında dolaşmak bıkmadan usanmadan, 

yıldız yağmurlarında kalmak ıslanmadan.

Olur mu acaba', 'Gölgelerimize basmayı denerdik çocukken,  gizlice bizi görse kaçacakmış gibi, ne gölgemize basabildik ne de gölgemiz bizi bıraktı, ne zaman ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/golgeler-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidenin Ardından', 'gidenin-ardindan-hasan-aydin-fe7bu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hangi kudret koparır birleşen iki ruhu

Ki, olmadıkça kalleş, bencil tilki güruhu

Vicdanı perdelerse üç kuruşluk menfaat

Göz avcı gözü olur ve et yığını âhu

Madem ki tâb-ı âdem şehvet ile malûldur

Elzemdir kul edinsin, İblis endam-ı şuhu

İffet imiş, vefaymış... neyine namussuzun

Emelinden mukaddes bağ mı olurmuş ya hu! 

Vahiy birleştirse de tertemiz iki ruhu

Kirletir ırz-i pâki habis tilki güruhu', 'Hangi kudret koparır birleşen iki ruhu Ki, olmadıkça kalleş, bencil tilki güruhu Vicdanı perdelerse üç kuruşluk menfaat Göz avcı gözü olur v...', ARRAY['Türk Edebiyatı','Şiir','Hasan Aydın']::text[], 8.5, '{"poet":"Hasan Aydın","poet_slug":"hasan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gidenin-ardindan-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtiyardan', 'i-htiyardan-hasan-aydin-gycea', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kurudur sâikiyle vazgeçme ihtiyardan

Çûn tohumun makbulü çıkar kuru hıyardan

Taze görse avını hemen bulur tavını

Lâkin mukavim olmaz çabuk düşer ayardan

Erbab-ı mest mesh ile temdit eder hazzını

Duhul-huruç ashabı bîhaberdir tımardan

Genç şehveti fevridür; usul-erkân tanımaz

Gâh cûş edüp cân alur, gâh eder itibardan

Zaman bazı şeyleri alsa da ihtiyardan

Pîr-i âdem evlâdür nice taze hıyardan', 'Kurudur sâikiyle vazgeçme ihtiyardan Çûn tohumun makbulü çıkar kuru hıyardan Taze görse avını hemen bulur tavını Lâkin mukavim olmaz çabuk d...', ARRAY['Türk Edebiyatı','Şiir','Hasan Aydın']::text[], 8.5, '{"poet":"Hasan Aydın","poet_slug":"hasan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ihtiyardan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Sessizligi', 'gecenin-sessizligi-necmettin-karaman-yhuq8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin sessizliginde uykum kaçıyor

Kalkıyor oturuyor, olmadı yatıyorum

Gözlerimi kapayıp uyumak istiyorum

Sağıma dönüyorum, nafile

soluma dönüyorum, imkansız

Uykum kaçtı bir kere ne yapsam faydasız

Rüzgarın sesi geliyor bir anda kulağıma

Derdin nedir der gibi dönüyor etrafımda

Terlemişim, git dersem gider mi uzağıma

Rüzgar fısıldıyor sanki

Haydi artık uyuma der gibi kulağıma

Meğer onun  da anlatacakları varmış

Çok uzaklardan gelip

Geçiyormuş buradan

Konuşmak istiyormus Hava’dan ve Su’dan

Duramıyor bir türlü

Sanki onu iten var arkasından

Gecenin sessizliği galip geliyor o an

Haydi kaldığın yerden uyumaya devam.....

İstanbul,9 Ağustos 2003', 'Gecenin sessizliginde uykum kaçıyor Kalkıyor oturuyor, olmadı yatıyorum Gözlerimi kapayıp uyumak istiyorum Sağıma dönüyorum, nafile soluma d...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Karaman']::text[], 8.5, '{"poet":"Necmettin Karaman","poet_slug":"necmettin-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gecenin-sessizligi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün', 'bir-gun-mustafa-i-lhan-guldemir-4x0uw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gün söyleyeceksin özlediğini

Her yerde beni aradığını

Hep andığını, düşündüğünü

Yolumu gözlediğini söyleyeceksin

Bir gün söyleyeceksin yokluğumda 

Her an beni konuştuğunu

Herkeze anlattığını, sorduğunu

Dönmemi istediğini söyleyeceksin

Bir gün söyleyeceksin özlediğini

Günaydın diye seslenişimi

İyi akşamlar dileyişimi

Alo diyen sesimi özlediğini söyleyeceksin

Bir gün söyleyeceksin özlediğini

Sabah sarılıp öperek, tebessüm etmek

Akşam sarlıp üzülerek özleyeceğini

Sabahı beni görmek için beklediğini söyleyeceksin

Bir gün söyleyeceksin beni sevdiğini

Yokluğumda, göremediğinde

Sesimi duyamadığında, beni cok sevdiğini, 

Bana itiraf etmek istediğini söyleyeceksin.

Geç kalacaksın sevgilim 

O gün ben olmayacağım 

Söyleyeceklerini gökyüzüne yazki

Benim için düşündüklerini öğreneyim....', 'Bir gün söyleyeceksin özlediğini Her yerde beni aradığını Hep andığını, düşündüğünü Yolumu gözlediğini söyleyeceksin Bir gün söyleyeceksin y...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İlhan Güldemir']::text[], 8.5, '{"poet":"Mustafa İlhan Güldemir","poet_slug":"mustafa-i-lhan-guldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-gun-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Yıllar', 'kayip-yillar-i-brahim-bayraktar-sj8kk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana kalbim kırık benim, bunu hiç bilmedin, 

Zalimlere gül dağıttın, bana diken vermedin, 

Hep riyakâr davrandın, gerçekleri görmedin, 

Sen gülseydin yüzüme belki bende gülerdim.

Ömrüm, sensiz geçen günleri saymakla geçti, 

Rakamlar tecrübesiz, zaman kifayetsiz kaldı, 

Elimde gonca güler, kalbimde aşkın kemendi, 

Özleminle yorgun gözlerim hep seni bekledi.

Elde avuçta bir şey yok, anız bastı gönlümüzü, 

Zalim felek hep çevirdi, doğru giden yönümüzü, 

Bitmez sanıp o günleri, har vurup harman savurduk, 

Nasıratımız bağlandı, görmez olduk önümüzü.

Bunca çaba uçup gitti, emeklerim kuşa döndü, 

Hasletlerim kayboldu, sevdalarım başa döndü, 

Hiç bir şeyin ebedi yok, sen güneş oldun, ben su, 

Gözlerimdeki nemler isyan edip yaşa döndü.

Hiç nedensiz heba ettik yıllar süren aşkımızı, 

Viraneye çevirdik gıptayla bakılan sevgimizi, 

İkimiz de unutup, tatlı dilin kapıları açtığını, 

Elimizle harap ettik, sonra açtık gözümüzü.

Ne büyük hata yaptığımı şimdi iyi anlıyorum, 

Hislerime aldanmayıp, sağduyumu dinliyorum, 

Geçmişi tek tek irdeleyip yeniden günlüyorum, 

Elde kalan bir şey yok, sıfırla sıfırı topluyorum. 

11.08.2003', 'Sana kalbim kırık benim, bunu hiç bilmedin,  Zalimlere gül dağıttın, bana diken vermedin,  Hep riyakâr davrandın, gerçekleri görmedin,  Sen ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kayip-yillar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamak Yok', 'aglamak-yok-erol-sen-51wkn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevincin gözyaşına

Hüznün gözyaşına

Kederin gözyaşına

İzin yok hepsine birden gönlüm

Tecrübeyle yaşanmış 

Gözyaşından önce doğan güne

Umutlar saçan çocuklara

Sarıl karşlıksız sevgiyle

Sana verdikleri karşılıksız sarılmaya

Aldatmasız ihanetsiz sevgiyle

Senden beklenen umuda

Sahte sevgiyi ittiğin ellerinle....

12.08.03', 'Sevincin gözyaşına Hüznün gözyaşına Kederin gözyaşına İzin yok hepsine birden gönlüm Tecrübeyle yaşanmış  Gözyaşından önce doğan güne Umutla...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aglamak-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Et', 'hayal-et-hakki-hakan-kaya-t9f0n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir hayal tut elinde, sakın bırakma, 

Yaşam kadar değerli, hayat kadar acı, 

Hayallerdir insanı yaşatan ve ayakta tutan, 

Mutluluğun melhemi, sevginin ilacı.

Ama dikkat et, sakın gerçekleşmesin hayalin, 

Hep bir adım kadar gerisinde ol, 

Kimi zaman yakala bir köşesinden hınçla, 

Kimi zaman ölüm kadar uzağında ol.

Dibi delik bir su kovasıdır hayaller, 

Sürekli bir su sirkülesi, 

Sakın kapama kovanın deliğini, 

Ölmektir bir nevi, hayallerin gerçekleşmesi.', 'Bir hayal tut elinde, sakın bırakma,  Yaşam kadar değerli, hayat kadar acı,  Hayallerdir insanı yaşatan ve ayakta tutan,  Mutluluğun melhemi...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayal-et-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Densiz', 'densiz-i-brahim-bayraktar-5sefe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gecenin bir yarısı arayıp, 

Alo! Biz boğazda balık yiyoruz, 

Siz ne yapıyorsunuz? 

İnsana nispet yapar gibi.

Ne yapacağız ulan, 

Çoluk çocuk televizyon başında

Sizin rezaletlerinizi izliyoruz.

01.08.2003', 'Gecenin bir yarısı arayıp,  Alo! Biz boğazda balık yiyoruz,  Siz ne yapıyorsunuz?  İnsana nispet yapar gibi. Ne yapacağız ulan,  Çoluk çocuk...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/densiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güvensiz Aşk', 'guvensiz-ask-i-brahim-bayraktar-9lo8f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu dünyada her şey emek, 

Her bedende bir can demek, 

Huzur için dostluk gerek, 

Her işin bir ırıbı var, 

İşin ehli olmak gerek.

Her dilimi ayrı bir muamma, 

Şafak vakti gibi saf ve temiz, 

Gece yarısı gibi kirlenmiş.

Yağmur damlası kadar hafif ve ürkek, 

Nehirler gibi coşkulu, 

Su lekeleri gibi kuşkulu, 

İşte bizim yıllar süren aşkımız izahı.

12.08.2003', 'Bu dünyada her şey emek,  Her bedende bir can demek,  Huzur için dostluk gerek,  Her işin bir ırıbı var,  İşin ehli olmak gerek. Her dilimi ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/guvensiz-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanın Sürükleyip Getirdiği Bu Yolda', 'zamanin-surukleyip-getirdigi-bu-yolda-dilek-ozkan-w406h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zamanın sürükleyip getirdiği bu yolda, 

Yaşamı sevdiren bir tebessüm vardır.

Yaşanan hayatın her baharında, 

Bir sonrakinin umudu vardır.', 'Zamanın sürükleyip getirdiği bu yolda,  Yaşamı sevdiren bir tebessüm vardır. Yaşanan hayatın her baharında,  Bir sonrakinin umudu vardır....', ARRAY['Türk Edebiyatı','Şiir','Dilek Özkan']::text[], 8.5, '{"poet":"Dilek Özkan","poet_slug":"dilek-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zamanin-surukleyip-getirdigi-bu-yolda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma', 'unutma-dilek-ozkan-393ki', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kararan odada, 

Bir tek mum ışığı görmek umuduyla, 

Kapatılan kapıların ardında, 

Seni Bekleyen birinin olduğunu unutma.

Ayrılıkların yaşandığı, 

Göz yaşlarının hüküm sürdüğü, 

Acılarla bezenmiş bir hayat.

Sanma ki bütün bunlar beni yıldıracak.

Biliyorum, gidenler dönmez.

Unutma ki yaşanılan ilk aşklar ölmez.', 'Kararan odada,  Bir tek mum ışığı görmek umuduyla,  Kapatılan kapıların ardında,  Seni Bekleyen birinin olduğunu unutma. Ayrılıkların yaşand...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özkan']::text[], 8.5, '{"poet":"Dilek Özkan","poet_slug":"dilek-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/unutma-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel', 'guzel-dilek-ozkan-rdp2u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güzel güzeldir, iyi hoş da

Güzel senin olsa neye yararki 

Güzeli farketmedikten sonra', 'Güzel güzeldir, iyi hoş da Güzel senin olsa neye yararki  Güzeli farketmedikten sonra...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özkan']::text[], 8.5, '{"poet":"Dilek Özkan","poet_slug":"dilek-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/guzel-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takmayacaksın', 'takmayacaksin-murat-demir-bkr0a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu dünya fanidir, takmayacaksın

Ne seni ne onu, yakmayacaksın

Derde üzüntüye, bakmayacaksın

Zevk sefa içinde, yaşamak varken

Eğlence denildi, kaçmayacaksın

Neşene elemi, katmayacaksın

İçindeki seli, tutmayacaksın

Şelaleler gibi, çağlamak varken

İnsansan insanı, satmayacaksın

Her olur olmazı, yapmayacaksın

Uzanmayan eli, tutmayacaksın

Beş parmağı beşle, bağlamak varken

Soysuzun lafına, uymayacaksın

Kapından içeri, koymayacaksın

Açmısın tokmusun, sormayacaksın

Gülmeyi neylesin, ağlamak varken

Seni sevmeyeni, sevmeyeceksin

Gel desede geri, dönmeyeceksin

Yazıktır, gül bile vermeyeceksin

Gülü sevenine, saklamak varken

Ağlayana bakıp, gülmeyeceksin

Kapı açılmadan girmeyeceksin

Bağ senin değilse, dermeyeceksin

Kendi güllerini, koklamak varken', 'Bu dünya fanidir, takmayacaksın Ne seni ne onu, yakmayacaksın Derde üzüntüye, bakmayacaksın Zevk sefa içinde, yaşamak varken Eğlence denildi...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/takmayacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözün Aydın Kara Sevda', 'gozun-aydin-kara-sevda-murat-demir-7h7gm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıllar sonra geçiyordum

Kapısının sokağından

Susamıştım ayran içtim

Babasının otağından

Sağa sola bakıyordum

Onu gözle arıyordum

Kapılardan birisini

Açar gelir sanıyordum

Orada çok duramadım

Lafımı uzatamadım

Yanımdan bir ceylan geçti

Onu ona soramadım

Takılmıştım ben peşine

Tutulmuştum cilvesine

Yarı aygın yarı baygın

Girmiş idim bahçesine

Bahçesinde iki çocuk

Anne deyip sarıldılar

Terlemiştim boncuk boncuk

Sanki canımı aldılar

Çıktım sokağın başına

Uzandım gönül taşına

Gurbet adın yere batsın

Neler geldi bak başıma

Gözümü açtım evdeyim

Boşluğa sordum nerdeyim

İçimde bir tatlı hüzün

Sanki cennet evindeyim

Kapıda bir gölge gördüm

Tanıdım o geliyordu

Derin derin hızlı hızlı

Nefesini alıyordu

Odaya bir ışık girdi

Aymı desem güneşmiydi

İnanmak istemiyordum

İki çocuklu eşmiydi

Boş bakıştık konuşmadı

Sanki dili tutulmuştu

Gözün aydın kara sevda

Oda benimle ölmüştü

Eşi vardı evlenmişti

Artık iş işten geçmişti

Buda kimdir diyenlere

Çok eski bir dost demişti

Kalk git Murat ne durursun

Sana artık yol göründü

Son kez olsun gözlerine

Baktığımda ağlıyordu', 'Yıllar sonra geçiyordum Kapısının sokağından Susamıştım ayran içtim Babasının otağından Sağa sola bakıyordum Onu gözle arıyordum Kapılardan ...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/gozun-aydin-kara-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pazar Günleri çamaşır günüdür...', 'pazar-gunleri-camasir-gunudur-hakan-komurcu-xb40v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'pazar günleri çamaşır günüdür

pazarın tesiyse temiz çamaşır giyebilirsin

salı, çarşamba derken

kirlenir çamaşırlarda insanlar gibi

pazar günleri temizlik günüdür

tırnaklar kesilir

salı çarşamba derken

bir birine girer her şey

uzar tırnaklar

pazar günleri görüş günüdür

insanlar birbirini görür, 

emeğe pay biçilir

pazar günleri düğüm çözülür

anne oğlu

oğlu yarini

hakederek beklemiştir

pazar günleri önemli bir gündür...

insanın temize çekildiği

kendisi olduğu

mübarek bir gün.....', 'pazar günleri çamaşır günüdür pazarın tesiyse temiz çamaşır giyebilirsin salı, çarşamba derken kirlenir çamaşırlarda insanlar gibi pazar gün...', ARRAY['Türk Edebiyatı','Şiir','Hakan Kömürcü']::text[], 8.5, '{"poet":"Hakan Kömürcü","poet_slug":"hakan-komurcu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/pazar-gunleri-camasir-gunudur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılıyorsun', 'yaniliyorsun-sair-asivan-7r3fc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benden bir tane  var bu dünyada, 

senden onlarca..

Özledim mi sanıyorsun? 

yanılıyorsun, 

seninleyken veda ettim içimdeki özleme...

Devam edemem mi sanıyorsun? 

yanılıyorsun, 

mutluluk, on göz yaşı ötede...', 'Benden bir tane  var bu dünyada,  senden onlarca.. Özledim mi sanıyorsun?  yanılıyorsun,  seninleyken veda ettim içimdeki özleme... Devam ed...', ARRAY['Türk Edebiyatı','Şiir','Şair Asivan']::text[], 8.5, '{"poet":"Şair Asivan","poet_slug":"sair-asivan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yaniliyorsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-ahmet-aksoy-pi4bx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bak her şey sustu

Teyp çalmıyor artık

Bir sen bir ben kaldık

Herkes ve her şey

Uyudu artık

Bir sen bir ben kaldık.', 'Bak her şey sustu Teyp çalmıyor artık Bir sen bir ben kaldık Herkes ve her şey Uyudu artık Bir sen bir ben kaldık....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/zaman-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mademki', 'mademki-ahmet-aksoy-e7j5a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kurşundan olmaz canım

Kurşundan olmaz

Verdiğin kalem tükenmez

Olmalı canım tükenmez

Mademki hataya yer yok 

Tek bir kez

Kurşundan olmaz canım

Tükenmez olmalı tükenmez.', 'Kurşundan olmaz canım Kurşundan olmaz Verdiğin kalem tükenmez Olmalı canım tükenmez Mademki hataya yer yok  Tek bir kez Kurşundan olmaz canı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mademki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigara', 'sigara-dung-sack-8tbxz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sigara; 

Gözlerimin platonik aşkı, 

Ki her vedadan önce

Dumanıyla

ağlatır onları..', 'Sigara;  Gözlerimin platonik aşkı,  Ki her vedadan önce Dumanıyla ağlatır onları.....', ARRAY['Türk Edebiyatı','Şiir','Dung Sack']::text[], 8.5, '{"poet":"Dung Sack","poet_slug":"dung-sack","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sigara-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmişin Geçmişi', 'gelmisin-gecmisi-ahmet-aksoy-dl0xi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gelmişin geçmişi

Geçmişin gelmişi olmadığında

Ne ben, ben olacağım

Ne sen, sen olacaksın

Bitmişi olacak her şey

Ne zaman olacak geçecek

Ne de gelecek, gelecek

Bitmiş olacak her şey

Geçmişi olmadığında gelmişin

Gelmişi olmadığında geçmişin

Bitmiş olacak her şey

Ne sen ne ben olacağız.', 'Gelmişin geçmişi Geçmişin gelmişi olmadığında Ne ben, ben olacağım Ne sen, sen olacaksın Bitmişi olacak her şey Ne zaman olacak geçecek Ne d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gelmisin-gecmisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanmıyorsan', 'i-nanmiyorsan-ahmet-aksoy-3en0i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnanmıyorsan seni sevdiğime

İçimi gör birde 

Röntgenimi vereyim

Dur bekle.', 'İnanmıyorsan seni sevdiğime İçimi gör birde  Röntgenimi vereyim Dur bekle....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/inanmiyorsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-gizemli-dahi-1lmnq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayat bir kaçıştır; 

Toz pembe hayallere.

Hayat, bir uykunun içinde, 

Ansızın bir rüyadan uyanıştır.

Bu hayat işte! 

Kimine zor, kimine rahat

Bir sahipsiz inat belki de, 

Bir heveslik  inat…

Anlatması güç bir çelişkidir hayat; 

Bir şeyler uğruna

Yaşasan kabahat

Ölsen kabahat..!', 'Hayat bir kaçıştır;  Toz pembe hayallere. Hayat, bir uykunun içinde,  Ansızın bir rüyadan uyanıştır. Bu hayat işte!  Kimine zor, kimine raha...', ARRAY['Türk Edebiyatı','Şiir','Gizemli Dahi']::text[], 8.5, '{"poet":"Gizemli Dahi","poet_slug":"gizemli-dahi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayat-95-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşümce', 'dusumce-ozlem-torkul-tekan-6m9hi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Enginlere yolladım mavilerimi

Bana beyazlarla avunmak düştü.

Laleden yana olmadı hiç nasibim

Payıma bir demet karanfil düştü.

Çocuk bakışlarında saklıydı umut

Hüzün dudaklarda içli gülüştü.

Sevda dedikleri o erdirici sır

Her gece gördüğüm tatlı bir düştü.

İlk tufanla yitirdim çarelerimi

Bana son gemiyi beklemek düştü.

Vuslattan yana olmadı hiç nasibim.

Payıma kimsesiz limanlar düştü.

(17 Mayıs 1997)', 'Enginlere yolladım mavilerimi Bana beyazlarla avunmak düştü. Laleden yana olmadı hiç nasibim Payıma bir demet karanfil düştü. Çocuk bakışlar...', ARRAY['Türk Edebiyatı','Şiir','Özlem Torkul Tekan']::text[], 8.5, '{"poet":"Özlem Torkul Tekan","poet_slug":"ozlem-torkul-tekan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dusumce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Sevdalar', 'yorgun-sevdalar-gizemli-dahi-nsq1e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'YORGUN SEVDALAR

Gün gelir güler insan, 

Geçmiş aşkların ardından, 

Kendine kızar ve güler.

Yaşadığı heyecanları hesaba katmadan.

Bense kararsızım, 

Gülsem mi? 

Daha  mı iyi? 

Unutmuşcasına hatırlamasam.

Şunu biliyorum tek:

Duygularımın yazdığı senaryoları Söyleyemem

Zor olur söylemek.

Ya da moral bozan gerçekleri; 

Reddedilmek gibi; 

Kabullenemediklerini, 

Zor olur söylemek.

Biten aşkların ardından konuşmaz dilim, 

Hem yeniden sevmeye hazır değilim, 

Daha zor acıları aşkla paylaşamam, 

Yorgun sevdalar mezarlığında, 

Avare avare uğraşamam.

Ne kadar kaybetmiş görünsem de, 

Vaktim var kazanmaya halen, 

Pes etmedim sevdalara, 

Pes etmem zaten.', 'YORGUN SEVDALAR Gün gelir güler insan,  Geçmiş aşkların ardından,  Kendine kızar ve güler. Yaşadığı heyecanları hesaba katmadan. Bense karar...', ARRAY['Türk Edebiyatı','Şiir','Gizemli Dahi']::text[], 8.5, '{"poet":"Gizemli Dahi","poet_slug":"gizemli-dahi","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yorgun-sevdalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-yildiz-kamiloglu-8n0sd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '...................................

Anlamadın işte

Sevgini kendin gibi çok gördün bana, 

Olsun, sev diye sevmedim zaten seni, 

Dedim ya; ıssız bir sokaktayım, 

Bak üstüne üstlik yağmur yağıyor, 

Ağlamak istiyorum, biri görür diye korkuyorum...

Ama şimdi ağlayabilirim..

Gözyaşlarım yağmurla birlikte toprağa kavuşuyor..........', '................................... Anlamadın işte Sevgini kendin gibi çok gördün bana,  Olsun, sev diye sevmedim zaten seni,  Dedim ya; ıss...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Kamiloğlu']::text[], 8.5, '{"poet":"Yıldız Kamiloğlu","poet_slug":"yildiz-kamiloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/elveda-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Bana Ait', 'ask-bana-ait-gizemli-dahi-c1w3s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşk bana ait güzelim, 

Ver elini mehtaplarda gezelim, 

Ver elini haram aşkı sezelim, 

Aşk bana ait güzelim.

Sensiz de olur inkarcı geceler, 

Sensiz yine gelir bahar, 

Sensiz de felekler ağlar, 

Aşk bana ait güzelim. 

Yalansız aşkım bir gece biter, 

Riyasız yalnızlık kalbime yeter.

Darbe yemiş gönül çeker gider, 

Aşk bana ait güzelim.

Yakarım ömrümün sahtekar ahengini; 

Bir deli düşünce, bir deli kibrit, 

Sen gidersen haydi git! 

Aşk bana ait güzelim, 

Aşk bana ait.', 'Aşk bana ait güzelim,  Ver elini mehtaplarda gezelim,  Ver elini haram aşkı sezelim,  Aşk bana ait güzelim. Sensiz de olur inkarcı geceler, ...', ARRAY['Türk Edebiyatı','Şiir','Gizemli Dahi']::text[], 8.5, '{"poet":"Gizemli Dahi","poet_slug":"gizemli-dahi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ask-bana-ait-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıcak', 'sicak-gizemli-dahi-301k1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu kadar mı sıcak olacaktı? 

Bu kadar mı? 

Böyle mi söz vermişti, 

Yalnızlığını paylaştığımız gökyüzü? 

Nankör havalar kavurdu bizi.

Gerçi, asıl suç güneşin.

Doğuşunu izlediğimiz güneşin.

Sen de güneşten geldin, 

Güneş senin kardeşin.

Şimdi gökyüzü de, güneş de uzak bana, 

Ben uzağım, aşkım yakın sana. 

Bir yudum sevgi yolladım, 

Benim için iç kana kana; 

Hem özlemden, 

Hem sıcaktan; yana yana', 'Bu kadar mı sıcak olacaktı?  Bu kadar mı?  Böyle mi söz vermişti,  Yalnızlığını paylaştığımız gökyüzü?  Nankör havalar kavurdu bizi. Gerçi, ...', ARRAY['Türk Edebiyatı','Şiir','Gizemli Dahi']::text[], 8.5, '{"poet":"Gizemli Dahi","poet_slug":"gizemli-dahi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sicak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Sevdalar', 'kara-sevdalar-abdulhamit-kanca-tpqwl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani

Kara sevdalarımız vardır

Bıkmadığımz, 

Yüküne sevinip 

Hep yanımızda taşıdığımız, 

Hem de nöbetçi sıkıntılara inat

Fırtınalı sularda aradığımız

O kara sevdalarımız.

Hani; 

Bilsem köpürmeyeceğini

O kara sevdanın, 

Yürekler denizine 

Kucak aşmış bir heykelini dikerdim, 

Sonra da geçip karşısına

Gece gündüz ibadet ederdim..

Gelen haberciler getirse de

Davetiyesini cehennemin

O sevdanın kucağında

Sadece gülüp geçerdim 

Hem de kendimden emin.

Nasıl soracak ki Tanrı bana

Niye böyle yaptığımı! 

Yaratmasaydı o da

Kara sevdalık yaratığını...

12.08.2003/Samsun', 'Hani Kara sevdalarımız vardır Bıkmadığımz,  Yüküne sevinip  Hep yanımızda taşıdığımız,  Hem de nöbetçi sıkıntılara inat Fırtınalı sularda ar...', ARRAY['Türk Edebiyatı','Şiir','Abdülhamit Kanca']::text[], 8.5, '{"poet":"Abdülhamit Kanca","poet_slug":"abdulhamit-kanca","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kara-sevdalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş', 'ates-dung-sack-1irlm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sigara..

Ne kadar cool gözüksen de, 

İçinde ateşler yandığını

biliyorum...', 'Sigara.. Ne kadar cool gözüksen de,  İçinde ateşler yandığını biliyorum......', ARRAY['Türk Edebiyatı','Şiir','Dung Sack']::text[], 8.5, '{"poet":"Dung Sack","poet_slug":"dung-sack","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ates-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-gizemli-dahi-rh6aq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şarkıların tüfeğidir yağmur; 

Hasreti vurur, sevgiyi vurur, nefreti vurur.

Aşkların dostudur yağmur; 

Bildiği sırları aşk için unutur.

Nehirleri coşturur sevdasından, 

Ödün vermez asla sessiz kavgasından, 

Bazen gelir gözlerimi kurutur, 

Saklar ağladığımı vefalı yağmur.

Sel olur kimi zaman; felaket, 

Kimi zaman ekmek parası; bereket

Bazen de beni bekler cefalı yağmur, 

İnce ince yağar onurlu ve mağrur.

Belki beni güldürmez, 

Hiç ağlatmaz da, 

Biri gelir öyküsünü sorar da, 

Çok şey anlatır, anlatır yağmur.

İyidir gözyaşlarıyla ıslanmaktan, 

Yağmurda ıslanmak.

İyidir yağmur gibi kendiliğinden uslanmak.

İyidir  inancına bakıp da, 

Onun gibi hırslanmak.

Yağmur, gönlümde hüznüyle biriken, 

Boşver dünyanın masallarını, 

Asıl dinlenmesi gereken, 

O muhteşem huzur, 

Gökten gövdeme, ince ince yağan yağmur', 'Şarkıların tüfeğidir yağmur;  Hasreti vurur, sevgiyi vurur, nefreti vurur. Aşkların dostudur yağmur;  Bildiği sırları aşk için unutur. Nehir...', ARRAY['Türk Edebiyatı','Şiir','Gizemli Dahi']::text[], 8.5, '{"poet":"Gizemli Dahi","poet_slug":"gizemli-dahi","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yagmur-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanser', 'kanser-dung-sack-8d2d2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sigara...

O sadece, 

canını ''yaktığımız'' için

bizden intikam alıyor...', 'Sigara... O sadece,  canını ''yaktığımız'' için bizden intikam alıyor......', ARRAY['Türk Edebiyatı','Şiir','Dung Sack']::text[], 8.5, '{"poet":"Dung Sack","poet_slug":"dung-sack","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kanser-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İş''te', 'i-s-te-dung-sack-doj82', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ve işte; 

Kıçım

bir koltuk rahatlığında, 

Aklımda uyku, 

Bedenim iş''te...', 'Ve işte;  Kıçım bir koltuk rahatlığında,  Aklımda uyku,  Bedenim iş''te......', ARRAY['Türk Edebiyatı','Şiir','Dung Sack']::text[], 8.5, '{"poet":"Dung Sack","poet_slug":"dung-sack","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/is-te-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-gizemli-dahi-szvq6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Elveda gizli hasretler, 

Elveda hepinize, 

Elveda yaldızlı nefretler, 

Elveda topunuza.

Elveda sansürlenmiş hayallerim, 

Hayallerim, benim büyük ideallerim.

Elveda umutlara.

Elveda arada bir sevincim, 

Sevincim, benim hayata direncim.

Elveda ruhuma hapsedilmiş korkular, 

Elveda kabuslardaki sorgular, 

Elveda bana dair herşeye; 

Elveda aşka, 

Elveda hüzne, 

Elveda neşeye, 

Elveda gençliğim, 

Gençliğim, benim ömür diye biçtiğim.

Elveda yarınlara gideceğim, 

Bekleyin beni, 

Yarın olsun: Döneceğim.', 'Elveda gizli hasretler,  Elveda hepinize,  Elveda yaldızlı nefretler,  Elveda topunuza. Elveda sansürlenmiş hayallerim,  Hayallerim, benim b...', ARRAY['Türk Edebiyatı','Şiir','Gizemli Dahi']::text[], 8.5, '{"poet":"Gizemli Dahi","poet_slug":"gizemli-dahi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/elveda-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huyumsun', 'huyumsun-volkan-cebeci-xttos', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sensizlik uçurumunda, 

Hasretin avucunda, 

Bir hayal oldun, 

Her baharın kışında.

Çaremde umudumsun

Yürüdüğüm yolumsun, 

Kavuşmak hayaliyle, 

Bırakamadığım huyumsun.

Yaşarken ölümle, 

Kucaklaştım zulümle, 

Tek iyi günahımdın, 

Dua kokan elimde.', 'Sensizlik uçurumunda,  Hasretin avucunda,  Bir hayal oldun,  Her baharın kışında. Çaremde umudumsun Yürüdüğüm yolumsun,  Kavuşmak hayaliyle,...', ARRAY['Türk Edebiyatı','Şiir','Volkan Cebeci']::text[], 8.5, '{"poet":"Volkan Cebeci","poet_slug":"volkan-cebeci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/huyumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dertler Biter', 'dertler-biter-gizemli-dahi-htc6b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir tebessümle andım hatıraları.

Şöyle bir deştim, 

Onulmaz sandığım yaraları.

Güldüm acı bir gülümseyişle, 

Şaşırdım; 

Zamanın nasıl böyle geçtiğine.

Duygular kafiyelendi zihnimde, 

Bir çocuk sevinci gibi, 

Sevindim birdenbire.

İlk defa, 

Pişman olmadım, 

Ağlamadım, 

Sızlanmadım, 

Özlemedim kimseyi, 

Yanımda hissettim sevdiklerimi, 

Moralimi bozmadım, 

İsyan etmedim kaderime, 

Kimseye kızmadım.

Artık yüreğim, 

Bıktım endişelerden, 

Bıktım kederlerden, 

Artık yeter! 

Sıkıntılar geçmişe batar, 

Gün gelir dertler biter.', 'Bir tebessümle andım hatıraları. Şöyle bir deştim,  Onulmaz sandığım yaraları. Güldüm acı bir gülümseyişle,  Şaşırdım;  Zamanın nasıl böyle ...', ARRAY['Türk Edebiyatı','Şiir','Gizemli Dahi']::text[], 8.5, '{"poet":"Gizemli Dahi","poet_slug":"gizemli-dahi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dertler-biter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalimsin', 'zalimsin-gizemli-dahi-nhbwh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sensizlik ölümse, 

Seninle olmak zulüm.

Zulüm dediysem kızma gülüm, 

Senle olmak kolay mı? 

Gözlerine bakmak, 

Sözlerine kanmak, 

Kolay mı? 

Dedim ya; 

Sensizlik ölümse,

Seninle olmak zulüm.

Bir heyecanla beklemek seni, 

Bir gönül hediyesi vermek sana, 

Zor be gülüm.

Dedim ya; 

Sensizlik ölümse,

Seninle olmak zulüm.

Ölüm olsa yolunda, 

Ölüme kanatlanırım.

Zulüm bulsam sen de, 

Zulüme katlanırım.

Sana olan sevgim öylesine derin; 

Zalimsin, farketmez; yine severim.', 'Sensizlik ölümse,  Seninle olmak zulüm. Zulüm dediysem kızma gülüm,  Senle olmak kolay mı?  Gözlerine bakmak,  Sözlerine kanmak,  Kolay mı? ...', ARRAY['Türk Edebiyatı','Şiir','Gizemli Dahi']::text[], 8.5, '{"poet":"Gizemli Dahi","poet_slug":"gizemli-dahi","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/zalimsin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Konumu', 'askin-konumu-ensar-cevval-wg9m4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk, her yaşta güzeldir

onbeşinde saf, çocukcadır

içinde birşeyler vardır tarifi olmayan; 

yirmisinde şımartılmaya gelmez

bir kaptırırsan anaforuna beynini

gerisi, bir yastıkta kocayınlı temenni

Aşk heryerde güzeldir

köy yerinde saf, platoniktir

camdan cama kaçamak bakışlarda

ya da çeşme başında büyütülür

bir mendil atma ateşi tutuşturur

el ele tutunmanın sonuda temenni

Şehirlerde biraz daha yozlaşmıştır aşk

ele ele, göz göze, koyun koyuna

ne heyecanı kalmıştır ilk dokunmanın

ne de yanaktan öpüp kaçmanın

çok aşina olursa sevda, bıktırır bence

kaçamak buluşmaların sonu da temenni.

01,08,2003 İstanbul', 'Aşk, her yaşta güzeldir onbeşinde saf, çocukcadır içinde birşeyler vardır tarifi olmayan;  yirmisinde şımartılmaya gelmez bir kaptırırsan an...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/askin-konumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çirkinname', 'cirkinname-hasan-aydin-wl6k7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nesi var ki çirkinin neyini arz eylesin? 

Reva mı Hakk hüsnü men, bete cevaz eylesin? 

Bîrevaç mülke mâlik celb-i rağbet edemez

Varsın çarşı pazarda meth-i avaz eylesin

Arz-ı endam çirkine kâr-ı müf’id değildir

Elverir ki dengini Hakk’tan niyaz eylesin

Göz almazsa ibtida tenden temas zevkini

Gönül tenhada nasıl hayalden haz eylesin? 

Bir suret ki, tahattur, kırar kalbin şevkini

Köroğlu olsa bile ânı Ayvaz neylesin?', 'Nesi var ki çirkinin neyini arz eylesin?  Reva mı Hakk hüsnü men, bete cevaz eylesin?  Bîrevaç mülke mâlik celb-i rağbet edemez Varsın çarşı...', ARRAY['Türk Edebiyatı','Şiir','Hasan Aydın']::text[], 8.5, '{"poet":"Hasan Aydın","poet_slug":"hasan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cirkinname-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Kokusu', 'i-nsan-kokusu-gokhan-uckaya-3rmgv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hepsi, hepsi

kaybetmişlerdi bu yarışı

toprak suya karışmıştı çünkü.

çok önceleri

güller henüz ağlamazken başladı yanlışlık

toprağa değilde

suya özlem duydu insanlar

anaya ihanetti bu

hepsi, hepsi kaybettiler

yüzyıllar soracak

çiçek kokularıyla

yaprak hışırtılarıyla

hep ağlatacak gülleri

yok çünkü

çünkü yok

kaybetmişlerdi

ve neonlar durmamacasına

yanıp sönecek

              bir yanıp bir sönüp

              ağlatacak gülleri

neonlara akacak umutlar

bir elektirisiti olacak

insan kokusu

bu bile oluyor

bedelini yaşamamışlıkla ödeyeceğimiz

insan olmamışlığımız

bakıyor

camlardan

havayı demirlerle

kesen camlardan

neon renklerle ağlıyor

insanlık

bu bile oluyor diyoruz

aktöre 

        öksürüklerle

boğulana dek

biz balgam

üreteceğiz

çirkinlerin en güzeli

birer kertenkele

(ankara,1987)', 'hepsi, hepsi kaybetmişlerdi bu yarışı toprak suya karışmıştı çünkü. çok önceleri güller henüz ağlamazken başladı yanlışlık toprağa değilde s...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Üçkaya']::text[], 8.5, '{"poet":"Gökhan Üçkaya","poet_slug":"gokhan-uckaya","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/insan-kokusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıyorum Ağlamana', 'agliyorum-aglamana-umut-taskin-glbhm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağlamana ağlıyorum ağlamanın nedenini bilmeksizin

Umurumda değil gözyaşı bezelerini tekmeleyen lanetler

Ben gözyaşlarına ağlıyorum

Temizliğine ağlıyorum yanağına dokunan herbir tanenin

2003-erdem cafe-bakırköy', 'Ağlamana ağlıyorum ağlamanın nedenini bilmeksizin Umurumda değil gözyaşı bezelerini tekmeleyen lanetler Ben gözyaşlarına ağlıyorum Temizliği...', ARRAY['Türk Edebiyatı','Şiir','Umut Taşkın']::text[], 8.5, '{"poet":"Umut Taşkın","poet_slug":"umut-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/agliyorum-aglamana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgardı Bu', 'ruzgardi-bu-gokhan-uckaya-cdeki', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir denizden çıktım 

yosun ayaklarım

ellerim mavi, masmavi

içimde tuzlu burukluk

kanlıca yaşardım

yaşadığıma şaşardım

rüzgardı bu

kayardı martı gibi

kayığım sular üstü

döşemesi kurtlanmış

ıskarmozlar çığlık çığlığa

kanlıca yaşardım

yaşadığıma şaşardım

rüzgardı bu

kalın gelirdi her öğreti

yelkenleri doldurunca rüzgar

bir elim kaldı 

beni ısıtan

      merhaba dedi

                  hüzün

                        hüsran

rüzgardı bu

(ankara,1988)', 'bir denizden çıktım  yosun ayaklarım ellerim mavi, masmavi içimde tuzlu burukluk kanlıca yaşardım yaşadığıma şaşardım rüzgardı bu kayardı ma...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Üçkaya']::text[], 8.5, '{"poet":"Gökhan Üçkaya","poet_slug":"gokhan-uckaya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ruzgardi-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun(1)', 'oyun-1-umut-taskin-7b1e3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gece ansızın gel yine

Çıplak bedenin yasaklı olsun

Etin sana kalsın, ben ruhunla sevişeyim

Bir gece ansızın gel yine

Ben günahkar olayım, sen rahibe

Evcilik oynayalım

2003-erdem cafe-bakırköy', 'Bir gece ansızın gel yine Çıplak bedenin yasaklı olsun Etin sana kalsın, ben ruhunla sevişeyim Bir gece ansızın gel yine Ben günahkar olayım...', ARRAY['Türk Edebiyatı','Şiir','Umut Taşkın']::text[], 8.5, '{"poet":"Umut Taşkın","poet_slug":"umut-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/oyun-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-ercan-sari-8g45s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen yanımdayken

Her şey basit geldi

Oysa bu yürek

Ne acılar çekti

Şimdi yanımdasın

Yüzüm gülüyor

Yokluğunu görmedin

Yaşamak zor geliyor

Sen varken güçlüyüm

Hayat avucumda

Sensiz kaybolurum

Çıkmaz sokaklarda

Eşgalim kayboldu

Aynalar paramparça

Seni görmeliyim

Küstüm ışıklara

Anlamsız geliyor

Seninle anlamlı şarkılar

Her yer sen olur

Beni avutur rüyalar

Sensizlik bir uçurum

Ben kenarındayım

Artık zor bulurum 

Umudun son durağındayım', 'Sen yanımdayken Her şey basit geldi Oysa bu yürek Ne acılar çekti Şimdi yanımdasın Yüzüm gülüyor Yokluğunu görmedin Yaşamak zor geliyor Sen ...', ARRAY['Türk Edebiyatı','Şiir','Ercan Sarı']::text[], 8.5, '{"poet":"Ercan Sarı","poet_slug":"ercan-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sensizlik-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun(2)', 'oyun-2-umut-taskin-rnxt5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben ikimize cam diplerini seçtim

Perdesini kestim camın

Sana fistan, bana incir yaprağı

Ben ikimize cam diplerini seçtim

Sen sana saklan, ben ruhunu arayayım

Saklanbaç oynayalım', 'Ben ikimize cam diplerini seçtim Perdesini kestim camın Sana fistan, bana incir yaprağı Ben ikimize cam diplerini seçtim Sen sana saklan, be...', ARRAY['Türk Edebiyatı','Şiir','Umut Taşkın']::text[], 8.5, '{"poet":"Umut Taşkın","poet_slug":"umut-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/oyun-2-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevemem Başka Biri', 'sevemem-baska-biri-ercan-sari-yid6m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni görmediğim günden 

Ümidimi kestim

Günleri tüketmek uğruna

Ömrümü feda ettim

İsteklerimdi çığ gibi büyüyen

Bir günden düğer yarınlara

Sensiz yaşamakytansa

Razıyım kara toprağa

Çok zorladım kaderi

Ya sendin ya hiç biri

Sensizliğe razıyım ben

Sevemem başka biri

Bu yüzden getirme

Aklına kötü şeyleri

Ancak ölümle

Unutmak mümkün seni

Sensizlikte tattım

Zaten ölüm acısını

Bırak artık yaşayalım

Doya doya bu aşkı', 'Seni görmediğim günden  Ümidimi kestim Günleri tüketmek uğruna Ömrümü feda ettim İsteklerimdi çığ gibi büyüyen Bir günden düğer yarınlara Se...', ARRAY['Türk Edebiyatı','Şiir','Ercan Sarı']::text[], 8.5, '{"poet":"Ercan Sarı","poet_slug":"ercan-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevemem-baska-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sokağı Kaybetmek', 'bir-sokagi-kaybetmek-gokhan-uckaya-7f0o4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-Koray''a

sonra sorulduğunda güne yazılanlar

anlat azar azar o yalanları

hep acısı ile sarı-sayrı gece yılanları

ömrüm kara yazmalı günüm

hep içinden geçer sokaklarım

sanki bilir gibi geceye çıkar 

                            o yolcusuz yollarım

sonra bir kahkaha gelir 

                          inletir nehirleri

bize anlatır geçen güzel günleri

hani sıcacık bir gün sarsaydı bizi

ve yumuşacık en incitmesiz sevdalar

               dikenli dallar ardında kalmasaydı

olurdu belki 

belki olurdu

suyun akışı

aktığı suyu okşayışı

yumuşacık başın yastığa batışı

özlesekte

yüreğin sevdaya dokunuşu

eksilmedi yürünen yolların geçmişe kalışı

yürüsün seninle bastığın her toprak

yürüyen yalnız sen oldukça 

gitsende uzaklar neyi değiştirir

ayak izin senle olduktan sonra

(moda, ekim 1998)', '-Koray''a sonra sorulduğunda güne yazılanlar anlat azar azar o yalanları hep acısı ile sarı-sayrı gece yılanları ömrüm kara yazmalı günüm hep...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Üçkaya']::text[], 8.5, '{"poet":"Gökhan Üçkaya","poet_slug":"gokhan-uckaya","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bir-sokagi-kaybetmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heyecanlanırım', 'heyecanlanirim-bekir-gedikoglu-iha2i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Marşımız çalınırken

Heyecanlanırım

Bunun gibi

Seni görünce bir hoş olurum

Sesini duyunca

İster uzak 

İster yakın

Heyecanlanırım

Üç harftir bunun başlangıcı

Tamam mı? 

Aşka-A- düşünce

Heyecanlanırım

Nice yollardan aştın

Sevmenin 

Sevilmenin

Zirvesine ulaştın

Örümcek gibi kalbime

Bembeyaz ağlar attın

Göremem

Senden başkasını

Kalbimde göremem

Bunalar güzel şeyler

Efsunlu anlar

Bunları düşünmekle

HEYECANLANIRIM

Tirebolu,10 Kasım 1970', 'Marşımız çalınırken Heyecanlanırım Bunun gibi Seni görünce bir hoş olurum Sesini duyunca İster uzak  İster yakın Heyecanlanırım Üç harftir b...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/heyecanlanirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykırmak İstiyorum', 'haykirmak-i-stiyorum-ercan-sari-tnnxw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her yanım sensiz

Ama her yanım seninle

Gündüz hayalimde

Gece rüyamda

Bazen bir şiir oluyorsun

Satırlarımda

Bazen bir türkü

Ağzımda

Derdimi anlatmak istiyorum

Haykırmak istiyorum

Seni hayata', 'Her yanım sensiz Ama her yanım seninle Gündüz hayalimde Gece rüyamda Bazen bir şiir oluyorsun Satırlarımda Bazen bir türkü Ağzımda Derdimi a...', ARRAY['Türk Edebiyatı','Şiir','Ercan Sarı']::text[], 8.5, '{"poet":"Ercan Sarı","poet_slug":"ercan-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/haykirmak-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resim ve İsim', 'resim-ve-i-sim-bekir-gedikoglu-239yw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalbimin üstünde

Ama dışında

Var bir resim

Var bir isim

Sanma ki bunu sen

Her zaman üstünde

Her zaman dışında

Taşıdı sanacaksın

Unuttu sanacaksın

Hey, hey, hey, hey

Yok, yok, yok, yok

Öyle değil

Böyle değil

İçimde sen

Rüyamda sen

Karşımda resmin

Zihnimde ismin

Tirebolu,7 kasım 1970', 'Kalbimin üstünde Ama dışında Var bir resim Var bir isim Sanma ki bunu sen Her zaman üstünde Her zaman dışında Taşıdı sanacaksın Unuttu sanac...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/resim-ve-isim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martılanmak', 'martilanmak-gokhan-uckaya-zizmk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gözlerim yanmayın

şiire düşmenin ne yeri 

ne zamanı 

yapmayın

yoksa gün bir sürgün olur

bütün şehir benden korkar

gece kocaman bir ses olur

      şiire düştüğünde

sokakları şehrin taa içimde akar 

kocaman bir göz olup bakar

ellerim

ellerim büyür

nereye koyacağımı bilemem

bütün şehir bana bakar

direnemem

damağımda buruk bir şiir durur gece boyu

sokaklar

ellerim sokaklarda büyümüştür

vazgeçemem şiire düşerim

taa içimden akar

hep zamansız düşerim

öyle işte

ama bir martı kanatlanır içimde

kocaman elleriyle

bütün şehir benden memnun

bütün sokakları bana çıkar

bütün ışıkları şehrin bana yanar

damarları şehrin nabzımda atar

yumuşacık, sevgiyle

içimde bir bebek büyür

her sancı bir sözcük

taa içimde kocaman elleriyle

sonra yine gün doğar

sigaramın dumanı duvarlara siner

her yer ölüm kokar artık anlatamam

gündüz dolar sokaklara sokaklarıyla şehrin küçülürüm

ama önce ellerim, en çok

ellerim

gözlerim öyle pervasız büyür ki ardından

tüm şehir ellerini nereye koyacağını bilemez

küçük ellerim her yere sığar o zaman 

gözlerim yanmaz 

artık

martı olmaz

(kurtuluş,2000)', 'gözlerim yanmayın şiire düşmenin ne yeri  ne zamanı  yapmayın yoksa gün bir sürgün olur bütün şehir benden korkar gece kocaman bir ses olur ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Üçkaya']::text[], 8.5, '{"poet":"Gökhan Üçkaya","poet_slug":"gokhan-uckaya","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/martilanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbaharda', 'sonbaharda-bekir-gedikoglu-z3qa8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yaprak düştü

Dalından

Bir yaprak uçtu havada

İkisinin de gittiği

Çizdiği yol

AYNI

Hareketleri

Seni çizdiler

Seni hatırlattılar

Tirebolu,10 Kasım 1970', 'Bir yaprak düştü Dalından Bir yaprak uçtu havada İkisinin de gittiği Çizdiği yol AYNI Hareketleri Seni çizdiler Seni hatırlattılar Tirebolu,...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sonbaharda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Arkadaş', 'bir-arkadas-cennet-sengul-bkitb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Arkadaşlığın büyüsünü tadanlardanım 

Dostluğun kavramını yaşayanlardanım 

Bir söz söyle bana taaa uzaklardan 

İçten olsun. 

Arkadaşça, dostça bir selam gönder bana 

Yürekten olsun. 

Atma içine üzüntülerini 

Tatma kederli saatleri 

Paylaş kardeşçe mutlu sevgileri 

Düşünme, 

Ardına bırak üzüntülerini 

Gel arkadaşım 

Birlikte atalım kederli düşünceleri 

Dünya değmez hiç bir üzüntüye 

Kapıl git yepyeni sevgilere 

İnandır dünyanın sevgi dolu olduğuna 

Evrende saygının var olduğuna 

Çocuk gibi, saf, temiz, tertemiz 

Yüreğinin bir köşesinde 

Yer var mı bana da? 

Canımı verirdim o yürek için. 

Arkadaşça, sevgiyle, dostça 

Bir selam gönder bana 

Ama ne olur yürekten olsun... 

--------------------', 'Arkadaşlığın büyüsünü tadanlardanım  Dostluğun kavramını yaşayanlardanım  Bir söz söyle bana taaa uzaklardan  İçten olsun.  Arkadaşça, dostç...', ARRAY['Türk Edebiyatı','Şiir','Cennet Şengül']::text[], 8.5, '{"poet":"Cennet Şengül","poet_slug":"cennet-sengul","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-arkadas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanfil', 'karanfil-ozlem-torkul-tekan-r17bn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağız atın terkisine vur da git

Deli gönlün zincirini kır da git

Yıkılmışsa köprüleri kur da git

İnce dalda karanfil bekler seni...

(10 Nisan 2002)', 'Yağız atın terkisine vur da git Deli gönlün zincirini kır da git Yıkılmışsa köprüleri kur da git İnce dalda karanfil bekler seni... (10 Nisa...', ARRAY['Türk Edebiyatı','Şiir','Özlem Torkul Tekan']::text[], 8.5, '{"poet":"Özlem Torkul Tekan","poet_slug":"ozlem-torkul-tekan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/karanfil-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin gülyüzlüm', 'neredesin-gulyuzlum-kadir-keskin-wkom1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neredesin Gülyüzlüm

Günler Bürüdü Şimdi Bir Kızıl Ufukta Hasreti, 

Sensizliğin Her Bir Saatindeyim Gülüm Gurbetinde Akşamın...

Istırabı, Sevgiyi Belki De Sımsıcak Bir Özlemi Dizdim Akşamların Her Bir Deminde.

Neredesin Gülyüzlüm....? 

		Ağla Yüregim Agla... Sabaha Onsuz Dönüşen Şafaklara, Gün Batımlarına Dönen Gündüzlere Ağla Yüregim Ağla...

		Dudaklarıma Konan Hasreti Vurgulayan Gönül Bestelerine  Ağla Yüreğim Ümitler Kuruyasıya...

		Ve Bir Gün Gülüm Hasretimin Vuslata Davetiye Çıkardığı Bir Gün Tarifsiz Bir Çığlık Olup; 

		“Hasretinle Doluyum Hazanda Mevsimler 

Hicranlar Bitmitor, Küllendi Alevler, 

Vuslatım Nerede Yüreğim Ah İnler

Andığım Yandığım Kandığım  Sensin “ Derim Gülüm.', 'Neredesin Gülyüzlüm Günler Bürüdü Şimdi Bir Kızıl Ufukta Hasreti,  Sensizliğin Her Bir Saatindeyim Gülüm Gurbetinde Akşamın... Istırabı, Sev...', ARRAY['Türk Edebiyatı','Şiir','Kadir Keskin']::text[], 8.5, '{"poet":"Kadir Keskin","poet_slug":"kadir-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/neredesin-gulyuzlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Muştusu', 'gul-mustusu-ozlem-torkul-tekan-kun86', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uyan artık gözlerim söyle bu ne uykusu

Özgürlük ilelebet gaflet hiçlik korkusu

Gün gelir döner devran, biter özlem tutkusu 

Yine yeni yeniden sinede gül muştusu...

(2 Aralık 2001)', 'Uyan artık gözlerim söyle bu ne uykusu Özgürlük ilelebet gaflet hiçlik korkusu Gün gelir döner devran, biter özlem tutkusu  Yine yeni yenide...', ARRAY['Türk Edebiyatı','Şiir','Özlem Torkul Tekan']::text[], 8.5, '{"poet":"Özlem Torkul Tekan","poet_slug":"ozlem-torkul-tekan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gul-mustusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazel', 'gazel-ahmed-pasa-3pnf8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şol kara kaşın çatıp gönlüm hilâl etmek neden

Hey elâ gözlüm bizimle mekr ü al etmek neden

Âyet-i hüsnünle sen vaslın harâm etdin bana

Ben harâmî çeşmine kanım helâl etmek neden

Hüsnü kandilin uyarmış nûr-ı Hak''dan nûr-ı aşk

Zâhidâ inkâr-ı nûr-ı zü''l-celâl etmek neden

Âlemin gönlün yapar o seng-dil illâ benim

sırça gönlüm sındığıncs pây-mâl etmek neden

Dedim âhir cân ise maksûd nâzından me''âl

Dedi evvel âşıka fikr-i me''âl etmek neden

Gülşen-i vaslın hevâsında uçarken murg-ı dil

Âşiyân-ı hecrde bî-perr ü bâl olmak neden

Leblerinde hat görüp kan ağladım güldü dedi

Sâye-i ebrûm için egri hayâl etmek neden

Kâmetin sordum rakîbe işidüp dilber dedi

Ahmed İblis''e kıyâmetden suâl etmek neden

                         AHMED PAŞA', 'Şol kara kaşın çatıp gönlüm hilâl etmek neden Hey elâ gözlüm bizimle mekr ü al etmek neden Âyet-i hüsnünle sen vaslın harâm etdin bana Ben h...', ARRAY['Türk Edebiyatı','Şiir','Ahmed Paşa']::text[], 8.5, '{"poet":"Ahmed Paşa","poet_slug":"ahmed-pasa","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gazel-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teneke yüreğe', 'teneke-yurege-aysenur-yazici-fng4d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hangi dost görse aynı şeyi söylüyor

bu kadar teneke bir yüreğe

bu  kadar yabani bir sevgiye

döktüğün gözyaşı yetmez mi diyor

sende bu koşulsuz okyanus varken, 

varken sende bu yürek kalender

kıymet bilmez ademoğluna destan yazılır mı hiç

utanır adı ''AŞK'' olmuş tarihtekiler...

küskün perdelerimi görenler

'' aç gözlerini dostum ''  der

kendini mapuslara koyma

ne olur bir aynaya bak! ! 

tapan bir kadın yüreğini

göremeyendir asıl  avanak! 

              12.08.2003

                Çeşme

                (21:30)', 'Hangi dost görse aynı şeyi söylüyor bu kadar teneke bir yüreğe bu  kadar yabani bir sevgiye döktüğün gözyaşı yetmez mi diyor sende bu koşuls...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/teneke-yurege-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-ozlem-torkul-tekan-brghe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sonbahar çocuğuyum ben

Hüzün mevsiminin ilk ayında gelmişim dünyaya.

Saçlarım düşen yapraklardan almış rengini

Gözlerim ise yeşile elveda, 

Sarıya merhaba diyen çimenlerden.

Belki de bundandır bakışlarımın donukluğu

Saçlarımın deli rüzgarlara olan tutkusu.

Ne ırmak gibi coşmayı bilirim baharda, 

Ne renk renk açmayı yazın kırlarda.

Ne ayaz olabilirim insanın içine işleyen

Ne de yakabilirim gönülleri yaz güneşi misali.

Yağmur olur, damla damla açık kalplere akarım, 

Rüzgar olur, diyar diyar bendeki beni ararım, 

Yaprak olur, bir sağa bir sola savrulurum, 

Toprak olur, hasret ile yanarım ben.

Sanki okumuş da kaderimi yüzümden, 

Özlensin ama özlemesin demeden

Bir isim vermiş ki bana annem

Tek duygudur yıllar yılı bende hüküm süren.

Bu ne itiraf ne de sitem:

Sonbahar çocuğuyum ben.

(Mayıs 1994)', 'Sonbahar çocuğuyum ben Hüzün mevsiminin ilk ayında gelmişim dünyaya. Saçlarım düşen yapraklardan almış rengini Gözlerim ise yeşile elveda,  ...', ARRAY['Türk Edebiyatı','Şiir','Özlem Torkul Tekan']::text[], 8.5, '{"poet":"Özlem Torkul Tekan","poet_slug":"ozlem-torkul-tekan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ben-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savunmasız Gecem', 'savunmasiz-gecem-sedef-unal-dp5n4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin bir vakti 

Ben yine hüzünlerdeyim 

Ümitlerim yorgun, yalnızlığım buz kesiyor 

Düşüncelerim dolu dizgin giden 

Bir küheylan sürüsü gibi 

Üzerime gelmekte 

Yüreğim sanki bir  girdaba tutulmuş 

İsyanlarda 

Ya..o su gibi akan zaman 

Bana inat ayağını sürüye sürüye gidiyor. 

Neydi beni böylesine hüzünlendiren 

Dinlediğim eski bir bozlak türkü 

Geri gelmez günlerimden 

Bir buket çiçek sunar gibi 

Yüreğime düştü 

Bu gece ben mi savunma sizsizim 

Yoksa..türküler mi acımazsız 

Bitmeyen gecenin esmer rengi 

Kirpiklerimin üzerine çöken bir yorgunluk 

Oysa yarına umutlarla bakıp 

Rüyalarımı bile gömgök boyamak isterim 

Gece koynunda sakladığı tüm renklerini 

Yakut kızıllığında ki ağaran sabaha 

Devretmenin huzuru ile yalabımakta 

Bense gömgök hayallerin peşinde

10 Ağustos 2003', 'Gecenin bir vakti  Ben yine hüzünlerdeyim  Ümitlerim yorgun, yalnızlığım buz kesiyor  Düşüncelerim dolu dizgin giden  Bir küheylan sürüsü gi...', ARRAY['Türk Edebiyatı','Şiir','Sedef Ünal']::text[], 8.5, '{"poet":"Sedef Ünal","poet_slug":"sedef-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/savunmasiz-gecem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Odamın Penceresinden', 'odamin-penceresinden-abdulkerim-capar-vfaf0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şimdi uzak bir şehirde

Odamın penceresi kadar özgürüm

Bu şehirde insanlar çok

Sayamayacağın kadar çok

Bilmem kaçta kaçı burada yaşıyor ülkenin

En yüksek yerinden bile

Görünmüyor bizim memleket

O kadar uzak bir yerdeyim yani

Ve odamın penceresi kadar özgür

Herkes bir taraflara gitmekte

Her dolmuşta onlarca insan

Kısır bir döngüde

Dönüşü olmayan bir yolculuksa hayat

İstikamet nereye sakallı dede

Ne düşünmekte karşıdaki kız

Uzakları yakın emek mi amacı

Bizim şoförün

Son durak neresi teyze

Kadıköy mü

Bir soğuk musalla taşımı yoksa

Gecenin en verimli saatleri bunlar

Harıl harıl çalışmakta şimdi

Aydınlık yapmak için karanlıkları

Yavaş yavaş belirginleşiyor deniz

Tek direnen sokak lambaları gündüze

Birazdan

Bir ezan sesi son verecek bu sessizliğe

Yeni umutlarla uyanacak şehir

Çöpçülerde gelmeye başladı işte

Yeniden kirletebilsin diye insanlar

Sokakları süpürüyorlar usulca

Hani eski aşkları unutmaya çalışır ya insan

Yol-vermek için yeni sevdalara...

Bu şehrin sokaklarında yürüdüm ben

Her adımda hissettim yaşamayı

Vapurlara bindim geceleri

Gitmek için düşler kıyısına

Beşiktaş iskelesinden

Bu şehirde yeniden öğrendim seni sevmeyi

Vapur vapur, sokak sokak, insan insan

Hep hayallerimdi odamda gördüklerim

Çöpçüler, insanlar, sokak lambaları hep hayal

Sırf seni gördü gözlerim pencerede

Sırf seni aradı ellerim

senin kollarında daldım uykuya

Senin günaydınınla açıldı gözlerim.

Oysaki

Her köşe başında bir bilinmezlik vardı bu şehrin

Her adımında onlarca insan

Her nefesi ayrı bir zevk verdi

Boğazda içtiğim sigaranın

Onlarca vapur varken bu şehirde

Binlerce bina, milyonlarca insan

Bir o kadar da sokak lambası

Senin yerini dolduramadı kara gözlüm

Bir sen edemedi bu ülkenin bilmem kaçta kaçı

...

Anladım sen bu şehirden gizemli değilsin

Anladım bu şehir senden kalabalık değil!', 'Şimdi uzak bir şehirde Odamın penceresi kadar özgürüm Bu şehirde insanlar çok Sayamayacağın kadar çok Bilmem kaçta kaçı burada yaşıyor ülken...', ARRAY['Türk Edebiyatı','Şiir','Abdulkerim Çapar']::text[], 8.5, '{"poet":"Abdulkerim Çapar","poet_slug":"abdulkerim-capar","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/odamin-penceresinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayılma Saatleri', 'ayilma-saatleri-turgay-kaygi-sp6yj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'daha önce de oldum böyle; 

defalarca hem de! 

hep aynı terane! 

gidecek bir yer, 

edecek bir şey kalmadığında

kendisini okyanusa atan 

yorgun göçmen kuşlar gibi olurum…

“belki bambaşka bir yerde uyanırım, 

belki de hiç uyanmam bir daha! ”

diyerek

vurup kendimi ummanına alkolün

kendimi 

alkolün ummanında kaybetmekten başka bir şey ummam! 

beni seven herkes

bu saatlerde sevmiş olmalı diyorum! 

serserilik peşinde, bar bar dolaşıp, 

bilfiil ayaklar altına alıp

onur, haysiyet v.b. ne varsa

akabinde ayılmaya yüz tuttuğum saatlerde…

babam bile gülmüştü bir gece; 

“şerefyab oldum; kimlerdensiniz? ” 

diye sorduğumda…

velhasılı

ayılıyor insan gitgide! 

aşk, meşk, kariyer

ve diğer

onca soluk soluğa savaştan sonra

sadece bilmemkaç promili kalıyor saadetin

insan vücudunda

sonra o da uçup gidiyor…

bazen; 

dalsam denize 

sarhoş olup olmayacağı geliyor aklıma balıkların, 

bazen; 

hayatı sevmediğim geliyor, 

hayatında bana pek düşkün olmadığı geliyor, 

geliyor da geliyor…

hayat; 

sanki üzerime ters giydiğim

bir gömlekmiş gibi geliyor

bazen…

mutluluk; 

son sürat koşan

bir tazıdır; 

yakalayabilene aşk olsun…

aşk olsun; 

duyuyor musun? 

(bursa,  08.08.2003)', 'daha önce de oldum böyle;  defalarca hem de!  hep aynı terane!  gidecek bir yer,  edecek bir şey kalmadığında kendisini okyanusa atan  yorgu...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/ayilma-saatleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlı Gece', 'yildizli-gece-turgay-kaygi-29ay1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dün gece; 

karşımda

van gogh''un o tablosu gibi

asılı duran 

gökyüzünün

bana en uzak yıldızını

seçip

senin isminle çağırdım

gelmeyeceğini

fena halde bilerek! 

(inegöl,  09.08.2003)', 'dün gece;  karşımda van gogh''un o tablosu gibi asılı duran  gökyüzünün bana en uzak yıldızını seçip senin isminle çağırdım gelmeyeceğini fen...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yildizli-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-sair-musturk-wb2yr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşamak direnmektir

Katlanmaktır her türlü acıya

Bazen mutlu olmaktır 

Baska hiçbir şey düşünmeden

Bazen mutlu olsanda rahat etmemektir 

Düşünerek bütün kötülükleri

Aslında yaşamak ölmektir 

Adım adım yaşadığını sanarak', 'Yaşamak direnmektir Katlanmaktır her türlü acıya Bazen mutlu olmaktır  Baska hiçbir şey düşünmeden Bazen mutlu olsanda rahat etmemektir  Düş...', ARRAY['Türk Edebiyatı','Şiir','Şair Mustürk']::text[], 8.5, '{"poet":"Şair Mustürk","poet_slug":"sair-musturk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yasamak-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaşa Gitmermiz Buyruldu', 'savasa-gitmermiz-buyruldu-demyan-bedniy-1ty5e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '- Bir Asker Türküsü 

Savaşa gitmemiz buyruldu 

“Toprak için aslanlar gibi dövüşün” diyerek 

Toprak için! Ama kimin toprağı? Söylenmedi bu 

- Dere beyinin toprağı olsa gerek! 

Savaşa gitmemiz buyruldu 

“Özgürlük adına” diyerek 

Özgürlük adına! Ama kimin özgürlüğü? Söylenmedi bu 

Halkın özgürlüğü olmasa gerek! 

Savaşa gitmemiz buyruldu 

“Bizden” dendi “yardım bekliyor müttefik uluslar” 

Ama en önemli şey unutuldu: 

Kimin cebine girecek banknotlar? 

Savaş kimisi  için hayatla ödenen bir fatura 

Milyonluk kazançtır kimisine

Çoçuklar, daha ne kadar -

Katlanacağız bu ağır işkenceye? 

                Demyan BEDNIY', '- Bir Asker Türküsü  Savaşa gitmemiz buyruldu  “Toprak için aslanlar gibi dövüşün” diyerek  Toprak için! Ama kimin toprağı? Söylenmedi bu  -...', ARRAY['Türk Edebiyatı','Şiir','Demyan Bedniy']::text[], 8.5, '{"poet":"Demyan Bedniy","poet_slug":"demyan-bedniy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/savasa-gitmermiz-buyruldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Tutsak Gülüşlerim', 'aska-tutsak-guluslerim-kibar-tavasav-a5sa7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerinle beni içtiğin günden beri ben

Okyanusta fırtınaya yakalanmış

Bir gemi gibi yalpaladım 

Bir o yana, bir bu yana, yana, yana

Ne bir yol buldu dümenim, nede gözlerinden bir iz 

Kayboldum bu maviliğin gölgesinde 

Bir dalga aldı beni 

Bir kasırga savurdu

Bir balık gülümsedi 

Dişi bir martı yoldaşım oldu 

Dudaklarını içtiğimden beri küpeştesi çatırdamış bir gemiye döndüm 

Su aldım içime, 

Balıkları aldım, 

Yosun gözlerini, 

Narin ellerini, saçlarını aldım 

Bunlar da yetmedi, aşkını da aldım 

Şimdi aşka tutsak gülüşlerim 

Savruldum, 

Dans ettim gözlerindeki dalgalarda 

Ve bir ada çıktı karşıma, dağları ikili göz, göz kahverengi

Dağların etekleri sarımtırak boy, boy kahve ağaçları, 

Palmiyeler kaplamış ada sahilini,  yeşili üstünde son gördüğüm elbisen rengiydi, 

Gökyüzü maviydi 

Adanın çevresindeki deniz 

En güzel yeşili, 

En güzel maviyi, 

En güzel kırmızıyı, 

Sarıyı, 

Kahverengiyi, 

İçiyordu kainatın dudaklarından bir, bir 

Gökkuşağının bütün renkleri burada hakimdi ve bu ada sendin! 

Biletsiz ve kaçak bindim biliyorum 

Vurdum kapıyı, daldım gözlerinden içeri şu yüreğim salkım, salkım 

Sana hiç bir şey sormadım, 

Ben böyleyim şaşırtırım, ansızın ve hiç beklenmemiş bir anda usul, usul sokulur 

Ve aniden vururum yüreğinin on iki sinden 

Sen ne yaparsan yap yüzde yüzdür isabet oranım, 

Tuttum mu tutarım, 

Çarptım mı çarparım, 

Sende tutuşursun çırpınışların boşuna, artık bende bir ada sahibi olanlardanım 

Ve benim aşka tutsak gülüşlerim 

On yedi renk duygular yoğun içimde

Renk, renk

Canlı, canlı 

Biz yerinde mertizde birazda delikanlı

Sen aldırma otuz beş yaşımıza ve de beş beyazlamış sakalımıza

Biz çivileri dişimizle bir, bir çıkarırız aşkımızın sökemezken hiç bir kerpeten 

Söyleyeyim mi sana en çok neyini sevdiğimi? 

Söyleyeyim mi? 

Söyleyeyim mi? 

Duruşunu, kokunu sevdim 

Leylak kokuyorsun sen, 

Sonra ellerini, 

Ok, ok olmuş gönlüme batan kirpiklerini, 

O gülüşlerini sevdim 

Tıpkı ben gibi gülüyorsun sen, 

Sonra, sonra içimi titreten öpüşlerini sevdim

Öptün kapadın gözlerini, 

Biliyorum o an ben gözlerinin içindeydim, 

Ve de yüreğinden bir cımbız gibi tel, tel sevdanı çektim bir, bir 

Tıpkı gözlerinde fırtınaya tutulmuş ben gibiydin, 

Tenimde bedeninle çağlıyordun

Bense kükrüyordum, 

İşte o an senin aşka tutsaktı gülümsemelerin 

Elim eline dokunduğunda, 

Dokunuşlarımda, 

Ben yoktum

Sen yoktun 

Biz vardık ikimiz

Kavga ederdi birbirleriyle göz bebeklerimiz 

İşte budur aşkımız 

İşte buyuz biz ikimiz 

Bitirilemeyecek bu sevgimiz

Çünkü her öpüşmelerinde gözlerimiz 

Yükleniyor daha da üstü üstüne gönlümüzde sevgimiz 

Çok düşünmene gerek yok

Fırtına yağmur var

Fırtına kar,

Fırtına gol var 

Buda fırtına aşk bizimkisi, 

Tam da gönlümüzün ortasında yaşamalıyız 

Kaçmadan, 

Korkmadan, 

Bıkmadan, usul, usul sıcacık 

Uyuyor musun? 

Aynı zamanda duyuyor musun? 

Aç o kahve gözlerini, bekle gireyim içeri 

Sar bir yonca demeti gibi beni 

Bırak da emeyim dudaklarından seni 

Ben seni içtiğim o ilk günden beri sarhoş olamıyorum 

Ve şimdi keşmekeşim, 

Dilimde sözcük kalmadı döküldü bir, bir koynuna 

Senin o hayal parmakların geziyor yine boynumda 

Dokunuşların bir kor edasında 

Yakıyorsun beni 

Hadi yak beni 

İç beni, çıldırdım inan şimdi

Vur beni! Vur! 

Vur! 

Vur! 

Aşka tutsak gülüşlerim', 'Gözlerinle beni içtiğin günden beri ben Okyanusta fırtınaya yakalanmış Bir gemi gibi yalpaladım  Bir o yana, bir bu yana, yana, yana Ne bir ...', ARRAY['Türk Edebiyatı','Şiir','Kibar Tavasav']::text[], 8.5, '{"poet":"Kibar Tavasav","poet_slug":"kibar-tavasav","theme":"Türk Şiiri","is_hero":false,"total_lines":101,"source_url":"https://www.antoloji.com/aska-tutsak-guluslerim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-ahmet-aksoy-ml5rl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu dünyada

Zamanı gelse de gelmese de

Her şey öldü

Kimi zaman yaşlılar 

Kimi zaman çocuklar 

Genç yaşlı demedin

Hiç acımadın olum

Aşk öldü sevgi öldü

Yalnız iyiler değil 

Kötüler de oldu

Hiç kıyamadığın oldu mu olum

Yada bir kez olsun elin titremedi mi

Hiç acımadın mı ölüm

Bir tek sen ölmedin

Korkmadın mı hiç 

Düşünmedin mi kendi sonunu

Yoksa her şey gibi

Senin de sonun olabileceği

Aklına gelmedi mi ölüm

Hiç ne zaman demedin mi 

Ne zaman sonum.', 'Şu dünyada Zamanı gelse de gelmese de Her şey öldü Kimi zaman yaşlılar  Kimi zaman çocuklar  Genç yaşlı demedin Hiç acımadın olum Aşk öldü s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/olum-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Miço''ya Fırça Şiir', 'mico-ya-firca-siir-orhun-basat-dbzfc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '‘’denizin tadı olmasaydı

			                                       sırtıma saplanan gecede, 

			                                        affetmeyebilirdim..’’

			

	Bu gün palamarları çözen fırtınalar yok, 

	Miço’ lar izinde.

	Yağan yalnızca yağmurdu, 

                gözlerim üşümeden önce..

                 Üşümeden önce baktım, palamarda yok; 

                 iskeleye ruhumla birlikte bağladığım tekne de.

                 Yalnızsam; şiir yazacak kimileri de, 

                                                                     - şiir de...-

	Bilirim denizleri üstelik, Akdeniz’i de, 

	sen de benim denizleri bildiğimi bilirsin, Miço.

	Rüzgar sinmiş tuzlu özlemlerime

	Hükmedemediğimi de..

                Bilirsin, deniz değince cız eden yüreğimi 

	ve  deniz deyince tutmayan dizlerimi de..

	Bana üzerinde anılar olan

	iki karış kumsal getir, unutma..

	ve bir kokum da olsa, deniz getir.

	Tuzludur deniz, bilirsin, Miço.

	Bakarsın yaralarıma iyi gelir...

			

			 				[email protected]', '‘’denizin tadı olmasaydı 			                                       sırtıma saplanan gecede,  			                                        affe...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/mico-ya-firca-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman II', 'zaman-ii-ahmet-aksoy-knp0y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aldıkların verdiklerini

Geçer oldu zaman

Eskiden hep verirdin

Geçerken bırakırdın geride güzellikleri de

Şimdilerdeyse ya vermeyi unuttun

Yada verecek bir şeyin kalmadı da

Geçerken önüne geleni

Silip süpürüyorsun

Hem eskiden elin bu kadar sıkıda değildi

Tartmazdın verirken eksik mi fazla mı diye

Şimdiyse cimri ihtiyarlara döndün

Ne koparırsam kar diyorsun

Sen de mi yaslandın yoksa

Benimle birlikte zaman', 'Aldıkların verdiklerini Geçer oldu zaman Eskiden hep verirdin Geçerken bırakırdın geride güzellikleri de Şimdilerdeyse ya vermeyi unuttun Ya...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zaman-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koşar Adım', 'kosar-adim-ahmet-aksoy-eg1ub', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Koşar adım gidiyorum bir yerlere

Sanki yetişmem gerekiyor gibi

Bazen kaçıyorum hızla bir yerlerden

Sanki ardımda beni arayan bir ordu var gibi

Bazen beni arayandan korkuyorum

Bazen de yetişememekten beni bekleyene, 

İki arada yasıyorum.', 'Koşar adım gidiyorum bir yerlere Sanki yetişmem gerekiyor gibi Bazen kaçıyorum hızla bir yerlerden Sanki ardımda beni arayan bir ordu var gi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kosar-adim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Banka Hesabı', 'banka-hesabi-ahmet-aksoy-vlprn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıllar geçiyor ya

Ne kadar da acıtıyor geçerken

Her saniye bir şeyler götürüyor

Yalnız ölüme yaklaştırmıyor üstelik

Geçen her saniye birleşerek

Yalnızca ömrümü törpülemiyor

Giderken isteklerimi de sürüklüyor

Hiç, iyi kötü demeden

İmkanım olsa eğer

Yapacağım her şeyi de yanında götürüyor

Geçen her saniye ve her dakika

Üst üste konduğunda

Yapamadıklarımı da götürüyor

Hem de çok isteyip de yapamadıklarımı

Belki de biraz daha vaktim olduğunda

Yapacaklarımı, Keşke ömürde 

Banka hesabı gibi olsaydı

Ne yazık.', 'Yıllar geçiyor ya Ne kadar da acıtıyor geçerken Her saniye bir şeyler götürüyor Yalnız ölüme yaklaştırmıyor üstelik Geçen her saniye birleşe...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/banka-hesabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çeşit Asker(lik) Kaçaklarına', 'bir-cesit-asker-lik-kacaklarina-orhun-basat-uu5c7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üçüncü bir kol gibi taşınırken, 

Cilo dağlarında mavzer, 

sen yolunu bulup, 

makam aracının direksiyonuna kurulup, 

paşa’sını, paşa paşa taşıyan asker..

Seni torpilin kurşunlayacak, 

 Ve şehit sayılmayacaksın..', 'Üçüncü bir kol gibi taşınırken,  Cilo dağlarında mavzer,  sen yolunu bulup,  makam aracının direksiyonuna kurulup,  paşa’sını, paşa paşa taş...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-cesit-asker-lik-kacaklarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terket Beni', 'terket-beni-seval-kemertas-cwewx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'git gide büyüyor

anlaşılmazlık içimizde

ben artık biraz senden

sen artık biraz benden

gidiyorsun...

elden düşme kavgalar

yoruyor, yıpratıyor git gide

içimizdeki aynaları kırıp

karanlığa gömülüyoruz ikimizde

ne umut kaldı içimizde

ne de aşkın mavi rengi

yok oluyoruz göz göre göre

eğer iyi gelecekse sana

hiç düşünme aşkım

terket beni...

beni dağıt...

beni yağmalat..

beni aldat...

İstanbul sokaklarında...

12/08/2003', 'git gide büyüyor anlaşılmazlık içimizde ben artık biraz senden sen artık biraz benden gidiyorsun... elden düşme kavgalar yoruyor, yıpratıyor...', ARRAY['Türk Edebiyatı','Şiir','Seval Kemertaş']::text[], 8.5, '{"poet":"Seval Kemertaş","poet_slug":"seval-kemertas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/terket-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eda', 'eda-cahit-sitki-taranci-pdqnh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'N''eyleyim seni kartpostal manzara

Rüzgarın yok o yerin havasından

Uğuldamak yaraşır ormanlara

Denizin güzelliği dalgasından

Geyik dağdan dağa atlarken güzel

Nar dalında diş diş çatlarken güzel

Kestane mangalda patlarken güzel

Kişilik güzelliğin esasından

Beni saran şey suyun akışıdır

Yemiş yüklü dalların sarkışıdır

Ananın çocuğuna bakışıdır

Sevdiğim geçilmez edasından', 'N''eyleyim seni kartpostal manzara Rüzgarın yok o yerin havasından Uğuldamak yaraşır ormanlara Denizin güzelliği dalgasından Geyik dağdan dağ...', ARRAY['Türk Edebiyatı','Şiir','Cahit Sıtkı Tarancı']::text[], 8.5, '{"poet":"Cahit Sıtkı Tarancı","poet_slug":"cahit-sitki-taranci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklardan gelen', 'uzaklardan-gelen-serhat-kaya-rvx3w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'belki bir gün gelir 

kapın çalınır ansızın 

ve birden heyecanlanırsın 

kimdir gelen diye 

ve aniden yazdığın o şiirin 

kahramanı geldi diye 

ve kendini uçsuz bucaksız 

hayyalerin içinde bulursun 

anlaşılmayan yanıyla hayatın 

merak sinyalleri geçer yüreğinden 

kimdir haykırdığın nidalarını 

işiten ve nasıldır 

belki hiçi ummadığın bir aşktır 

sana ulaşan veya güvercindir 

ellerinde bir mektup var 

uzaklardan gelen 

ve altından benim adım 

yazılı büyük harflerle 

ve en güzel renkle 

ve en güzel biçimde kırmızıyla 

seni bekleyen ''Karanlık''tır....', 'belki bir gün gelir  kapın çalınır ansızın  ve birden heyecanlanırsın  kimdir gelen diye  ve aniden yazdığın o şiirin  kahramanı geldi diye ...', ARRAY['Türk Edebiyatı','Şiir','Serhat Kaya']::text[], 8.5, '{"poet":"Serhat Kaya","poet_slug":"serhat-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/uzaklardan-gelen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeç', 'vazgec-fatih-erkoc-tzksk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vazgeç heyevanlardan vazgeç

İki günlük yaşamda boşuna yorulma

Gel otur, tadını çıkar anın

Unut artık figanı

Boşuna yorulma

Dinle

Huzur dolsun kalbine

Kapa gözlerini ve unutup kederleri

Ah avun

Sahip olduklarınla

Ruhunu temizlerken

Sesimi duyunca bu şarkıda', 'Vazgeç heyevanlardan vazgeç İki günlük yaşamda boşuna yorulma Gel otur, tadını çıkar anın Unut artık figanı Boşuna yorulma Dinle Huzur dolsu...', ARRAY['Türk Edebiyatı','Şiir','Fatih Erkoç']::text[], 8.5, '{"poet":"Fatih Erkoç","poet_slug":"fatih-erkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vazgec-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama', 'aglama-fatih-erkoc-fefwj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gönül var ki sende benliğini eser alan

Her elveda dediğimde seni yerden yere vuran

Ne yapsam fayda etmiyor yazık

Üzülmemek elde değil biliyorum sen ağlarken

Akan yaşlar yalan değil

Gel artık ağlama

Dönüyorum işte sana

Bir daha terketmem

Ne olursun inan bana

Aşık olmak yetmkiyor canım mutluluğa giden yolda

Ayrılmayalım derken bir daha

Yaşıyoruz uzaklarda

Ama inin ki sevgilim bana

Her acının sonu güzel

Ve her yağmurun ardından güneş açar pırıl pırıl

Zaman doldu birazdan ordayım

Silinecek ayrılıklar acı dolu gözyaşları

Dönüşecek mutluluğa', 'Bir gönül var ki sende benliğini eser alan Her elveda dediğimde seni yerden yere vuran Ne yapsam fayda etmiyor yazık Üzülmemek elde değil bi...', ARRAY['Türk Edebiyatı','Şiir','Fatih Erkoç']::text[], 8.5, '{"poet":"Fatih Erkoç","poet_slug":"fatih-erkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/aglama-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Piyasaya Çıkan Aşka ve Bana Dair', 'piyasaya-cikan-aska-ve-bana-dair-sair-ysl-p1gba', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'her düş kabusa çıkıyor

her ten senindir artık

siz ey orospular! 

teslim edin bana aşklarınızı

- üstünden kimler geçti-

bir kuytuda

ya da bir bekar evinde

nerde benim kaybettiğim

benimki hanginizde

Hiçbir taş yerinde değil

parçalanmışım deprem zamanı

her parçam gitmiş bir dağ başına

ne sende ben kalmışım ne bende sen 

hangi aşk onurlanır 

aya gölge düşürmüşsen

yıkanmak istiyorum

yıkanmak yıkanmak yıkanmak

külliyen zehir 

külliyen kan

kendi içine akan

bir sıcak damla olmak

ve sen ey aşk! 

yağmur sularıyla gel bana

toprak, dağ, deniz olmalısın

safi düş

ve safi ıhlamur kokmalısın

materyalist korku:

korkuyorum

bu yıl

bahar gelmeyecek

fakat

su da yürüyor bir yandan

izmir,7-15 nisan 2003, YSL', 'her düş kabusa çıkıyor her ten senindir artık siz ey orospular!  teslim edin bana aşklarınızı - üstünden kimler geçti- bir kuytuda ya da bir...', ARRAY['Türk Edebiyatı','Şiir','Şair Ysl']::text[], 8.5, '{"poet":"Şair Ysl","poet_slug":"sair-ysl","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/piyasaya-cikan-aska-ve-bana-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyemem Sana Haydi Güle Güle', 'diyemem-sana-haydi-gule-gule-salih-ozalasan-uesa3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yanıyorsa yüreğim gittiğinde

Lâvlara dönüyorsa gözyaşım

Anlamı kalmıyorsa etrafa bakmanın

Diyemem sana, haydi güle güle

Öfkem kabarıyorsa

Azgın dalgalara dönüyorsa isyanım

Kırıyorsam beni sevenleri

Diyemem sana, haydi güle güle

Nefrete dönüyorsa sevgim

Yanardağ misali kızartıyorsam gölgemi

Kükrüyorsam kudurmuş aslan misali

Diyemem sana, haydi güle güle

Kalemim kan kusuyorsa

Sevgi sözcüklerini yutuyorsa deniz gibi

Sayfalar korkup kaçıyorsa benden

Diyemem sana, haydi güle güle

Deme bana gelmeler varsa olacak gitmeler

Topraktan geldik toprağa dönmeler

Say ki ölmüşüm bitsin sevmeler

Uzaktan olsun gizli kalsın sevmeler

Deme bana sakın, sakın deme

Seni seviyorum, seviyorum gidiyorum

Yüreğimde senden başkasına yer yokken

Diyemem sana, haydi güle güle

Toprak yarılıp alsa da seni benden

Kopsa kıyamet yıkılsa gök kubbem

Sanır mısın ecel alır seni benden

Ateş olur yağarım inan gökten

Seni benden başkası alamaz bilesin benden

Tanrıdan sonra tek sevdiğim senken

Dünya da etmişsem seni kıblem

Diyemem sana, haydi güle güle

Ben yaşıyorsam benimle yaşayacaksın

Kâlbim atıyorsa orada kalacaksın

Mahşerde doğarsam benimle olacaksın

Kim bilir belki o gün beni unutacaksın

Cennet bahçesinde bir huri olacaksın

Yine o endamınla dolanacaksın

Sen unutulamazsın hep hatırlanacaksın

Diyemem sana, haydi güle güle

Y.Tarihi 12-08-2003 Saat 12,15

Salih ÖZALAŞAN', 'Yanıyorsa yüreğim gittiğinde Lâvlara dönüyorsa gözyaşım Anlamı kalmıyorsa etrafa bakmanın Diyemem sana, haydi güle güle Öfkem kabarıyorsa Az...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/diyemem-sana-haydi-gule-gule-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kemal Bey İle Servet Usta', 'kemal-bey-i-le-servet-usta-ensar-aktas-8v02y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kemal bey ile Servet usta aynı mahallede otururlardı, 

Ve aynı sıraları paylaşırlardı ilkokul çağlarında

Birlikte taş atarlardı sapan ile armut ağacına da

Bir gün taş, caminin penceresine isabet etmişti kazara

Çok korkmuşlardı, çocukluk işte, çarpılacaklarını sanmışlardı…

Sonra yolları ayrıldı ortaokul çağlarında

Kemal bey büyük şehire gitti, kolejde okumaya

Servet usta ise çıraklığa başlamıştı bir tamirci dükkanında

Kemal beyin gözü yükseklerdeydi, hedefleri vardı

Servet çırağın ise hayali küçüktü, meramı usta olmaktı…

Tornavida, ingiliz anahtarı derken iyi bir usta oldu sonunda

Kemal bey ise koleji bitirmişti bitirmesine ama hedefini tutturamamıştı

Kasabaya dönüp politikaya atılmıştı…

Havasından mı, suyundan mı, kasabada işi yaver gitmişti

Bir partinin belediye başkanlığı adayı oluvermişti

Havası yerindeydi… Ankara’ya gidecek yolda besmeleyi çekmişti

Günler gelip geçiyordu, Kemal beyle Servet usta pek görüşmeselerde

Kemal bey seçimin, Servet usta ise geçimin derdindeydi…

Bir gün çok önemli bir mitinge giderken arızalandı seçim otobüsü de

Servet usta yetişdi imdadına Kemal beyin, yetiştirdi onu mitinge…

Kemal bey çiçeği burnunda başkan olmuştu ve Servet ustanın adı dilinden hiç düşmüyordu

Her fırsatta; “Ben bu seçimi Servet ustanın sayesinde kazandım” diyordu

Kasabada günler genelde sakin gelip sakin geçiyordu… 

Ama bir sabah Servet ustanın dükkanının önünde bir velvele koptu ki…

Servet usta parmağına vurduğu kanlı çekiç ile birlikte fırladı dışarıya…

Parmak acısı da birşey mi? Şoke olmuştu gördüklerinin karşısında

Bir grayderle bir de dozer eşliğinde polisler, zabıtalar ve başkan Kemal bey en ön safta; 

“Servet usta! Servet usta! Yıkacağım dükkanını, ruhsatsız yapıymış” diye bağırıyordu

“Yapma başkan! Biz seninle eski arkadaşız, kankiyiz, yediğimiz içtiğimiz ayrı gitmezdi, 

Ne yaparım ben sonra? Başımda beş horanta, elime bakıyorlar, birde hasta ve yaşlı bir ana…”

“İş ayrı arkadaşlık ayrı, yasaları uyguluyorum ben, kusura kalma.” 

Ve dükkanın bacasıyla birlikte başına yıkılıverdi Servet ustanın dünya…

Eski dost düşman olmazdı ama bu olay Servet ustanın iflası olmuştu, 

Başkan Kemal beyin ise kasaba daki en büyük icraatı…

Rotterdam,22-06-2003', 'Kemal bey ile Servet usta aynı mahallede otururlardı,  Ve aynı sıraları paylaşırlardı ilkokul çağlarında Birlikte taş atarlardı sapan ile ar...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kemal-bey-ile-servet-usta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şi-i-rinsin', 'si-i-rinsin-ensar-aktas-57ptc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Masallarda duyardım eskiden

Bahsederlerdi hep güzeller güzeli bir prensesten 

Bazan yeşil olurdu gözleri

Bazan da türkuaz, mavi

Nedense hep renkli, hep iri iri…

Yanakları elma, dudakları kiraz gibi…

(Burası çok önemli) : 

…Ve melek gibi bir yüreği

En çokta o vururdu yüreğimden beni 

Bir de fakir bir genç olurdu ve ölümüne severdi prensesi

İçine kapanıktı belki… kimsesizdi, 

Üstü başı perişan, eski

Dağınıktı perçemleri

Ama yiğit gibiydi bileği…

Ve tek servetiydi altın gibi yüreği 

Ninem bazan hile yapıp masalı mutlu sonla bitirirdi

Ama genelde delikanlı Ferhat, prenses ise Şirin idi

Deli gibi dağları delerdi, yine de kavuşmazdı elleri

Masalın sonunda ninem yorganı üzerime örtüp, 

Bir de yanağımdan usulca öpüp, 

Bir balerin edasıyla parmaklarının ucuna basarak kapıdan çıkar giderdi

Bense bir süre Ferhat olup vururdum dağlara…

Ve sonra göz kapaklarım yorgun düşerdi

Yenik düşerdim hayallerime, prensesin gözlerine…

Birgün ninem parmaklarının ucuna basarak odadan çıktığı gibi

Hayatımdan da çıkıverdi… Aldı götürdü onu melekler

(Nur içinde yat kır saçlı nineciğim benim, tatlı dillim)  

Bu, masalların da bitimiydi…

Ve yüzüme ilk çarpışı hayatın acı gerçeklerini

Yıllar su gibi akıp gidiyordu, masalsız, düşsüz, prensessiz…

Hüzünler ağını örmüştü yüreğime sessiz sessiz

Gözlerimin yaşama sevincinden, yaşamınsa yoktu haberi benden

Ne uğruna Mecnun olacak Leyla, ne Kamber’in Arzu’su, ne Kerem’in Aslı’sı…

Ne de uğrunda dağları delecek bir Şirin vardı

Masallarda yaşardı o büyük aşklar, masallarsa mazide kalmıştı

Tâ ki o sevdalı gözlerin geçinceye dek yüreğimden, aniden

Ve şiir gibi sözlerin, güneş gibi gülüşlerin alıncaya dek beni benden

Kader miydi seni çıkartan karşıma? Felek pes mi etmişti, bilinmez

Ama masallar canlandı yeniden, yeniden başladı bir aşk hikayesi

Her gülüşün, gelişi oldu baharın, açışı kırmızı gülün

Her sözün bir aşk nağmesi, kıskandığı bülbülün

Ferhat oldum ben, sen dağları deldirensin

Şirin’im oldun sen, şiirimsin… 

Çok güzelsin, şi-i-rinsin

Rotterdam,20-06-2003', 'Masallarda duyardım eskiden Bahsederlerdi hep güzeller güzeli bir prensesten  Bazan yeşil olurdu gözleri Bazan da türkuaz, mavi Nedense hep ...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/si-i-rinsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlı Bir Kabiledir Aşk', 'dagli-bir-kabiledir-ask-fadil-ozturk-db9zt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aşk, dört işlemle ifade edilmeyen

görünmeyen rüzgar

bir kum tanesinin hafızasında kalan kaya parçası

düşün bozup bozup kendince kurduğu görüntüler

ve resmi tarih yazıcılarının asla anlayamadığı şeydir aşk

aşk, suda ıslanmaz

kutuplarda eksi altmış derecede bile yakar insanı

babadan oğula devredilecek bir mülkiyet ve iktidar da değildir aşk.

dini, dili, rengi, sınır ve bayrağı, nöbetçi kuleleri yoktur

ama genellikle biri sonunda yaralanır

acil servislerde de kaydına rastlanmaz

erken tanısı yapılamayan

yüreğimizi yurt edinmiş

ve asla düze inmeyen dağlı bir kabiledir aşk

aşk, dünyada dolaşan serseri bir ıslıktır

zamanın arşivinde esrarı çözülmemiş giz

dibe vurmuş mektuplarda solmuş elyazısı

telefonda uzakların ayak izi

defter arasında kurutulmuş gülün ahı

hep sürgün efsanedir aşk

kahramanı dağları deler, kuyulara iner

sevgilinin yokluğunda yağmalanmış kent görüntüsüdür aşk

aşk, dağlara çivi gibi çakılmış

eşkıyanın kendince hayata itirazdır

kaşları çatılırsa çatışma hali

susarsa soğuk savaş, gülerse devrimdir aşk

hindiçin''de giyap anti-emperyalist

anti-faşist ve ispanya iç savaşında anarşist

yunanistan''da teslim olmaktansa 

beynine kurşunu sıkan aris''tki bağlılıktır aşk

aşk, babil kulesinin varlığına duyulan şüphedir

kafkasya''da şeytanın dağlarla aynı torbada yeryüzüne inmesi duaların hayatı temize çekmediğini 

öğrenen tibetlinin tapınağını terketmesidir aşk

dünyanın yedi günde kurulduğunu yazan tevrat''a göre 

iki kişiliktir, üçüncü bir kişinin varlığı 

mısır''ı düşman görmektir israiloğularına göre aşk

aşk, başını buluta koyup uyumak değildir

tedirginlik, şüphe, heyecan, kızgınlık, küskünlüktür

sonsuz bir kahkaha da değildir aşk

içimizde bin yılda bir uyanan

ve uyandığında kıyameti koparan ateşlerin çocuğu devdir

o, gecelerin efendisi

gündüzlerin kanatları ışıktan kuşudur sevgiliye göre

yaratan, ama ihaneti asla bağışlamayan

bir elinde gül, diğerinde rüzgar

kıyamet gününde suyun yüzü

yastığının altında bıçakla uyumaktır aşk', 'aşk, dört işlemle ifade edilmeyen görünmeyen rüzgar bir kum tanesinin hafızasında kalan kaya parçası düşün bozup bozup kendince kurduğu görü...', ARRAY['Türk Edebiyatı','Şiir','Fadıl Öztürk']::text[], 8.5, '{"poet":"Fadıl Öztürk","poet_slug":"fadil-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/dagli-bir-kabiledir-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Bizim Aşkımız', 'bu-bizim-askimiz-salih-ozalasan-t35ne', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni sevmek nasıl bir duygu, anlatsam; 

Bir bulabilsem anlatacak kelimeleri

Duygular öyle iç içe kaynaşmış ki, görebilsen; 

Yüreğimde yeşeren aşk filizlerini

Aşk dedim ya, bu belki aşk değil

Aşktan da öte, yücelerden yüce bir sevgi

Diyeceğim; işte Kerem misali, Aslı misali

Ama değil ki, karşılığı yok; Tanrıyı sever gibi

Bir sürüngenin  kanada mahkum olması

Yaşamaya mahkûm yüreğin atması

Güneş doğduğunda günün ağarması

Velhasıl; bir birine kaynaşmış, yürekle can gibi

İçimde ikinci bir cansın, canıma yoldaş

Bir sevgili, bir dost, vazgeçilmez arkadaş

İstiyorum tüm hayatı, ömrünü benimle paylaş

Ama; bu asla değil, kollarımda ol sarmaş dolaş

Böyle olsa, tenim tenini arzuluyor diyeceğim

Ama değil, arzulayan sadece yüreğim

Belki farklı olacak herşey, 

Yoksa kendimden nefret edeceğim

Öyle zorki be güzelim

Ben bu sevdayı nasıl tarif edeceğim? 

Duygularım kar değil, ama, kardan temiz

Bir bulut değiliz, ama, sevdaya uzanır gölgemiz

Yatağımız ayrı, ama, beraber yaşıyor bedenimiz

Biz, bir bedende iki can gibiyiz

Sen, Alplerin eteklerinde bir can

Ben, volkanik Uludağda kaynayan bir kan

Damarda dolaşan kan, yürekte atan can

Biz bir kâlbe uzanan iki damar gibiyiz

Adını anmasam, düşünmese seni beynim

Yüzünü bilmesem, olmasa da elimde bir resmin

Benim için ilahi bir melek senin cismin

Biz, Ruh güzelliğine aşık iki sevgiliyiz

Ağlıyorum, gözümden akan gözyaşı sensin

Gülüyorum, gönlümdeki tek neşemsin

Canın acısa, hissediyorum; sen bende bir bedensin

Biz, bir kökten yeşeren iki fidan gibiyiz

Y.tar11-01-2002+12-01-2002 saat 12,15+15,30

Salih ÖZALAŞAN', 'Seni sevmek nasıl bir duygu, anlatsam;  Bir bulabilsem anlatacak kelimeleri Duygular öyle iç içe kaynaşmış ki, görebilsen;  Yüreğimde yeşere...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bu-bizim-askimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Severdim', 'severdim-can-ozbey-5iaqp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen benim bahar gülüm

Sen benim ekmeğimsin

Sen benim içtiğim susun...

Sen bahar gör diye kokladığım çiçeğim

Üzüntüm, neşem, hasretimsin', 'Sen benim bahar gülüm Sen benim ekmeğimsin Sen benim içtiğim susun... Sen bahar gör diye kokladığım çiçeğim Üzüntüm, neşem, hasretimsin...', ARRAY['Türk Edebiyatı','Şiir','Can Özbey']::text[], 8.5, '{"poet":"Can Özbey","poet_slug":"can-ozbey","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/severdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
