INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle Beni', 'bekle-beni-derin-oger-22cx8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kim yazdı seni

Gönlümün seyir defterine

Bilendi rüzgarın kopardı ipleri

Çektin alacakaranlığa kürekleri

Sen mi bıçak

Sen mi korkusuz aşık

Dağda tavşan denizde yakamoz kayboluşun

Bende kaldı  tanımadığım yanın

Bende kaldı

Bekle beni yitirdiğim

Dalga darbeleriyle geleceğim

Unutuşunun başlangıcında bekle

Gün ortası mehtabı gömeriz birlikte..........', 'Kim yazdı seni Gönlümün seyir defterine Bilendi rüzgarın kopardı ipleri Çektin alacakaranlığa kürekleri Sen mi bıçak Sen mi korkusuz aşık Da...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bekle-beni-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-sema-gorur-hgj3s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aksam olupta, el ayak çekilince, 

Isiklar yakilipta, perdeler çekilince, 

Sobadan gelen sicaklik içine isleyince, 

Bir baskadir aglamak, gülmek, 

Bir baskadir uzun uzun düsünmek.

Aksam olupta sessizlik inince, 

Yagan yagmur göz yasini silince, 

Annenin sevgisi burnunda tütünce, 

Bir baskadir özlemek, aglamak, 

Bir baskadir hasreti yasamak.', 'Aksam olupta, el ayak çekilince,  Isiklar yakilipta, perdeler çekilince,  Sobadan gelen sicaklik içine isleyince,  Bir baskadir aglamak, gül...', ARRAY['Türk Edebiyatı','Şiir','Sema Görür']::text[], 8.5, '{"poet":"Sema Görür","poet_slug":"sema-gorur","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/annem-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay’a tutuldum', 'ay-a-tutuldum-sema-gorur-qsxjt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sessiz, sâkin bir gecede

Ay’a tutulu verdim.

Önce beni görmezden geldi, 

Gökyüzünde usul usul süzülüverdi.

Sonra aniden bana göz kirpti…

Nazlandim önce, 

Ondan gözlerimi çevirdim, 

Yeryüzüne baktim, 

Ayaklarimi aradim, kanatlanmislar! 

O, hiç bikip usanmadan

Isik tuttu yüregime, zifiri karanliklarda.

Sabirla ayaklarimin yerden kesilmesini bekledi, 

Öylede oldu sonunda, Ay’a tutuluverdim.

Tam o anda, 

O gökyüzünden kaybolu verdi, 

Yerini çiglik çigliga bir yürege birakarak.

Artik bu yürek ne gökte, nede yerde

Yer ile gök arasinda bir yerde! 

Ay’a tutuldum, geceye küstüm, 

Ama ay’a küsmedim, 

Küsemedim!', 'Sessiz, sâkin bir gecede Ay’a tutulu verdim. Önce beni görmezden geldi,  Gökyüzünde usul usul süzülüverdi. Sonra aniden bana göz kirpti… Naz...', ARRAY['Türk Edebiyatı','Şiir','Sema Görür']::text[], 8.5, '{"poet":"Sema Görür","poet_slug":"sema-gorur","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ay-a-tutuldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu spikeri kovdurmalı!', 'bu-spikeri-kovdurmali-sema-gorur-hpnwf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün yine telefonum çalmadı, 

Hatlarda bir sorun olmalı, 

Evet, evet, muhakkak hatlarda sorun var, 

Yoksa sen beni arardın.

Mektubun gelmedi bugün, yine, 

Kesinlikle bu postacının hatâsıdır, 

Evleri şaşırıp başkasına vermiştir

Bana, sadece bana yazmış olduğun

Hasret dolu mektuplarını.

Maillerime baktım bugün, 

Yine senden mail gelmemiş.

Şüphesiz, adresimi yanlış yazıyorsundur, 

Bu yüzden ulaşmiyordur bana

Sevgi dolu sözlerin.

Akşam üstü televizyon kanallarını gezerken, 

Bir paparazzi programında seni gördüm…

Gri takımın sana çok yakışmış, 

Birazda kilo almışsın, 

Gözlerinin içi gülüyordu…

Seni çok iyi gördüm canım, 

Seni mutlu görmek ne güzel! 

Spiker, « yılın düğünü » diyordu …

Acemi spikerin hatâsıdır, şapşal şey! 

Mutlaka senin resmine bakarak

Bir sonraki haberi okudu.

Acemilik işte! …

Sen evlensen, ilk benim haberim olur

Öyle değilmi canim? 

Senin gelinin benim çünkü.

Yok, yok, bu spikeri kovdurmalı!', 'Bugün yine telefonum çalmadı,  Hatlarda bir sorun olmalı,  Evet, evet, muhakkak hatlarda sorun var,  Yoksa sen beni arardın. Mektubun gelmed...', ARRAY['Türk Edebiyatı','Şiir','Sema Görür']::text[], 8.5, '{"poet":"Sema Görür","poet_slug":"sema-gorur","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bu-spikeri-kovdurmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçbirsey sonsuza dek sürmez', 'hicbirsey-sonsuza-dek-surmez-sema-gorur-ip68u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bak, nasilda gece zifiri karanliklara dalmis, 

Derlerki, böyle gecelerde kalp kalbi duyarmis, 

Oysa, göz gözü bile görmüyor…

Bu karanlik damla damla yüreklere akarken, 

Kim derki, birkaç nefes sonra safak sökecek, 

Seher yeli bu karanligi silip süpürecek, 

Gök yüzünden ve yüreklerden…

Günes dogacak yeniden, seller aksada gözlerden.

Hiçbirsey sonsuza dek sürmez, 

Ne gönülde kopan firtinalar, 

Ne agitlar, nede ayazlar.

Sabir…

Sabir en büyük erdemdir

Sabret gönül, sabret hüzün…

Hiçbirsey sonsuza dek sürmez, 

Ne karanliklar, ne ayriliklar, 

Nede umutsuzluklar…

Göz gözü görmesede, 

Kalp kalbi duyar.', 'Bak, nasilda gece zifiri karanliklara dalmis,  Derlerki, böyle gecelerde kalp kalbi duyarmis,  Oysa, göz gözü bile görmüyor… Bu karanlik dam...', ARRAY['Türk Edebiyatı','Şiir','Sema Görür']::text[], 8.5, '{"poet":"Sema Görür","poet_slug":"sema-gorur","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hicbirsey-sonsuza-dek-surmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Itirafimi sustum', 'itirafimi-sustum-sema-gorur-gx19c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öyle bir bosluk ki gözlerimdeki, 

Agla agla dolmaz, 

Gözlerim konussada, 

Karsimdaki gözlerin anlamaz.

Öyle bir isyanki yüregimdeki, 

Haykir haykir dinmez, 

Dilim söylesede, sinemdeki

Sözlerim bitmez.

Öyle bir sevda ki bendeki, 

Sussam olmaz, 

Itiraf etsem, sendeki

Yürek dayanmaz.', 'Öyle bir bosluk ki gözlerimdeki,  Agla agla dolmaz,  Gözlerim konussada,  Karsimdaki gözlerin anlamaz. Öyle bir isyanki yüregimdeki,  Haykir...', ARRAY['Türk Edebiyatı','Şiir','Sema Görür']::text[], 8.5, '{"poet":"Sema Görür","poet_slug":"sema-gorur","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/itirafimi-sustum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soğuk', 'soguk-ahmet-aksoy-0o1wr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gidecek misin

Gitme soğuk

Bir sen kaldın

Yasadığımı hissettirecek

Gitme ne olur

Gitme soğuk

Öldüreceksen öldür beni

Bir sen kaldın

Yaşadığımı hissettirecek

Gitme ne olur

Öldür beni

Gitme soğuk.', 'Gidecek misin Gitme soğuk Bir sen kaldın Yasadığımı hissettirecek Gitme ne olur Gitme soğuk Öldüreceksen öldür beni Bir sen kaldın Yaşadığım...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/soguk-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin', 'senin-i-cin-ahmet-aksoy-cplki', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bak sana ne göstereceğim

Bak beğendin mi

Ne güzel değil mi

Senin için yaptım

Pardon anlamadım

Yine mi göremedin

Bir kez daha bak o zaman 

Bir kez daha göstereyim

Bu sefer iyi bak ama

Diğer yaptıklarım gibi 

Olmasın.', 'Bak sana ne göstereceğim Bak beğendin mi Ne güzel değil mi Senin için yaptım Pardon anlamadım Yine mi göremedin Bir kez daha bak o zaman  Bi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/senin-icin-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmisim, gelecegim: toprak ve anam', 'gecmisim-gelecegim-toprak-ve-anam-sema-gorur-aa3q7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugünler yarinlardin dün’ü degil

Bugünler gelecekte bir an, 

Tozlu ve melankolik bir ani.

Bir tebessüm, bir bakis akillarda kalan…

Belki yagisli bir gün, 

	Belki günesli bir dün

Bir bakis, bir tereddüt

	Kaçivermis yelkovanin ardindan

Birde bir yaprak kalmis enkazin altinda

	O bahardan kalma bir yaprak.

Toprak kokusunu özledim

Hani ayak altina aldigimiz toprak, 

	Bizi var eden, bizi kucaklayan topragin

	Kokusunu özledim.

Tipki ana sütü kadar sicak, 

Ana yüregi gibi kabarik

Topragin kokusunu özledim.

Annemi özledim, 

Beni göz yaslarinda ninniler’le büyüttügü aksamlari özledim

Dertsiz geçmeyen gününü özledim

Bana can veren gözlerine

Bana hayat veren sabrina hasret kaldim.

Simdi o günler bugünlerde bir dün oldu, 

Gözlerimi sulayan bir düs oldu.', 'Bugünler yarinlardin dün’ü degil Bugünler gelecekte bir an,  Tozlu ve melankolik bir ani. Bir tebessüm, bir bakis akillarda kalan… Belki yag...', ARRAY['Türk Edebiyatı','Şiir','Sema Görür']::text[], 8.5, '{"poet":"Sema Görür","poet_slug":"sema-gorur","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gecmisim-gelecegim-toprak-ve-anam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lokomotifini Arayan', 'lokomotifini-arayan-ahmet-aksoy-pbm79', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Lokomotifsiz vagon

Üşüyen vagon

Gidiyorsun karanlıklara

Gidiyorsun durmadan

Kaybettin lokomotifini

Kaybettiniz birbirinizi

Ve sen hala peşindesin

Gitmen gerekene gidebilmen için.', 'Lokomotifsiz vagon Üşüyen vagon Gidiyorsun karanlıklara Gidiyorsun durmadan Kaybettin lokomotifini Kaybettiniz birbirinizi Ve sen hala peşin...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/lokomotifini-arayan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leşçi', 'lesci-ahmet-aksoy-j8oi7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yetmiyor kuzu, yetmiyor

Leşçi mideler doymuyor

İstiyorlar daha fazla.

Leşçi mideler her zaman

Ölülerle besleniyor.

Sen öl o ölsün ben öleyim

Zorla ya da kendiliğinden

Leşçi mideler et istiyor.', 'Yetmiyor kuzu, yetmiyor Leşçi mideler doymuyor İstiyorlar daha fazla. Leşçi mideler her zaman Ölülerle besleniyor. Sen öl o ölsün ben öleyim...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/lesci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşadığımız Fakirlik', 'yasadigimiz-fakirlik-ahmet-aksoy-e2e9a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir fakirlikti yaşadığımız

Bir yoksulluktu

Birbirimizin fakiriydik

Yalnızlığımızdı yoksulluğumuz

Hazineler içindeyken yaşadığımız

Elmas altın hepsini değersiz kıldık

Bir biz kaldık sonunda

Birbirimizden yoksun

Zenginlikleri değerlendiremeyen

Zenginliklerden yoksun

Acınası zavallılar

Birbirimizin fakiri olduk.', 'Bir fakirlikti yaşadığımız Bir yoksulluktu Birbirimizin fakiriydik Yalnızlığımızdı yoksulluğumuz Hazineler içindeyken yaşadığımız Elmas altı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasadigimiz-fakirlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen III', 'sen-iii-ahmet-aksoy-sb6te', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'En ağır makamdaydı

Çalınışın

Notalarda yaşayan 

Bir hüznün

Şarkısıydın.', 'En ağır makamdaydı Çalınışın Notalarda yaşayan  Bir hüznün Şarkısıydın....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sen-iii-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklara', 'uzaklara-ahmet-aksoy-26bdl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben bir asker

Ayrılık ise bir subay

Koşturuyor beni uzaklara

Senden uzaklara

Ben bir askerim

Ona sözüm geçmez 

Ne diyeyim, onu 

Başıma komutan yapan 

Kader utansın.', 'Ben bir asker Ayrılık ise bir subay Koşturuyor beni uzaklara Senden uzaklara Ben bir askerim Ona sözüm geçmez  Ne diyeyim, onu  Başıma komut...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/uzaklara-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Mavi Sevda Masalı', 'bir-mavi-sevda-masali-nuri-can-654je', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir mavi denizdeyiz şimdi seninle 

ak bir martı gibi umut ve sevinç yüklü gemimiz 

mutluluk rüzgarları vuruyor yelkenlerimize 

pupa yelken yol alıyoruz sabaha 

güneşli günlere çıkıyoruz, mavi gecelere 

güzelliklerin el değmemiş ormanlarında 

düşlenmemiş renklerin çılgınlığı düşüyor bakışlarımıza 

kulaklarımıza binlerce kuş sesi dökülüyor 

şiir cıvıltıları üşüşüyor saçlarımıza 

güneşe renk veren renkler ülkesinde

huzur ve sevgi çelenkleri örüyor zaman içimizdeki ışıltılardan 

şiirlerle beslenerek, 

bir çiçek büyüyor tüm zamanların özlem bahçelerinden 

küskün çocuklardan bir çocuk gülümsüyor geleceğe 

seviyoruz bütün insanları, bütün hataları affediyoruz 

şarkılar bizim oluyor, şiirler bizim, yarınlar bizim 

aşkı içiyoruz su gibi yudum yudum, 

hava gibi nefes nefes mutluluğu tadıyoruz tüm pınarlardan 

sevgimizi koyup bütüm sevdaların üstüne 

yelin suyla öpüştüğü kıyılara bırakıyoruz mavi gözyaşlarımızı...

seninle hayaller dolusu mutluluk 

çiçekler dolusu sevgi ekiyoruz güzelliğin doruklarına 

kaldırıp duvağını gökyüzünün her sabah 

öpüyoruz tüm beyaz bulutları alnından birer birer

dudakların gül oluyor, gözlerin yıldız, bakışların ay 

uçuk bir mavide tutsak kalıyor hayallerimiz 

dansediyoruz rüzgarlarla sırılsıklam aşkla 

kanatlanmış atlar geçiyor rüyalarımızdan 

kardan çiçekler, 

sevinçten yıldızlar dökülüyor üstümüze 

maviler boyu martılar uçuruyoruz gökyüzüne.....

bir Adem- Hava faslındayız şimdi seninle 

yeni bir rüya görüyoruz 

yeni bir bahar yeşeriyor tenlerimizde 

bir yanı Mecnun masalımızın bir yanı Leyla 

bir yanı Yusuf, bir yanı Züleyha 

yeni bir aşk masalı yaşıyoruz şarkıların tılsımında 

güneşi, mehtabı, yıldızları içiyoruz tüm pınarlardan... 

dudakların kalplere sığındığı bir adada 

şimdi binbir arzuyla köpürüp kabarıyor dalgalar 

şiir’in yedirenk çakılları vuruyor kıyılarımıza 

gözlerin zeytin dalı oluyor umudu tükenmişlere,

bütün ihanetlerden arı, bütün çirkinliklerden uzak 

yıldızları yol yapıp umutlarımıza 

mavilere tırmanıyoruz ince alımlı ayaklarıyla aşkın 

Nuri CAN

www.nurican.com', 'Bir mavi denizdeyiz şimdi seninle  ak bir martı gibi umut ve sevinç yüklü gemimiz  mutluluk rüzgarları vuruyor yelkenlerimize  pupa yelken y...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/bir-mavi-sevda-masali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Üzerine', 'olum-uzerine-tahsin-kavak-ue0oy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tut ki sana güneş doğmuyor artık 

Cânım sabahlarda umutlar sahipsiz, 

Bir yoksul kişisin 

Sevinçsiz - kedersiz... 

Tut ki göçüp gitmişsin dünyadan 

Denizsiz, ağaçsız, çiçeksiz 

Doğru söyle kardeşim 

Yapabilir misin? ... 

Tut ki öldün 

En kötüsü ölü kardeşim, en kötüsü, 

Anana sövsem 

Kızabilir misin? 

«Halin nice» desem, 

Dudağını büküp, yoksulca, 

Gülebilir misin? ...', 'Tut ki sana güneş doğmuyor artık  Cânım sabahlarda umutlar sahipsiz,  Bir yoksul kişisin  Sevinçsiz - kedersiz...  Tut ki göçüp gitmişsin dü...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/olum-uzerine-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarancı Gibi', 'taranci-gibi-tahsin-kavak-iyxu5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vay anasını! 

Harcadığımız gençlikmiş adım başına 

Eskiden geçerken 

Beni böyle düşündürmezdi bu mezarlık 

Göğün mavisine, 

Yaprağın yeşiline, artık, 

Alıcı gözüyle bakmaya başladık. 

Hani benim güzellişim? 

Neden kırdım kırk yıllık dost aynamı? 

Bir şey daha öğrendim ki -çok acı- 

Bizim evin yolu yokuşmuş meğer 

Vay anasını! ...', 'Vay anasını!  Harcadığımız gençlikmiş adım başına  Eskiden geçerken  Beni böyle düşündürmezdi bu mezarlık  Göğün mavisine,  Yaprağın yeşilin...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/taranci-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümcül', 'olumcul-tahsin-kavak-m12ge', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben de bir gün ölürüm, 

Resmimi bir çerçeveye koyarsınız 

Ve baka baka 

Yokluğuma doyarsınız. 

Çünkü, ben de öyle yaptım. 

Bu iş böyle devam eder, 

Böyle gelmiş, böyle gider.', 'Ben de bir gün ölürüm,  Resmimi bir çerçeveye koyarsınız  Ve baka baka  Yokluğuma doyarsınız.  Çünkü, ben de öyle yaptım.  Bu iş böyle devam...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/olumcul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erişilmezsin', 'erisilmezsin-tahsin-kavak-u6rzq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '- Bilge’ye -

Bana uzak durunca 

Sana erişemedim. 

Biraz yaklaşıverseydin, 

Seni tutabilirdim...', '- Bilge’ye - Bana uzak durunca  Sana erişemedim.  Biraz yaklaşıverseydin,  Seni tutabilirdim......', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/erisilmezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavice', 'mavice-tahsin-kavak-mhgfz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '- MAVİ şiirle başlayan 42 mavi yaprağın anısına -

Mavice konuş bana 

Bir hoş oluyorum 

Mavili satırlar okuyorum, 

Mavili yapraklar çeviriyorum gün boyu 

Sonunda seni buluyorum. 

Mavice konuş bana 

Bir hoş oluyorum 

Maviden söz ettikçe sen, 

Maviye tutuldum ben de 

Mavi yüreğe işler mi? 

S ö y l e... 

Mavice konuş bana 

Bir hoş oluyorum 

Çağrını arıyorum 42 kat yaprak altında 

Ve bu şiirle yollara çıkıyorum. 

Bir de bakıyorum sonra, 

Esirgiyorsun benden bir parça maviyi 

Yırt şiirimi o zaman, yırt, 

Ağlıyorum...', '- MAVİ şiirle başlayan 42 mavi yaprağın anısına - Mavice konuş bana  Bir hoş oluyorum  Mavili satırlar okuyorum,  Mavili yapraklar çeviriyor...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mavice-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavice II.', 'mavice-ii-tahsin-kavak-w7oj9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'A. 

Bozbulanık sevgiler ortasındaydım 

Mavide duruldum. 

Şimdi sana el değmemiş bir sevgi veriyorum, mavi, 

Bir sevgi, hiç dudak değmemiş, 

Dünya görmemiş, 

Uzat, ellerine bırakayım. 

Büyük mutluluklar büyük acılara benzermiş 

Ben mavi mutluluklarda ağlasam, sen susar mısın? 

Senin istediğin gibi döşedim evrenimi 

Haydi, seni mavide bekliyorum, koş desem 

Koşar mısın? ... 

Maviye darılacağımı da nereden çıkardın 

Ne olur korkulu kelimeler sokma aramıza 

Sen darılıyor musun yoksa? 

Ben mavi kattıkça DUAMIZ’a. 

Ben mutlu kişiyim artık 

Tüm acıların beline tekmeyi indirdim 

Mavi bakışlı çocuklardan söz et bana haydi, 

Ben de severim mavi bakışlı çocukları, 

Ben de severim. 

Sen, mavi evrenlerin kızı 

Sen, tut ki peri padişahının küçük kızısın 

Demir asa-demir çarık 

Tez elden sana geliyorum, hazır mısın? 

B. 

Burada azıcık dur! 

Gel karışma şimdi 

Ver bana mavi bakışını bir, 

Al, bu da benim dudak değmemiş sevgim...', 'A.  Bozbulanık sevgiler ortasındaydım  Mavide duruldum.  Şimdi sana el değmemiş bir sevgi veriyorum, mavi,  Bir sevgi, hiç dudak değmemiş,  ...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/mavice-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nostaljik Şiir', 'nostaljik-siir-tahsin-kavak-n6qmq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '- Erdek anılarıyma- 

Şiirlere konu olmuştu denizimiz 

Sevgililer, Sevgi çoğaltıyorken banklarda ha babam 

Öpü sıcaklığımızı katmıştık biz de gecelerine, 

Öyle körpe bir gülüştü güzelliğimiz, 

Kumsalında bıraktığımız ayak tıpırtılarına 

Şimdi istesek de yetişemeyiz... 

Apostol’da içtiğimiz şarabın sevişgenliğini, 

Nasıl taşırdık kuytulara ürpererek. 

Çalı diplerindeki fısıltılarımız aynı yaşta kaldılar da 

Ne geçti elimize bilmem bizim, büyüyerek...', '- Erdek anılarıyma-  Şiirlere konu olmuştu denizimiz  Sevgililer, Sevgi çoğaltıyorken banklarda ha babam  Öpü sıcaklığımızı katmıştık biz de...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/nostaljik-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmirli Bir Müstehcen', 'i-zmirli-bir-mustehcen-tahsin-kavak-m9kig', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sırsıklam delikanlı geçiyoruz İzmir gecelerinden 

Olmazsa siz yağmur yağın, odalar sevişilsin 

Sevişilsin, sevişilsin, şöyle biraz müstehcen 

Şöyle biraz çekingen, en güzel ıslanarak, 

Seni bir sümbül kokusu getiriyor kapıma 

Odamı doldurarak, ama çokça sevişgen 

Evet çokça sevişgen, ama biraz müstehcen. 

Sırsıklam delikanlı geçiyoruz İzmir gecelerinden 

Sultanlığımızı yaşıyoruz en kösnük sevgimizle 

Sevişgen bir duyarlıkta, yani biraz müstehcen 

Söyletmeye katırlaşırsan tutar söylerim 

Söylerim ya zoraki bir istekle, birazcık da çekingen: 

«Sevişmeye en duyarlı yerlerinlen» 

Yani biraz müstehcen... 

Sırsıklam delikanlı geçiyoruz İzmir gecelerinden 

Öpülmeye katırlaşırsan seni öperim 

Ele-avuca gelen yerlerinden, şöyle biraz müstehcen, 

Tutar çok yalın bir şekilde ellerimle öperim. 

Sırsıklam delikanlı geçiyoruz İzmir gecelerinden 

Seni bir sümbül kokusu soyunuyor odama 

Elim en kutsal duyarlığına geberiyor bir meme diriliğinden 

Çok güzel bir müstehcen...', 'Sırsıklam delikanlı geçiyoruz İzmir gecelerinden  Olmazsa siz yağmur yağın, odalar sevişilsin  Sevişilsin, sevişilsin, şöyle biraz müstehcen...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/izmirli-bir-mustehcen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarap Mirella', 'sarap-mirella-tahsin-kavak-jcg4c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben meyhaneye gidersem geceleri 

Şarap Mirella için giderim 

Şarap Mirella gözyaşıdır 

Şarap Mirella teselli 

Şarap Mirella: 

Son damlasına kadar içtiğim 

Kadehimdeki...', 'Ben meyhaneye gidersem geceleri  Şarap Mirella için giderim  Şarap Mirella gözyaşıdır  Şarap Mirella teselli  Şarap Mirella:  Son damlasına ...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sarap-mirella-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Mirella', 'ask-mirella-tahsin-kavak-1v758', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir Mirella çıktı ağzımdan 

Şiir oldu. 

Aşk Mirella 

Dert Mirella 

Mirella başbelâm oldu...', 'Bir Mirella çıktı ağzımdan  Şiir oldu.  Aşk Mirella  Dert Mirella  Mirella başbelâm oldu......', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ask-mirella-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mirella’dan Bana Kalan', 'mirella-dan-bana-kalan-tahsin-kavak-lidgj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cümle acıları tattım, eyvallah, 

Kadere sövgülerim erkekçe oldu 

Gel gelelim bu, 

Bu bir başka türlü 

Ölüm kadar acı, ölüm kadar gerçek 

Bu, ağlamadan söyleyemediğim türkü. 

Bu, beni meyhanelere düşüren acı 

Bir başka türlü, berbat... 

Bu, bir istasyonun tenha köşesinde 

Dudağıma bırakılan öldürücü tad. 

Bu, şimdi birinin 

Şarap tası başında Mirella’yı düşünüşü 

Bir trenin götürdüğü mutluluk 

Ve içmeden söylenmeyen bir türkü. 

Bu, bozulmasını beklediğim korkunç bir büyü.', 'Cümle acıları tattım, eyvallah,  Kadere sövgülerim erkekçe oldu  Gel gelelim bu,  Bu bir başka türlü  Ölüm kadar acı, ölüm kadar gerçek  Bu,...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mirella-dan-bana-kalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavak Yelleri', 'kavak-yelleri-tahsin-kavak-yjbp2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Köşedeki elektrik direğinin altında durdum ilkten, 

Başımda kavak yelleri, 

Gölgem ayaklarımın dibine sinmiş. 

Dayandım direğe 

Kaldırımdaki su birikintilerine 

Yıldız serptim. 

Sonra paşa gönlüm sıkılmış da 

Bir hava tutturmuş ıslıkla 

Peşi sıra düşüncelerim, 

Dertlerim Z sine kadar bitmiş. 

Dudağımda ıslık 

Düşüncelerimi de ardına takıştırmışım, 

Düşüncelerim işin keyfinde...', 'Köşedeki elektrik direğinin altında durdum ilkten,  Başımda kavak yelleri,  Gölgem ayaklarımın dibine sinmiş.  Dayandım direğe  Kaldırımdaki...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kavak-yelleri-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paşabayırı’ndan Bakış', 'pasabayiri-ndan-bakis-tahsin-kavak-t8dqf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-Gençliğimin Bandırma’sına yazılmıştı, şimdi ne Yanan Şube, ne merdivenleri kaldı.-

Paşabayırı’na canın istediği an çıkabilirsin 

Mendil sermeden oturmalısın çimenlerin üzerine 

Ama sen, 

Yanan şubenin merdivenlerine oturmak istemişsin, 

Oturabilirsin. 

Aşağı İstasyon’a bir bakarsın, kuşbakışı, 

Bir tren düdüğü, bir istim 

Bir büyür medeniyet gözünde 

Büyür gücün. 

Bir gider-bir gelir vagonlar 

Beyaz maden, siyah maden dolu 

Sarı-sarı ekinlerin yanı sıra bir servet, 

Gururun büyür. 

Limana demir atar bir ecnebi gemisi 

Zincir şakırtısını balıklara şarkı yaparsın kafanda 

Geminin yanında bir kayık görürsün 

- İçindeki Balıkçı şevket’tir - 

«Kaptanyooo» diye bağırttır Şevket’i gemiye 

Hikâyeni devam ettir. 

Bir bakarsın İzmir Ekspresi gelir 

İnsan kardeşlerin kompartımanlarda cıvıl cıvıl 

Allı - yeşilli giyinmişler 

İyi - kötü günler görmüıler. 

Hayırlı yolculuklar dile içinden istersen 

İstersen gittikleri yeri aklına getir 

İster mendil salla bir kıza, 

Ayıp değil. 

Paşabayırı’na canın istediği an çıkabilirsin 

Mendil sermeden oturmalısın çimenlerin üzerine 

Ama sen, 

Yanan şubenin merdivenlerine oturmak istemişsin, 

Oturabilirsin...', '-Gençliğimin Bandırma’sına yazılmıştı, şimdi ne Yanan Şube, ne merdivenleri kaldı.- Paşabayırı’na canın istediği an çıkabilirsin  Mendil ser...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/pasabayiri-ndan-bakis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çirkinçavuşköylüm', 'cirkincavuskoylum-tahsin-kavak-6vad9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '- Güzel köyümün güzel insanlarına -

Ben, Çirkinçavuşköylü 

Hacı Ahmet oğlu Tahsin Kavak; 

Hemşehrinim senin 

Bir evleği de benimdir. 

Kertil’deki ekinin. 

Sağdıçlarım vardı bir çok 

Unuttular mı? 

Yavuklum vardı beşikten 

Beni sorar mı? 

Tepede bir ahlat ağacı vardır, bilirsin, 

Her dalında bir yaramazlık bıraktım 

Geçerken bir bakıver 

Uslandılar mı? 

Çirkinçavuşköyü’nde bir tepe vardır, siz bilmezsiniz, 

Bir yamacı Kocadere’ye iner, 

Bir yamacına evler tırmanmış soluklanır 

Soluklar, saadete yönelmiş umutlarda dinlenir 

Her sancılı gecenin sabahında 

Bir gayret filizlenir. 

Hazırla gücünü hemşehrim 

Elbet hakkını verecek toprak 

Terindeki hakka inan. 

Toprağa düşen yağmur 

Bereketi düşünür bak, 

Hani gücün? Davran! . 

Senindir gayri kucakla şafakları 

Sabahlar kendiliğinden durulur 

Tepedeki ahlat ağacının altına otur da hemşehrim 

Bir türkü tuttur Bandırma’ya uzansın 

O beni bulur...', '- Güzel köyümün güzel insanlarına - Ben, Çirkinçavuşköylü  Hacı Ahmet oğlu Tahsin Kavak;  Hemşehrinim senin  Bir evleği de benimdir.  Kertil...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/cirkincavuskoylum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ata’mın Ölmezliği', 'ata-min-olmezligi-tahsin-kavak-5domh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sızı içimizde 

«Edirne’den Ardahan’a kadar» 

Susmuş Türkiye’m, içine yönelmiş 

Ata’sıyla baş başa 

Ata’sız... 

Bir vatan bıraktın Ata’m, yeşertip, 

Şimdi boy verdi yeşilliklerin 

Sevincimiz sonsuz 

Bir vatan yükseltiyoruz adına anıt 

Ne çare tam tadı yok sevincin 

Ata’siz... 

Bir sızı kalplerimizde 

«Ardahan’dan Edirne’ye kadar» 

Arkandan ağlayanın 

Ağlıyoruz ama, 

Ölmezliğine öyle inandik ki bir taraftan 

Tanrı’ya yakın...', 'Bir sızı içimizde  «Edirne’den Ardahan’a kadar»  Susmuş Türkiye’m, içine yönelmiş  Ata’sıyla baş başa  Ata’sız...  Bir vatan bıraktın Ata’m,...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ata-min-olmezligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bak Gözlerime', 'sen-bak-gozlerime-derin-oger-vm3yl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kurtlar uyusun

Kuşlar uyusun

Kâinat uyusun

Bir sen bak 

Gözlerimin içine

Hüznümün öz tarlası

Sessizliğin huzurlu çayırı

Yar gözlerime düşür 

Çıplak bakışlarını

Senindir arzuları

Senindir görkemi hazzı

Büyülenmişcesine

Bir sen bak 

Gözlerimin içine............', 'Kurtlar uyusun Kuşlar uyusun Kâinat uyusun Bir sen bak  Gözlerimin içine Hüznümün öz tarlası Sessizliğin huzurlu çayırı Yar gözlerime düşür ...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-bak-gozlerime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sünnet', 'sunnet-tahsin-kavak-4zcnj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '- Yeğenim EFE SEVERCAN’a -

Telâşeli gibisin biraz, neş’elisin hem, 

Hem korkuyor gibisin, biraz endişeli hem, 

Ey sünnetçi güzel kes, küçülmesin büyüsün, 

İyi günlerde, güle güle kullansın Efe’m.', '- Yeğenim EFE SEVERCAN’a - Telâşeli gibisin biraz, neş’elisin hem,  Hem korkuyor gibisin, biraz endişeli hem,  Ey sünnetçi güzel kes, küçülm...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sunnet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılış', 'ayrilis-tahsin-kavak-sd9g0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geçti nice yılların acı-tatlı günleri 

Öldürdü bülbülleri güllerin dikenleri 

Öyle bir yaman esti 1981 

Savruldu rüzgârında aşkımızın külleri.', 'Geçti nice yılların acı-tatlı günleri  Öldürdü bülbülleri güllerin dikenleri  Öyle bir yaman esti 1981  Savruldu rüzgârında aşkımızın küller...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ayrilis-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezartaşına I.', 'mezartasina-i-tahsin-kavak-hd8p8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalbimizdeki nûrun o ilk güneşi burda 

Hasret dolu yılların yanan ateşi burda 

Rabbimin bahşettiği o iki melek insan 

İlknur’uyla beraber Nermin yatıyor burda.', 'Kalbimizdeki nûrun o ilk güneşi burda  Hasret dolu yılların yanan ateşi burda  Rabbimin bahşettiği o iki melek insan  İlknur’uyla beraber Ne...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mezartasina-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezartaşına II.', 'mezartasina-ii-tahsin-kavak-pfw8e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir trafik kazasında aldı ecel İlknur’u 

Kanser oldu annesi, söndü bütün sürûru 

Izdırapla yaşadı, hasretten öldü Nermin 

Bu kabirde yatıyor, kucağında yavrusu.', 'Bir trafik kazasında aldı ecel İlknur’u  Kanser oldu annesi, söndü bütün sürûru  Izdırapla yaşadı, hasretten öldü Nermin  Bu kabirde yatıyor...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mezartasina-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sır', 'sir-tahsin-kavak-5hbas', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güzelliğin ziyneyi, kötünün tıyneti ne? 

İyinin okşayışı, zalimin şiddeti ne? 

Çözmek için bu sırrı bir ömür yetmez Tanrım 

Var olmanın hikmeti, yokluğun zulmeti ne?', 'Güzelliğin ziyneyi, kötünün tıyneti ne?  İyinin okşayışı, zalimin şiddeti ne?  Çözmek için bu sırrı bir ömür yetmez Tanrım  Var olmanın hikm...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sir-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilekçe I.', 'dilekce-i-tahsin-kavak-h036o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnanç ver bize, sana inandık diyelim 

Sabır ver, acılara katlandık diyelim 

Sonunda bize öyle bir mutluluk ver ki, 

Mutluluktan bıktık ve usandık diyelim.', 'İnanç ver bize, sana inandık diyelim  Sabır ver, acılara katlandık diyelim  Sonunda bize öyle bir mutluluk ver ki,  Mutluluktan bıktık ve us...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dilekce-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şans', 'sans-tahsin-kavak-li7o1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bahtımıza zamanı kurduk bir saat gibi 

Ömrümüzde mutluluk sanki bir vaat gibi 

Yıllar boyu bekleriz talihin gülmesini 

Sıladaki cananla bir fasıl vuslat gibi.', 'Bahtımıza zamanı kurduk bir saat gibi  Ömrümüzde mutluluk sanki bir vaat gibi  Yıllar boyu bekleriz talihin gülmesini  Sıladaki cananla bir ...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sans-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bademlik’de Akşam', 'bademlik-de-aksam-tahsin-kavak-j9nr8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '- Eskişehir akşamlarına - 

Bu bahçeye bir gel de açan gülleri gör 

Kalbine diken batyran bülbülleri gör 

Bir yaz akşamında otur da Bademlik’de 

Leyla’ları, Aslı’ları, Şirin’leri gör.', '- Eskişehir akşamlarına -  Bu bahçeye bir gel de açan gülleri gör  Kalbine diken batyran bülbülleri gör  Bir yaz akşamında otur da Bademlik’...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bademlik-de-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatar Güzeli', 'tatar-guzeli-tahsin-kavak-474tb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kız senin insafının hiç ölçüsü yok mu? 

Sakınarak fırlattığın o bakış bize çok mu? 

Sen, ey! Bademlik’deki Tatar güzeli kız 

Senin kaşların yay da kirpiklerin ok mu?', 'Kız senin insafının hiç ölçüsü yok mu?  Sakınarak fırlattığın o bakış bize çok mu?  Sen, ey! Bademlik’deki Tatar güzeli kız  Senin kaşların ...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tatar-guzeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilekçe II.', 'dilekce-ii-tahsin-kavak-cwpjf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeter, artık kahrından usandık diyelim 

Bıktık ve bir isyanla donandık diyelim 

Bir mutluluk kapısı aç da bize şimdi, 

Bu isyan için senden utandık diyelim.', 'Yeter, artık kahrından usandık diyelim  Bıktık ve bir isyanla donandık diyelim  Bir mutluluk kapısı aç da bize şimdi,  Bu isyan için senden ...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dilekce-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öp I.', 'op-i-tahsin-kavak-b3e5t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönlünün bahçesinde gülü öp, lâleyi öp 

Yapraktaki şebnemi, daldaki çiçeği öp 

Yüzündeki gülüşle öpüş vadediyorsa 

Hiç durma düş peşine, tenhada tazeyi öp.', 'Gönlünün bahçesinde gülü öp, lâleyi öp  Yapraktaki şebnemi, daldaki çiçeği öp  Yüzündeki gülüşle öpüş vadediyorsa  Hiç durma düş peşine, ten...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/op-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nikah Töreni', 'nikah-toreni-tahsin-kavak-yiea0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '- Sevgili eşim Türkan’a - 

Yepyeni bir ülkeye ulaşmış gibiyim, 

Sevda sarmaşığına dolaşmış gibiyim, 

Sanki kırk yıl peşinden koşmuş ve aramış 

Ve bu aşk ayininde sana tapmış gibiyim.', '- Sevgili eşim Türkan’a -  Yepyeni bir ülkeye ulaşmış gibiyim,  Sevda sarmaşığına dolaşmış gibiyim,  Sanki kırk yıl peşinden koşmuş ve aramı...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/nikah-toreni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gebe', 'gebe-tahsin-kavak-vj2k8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '- Sevgili Karıma - 

Sanmıştın ki dünyanızı sardı kahırlar, 

Oysa sevginin içinde mutluluklar var 

Mutluluklar doğumlarla çoğalır Türkan, 

Mutlu doğumlar sana ve güzel yavrular.', '- Sevgili Karıma -  Sanmıştın ki dünyanızı sardı kahırlar,  Oysa sevginin içinde mutluluklar var  Mutluluklar doğumlarla çoğalır Türkan,  Mu...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gebe-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Ver', 'geri-ver-tahsin-kavak-foi1f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '- Aziz ölülerime - 

İkbali şuna, istikbali bunlara ver 

Zenginliği Harun’lara - Karun’lara ver 

Bana, ya benden aldığın canları, yahut 

Beni de bu alemden alıp onlara ver.', '- Aziz ölülerime -  İkbali şuna, istikbali bunlara ver  Zenginliği Harun’lara - Karun’lara ver  Bana, ya benden aldığın canları, yahut  Beni...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/geri-ver-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gamze', 'gamze-tahsin-kavak-zgc8c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '- Sevgili Kızım Gamze’ye - 

Doğmak meçhul bir yolun başlangıcı Gamze, 

Sevmek bu yolculukta hoş bir sızı Gamze, 

Ömrünce mutlu yaşa; sev, sevil, gül; olsun 

Adın, yüzündeki gülüşün adı: GAMZE... 

                                16/Kasım/1984-KONYA', '- Sevgili Kızım Gamze’ye -  Doğmak meçhul bir yolun başlangıcı Gamze,  Sevmek bu yolculukta hoş bir sızı Gamze,  Ömrünce mutlu yaşa; sev, se...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gamze-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Şarkı', 'son-sarki-tahsin-kavak-1gnb9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '- Dostum Udî Ahmet Fersal’ın aziz ruhuna. - 

Doğdun, yaşamayı bir büyük nimet bildin 

Sevdin, gönül denilen cennetlere girdin 

Hoş bir sedaymış baki kalan boş kubbede 

Ud’unla boş kubbeye hoş sedalar verdin.', '- Dostum Udî Ahmet Fersal’ın aziz ruhuna. -  Doğdun, yaşamayı bir büyük nimet bildin  Sevdin, gönül denilen cennetlere girdin  Hoş bir seday...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/son-sarki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vekil', 'vekil-tahsin-kavak-brj27', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '- 46 yaşında ölen Sevgili Eniştem H. Ertan Severcan’ın aziz ruhuna. - 

Takdir-i ilâhinin hazin bir misali ol, 

Cennette hurileri güldürüp teselli ol, 

İlâhi adalette, hak arama gününde; 

Genç yaşta ölenlerin, huzurda vekili ol.', '- 46 yaşında ölen Sevgili Eniştem H. Ertan Severcan’ın aziz ruhuna. -  Takdir-i ilâhinin hazin bir misali ol,  Cennette hurileri güldürüp te...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/vekil-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Habersiz', 'habersiz-tahsin-kavak-6ll4s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '- Mezar taşıma - 

Doğduk, ölüm denilen gerçekten habersiz, 

Sevdik, deliler gibi, nefretten habersiz 

Düşmanlığı, kavgayı ve korkuyu öğrendik, 

Bir cehennem yaşadık, cennetten habersiz.', '- Mezar taşıma -  Doğduk, ölüm denilen gerçekten habersiz,  Sevdik, deliler gibi, nefretten habersiz  Düşmanlığı, kavgayı ve korkuyu öğrendi...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/habersiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öp II.', 'op-ii-tahsin-kavak-tu967', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgili işvesinde sözü öp, sohbeti öp 

Dudağından heceyi, gözlerden cilveyi öp 

Şakrak kahkahalaryn döküldüğü pınardan 

Sunulan o buseyi, yanaktan Gamze’yi öp.', 'Sevgili işvesinde sözü öp, sohbeti öp  Dudağından heceyi, gözlerden cilveyi öp  Şakrak kahkahalaryn döküldüğü pınardan  Sunulan o buseyi, ya...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/op-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülberk’e', 'gulberk-e-tahsin-kavak-lrfxu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gül çiçeğisin, gül ki yakışsın sana gülmek 

Gülberk, doruğunda gül açmış gül dağı demek. 

Gül kokusu sinmiş de pembe yanaklarına; 

Ondan bir hoş oluyor, gül yanağından öpmek. 

                            Konya,3.4.1989', 'Gül çiçeğisin, gül ki yakışsın sana gülmek  Gülberk, doruğunda gül açmış gül dağı demek.  Gül kokusu sinmiş de pembe yanaklarına;  Ondan bir...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gulberk-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kastamonu Kalesi', 'kastamonu-kalesi-tahsin-kavak-afrmo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '- Bizanslı dilber Moni’nin anısına - 

Yaşatır hâlâ bin yıllık efsanesini, 

Surlarda fısıldanan aşk hikâyesini. 

Burçlarında her gece bir hayal inler ve 

Bir çığlık parçalanır: «Kastin neydi Moni? »', '- Bizanslı dilber Moni’nin anısına -  Yaşatır hâlâ bin yıllık efsanesini,  Surlarda fısıldanan aşk hikâyesini.  Burçlarında her gece bir hay...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kastamonu-kalesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen', 'bazen-ugur-arslan-hgavj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazen çıkardım

Fenerden

Hiç... Öylesine

Önce kalbime

Sonra ayaklarıma

Bırakırdım

Gideceğim yerin seçimini

Ve bir kaç saat sonra

Ulaştığım yer hep aynı olurdu

Eski cumbalı ahşap evlerin bulunduğu

Kesme kaya caddeli dar sokaklar

Çocukluğum gelirdi buralarda aklıma

Belki ondandı

Önlüğüm

Hiçbir zaman bembeyaz

Ve ütülü kalamayan yakalığım

Kendimden ağır okul çantamla

Çıktığım yokuşları, çıkmaz sokakları

Dolaşırdım

Bazen

Her pazartesi sabahı

Ve cuma günleri esas duruş

Avaz avaz çınlardı kulaklarımda

Türküm, Doğruyum, Çalışkanım...

Sonra

Okul çıkışı simitçiler

Macun ve pamuk helva fasılları

İki buçuk liraya iki gofret

Ve bir gazoz içtiğim günler

Ve top oynadığımız

Çöplük bozması arka bahçe

Çocuk olmak güzeldi

Çocukluğunu yaşayabildiğin sürece...

Çocuklar görürdüm

Kendi küçüklüğüme benzeyen

Sokak aralarında

uzaktan izlerdim

Ve izlerken çocuk olurdum

İster istemez

Eskiden daha mı güzeldi herşey

Yoksa çocuk olduğumuz için mi öyleydi.

Ama birşeyler eksikti

Belki de

Eski renkler', 'Bazen çıkardım Fenerden Hiç... Öylesine Önce kalbime Sonra ayaklarıma Bırakırdım Gideceğim yerin seçimini Ve bir kaç saat sonra Ulaştığım ye...', ARRAY['Türk Edebiyatı','Şiir','Uğur Arslan']::text[], 8.5, '{"poet":"Uğur Arslan","poet_slug":"ugur-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/bazen-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satılık Aşk', 'satilik-ask-ugur-arslan-yw4xo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Deniz gözleri

Ebrulu bakışlı

Sevdayı kendine esir eden

Omuzu şallı kız.

Söyle! Aşkını kaça sattın? 

Kaç kere görücüye çıktı

Uzun saçların

Kaç pazarlığa teslim oldun

Söyle

Kaç kere gerçekten aşık oldun

Zaten herşey para olmuş

Ve para pul

Bir de sen aşkı satsan ne yazar.

Çünkü para

En kral delikanlıyı bile bozar', 'Deniz gözleri Ebrulu bakışlı Sevdayı kendine esir eden Omuzu şallı kız. Söyle! Aşkını kaça sattın?  Kaç kere görücüye çıktı Uzun saçların Ka...', ARRAY['Türk Edebiyatı','Şiir','Uğur Arslan']::text[], 8.5, '{"poet":"Uğur Arslan","poet_slug":"ugur-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/satilik-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-guven-aktas-ba5l9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hakk karsıma seni cıkardı sandım, 

Artık sönecek dedim içimdeki yandın, 

Lakin olmadı sana bir kere sarılamadım

Ellerini bir kere olsun tutamadım.

Aslında seni cok sevmistim, 

Canımı bile yoluna sermiştim

Aklıma adını cıkmayacak gibi kazımıstım

Rüyalarımda görmüstüm sana kavusacaktım.

Günler gecmiyor artık yoksun ya

Üzülmek neye yarar ki

Vakti geldi bir sevgili buldum sanmıstım, 

Ellerimi yine tek tutan yanlızlıgım

Ne ye yarar ki sen yoksun ya, 

Aklımdan cıkartıp atamıyorum 

Kalbimi söksem yerinden acaba unuturmuyum

Tek tesellim seni uzaktanda görüyorum

Artık sensiz yasamak neye yarar ki

Şansım yokmuş mutlu olamıyorum.', 'Hakk karsıma seni cıkardı sandım,  Artık sönecek dedim içimdeki yandın,  Lakin olmadı sana bir kere sarılamadım Ellerini bir kere olsun tuta...', ARRAY['Türk Edebiyatı','Şiir','Güven Aktaş']::text[], 8.5, '{"poet":"Güven Aktaş","poet_slug":"guven-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/biz-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Yanıyor Canım', 'canim-yaniyor-canim-murat-demir-w0620', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Canım yanıyor canım

İnanın çok derinden

Sanki, deli yüreğim

Çıkacaktır yerinden

Göz yaşıma bakmadan

Onu benden aldılar

Kime ne yapmıştımki

Canımdan ayırdılar

Onun ayrılığına

Nasıl dayanacağım

Alevim sönmeyecek

Hep böyle yanacağım

Düşünürüm durmadan

Onu hayal ederken

Nasıl gülerim artık

Ben bu derdi çekerken

Ömrümün baharında

Sevmekten suçladılar

Sevene revamıki

Beni yağmaladılar

Kaderin cilvesimi

Bize bu yapılanlar

İki can bir bedenle

Ne yapar ayrılanlar

Bunu böyle bilsinler

Umudum tükenmedi

Ne derseler desinler

Bu aşk henüz bitmedi', 'Canım yanıyor canım İnanın çok derinden Sanki, deli yüreğim Çıkacaktır yerinden Göz yaşıma bakmadan Onu benden aldılar Kime ne yapmıştımki C...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/canim-yaniyor-canim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Hatırla', 'beni-hatirla-sedat-sakabey-baysal-qwukl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayatın, 

Coşkulu demleri geçipte birgün

Sadece mazide kalınca güzelliğin

Hatıraların sisli tayfına bakıp

Hiç sönmeyen bir ışık görürsen

Beni hatırla.

Bir gün, 

Herkese cömertçe sunduğun kahkahaların

Çıkmaz olurda kesilirse sesin

Hiç bir güzelliğim olmadan yok mu sevenim? 

Diye bir garip duyguya kapılırsan

Beni hatırla.

Elden ele gezdirirp sunduğun mutluluğun

Meclisleri şen kahkahalara boğduğun

Her bahar bir başka güle konduğun

Neşeli günlerin bittiği yerde

Beni Hatırla

Ben o bıraktığın küçücük yerde

Nefesini tutmuş belki gelir de

Tekrar değermi ki ellerim ellerine? 

Diye umutsuz

Bekliyor olacağım.

Nereden nasıl ve neden? 

Geldiğini sormadan sana

Alıp başını ellerimin arasına

Bağrıma koyacağım.

O an son nefesimi verirsem eğer

Üzülme bir tanaem

Gerçekten değer.

Sadece kalan günlerde her gün

Uykuya varmadan kara gözlerin

Bir nefeslik dur da

Beni hatırla.

13.08.03 Ankara', 'Hayatın,  Coşkulu demleri geçipte birgün Sadece mazide kalınca güzelliğin Hatıraların sisli tayfına bakıp Hiç sönmeyen bir ışık görürsen Ben...', ARRAY['Türk Edebiyatı','Şiir','Sedat Sakabey Baysal']::text[], 8.5, '{"poet":"Sedat Sakabey Baysal","poet_slug":"sedat-sakabey-baysal","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/beni-hatirla-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklar', 'cocuklar-zeren-cangert-ia1ig', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mihveri arz olmuş paramparça

Sağır kulaklar, kör gözler

Dışarda çocuklar üşüyor

Gizlenmişler gecenin karanlıklarına

Hayatın Savurduğu, 

Küçük yürekler.

Örtün üstlerini ne olur titremesinler.', 'Mihveri arz olmuş paramparça Sağır kulaklar, kör gözler Dışarda çocuklar üşüyor Gizlenmişler gecenin karanlıklarına Hayatın Savurduğu,  Küçü...', ARRAY['Türk Edebiyatı','Şiir','Zeren Cangert']::text[], 8.5, '{"poet":"Zeren Cangert","poet_slug":"zeren-cangert","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cocuklar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tiryaki', 'tiryaki-sedat-sakabey-baysal-m9um7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben Zaten Seni Unutmak İçin Sevdim.

Unutmanın, Unutulmanın Da Bir Tadı Vardır.

Sadece Unutulanlar Tekrar Hatırlanır.

Sadece Hatıralarda Kalanlar Tekrar Yaşanır.

Seni İlk Gördüğümde Ben, 

Acemi, Toy Bir Delikanlıydım.

Kalbim Göğüs Kafesimi Zorlayan Bir Kuş Gibi, 

Elim Ayağım Dolaşmış Heyecanlıydım.

Seni Görünce Zaten, 

Yüzüm Kızarırdı.

Damarlarımdan Kan Çekilir, 

Ciğerlerime Çivi Çakılırdı.

Sigarayı İlk Çektiğimde De Öyle, 

Ayaklarım Yerden Kesilmişti.

Gözlerim Bulanıp, Başım Dönerken, 

Her Yanım Bir Başka Titremişti.

Artık Ben Bir Tiryakiyim Güzelim.

Dilimde Nağmeleri O Gazelin, 

Bak Nasıl Da Tüttürüyorum Dumanını, 

Hatırlayıp Mazimin Toy Zamanını.

                                                                    15.03.2001', 'Ben Zaten Seni Unutmak İçin Sevdim. Unutmanın, Unutulmanın Da Bir Tadı Vardır. Sadece Unutulanlar Tekrar Hatırlanır. Sadece Hatıralarda Kala...', ARRAY['Türk Edebiyatı','Şiir','Sedat Sakabey Baysal']::text[], 8.5, '{"poet":"Sedat Sakabey Baysal","poet_slug":"sedat-sakabey-baysal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tiryaki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Ateşi', 'ayrilik-atesi-murat-demir-pxt2p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İlk aşkım ilk sevdamdan

Sebepsiz ayırmayın

Onun ile çalışan

Yüreğimi yarmayın

Mutlu olmaktan başka

Ne yapmıştık biz size

Olmazlarla boğarak

Kıymayın ikimize

Hayır değişinize

Anlam veremiyorum

Bir an bile unutup

Onsuz olamıyorum

Ben ergin bir insanım

Karar benim olmalı

Sizin kararınızla

Yüreğim yanmamalı

Ben düşersem çekerim

Size sitemim olmaz

Ben dikersem bağıma

Bakarım gülüm solmaz

Başkasıyle olamam

Beni hiç zorlamayın

Ayrılık ateşine

Gelin beni atmayın', 'İlk aşkım ilk sevdamdan Sebepsiz ayırmayın Onun ile çalışan Yüreğimi yarmayın Mutlu olmaktan başka Ne yapmıştık biz size Olmazlarla boğarak ...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ayrilik-atesi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yokken', 'sen-yokken-zeren-cangert-8pk65', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yokluğunda çok şey değişti

Kuşlar penceremize konmuyor artık

Sen ekmek atardın.

Kapımızı sütçü bile çalmıyor

Sütlaç yapardın.

Mahalledeki esnafla aram git gide soğuyor, 

Eve bir şey almıyorum.

Karnımı ekmek ve suyla doyuruyorum.

Çiçekler kurumuşlar, 

Ellerim kırılasıca, su vermeye üşendim

Eve  gazetede  almıyorum.

Merak etme bol bol kitap okuyorum.

Elektrikleri kapatıp, 

Mum ışığında şiirler yazıyorum.

Hicaz şarkılar dinliyorum.

Gel artık sevinç denizim.

Biliyorum bunu sana çok az söylüyorum ama

Seni çok seviyorum.', 'Yokluğunda çok şey değişti Kuşlar penceremize konmuyor artık Sen ekmek atardın. Kapımızı sütçü bile çalmıyor Sütlaç yapardın. Mahalledeki es...', ARRAY['Türk Edebiyatı','Şiir','Zeren Cangert']::text[], 8.5, '{"poet":"Zeren Cangert","poet_slug":"zeren-cangert","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-yokken-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlıklar 1', 'yalnizliklar-1-zeren-cangert-fglko', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yürümekteyim ıssız yollarda, yüreğimin beni götürdüğü yerdeyim. 

Sağ yanımda burçak tarlası sol yanım alabildiğine Ak Deniz. 

Kısık Gözlerim kapandı kapanacaklar. 

Sanki gözlerimi bir açsam hepsi kaybolacaklar. 

Ceplerimde deniz kumu avuçlarımla sımsıkı sıkıyorum, 

Ellerim kanıyor yüreğim gibi. 

Bir rüzgar gönderiyor deniz, saçlarımı yalayıp geçiyor. 

Burçak tarlasında güvercinler homurdanıyor. 

Bir korkuluk kadar yalnız ve hareketsizim. 

Kuşlar konmakta omuzlarıma, ah beni tutup kaldırsalar havada savursalar. 

Fakat onlar bile bi haber benden. 

İçlerinde ürperti bile yok titremelerini hissetmiyorum. 

Oysa benim yüreğim üşüyor avazım çıktığı kadar sessiz, 

kan ter içinde durgunum. 

Sağ yanımdaki mavilikler elbet ısıtacaklar yüreğimi. 

Ceplerim de avuçlarımdaki kumu denize savuruyorum ait oldukları yere, biliyorum bana dönecekler. 

Sen gelmesen de saçları kumlu kız omuz uma konan kuşlar haberini getirecekler.', 'Yürümekteyim ıssız yollarda, yüreğimin beni götürdüğü yerdeyim.  Sağ yanımda burçak tarlası sol yanım alabildiğine Ak Deniz.  Kısık Gözlerim...', ARRAY['Türk Edebiyatı','Şiir','Zeren Cangert']::text[], 8.5, '{"poet":"Zeren Cangert","poet_slug":"zeren-cangert","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yalnizliklar-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünsen Fena Olmaz', 'dusunsen-fena-olmaz-murat-demir-bds2u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Büyük lafını düşün

Henüz yaşın küçüktür

Kapılma aşk seline

Aşkın seli büyüktür

Pembe gözlük taktırır

Yakar anlayamazsın

Sonra aptallaştırır

Farkına varamazsın

Seveceğin birini

Belki yine bulursun

Aşkta hataya düşme

Kahreder kudurursun

Hele bir düşünsene

Aşktan sonra neler var

Ağır şartlar altında

Ağlayacak çocuklar

Bakıpta geçmişine

Güleceksin belkide

Acele evliliğin

Kalmayacak zevkide

Sevda bir kelimedir

Samanlık seyran değil

Çoluk çocuk bir koca

Her zaman bayram değil

Aç mideyle aşk olmaz

Kavga gürültü olur

Geçmişi hatırlayıp

Sevenlerde kahrolur

Mutfakta buzdolabı

Mideye benzer  bilki

Boşalanın yerine

Yenisi gelmez belki

Bunlar kesin değildir

Olabilir diyorum

Düşünmek gerek diye

Bunları söylüyorum', 'Büyük lafını düşün Henüz yaşın küçüktür Kapılma aşk seline Aşkın seli büyüktür Pembe gözlük taktırır Yakar anlayamazsın Sonra aptallaştırır ...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/dusunsen-fena-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ummadık Kişide Cevherler Olur', 'ummadik-kiside-cevherler-olur-mustafa-demirci-2-4wcd6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dumanlı yollarda hiç yürüdün mü? 

Önün karanlık adımın yavaş olur

Boş hayal yerine sevgiyi düşün

Ummadık kişide cevherler olur

Gülün dikenine bülbül konmuş

Ahu zârından yorulmuş kalmış

Siyah saçlarına bak aklar dolmuş

Ummadık başlarda ne dertler olur

Zühürtün derdi de zengin parası

Kendine dön olma insan maskarası

Günden güne azıyor derin yarası

Ummadık melhemde medetler olur

Mustafayım dünya hali karışık

Derinleşir yüzündeki kırışık

Karanlıktan süzülüyor bir ışık

Ummadık yerlerde sedefler olur', 'Dumanlı yollarda hiç yürüdün mü?  Önün karanlık adımın yavaş olur Boş hayal yerine sevgiyi düşün Ummadık kişide cevherler olur Gülün dikenin...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Demirci 2']::text[], 8.5, '{"poet":"Mustafa Demirci 2","poet_slug":"mustafa-demirci-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ummadik-kiside-cevherler-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Fermanı', 'ask-fermani-bekir-gedikoglu-mgrk6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerimi sarı-kırmızıya boyadılar

Bedenimi kırmızı-beyaz ile giydirdiler

Sonra asker diye kışlaya yolladılar

Ama bağımdaki ayvamı çaldılar

Çalışıp ta mor boyalı bir ev aldım

Gönlümde yoğurduğum hamura uygun bir yar buldum

Foto Nurda çektirdiğimiz fotoğrafı baş ucuma koydum

Kalleşler bir oldu arkamdan vuruldum

Bir oğlum oldu bahtiyar oldum

Altına çam ağcından-meşeden beşikler oydum

Gece gündüz demeyip ninniler saydım

Fena vurdu kahpe felek hayattan soğudum

Akşam ezanında gün kısalmıştır

Sevgi tohumları meyve salmıştır

Sanmayın bu dünyada Bekir ölmüştür

Artık onun AŞK FERMANI evrensel olmuştur', 'Gözlerimi sarı-kırmızıya boyadılar Bedenimi kırmızı-beyaz ile giydirdiler Sonra asker diye kışlaya yolladılar Ama bağımdaki ayvamı çaldılar ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-fermani-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beceriksiz', 'beceriksiz-sule-aydemir-d2pvu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir an dem vuruyor geriliyorum

kokuşmuş leş gibi dönüveriyor yaşam

sırıtıyor haince gözlerimden

boşluk ruhumu sarıyor sevdalım sanki

git desem gitmiyor kal desem ani baki

susuyorum dilim gözüm lal oluyor 

yüreğim beceremiyor', 'bir an dem vuruyor geriliyorum kokuşmuş leş gibi dönüveriyor yaşam sırıtıyor haince gözlerimden boşluk ruhumu sarıyor sevdalım sanki git des...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/beceriksiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Silgi Silmez Olmuş Kendi Derdini', 'silgi-silmez-olmus-kendi-derdini-mustafa-demirci-2-g8fi7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bizim Haso bir gün dilekçe yazmış

Anlatıyor garip garip kendi derdini

Kalemi tükenmiş kağıdı bitmiş

Silgi silmez olmuş oy oy kendi derdini

Harfleri karışık kelime bozuk

Paragraf yapmamış noktası kazık

Zarfları pürsümüş puluna yazık

Yapıştırmış ağır ağır kendi derdini', 'Bizim Haso bir gün dilekçe yazmış Anlatıyor garip garip kendi derdini Kalemi tükenmiş kağıdı bitmiş Silgi silmez olmuş oy oy kendi derdini H...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Demirci 2']::text[], 8.5, '{"poet":"Mustafa Demirci 2","poet_slug":"mustafa-demirci-2","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/silgi-silmez-olmus-kendi-derdini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar yağdı dağlara ah ömrüm sana ne desem', 'kar-yagdi-daglara-ah-omrum-sana-ne-desem-nuri-can-1e6ve', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Suz-i Nağme

Kar yağdı dağlara ah ömrüm sana ne desem

ne söylesem zülf-i yare ey gönül

bülbüle figan düştü, bağlara gam-ı hazan

giryan eden gül-i zare ne desem

ne söylesem zülf-i yare ey gönül

çıkıp yücelerde seyr-i seyran eylerdin

dört mevsim aleme suz-i nağme söylerdin

elifi solmuş bir gül şimdi hasret pare pare

gitti giden ömür geri gelmez ne çare

şimdi bütün akşamlarda hüzn-ü  yas ağlar 

aşk-ı endam kızıl bir alev olup yakmasaydı bu canı

bir ahım bile yeterdi yakmak için ol cihanı

ben ki, gözleri yetim bir dervişim şimdi ey yar

her doğrulduğumda yedi yerimden vurdular beni

bu yüzdendir karalar giyerim, küserim yıldızlara

yüreğimden bir gül düşürürüm sulara her akşam

ve her gece bir can-ı canan veririm toprağa

kör olur gözlerim nereye baksam

kar yağdı dağlara ömrün ah sana ne desem

ne söylesem zülf-i yare ey gönül

bağlara gazel düştü, bülbüle feryad-ı ah

giryan eden gül-i zare ne desem

ne söylesem zülf-i yare ey gönül

ben ki, aşkın yollarında yönünü yitirmiş seyyah

dağlara yazar giderim derdimi her sabah

gitti giden ömür geri gelmez eyvah

kar yağdı dağlara ömrüm sana ne desem

ne söylesem zülf-i yare ey gönül

yaramı bağrıma basar giderim

hasret ki dudağımda bir alev gül pare pare

gitti giden ömür geri gelmez ne çare

ne dost kaldı hanede ne de can-ı canan

yan şimdi ey gönül, dermansız derdine yan

Nuri Can

www.nurican.com', 'Suz-i Nağme Kar yağdı dağlara ah ömrüm sana ne desem ne söylesem zülf-i yare ey gönül bülbüle figan düştü, bağlara gam-ı hazan giryan eden g...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kar-yagdi-daglara-ah-omrum-sana-ne-desem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Budur İşte Diyebilelim!', 'yasamak-budur-i-ste-diyebilelim-necmettin-karaman-45lky', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünü, bugünü, yarını yaşamak ve yaşamak

Yaşadım, yaşıyorum, yaşayacağım

Diyebilmek kendimce

Sigara, içki ve kumar

Hoşlanmadığın, kullanmadığım, 

Zevk almadığım hususlar....

Sakın bana kızmayın, böyle yazıyorum diye

Sevgili dostlar.

Yaşamak istiyorum...

Arkadaş arıyorsan sigaraya yanaşma

Zevk almak istiyorsan alkol yanıcı madde

Mideden başlar ise, beyne kadar ulaşır

Kontrolünü kaybetme

Şakası yok kumarın

Fakir zengin dinlemez kaptırırsan kendini

Eziyet eder size, 

Yuvanızı dağıtır, rezil eder herkese

Paranız hükmetmesin, diliniz küfretmesin

Saygı temel taşımız, sevgi günlük aşımız

Olsun herzaman bizim

Mutluluk şiirleri yazalım, okuyalım

Müzik ve Resim ile doğru yolu bulalım

Sevelim sevilelim, kendimizden geçelim

Yaşamanın tadına doyasıya varalım

Yaşamak budur iste

Diyebilelim.

12.8.2003 İstanbul', 'Dünü, bugünü, yarını yaşamak ve yaşamak Yaşadım, yaşıyorum, yaşayacağım Diyebilmek kendimce Sigara, içki ve kumar Hoşlanmadığın, kullanmadığ...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Karaman']::text[], 8.5, '{"poet":"Necmettin Karaman","poet_slug":"necmettin-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yasamak-budur-iste-diyebilelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kürsüde Maymun Oynar', 'kursude-maymun-oynar-mustafa-demirci-2-ow7nq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kürsüye garip bir maymun dadanmış

Oynayıp duruyor kendi başına

Mikrofonu bozdu bardağı devirdi

İş açtı dururken kendi başına

Çaldığı muzu çıkardı zevkle yedi

Harama vetfaa verdi helal dedi

Pantolonu çıkarıp eteği giydi

Belkide geliyordu onun işine', 'Kürsüye garip bir maymun dadanmış Oynayıp duruyor kendi başına Mikrofonu bozdu bardağı devirdi İş açtı dururken kendi başına Çaldığı muzu çı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Demirci 2']::text[], 8.5, '{"poet":"Mustafa Demirci 2","poet_slug":"mustafa-demirci-2","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kursude-maymun-oynar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-ozgur-arda-r9id6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamanla dövüşen dalga, 

Çağırmış bekleyen yelkovanı, 

Dinlemiş akrebe olan zamansız aşkını.

Anlatmış deniz dostuna

Anlamış deniz, 

Ağlamış ve dönüşmüş okyanusa.', 'Zamanla dövüşen dalga,  Çağırmış bekleyen yelkovanı,  Dinlemiş akrebe olan zamansız aşkını. Anlatmış deniz dostuna Anlamış deniz,  Ağlamış v...', ARRAY['Türk Edebiyatı','Şiir','Özgür Arda']::text[], 8.5, '{"poet":"Özgür Arda","poet_slug":"ozgur-arda","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ask-172-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-ozgur-arda-16rel', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnızlığımı sensizliğime sormuşlar, 

Demiş koca deniz bir balığa aşık, 

Balık kaybolmuş kalbinde; 

Balık biliyor deniz tek, 

Deniz biliyor içinde sonsuza dek...', 'Yalnızlığımı sensizliğime sormuşlar,  Demiş koca deniz bir balığa aşık,  Balık kaybolmuş kalbinde;  Balık biliyor deniz tek,  Deniz biliyor ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Arda']::text[], 8.5, '{"poet":"Özgür Arda","poet_slug":"ozgur-arda","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sensizlik-91-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Özlerim', 'deli-ozlerim-ozgur-arda-6co7u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bazen bir anı kopup geliyor yanıbaşıma

Ne özlüyorum kadınları bir bilsen! 

O gözlerle sevişmek, 

Dokunmak o ellere, 

Kapamak gözlerini o bedene

Bilir misin ne demek? 

Bir papatya tarlasında yalın ayak gezmişim

Susup koklamışım titreyen tenlerini

Toplamışım zamana uzanabildiklerimi

Gezerken umursamaz geceleri, 

Kuru topraktayım şimdi kaldırmış ellerimi, 

Özlemez mi insan o aşk tutan renklerini

Dans eden şarabın ıslak davetini

Kucaklayabilsem demez mi tekrar o buketleri

Deli özlerim kadınları bir bilsen, 

Bir bilseler koparıp gelmezler mi köklerini?', 'Bazen bir anı kopup geliyor yanıbaşıma Ne özlüyorum kadınları bir bilsen!  O gözlerle sevişmek,  Dokunmak o ellere,  Kapamak gözlerini o bed...', ARRAY['Türk Edebiyatı','Şiir','Özgür Arda']::text[], 8.5, '{"poet":"Özgür Arda","poet_slug":"ozgur-arda","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/deli-ozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zordur Değişmek', 'zordur-degismek-ahmet-aksoy-vvisi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Acıdır marangozun

Çekicinden çıkan

Ve inler tahta

Her bir vuruşta

Çakılan çivi

İlerlemektedir  her an

Tahtanın bağrını delerek

Usta memnun tahta acılıdır

Ustaya sorarsan emek

Tahtaya sorarsan

Zorunlu bir işkencedir

Ne kadar zordur değişmek.', 'Acıdır marangozun Çekicinden çıkan Ve inler tahta Her bir vuruşta Çakılan çivi İlerlemektedir  her an Tahtanın bağrını delerek Usta memnun t...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zordur-degismek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Film Sahnesi', 'film-sahnesi-filiz-angay-8ulca', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kardeşim Barış''a

Her yer bir film sahnesi...

Bir yanda savaş, bomba, kaybolan umutlar, 

	Önce kulakları sağır eden gürültü, 

		Sonra ölüm sessizliği...

Diğer yanda çıkar çatışmalarının bataklığı...

Kaçmaya çalışanlar batıyor, batıyor, 

	Son bir umutla ellerini uzatıyorlar, 

		Onlar da gömülüyor derinliğe...

Başka bir yanda ışın karmaşası...

Bütün soyut kavramlar renklenip ışın olmuş, 

Sevginin, umudun, barışın çekici renkleri, 

Ve fesadın, bencilliğin, hırsın kasvetli renkleri, 

Etrafı göremiyorum, oluşan sisten...

Sahnelerden kaçmak istiyorum, dönüyorum, 

Ama çevremdekilerin egolarının dağları yolu kesiyor, 

Kimisi çocukluğumuzu, 

	Kimisi hedefimizin yolunda uçuracak motivasyonumuzu, 

		Kimisi de umutlarımızı kesmiş...

Bastığım toprak sanki dibe inmekte, 

Dağlar daha da yükselmekte...

Ben ve yolları kesilenler, 

Ya da gerçekleri böyle görebilenler, 

Kardeşim, sevdiceğim, dostlarım, 

Ya güneşimiz kesildiği için solan bir bitki olacağız, 

Ya da ellerimiz birleşecek, güçlenip dağları aşacağız, 

Uçacağız enginlere...', 'Kardeşim Barış''a Her yer bir film sahnesi... Bir yanda savaş, bomba, kaybolan umutlar,  	Önce kulakları sağır eden gürültü,  		Sonra ölüm se...', ARRAY['Türk Edebiyatı','Şiir','Filiz Angay']::text[], 8.5, '{"poet":"Filiz Angay","poet_slug":"filiz-angay","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/film-sahnesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gidişe Şiir', 'bir-gidise-siir-erdal-noyan-s3fe9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akşamüstüdür sende hüzün

Kaygan sevmelerin misafiri

Dar elbise seri sonu

Mecburen giyindiğin

Zamanı gelince gidersin sen de

Binbir vehimle mühürlenir şehir

O mekânsız dilbere

Rehin kalır yüreğin.', 'Akşamüstüdür sende hüzün Kaygan sevmelerin misafiri Dar elbise seri sonu Mecburen giyindiğin Zamanı gelince gidersin sen de Binbir vehimle m...', ARRAY['Türk Edebiyatı','Şiir','Erdal Noyan']::text[], 8.5, '{"poet":"Erdal Noyan","poet_slug":"erdal-noyan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-gidise-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksa', 'yoksa-cankat-girgince-r0g6w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir şiire isim bulmak mı zordu? 

Yoksa bir isme şiir yazmak mı? 

Başka öyküleri sevmek mi gerekirdi? 

Yoksa başka sevgilere öykünmek mi biraz da...? 

Asıl olan özne miydi bir cümlede? 

Yoksa cümlenin özü kendisi miydi? 

Beni sevindiren yüzünün gülmesi miydi? 

Yoksa her gülün bilmediğim bir yüzü mü vardı? 

Onlar, başından omuzlarına düşenler; saçların mıydı? 

Yoksa gökkuşağının düşlerimdeki saçmalığımı? 

Bilmiyorum, sana benim kadar aşk veren olur mu? 

Yoksa sana verilen en büyük aşk ben miyim...? 

29.10.1999 (İstanbul)', 'Bir şiire isim bulmak mı zordu?  Yoksa bir isme şiir yazmak mı?  Başka öyküleri sevmek mi gerekirdi?  Yoksa başka sevgilere öykünmek mi bira...', ARRAY['Türk Edebiyatı','Şiir','Cankat Girgince']::text[], 8.5, '{"poet":"Cankat Girgince","poet_slug":"cankat-girgince","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yoksa-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Bitti...', 'ask-bitti-i-lhan-garip-ss6sd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllar sonra bulmuştum  seni.

Bir akrebin kıskacında..

Hani derler ya; 

''Derenin kesileceği hızlı akışından belli olurmuş.''

Ha işte buda öyle bitti. Ben bittim...

Yıllar sonra görmüştüm seni.

Bir pencerenin puslarında 

Bir flim şeriti gibi geçtin.

Flim bitti. Ben bittim...

Güneşin kızıllığında gördüm seni

Işıyordun yüreğime.

Sonra bilemediğim bir şeyler oldu.

Gün bitti. Ben bittim...

Gecenin karanlığında gördüm seni.

Ay hilaldi.Hilal ümitti..

Ay şimdi dolunay.

Ümit bitti. Ben bittim...', 'Yıllar sonra bulmuştum  seni. Bir akrebin kıskacında.. Hani derler ya;  ''Derenin kesileceği hızlı akışından belli olurmuş.'' Ha işte buda öyl...', ARRAY['Türk Edebiyatı','Şiir','İlhan Garip']::text[], 8.5, '{"poet":"İlhan Garip","poet_slug":"i-lhan-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ask-bitti-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amcacığım,', 'amcacigim-seref-kaya-2tm6y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgili Amcam''a



Seni çok seviyorum Amca, 

Ne kadar uzakta olsan da. 

Bunu sana anlatamam, 

Kelimelere sığdıramam. 

Yakışıklı, tatlı dilli, çok şekersin, 

Herkesi mest edersin. 

Bütün yeğenlerin seni çok sever, 

Belki sen bunu bilemezsin. 

Canım Amcam benim! 

Seni çok özledim. 

Bir an önce göreyim, 

Daha da çok seveyim. 

Bu ararlar şiir yazamadım, 

Çok özür dilerim. 

Hatırlat bana unutma, 

Açıklarımı kapatayım. 

                              Didem', 'Sevgili Amcam''a Seni çok seviyorum Amca,  Ne kadar uzakta olsan da.  Bunu sana anlatamam,  Kelimelere sığdıramam.  Yakışıklı, tatlı dilli, ç...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/amcacigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Kazaklı Bulutla Söyleşi', 'siyah-kazakli-bulutla-soylesi-ensar-cevval-ugdum', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıldırım çakışından korkan çocuk

başını yastığa saklar dua ederdin

görüyordum

yalnızdın odanda, ağlamaklıydın

baban korktuğunu bilir,

usulca odana girer, koyun koyuna yatardınız

korkuların mevsimseldi

biliyordum; 

ben en çok baharlarda yağardım, 

korktuğunda babanın geleceğini  bilir

ve anlardım hep yanında olmam gerektiğini 

babana sarılıyken yüzündeki tebessümü

avuç açıp dua edişini

dudaklarını da okurdum.

Büyüdün, kocaman bir dünya kurdun

yanıbaşındayım 

havai fişklerimi patlatıyorum

korkuyorsun, yastığına saklanıp dualar ediyorsun 

görüyorum, 

bu kez yalnız değilsin, bir çift göz daha ağlamaklı

aranın ışığı yanıyor, ve bir karaltı süzülüyor yatağına

babacığım çok korkuyorum diye haykırıp

sarılıyor ürkek bedenine.

daha sıkı giyinmeliyim kara bulutlarımı

daha çok havai fişek patlatmalıyım biliyorum

ara ışığı yanan evler çoğalmaya başlamışken

daha çok pencere buğulandırmalıyım.

05,08,2003 İstanbul', 'Yıldırım çakışından korkan çocuk başını yastığa saklar dua ederdin görüyordum yalnızdın odanda, ağlamaklıydın baban korktuğunu bilir, usulca...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/siyah-kazakli-bulutla-soylesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Diş', 'i-ki-dis-birol-ozdemir-3knf7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'nerede yaşamak

nerede yaşlanmak istediğin

veya ne iş yapacağın değil merak ettiğim.

ne üzerinde duracağın toprağın kokusu

ne de içinde kalacağın iklim ilgilendiriyor beni, 

yatağına bırakacağım güllerin, 

hatta benimle seviştiğin odaların rengi bile, 

ya da gülüşüne iliştirdiğim şiirlerin zamanı

umurumda değil.

ben sadece isterim ki

en sonuncusunu da nefeslerimin

alıp dudaklarının üzerinden

yüreğine kadar gönderip

yani bütün vücudunda dolaştırıp yine, 

yine paylaş benimle.

bir de becerebilirsen

o iki dişini açıkta bırakıp

gülümseyebildiğince gülümse, 

küçük gözlerimin en içine.

(1998-İstanbul)', 'nerede yaşamak nerede yaşlanmak istediğin veya ne iş yapacağın değil merak ettiğim. ne üzerinde duracağın toprağın kokusu ne de içinde kalac...', ARRAY['Türk Edebiyatı','Şiir','Birol Özdemir']::text[], 8.5, '{"poet":"Birol Özdemir","poet_slug":"birol-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/iki-dis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşikâr', 'asik-r-ensar-aktas-4kn98', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şıvgın gözlerindir seni şiar kılan

Baygın bakışlarındır beni şikâr yapan

Sessizliğim, korktuğumdandır kırmaktan seni

Yoksa ölümüne sevdiğim aşikâr değil mi? 

Yeşilkavak,03-08-2003', 'Şıvgın gözlerindir seni şiar kılan Baygın bakışlarındır beni şikâr yapan Sessizliğim, korktuğumdandır kırmaktan seni Yoksa ölümüne sevdiğim ...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/asikar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir O Kadar, , ,', 'bir-o-kadar-murat-kustul-yfz7v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir dal sigara işte bu kadar baglıyım hayata! 

Bir o kadar basit, bir o kadar  alışmış, bir o kadar anlık yaşamalısın.

Bir nefes, bir fırt işte böyle olmalı sevda

Bir o kadar yarım, bir o kadar tatlı

Bu kadarla kalmalısın.

Şüphesiz sen bu ülkenin en agır tütünüsün, 

Fakat senin zehrini cigerlerine dolduracak tek tiryakin benim, , , 

Kalp çarpıntılarıma sebep, kalıcı nefes darlıgım

Akcigerlerime yapışmış silinmez lekeler, 

Parmaklarımda şu acı dolu nikotin kokusu, , , 

Yüregim sigara kagıdı, 

Hayalini sarıp, gözlerinin kibritini vurunca duygu kavına 

Yakıyorum hislerimi

ve sensizligin dumanı cigerlerimi dolduruyor, 

Bir de hasretinin kokusu sinmiyor mu tenime

Tiryakinim ''SENİN''sen ne dersen de! ! !', 'Bir dal sigara işte bu kadar baglıyım hayata!  Bir o kadar basit, bir o kadar  alışmış, bir o kadar anlık yaşamalısın. Bir nefes, bir fırt i...', ARRAY['Türk Edebiyatı','Şiir','Murat Kuştul']::text[], 8.5, '{"poet":"Murat Kuştul","poet_slug":"murat-kustul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-o-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümden Düşünceler', 'olumden-dusunceler-sule-aydemir-q4c30', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kucak dolusu Baccara güllerinden tebessümler

bir sabah kalkıp sar sarmala yaşamı

sonra tek tek sevdiklerini düşün 

bahar havasını ciğerlerine çeker gibi

ya da bir yağmur sonrası

mis gibi

sonra hisset 

ensende yine bir Azrail  nefesi 

sarıl sarıl öyle sarıl ki

sevdiğine 

ve sevmediklerini düşündüğün

binlerce kadir kıymete rahmete

binlerce lüzümsuz dediklerine

sevgiden buseler yükle rüzgarlarına

salıver gitsin yaşamın kıvrımlarına saklılarına

öyle bir yaşa ki

ölüme yaşam yaşar gitsin', 'kucak dolusu Baccara güllerinden tebessümler bir sabah kalkıp sar sarmala yaşamı sonra tek tek sevdiklerini düşün  bahar havasını ciğerlerin...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olumden-dusunceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çırılçıplak', 'cirilciplak-ozgur-arda-a1vtl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni uyandım sabah, 

11,12 gibiydin, pazardın.

Yürüdüm rüzgar saçlarında 

Yaza bir kala bahardın deniz dalgalarında, 

Akşamüstü bir demleme çay cam bardakta

Günbatımı martı martı yansıyor akşamına 

Tatlı bir yorgunluk çöküyor duygularıma

Bir tek atmalı rüyalarıma...', 'Seni uyandım sabah,  11,12 gibiydin, pazardın. Yürüdüm rüzgar saçlarında  Yaza bir kala bahardın deniz dalgalarında,  Akşamüstü bir demleme ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Arda']::text[], 8.5, '{"poet":"Özgür Arda","poet_slug":"ozgur-arda","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cirilciplak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farksız', 'farksiz-hakki-hakan-kaya-h5ese', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yoktur aslında farkımız, 

Kimimiz uzun, kimimiz kısayız, 

Bir ip ile birbirimize bağlıyız, 

Tespih halkasında yanyana insanız.

Aynıyız aslında hepimiz, 

Kimimiz yaşlı, kimimiz genciz, 

Yolun sonunu görmeden biliriz, 

Nöbet değişimi yaparız hepimiz.

Biliriz herşeyi de, Bilmeyiz, 

Görürüz herşeyi de, Görmeyiz, 

Bazen durur, bazen gideriz, 

İnilmesi gereken yerde inmeyiz.

İnsanız işte hepimiz, 

Farklı kişilik, farklı karakteriz, 

Vardır tek bir ortak noktamız, 

Sonunda aynı yerde konaklarız.', 'Yoktur aslında farkımız,  Kimimiz uzun, kimimiz kısayız,  Bir ip ile birbirimize bağlıyız,  Tespih halkasında yanyana insanız. Aynıyız aslın...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/farksiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yola Devam Etmeli', 'yola-devam-etmeli-sair-asivan-hqrm5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bitmiş bir ilişkiyi geçmişe gömerken, 

hep bir parça alıyoruz yanımıza

yeni ilişkiye yapıştırmak için...

Biriktiriyoruz içimizdeki yaşanmamış özlemleri, 

geçmişin artıklarından oluşturmaya çalışıyoruz yeni bir sevgiliyi..

Onun yeni bir insan, yeni bir yaşam olduğunu görmüyoruz...

Boş bakkal misali eski defterleri karıştırıp duruyoruz, 

kıyaslıyoruz, ''''o böyle demezdi, yapmazdı''''

Ve bir gün  yapayalnız kalınca faturayı o insanlara çıkarıyoruz, 

sanki yaşanmasına izin vermişiz gibi...

Çok geç olmadan 

geçmişin adı üzerinde, 

yaşanmış, bitmiş, geçmişşş olduğunu kabullenmeli, 

yola devam etmeli...', 'Bitmiş bir ilişkiyi geçmişe gömerken,  hep bir parça alıyoruz yanımıza yeni ilişkiye yapıştırmak için... Biriktiriyoruz içimizdeki yaşanmamı...', ARRAY['Türk Edebiyatı','Şiir','Şair Asivan']::text[], 8.5, '{"poet":"Şair Asivan","poet_slug":"sair-asivan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yola-devam-etmeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkak', 'korkak-sule-aydemir-ddbsf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'çelik pençelerinde düşünce hürriyet

şahin bakışlarında 

ve bir avcı pazarlığında

elleme sen avuçların ciğerin yanacak

kendini kim diye düşünmekten korkak', 'çelik pençelerinde düşünce hürriyet şahin bakışlarında  ve bir avcı pazarlığında elleme sen avuçların ciğerin yanacak kendini kim diye düşün...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/korkak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mührünü Takar Ellerim', 'muhrunu-takar-ellerim-kamil-colak-yxi2w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ahşap fırınları süsleyen ateş topu

taşırım ellerini esnek bir zamana

gümüş tenli yıldızlar kuşatmış seni, uzaksın

ellerimde kalır hicran müsveddeleri

dökülür sensizliğe yalnızlığım, garip

gömülür başım renkli saatlere, yoksun 

anne bana atımı getirin 

gitmeliyim, elimden tutar ışık yağmurları

kuyular sırrını açar bana

ben o yerlerin küçük delikanlısıyım

saclarım fırtına kokar

durmadan kekik toplarım

türkülerimde çekik gözlü kızlar

söğüt kavlatırlar asırlık dudaklarına

sevdiklerine ayna tutarlar ikindi güneşlerinde

en kırmızı güller yetiştirirler

baharın gümüşten bahçelerinde

duramam 

gitmeliyim

beni çağıran bir ses var

geldin taş atarak girdin bahçeme, kanattın renklerimi

ağlattın beni uzun uzun, yoktun

şimdi girdim sensizliğin bahçesine

kokladığım güller yitmiş hiç olmuş

girdabını yitirmiş sular gibiyim

yıllardır bitmeyen yokuşlarındayım

denizleri yırtan eller bana, 

fısıldar kulağıma seni, özlerim 

bitmeyen şarkının dudağımdaki karesi

içime doğru koşar, sen yoksun

mimoza bahçelerinde erirken ay ışıkları

mührünü takar ellerime gelirim sana

gönlümde ıslanmış aşklar

yasaklı bahçelerdir, sensin

geçerim önünden bana kaldırılmış tüfeklerin

sabah akşam yürürüm mihriban yokuşlarında

dudaklarımda hep o şarkı, gözlerin için

takarım ellerime mührünü sana gelirim', 'ahşap fırınları süsleyen ateş topu taşırım ellerini esnek bir zamana gümüş tenli yıldızlar kuşatmış seni, uzaksın ellerimde kalır hicran müs...', ARRAY['Türk Edebiyatı','Şiir','Kamil Çolak']::text[], 8.5, '{"poet":"Kamil Çolak","poet_slug":"kamil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/muhrunu-takar-ellerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençlik Türküsü', 'genclik-turkusu-esma-ozdemir-7qa43', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Otuziki otuziki yaşındayım 

Daha hayatın başındayım!

Diye, söyleyemeden kendi türkümü

Yaş otuzüç olmuş da 

Haberimiz olmamış! 

Varsın, olsun yaş otuziki, otuzüç, 

Ya da otuzbeş...

Ben değilim ki Cahit Sıtkı, derd''edeyim yılları!

Yaş dönümümüz geldi; hoş geld,i sefa geldi! 

Yaşım otuzikiyi geçti, gitti; güle güle, güle güle! 

Bak güzelim aynalara, seyret kendin,i

Seyret bütün güzelliğini! 

Korkma, sen asla çirkinleşmezsin

Kalbini bozmadıkça ve sevgiden uzaklaşmadıkça! 

Şimdi, yeniden söylüyorum 

Otuzu deviren genç kızlara türkümüzü; 

Haydi kızlar, başlayın, sesiniz çıksın,

Var mı paşa gönlümüzün kahyası! 

Günah benim, keyif benim, dert benim

Hayat benim, ömür benim, yaş benim

Sakın ağlama ardımdan garip gençliğim

İğneyi ipliği başına iş eden benim! 

Sevda benim, gönül benim, aşk benim!

Yürek benim, umut benim, düş benim!

Gözlerimden akan billur gibi yaş benim!

Sinesinde deste deste gülistan benim!

Haydi kızlar, söylemeye başlayın,

Umutsuz gönüllere cesaret aşılayın! 

Otuziki otuziki yaşındayım

Daha hayatımın başındayım! ...', 'Otuziki otuziki yaşındayım  Daha hayatın başındayım! Diye, söyleyemeden kendi türkümü Yaş otuzüç olmuş da  Haberimiz olmamış!  Varsın, olsun...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/genclik-turkusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda Türküsü', 'veda-turkusu-kamil-colak-gd66y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Alaeddin ÖZDENÖRENE

ak çiçekli kavala ses oldu gidişin

döküldü uzun bir ırmağa karıştı

bizim bahçemizin gülü gülzarı

gölünden içtik en duru suları

yavru üveyikler ötüşünce dallarda

çocuklar koşar her sabah rüyalarına

okşadı toprağı tül gibi bulutlar

gölgene serdi ay ışıklarını sarı

sende koştun bahçesine ölümün

bulutlar ağır şimşekler savurur

“avuç avuç” cinasa döker gözler

yaşarız içten içe derin kuyuları

menzile süzülen ten kafesinde

uçuçu kuş besledin

onu  taşırım bir göz rengi gibi

her kim görmek için koşar bana

devşiririm yüzümün suyunu dökerek

“ah gülüm gülüm insanlaradır ölümüm”

dediniz ve gittiniz ah güzel insan

                                            05.07.2003', 'Alaeddin ÖZDENÖRENE ak çiçekli kavala ses oldu gidişin döküldü uzun bir ırmağa karıştı bizim bahçemizin gülü gülzarı gölünden içtik en duru ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Çolak']::text[], 8.5, '{"poet":"Kamil Çolak","poet_slug":"kamil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/veda-turkusu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçır Seni Sevgilim', 'kacir-seni-sevgilim-kamil-colak-pyb03', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'KAÇIR SENİ SEVGİLİM

bizi bekler kavlimiz sevgilim

yönlerimizi bulalım ayrılmadan köşemiz

derin bir mezar bizimkisi sevgilim

çiçekleri dallarında koklarız 

erince sevginin sır burcuna

evler yürür uzun ırmaklara

ne elimde masal kalır ne kahır

sarınca sevgilim seni yâr burcuna

bir şarkı  birde türkü doldurur

dillerine söz olurum sevgilim

kumru uykuları gezdirir gözlerim

kalbinin özüne uyurum sevgilim

çiçekleri yıkadım en duru sularda

saçlarına yakın açacak diye

sesini sakladım kuru güllerde

sevda tutkuların dil açımına

kaçır seni sevgilim

akşam inerken suya

yıldızları boyayalım göz rengine

ve geceler gözlerinin rengiyle kalsın

rüyalar bitmesin, bildiğim kule 

imbik imbik kumru seslerini içelim

kaçır beni sevgilim imlası bol ellerine

beni çocukluğumun gök kuşağına ver

gittikçe ırayan koştukça kaybolan

sıkıca arkadaşım ol oyunlarımda

sevgilim bana çocukça bilyelerini ver', 'KAÇIR SENİ SEVGİLİM bizi bekler kavlimiz sevgilim yönlerimizi bulalım ayrılmadan köşemiz derin bir mezar bizimkisi sevgilim çiçekleri dallar...', ARRAY['Türk Edebiyatı','Şiir','Kamil Çolak']::text[], 8.5, '{"poet":"Kamil Çolak","poet_slug":"kamil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kacir-seni-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mimoza bahçelerinde ay hale hale', 'mimoza-bahcelerinde-ay-hale-hale-kamil-colak-9ip7n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mimoza bahçelerinde ay hale hale

dokunur akşamın veremli penceresine

Eşiğimde açan gülleri takar

Kıvrılır yatar göz kapaklarımda

Su yürür yeşil türkü söyler

Benim soylu yüreğimde büyür

Şehre girdiğin saat zambaklar 

Mimoza bahçelerinde ay hale hale

Rabbim onda giydiğim duyguları

Koşup bağırasım geliyor insanlara

Göksel ışığını ver ona uzayıp gitsin

Mimoza bahçelerinde ay hale hale

Ardıçlara gölge düşer tepelerde

Kuşlar yuvalarında bulurlar seni

Güneş yatağını toplarken yerden

Mimoza bahçelerinde ay hale hale', 'Mimoza bahçelerinde ay hale hale dokunur akşamın veremli penceresine Eşiğimde açan gülleri takar Kıvrılır yatar göz kapaklarımda Su yürür ye...', ARRAY['Türk Edebiyatı','Şiir','Kamil Çolak']::text[], 8.5, '{"poet":"Kamil Çolak","poet_slug":"kamil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mimoza-bahcelerinde-ay-hale-hale-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanıyorum', 'utaniyorum-kamil-colak-fchja', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman çekirdeğini bölüp de bana, 

Gül üstü gönlünü açan sevgili

Sana yürüyorum ülkemin sokaklarından

Her yanım zehir kesilmiş duramam

Sular gözlerinin kumaşını arıyor

Sözlerinin giziyle çatlayan kayalar

Büzüyor ellerimizi, güller kuruyor

Ötmüyor bahçelerimizde bahçıvancı kuşlar

Sevgili seni unuttu dillerimiz; utanıyorum

Anneler artık imaj suyu içiyorlar

Yarasa börklü duygular ovuyor ellerini

Her şeyimize yürüdü metal kasalar

Sevgimize aşkımıza güzelliğimize

Kaç zamandır bilmeyiz gül şerbetini

Bir azap uykusuna gömüldü başımız

Sevgili seni unuttu dillerimiz; utanıyorum

Ne hazindir ki savururduk en tatlı yellere

Yağmurdu yeşerirdik  dal budak gür

Sevda nehirlerine dalardık gülerdi kuğular

Kumaşımızı dokurdun renkli nakışlarla

Kardeş derdik birbirimize gönlümüzdü kardeş

Şimdi savrulur olduk acı imbatlara

Kaptanlar harcandı gemiler yandı, divaneyiz

Sevgili seni unuttu dillerimiz; utanıyorum

 Nergis ve zambakla ördüğümüz evler

Gittiler çorak gönlümüzü süzerek

Bahar çiçeklerine koşamaz olduk

Kapandık yada kapattılar bizi küçücük balkonlara 

Unuttuk çeşmelerin yolunu su sesini kırba meşini 

Bilemeyiz o celi sülüs yazısını, uğramamış da diyarımıza sanki

Gönül tarlamızın arı namelerini resmettiğimiz kule

Ebruli sevda kulesi yıkıldı ey sevgili

Sevgili seni unuttu dillerimiz; utanıyorum

Bir yasak tortusuna kurudu fidanlarımız

Büyütemedik, dur diyemedik küfre

Kitabını açıp bakamadık bakamadılar

Kalın surlarla çevriliydi gözlerimiz

Bizim olmayan standarda uyandık

Oysaki gülümüz vardı bizim goncadan ipek 

Kokladıkça açılır ışık olur yüzlerimize saçılır

Yasakmış, firengi hastalığına tutulmuş bunlar

Görmeyecekler aşk incileriyle el ele olduğumuzu

Sevgili seni unuttu dillerimiz; utanıyorum

Sevgili seni unuttu kalplerimiz utanıyorum

Sevgili seni unuttu ellerimiz utanıyorum

Sevgili en acısı seni unuttu hallerimiz, utanıyorum

Seni selamlıyorum ey nebi

Seni selamlıyorum ya resul

Seni selamlıyorum eteğine tutunduğum peygamberim', 'Zaman çekirdeğini bölüp de bana,  Gül üstü gönlünü açan sevgili Sana yürüyorum ülkemin sokaklarından Her yanım zehir kesilmiş duramam Sular ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Çolak']::text[], 8.5, '{"poet":"Kamil Çolak","poet_slug":"kamil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/utaniyorum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hilal Gibi Gül', 'hilal-gibi-gul-i-lhan-garip-j80k2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hergün yıkılır mı insan? 

iki kere yıkıldım ben

biri öğle saatlerinde

biri ikindi ezanı okunurken..

hep bedenimde bir titreşim bekledim

ikindi vakitlerinde..

Hep teneşirlerde kaldım.

Hakkını helal eden yüzlerce melekle...

iki kanat pencere açıldı gözlerimde.

Birinde senin gülüşün, benim hıçkırıklarım.

Senin alaycı bakışın

Benim kahroluşum

Sen güldün.

Ben eridim

SEN HEP GÜL EMİ...', 'Hergün yıkılır mı insan?  iki kere yıkıldım ben biri öğle saatlerinde biri ikindi ezanı okunurken.. hep bedenimde bir titreşim bekledim ikin...', ARRAY['Türk Edebiyatı','Şiir','İlhan Garip']::text[], 8.5, '{"poet":"İlhan Garip","poet_slug":"i-lhan-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hilal-gibi-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabrın Çiçek Açtı ANNE', 'sabrin-cicek-acti-anne-erdal-gisi-polpz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kar doluyor gözlerime

sen gözyaşını gizlerken

hiç insana susamazdım

anne.. seni yudumlarken

ne kadar yüreğin billur

duygular ne kadar içten

sütün kadar ak herşeyin

ak yine ben kararırken

yüzüm gözüm kandı hani

tek doktorum sendin hani

şefkat yurdunda büyüttün

yurdun bahdı karalıyken

evlerde su yoktu o gün

taşıyarak büyütürdün

yetim bir insan türüydün

melekler de kaçıyorken

iyi günün kötü günün

tebessümle kaldı dünün

sen topraktın bense gülün

sabrın çiçek açtı anne..

1995', 'kar doluyor gözlerime sen gözyaşını gizlerken hiç insana susamazdım anne.. seni yudumlarken ne kadar yüreğin billur duygular ne kadar içten ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Gişi']::text[], 8.5, '{"poet":"Erdal Gişi","poet_slug":"erdal-gisi","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sabrin-cicek-acti-anne-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yirmibirinci Yüzyıl Türküsü', 'yirmibirinci-yuzyil-turkusu-rasim-eksi-jo1xb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey demirden duvarları delip geçen ışık

Düşüncenin suyu tuzu yüreği

Yaşıyası özgürlük tutkusu.

Bir yerde bir insan ağlar

Hıçkırığı rapsodiden dönüşme

Özgürlüğe ağıttır suskusu.

Hey gizemli oluş

Hey güçlü büyü

Bu bir değil artık

Bu sayısız

Bu gizli değil artık bu apaçık

Tamtamdır kulaklarımızın duyduğu.

Bir kutsal ilkyazdır adağı insanlara

Göğüsleri al 

Alınları ak kılar

Yaşıyası özgürlük tutkusu.', 'Ey demirden duvarları delip geçen ışık Düşüncenin suyu tuzu yüreği Yaşıyası özgürlük tutkusu. Bir yerde bir insan ağlar Hıçkırığı rapsodiden...', ARRAY['Türk Edebiyatı','Şiir','Rasim Ekşi']::text[], 8.5, '{"poet":"Rasim Ekşi","poet_slug":"rasim-eksi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yirmibirinci-yuzyil-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyalarım Sende Kaldı', 'ruyalarim-sende-kaldi-nuri-can-8vopw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçimde bir şeyler eriyip gidiyor her gece

sancılı ve sessiz

akıp gidiyor bilmediğim yolculuklara

suskularla örüyor alnımı zaman

ah aldığını geri vermiyor yıllar

umutlar kırılıyor iç çekişlerimde

düş bahçelerimde çiçekler üşüyor

yıkılıyor yıllarca kurduğum hayaller

yedi kat yerin altında kaldı haykırılarım

ah sesimi kimse duymuyor

yoruldum yıllarca kendimi taşımaktan

bir serseri gibi yaşamaktan 

içimde tutsak kaldı geçen günler

dönüp bakamam geriye

rüyalarım sende kaldı

hayallerim sende

ümitlerim sende

yüreğim sende kaldı

ah adresini kimse bilmiyor

bir sonbahardı alıp gitti gemiler seni

kaldım avuntusuz öyle bir başıma

yanlızlığım sende kaldı, sensizliğim sende

sende kaldı baharım, sabahım sende kaldı

bir de martılarım kaldı çığlık çığlığa

ah şimdi hiç bir gemi almıyor beni

bir yanım ellerin parmakların

bir yanım gözlerin dudakların

rüyalarım sende kaldı

ümitlerim sende

aklım sende

ben sende kaldım

ah adresini kimse bilmiyor

.', 'İçimde bir şeyler eriyip gidiyor her gece sancılı ve sessiz akıp gidiyor bilmediğim yolculuklara suskularla örüyor alnımı zaman ah aldığını ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ruyalarim-sende-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-olcay-yazici-wvxog', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen sana doğru Fatih

O ona doğru Sezar

Erdemsiz bencil koşu

Bitiş noktası mezar

Sevgi yürekte mahpus

Bakış bakışa mermi

Kim kime yaklaşacak

Mermer kanı emermi.

olcay yazıcı', 'Sen sana doğru Fatih O ona doğru Sezar Erdemsiz bencil koşu Bitiş noktası mezar Sevgi yürekte mahpus Bakış bakışa mermi Kim kime yaklaşacak ...', ARRAY['Türk Edebiyatı','Şiir','Olcay Yazıcı']::text[], 8.5, '{"poet":"Olcay Yazıcı","poet_slug":"olcay-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevgi-91-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Yudumda Aşk', 'i-lk-yudumda-ask-cem-ucar-e1l1d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlk yudumu gibi rakının 

			Eski arkadaşlarla uzun zaman sonra 

			Eski günleri yadederken

İlk kelime gibi hediye bir kalemle yazılan

			Anlamsız ama beklentili

			Bilinçsiz ama ümitli

İlk dokunuşu gibi güneşin

			Kara bir kıştan sonra 

			Bir bahar sabahı 

İlk göz yaşı gibi bir erkeğin

			Saf ve çekingen

			Aşık ve gururlu

İlk damla gibi toprağa düşüp içeri giremeyen

			Kaybetmeye hazır

			Yenilgiye mahkum

İlk sessizlik gibi tufandan sonra gelen

			Yorgun

			Işıltılı

İlk aşk gibi

			Lisede 

			Kantinde

İlk yudum da sarhoşluk gibi

			Dağılmaya hazır

			Şuursuzluğa istekli

İlk yudumda aşk gibi

			Sadece tek kişilik

			Tamamı bir anda

Seni ilk kez sevmek gibi

				Tarifsiz

Seninle ilk buluşma gibi

			Heyecan dolu

Seninle yeniden görüşmek gibi

			Yaralayıcı

Seninle bir günü düşlemek gibi

			Saatler süren

Seninle bir masayı paylaşmak

			Sıra dışı bir keyif

Senin ellerine bir demet çiçek uzatmak

			Bir elimde çiçek

			Bir elimde kalbim

Seninle ilk kez kadeh kaldırmak

			En kötü sona

			En iyi adım

Seni başkasının kollarına uğurlamak

			………

								12.08.2003 22:39:45', 'İlk yudumu gibi rakının  			Eski arkadaşlarla uzun zaman sonra  			Eski günleri yadederken İlk kelime gibi hediye bir kalemle yazılan 			Anl...', ARRAY['Türk Edebiyatı','Şiir','Cem Uçar']::text[], 8.5, '{"poet":"Cem Uçar","poet_slug":"cem-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ilk-yudumda-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurlar (ıı)', 'yagmurlar-ii-caglar-akarsu-6m2bb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmurlar (ıı) 

....

Çağırmalısın her gece vakti, 

Gözlerinden çile yaşları akarken, 

Yağmurlar üzerine inerken, 

Avare sokaklarda bir başıma, 

Gezerken  ışıkları kapat, 

Sisler arasında kalmışsa her şey, 

Puslu havların sıkıntısı çökmüşse, 

Uzat ellerini çağır işte, 

İnsin bu gece..

Yağmurlar, yağmurlar...

....

Bitkiler başlarını kaldırmışlar, 

Güller, kırmızı yapraklarını dökmüşse, 

Kuşlar, yuvalarını terk etmişse, 

İşte o sabah çığlıklar yüreğine dolar, 

Yağmurlar, yağmurlar.

.....

Bir anne haykırmışsa, olanca sesi ile, 

Savaşın hüznü çökmüşse yüreğine, 

Bebeğine sımsıkı sarılırda kaçar, 

Korkular sarmışsa tüm dağları, 

Yollar aşılmaz tepelere çıkmışsa, 

Gökyüzüne kaldır ellerini, insin! 

Yağmurlar, yağmurlar

....

13/tem/03

caglar akarsu', 'Yağmurlar (ıı)  .... Çağırmalısın her gece vakti,  Gözlerinden çile yaşları akarken,  Yağmurlar üzerine inerken,  Avare sokaklarda bir başım...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yagmurlar-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtınalı Deniz', 'firtinali-deniz-ahmet-aksoy-ian3p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Denizciler bilir en iyi seni

Ey fırtınalı deniz korkutma beni

Ben anlamam iskeleden sancaktan

Ben anlamam yelkenden pruvadan

Ey fırtınalı deniz korkutma beni

Bir kez düştü işimiz sana

Bırak devam edelim yolumuza

Ey fırtınalı deniz rahat bırak beni.', 'Denizciler bilir en iyi seni Ey fırtınalı deniz korkutma beni Ben anlamam iskeleden sancaktan Ben anlamam yelkenden pruvadan Ey fırtınalı de...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/firtinali-deniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hafıza', 'hafiza-ahmet-aksoy-ikugi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geçen günler geçer

Kalıntıları kalır hafızada

Hafızadır en büyük, 

Ölülere mezar

Ölüler bir canlanır bir ölür

Bir koşar bir yürür bir durur

Ölülerdir tek yaşayan

Benliğin soğuk mezarlarında.', 'Geçen günler geçer Kalıntıları kalır hafızada Hafızadır en büyük,  Ölülere mezar Ölüler bir canlanır bir ölür Bir koşar bir yürür bir durur ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hafiza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lamba', 'lamba-ahmet-aksoy-d5ccy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni ben yaktım lamba

Seni bu direğe ben taktım

Nasıl anlaşmıştık nankörlük yapma

İşin aydınlatmaktı insanları

Eğlenmeyecektin serseriler gibi.

Aydınlatmaktı insanları işin.

Öyle anlaşmamış mıydık.

Öyleyse niye su koyuverdin

Niye su koyuverdin nankör lamba?', 'Seni ben yaktım lamba Seni bu direğe ben taktım Nasıl anlaşmıştık nankörlük yapma İşin aydınlatmaktı insanları Eğlenmeyecektin serseriler gi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/lamba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz', 'i-simsiz-ahmet-aksoy-0sli6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimsesi yoktu onun

Adı Garip soyadı Yalnız’dı

Kimsesi yoktu onun

Kimsesi de olmamıştı

Ondan başka

Yıllar önce ölen 

Her gün ziyaret ettiği

Ama hiç görmediği

Köy mezarlığında yatan

İsimsiz ölüden başka

Her gün düzenli olarak gider

Konuşurdu, sabahtan akşama kadar

Ya da akşamdan sabaha

Bir gün bir savaşçı

Bir gün bir çoban

Bir gün bir marangoz

Bir gün bir doktor olurdu ölü

Bazen bir zalim 

Bazen bir mazlum

Bazen kral

Bazen soytarı

Ama her gün başka 

Bir hikayenin kahramanı

Bir gün kadın olurdu

Anne eski sevgili eski bir eş

Bir gün erkek olurdu

Baba, kardeş eski bir arkadaş

Ama hep dinleyen olurdu

Hiç küsmez hiç kızmazdı

Ne isterse Garip, o olurdu

Nasıl olsa mezar taşı boştu

Ne isterse garip, o olurdu.', 'Kimsesi yoktu onun Adı Garip soyadı Yalnız’dı Kimsesi yoktu onun Kimsesi de olmamıştı Ondan başka Yıllar önce ölen  Her gün ziyaret ettiği A...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/isimsiz-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevişme Vakti', 'sevisme-vakti-ali-ender-cemgil-v0jx7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bitsin artık bu sessizlik

Sessizliğini duymak istiyorum.', 'Bitsin artık bu sessizlik Sessizliğini duymak istiyorum....', ARRAY['Türk Edebiyatı','Şiir','Ali Ender Cemgil']::text[], 8.5, '{"poet":"Ali Ender Cemgil","poet_slug":"ali-ender-cemgil","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/sevisme-vakti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda cicegim', 'sevda-cicegim-seref-kaya-bsi2t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dogumla basliyan hayatin, sonu ölüm! 

Hayatin baharinda, neler görüp, neler yasiyacaksin.

Bak! dün sokakta kosturan sen, düsünürmüydüm ölümü

Sevda cicegim.en son düsünecegin olsun ölüm.

Dogumla basliyan, bir cok yerinden yapistirilmis, Film seridi yasam.

Yasam acilari, biber acisina benzemez, Film seridinde ki güzellikler.

Kötümser olup, bahar gelmiyecek diye kahrolamazsin, 

Sevda cicegim, her halde en son düsünecegin ölüm.

Genc kiz oldun; ne hayallerin vardi, düsünür müydün sen ölümü

Bir basamak yukari ciksam, basim göge degecek derdin.

Umutlarini yitirme, kaybolan zaman, sen hala ayaktasin.

Sevda cicegim, Film seridinde daha ne güzellikler var, düsünemezsin ölümü

Hani cocuktun hatirladin mi? ya simdi cocuklarin oldu, 

Mutluluk bazen, bir Ful cicegi koklayinca solar

Sogukta kalmis, bir Gül sün solmamali, gülmelisin.

Benim adim ask, beni kaybettigin icin düsünmemelisin ölümü.

                                                                             seref kaya  2003', 'Dogumla basliyan hayatin, sonu ölüm!  Hayatin baharinda, neler görüp, neler yasiyacaksin. Bak! dün sokakta kosturan sen, düsünürmüydüm ölümü...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevda-cicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer', 'eger-alaettin-isik-btb0g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir başka yaşam varsa eğer, 

Korkmak olmayacak orada, 

Kaçmak hiç olmayacak

Sevmek olacak her mevsim.

Bir başka yaşam varsa eğer, 

Bütün gördüklerimiz unutulacak, 

Her çiçek bin sevdaya eşit, 

Yeniden göreceklerimiz çeşit çeşit..

Bir başka yaşam varsa eğer, 

Toprak olacak her şey gibi..

Kimse bilmeyecek içimizdekileri

Bilmeyecekler kalbinin bana, 

Zimmetli olduğunu..

Bir başka yaşam varsa eğer, 

Ağaçlar bizi açacak

En güzel şarkılar bizim olacak

En deli sevişmeler bizimle.

Korkuların hepsi geçmişte kalsın, 

Sarılmak orada.. dokunmak..

En güzeli de sevgili

Doymak imkansız olacak..

13/08/2003', 'Bir başka yaşam varsa eğer,  Korkmak olmayacak orada,  Kaçmak hiç olmayacak Sevmek olacak her mevsim. Bir başka yaşam varsa eğer,  Bütün gör...', ARRAY['Türk Edebiyatı','Şiir','Alaettin Işık']::text[], 8.5, '{"poet":"Alaettin Işık","poet_slug":"alaettin-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/eger-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğini Aldım', 'yuregini-aldim-alaettin-isik-d84su', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben bir sevgi bahçesiyim, 

Yüreğimde çiçekler açar

Sevgi tohumlarından..

Bir yaralı yüreğin vardı ya, 

Gönül bahçeme aldım onu.

Çiçekleri açtı ve birleşti, 

Her iki bahçe.

Şimdi bir yürekte, 

Yalnızca Biz olduk, 

Yaşamı şimdi anladık

Meğer, 

Sınırsız yaşamakmış

Yaşamak.', 'Ben bir sevgi bahçesiyim,  Yüreğimde çiçekler açar Sevgi tohumlarından.. Bir yaralı yüreğin vardı ya,  Gönül bahçeme aldım onu. Çiçekleri aç...', ARRAY['Türk Edebiyatı','Şiir','Alaettin Işık']::text[], 8.5, '{"poet":"Alaettin Işık","poet_slug":"alaettin-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yuregini-aldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapıyı Araladım', 'kapiyi-araladim-sair-celebrian-cioo8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kapıyı araladım, 

Bilirim, sürprizleri seversin

Belki birden gelirsin diye 

Kapıyı araladım, 

Açtım tüm perdelerini camların

Burada olduğumu bilesin diye

Kapıyı araladım…', 'Kapıyı araladım,  Bilirim, sürprizleri seversin Belki birden gelirsin diye  Kapıyı araladım,  Açtım tüm perdelerini camların Burada olduğumu...', ARRAY['Türk Edebiyatı','Şiir','Şair Celebrian']::text[], 8.5, '{"poet":"Şair Celebrian","poet_slug":"sair-celebrian","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kapiyi-araladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokaktaki Çocuk', 'sokaktaki-cocuk-sair-celebrian-t09le', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Küçük çocuk banktan düşerdi

Aç ve hasta

Soğuk bir bankta uyurken.

Oysa çocuklar düşmezler asla

Anne babalarının ortasında yatarken…', 'Küçük çocuk banktan düşerdi Aç ve hasta Soğuk bir bankta uyurken. Oysa çocuklar düşmezler asla Anne babalarının ortasında yatarken…...', ARRAY['Türk Edebiyatı','Şiir','Şair Celebrian']::text[], 8.5, '{"poet":"Şair Celebrian","poet_slug":"sair-celebrian","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sokaktaki-cocuk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Damlaları', 'su-damlalari-sair-celebrian-on0r8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hepimiz birer su damlası değil miyiz? 

Akıntısına kapıldığımız bu hayat nehrinde

Bazen bu nehir öyle coşkun akıyor ki, 

Başımız dönüyor, afallıyoruz.

Bazense olabildiğine durgun, 

Sıkılıyoruz.

Bulutlar getirirken bu nehre yeni damlaları, 

Bir çoğumuz buharlaşıyor.

Yanımızdan akıp gidiyorlar

Bazısını seviyoruz, çok seviyoruz

Şeffaf kalplerimize işliyoruz adlarını

Ama ayrılırken akıntıya karşı gelemiyoruz

ve ayrılmamak için sarılamıyoruz birbirimize 

Kollarımız yok diye.', 'Hepimiz birer su damlası değil miyiz?  Akıntısına kapıldığımız bu hayat nehrinde Bazen bu nehir öyle coşkun akıyor ki,  Başımız dönüyor, afa...', ARRAY['Türk Edebiyatı','Şiir','Şair Celebrian']::text[], 8.5, '{"poet":"Şair Celebrian","poet_slug":"sair-celebrian","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/su-damlalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hala Titriyorum Nöbetlerce', 'hala-titriyorum-nobetlerce-feyza-kalender-4sv5j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gün döndü hala ısınmadım

hala titriyorum nöbetlerce

deliliğim yasaklığımdan....

*    *    *

hala tükenmek bilmedim

nedendir bilmem 

ben hala ölmedim.

kırgınlığım yazgımdan, 

yılgınlığım umutsuzluğumdan.....

bu sev sevmeler ıstırab dolu 

                                             yine de

vazgeçemiyorum, çılgınlığımdan..

                                              yardan..........

                    2003', 'gün döndü hala ısınmadım hala titriyorum nöbetlerce deliliğim yasaklığımdan.... *    *    * hala tükenmek bilmedim nedendir bilmem  ben hala...', ARRAY['Türk Edebiyatı','Şiir','Feyza Kalender']::text[], 8.5, '{"poet":"Feyza Kalender","poet_slug":"feyza-kalender","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hala-titriyorum-nobetlerce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belalı Sevişim', 'belali-sevisim-feyza-kalender-s7dq2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'nar ağacım

sesizce geldin gönlüme

şimdi sormadan yine

sessizce git! 

nedensiz çelişliker

mesken tutmuş zihnini

hoyrat eller

gardını al nar ağacım

bak, geliyor düşmanlar

kanma  pusulara, 

bu yürek senle güler

senle ağlar

sessizce git! 

ben bile hissetmemeliyim

acını.

bilmemeliyim.

benden kendini al! 

hatta gel, hırsız gibi 

çal! 

sevdiğim umudumdur, 

tutkumdur

vazgeçemediğimdir.

bu belalı sevişime kanmadan

toparlan! 

                    2003', 'nar ağacım sesizce geldin gönlüme şimdi sormadan yine sessizce git!  nedensiz çelişliker mesken tutmuş zihnini hoyrat eller gardını al nar a...', ARRAY['Türk Edebiyatı','Şiir','Feyza Kalender']::text[], 8.5, '{"poet":"Feyza Kalender","poet_slug":"feyza-kalender","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/belali-sevisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Vurulsam Sen Yaşarmısın', 'ben-vurulsam-sen-yasarmisin-derin-oger-b5esh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dışım yalnız

İçimde sen varsın

Görmez gözlerin anlamazsın

Göğsümde çoğaldıkça yaralarsın

Yaralı benim sen niye kanarsın....

Gözlerim dolu dolu

Ağlasam içime yağarsın

Çalkalanır caniçim canımda

Gözlerin sürer kurşunu namluya

Ben vurulsam  sen yaşarmısın.........', 'Dışım yalnız İçimde sen varsın Görmez gözlerin anlamazsın Göğsümde çoğaldıkça yaralarsın Yaralı benim sen niye kanarsın.... Gözlerim dolu do...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ben-vurulsam-sen-yasarmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçüktüm Büyüdüm', 'kucuktum-buyudum-ahmet-aksoy-7sidy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Küçücük yüreğimle aşka yeltenir

Sever sever üzülürdüm

Bir kavuşamamazlıkdı sevgim

O zamanlar çok küçüktüm

Ufak dünyalarda büyük sevdalar

Büyük acılar yaşardım

Bir sevgiden başka bir sevmeye

Giden, otobüs şoförüydü aklım

Küçük acılarla yoğruldu yüreğim

Daha büyüklerine yol açmak için

Küçük acılarla büyüdü yüreğim

Şimdi hala küçük benliğim büyük bir yürekle.', 'Küçücük yüreğimle aşka yeltenir Sever sever üzülürdüm Bir kavuşamamazlıkdı sevgim O zamanlar çok küçüktüm Ufak dünyalarda büyük sevdalar Büy...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kucuktum-buyudum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peri', 'peri-ahmet-aksoy-dz5j3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Billur bir pınar

Gibi sessizliğin

Su sesine dönmüş sözlerin

Aksin bir gölde, yakamoz

Ay ışığı değil yakamozun

Daha da güzel

Ve sen su perim

Karanlıklarda aydınlığım

Çıkıyorsun her gece

Çıkıyorsun karanlıklardan

Dünyamı aydınlatmak için.', 'Billur bir pınar Gibi sessizliğin Su sesine dönmüş sözlerin Aksin bir gölde, yakamoz Ay ışığı değil yakamozun Daha da güzel Ve sen su perim ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/peri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlüğe', 'ozgurluge-ahmet-aksoy-rgfn5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Koşan atlar koşar

Duran atlar durur

Özgürlerdir çayırlarda

Yabani atlar

Bu çayırlardan 

Farklıdır o çayırlar

Yabani atlar özgürdür

Hara istemiyorum 

Çayırları verin bana

Yağmur istiyorum

Rüzgar istiyorum umarsız

İstediğim kaygısız çayırlar

Hara istemiyorum

Çayırları verin bana.', 'Koşan atlar koşar Duran atlar durur Özgürlerdir çayırlarda Yabani atlar Bu çayırlardan  Farklıdır o çayırlar Yabani atlar özgürdür Hara iste...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ozgurluge-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam', 'yasam-ahmet-aksoy-53hvq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen bir resimsin

Kendi ressamı olan

Bir resim

Ne çizersen 

O olacaksın

İşte budur yasam.', 'Sen bir resimsin Kendi ressamı olan Bir resim Ne çizersen  O olacaksın İşte budur yasam....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yasam-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşek', 'esek-ahmet-aksoy-9uvdg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yemini aldın mı

Hadi gidiyoruz

Çabuk ol geç kalmayalım

Zamanında varmalıyız

Anladık eşeksin

Ama eşek olman

Eşeklik yapmanı gerektirmez

Gidecek dediysek gideceğiz

Hadi düş önüme

Bir kez söz verdin

Eşeklik etme.', 'Yemini aldın mı Hadi gidiyoruz Çabuk ol geç kalmayalım Zamanında varmalıyız Anladık eşeksin Ama eşek olman Eşeklik yapmanı gerektirmez Gidec...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/esek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazin', 'hazin-ahmet-aksoy-284ot', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir anarşistin anıları gibisin

Her şeye saldıran kendine düşman

Hiçbir tutacağın yok geçmişlerde

Ve böyle giderse olmayacak da

Yıllar ihtiyarlatırken bedenini

Sen yalnız olacaksın, yapmadıklarının

Yalnızı, yapamadıklarının eksikliği

Yapamayacaklarının fazlalığıyla.', 'Bir anarşistin anıları gibisin Her şeye saldıran kendine düşman Hiçbir tutacağın yok geçmişlerde Ve böyle giderse olmayacak da Yıllar ihtiya...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hazin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadakat', 'sadakat-ahmet-aksoy-ko5gb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her şey terk eder seni

Bir zaman kalır seninle

Yaşamda ve ölümde.', 'Her şey terk eder seni Bir zaman kalır seninle Yaşamda ve ölümde....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/sadakat-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Odun', 'odun-ahmet-aksoy-iq15v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben bir odunum

Yontulmam gerek

Dur hemen yakma

Yakarsan bir kerelik

Olur ömrüm

Ama marangozum olursan

Ben bir eser sense

Bir sanatçı olabilirsin

İkimiz bir olur 

Birlikte yaşarız

Korkma ölürüm diye

O zaman, ben 

Seni anlatırım

Senden sonrakilere

Yont beni marangozum.', 'Ben bir odunum Yontulmam gerek Dur hemen yakma Yakarsan bir kerelik Olur ömrüm Ama marangozum olursan Ben bir eser sense Bir sanatçı olabili...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/odun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümü Anlamak', 'olumu-anlamak-ahmet-aksoy-i47ua', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nerede gidenler

Daha demin buradaydılar

Ne çabuk gittiler.', 'Nerede gidenler Daha demin buradaydılar Ne çabuk gittiler....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/olumu-anlamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşin Söndü', 'atesin-sondu-ahmet-aksoy-w4p3c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ateşin söndü

Ama isin kaldı

Aşk.

Silecek bir

Can yok

Bıraktığın isini.', 'Ateşin söndü Ama isin kaldı Aşk. Silecek bir Can yok Bıraktığın isini....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/atesin-sondu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beş Duyu', 'bes-duyu-birol-ozdemir-o6t8b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'içtiğim sigaranın tadı yok

dudaklarının tadı karışmadığında

yani gözlerinin içinden geçecek ki bakışım

gördüğüm bir şeye benzesin, 

en küçüğü bile dokunsa tenime parmaklarının

her yanımı dağlasınlar, acımaz

sesini duymadan indim mi güne, diyeceğim, 

gün güne benzemiyor

yani kuvvetli en kuvvetlisinden uyuşturucunun

bir nefes kokun.

insanım diyorum

hepi topu beş duyumdan, 

gittin mi

beşiyle bir gidersin, 

gittin mi

ne anlarım ''insan''dan.

(1998)', 'içtiğim sigaranın tadı yok dudaklarının tadı karışmadığında yani gözlerinin içinden geçecek ki bakışım gördüğüm bir şeye benzesin,  en küçüğ...', ARRAY['Türk Edebiyatı','Şiir','Birol Özdemir']::text[], 8.5, '{"poet":"Birol Özdemir","poet_slug":"birol-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bes-duyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sade', 'sade-ozgur-arda-63mlf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Taş aşka, 

Aşk doğaya, 

Doğa buluta, 

Bulut yaşa, 

Yaş sana, 

Sen bana, 

Ben aynaya, 

Dönene dek taşa, 

Yaşa.', 'Taş aşka,  Aşk doğaya,  Doğa buluta,  Bulut yaşa,  Yaş sana,  Sen bana,  Ben aynaya,  Dönene dek taşa,  Yaşa....', ARRAY['Türk Edebiyatı','Şiir','Özgür Arda']::text[], 8.5, '{"poet":"Özgür Arda","poet_slug":"ozgur-arda","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sade-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-necmettin-karaman-zmz79', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaman Zaman

Ararım ben onu

Mumla olsada

Derdini dökecek

Vakit bulsada

Var olan dertlere

Ortak olsada

Tadında bırakalım olan biteni

Bitmiyor çileler antatılmakla

Gülmüyor çehreler asık suratla

Arkadaş ne yapsın sinirler gergin

İmkân bulursa olacak zengin

İste o zaman herkes

Candan arkadaşın, dostun olur senin....

Necmettin Karaman

13 Ağustos 2003

İstanbul', 'Zaman Zaman Ararım ben onu Mumla olsada Derdini dökecek Vakit bulsada Var olan dertlere Ortak olsada Tadında bırakalım olan biteni Bitmiyor ...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Karaman']::text[], 8.5, '{"poet":"Necmettin Karaman","poet_slug":"necmettin-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/arkadas-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp', 'kayip-ozgur-arda-pa0io', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kayboldum bugün gözlerinde, 

Düşüncelerinle salladın beni, 

Daha hızlı, en yukarı, 

Açtım kollarımı, bıraktım kendimi en yukarıda, 

Deyeceğim sandım pembe bulutlara, 

Ta ki bulana dek kendimi kollarında, 

Ayrılık vakti geldi derken, 

Çektim demir kapıyı, gıcırdayarak kapandı, 

Kanatlarını germiş gelen demir bir kartal yakmıştı yıldızlarını, 

Süzülen bir o, bir de sonbahar vardı.

Kat kat bulutlar örtmüştü dolunayı, 

Sokak kedileri titriyordu, göz göze geldik, 

O zaman hissettim, 

Ben durmuştum ama, dünya dönüyordu...', 'Kayboldum bugün gözlerinde,  Düşüncelerinle salladın beni,  Daha hızlı, en yukarı,  Açtım kollarımı, bıraktım kendimi en yukarıda,  Deyeceği...', ARRAY['Türk Edebiyatı','Şiir','Özgür Arda']::text[], 8.5, '{"poet":"Özgür Arda","poet_slug":"ozgur-arda","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kayip-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davet', 'davet-ozgur-arda-1sdry', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneş gölgemle uykuya daldı, 

Ben buket yaptım sana yıldızları, 

Gecem yemyeşil, 

Ay yine gözlerinden yansıyor olmalı.

Gülümse, 

Sen ağlama diye suladım bulutları.', 'Güneş gölgemle uykuya daldı,  Ben buket yaptım sana yıldızları,  Gecem yemyeşil,  Ay yine gözlerinden yansıyor olmalı. Gülümse,  Sen ağlama ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Arda']::text[], 8.5, '{"poet":"Özgür Arda","poet_slug":"ozgur-arda","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/davet-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç', 'gec-ozgur-arda-zhuab', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gece uzun uzun düşünmüşüm, 

Seni sadece yüzyıl eksik öpmüşüm.

Derin deniz, sarılmış üşümüşüm

Bu seni rüyamda ne ilk ne de son görüşüm!', 'Bir gece uzun uzun düşünmüşüm,  Seni sadece yüzyıl eksik öpmüşüm. Derin deniz, sarılmış üşümüşüm Bu seni rüyamda ne ilk ne de son görüşüm!...', ARRAY['Türk Edebiyatı','Şiir','Özgür Arda']::text[], 8.5, '{"poet":"Özgür Arda","poet_slug":"ozgur-arda","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gec-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dur Gitme!', 'dur-gitme-guven-aktas-skvqe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gül gibimiydi sevdamız., 

Mevsimi bitiğinden mi soldu? 

Hemen kapanır mı yaramız? 

Ağlamakla göz pınarları kurur mu? 

Git! 

Gitmek istiyorsan eğer, 

Senin olsun istediğin yerler, 

Eğer bu akşam gideceksen? 

Dur! 

Sakın gitme! 

Beni son kez öpmeden….

Seni düşündükce hergece, 

Karşıma geçip oturacakmısın her zamanki yerine….

Eskisi gibi yine, Bakacakmısın gözlerime…

Başım ağrıyor dediğimde

Öpecekmisin alnımdan eskisi gibi yine, 

Sen bilmiyorsun giderken bıraktığın acıyı, 

Sen bilemessin sensiz senle nasıl yaşadığımı, 

Bilemessin deliler gibi aynalardan kaçtığımı, 

Bilemessin bir çılgınlık yapağacağımı.

Umutlarımı yıkık bırakırken, 

Gitme sakın ben uyurken, 

Dur! 

Sakın gitme beni son kez öpmeden, 

Ne olur gitme! son kez öpmeden, 

Içimde seni yaşatmak çok zor, 

Sana deliler gibi aşıkken 

Bırakıp gitmen çok koyuyor, 

Çok acı veriyor bedenime

Geleceksin diye her gece penceremde, 

Çocuklar gibi çaresizce, 

Beklemek koyuyor sadece 

Aslında en çokta, 

Seni böyle severken, 

Bırakıp beni gitmen, 

Beni yanlızlığıma yine 

Hapsetmen koyuyor.', 'Bir gül gibimiydi sevdamız.,  Mevsimi bitiğinden mi soldu?  Hemen kapanır mı yaramız?  Ağlamakla göz pınarları kurur mu?  Git!  Gitmek istiy...', ARRAY['Türk Edebiyatı','Şiir','Güven Aktaş']::text[], 8.5, '{"poet":"Güven Aktaş","poet_slug":"guven-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/dur-gitme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Beni Hiç Tanımıyorsun', 'sen-beni-hic-tanimiyorsun-ensar-aktas-2sgh2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen beni hiç tanımıyorsun ki

Çünkü ben seninleyken hiç ben olmadım

Hep senin istediğin gibi

Hayal ettiğin gibi biri oldum

Senin sevdiğin yemekleri yedim

Senin seçtiğin filmleri seyrettim

Senin beklediğin hediyeleri aldım

Senin beğendiğin çiçekleri kokladım

Ne zaman yatacağıma sen karar verdin

Saat kaçta kalkacağıma yine sen

Ne giyineceğime sen karar verdin

Ne söyleyeceğime sen

Beni kafanda yeniden yarattın

Kaderimi bile yeniden yazmaya kalkıştın

Olmadı hiç fırsatım kendi kendimi yaşamaya

Bu yüzden sen beni hiç tanımıyorsun

Ben sanki bir aynaydım karşında

Beni değil kendini gördün her bakışında

Şimdi büyü bozuldu, sihri yok oldu aşkın

Kırıldı ayna bir dokunuşta

İşte çıktım gerçek yüzümle karşına

Ya böyle bas beni bağrına

Ya da koca bir taş

İstersen gel otur karşıma

Yeniden tanış benimle yavaş yavaş

Rotterdam,30-05-2003

Çeşme,07-07-2003', 'Sen beni hiç tanımıyorsun ki Çünkü ben seninleyken hiç ben olmadım Hep senin istediğin gibi Hayal ettiğin gibi biri oldum Senin sevdiğin yem...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sen-beni-hic-tanimiyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ucuz Canlar', 'ucuz-canlar-murat-demir-dpyid', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim gibi meydanda

Dolaşın ucuz canlar

Gösterin kendinizi

Bu günlerde Pazar var

Belki işe yararız

Canımız pahasına

Yada layık oluruz

Gazi madalyasına

Baba ne derse desin

Karşı gelmek asla ha

Kafasını kızdırma

Para vermez bir daha

Emir ferman ondadır

Yer varmı kaçacaksın

İster sağ ister ölü

Bu işi yapacaksın

Bize güvenen beyler

Söz vermiş adımıza

Öl diyorsa ölmemek

Uyarmı şanımıza

Vay ben böyle kaderin

Tüküreğim içine

Oda onlardan yana 

Bak feleğin işine', 'Benim gibi meydanda Dolaşın ucuz canlar Gösterin kendinizi Bu günlerde Pazar var Belki işe yararız Canımız pahasına Yada layık oluruz Gazi m...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ucuz-canlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biraz', 'biraz-nizam-uzun-dxask', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şöyle uzanıversem

Musalla taşına boydan boya

Bu akşam öyle bıkkınım ki

Biraz ölsem diyorum

(Bostancı-1984)', 'Şöyle uzanıversem Musalla taşına boydan boya Bu akşam öyle bıkkınım ki Biraz ölsem diyorum (Bostancı-1984)...', ARRAY['Türk Edebiyatı','Şiir','Nizam Uzun']::text[], 8.5, '{"poet":"Nizam Uzun","poet_slug":"nizam-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/biraz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık', 'asik-mustafa-i-lhan-guldemir-0trki', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neden takılıyorum sana

Niçin dolaşıyorum saçlarına

Ellerim dolaşıyor aşık gibi

Kurtaramıyorum kalbimi senden

Nasıl çırpınıyorum senin için

Kim koşturuyor beni peşinden

Niye yarışıyorum senin için.

Anlamıyorum sende ne buluyorum

Ben kimim niye yanındayım

Bazen neden birlikteyiz

Ne bekliyorum senden

Ara, ara niçin kalbim hızlanıyor

Sana ulaşmak için kiminle yarışıyorum

Ulaşınca kimseyi göremiyorum yanında

Demek ben onlardan hızlıyım, 

Acaba abdalmıyım, yoksa aşıkmı.

Boşuna yazıyorum sana bunları

Herkez gülecek, sende güleceksin

Ömür bu, eğlenirim dünyada

Gönlümü vermişim başkasına

Kendine başka gönül bul diyeceksin

Çünkü sen aşkı nereden bileceksin

Senin için eğlence ve sefadır aşk

Beni öldürecek cefadır seni sevmek.

Yılmayıp arayacağım bir seveni

Ona yazacağım şiirlerimi

Dinlerken göğsüme yaslar başını

Silerim gözünden akan yaşını

Saçlarından süzülür kurtulurum

Gönlünün en üstünde ben olurum

İndirmez beni el için oradan

Belki mutlu olurum tanımadan

Tanıyıp için, için ağlamaktansa

Tanımadan yazmak beklememek

Belki İyi gelir Aşık olmamak

Bilmem seni iyimi olursun

Gülermi, yoksa ağlarmısın

Verdiğin gönlünü geri alırmısın.

Ama ben hep aşık kalırım sana

Gizli, gizli ağlasamda aşık kalır

Sevinçten gülüyor olsamda aşık....', 'Neden takılıyorum sana Niçin dolaşıyorum saçlarına Ellerim dolaşıyor aşık gibi Kurtaramıyorum kalbimi senden Nasıl çırpınıyorum senin için K...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İlhan Güldemir']::text[], 8.5, '{"poet":"Mustafa İlhan Güldemir","poet_slug":"mustafa-i-lhan-guldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/asik-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen gül yeter ki', 'sen-gul-yeter-ki-guven-aktas-37m6v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kelimeler kalmadı sana askımı anlatmama yarayacak

Sen belki okudugunda yazılarımı gülüyorsun, 

Gülmek sana cok yakısıyor biliyormusun, 

Gül bakalım bu halimin sonu ne olacak, 

Askın elinde bir oyuncak olmusum, 

Bu sıra sadece nefes alıp veriyorum, 

Kelime kalmadı asıgım sana diyiyorum, 

Sen belki bu halime cok gülüyorsun…

Ne yapayım böyle bir seyi bende istemiyorum, 

Elimde degil seni deli gibi seviyorum, 

Sen belki bu halime cok gülüyorsun, 

Gül bakalım gülünce cok güzel oluyorsun.

Yüregimden adını cıkartmayacagım, 

Belki bir gün gelip senide unutacagım, 

Sen bu halime biliyorum cok gülüyorsun, 

Her gece deli gibi burnumda tütüyorsun, 

Bir kere olsun tutamadım ellerini, 

Sevmis bu gönül vurdum duymazın birini, 

Biliyorum sen cok gülüyorsun simdi, 

Gül bakalım, Tanrı kimselere vermesin bu derdi

Ilk seferine cıkmıs bir gemi gibi, 

Pırıl pırıl parlıyorsun yüregimde, 

Sen bu halime cok gülüyorsun belki, 

Olsun be, sen gül yeter ki…', 'Kelimeler kalmadı sana askımı anlatmama yarayacak Sen belki okudugunda yazılarımı gülüyorsun,  Gülmek sana cok yakısıyor biliyormusun,  Gül ...', ARRAY['Türk Edebiyatı','Şiir','Güven Aktaş']::text[], 8.5, '{"poet":"Güven Aktaş","poet_slug":"guven-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-gul-yeter-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vurgun', 'vurgun-sedat-sakabey-baysal-t72pc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nasıl? ..

Yıldırım düşer de bir ağaca, 

Köklerini yakar ya, 

Dalından önce.

İşte, 

Tam onun gibi, 

İndi yüreğime, 

Vurgun.

Dallarım yemyeşil duruken, 

Yüreğimde kurudum.

Ağaçlar...

Dalları renk renk...

Ve çiçek çiçek.

Ve benim, 

Yüzümde tebessüm! ..

Ama, 

Bir rüzgar esmeye görsün, 

Ya da, 

Yağmur sonrası fırtına...

Köksüz bir ağaç gibi durgun, 

Yüreğim yorgun...

Savrulur giderim meçhule, 

Kurur dallarım da, gövdem de, 

Belki bir yangın çıkar, 

Kül olurum.

Fayda vermez son pişmanlık, 

Henüz çiçek açmadım, 

Tohum vermedim ki toprağa, 

Takrar açmaz  bu yürek, 

Gülmez yeniden gözlerim.

Yüreğim, 

Ruhum yorgun.

Biliyormusun bir tanem, 

Seninle yedim, 

Vurgun! ....

	                                 27.07.03', 'Nasıl? .. Yıldırım düşer de bir ağaca,  Köklerini yakar ya,  Dalından önce. İşte,  Tam onun gibi,  İndi yüreğime,  Vurgun. Dallarım yemyeşil...', ARRAY['Türk Edebiyatı','Şiir','Sedat Sakabey Baysal']::text[], 8.5, '{"poet":"Sedat Sakabey Baysal","poet_slug":"sedat-sakabey-baysal","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/vurgun-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni aradım', 'seni-aradim-guven-aktas-t4quz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ve bir fırtına çıktı önce, 

Sonrada ince bir yagmur basladı, 

Ben yine her zaman ki yerimde, 

Rüzgara karısıp gezdim uzak diyarları, 

Bir umut aradım sevgiye dair, 

Mutlulugun sehrini aradım, 

Birde seni aradım diyar diyar, 

Mutlulugumu sende bırakmısım, 

Kıymet bilen bir yer aradım, 

Denizlerin ortasında ben beni aradım, 

Bir gece ansızın baslayan ince yagmurla, 

Ben bu gece deli gibi seni aradım, 

Yüregimin pesine takıldım, 

Ince yagmur ve rüzgarla karısık seni aradım, 

Pencerene geldim baktım, yoksun..

Neredesin diye seni aradım bu gece, 

Pek fazla bir sey aramadım, 

Ne bir söhret nede para aradım, 

Inceden baslayan yagmurla karısık

Ben seni aradım.', 'Ve bir fırtına çıktı önce,  Sonrada ince bir yagmur basladı,  Ben yine her zaman ki yerimde,  Rüzgara karısıp gezdim uzak diyarları,  Bir um...', ARRAY['Türk Edebiyatı','Şiir','Güven Aktaş']::text[], 8.5, '{"poet":"Güven Aktaş","poet_slug":"guven-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-aradim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adın Saklı', 'adin-sakli-hafize-zuluflu-iz5ia', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine zihnimin en derinlerinde

Saklı adın.

Bir tuhaf sükût, 

Söylenmeyen hecelerdesin...

Kimseye açamam gizim

Bir sen bilirsin, 

Bir ben.

Yine garip düşlerde, 

Gecelerdesin...

“Geleceğim” demiştin

a sevdiğim! 

Yine haftalar, aylar geçti

Büküldü boynu umutlarımın

Gelmez oldun, nerelerdesin? ...

Uzak uzak diyarlarda olsan da

Bana benden yakın, benden içeridesin.

İçimdeki yangında büyüyen

Vahaları görmezden gelip

Kayboldun seraplarda, 

İnadına çöllerdesin...', 'Yine zihnimin en derinlerinde Saklı adın. Bir tuhaf sükût,  Söylenmeyen hecelerdesin... Kimseye açamam gizim Bir sen bilirsin,  Bir ben. Yin...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/adin-sakli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kedinin Valsi', 'kedinin-valsi-sedat-sakabey-baysal-axxy1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilmem hiç izledin mi? 

Yarı tok bir kedinin, 

Fare ile valsini.

Haşin bir pençe önce, 

Sersemletir fareyi.

Sonra, 

Küçük okşamalarla, 

Kendine gelir fare.

Mahzun gözlerle bakar, 

Şöyle bir etrafına.

Bir hamle yapar kaçmak için, 

Ayakları gitmez bir türlü, 

Mehter marşı gibi öyle, 

Bir ileri bir geri, 

Sendeler ikinci pençeyle.

Büzülür, 

Bekler öyle.

Öylece durursa belki, 

Kedi bırakır diye.

Oyun bitince kedi, 

Siler bıyıklarını.

Fare  razı kaderine, 

Sızan kanları, 

Acılarıyla.

Bilir kaderini sanki, 

Bilir rızık olduğunu, 

Kediye.

İşte öylece biter, 

Bir hazin hikaye, 

Fare  mutludur yine de, 

Gerçekleşti var oluş gayem, 

Vuslata erdim diye.

				12.05.2003 -0045', 'Bilmem hiç izledin mi?  Yarı tok bir kedinin,  Fare ile valsini. Haşin bir pençe önce,  Sersemletir fareyi. Sonra,  Küçük okşamalarla,  Kend...', ARRAY['Türk Edebiyatı','Şiir','Sedat Sakabey Baysal']::text[], 8.5, '{"poet":"Sedat Sakabey Baysal","poet_slug":"sedat-sakabey-baysal","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kedinin-valsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sır', 'sir-sedat-sakabey-baysal-1uxoz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seninle, 

Bir bebeğin annesine olan sevgisi gibi, 

Masum başladı aşkımız.

Bahar mevsiminde, 

Tohumu saran toprak gibi, 

Sımsıcaktı..

Gönül bahçemiz.

Ne hülyalar kurardık bakarken gözlerimize.

Hani, 

Görmesek  dokunamasak bile ellerimizle, 

Yaşardık sadakati, 

Yüreğimizde.

Bir tabur askerin arasında kalsaydın sen, 

Ya da saray haremlerinde ben, 

Aklımıza gelmezdi şüphe.

Öylesine severdik birbirimizi.

Ya da, 

Ben öyle yaşadım aşkı.

Saf ve temiz.

Güvenle! 

Bebekler kıskanırdı, 

Kelebekler gıpta ederdi, 

Masum günahlarımızdaki saflığa.

Melekler bile gülerdi, 

Ne kadar güzeldi...

Ah ne günlerdi.

Sevdiğim.

Bir belirsiz  zaman girdi araya.

Bir yarım ay.

Ve soğuk sözlerin.

Nasılsın? 

İyimisin? 

Merhaba.

Merhaba.

Soğuk...

Hissiz...

Duygusuz...

Yüreğimin bir parçası hala  orada.

Hala boş kaldı yeri.

Aklım ege sahillerinde

Bir türlü, 

Gelmez geri.

Ah bir tanem! 

Bu sır beni öldürür.

Sen, 

Nasıl yaşarsın bilemem.

Ben artık eskisi gibi, 

Gülemem.

Gülemem bebeğim...

Keşke büyümeseydin, 

Ya da, 

Ben görmeseydim.', 'Seninle,  Bir bebeğin annesine olan sevgisi gibi,  Masum başladı aşkımız. Bahar mevsiminde,  Tohumu saran toprak gibi,  Sımsıcaktı.. Gönül b...', ARRAY['Türk Edebiyatı','Şiir','Sedat Sakabey Baysal']::text[], 8.5, '{"poet":"Sedat Sakabey Baysal","poet_slug":"sedat-sakabey-baysal","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/sir-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Hayali', 'askin-hayali-i-rfan-cebeci-cf3hc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sahili sardığında hayalin

Kızkulesinde yangınlar çıkar

Ayışığında yakamozlar

Hüzünlü baktığında yüreğim

Yağmurlarda gökkuşağı çıkar

Gözlerinde yangınlar', 'Sahili sardığında hayalin Kızkulesinde yangınlar çıkar Ayışığında yakamozlar Hüzünlü baktığında yüreğim Yağmurlarda gökkuşağı çıkar Gözlerin...', ARRAY['Türk Edebiyatı','Şiir','İrfan Cebeci']::text[], 8.5, '{"poet":"İrfan Cebeci","poet_slug":"i-rfan-cebeci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/askin-hayali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatandaş Abuzer', 'vatandas-abuzer-hakki-hakan-kaya-p1auu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O kendini bildi bileli böyleydi, 

Süzdü baştan aşağı endamını ah dedi.

Sonra bir meltem esti serinden, 

Girdi yamalı pantalondan içeri oh dedi.

İşi vardı dairede, o bir vatandaştı, 

Çıktı merdivenleri şefin masasına dayandı, 

Bir zılgıt yedi, zinhar feleği şaştı, 

Dönmedi bile arkasına vah dedi.

Attı kendini sokağa kan ter içinde, 

Döndü baktı daireye fikri ziyan içinde, 

Yaktı bafrasını ters bir biçimde, 

Sonra farkına vardı tüh dedi.

Borcu vardı mahallenin bakkalına kasabına, 

Yedi yedi yazdırdı borç hesabına, 

Zamanı gelipte düşünce ödeme tasasına, 

Vurdu topukları kıçına yok dedi.

Vatandaş abuzerdi o ezelden, 

Köşeyi dönmekti amacı tezelden, 

Nem kapardı hafifçe esen yelden, 

Baktı şöyle bir kaderine yuh dedi.', 'O kendini bildi bileli böyleydi,  Süzdü baştan aşağı endamını ah dedi. Sonra bir meltem esti serinden,  Girdi yamalı pantalondan içeri oh de...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/vatandas-abuzer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farklısınız', 'farklisiniz-ayse-tural-56mbq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güne 

Merhabalarla başlayın

İçiniz kıpır kıpır

Siz siz oluverin

Aydınlık gülüşleriniz 

Isıtsın yürekleri

Gözleriniz çakışsın 

Sevgiler akıtsın 

Selamınız saygınız 

İnsanlık onuruna yakışsın

Çünkü siz farklısınız....', 'Güne  Merhabalarla başlayın İçiniz kıpır kıpır Siz siz oluverin Aydınlık gülüşleriniz  Isıtsın yürekleri Gözleriniz çakışsın  Sevgiler akıts...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tural']::text[], 8.5, '{"poet":"Ayşe Tural","poet_slug":"ayse-tural","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/farklisiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretim...', 'hasretim-yilmaz-sarper-cagribeg-2xweh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'HASRETİMSİN...

Kavruktur şimdi toprakları ülkemin.

Bir sapsarı uzanır göğün altında, 

Meltemler kar etmez susuzluğuna, 

Çatlar, yanar, kavrulur...

Yılanı, çiyanı, kuşları, böceği tekmilden kavruk...

Yine de çaresi yok, 

Toprağadır sımsıkı asılmaları.

Hem eli kulağındadır deli yağmurların.

“Minalayalar” yalan söylemedi ki hiç.

Karpaz’daki bulutlar aldatmadı ki kimseyi.

Tosbağaların gelişi boşuna mı sanki o kıyılara? 

Alıçların sabrındaki anlam; 

O kavruk toprağa yapışması, 

O inat, 

O sımsıkı tutunuşu...

Yağmur gelecektir gülüm.

Sert rüzgarların ardından, 

Bereketle çöküp Mesaryanın üstüne, 

Sağnaklarca...

Soy’dur bu topraklar gülüm.

Nasıl da cıvık çamura keser bilsen...

Yağmur kokusu, 

Toprak kokusu...

Toprağa yağmur düşmeye görsün; 

Çamur deyip geçmemeli.

Tohumun özü, hasadın zahmetli başlangıcı, 

Soylu bir sevişmedir bu! 

Toprağın, 

Yağmurun, 

Çamurun, 

Kısrağın Soy’u...

Benim er yüreğim duyumsar...

Toprağı, yağmuru, çamuru, kısrağın Soy’unu

Sevdanın hasını, 

Kadın yüreğinin yiğitliğini...

Ve ağlamışsan eğer; 

Duyumsar gülüm, duyumsar...

Kanayarak ve kana kana duyumsar...

Hasretim; yağmurca tutkulu, 

Döl rahmetinde sanadır gülüm.

Sana...', 'HASRETİMSİN... Kavruktur şimdi toprakları ülkemin. Bir sapsarı uzanır göğün altında,  Meltemler kar etmez susuzluğuna,  Çatlar, yanar, kavru...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Sarper Çağrıbeğ']::text[], 8.5, '{"poet":"Yılmaz Sarper Çağrıbeğ","poet_slug":"yilmaz-sarper-cagribeg","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/hasretim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgileri Yarına Bırakma', 'sevgileri-yarina-birakma-ayse-tural-hmndc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sakın 

Sevgileri yarına bırakma

Ürkek korkak davranma

Doğru bildiğini savun.

Ellerin

Sevgiyle uzanmalı ellere...

Bakışların pırıl pırıl 

Güller açmalı yüzünde...

Sakın

Sevgileri yarına bırakma

Soldurma ümitleri...

Boynu bükük kalmasın 

Gönüllerde umut çiçekleri...

Serin serin esmeli

Ferahlamalı için...

Yüreğini açsana

Sevgi rüzgarlarını

Kucak kucak saçsana....', 'Sakın  Sevgileri yarına bırakma Ürkek korkak davranma Doğru bildiğini savun. Ellerin Sevgiyle uzanmalı ellere... Bakışların pırıl pırıl  Gül...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tural']::text[], 8.5, '{"poet":"Ayşe Tural","poet_slug":"ayse-tural","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevgileri-yarina-birakma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğribacağın Meyhanesi', 'egribacagin-meyhanesi-yilmaz-sarper-cagribeg-lj132', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ekspresler geçti gözlerinden 

Vagon vagon...

Dördü on geçelerini yüklenmişlerdi sabahların.

Dönüp baktıkları yoktu.

Düşünemezlerdi gerçi ama, 

Beni aradıklarını biliyordum.

Beni aradınız mı; 

Eğribacağın meyhanesindeyimdir.

Eğribacağın meyhanesini bir görsen! 

Hele Brigitte’in resmini...

Anam babam Brigitte! 

Dudaklarını öyle bir uzatışı var ki...

Eğribacağın meyhanesinde bir eski gramafon.

Gramafonda taş plak.

Ve avazı çıktığı kadar

Ve yanık yanık söylüyor Abdullah Yüce

“Acıyıp lütfedip sevme istemem

Ölürsem kabrime gelme istemem”

Diye başlayan gazelini...

Abdullah Yüce bir yanda, 

Eğribacak bir yanda, 

Brigitte bir yanda, 

Kubilay, İbrahim, Deli Güvenç ve ben bir yanda.

Şimdi içilmez de ne halt edilir? 

Beni aradınız mı Eğribacağın meyhanesindeyimdir...', 'Ekspresler geçti gözlerinden  Vagon vagon... Dördü on geçelerini yüklenmişlerdi sabahların. Dönüp baktıkları yoktu. Düşünemezlerdi gerçi ama...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Sarper Çağrıbeğ']::text[], 8.5, '{"poet":"Yılmaz Sarper Çağrıbeğ","poet_slug":"yilmaz-sarper-cagribeg","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/egribacagin-meyhanesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Mektup', 'sevgiliye-mektup-ali-mesrefoglu-d00t2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gideli üç beş gün oldu

Zamanın ilerleyişini saniye saniye gözlüyorum

izliyorum saatimin kadranında hayalini

hayalin kayboluyor yavaş yavaş

Her geçen saniyede; 

Seni özlüyorum.

.

Ne zaman düneceksin geri? 

Oturmuş sonsuz bilinmeyenli denklem gibi

Hesaplıyorum dönüş gününü

Sonuçsuz kalıyor, kalıyorum.

.

Hayatım monotonlaştı iyice

Sensizlik beynimi

Beynim bedenimi hapsetti, 

Eski çılgınlılarımı yapamıyor

Bunalıyorum sensizlikten.

.

Sen neler yapıyorsun oralarda? 

Sahi niçin gittin sen

Beni üzmek için mi? 

Yoksa sınamak, değerini anlmak için mi? 

.

Ancak biliyorum sen de dayanamıyorsun

Fakat deneyin başarılı geçiyor sevdiğim

üzlüyor, özlüyorum

Ve seni 

Eskisinden çok

Seviyorum.

.

Senin de içinde yapraklar soldu, kırıldı

Onları yeşertecek benim sevgim eksik

Bütün yaşam isteğin kaçtı

Geri dönme isteğin arrtı, 

Uyuyamıyor geceleri, ağlıyorsun hayalimle

Beni çok özledin ve yarın gelyorsun değil mi? 

.

Çünkü herşeyi hissediyorum

Parçalarım konuşuyor artık

Parçalanmıştım gittiğin gün

Döndüğün gün birleşeceğim tekrar

beynim bedenim özgürlüğüne kavuşacak seninle

Saatime bakmayacağım artık

Hatta toprağa gömeceğim

Zamanın geçişine sen varken ihtiyacım yok.

Duvarlarıma da çentik atmam

Her geçen dakika için..

.

Gel artık yanıma

Boşa geçsenin saatlerimiz

ziyan olmasın beraber geçireceğimiz günler

Dön sevgilim

İkimize bu kadar hicran eyetr artar bile..', 'Gideli üç beş gün oldu Zamanın ilerleyişini saniye saniye gözlüyorum izliyorum saatimin kadranında hayalini hayalin kayboluyor yavaş yavaş H...', ARRAY['Türk Edebiyatı','Şiir','Ali Meşrefoğlu']::text[], 8.5, '{"poet":"Ali Meşrefoğlu","poet_slug":"ali-mesrefoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/sevgiliye-mektup-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lades', 'lades-murat-tali-ixcse', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Lades tutmuş gibiydim 

yerde çimen havada bulut 

sen bunu unut 

ama hep aklımdaydın 

kime lades olmasın diye 

çıkarmadım aklımdan

seni', 'Lades tutmuş gibiydim  yerde çimen havada bulut  sen bunu unut  ama hep aklımdaydın  kime lades olmasın diye  çıkarmadım aklımdan seni...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/lades-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kesili Gül', 'kesili-gul-ali-mesrefoglu-3dv0v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hataymış deli gülüm 

Bak işte hayatına mal oldu..

Her nekadar saklan dedimse de

Sen gösterdin kendini aşıklara; 

Hata olduğunu sen de anladın

Küçük çakıyı görünce...', 'Hataymış deli gülüm  Bak işte hayatına mal oldu.. Her nekadar saklan dedimse de Sen gösterdin kendini aşıklara;  Hata olduğunu sen de anladı...', ARRAY['Türk Edebiyatı','Şiir','Ali Meşrefoğlu']::text[], 8.5, '{"poet":"Ali Meşrefoğlu","poet_slug":"ali-mesrefoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kesili-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Adım Şiir', 'benim-adim-siir-ayse-tural-0w09a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben varım ya ben...

Öyle sessiz sedasız geliveririm

Usulca sokuluveririm

İnce ince dokunuşlarla

Yüreğinize dalıveririm

Benim adım şiir....

Bakışlarınızın 

Daldığı yerdeyim

Umutlarınızı derdiğiniz yerde...

Bir okyanusların en derininde

Bir, masmavi  göklerde

Erişilmez bulutların

Tepesindeyim bazen

Benim adım şiir....

Sonbahar  yapraklarında

Savrulan benim

İlkyaz yağmurlarının 

Kokusunda ben

Sahili öpen denizim

Ayakizlerini silen

Bir öpücüğüm sevgilini yanağında

Bir elvedayım

Sallanan mendillerde

Benim adım şiir...

Bir avuç sevgiyim belki

Bir damla gözyaşı

Süzülen yanaklardan

Umutların tükendiği

Katran karası 

Gecelerden biriyim...

Ansızın 

Yeniden doğuş olabilirim

Yaşama gülümseyişlerde

İçinizde yeşeren UMUT belki

Benim adım şiir....', 'Ben varım ya ben... Öyle sessiz sedasız geliveririm Usulca sokuluveririm İnce ince dokunuşlarla Yüreğinize dalıveririm Benim adım şiir.... B...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tural']::text[], 8.5, '{"poet":"Ayşe Tural","poet_slug":"ayse-tural","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/benim-adim-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Başka Dünya', 'bir-baska-dunya-ayse-tural-urgf5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevginle 

Zamanların dışındayım...

Dünlerin

Masal olduğu zamanlar...

Bakışların

İçimdeki taşları oynatıyor

Unufak oluyorum...

Dudaklarımdaki öpücüğün 

Düşlere daldırıyor beni...

İlkyaz sevinci bakışlarında

Çocuksu kahkahalar doldurur içimi....

Acıyan dizime konan öpücük

Bir başka dünyadır seninle yaşamak...

                                                               İstinye,3 Ağustos 2003', 'Sevginle  Zamanların dışındayım... Dünlerin Masal olduğu zamanlar... Bakışların İçimdeki taşları oynatıyor Unufak oluyorum... Dudaklarımdaki...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tural']::text[], 8.5, '{"poet":"Ayşe Tural","poet_slug":"ayse-tural","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-baska-dunya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tek Mavilik Kaldı Yerinde', 'bir-tek-mavilik-kaldi-yerinde-okay-yildiz-9meh9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her şey gitti, 

Bir tek mavilik kaldı yerinde...

Haykırışlarım yormaya başlamıştı beynimi.

İnandırıcı gelmiyordu yankılarımın bana söylediği yüzlerce öğüt.

cesaretti benim için susup da dinlemek sessizliği.

İçinde aramak  bazı sesleri.

Artık anlamı yoktu gözlerimi açık tutmanın.

Elimle şekiller yapıp, görmediklerimin adını koymanın

Saçlarımı okşayarak uzadığını hissetmenin, 

Kestirmek isteyişimin, 

Tırnaklarımla kanatarak suratımı bir şekil vermenin.

Nefes almanın bir anlamı yoktu. 

Uykuydu  galiba.

Varolandan uzaklaştıran beni.

Hangisi gerçekti bilmiyorum.

Ama isterdim bir yeşillik önümde olsun, 

Bir koku gelsin burnuma küf kokusuna benzemeyen.

Bir farklı ses duymayı isterdim.

Önceden vardı.

Evet, uyku değildi hatırladıklarım, 

Bir yüz var gözümde hiç silinmeyen.

Bir ağlama sesi, 

Ve, 

Ve bir kırmızılık...

Hayır! uykuydu bunlar.

Uyku olsun ne olur! 

Ben niye buradayım.

Ben neden kaçıyorum. 

Kim  koydu bu karanlığa bedenimi.

O yüz kime ait.

Önceden karanlığın dışını gezerdim.

Bir çocuk sesi duyardım.

Ağlayanlar kuş yavrularıydı galiba.

Su ses çıkarıyordu kendi başına, usulca akarak.

Bir mavilik ve parlaklık vardı üstünde.

Karanlığın sırrımıydı. 

Ayaklarımı parçalayan demir teller hatırlıyorum.

Dev  duvarları, 

Bağıranlar vardı etrafımda, 

Çığlıklar, bağırışlar

Ve sessizlik.

Her şey gitti

Bir tek mavilik kaldı yerinde.

Demirlerle ayrılmış ve bazen yok olan.', 'Her şey gitti,  Bir tek mavilik kaldı yerinde... Haykırışlarım yormaya başlamıştı beynimi. İnandırıcı gelmiyordu yankılarımın bana söylediği...', ARRAY['Türk Edebiyatı','Şiir','Okay Yıldız']::text[], 8.5, '{"poet":"Okay Yıldız","poet_slug":"okay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/bir-tek-mavilik-kaldi-yerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hapsetmişim Seni İçime', 'hapsetmisim-seni-i-cime-ali-mesrefoglu-5v22g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hapsetmişim seni içime

Bütün tezatlığımızla...

Sen benim kavgamsın

Umudum, geleceğim, hayatımsın.

Sen benim kaynağım

Beni ben yapan varlığımsın, 

Mimarım, aşkım sevgilimsin

Hapsetmişim seni içime...

.

Hapsetmişim seni içime

Bütün tezatlığımızla...

Senin beni sana hapsettiğin gibi

Beni yollara düşürdüğün

Ağlattığın, güldürdüğün gibi

Yaşarken öldürdüğün; 

Ölürken yaşattığın gibi

kendine bağladığın gibi

Hapsetmişim seni içime...

.

Hapsetmişim seni içime

Bütün tezatlığımızla...

İçime girdin çıkmayacağını bile bile; 

Ben de senin içindeyim biliyorum

Çıkamayacağımı düşünmeksizin

Vazgeçemediğim sigaram

Terkedemeyeceğim ümidim

Bitiremeyceğim şiirim gibi

Hapsetmişim seni içime.....', 'Hapsetmişim seni içime Bütün tezatlığımızla... Sen benim kavgamsın Umudum, geleceğim, hayatımsın. Sen benim kaynağım Beni ben yapan varlığım...', ARRAY['Türk Edebiyatı','Şiir','Ali Meşrefoğlu']::text[], 8.5, '{"poet":"Ali Meşrefoğlu","poet_slug":"ali-mesrefoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hapsetmisim-seni-icime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-ayse-tural-9u6iq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Küçük dünyanda

Büyük dünyalar yarat

Yaşam bir armağandır

Unutma....', 'Küçük dünyanda Büyük dünyalar yarat Yaşam bir armağandır Unutma.......', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tural']::text[], 8.5, '{"poet":"Ayşe Tural","poet_slug":"ayse-tural","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-283-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzyıl...', 'yuzyil-hakan-komurcu-hdnx6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ben hala sürüyorum ayaklarımı

yüzyıla inat, 

dilencilere kanıyor

olur olamaz, virgülsüz cümleler kuruyorum...

sen hala tırnaklarını yiyormusun

bana inat, 

çarçabuk ağlıyormusun

anıyormusun beni yüzyıla inat....', 'ben hala sürüyorum ayaklarımı yüzyıla inat,  dilencilere kanıyor olur olamaz, virgülsüz cümleler kuruyorum... sen hala tırnaklarını yiyormus...', ARRAY['Türk Edebiyatı','Şiir','Hakan Kömürcü']::text[], 8.5, '{"poet":"Hakan Kömürcü","poet_slug":"hakan-komurcu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yuzyil-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir hastanenin acil servisinde büyüyorum', 'bir-hastanenin-acil-servisinde-buyuyorum-aysenur-yazici-yxskp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Yaşa'' diyerek attılar buralara beni

Toprak,  bildiğim toprak değil, 

''dal '' sandığım koskoca bir gemi! 

mülteciyim  desem değil

bilemediğim bir memleket buraları

ne içgüdüm yol gösterir

ne öncekilerin anlatılmış hikayeleri..

tökezledikçe kırılır dizkapaklarım

ne ben doğrulabilirim

ne de kaldırabilir beni elalemin elleri

Bir hastanenin acil servisinde büyüyorum 

kan verildikçe kanamam artar

ne can veririm, ne iyileşir..

bildiklerinin hepsini unutmuş doktorlar

kalbimde unutulmuş tüm neşterler

sargı bezleri  yumak yumak dil altımda

serum dedikleri görünmez izmaritler yüzer

mavi olmaktan uzak damarlarımda

 kalp ameliyatım özürlü yapılmıştır üstelik! 

...başkasının soluğuna bağlamışlar nefesimi

dikerken içinde ''birini '' unutmuşlar

kapakçıkları tıkalı, içinde pıhtı ve kemik..! 

ölmekten ''kısa'' diye vazgeçtim

ama yaşamak daha büyük  delilik

..ve illaki  birileri bırakmıştır beni

çocuk esirgeme adına hastane kapılarına

cami avluları ağlar bir taraftan, 

bir yandan talan edilmiş insanlıklar

töresini bilmediğim bu dünyada ''yaşa''diye

zorlarlar  ha zorlarlar...', '''Yaşa'' diyerek attılar buralara beni Toprak,  bildiğim toprak değil,  ''dal '' sandığım koskoca bir gemi!  mülteciyim  desem değil bilemediğim...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bir-hastanenin-acil-servisinde-buyuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cilve Naz', 'cilve-naz-hasan-aydin-ga0us', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Arz-ı nefs çirkin işi güzele has cilve naz

Tarz-ı mutadındır naz ne kadar nazlansan az

Bir tek gamzen içindir aşkın ile yanmağım

Ümit etmiş değilim bundan özge bir ivaz

Ağyar sanır ziyandır bu ahz ü kabzdan kârım

Kadri erbabı bilir güle baykuş ağlamaz

Visal merbut ne çare yâr elinden ölmeye

Bilir ecelini de can yâre eder pervaz

Nazlan Ey Melek haktır mahbubeye cilve naz

Naz ki senin tâbındır ne kadar nazlansan az

KARAKIŞTA KİRAZ

Fuzulî okumakla şair oldum sanan lâz

At şimdi Üsküdar’da boş yere etme niyaz

Mürekkep sudan ucuz kağıt ganimet gibi

İlham zaten bedava aklına geleni yaz

Kaleme mahkûm olmak gölge eder şanına

Hem aşk yavan çekilmez biraz talim eyle saz

Evlâdım işin yok mu, bak sen kendi işine! 

Kara kışta fakirin neyine gerek kiraz.', 'Arz-ı nefs çirkin işi güzele has cilve naz Tarz-ı mutadındır naz ne kadar nazlansan az Bir tek gamzen içindir aşkın ile yanmağım Ümit etmiş ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Aydın']::text[], 8.5, '{"poet":"Hasan Aydın","poet_slug":"hasan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cilve-naz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Makinist', 'makinist-ahmet-aksoy-4h1ap', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben bir makinistim

Ömür treninde

Bazen tik tak bazen çuf çuf

Her saat bir durak olmuş

Lakin istasyon neye yarar

Dinlenecek vakit olmadan

Öyle bir tren ki bu tren

Aydınlık geçmişten karanlığa giden.', 'Ben bir makinistim Ömür treninde Bazen tik tak bazen çuf çuf Her saat bir durak olmuş Lakin istasyon neye yarar Dinlenecek vakit olmadan Öyl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/makinist-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Canım', 'ah-canim-ahmet-aksoy-m3h0c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ah canım ah canım

Neden yanıyorsun böyle

Kaybettiğine mi yanarsın söyle 

Gözlerin mi kör olmuş yoksa canım

Mutluluğun yanı başındayken

Görmez olmuş gözlerin

İşte fırsat kaybettiğini 

Tekrar kazanmak için

Kaybettiğin aşkındı canım

Yanma boşuna aşk senin 

Sevgi senin 

Bir çiçek gibi büyütmek varken

Neden hala yanıyorsun böyle

Ölen çiçekler ölür ama

Yeni tohumlar senin

Vaktin hala var canım.', 'Ah canım ah canım Neden yanıyorsun böyle Kaybettiğine mi yanarsın söyle  Gözlerin mi kör olmuş yoksa canım Mutluluğun yanı başındayken Görme...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ah-canim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsağım', 'tutsagim-ahmet-aksoy-8hphl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kodese düşmüş umutlar

Kurtarılmayı bekler

Suçları bir zeytin dalı

Suçları bir yeşil olmak

Ne haddime umutlanmak

Ne haddime kurtulmak

Umutlar bile mahkum

Umutlar bile kodeste artık.', 'Kodese düşmüş umutlar Kurtarılmayı bekler Suçları bir zeytin dalı Suçları bir yeşil olmak Ne haddime umutlanmak Ne haddime kurtulmak Umutlar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tutsagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılmadım', 'yilmadim-ahmet-aksoy-9hu9g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Batak batak her yer

Ayaklarımdan belime kadar

Çamur içindeyim

Çıkamıyorum bir türlü

Hayır henüz bitmedi

Daha bu çamur

Boğazımı geçmedi

Hala bir umut var

Hala bir umut var

Aydınlık günlere temiz çayırlara

Ama önce kurtuluş gerek

Bana bir el gerek bataklıktan çıkmaya.', 'Batak batak her yer Ayaklarımdan belime kadar Çamur içindeyim Çıkamıyorum bir türlü Hayır henüz bitmedi Daha bu çamur Boğazımı geçmedi Hala ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yilmadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna', 'ayna-ahmet-aksoy-lg021', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben bir aynayım

Bana baktığında 

Kendini görürsün

Ne eksik ne fazla

(Vurursan vurulur

Kırarsan kırılırım

Ben hep buradayım

Ben bir aynayım) 

Dayanmıyorsa yüreğin

Bakma o zaman

Dost acı söyler ne yapayım

Ben bir aynayım

(Vurursan vurulur

Kırarsan kırılırım

Ben hep buradayım

Ben bir aynayım) .', 'Ben bir aynayım Bana baktığında  Kendini görürsün Ne eksik ne fazla (Vurursan vurulur Kırarsan kırılırım Ben hep buradayım Ben bir aynayım) ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayna-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba-Oğul', 'baba-ogul-hasan-aydin-enw1z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(E.Ekrem TALÛ’nun “Dedim-Dedi”sinden adaptasyondur.)

Karne aldık bak dedim

Lâmbayı bir yak dedi

Sonra bakarsın dedim

Pek ettim merak dedi

Vaziyet fena dedim

Hazırdır dayak dedi

Bu sefer affet dedim

Yalvarmak yasak dedi

Elin de yara dedim

Sopam pek kıyak dedi

Kaçıyorum ben dedim	

Hele kaç ta bak dedi

Ne yaparsın ki dedim

Ölüm sana hak dedi

Ciddi misin sen dedim

Ne sandın salak dedi

Desene yandık dedim

Hem de ne yanmak dedi

Bari yavaş vur dedim

Şakayı bırak dedi

Sonra alıp değneği 

Şöyle bir “Yâ Hakk! ” dedi

Sopa sanki kırk defa 

Kafamda “Tak! ” “Tak! ” dedi.', '(E.Ekrem TALÛ’nun “Dedim-Dedi”sinden adaptasyondur.) Karne aldık bak dedim Lâmbayı bir yak dedi Sonra bakarsın dedim Pek ettim merak dedi Va...', ARRAY['Türk Edebiyatı','Şiir','Hasan Aydın']::text[], 8.5, '{"poet":"Hasan Aydın","poet_slug":"hasan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/baba-ogul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salinip Giderken Boyunu Gördüm', 'salinip-giderken-boyunu-gordum-asik-veysel-satiroglu-k6n92', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Salinip giderken boyunu gördüm

Selvi miydi fidan miydi boy muydu

Egmis kislarini yayini gördüm

Kilic miydi gamze miydi yay miydi

Güzel keklik gibi geziyor tasta

Gören asiklari yakar ateste

Avazi bülbülde sedasi kusta

Keklik miydi turna miydi toy muydu

Taramis zülfünü dökmüs gerdana

Yel estikce dalgalanir her yana

Dedim dilber cevir yüzün bak bana

Gözleri yildiz al yanaklar ay miydi

Arasan dünyayi bulunmaz esi

Siyah bulut perdelemis günesi

Ah cekti gözünden sel etti yasi

Deniz miydi derya miydi cay miydi

Veysel Satir beyan eder derdini

Terkedemem ezberini virdini

Dilim tutup soramadim yurdunu

Yayla miydi kasaba mi köy muydu', 'Salinip giderken boyunu gördüm Selvi miydi fidan miydi boy muydu Egmis kislarini yayini gördüm Kilic miydi gamze miydi yay miydi Güzel kekli...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veysel Şatıroğlu']::text[], 8.5, '{"poet":"Aşık Veysel Şatıroğlu","poet_slug":"asik-veysel-satiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/salinip-giderken-boyunu-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Mirası', 'dunya-mirasi-i-brahim-ugur-toprak-eegzk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hey gidi İstanbul! 

Alnımın yazısı, 

Dünya Mirası.

Gün gelip, saat çattığında, 

Ben dönüşsüz yola çıktığımda, 

Ardımdan yalnızca sen ağla 

İstanbul''um, yalnızca sen! 

Gazeteler üçüncü sayfadan vermesin

Ölüm haberimi.

Anam bilmesin

Gittiğimi ve bir daha dönmeyeceğimi.

Bunu yalnızca sen bilmelisin

İstanbul''um, yalnızca sen! 

Hey gidi İstanbul! 

Alnımın yazısı, 

Dünya Mirası.

Şimdi kilometrelerce uzağımdasın.

Gündüzleri hayalimde, 

Geceleri rüyamda.

Yediğim ekmeğimde, 

İçtiğim şarabımdasın.

Aldığım her soluğumda…

Az kaldı İstanbul''um,

Az kaldı, bekle.

Bir gün mutlaka döneceğim, 

Yüreğimde tarifsiz bir özlemle.

Ve ben döndüğümde 

Çiçekler açmış olacak her yerde.

Sen ağlayacaksın öldüğüme, 

Bense, sevineceğim sana erdiğime.

Hey gidi İstanbul! 

Alnımın yazısı, 

Dünya Mirası.

Beni kollarının arasına al.

İster Yerebatan Sarnıcın’a, 

İstersen Ayasofyan''a göm.

Çünkü; 

Doğacağım nasıl olsa

Her sabah Çengelköy''den,

Seni seyredeceğim Sultanahmet''ten.

Bakacağım anama ve sana 

Adalar''dan

Ve batacağım her akşam Çamlıca''dan.

Unutmadan! 

Anama da iyi bak.

Sen nasıl Dünya Mirasıysan bana, 

Anam da benim mirasımdır sana.

O’na benim için iyi bak.

Hey gidi İstanbul! 

Alnımın yazısı, 

Dünya Mirası, 

Koca İstanbul! ..

05.12.01

 İzmir', 'Hey gidi İstanbul!  Alnımın yazısı,  Dünya Mirası. Gün gelip, saat çattığında,  Ben dönüşsüz yola çıktığımda,  Ardımdan yalnızca sen ağla  İ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/dunya-mirasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaralı', 'yarali-i-brahim-ugur-toprak-wx1rf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kuş var gönlümde, 

Gönül evinden vurulmuş.

Yaralı, öylece yatıyor.

Ve bir el bekliyor, 

Sarması için yaralarını.

21.04.99/Çarşamba

    21:33/Tekirdağ', 'Bir kuş var gönlümde,  Gönül evinden vurulmuş. Yaralı, öylece yatıyor. Ve bir el bekliyor,  Sarması için yaralarını. 21.04.99/Çarşamba     2...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yarali-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün', 'bir-gun-i-brahim-ugur-toprak-43r6h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün göçüp gitsem de, 

Ben bu diyardan

Sessiz, sedasız.

Bir gün terk - i diyar etsem de, 

Bu dünyadan

Apansız.

Bu böyle olmamalı, 

Ömrüm bir gül gibi solmamalı.

Her ne olursa olsun sebebim, 

Ben ölmemeliyim

Terk etmemeliyim

Bu dünyayı

Tek başıma, yapayalnız.

Bir sevenim olmalı, 

Ardımdan gözyaşı dökenim.

Her ne kadar yalnız da doğsam, 

Ben yalnız ölmememliyim.

22.01.99/Cuma

00:08/Tekirdağ', 'Bir gün göçüp gitsem de,  Ben bu diyardan Sessiz, sedasız. Bir gün terk - i diyar etsem de,  Bu dünyadan Apansız. Bu böyle olmamalı,  Ömrüm ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-gun-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm Dünya', 'gulum-dunya-nurullah-celik-a5k5h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ulan dünya gülüm dünya, 

Kime kaldın, kime kaldın? 

Gün doğmadan şu gönlüme, 

Sevdiğimi benden aldın.

Göçüp gitti toprağına, 

Tüm acılar ta bağrıma, 

Beni de kat ırmağına, 

Ulan dünya, zalım dünya, 

Ulan dünya, gülüm dünya.', 'Ulan dünya gülüm dünya,  Kime kaldın, kime kaldın?  Gün doğmadan şu gönlüme,  Sevdiğimi benden aldın. Göçüp gitti toprağına,  Tüm acılar ta ...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Çelik']::text[], 8.5, '{"poet":"Nurullah Çelik","poet_slug":"nurullah-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gulum-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Savaş Var', 'bir-savas-var-i-brahim-ugur-toprak-rpef8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir savaş var, sonucu ortada.

Ölmekle, yaşamak arasında.

Ya yatılacak ebedi uykuya, 

Ya devam edilecek yaşamaya.

Büyük bir savaş var dünyada, 

Ölmekle, yaşamak arasında.

04.10.98/Pazar

14:15/Tekirdağ', 'Bir savaş var, sonucu ortada. Ölmekle, yaşamak arasında. Ya yatılacak ebedi uykuya,  Ya devam edilecek yaşamaya. Büyük bir savaş var dünyada...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-savas-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Gibi', 'benim-gibi-i-brahim-ugur-toprak-9iqwk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sıkıntılı bir geceyi daha

Geçirdim soru sorarak.

Derken, bir bulut geldi yanıma.

O da benim gibi, herhalde dertliydi.

Oldu derdime ortak.

Beraber geçirdik geceyi, 

Ağlayarak.

16.05.98/C.tesi

11:59/Tekirdağ', 'Sıkıntılı bir geceyi daha Geçirdim soru sorarak. Derken, bir bulut geldi yanıma. O da benim gibi, herhalde dertliydi. Oldu derdime ortak. Be...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/benim-gibi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Orada Kal', 'sen-orada-kal-oguzkan-bolukbasi-q0wkj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rengi hüsrana dönmüşken toprakların

Bir yağmur yağdırdın çöller üstüne

Umuttu yeşeren çiçeklerin adı

Beklenmezken birdenbire

Gece güneş doğdu aştı maksadı

Şaşırdım

Şaşırmamayı huy edinmişken

Terk-i diyar terk-i aşk demek

Sana taşınamam ki

Mekanına sığmaz benimle olanlar

Yani şiirler

Yani sevdalar

Yani beni ben yapan anılar

Sen orada kal

Bende yer varsa da sen orada kal

Yağdırdığın yağmurların kokusu

Estirdiğin rüzgarların coşkusu

Gelir bulur beni

Gelir vurur beni

Sensizlik soldurur beni

Sen orada kal', 'Rengi hüsrana dönmüşken toprakların Bir yağmur yağdırdın çöller üstüne Umuttu yeşeren çiçeklerin adı Beklenmezken birdenbire Gece güneş doğd...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-orada-kal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceket', 'ceket-safak-kilinc-xujpe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir çay bahçesiydi

Kıştı, ayaz esiyordu.

Soğuktan değilde

Hüzünlerden yüreklerimiz üşüyordu.

Titremiştinde.

Omuzlarına vermiştim ceketimi.

Isındım o gece

Unutmadım deiştin.

Her ceket ısıtırdı 

Ayaz rüzgarlarda üşüyen bedenini.

Eğer ısıtabiliyorsam yüreğini

O sıcaklıkla sev beni

Çünkü gördüm ben 

Güneş altında bedeni yanıp, 

Yüreği üşüyenleri....

                                          03,03,2003', 'Bir çay bahçesiydi Kıştı, ayaz esiyordu. Soğuktan değilde Hüzünlerden yüreklerimiz üşüyordu. Titremiştinde. Omuzlarına vermiştim ceketimi. I...', ARRAY['Türk Edebiyatı','Şiir','Şafak Kılınç']::text[], 8.5, '{"poet":"Şafak Kılınç","poet_slug":"safak-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ceket-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bülbül', 'bulbul-i-brahim-ugur-toprak-dxc18', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün gelip yanına, 

''Seviyorum'' desem sana.

Söyle, ne dersin bana, 

Sever misin, benim sevdiğim gibi, 

Gelir misin, benim geldiğim gibi? 

Bilir misin seni nasıl sevdiğimi, 

Bülbül desem yeterli mi, 

Anlatabilir mi hislerimi, 

Anlatabilir mi seni nasıl sevdiğimi? 

Bir gün gelip yanına, 

''Seviyorum'' desem sana.

''Ben de seni'' der misin, 

Benim sevdiğim gibi, 

Söyle, sen de sever misin? 

14.04.98/Salı

21:29/İstanbul', 'Bir gün gelip yanına,  ''Seviyorum'' desem sana. Söyle, ne dersin bana,  Sever misin, benim sevdiğim gibi,  Gelir misin, benim geldiğim gibi? ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bulbul-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizim', 'sensizim-i-brahim-ugur-toprak-sm1a3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yanımda mavi derin bir deniz, 

Karşımda birkaç ada ki emsalsiz.

Bir yanımda yeşil uzun kırlar, 

Ve neşeyle gülen insanlar.

Bense, bu güzelliğin tam ortasındayım, SEVDİĞİM

Bu harikalar diyarında, yalnız ve SENSİZİM

10.04.98/Cuma

 14:37/İstanbul', 'Bir yanımda mavi derin bir deniz,  Karşımda birkaç ada ki emsalsiz. Bir yanımda yeşil uzun kırlar,  Ve neşeyle gülen insanlar. Bense, bu güz...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sensizim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldız', 'yildiz-i-brahim-ugur-toprak-8syct', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yıldız kayarken gökten, 

Sevdiğimi söylesem sana yürekten.

Sen de söylesen bana sevdiğini içten, 

Gökten bir yıldız kayarken.

04.04.98/C.tesi

19:32/Tekirdağ', 'Bir yıldız kayarken gökten,  Sevdiğimi söylesem sana yürekten. Sen de söylesen bana sevdiğini içten,  Gökten bir yıldız kayarken. 04.04.98/C...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yildiz-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirmiydik Kıymetini', 'bilirmiydik-kiymetini-safak-kilinc-w6xfg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilirmiydik kıymetini

İlkyaz çiçeklerinin

Hazanda sarı yapraklar

Çıplak ağaçlar olmasa.

Bilirmiydik kıymetini

Bir kemanın telindeki çığlığın

Bir sazın telindeki sevdanın

Elektronik sanal sesler olmasa.

Bilirmiydik kıymetini

sadakatın, vefanın

Çevremizde onca yalan, riya

Ve hatta ihanet olmasa.

Bilirmiydik kıymetini

Sağlığın, sıhhatin

Şu doyasıya yedirtmeyen

Yesen, bıçakla nöbet bekleyen

Ülser olmasa.

Bilirmiydik kıymetini

Kazanmanın

Kazandıklarımıza sahip çıkmanın

Kaybettiklerimiz, yitirdiklerimiz olmasa.

Bilirmiydik kıymetini

Sevgiliye kavuşmanın

Kırarcasına göğsüne bastırmanın

Ayrılıklar, hasret olmasa.

Bilirmiydik kıymetini

En küçük sevinçlerin

Kendi ellerimizle yarattığımız

Üst üste yığdığımız acılar olmasa

Bilirmiydik kıymetini.....

                                         12,08,2003', 'Bilirmiydik kıymetini İlkyaz çiçeklerinin Hazanda sarı yapraklar Çıplak ağaçlar olmasa. Bilirmiydik kıymetini Bir kemanın telindeki çığlığın...', ARRAY['Türk Edebiyatı','Şiir','Şafak Kılınç']::text[], 8.5, '{"poet":"Şafak Kılınç","poet_slug":"safak-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bilirmiydik-kiymetini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Durak', 'son-durak-i-brahim-ugur-toprak-c0zdt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Durdurun dünyayı, 

Azrail kapıya dayandı.

Geldik işte yolun sonuna, 

Geldik son durağa.

Gidiyoruz insanoğlu

Doğanın kanunu bu.

Kader defterinde böyle yazar

Hayat! Hayat buraya kadar.

Yolun sonu burası, 

Yoktur senin için, 

Buradan sonrası.

Geldik işte son durağa

Güle güle dünya, 

Ahirete merhaba.

Ey Dost! Arkamdan ağlama.

Hatırlamak istersen eğer, 

Dön de maziye bak.

Şarkılara, şiirlere, resimlere bak.

Bir gün nasıl olsa, 

Sen de geleceksin buraya

Çünkü, burası SON DURAK! ..

12.05.98/Salı

20:54/İstanbul', 'Durdurun dünyayı,  Azrail kapıya dayandı. Geldik işte yolun sonuna,  Geldik son durağa. Gidiyoruz insanoğlu Doğanın kanunu bu. Kader defteri...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/son-durak-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pranga mahkumu', 'pranga-mahkumu-safak-kilinc-erjtc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ömür boyu hasret yemiş

Pranga mahkumuyum.

Çakmak çakmak kıvılcımlar gözlerimde.

Seni her düşündüğümde.

Altın gerdanlık gibi taktım

Özlem prangasını

Gönlümün en nadide köşesine.

Ömür boyu hasret yemiş

Pranga mahkumuyum.

Hiç bir yere kıpırdatmayan zincirler değil de

Gözlerimden kan damlar

Yaş değil de

Zalim celladın kırbacı gibi

Tamda yüreğime

Ömür boyu hasret yemiş

Pranga mahkumuyum.', 'Ömür boyu hasret yemiş Pranga mahkumuyum. Çakmak çakmak kıvılcımlar gözlerimde. Seni her düşündüğümde. Altın gerdanlık gibi taktım Özlem pra...', ARRAY['Türk Edebiyatı','Şiir','Şafak Kılınç']::text[], 8.5, '{"poet":"Şafak Kılınç","poet_slug":"safak-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/pranga-mahkumu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanki', 'sanki-safak-kilinc-ron7m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sanki, 

Tüm acılar

Tüm hüzünler

Donmuş gıda gibiymişler

Kim çıkardı buzluktan

Hepsi ardıardına

Hiç aratmadan

Çözüldüler', 'Sanki,  Tüm acılar Tüm hüzünler Donmuş gıda gibiymişler Kim çıkardı buzluktan Hepsi ardıardına Hiç aratmadan Çözüldüler...', ARRAY['Türk Edebiyatı','Şiir','Şafak Kılınç']::text[], 8.5, '{"poet":"Şafak Kılınç","poet_slug":"safak-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sanki-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmece', 'bilmece-i-brahim-ugur-toprak-y4q8c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seven insan; 

Labirente benzer bir kalpte

Kaybolmuş bir adam mı? 

Yoksa, 

Uçsuz bucaksız ve bir o kadar da

Karanlık bir tünelin sonunda

Görülen, bir ışığa doğru, durmadan

Yürüyen bir insan mı? 

09.11.98/P.tesi

23:51/Tekirdağ', 'Seven insan;  Labirente benzer bir kalpte Kaybolmuş bir adam mı?  Yoksa,  Uçsuz bucaksız ve bir o kadar da Karanlık bir tünelin sonunda Görü...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bilmece-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ebedi Dostuma!', 'ebedi-dostuma-i-brahim-ugur-toprak-yc5d9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne zaman bir yağmur yağsa, 

Ben, hep o geceyi hatırlarım.

Ne zaman bir insan bakakalsa yağmura, 

Hep, o geceki halimizi anımsarım.

Ne zaman kapılıp gitsem bir rüzgara, 

O, sıcak akşama sarınırım.

Ne zaman bir şarkı çalsa radyoda, 

İki dost ne zaman konuşsa yağmur altında, 

Gurbetteki günlere yanarım.

Ne zaman dalgalar vursa kumsala, 

Ne zaman martılar çığlık atsa, 

Bana bir haber getirdiler sanırım.

Ve, ne zaman dalıp gitsem engin akşamlara, 

Ne zaman alışmak istese bedenim yalnızlığa, 

İşte o an, 

İşte o zaman, 

Dostluğumuza sarılırım.

 15.12.98/Salı

10:44/Tekirdağ', 'Ne zaman bir yağmur yağsa,  Ben, hep o geceyi hatırlarım. Ne zaman bir insan bakakalsa yağmura,  Hep, o geceki halimizi anımsarım. Ne zaman ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ebedi-dostuma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda Mektubu 1', 'veda-mektubu-1-sedat-sakabey-baysal-ybphu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hani, 

Yağmur Yağdığında Toprak, 

Nasıl Tüterse Sımsıcak, 

İşte Öyle Yüreğim Şimdi, 

Ipıslak.

Yemin Ederim! 

Sana Kızmıyorum.

Hatta, 

Kırgın Bile Değilim Hayata.

Yiğit Urbası Giymiş, 

Bu Kadar Kahpe Varken Dünyada, 

Sana Ne Verdim Ki Ben? 

Ne Verebildim? 

Sevgimden Başka.

....................

Sözlerin Sükutuyla Beraber, 

Gözler Dile Gelirler.

Neyleyim? ..

Bir Tek O Dili Bilirim.

Kırk Kilit Var Yüreğimde, 

Senin Duymak İstediğin Sözü Söylemek İçin, 

Ölürüm! ...

Cesedimi Cımbızla Çeksen, 

Titremezse Hiçbir Organım, 

Öldüğümden Değil Suskunluğum, 

Yorgunum...

Bu Son Durak Değil Senin İçin, 

Sondan Bir Önceki Belki? ...

Sen, 

Bana Bakma Güzelim.

İnadına, İnadına İşte, 

Güzelimmmm...

Unutmazsın Biliyorum, 

Bir Tek Sen Satmazsın Beni.

Ama Terk  et Ne Olur? 

Terk et, Vur, Ya Da Öldür.

Yıkma Kaşını, 

Eğme Başını.

Kartallar Yalnız Yaşar Bir Kaya Kovuğunda, 

Dünyanın Sonu Değil ki Yapayalnız Kalmak, 

Gün Ortasında....

Hüzünmüş! ...

Sünger Gibi Yüreğim.

Sıksan Sel Gibi Akar Ama, 

Kilit Vurdum Yüreğime, 

İnadına.

Göz Yaşlarına Gömdüm Yüreğimi.

Eğer Ağlarsan Benim Yüzümden, 

Akar Giderim.

İşte O Zaman Hayatından, 

Çıkar Giderim.

Zor Olacak Biliyorum, 

Beni, Gülerek Terk et.

Çivi Çak Yüreğime, 

Bir Daha Atamasın, 

Sevecekse Bir Başkasını Eğer, 

Yaşamasın.

Yalvarmak Yoktu Lügatımda Dün, 

Yarın Da Olmayacak.

Ama Bu Gün, 

Sana Yalvarıyorum, 

Durdur Sevda Trenini Artık.

Beni, 

Aynı Durakta Bırak.

Ben, 

Tiryakisi Olmuşum, 

Sahte Sevdaların.

Avunup Duruyorum İçinde, 

Riyakarlıkların.

Bu Dünyada Ne Ekersen, 

Onu Biçersin Diyorlar, 

Ölünce.

Beni Kandırdığını Sananlar Biliyorum, 

Çok Şaşıracaklar, 

Ben Gülünce.

Güzelim, 

Bir Tek Sana Borçluyum, 

Sevdalarımı...

Seni Orada Beklemek İçin, 

Bıçakla Kestim, 

Rüyalarımı...

Haydi Kapat Artık Bu Sayfayı.

Yırt At Bu Şiiri De Çöp Sepetine.

Yep Yeni Bir Gün Doğacak Yarın.

Biliyorum.

Yeniden Yeşerecek Bir Başka Bahçede, 

Sevdaların.

Görüyorum...                                                                                             03.03.03', 'Hani,  Yağmur Yağdığında Toprak,  Nasıl Tüterse Sımsıcak,  İşte Öyle Yüreğim Şimdi,  Ipıslak. Yemin Ederim!  Sana Kızmıyorum. Hatta,  Kırgın...', ARRAY['Türk Edebiyatı','Şiir','Sedat Sakabey Baysal']::text[], 8.5, '{"poet":"Sedat Sakabey Baysal","poet_slug":"sedat-sakabey-baysal","theme":"Türk Şiiri","is_hero":false,"total_lines":88,"source_url":"https://www.antoloji.com/veda-mektubu-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda Mektubu 2', 'veda-mektubu-2-sedat-sakabey-baysal-mb4cg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sıradan bir yaz günü, 

Sakin, Sessiz...

Havada, 

Yaprak kımıldamıyor, 

Her şey hareketsiz.

Durağan her şey, 

Canlar nefessiz...

Bir can soluk alıyor, 

Soluk veriyor, 

Umudunu yitirmiş yaşamdan, 

İsteksiz....

Sanki sonu gelmiş yaşamın, 

Enerjisi tükenmiş, 

Bekliyor öylece gelmesini, 

Akşamın.

Birden gök yüzünde bulutlar, 

Fırtına ve rüzgar.

Derken, 

İlk damlaları yağmurun, 

Mezarından kalkıyor toprak, 

Yeşermeye duruyor, 

Yaprak...

Küçük bir şimşek çakıyor, 

Alaca karanlığında akşamın.

İncecik narin bir ışık, 

Yeniden doğuşunda yaşamın.

Bir umut! ..

Denesem mi? ..

Bu ışıktan haleyi içime, 

Bir nefes gibi, 

Çeksem mi? ..

.

İçim kıpır kıpır artık, 

Sakın akşam olmasın, 

Ruhumu dolduran bu ışık, 

Solmasın..

Zaman dursun bam telinde, 

Artık akşam olmasın.

İçimdeki yıldırım, 

Durmaz deprenir.

Kabım dar mı geliyor ne? 

Nefesim yetişmiyor, 

Hayat dolu nefesine...

Sakın, sakın bırakma! ...

Ruhuna can veren canı, 

Ama, ...

Sığamıyor kabına.

Sen Yetişemezsin ki, 

Yıldırımın hızına...

Kapat ellerini, 

Sık yüreğini.

İçine hapset, 

Sevgilerini..

.

.

.

Denedim bir tanem, 

Denedim olmuyor...

Hazan ile ilkbahar, 

Aynı kaba dolmuyor.

Yeniden bulutlanırsa Gözlerin, 

Hüzün çökerse dünyana Yeniden, 

Bakamam gözlerine.

Dayanamam, 

Sen kabına sığmayan mutluluk, 

Aç kanatlarını uç sonsuzluğa, 

Ben solan güneşimin yalnızlığında, 

İnan mesut olurum.

Çok uzaklarda da olsan kahkahalarınla, 

Neşe dolarım.

Şenin yeniden yeşereceğin bahçenin, 

Taşı toprağı olurum.

Şimdi yüreğimde bir yangın, 

Ama son deminde güneşin.

Senin halelerin durağan, 

Kanayan benim yüreğim.

Bebeğim! ...

Yeniden doğuşun olsun bu ayrılık, 

Gamzeler otursun yüzüne, 

Mutluluk gölgen olsun, 

Son olsun bu hüzün yağmuru, 

Son olsun seni üzdüğüm.

Kapatıyorum bu sayfayı 

Ve, 

Üzerine kör düğüm.

Elveda, 

Sevdiğim.

                   

                                                06.02.03', 'Sıradan bir yaz günü,  Sakin, Sessiz... Havada,  Yaprak kımıldamıyor,  Her şey hareketsiz. Durağan her şey,  Canlar nefessiz... Bir can solu...', ARRAY['Türk Edebiyatı','Şiir','Sedat Sakabey Baysal']::text[], 8.5, '{"poet":"Sedat Sakabey Baysal","poet_slug":"sedat-sakabey-baysal","theme":"Türk Şiiri","is_hero":false,"total_lines":88,"source_url":"https://www.antoloji.com/veda-mektubu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Ev Bir Araba Sergüzeşt Avrat', 'al-ev-bir-araba-serguzest-avrat-goktu-kara-02hwq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'aaaaa diye bağırasım geliyor

bana bir al ev al baba

sandım ki yaşam uyumakla geçiyor

aldanmışım

sandım ki umut konuşmakla oluyor

kanmışım

sandım ki sevgi sevişmekle birebir

üçmuşum

bana bir araba al baba

sandım ki direnç susmak sadece

yumruğu gözüme yedim

sandım ki istenç bilmek abece

dilime acı biber sürdüler

sandım ki güvenç gözlerime bakmak kendimin

soğanı gözlerimin önünde kestiler

bana sergüzeşt avrat al baba

sandım ki her güzel benim olacak

gülümse

sandım ki her çiçek solacak benim için

anımsa

sandım ki her yürek doğacak bir güneş gibi üstüme

doğumsa', 'aaaaa diye bağırasım geliyor bana bir al ev al baba sandım ki yaşam uyumakla geçiyor aldanmışım sandım ki umut konuşmakla oluyor kanmışım sa...', ARRAY['Türk Edebiyatı','Şiir','Göktu Kara']::text[], 8.5, '{"poet":"Göktu Kara","poet_slug":"goktu-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/al-ev-bir-araba-serguzest-avrat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşadığını Hissetmeli İnsan', 'yasadigini-hissetmeli-i-nsan-ensar-cevval-riiwc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşadığı yerde mutlu olmalı insan, 

soluduğu hava sökmüyorsa ciğerlerini, 

içtiği sigara yakmıyorsa genzini, 

hele bir de tutmuşsa sevdiğinin elini

kök salıp bağlanmalı şehrine.

Doğduğu topraklara hasreti bitmeyecek

yaylalarını, sularını unutamayacak belki

bir şarkı duyduğunda memleket havalı

için için ağlayacağı zamanlar da olacak

bir fidayda, mastika, horon ezgisinde oynayacak

bir halay başında tey tey lerle coşacak

sadece özlemlerle sınırlı kalacak bir yaşam, 

yerini alamayacaktır yaşanılan zamanın.

Bunun içindir ki; 

yaşadığı yeri yurt edinmeli insan

balkonunda, bahçesinde çay içtiği dostları

selamlaştığı komşuları olmalı, 

aynı binada yaşadığı insanları tanımalı, 

esnafı, sokaktaki çocukları selamlamalı; 

ne dil, , ne de ırkını sormalı dostunun

ne dinlediği şarkıları yok saymalı, 

ne de konuşmasıyla dalga geçmeli

insan sevgisiyle, toprak sevgisiyle dolmalı

yaşadığı yerde yurttaşlığını hissetmeli 

sapasağlam, kaya gibi sağlam durmalı insan..

13,08,2003 İstanbul', 'Yaşadığı yerde mutlu olmalı insan,  soluduğu hava sökmüyorsa ciğerlerini,  içtiği sigara yakmıyorsa genzini,  hele bir de tutmuşsa sevdiğini...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yasadigini-hissetmeli-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gündönümü', 'gundonumu-ozlem-torkul-tekan-eni67', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç ağrıdı mı kalbiniz

Bilinmezin kasvetiyle.

Ve sabır, çok zor ve ağır

Gündönümü penceremde.

Yoksa siz o el misiniz

Uzak ilde seferlerde

Ve ömür, çok an ve satır

Kaptan seyir defterinde.

Hiç sıkılmaz mı içiniz

Dünüm bugüne denk diye

Ve erdem, çok kör ve sağır

Taşınıyor geleceğe.

(16 Mart 2003)', 'Hiç ağrıdı mı kalbiniz Bilinmezin kasvetiyle. Ve sabır, çok zor ve ağır Gündönümü penceremde. Yoksa siz o el misiniz Uzak ilde seferlerde Ve...', ARRAY['Türk Edebiyatı','Şiir','Özlem Torkul Tekan']::text[], 8.5, '{"poet":"Özlem Torkul Tekan","poet_slug":"ozlem-torkul-tekan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gundonumu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hür ve Mavi', 'hur-ve-mavi-ozlem-torkul-tekan-f76v7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Balık gibi, pul pul derya duygular

Yüreğimin ağlarına takılmışlar.

Balık gibi, ürkek çelimsiz onlar

Sudan çıkarıldı mı yaşayamazlar...

Kuşlar gibi, hür ve mavi umutlar

Yüreğimin dallarına konmuşlar.

Kuşlar gibi, küçük narindir onlar

Kanadı kırıldı mı uçamazlar...

(10 Aralık 2001)', 'Balık gibi, pul pul derya duygular Yüreğimin ağlarına takılmışlar. Balık gibi, ürkek çelimsiz onlar Sudan çıkarıldı mı yaşayamazlar... Kuşla...', ARRAY['Türk Edebiyatı','Şiir','Özlem Torkul Tekan']::text[], 8.5, '{"poet":"Özlem Torkul Tekan","poet_slug":"ozlem-torkul-tekan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hur-ve-mavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirler Destesinden', 'siirler-destesinden-elif-kerenciler-vxd00', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şiir yazıp, alıp, satanlara

adımı sormayın diyeceksem sormayın işte

Hiçbir şey göründüğü gibi değildir ve yaşandığı kadar da 

Umursanmamak umursamamaktan daha mı kötü

orası bana gerisi size kalsın', 'Şiir yazıp, alıp, satanlara adımı sormayın diyeceksem sormayın işte Hiçbir şey göründüğü gibi değildir ve yaşandığı kadar da  Umursanmamak u...', ARRAY['Türk Edebiyatı','Şiir','Elif Kerenciler']::text[], 8.5, '{"poet":"Elif Kerenciler","poet_slug":"elif-kerenciler","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/siirler-destesinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba, bişey sorcam!', 'baba-bisey-sorcam-gokay-balci-acr0z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bişey sorucam! Aydınlık nedir baba? 

Ben bir tek lambayı biliyorum, anlat bana...

Gazeteden gördüm, nedir demokrasi? 

Çok karmaşık yazmış Dünya Ansiklopedisi

Cumhuriyet neden daha iyi, baba? 

İnkılap nedir? Laikliği anlat bana...

Baba Kemalist ne demek? Sen Kemalist misin? 

Mustafa KEMAL''i anlat bana, biliyorsundur kesin! 

Atatürkçülüğü anlattı dün öğretmenim, 

''Niye herkes Atatürkçü değil'' dedim...

Ufak bi tebessümle geçiştirdi sorumu benim

Anlat bana baba, hepsini öğrenmeliyim...

Baba dün gördüm, kapkara bi örtü örtmüş üstüne

Arkadaşımın annesi, bilmiyorum adını...

Bir de komşumuz var, peçe takmış yüzüne

Bilmiyorlar mı onlar, Kılık-Kıyafet İnkılabını? 

Sokaktan geçiyorlar bazen sarıklı adamlar

Hatta içlerinden biri şalvar da giymişti

Daha çok önceleri, baba...

Atatük bize şapkayı getirmemiş miydi? 

Dün sizi konuşurken duydum dedemle

Baba Uğur MUMCU kim? Öldü mü? 

Konuşmuştunuz Ahmet Taner KIŞLALI diye birisini

Niye öyle bakıyorsun, bilmek istiyorum hepsini! 

Baba, ben on iki yaşındayım, büyüyorum artık

Oyuncak araba ya da tren istemiyorum artık

Bilinçlendirin bizi, ufkumuza ufuk katın

Biz çocuklara masal değil, Mustafa KEMAL''i anlatın...', 'Bişey sorucam! Aydınlık nedir baba?  Ben bir tek lambayı biliyorum, anlat bana... Gazeteden gördüm, nedir demokrasi?  Çok karmaşık yazmış Dü...', ARRAY['Türk Edebiyatı','Şiir','Gökay Balcı']::text[], 8.5, '{"poet":"Gökay Balcı","poet_slug":"gokay-balci","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/baba-bisey-sorcam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durmamıs Dünya', 'durmamis-dunya-guven-aktas-ypj65', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Derin bir of cektim once, 

Sonra aklımdan hıc cıkarmadıgım yerinde buldum onu, 

Hiç degişmemiş, günler, aylar gecsede, 

Yine dünyam durdu…

Bir ahh cektim derinden, 

Elimi bilmedigim kadehe uzattım, 

Içinde ne oldugunu anlayamadım, 

Cok acı tadı vardı, 

Yürek bu dinler mi ferman dedim kendi kendime, 

Sonra bir nefes aldım cigaramdan, 

Hani görünce onu durdurmustum ya dünyayı, 

Birde baktım ki pencerede karsılamısım sabahı, 

Hala kadehim yanımda, 

Cigaram sönmüş, gece onu alıp gitmiş, 

Umutlarım günesle ortaya cıkmıs, 

Bende ona sarılıp uyumusum.', 'Derin bir of cektim once,  Sonra aklımdan hıc cıkarmadıgım yerinde buldum onu,  Hiç degişmemiş, günler, aylar gecsede,  Yine dünyam durdu… B...', ARRAY['Türk Edebiyatı','Şiir','Güven Aktaş']::text[], 8.5, '{"poet":"Güven Aktaş","poet_slug":"guven-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/durmamis-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Noktadır', 'bir-noktadir-ahmet-aksoy-tott7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızlığın rengi var mı bilmem

Ya da ter edilmenin terk edenin terk edilenin

Ama bana sorarsan yalnızlık

Bir mor lekedir beyaz bir okyanusta

Terk edilmişlik de işte budur

Koca bir beyazlıkta yalnız bir nokta

Terk edilen renklidir terk eden rengini verir

Kimi zaman mor kimi zaman kan kırmızı

Kimi zamansa ölümün siyahı.', 'Yalnızlığın rengi var mı bilmem Ya da ter edilmenin terk edenin terk edilenin Ama bana sorarsan yalnızlık Bir mor lekedir beyaz bir okyanust...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-noktadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Kurtuluşa', 'gercek-kurtulusa-ahmet-aksoy-cmvgl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir imdat uğultusunda kulaklarım

Hep aynı ses hep aynı çığlık

Yetişmem gerek kurtarmaya

Çünkü bu benim kurtuluşum

Ama yok istemiyorum gerçekte

Bir kurtuluş kurtuluş değil, gerçek 

Kurtuluşa, ayaklarımı itemem zorla

Bana tek değil bütün bir kurtuluş gerek.', 'Bir imdat uğultusunda kulaklarım Hep aynı ses hep aynı çığlık Yetişmem gerek kurtarmaya Çünkü bu benim kurtuluşum Ama yok istemiyorum gerçek...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gercek-kurtulusa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Aydınlık Gerek', 'gercek-aydinlik-gerek-ahmet-aksoy-ds9ol', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sokağın ışıkları yakıyor gözlerimi

Sahte aydınlıktan nefret ediyorum

Bırakın beni karanlığımda

Söndürün bütün yapma ışıkları

Beni aydınlatamaz ışıklarınız

Bana gerçek aydınlık gerek

Sahte ışıklarınız batıyor yüreğime

Bana gerçek aydınlık gerek.', 'Sokağın ışıkları yakıyor gözlerimi Sahte aydınlıktan nefret ediyorum Bırakın beni karanlığımda Söndürün bütün yapma ışıkları Beni aydınlatam...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gercek-aydinlik-gerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırkın', 'kirkin-ahmet-aksoy-qrqjm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kırkın çıkmadı henüz

Kırk dakika olur

Kiminde kırk gün olur

Kiminde kırk yıl olur

Kırk asır olur kırkın

Kiminde, aşk.', 'Kırkın çıkmadı henüz Kırk dakika olur Kiminde kırk gün olur Kiminde kırk yıl olur Kırk asır olur kırkın Kiminde, aşk....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kirkin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Bir Elmas Vereceğim', 'sana-bir-elmas-verecegim-ahmet-aksoy-z77k5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana bir elmas vereceğim

İsteyene vereceksin

Sana elmas vereceğim

Ama kıskanmayacaksın

Ya da iç geçirmeyeceksin

Başkasına verirken

Sana bir elmas vereceğim

İsteyene vereceksin.', 'Sana bir elmas vereceğim İsteyene vereceksin Sana elmas vereceğim Ama kıskanmayacaksın Ya da iç geçirmeyeceksin Başkasına verirken Sana bir ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sana-bir-elmas-verecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umuda', 'umuda-ahmet-aksoy-xfinj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimsesizin umudu

Olan kimse

Çık artık

Saklandığın yerden

Umut olarak

Umutsan yap

Yapman gerekeni

Yoksa kimsesizi

Kimsesizliğinde

Rahat bırak.', 'Kimsesizin umudu Olan kimse Çık artık Saklandığın yerden Umut olarak Umutsan yap Yapman gerekeni Yoksa kimsesizi Kimsesizliğinde Rahat bırak...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/umuda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimler', 'kimler-ahmet-aksoy-4ivbi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kime ne benden kime ne senden

Kimler sevmedi ki beni

Kimler sevmedi ki seni

Benim seni

Senin beni, sevdiğin kadar.', 'Kime ne benden kime ne senden Kimler sevmedi ki beni Kimler sevmedi ki seni Benim seni Senin beni, sevdiğin kadar....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kimler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Trenler', 'kara-trenler-ahmet-aksoy-25tkb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kara tren girdi istasyona

Kimler var içinde kimler var

Kara tren çıktı istasyondan

Kimler var içinde kimler var

Bin arzu bin ayrılık

Bin hüzün bin sevda var

Dünya oldukça kara trenler olacak

İçinde kimler kimler olacak.', 'Kara tren girdi istasyona Kimler var içinde kimler var Kara tren çıktı istasyondan Kimler var içinde kimler var Bin arzu bin ayrılık Bin hüz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kara-trenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dumani Duman Olmuş', 'dumani-duman-olmus-ahmet-aksoy-22tse', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerim dumandan

Görmez olmuş

Şu dışarıdaki ışık

Ne kadarda karanlık

İçim duman olmuş

Göz gözü görmez olmuş

Yaktığın ateşin dumanları

İçime dolmuş

Yol arar çıkmak için

Bulamaz üstüne üstlük

İçim duman olmuş

Duman, duman olmuş.', 'Gözlerim dumandan Görmez olmuş Şu dışarıdaki ışık Ne kadarda karanlık İçim duman olmuş Göz gözü görmez olmuş Yaktığın ateşin dumanları İçime...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dumani-duman-olmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük', 'ozgurluk-ahmet-aksoy-gh6oy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gümbür gümbür geliyor sesin

Durduracak engel yok

Bir kere çağlamaya başladın

Önü kesilmez şelalesin

Yolunu kesmek isteyen

Sürüklenecek akıntına kapılarak

Sense durmadan, artarak akacaksın 

Özgürlük nehirleriyle beslenen. 

Yolun sonu değil yakın

Ama zaman senin için geçecek

Gümbür gümbür geliyor sesin

Sen bir ulusun yüreğisin', 'Gümbür gümbür geliyor sesin Durduracak engel yok Bir kere çağlamaya başladın Önü kesilmez şelalesin Yolunu kesmek isteyen Sürüklenecek akınt...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozgurluk-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceleri Çıkma', 'geceleri-cikma-ahmet-aksoy-uffur', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geceleri çıkma dışarıya

Kaş göz işareti yapıyor yıldızlar sana

Bak sonra kötü olacak

Söndüreceğim yıldızları

Geceleri dışarıya çıkma

Çıkarsan mehtabı görürsün

Ve içinden güzel dersin, kıskanırım

Parçalarım ayı

Ben yokken yanında 

Geceleri çıkma dışarıya

Aklım sende kalmasın 

Erkenden yat uyu

Ben öyle yapacağım

Rüyalarda buluşalım

Aman sakın geç kalma

Yoksa kıskanırım kaldığın yeri', 'Geceleri çıkma dışarıya Kaş göz işareti yapıyor yıldızlar sana Bak sonra kötü olacak Söndüreceğim yıldızları Geceleri dışarıya çıkma Çıkarsa...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/geceleri-cikma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni kendime mahkum etti', 'beni-kendime-mahkum-etti-guven-aktas-v7y7e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni aşktan nefret ettirdi, 

Beni bende eritip, bitirdi

Ne bir evet, Ne de hayır dedi, 

Beni kendime mahkum etti, 

Kollarımda aşk''ın acı kelepçesi, 

Oldum genc yasımda sevda kölesi, 

Deli etti beni güzeller güzeli

Kendine beni mahkum etti, 

Müebbet ceza yemiş mahkum gibi, 

Cöllerde çürüyen Mecnun misali, 

Oldum Aslı''nın Kerem''i, 

Beni kendime mahkum etti, 

Aftanda yararlanamıyorum ki, 

Ne zaman kırılacak zindanın demirleri, 

''''Koşarak kollarıma gel'''' deseydi, 

Bu siirin son mısrası eksikti....', 'Beni aşktan nefret ettirdi,  Beni bende eritip, bitirdi Ne bir evet, Ne de hayır dedi,  Beni kendime mahkum etti,  Kollarımda aşk''ın acı kel...', ARRAY['Türk Edebiyatı','Şiir','Güven Aktaş']::text[], 8.5, '{"poet":"Güven Aktaş","poet_slug":"guven-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beni-kendime-mahkum-etti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara', 'kara-ahmed-arif-nt508', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çarpmış, 

   Paramparça etmiş, 

   Kara sütü, kara sevdayla seni...

   Ve kara memelerinde dişlerin asi, 

   Karadır, upuzun yattığın gece, 

   Felek, ah ettirir, boynun kıl - ince...       

   Cihanlar, çocuklar, kuşlar içinde

   Sızlar bir yerlerin

   Adsız ve kayıp

   Sızlar, usul-usul, dargın, 

   Ve kan tadında bir konca, 

   Damıtır kendini mısralarınca...

   De be aslan karam, 

   De yiğit karam, 

   Hangi kalemin yazısı, 

   Zorlu yazısı, 

   Belanda? 

   Anadan doğma nişan mı, 

   Sütlü barut damgası mı, 

   Bir gece parçası mı kaburgandaki? 

   Kız kakülü, ne hal eylermiş teni, 

   Ellerin, deli hoyrat, 

   Ellerin, susuz, yangın.

   Ellerin ooooy alarga...

   De be aslan karam, 

   De yiğit karam, 

   Hangi güzelin diş yeri, 

   Mavi diş yeri, 

   Sevdanda? 

   Vurmuş, 

   Demirlerin çapraz gölgesi, 

   Alnın galip ve serin.

   Künyen çizileli kaç yıldız uçtu, 

   Kaç ayva sarardı, kaç kız sevişti, 

   Gelmemiş, kimselerin...

   De be aslan karam, 

   De yiğit karam, 

   Hangi zehirin meltemi, 

   Saran meltemi, 

   Hülyanda? 

   Hakikatli dostun muydu, 

   Can koyduğun ustan mıydı, 

   Bir uyumaz hasmın mıydı, 

   ''Ooooof'' de bunlar olsun muydu? 

   De be aslan karam, 

   De yiğit karam, 

   Hangi kahpenin hançeri, 

   Saklı hançeri, 

   Yaranda?', 'Çarpmış,     Paramparça etmiş,     Kara sütü, kara sevdayla seni...    Ve kara memelerinde dişlerin asi,     Karadır, upuzun yattığın gece, ...', ARRAY['Türk Edebiyatı','Şiir','Ahmed Arif']::text[], 8.5, '{"poet":"Ahmed Arif","poet_slug":"ahmed-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/kara-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraf', 'i-tiraf-i-lker-sahin-hqlza', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Olur dedim baskasıyla bakmadan yüzüne

muhtac oldum seninle yasadıgım bir damla hüzüne

kosardım ölüme kafa tutardım ecele seninle

senden ayrıldımya günessiz güne dödüm

Seni yasadım inan anıda hatırada

hep seni aradım kalemimde kagıtta 

hep sen sandım heyecanla actıgım telefonda

senden ayrıldımya balıksız okyanusa döndüm

Senden ayrıldımya agacsız ormana döndüm

lanet ettim hergece tükendi ömrüm

sensiz hergün gün be gün öldüm

senden ayrıldımya kanatsız kusa döndüm....', 'Olur dedim baskasıyla bakmadan yüzüne muhtac oldum seninle yasadıgım bir damla hüzüne kosardım ölüme kafa tutardım ecele seninle senden ayrı...', ARRAY['Türk Edebiyatı','Şiir','İlker Şahin']::text[], 8.5, '{"poet":"İlker Şahin","poet_slug":"i-lker-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/itiraf-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ali Emmi', 'ali-emmi-sair-emekci-n705n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasır mı tuttu ellerin

Ali emmi, Ali emmi

Bilirim kötü hallerin

Hammal Ali, Ali emmi

Her gün üç paket birinci

Akşam olur gelir sancı

Ne zaman doğdu yedinci

Hammal Ali, Ali emmi

Sermayesi alınteri

Her gün sızılar bir yeri

Mezardadır diri diri

Hammal Ali, Ali emmi

Der Emekçi gayrı öğün

Sana iş bulundu sevin

Mezarcılık son görevin

Hammal Ali, Ali emmi', 'Nasır mı tuttu ellerin Ali emmi, Ali emmi Bilirim kötü hallerin Hammal Ali, Ali emmi Her gün üç paket birinci Akşam olur gelir sancı Ne zama...', ARRAY['Türk Edebiyatı','Şiir','Şair Emekci']::text[], 8.5, '{"poet":"Şair Emekci","poet_slug":"sair-emekci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ali-emmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümsüz sevgi', 'olumsuz-sevgi-i-lker-sahin-gc91s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aglıyor gözlerim, aglıyor sözlerim, agrıyor kalbim

kim vardı hayatımda senden baska sevdigim

sendin tek hedefim, umudum, istegim

ellerin olamazsın bil benimsin bir benim

Kan doldu senin adına yazdıgım sayfalar

her kelimesi her hecesi askımdı bilesin

kimse anlamadı beni senden oldu bütün satırlar

ellerin olamazsın bil benimsin bir benim

belki bindefa kalem kırdım sana olan sevgime

düsman oldu beynim yazan ellerim

söz gecmedi aklıma, fikrime, yüregime

ellerin olamazsın bil benimsin bir benim.....', 'Aglıyor gözlerim, aglıyor sözlerim, agrıyor kalbim kim vardı hayatımda senden baska sevdigim sendin tek hedefim, umudum, istegim ellerin ola...', ARRAY['Türk Edebiyatı','Şiir','İlker Şahin']::text[], 8.5, '{"poet":"İlker Şahin","poet_slug":"i-lker-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olumsuz-sevgi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askhennemden mektup', 'askhennemden-mektup-i-lker-sahin-nlyui', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Burası ne anlatılan nede düsünülen yer

ne cehennem ne cennet, burası askın soruldugu yer

sorulan soru hep aynı aska verdigin deger

ebediyen yanarsın dediler sevdigin davacı olursa eger

Eline düstüm sevdigim ne olur affet

az degil sana yaptıgım biliyorum ihanet

istersen hazırım sevdigin kalbi vermeye diet

ne olur sevdigim ne olur affet

Seni ne kadar sevdigim soruldu

söyleyince ihanet kalbimde korlar yogruldu

ayagıma pranga boynuma zincirler vuruldu

ne olur sevdigim ne olur affet

Sevenler sevilenler nagmem gelsin dile

varsa kalbinin sahibi bakma kimseye yan gözle bile

pisman olursun istedigin yasadıgın bir anlık zevke

askhennemde milyon sene yanarsın yaptıgın bir ihanete...', 'Burası ne anlatılan nede düsünülen yer ne cehennem ne cennet, burası askın soruldugu yer sorulan soru hep aynı aska verdigin deger ebediyen ...', ARRAY['Türk Edebiyatı','Şiir','İlker Şahin']::text[], 8.5, '{"poet":"İlker Şahin","poet_slug":"i-lker-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askhennemden-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunun 609. Günü...', 'yoklugunun-609-gunu-sibel-berfin-gursoy-pmvyw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Pencere  önünün  pervasız  kuşları

Arkalarında  Ankara’nın  simsiyah  buğulu  çığlığı

Ve gönül  hüzün  çiçekleri  dermeye  hazır..

Bir  martının  kırmızı  bakışlarında, 

Esmeyi  unutmuş  rüzgârların, 

Unuttuğum  uğultusu  kulaklarımda..

Ardına  bakmadan  bırakıp  gittiğin  kasabalar

Onulmaz  bir  yalnızlığın  kuyusunda  yosun  tutarken

Ve  sen  uzayıp  giderken  bir  yol  gibi, 

Yüreğimin  berrak  uçurumunda, 

Bir  kayanın  üstünde  açan  mavi  çiçek

Boğucu  bir  ısrarla  seni  sorarken  her  sabah

Sen  ardı  gelmeyen  sevdaları  bıraktın  bize..

Mavi  çiçek  ve  ben

Öncesi  ve  sonrası  olmayan

Rüyalar  görürüz her  gece...

Gönlümün  en  ücra  köşesinde, 

Baharat  kokulu  duvarlarına

Yoksulluğun  ince  sızısının  çöktüğü  bir  evde

Yarınını  arayan  bir  taşra  çocuğu... 

Senin  rüzgârın, 

Bunu  anlayamayacak  kadar uzak kıyılardan esiyor..

Bir  boyacı  sandığına  yapıştırılmış, eprimiş, 

Ucuz  şarkıcı  fotoğrafları  gibi  fark edilmeyen  biz, 

Ertelenmiş  sözler  gibi  zamanın  vicdanına 

Terk edilen  biz, 

Uzak  yakınlıklarda  yarınını, 

Yakın  uzaklıklarda  sevdasını  arayan  biz, 

Yine de  karanfil  kokulu  çocuklarıyız  bu  kentin...

İhanetin  kara  saplı  bıçağıyla  zehirlenen  ben, 

İçimde  yitip  giden  sen,

Lâl  bakışlı  yâren, 

Kaybolduk  biz  duvardaki  takvimin

Sararan  sayfalarında...

                                           22.10.2001 

                                            YAKAMOZ', 'Pencere  önünün  pervasız  kuşları Arkalarında  Ankara’nın  simsiyah  buğulu  çığlığı Ve gönül  hüzün  çiçekleri  dermeye  hazır.. Bir  mart...', ARRAY['Türk Edebiyatı','Şiir','Sibel Berfin Gürsoy']::text[], 8.5, '{"poet":"Sibel Berfin Gürsoy","poet_slug":"sibel-berfin-gursoy","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yoklugunun-609-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdasına Yandığım Hayat', 'sevdasina-yandigim-hayat-nuri-can-49rdy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalabalık kentler ürkütür yüreğimi 

uğultular doldurur beynimi yürüdükçe 

tüm gözlerden incinmiş bir bakış sızar istasyonlara 

kirli vagonlarda taşınan ince bir hüzün gibi 

ki, 

hep aynı yerimi burkan 

bu yüzü kirli şehirde 

kimse kimseyi sevmiyor 

bilmiyor avuçları kar çiçeği kokan 

bir çocuğun saçlarına dokunmayı 

şiirler okumayı bir alacaşafağa

kaç kez ittiysem uçuruma yüreğimi 

bir çift göz gördüm deltalarda 

yalvaran bir ses 

kırıldı içimde yıllarca gizlediğim ayna 

kalbime batıyor şimdi kırıkları 

nehirler boyu kanıyorum

ateşler boyu yanıyorum

alın götürün beni buralardan allah aşkına

dayanamıyorum

nereye baksam denizi duman

neye dokunsam ah

hüznün acıyla öpüştüğü bir kıyıda kaldım

yok,

yok gidemem başka bir liman

anla 

anla ve al bu acıları koy bir yana

kör bir sevdanın imgeminde

bir yanı Mecnun’dur çöllerimin bir yanı Leyla

bir yanı Yusuf’tur zindanımın bir yanı Züleyha

yorgunum her akşam yollara bakıp ağlamaktan

yüregimde hasret ateşleri yakmaktan

her kıyıda bir başka cehennem bekler beni 

nereye baksam güz bahçeleri

nereye gitsem üstüme devrilir gök

kime nasıl anlatırım sancıyan yanlarımı ah, kim anlar beni 

hasretin bin çeşidiyle delik deşik yüreğim 

kimsem de kalmadı halime ağlayacak

yaralarımı saracak

böyle boynu bükük duruşum ondan 

ondan bir yanım hep vurgun, hep yetim, hep kırgın

ömrüm oy

ömrüm oyy

şiir cıvıltıları oysa gönül ormanımda 

yıldız ışıltıları 

uzanıpda tutamıyorum

hüznün en kuyu gecelerde boğuldu sevinçlerim

yıldızlar örtmüyor artık yaralarımı 

gözyaşlarımı saklamıyor

en ucuz şarkılar yıkıyor ruhumu karanlık sularda

unutulmuş bir sokak ortasında 

düş denizlerine bırakıyorum soluğumu 

ellerim üşüyor, yüreğim, gözlerim üşüyor 

dönüp bakmıyor kimse, bölüşmüyor sevinçlerini benimle

uzak bir kıyıda tutsak kalıyor hayallerim 

bütün iskeleler yıkılıyor

bütün iskeleler yıkılıyor

hiç bir gemi almıyor beni 

bir damla gözyaşı olup akıyor yüreğim avuçlarıma 

yüreğim ki, deliboran, delipoyraz, kızılkan

hasretim kızıl alev bir güldür yangınlara

koparıp göğsümden ateşlere atıyorum 

hiç kimse çekip almıyor kalbimi ateşler içinde 

kanıyor en katı yerinde gece, yanıyor yüreğim 

yüreğim alev topu 

yüreğim kanrevan

yüreğim nar

yüreğim ateş

yüreğim ah! 

tutunduğum dallar kırık 

sokulduğum kucak çiçek açmıyor 

aldırmıyor çığlıklarıma sevdasına yandığım hayat 

acının ve ateşin burgacında 

ince bir sızı gibi geçip gidiyor ömrüm 

nasıl katlanacaksa kalbim bunca ağrıya 

ömrüm oy

ömrüm oy

gülüm oy 

/', 'Kalabalık kentler ürkütür yüreğimi  uğultular doldurur beynimi yürüdükçe  tüm gözlerden incinmiş bir bakış sızar istasyonlara  kirli vagonla...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/sevdasina-yandigim-hayat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göksuyum (Aşk Fermanım)', 'goksuyum-ask-fermanim-tayfun-kasapoglu-esgb9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yanlızlığımın başkentin de duruyor 

bakışların 

kaçmaya çalışsam 

acemiliğimden midir nedir 

yakalanırım... 

yakalandım 

habersiz bir tufana 

aşk denizinde mi 

yoksa kuru nehirde mi 

boğulup yandım 

sen yağmadın 

kurumuş pınarlarıma 

sebebini bilerek hep 

yandım 

yağmalandım 

bütün dikenler sensiz 

sanki benliğimde 

ne gül var ne bir damla 

su 

kuruyorum 

gecelerim seni çağırıyor 

duyuyormusun 

yalnızlığımın başkentinde... 

dem tutuyor bütün azalarım... 

gökyüzü seni yağdırıyor 

şarkılarla 

sesin çınlıyor sen gibi her tarafta 

bir yağmur bekleniyor 

oda geçikiyor 

tam dem 

zamanında 

sana uğramayan rüzgarlar boğuyor 

beni 

oysa senin yurdunun 

üstünde bütün kuşlarım 

kanatlarında taşıyorlar canımı 

gör al beyaz güvercinden 

yarınlarımı...

aslında ben seni bir mısraya 

sığdıramazken 

sen 

beni 

böyle deli uzağımdayken 

bir nefes kadar 

yakınsın tutuşmaya 

yakın hasretlerimin içindesin

ne oldur dön sılaya 

dön gönül yurduma vurma rotanı 

uzaklara

tenin tenimden uzaksa 

cehennemdeyim haberin ola

gök suyum 

attığım son imzam

aşk fermanım

dön gel yanıma 

belki de kendi yanına

...

''''uçsuz bucaksız bir yalnızlıkta öle yazılan bir aşkın kaderi bu kadar kısa boylu değildir.... benim bu aşka gücüm yeterse ellerinin ulaştığı yerdedir umudum...''''', 'yanlızlığımın başkentin de duruyor  bakışların  kaçmaya çalışsam  acemiliğimden midir nedir  yakalanırım...  yakalandım  habersiz bir tufana...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Kasapoğlu']::text[], 8.5, '{"poet":"Tayfun Kasapoğlu","poet_slug":"tayfun-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/goksuyum-ask-fermanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyiden İyiye', 'i-yiden-i-yiye-olgun-ocak-vir9m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İyiden iyiye alıştım bu şehre, 

İyiden iyiye alıştım tütünsüzlüğe, 

Ve sensizliğe...

Zaten istesemde istemesemde sike sike alışmıycakmıydım Tüm bu lanet olası şeylere...

Yalan söyledim...

Hiçmi hiç alışamadım bu şehre, 

Hiçmi hiç alışamadım tütünsüzlüğe, 

Ve sensizliğe...

Şimdi düşünüyorumda sikmişim şehrinide tütününüde...', 'İyiden iyiye alıştım bu şehre,  İyiden iyiye alıştım tütünsüzlüğe,  Ve sensizliğe... Zaten istesemde istemesemde sike sike alışmıycakmıydım ...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ocak']::text[], 8.5, '{"poet":"Olgun Ocak","poet_slug":"olgun-ocak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/iyiden-iyiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emeğimsin', 'emegimsin-ali-haydar-timisi-d0j5f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne zaman yağmur yağsa bu şehre

Bir sevda türküsüdür 

Yarım kalmış bir ömür gibi 

                  dönüp duran dilimde

Seni ben canımın içine saklarım

Sonra küskün yıldızlardan süzüp sevdanı 

Ağlarım...

Ne zaman gözyaşın yağsa yüzüne 

Güneşin nefesi değse  sesine

Seni ben 

Sayrılı bir mıh gibi 

Yüreğime saplarım

Sonra ceplerime doldurup anıları

Yaramaz bir çocuk gibi

Kaçarım...

Bir uçurumdur bekler yolumu

Bir kuş havalanır

Kanadında gülüşün

Göçüp  gider kervanımda sevdan

Bir ateştir sarar yüreğimi 

Yanarım...', 'Ne zaman yağmur yağsa bu şehre Bir sevda türküsüdür  Yarım kalmış bir ömür gibi                    dönüp duran dilimde Seni ben canımın için...', ARRAY['Türk Edebiyatı','Şiir','Ali Haydar Timisi']::text[], 8.5, '{"poet":"Ali Haydar Timisi","poet_slug":"ali-haydar-timisi","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/emegimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor', 'zor-sair-celebrian-o4o4k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karşı koyabilmek 

Gelen bir aşka, yürekle, 

Kayıtsız kalmak kadar zordur

Bir bebeğin gülücüğüne.', 'Karşı koyabilmek  Gelen bir aşka, yürekle,  Kayıtsız kalmak kadar zordur Bir bebeğin gülücüğüne....', ARRAY['Türk Edebiyatı','Şiir','Şair Celebrian']::text[], 8.5, '{"poet":"Şair Celebrian","poet_slug":"sair-celebrian","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zor-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zırdeli Bir Şair', 'zirdeli-bir-sair-ensar-aktas-ddr6i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Evet, deliyim ben

Zırdeli bir şair

Yazarım…

Deli, dolu şiirler

Aşka sevgiye dair

Atarım…

Duygu denizine şiirlerimi

Bir okuyan çıkar zahir

Dalarım…

Bazen de kendim o denize

Aşkolsun çıkartabilene beni

Yanarım…

Aşkına düştüğüm günden beri

Kaldı mı çekmediğim bir kahır

Yakarım…

Hasretinden Roma’yı da, kendimi de

Tükenirse bir gün yontup durduğun şu sabır

Yakarım da…

Korkarım üzülür mezarında anam

Yoksa bana her gün bayram

Dedim ya…

Deliyim ben, zırdeli bir şair

Zehir zemberek yazarım şiirlerimi velhasıl

Rotterdam,14-06-2003', 'Evet, deliyim ben Zırdeli bir şair Yazarım… Deli, dolu şiirler Aşka sevgiye dair Atarım… Duygu denizine şiirlerimi Bir okuyan çıkar zahir Da...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/zirdeli-bir-sair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-nizam-uzun-2jgio', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni çok özlüyorum...

Hepsi bu.', 'Seni çok özlüyorum... Hepsi bu....', ARRAY['Türk Edebiyatı','Şiir','Nizam Uzun']::text[], 8.5, '{"poet":"Nizam Uzun","poet_slug":"nizam-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/mektup-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Vuruş', 'uc-vurus-ayse-tural-80mqs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geldiysen

Gönlümün kapısına 

Üç kez vur...

Aşkların en güzeline 

Tutkunum

İlk vuruşun 

Gözlerin olmalı

Sarıp sarmalamalı beni

İkinci vuruşun

Sıcacık dokunuşların olmalı

Deli etmeli beni

Üçüncü vuruşunda

Sen ve ben 

Biz olmalıyız....', 'Geldiysen Gönlümün kapısına  Üç kez vur... Aşkların en güzeline  Tutkunum İlk vuruşun  Gözlerin olmalı Sarıp sarmalamalı beni İkinci vuruşun...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tural']::text[], 8.5, '{"poet":"Ayşe Tural","poet_slug":"ayse-tural","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/uc-vurus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal Erik Ağacı', 'hoscakal-erik-agaci-ayse-tural-5bhqp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bebeklerimi dallarına astım

İyi uyut erik ağacı

Çiçeklerin

Çocuk hayallerimde kaldı

Gölgesinde ortancalar

Çığlıklarımı geri ver

Ne olursun ! 

Saklambaçlarım 

Kovuklarında saklı...

Ben artık büyümüşüm

Oyunlarım sende kaldı

Sen de artık çürümüşsün

Hoşça kal erik ağacı....', 'Bebeklerimi dallarına astım İyi uyut erik ağacı Çiçeklerin Çocuk hayallerimde kaldı Gölgesinde ortancalar Çığlıklarımı geri ver Ne olursun !...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tural']::text[], 8.5, '{"poet":"Ayşe Tural","poet_slug":"ayse-tural","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hoscakal-erik-agaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidişim Sonun Olacak', 'gidisim-sonun-olacak-ayse-tural-mmlfv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gidişim sonun olacak

Duygu harmanımda

Savrulan başaklar gibisin

Rüzgarım dinerse

Kork...

Gülüşüm, 

Sonsuz zamanlarda 

Sanma boşuna

Bir gün 

Yitirebilirsin...

Fısıltılarım kulaklarında

Kalıcı sanma

Çekip gidiverirlerse 

Apansız 

Şaşar kalırsın....

Gidişim sonun olacak

Engininde denizlerin

Duygu teknelerini yüzdüremeyeceksin.

Balık gözlerinde gözlerimi arayacaksın

Nafile....

Bahar bahçelerinde 

Kelebeklerin uçmayacak

Boynu bükük menekşeler gibi

Yapayalnız kalacaksın...

Ellerin üşüyecek, 

Ocak başlarının alevlerinde.

Bir yangınında olacaksın

Bir soğuğunda 

Aşk nağmelerinin....

Gidişim sonun olacak

Bil...

Herşey beni sana hatırlatacak

Düşün...

Yaşam yelpazende 

''Olmayan bir gün'' olacağım.

Çaresizlikle, ellerin bomboş

Kalacak....

Gidişim sonun olacak

Yaban mersini kokumu

Rüzgarlara yükledim.

Bir gün duymazsan

Gülüm, 

Dalında kurumuş sanma

Başka eldedir.....', 'Gidişim sonun olacak Duygu harmanımda Savrulan başaklar gibisin Rüzgarım dinerse Kork... Gülüşüm,  Sonsuz zamanlarda  Sanma boşuna Bir gün  ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tural']::text[], 8.5, '{"poet":"Ayşe Tural","poet_slug":"ayse-tural","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/gidisim-sonun-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Bahçem', 'gonul-bahcem-ayse-tural-zro7i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşamı

Dedemin marangoz rendesinde tanıdım.

Hiç taze tahta kokusu duydunuz mu? 

Ne güzel kokar! ..

Büyükannemin katmerli karanfilleri

Hala düşlerimdedir.

Akşam sefaları yaz ikindilerinde

Yaşama kulaklarını uzatır..

Uyku çiçekleri uykuya hazırlanır.

Bir solucan siner toprağa

Usul usul....

Tırtıl boylu boyunca

Dut yapraklarındadır.

İpek ipek örülür zaman

Dal uçlarında....', 'Yaşamı Dedemin marangoz rendesinde tanıdım. Hiç taze tahta kokusu duydunuz mu?  Ne güzel kokar! .. Büyükannemin katmerli karanfilleri Hala d...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tural']::text[], 8.5, '{"poet":"Ayşe Tural","poet_slug":"ayse-tural","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gonul-bahcem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cıs', 'cis-ayse-tural-23coe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Cıs '' deyince annem

Ellerimi çekerdim

Nelere uzatmışsam...

Ben büyüdüm

Ayakkabılarım büyüdü.

Cıslar bir türlü bitmedi

İnadına devleşti...

Onu söyleme

Böyle yapma

Oraya gitme...

Nereye kadar? 

Ayıplar

Ve günahlar....

''İçimdeki çocuk! Seni çok seviyorum....''', '''Cıs '' deyince annem Ellerimi çekerdim Nelere uzatmışsam... Ben büyüdüm Ayakkabılarım büyüdü. Cıslar bir türlü bitmedi İnadına devleşti... O...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tural']::text[], 8.5, '{"poet":"Ayşe Tural","poet_slug":"ayse-tural","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Bitsin bu ayrılık yolu *', 'artik-bitsin-bu-ayrilik-yolu-guven-aktas-46e07', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artık bu haykırısların sonu, 

Artık cıkmaza döndü bu sokagın sonu, 

O dur hızlandıran kaybolusumu, 

Artık bitsin bu ayrılık yolu, 

Yanı basımda biten güller, 

Bir bir solup döküldüler, 

Yeter artık! beni yasarken öldürdüler, 

Artık bitsin bu ayrılık yolu, 

Kosarak gelsen bana, 

Sarılıp aglasan kollarımda, 

Yeminler  olsun ki Tanrıma, 

Artık bitsin bu ayrılık yolu, 

Resimlerini alıp yanı basımdan, 

Gidecegim bir gün buralardan, 

Tek dilegim var Tanrıdan, 

Artık bitsin bu ayrılık yolu, 

Daglara taslara feryadım, 

Söyle vefasız daha ne yapayım? 

Adını gökyüzüne kazımısım, 

Artık bitsin bu ayrılık yolu,', 'Artık bu haykırısların sonu,  Artık cıkmaza döndü bu sokagın sonu,  O dur hızlandıran kaybolusumu,  Artık bitsin bu ayrılık yolu,  Yanı bası...', ARRAY['Türk Edebiyatı','Şiir','Güven Aktaş']::text[], 8.5, '{"poet":"Güven Aktaş","poet_slug":"guven-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/artik-bitsin-bu-ayrilik-yolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haber vermeden', 'haber-vermeden-guven-aktas-umtgk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen artık bir türkü oldun dilimde, 

Sen ben oldun artık ne yapayım, 

Senin payın olmasada bu sevgide, 

Ben sana haberin olmadan taptım, 

Baglamamda sen bir tel oldun, 

Her kederlendigimde sırdas oldun, 

Sen artık benim oldun, 

Ben haber vermeden sana asık oldum, 

Gündüzümün günesi oldun sen, 

Göz yası oldun gecelerimden kopup gelen, 

Bir yanlızlıksın beni bende bitiren, 

Seni deli gibi sevmisim haber vermeden, 

Bundan sonra sen bir yabancısın, 

Acaba benden sonra ne yapacaksın, 

Elbet sende birine askını acacaksın, 

Biliyorum benden cok mutlu olacaksın', 'Sen artık bir türkü oldun dilimde,  Sen ben oldun artık ne yapayım,  Senin payın olmasada bu sevgide,  Ben sana haberin olmadan taptım,  Bag...', ARRAY['Türk Edebiyatı','Şiir','Güven Aktaş']::text[], 8.5, '{"poet":"Güven Aktaş","poet_slug":"guven-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/haber-vermeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Kurmaya Özlem', 'hayal-kurmaya-ozlem-sair-masmavi-w4dlj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayaller kursam gözlerim açık

Ayaklarım yerden kesilse aklımdan geçenlerle

Uçsam..

Kuşlar gibi değil asla

Arılar gibi bu kez..

Çiçeklerin ballarını toplasam bahar döşenmiş tarlalarda

Batırsam iğnemi hoyratça çiğneyenlere..

Bir gelincik, bir papatya tarlasına gitsem, 

Gelinciğin kan ağlayan gözlerine

Papatyaların beyazından gözlük yapsam

Hanımelinin o mis kokusunu

Korkak bir bebenin yanağına

Öpücük olarak bıraksam..

Yavrusunu koruyan annenin eline

Kırmızı gülün şehvetini bulaştırsam..

Hayaller kursan gözlerim açık, 

Ayaklarım yerden kesilse aklımdan geçenlerle

Ahh, uçsam!', 'Hayaller kursam gözlerim açık Ayaklarım yerden kesilse aklımdan geçenlerle Uçsam.. Kuşlar gibi değil asla Arılar gibi bu kez.. Çiçeklerin ba...', ARRAY['Türk Edebiyatı','Şiir','Şair Masmavi']::text[], 8.5, '{"poet":"Şair Masmavi","poet_slug":"sair-masmavi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hayal-kurmaya-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigara Parmağı', 'sigara-parmagi-i-lyas-orak-t41qj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'küçük bir sirke olmayı ağlardım

siyah saçlarınıza gizli

herkesin olurdu serçe

herkesin yüzük 

bir sizinkiydi sigara parmağı

sarışın bir hüznü aralardınız

nasıl da hatırladım sizdiniz 

camdan bir vazoydunuz

dokunsam kırılır ağlardınız

ah keşke hiç açmasaydınız ağzınızı

saçlarınız neden karışık 

ya bu üst bu baş

ne oldu camdan düşlerinize

durun canım siz O değilsiniz

O böyle ağlamazdı 

buruşturup çenesini

ah keşke hiç buruşturmasaydınız

yoksa dişleriniz mi 

her gece nasıl da fırçalardınız

ama durun yapmayın

böyle uluorta 

lütfen evinize gidin

hem ben evliyim sonra

ne zaman bir gül olsa elimde

narin açardınız kollarınızı

canlanırdı haliniz

açtıkça bileklerinizi

neyim var neyim yok toplardınız

ah keşke hep eski bir cam gibi kırılsaydınız

saklı düşleriniz vardı

benimle kurardınız 

bir benim değil miydi parmak aranız 

ellerimle yakardınız

bahar gelmeden frezya kokardı odanız

dokunsam da dokunmasam da ağlardınız.', 'küçük bir sirke olmayı ağlardım siyah saçlarınıza gizli herkesin olurdu serçe herkesin yüzük  bir sizinkiydi sigara parmağı sarışın bir hüzn...', ARRAY['Türk Edebiyatı','Şiir','İlyas Orak']::text[], 8.5, '{"poet":"İlyas Orak","poet_slug":"i-lyas-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sigara-parmagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El İzim Silahım Buğusunda Camların', 'el-i-zim-silahim-bugusunda-camlarin-i-lyas-orak-zuyv7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'EL İZİM SİLAHIM BUĞUSUNDA CAMLARIN

içine girdiği zarf kefenidir

adresine ulaşmayan mektubun

yalandı senin içinde öldüğüm 

yalan seni kefen yazan sözlükler

beni sorardı seni görenler

içli-dışlı olduğumuz yalandı

mektuplarını aldım zarflarından

kanayan kelimelerin yalan

hükmü fena adamları anlat bana

perdesinde sam yeli pencereleri

anlat ve sabret ey sevgili

sedyelerde koparılmış bebek gözleri

büyüyen çocukları anlat bana

dişlerinde gazoz açan oğlanları

saçları rüzgar dalga dalga kızları

çöplerinde şehrin kürtajdan artakalanları

kurtçuklar düşmeden öncesini

köpekler gelip götürdükten sonrasını

anlat ve sabret ey sevgili

memelerden süt çeken enikleri

yağmur suyu bacaları kırıldığında

kanalizasyonlardan akıp giden merhameti

anlat bana ince hesap gören klinikleri

Çukurova’da yetişen antibakteriyel pamuklara sızan ihaneti

yarı yollarda kanadım ey sevgili 

kanım ki merhemdi yaralarıma

buğusu kusulmuş sesimdi camların ardında

bitmemiş ölümler üstüne el Faaatiha

vurulmuş silahım berisinde ağların

bulvarlarda saklı yerim vadiyi rahim

dizelerime işerdi şeytanı izcim en nihayetinde

yalandı ihtiras dağların yalan müstakil sıradağların

el izim silahım buğusunda camların

yalandı rahman ve rahim yediemin tesellin

iyi ki sen vardın ve iyi ki gözlerin

yine de amin sevgili amin

ilyas orak', 'EL İZİM SİLAHIM BUĞUSUNDA CAMLARIN içine girdiği zarf kefenidir adresine ulaşmayan mektubun yalandı senin içinde öldüğüm  yalan seni kefen y...', ARRAY['Türk Edebiyatı','Şiir','İlyas Orak']::text[], 8.5, '{"poet":"İlyas Orak","poet_slug":"i-lyas-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/el-izim-silahim-bugusunda-camlarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Batağı', 'gul-batagi-murat-demir-ox16i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ömürlük birine tutuldum kaldım

Ayrılmam imkansız yansa da gönül

Bu aşkı kendime sır diye aldım

Saklarım diyemem sorsa da gönül

Her nere giderse ben izindeyken

Soluk alışımı fark eder gönül

Yürek sularının denizindeyken

Sevda deryasına hapseder gönül

Çırpındıkça battım gül batağına

Çıkamam içinden tutsa da gönül

Girmişim bir kere can yatağına

Terketmem imkansız atsa da gönül

Gerdanı doyumsuz baş koymak için

Gam yermiyim artık ölse de gönül

Hasret yok bağrına taş koymak için

Bundan sonra her gün gül sende gönül', 'Ömürlük birine tutuldum kaldım Ayrılmam imkansız yansa da gönül Bu aşkı kendime sır diye aldım Saklarım diyemem sorsa da gönül Her nere gide...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gul-batagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlış Bir İhbar Gibi', 'yanlis-bir-i-hbar-gibi-i-lyas-orak-841ar', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'serin güz akşamlarıydı 

Pera’ da yazılan zaman 

bizdik siyah körfezlerde 

çığlık çığlığa kurşun kalemlerimizle 

kumdan kaleleri fethe giden kağıt gemi 

ne güzeldi o günler o eski günler

bir bulutun ardına inen dolunay kadar 

inceymiş zaman

yanlış bir ihbar gibi her seferinde 

evlerimizden araklanan kuştüyleri

Hülya’ nın gülüşleri 

şifreli bir kahkahadır 

ellerimizde patlar 

mişli geçmiş ütopyalarda  yaşanamayanlar

en yaşlı çınarımızdı Muzaffer 

savaş parolasını veren dört yöne 

“algarina algarina”

Hülya sustu 

anladık başladı savaş

Muzaffer bağırdı gerilere ileri yoldaş

musallat bir aşkın bal-gamını söker gibi 

“algarina algarina”

yanlış bir ihbar gibi her seferinde 

şiirimiz büyür çoğalır ellerinde Yalvaç’ın

dik vuran şairlerdik kalemi kağıda

açılırdık öylece hainlerin sularına

Gülcemal bir an kayboldu

dişlerini dizer gibi alfabenin 

en son hangi harf ile kovdu Ş’ yi 

derken 

sanki provaya nefes nefese

ödünç alınmış bir mezar gibi

bağırdı gerilerden bir ses

“seni vuracaklar çocuk” 

“incecik duruşu” yla Mustafa

ne güzel çocuktu o güzel çocuk

Aziz Kemal, Tuncay, Ali Ulvi, 

Atila ve diğerleri 

yazdılar göllerde bir güzel sazdılar

kısık sesine halkımın davudi avazdılar

kim korkardı ölümden 

o yaşlı ölümden

düşüp o mavi güneşin peşinden

ne güzeldi o günler o eski günler', 'serin güz akşamlarıydı  Pera’ da yazılan zaman  bizdik siyah körfezlerde  çığlık çığlığa kurşun kalemlerimizle  kumdan kaleleri fethe giden ...', ARRAY['Türk Edebiyatı','Şiir','İlyas Orak']::text[], 8.5, '{"poet":"İlyas Orak","poet_slug":"i-lyas-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/yanlis-bir-ihbar-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslında Kimse Sana Uzak Değil', 'aslinda-kimse-sana-uzak-degil-mustafa-demirci-2-q1ws7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçimizi dökecek ne arkadaş var nede dost sanırdım 

Evet yanılmamışım şu iki telli internet ortamında 

Birileri döktürmüş kimse yok diye 

Meğersem feryat varmış yanıbaşımda 

Aslında yakınım ben sana Sen dünyada ben sanalda

Belki sevdadır bu tuşların dili kim bilir 

Belkide sadece samimi ve içten bir sevgi 

Belkide ayrılırız üzülerek yana yana 

Sen kendini yalnız hissediyorsun bu dünyada 

Sanki ben senden farklımıyım ki 

Aynı duyguları dökerken sana 

Belki cevap yazarsın bana 

Belki şiirlerimi okursun antolojide ıslak gözlerinle 

Ve aynı duyguyu yaşarız kim bilir mutlu bir evde 

Sen beni tanı ben seni 

Aynı sıcak ve bitmeyen nefeste 

Yazarsan dertleşiriz ne çıkar garip dünyada 

Belki dost oluruz belki bir arkadaş belki de......... 

Ne bilem yazamıyorum gerisini 

Kahretsin tuş takılıyor geride....', 'İçimizi dökecek ne arkadaş var nede dost sanırdım  Evet yanılmamışım şu iki telli internet ortamında  Birileri döktürmüş kimse yok diye  Meğ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Demirci 2']::text[], 8.5, '{"poet":"Mustafa Demirci 2","poet_slug":"mustafa-demirci-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aslinda-kimse-sana-uzak-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vicdanın Sızlamaz', 'vicdanin-sizlamaz-ahmet-aksoy-l0zmx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eller inandırır seni yalan yeminlere 

Eller inandırır seni yalan sözlere

Ben sana sadece doğruyu söyledim 

Nereden bilirdim hayallerinin

Bu kadar gerçeğe üstün geldiğini

Tek hatam sana olan sevgim

Değildi elbet 

Benimde hatalarım oldu

Sana verdiğim her acı 

İnan uykusuz gecelerimin nedeni oldu

Simdi eskiye dönmek mümkün olsa

İnandığımı değil istediğini söylerim

Yalanlarla seni mutlu ederim

O zaman daha çok severdin beni

Daha çok özlerdin

Şimdiki gibi diri diri gömmezdin

Ayrılığın ilk gününden beri

Hançerin yüreğimde

Ne zaman elimi götürsem kalbime

Butun vücudumu kaplar özlemin derin acısı

Ama nafile bilirim dönmez eski günler

Nafile acılar çekerim

Vicdanîn sızlamaz eski yarim', 'Eller inandırır seni yalan yeminlere  Eller inandırır seni yalan sözlere Ben sana sadece doğruyu söyledim  Nereden bilirdim hayallerinin Bu ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/vicdanin-sizlamaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstediğim', 'i-stedigim-ahmet-aksoy-9u42h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstediğim

Tekrar beni sevmen

Eskisi gibi daha fazla değil

Bir kere sevmiştin

Yine sevebilirsin

İstediğim tekrar seninle olmak

Yan yana el ele

Eskiden olduğundan farksız

Damarla kan gibi 

İstediğim sesini yine

Ve her zaman

Yanı başımda duymak

Seni tekrar aramak

Ama bu kez telefonu

Yüzüme kapatmadan.

Ayrıldıktan sonra her seferinde

Yaptığın gibi.

İstediğim yine sana dokunmak

Bana dokunduğun gibi

İstediğim yine sana güvenmek 

Eskisi gibi kaybetmekten korkmadan

Ve bana ikinci bir şans vermen

Acımadan.', 'İstediğim Tekrar beni sevmen Eskisi gibi daha fazla değil Bir kere sevmiştin Yine sevebilirsin İstediğim tekrar seninle olmak Yan yana el el...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/istedigim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürünüyor', 'surunuyor-ahmet-aksoy-r9056', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni terk etmenin

Dokuzuncu günüydü

Ona öyle bir ders vermiştim ki

Bir daha adını anmaya

Yüz bulamaz sanmıştım

Oysa o günden beri

Ne zaman ardıma baksam

Yaralı, eli yüzü kan içinde

Bir o kadar da çekingen

Gölge misali

Ardımdan geliyor

Ölmemiş ama her gün

Biraz daha tükeniyor

Seni hala sevmenin 

Verdiği acıyla

Gururum sürünüyor.', 'Beni terk etmenin Dokuzuncu günüydü Ona öyle bir ders vermiştim ki Bir daha adını anmaya Yüz bulamaz sanmıştım Oysa o günden beri Ne zaman a...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/surunuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefa Borcunu Ödeyen Şiir', 'vefa-borcunu-odeyen-siir-sair-ysl-k889o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-koşulu yok aşkın esirlik dışında ve sen bunu hakettin-

bir kız tanırdım

gülüşü kıvrımlarında

ben uyurken gelirdi 

uykusuz

nöbetten çıkagelirdi 

kıymalı yumurta yapardı

banardık ekmeğimizi

önce ruhumuz sevişirdi

sonra ekmeklerimiz

kimse beklemedi

otobüs duraklarında

senin bekleyişinle

ve kimse sevmedi 

senin gülüşünle beni

İzmir,24.01.1986- 5 haziran 03, YSL

Vefa Borcuna Ek Ödeme

şimdi

dipsiz kuyularına düştüğüm

hüzünlü bir tarihsin 

ama bil ki ben hep

anamın karnı gibi 

mesafesiz sevdim seni

beyoğlu,13.08.2003, YSL', '-koşulu yok aşkın esirlik dışında ve sen bunu hakettin- bir kız tanırdım gülüşü kıvrımlarında ben uyurken gelirdi  uykusuz nöbetten çıkageli...', ARRAY['Türk Edebiyatı','Şiir','Şair Ysl']::text[], 8.5, '{"poet":"Şair Ysl","poet_slug":"sair-ysl","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/vefa-borcunu-odeyen-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız Vefalı', 'vefasiz-vefali-ahmet-aksoy-2rob6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bıraktın gittin beni

Elimde senden kalan her şeyle

Götürseydin ya hatıraları da

Kendinle

Bu kadarcık isteği bile geri çevirdin

Yapamam deme boşuna

İnanmam

Sen ki beni bu kadar acıyla bırakabildin

Onları da götürebilirdin 

Eğer gerçekten isteseydin.', 'Bıraktın gittin beni Elimde senden kalan her şeyle Götürseydin ya hatıraları da Kendinle Bu kadarcık isteği bile geri çevirdin Yapamam deme ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/vefasiz-vefali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Feryat', 'sessiz-feryat-ahmet-aksoy-2nt2r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Canım yanıyor

Gözlerim her yüzde

Seni görüyor

Sanki her saç

Seninki ne es

Sanki her yüzde

Biraz sen varsın

İçtiğim suda 

Yediğim yemekte

Yürüdüğüm yol da

Benimlesin

Şu duvardaki resim

Ne kadar da sana benziyor

Allah’ım ne kadarda mesudum

Tek derdim şu gömlek

Bu kadar sıkmasa

Sana, gözlerimle olduğu gibi

Ellerimle de dokunsam.', 'Canım yanıyor Gözlerim her yüzde Seni görüyor Sanki her saç Seninki ne es Sanki her yüzde Biraz sen varsın İçtiğim suda  Yediğim yemekte Yür...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sessiz-feryat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoruldum', 'yoruldum-ahmet-aksoy-p8ja6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayrıldığımız günden beri

Her yüzde seni aramaktan

Trenle Bakırköy istasyonundan

Ne zaman geçsem

İstasyonda birini sana benzetip

Onun sen olmadığına kendimi

İnandırmaktan yoruldum

Yüreğim artık bunu kaldırmıyor

Kaç kez birine bakıp seni onda aradım

Bilemezsin

Belki içimde hala seni görmeye dair

Bir umut var 

Belki de dayanılmaz bir hasret

Adını sen koy.', 'Ayrıldığımız günden beri Her yüzde seni aramaktan Trenle Bakırköy istasyonundan Ne zaman geçsem İstasyonda birini sana benzetip Onun sen olm...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yoruldum-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimin Umurunda', 'kimin-umurunda-hakki-hakan-kaya-v3zjm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir hayal aleminde yaşıyoruz, 

Sanal bir gerçeklik bu aslında, 

Bindik bir alamete gidiyoruz, 

Neresi son durak, kimin umrunda.

Kısır bir döngü içindeyiz, 

Kiminin eli cebinde, kiminin karnı burnunda, 

Neyin hesabını yaparız da, ötesini bilmeyiz, 

Ak akçe kara pul kimin umrunda.

Rüyalarımızmı gerçek, gerçeklerimizmi rüya, 

Nereden bileceksinki uyanmadan daha, 

İpotekli hayatlarımız, yaşıyoruz güya, 

Ben peşin ödemişim, kimin umrunda.

İşin aslı, şudur son sözüm, 

İyi dinle küpe olsun kulağında, 

Dost arar, meşk-i muhabbet ister gönlüm, 

İş güç, para pul kimin umrunda.', 'Bir hayal aleminde yaşıyoruz,  Sanal bir gerçeklik bu aslında,  Bindik bir alamete gidiyoruz,  Neresi son durak, kimin umrunda. Kısır bir dö...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kimin-umurunda-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Dair Bir Başka Şiir', 'aska-dair-bir-baska-siir-ali-capan-7mh1h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşka dair şiirler yazmak için

Aşk yaşanmalı.

Hüznün değerini anlamak için

Gül alınıp/satılan pazarda

Dolaşılmalı.

Gül yaprağı/yar dudağı gibidir.

Her bahar öpüp/koklanmalı.

“Seni seviyorum” diye başlayan

Mektupların her satırına

Nakkaşlar gibi

Gül goncaları yapıştırılmalı.

Aşka dair şiirler yazmak için

Uçup giden sözcükler

Kanatlarından yakalanmalı.

Ferhat değilmiydi dağları delen

Aslı değilmiydi

Aşk ateşinden yanan

Yaşamak için aşkı

Aşık ölmeden önce ölmeli.', 'Aşka dair şiirler yazmak için Aşk yaşanmalı. Hüznün değerini anlamak için Gül alınıp/satılan pazarda Dolaşılmalı. Gül yaprağı/yar dudağı gib...', ARRAY['Türk Edebiyatı','Şiir','Ali Çapan']::text[], 8.5, '{"poet":"Ali Çapan","poet_slug":"ali-capan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/aska-dair-bir-baska-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahaflarda Satılıyor Anılar', 'sahaflarda-satiliyor-anilar-ali-capan-r9wsx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eskimiş anılar satılıyor sahaflarda

Sararmış kitapların arasında

Antep’te Buğday Arasasının orta yerinde

Bağırırdı yere vurarak bir deli

- Oysa  deli mi veli mi olduğu tartışılmıştır hep-

Elindeki zindiyan asasını

“-Saklanmayın lan” diyerek.

Eşarbına bir düğüm daha atan

Orta yaşlıbir kadın

Duyulur duyulmaz bir sesle

“ – Çocukları korkutuyorsun dayı”

Derdi, oysa korkan kendisiydi.', 'Eskimiş anılar satılıyor sahaflarda Sararmış kitapların arasında Antep’te Buğday Arasasının orta yerinde Bağırırdı yere vurarak bir deli - O...', ARRAY['Türk Edebiyatı','Şiir','Ali Çapan']::text[], 8.5, '{"poet":"Ali Çapan","poet_slug":"ali-capan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sahaflarda-satiliyor-anilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bezirganbaşı', 'bezirganbasi-ali-capan-8qyej', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hüzün satıyorum hüzün

Alan yokmu

Batmanı beşparaya

Usandım hep yakamda taşımaktan

İstersen al götür hepsini

Ya da bana bırak birazını

Bu kadar hüzün sana çok mu?', 'Hüzün satıyorum hüzün Alan yokmu Batmanı beşparaya Usandım hep yakamda taşımaktan İstersen al götür hepsini Ya da bana bırak birazını Bu kad...', ARRAY['Türk Edebiyatı','Şiir','Ali Çapan']::text[], 8.5, '{"poet":"Ali Çapan","poet_slug":"ali-capan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bezirganbasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Özgürlüğü', 'sevgi-ozgurlugu-sema-oztabak-5fahf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İtirafa giriş...

Yine aralanıyor perdesi yaşamın şafak vakti

Buram buram

Doruklara tırmanmak gibi

Ne bileyim... 

Sevgiliye kavuşmak gibi

Belki güzel bir öykü

Aydınlığın yalancı alemi gibi de olsa

Susmak çare mi dostum...

Bu perde hep açılıyor 

Işıtıyor zindan yürekleri

Denizin o çok bilmiş maviliğini bile

Hani gecenin serinliğinden daha bir canlanmış

Ağaçların arasından

Mavi ve duru gök görünür ya yer yer

Şafağın aydınlığı gecenin gölgelerine 

Yavaş yavaş yayılır

Cıvıldar ortalıkta adını bilmediğim kuşlar

                                               .... Adnan Öztabak.....Eylül 1992

Kabul ediş...

Bir gün başlamıştır ve

Hepsi habercidir sevgiye kavuşmak için

Yeşile kavuşamayan özlemler gibi

Susmak çare değil dostum...

Açılan perdeler arasından konuşmak

Aklanmak deniz köpüğü gibi

Sevgileri, hatırlanmışları zamanında söylemek

Bütün güzellikleri zamanıyla yaşamak

Kopan bir şeyleri son limede yakalamak

Sunmak altın tepsilerde sevgileri, sevgilere katmak

Kuşların adını öğrenmek, maviliklere ve

En ücra tepelere birlikte uçup sırdaş olmak

Güneşin yakıcı oklarıyla vurulmak mı

Yoksa koca bir ağacın gölgesine sığınmak mı

Daha haz verir insana...

Duaya kalkan papatyaları okşamak

Ağaç ve toprak gibi sarılmak sevgilerle.

Hiç bir şeyi yarım bırakmamak

Doğmak her gün yeniden umutla sevgilere.

                                                ..... Sema Öztabak.....Ekim 1992', 'İtirafa giriş... Yine aralanıyor perdesi yaşamın şafak vakti Buram buram Doruklara tırmanmak gibi Ne bileyim...  Sevgiliye kavuşmak gibi Bel...', ARRAY['Türk Edebiyatı','Şiir','Sema Öztabak']::text[], 8.5, '{"poet":"Sema Öztabak","poet_slug":"sema-oztabak","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sevgi-ozgurlugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annelerin En Yücesine', 'annelerin-en-yucesine-sema-oztabak-i1oed', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni biz sardık beyazlara

Gönderdik kuytu karanlıklara

Hakkını helal et canım Annem

Yerin belki karanlıkta 

Ama ruhun apaydınlıkta

Yerin cennet pür-nûr Annem

Seni biz sardık beyazlara; 

Yükledik sekiz çocuğun yükünü

On torunun yükünü

Yükledik en küçük çocuk:Kocanı

Kırkbeşyıl boyunca taşıdın

Yükledik konuyu komşuyu balya balya

İneği, tavuğu, çakalı, sansarı

Denizdeki sandalı, aleti-edevatı, 

Serenderde elmayı, patatesi, soğanı, 

Bahçedeki dikeni, çayları, otları

Yılmadın taşıdın.

Elimiz kesildi sana koştuk, merhem oldun

Gönlümüz yandı sana koştuk sarıldın avuttun

Anamız ağladı sana ağladık

Gizli gizli ağladın.

''Okuyun yavrularım'' dedin okuttun

Küçücük ikizlerini istikballeri için 

Yatılı okula verdin

Yıllar boyu yana yana özledin

Çocuklarım yokluk çekmesin, üzülmesin

Yorulmasın, dersini çalışsın dedin

Sen çalıştın, sen didindin.

Ağlayan bebeğinin ekmek parasını elinden aldılar

Kahvede harçlık yaptılar

''Büyüğümdür, saygılıyım'' dedin

Kan ağladın yıllar boyu 

Kimseye belli bile etmedin.

Çocuklarını büyüttün, okuttun ''adam'' ettin

Saygıyı, sevgiyi, görgüyü öğrettin

Hepsini iş-güç sahibi ettin, 

Kimini evlendirdin

Kimini gurbete yolladın hasret çektin

Özgürce ayakta durabilmelerini sağladın

Çocukların için ömrün yettiğince uğraştın

Analık görevini en yücesiyle yaptın.

''Evlatlarımdan razıyım, iyi olsunlar uzakta olsunlar'' dedin.

''Yoruldum yalnız başıma dinleneceğim, 

Artık al beni Allah''ım'' mı dedin? 

O kalp ağrısına bir hafta nasılda göğüs gerdin? 

Çocuklarını toplayıp etrafına acını mı dindirdin? 

Son gece helalleşip kocanla ''artık elveda'' mı dedin? 

Daha sana doyamadan bizi niye terkettin..? 

Dünyanın en büyük mutluluğuydun Annem

Son Haziran''da seninle birlikte uyumak

Sabahın ilk ışıklarıyla kalkarak  işe koyulmak

Sana yardım etmeye çabalamak, 

Sürekli yanında olmak, dokunmak

Seni sevmek, sarılmak, ipek yanağından öpmek

Asla hissedemeyeceğim bir hazdı Annem.

Tam rahat ettirebilecekken fani dünyada...

Seni biz mi sardık beyazlara

Allah mı aldı Annem? 

İstemezdik asla yatmanı karanlıkta

Allah da istemedi aldı  O nûrlu mekâna

Yerin cennet biliyorum

Huzur içinde yat Annem.

Ağustos 1992', 'Seni biz sardık beyazlara Gönderdik kuytu karanlıklara Hakkını helal et canım Annem Yerin belki karanlıkta  Ama ruhun apaydınlıkta Yerin cen...', ARRAY['Türk Edebiyatı','Şiir','Sema Öztabak']::text[], 8.5, '{"poet":"Sema Öztabak","poet_slug":"sema-oztabak","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/annelerin-en-yucesine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neşter Acısı', 'nester-acisi-sema-oztabak-a8xv2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neşterle kesilen kurşun kalemlerimi hatırlarım 

Çocukken...

Yürek sancılarıyla birlikte oynanan gençlik saklambaçlarını

